PROGRAM PRG_ReactorControl
VAR
    stScadaData : ST_SCADA_Data;
    nCurrentRole : INT; // 1=Operator, 2=Admin
    bWriteAccess : BOOL;
    fRequestedSP : LREAL;

    bIsPrimary : BOOL := TRUE;
    bPrimaryActive AT %I* : BOOL;
    bSecondaryActive AT %Q* : BOOL := TRUE;
    fbHeartbeatTimer : TON;
    bFailoverTriggered : BOOL;

    bEtherCATFault : BOOL;
    bSensorFault : BOOL;
    fbOuterPID : FB_BasicPID;
    fbInnerPID : FB_BasicPID;
    fCoreTempPV : LREAL;
    fJacketTempPV : LREAL;
    fCoreTempSP : LREAL := 80.0;
    fOuterOutput : LREAL;
    fInnerOutput : LREAL;
    fHeatingValveCmd : LREAL;
    fCoolingValveCmd : LREAL;
END_VAR

// IEC 62443 RBAC
bWriteAccess := (nCurrentRole >= 1);
IF bWriteAccess AND fRequestedSP > 0.0 THEN
    fCoreTempSP := fRequestedSP;
END_IF

// Redundancy Failover
fbHeartbeatTimer(IN := NOT bPrimaryActive, PT := T#500MS);
IF fbHeartbeatTimer.Q AND bIsPrimary THEN
    bFailoverTriggered := TRUE;
    bIsPrimary := FALSE;
END_IF

IF NOT bEtherCATFault AND NOT bSensorFault AND NOT bFailoverTriggered THEN
    fbOuterPID(fSetpointValue := fCoreTempSP, fActualValue := fCoreTempPV, fKp := 2.5, fTn := 60.0, fOut => fOuterOutput);
    fbInnerPID(fSetpointValue := fOuterOutput, fActualValue := fJacketTempPV, fKp := 5.0, fTn := 20.0, fOut => fInnerOutput);

    IF fInnerOutput > 50.0 THEN
        fHeatingValveCmd := (fInnerOutput - 50.0) * 2.0;
        fCoolingValveCmd := 0.0;
    ELSE
        fHeatingValveCmd := 0.0;
        fCoolingValveCmd := (50.0 - fInnerOutput) * 2.0;
    END_IF
ELSE
    fHeatingValveCmd := 0.0;
    fCoolingValveCmd := 100.0;
END_IF

// SCADA Mapping
stScadaData.fCoreTempPV := fCoreTempPV;
stScadaData.fCoreTempSP := fCoreTempSP;
stScadaData.bSystemReady := TRUE;
stScadaData.nActiveController := SEL(bIsPrimary, 2, 1);
