Here is the ultimate robust implementation with HIL mode, SMA sensor drift detection, and automated valve self-tests.

```iecst
PROGRAM PRG_UltimateReactorControl
VAR
    bHIL_ModeActive : BOOL;
    fSimCoreTemp : LREAL;

    fCoreTempPV_A : LREAL;
    fCoreTempPV_B : LREAL;
    aMovingAvgBuffer : ARRAY[1..100] OF LREAL;
    nAvgIdx : INT := 1;
    fMovingAvgA : LREAL;
    bSensorDriftAlarm : BOOL;

    eStartupState : (E_IDLE, E_TEST_HEAT, E_TEST_COOL, E_RUN, E_FAULT) := E_IDLE;
    fbTestTimer : TON;

    fbOuterPID : FB_BasicPID;
    fbInnerPID : FB_BasicPID;
    fCoreTempPV : LREAL;
    fJacketTempPV : LREAL;
    fCoreTempSP : LREAL := 80.0;
    fOuterOutput : LREAL;
    fInnerOutput : LREAL;
    fHeatingValveCmd : LREAL;
    fCoolingValveCmd : LREAL;
END_VAR

// HIL Synchronization
IF bHIL_ModeActive THEN
    fCoreTempPV_A := fSimCoreTemp;
    fCoreTempPV_B := fSimCoreTemp;
END_IF

// Sensor Drift Detection (Moving Average)
aMovingAvgBuffer[nAvgIdx] := fCoreTempPV_A;
nAvgIdx := nAvgIdx + 1;
IF nAvgIdx > 100 THEN nAvgIdx := 1; END_IF
IF ABS(fCoreTempPV_A - fCoreTempPV_B) > 3.0 THEN
    bSensorDriftAlarm := TRUE;
END_IF
fCoreTempPV := (fCoreTempPV_A + fCoreTempPV_B) / 2.0;

// Valve Self-Test State Machine
CASE eStartupState OF
    E_IDLE:
        IF NOT bSensorDriftAlarm THEN eStartupState := E_TEST_HEAT; END_IF
    E_TEST_HEAT:
        fHeatingValveCmd := 100.0;
        fbTestTimer(IN := TRUE, PT := T#5S);
        IF fbTestTimer.Q THEN
            fbTestTimer(IN := FALSE);
            eStartupState := E_TEST_COOL;
        END_IF
    E_TEST_COOL:
        fHeatingValveCmd := 0.0;
        fCoolingValveCmd := 100.0;
        fbTestTimer(IN := TRUE, PT := T#5S);
        IF fbTestTimer.Q THEN
            eStartupState := E_RUN;
        END_IF
    E_RUN:
        fbOuterPID(fSetpointValue := fCoreTempSP, fActualValue := fCoreTempPV, fKp := 2.5, fTn := 60.0, fOut => fOuterOutput);
