FUNCTION_BLOCK "ChemicalDosingSafety"
   VAR_INPUT 
      E_Stop : Bool;
      Tank_Level_OK : Bool;
      Flow_OK : Bool;
      Ack_Fault : Bool;
      Pump_Start_Req : Bool;
   END_VAR
   VAR_OUTPUT 
      Pump_Run : Bool;
      Fault_Active : Bool;
   END_VAR
   VAR 
      Fault_Latch : Bool;
   END_VAR
BEGIN
