        #Fault_Latch := TRUE;
    ELSIF #Ack_Fault AND #E_Stop AND #Tank_Level_OK AND #Flow_OK THEN
        #Fault_Latch := FALSE;
    END_IF;
    #Fault_Active := #Fault_Latch;
    #Pump_Run := #Pump_Start_Req AND NOT #Fault_Latch;
END_FUNCTION_BLOCK
