// Base Code: ISA-88 Batch Manager
FUNCTION_BLOCK "Batch_Manager"
VERSION : 1.0
VAR_INPUT
    Start_Batch : Bool;
    Recipe_ID : Int;
    LoadCell_Weight : Real;
END_VAR
VAR_OUTPUT
    Pump_Cmd : Bool;
    Mixer_Cmd : Bool;
    Batch_Complete : Bool;
    Report_Ready : Bool;
END_VAR
VAR
    Phase : Int := 0;
    Target_Weight : Real;
    Mix_Time : Time;
    Timer : TON;
END_VAR

BEGIN
    CASE Phase OF
        0: // IDLE
            IF Start_Batch THEN
                Phase := 1;
                Target_Weight := 100.0; // From recipe
                Mix_Time := T#10s;
            END_IF;
        1: // ADD INGREDIENT
            Pump_Cmd := TRUE;
            IF LoadCell_Weight >= Target_Weight THEN
                Pump_Cmd := FALSE;
                Phase := 2;
            END_IF;
        2: // MIX
            Mixer_Cmd := TRUE;
            Timer(IN:=TRUE, PT:=Mix_Time);
            IF Timer.Q THEN
                Mixer_Cmd := FALSE;
                Timer(IN:=FALSE);
                Phase := 3;
            END_IF;
        3: // COMPLETE
            Batch_Complete := TRUE;
            Report_Ready := TRUE;
            Phase := 0;
    END_CASE;
END_FUNCTION_BLOCK
