// --- 3-Element Drum Level Control ---
// Elements: 1: Drum Level, 2: Steam Flow (Feedforward), 3: Feedwater Flow
Drum_Level_PID.SP := Drum_Level_Setpoint;
Drum_Level_PID.PV := Drum_Level_Transmitter;
PID(Drum_Level_PID);

// Feedwater Setpoint = Level PID Output + (Steam Flow * Feedforward Gain)
Feedwater_Flow_Setpoint := Drum_Level_PID.OUT + (Steam_Flow_Transmitter * Steam_Flow_Gain);

Feedwater_PID.SP := Feedwater_Flow_Setpoint;
Feedwater_PID.PV := Feedwater_Flow_Transmitter;
PID(Feedwater_PID);
Feedwater_Valve_CV := Feedwater_PID.OUT;

// --- Burner Management System (BMS) Interlocks ---
BMS_Trip_Conditions := (Drum_Level_Transmitter <= Level_Low_Low_Limit) OR 
                       (Furnace_Pressure >= Press_High_High_Limit) OR 
                       (Fuel_Pressure <= Fuel_Low_Limit);

IF BMS_Trip_Conditions THEN
    BMS_State := 0; // TRIPPED
    Fuel_Safety_Valves := 0;
    Purge_Timer.TimerEnable := 0;
ELSIF BMS_State = 0 AND Reset_PB THEN
    BMS_State := 1; // STANDBY
END_IF;

// Purge Sequence
IF BMS_State = 1 AND Start_PB THEN
    BMS_State := 2; // PURGING
END_IF;

Purge_Timer(TimerEnable := (BMS_State = 2), PRE := 30000); // 30s purge
IF Purge_Timer.DN THEN
    BMS_State := 3; // IGNITION_READY
END_IF;

// --- Blowdown Sequencing ---
// Surface blowdown based on TDS (Total Dissolved Solids)
IF TDS_Transmitter > TDS_High_Setpoint THEN
    Surface_Blowdown_Valve := 1;
ELSIF TDS_Transmitter < TDS_Normal_Setpoint THEN
    Surface_Blowdown_Valve := 0;
END_IF;

// Bottom blowdown timer based
Bottom_Blowdown_TON(TimerEnable := NOT Bottom_Blowdown_TON.DN, PRE := 86400000); // 24 hours
Bottom_Blowdown_Duration(TimerEnable := Bottom_Blowdown_TON.DN AND NOT Bottom_Blowdown_Duration.DN, PRE := 15000); // 15s duration
Bottom_Blowdown_Valve := Bottom_Blowdown_Duration.TT;
