FUNCTION_BLOCK "Spindle_Controller"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      Setpoint_Speed : Real;
      Actual_Speed : Real;
      Vibration_Level : Real;
      ATC_Request : Bool;
      Tool_Unclamp_Sensor : Bool;
      Tool_Clamp_Sensor : Bool;
   END_VAR
   VAR_OUTPUT
      Drive_Speed_Ref : Real;
      Spindle_Ready : Bool;
      Tool_Wear_Warning : Bool;
      Spindle_Fault : Bool;
      ATC_State : Int;
   END_VAR
   VAR
      Kp : Real := 0.5;
      Ki : Real := 0.1;
      Speed_Error : Real;
      Integral_Sum : Real;
      Vibration_Limit : Real := 5.0; 
      State : Int;
   END_VAR

BEGIN
// Vibration Monitoring
IF #Vibration_Level > #Vibration_Limit THEN
    #Tool_Wear_Warning := TRUE;
ELSE
    #Tool_Wear_Warning := FALSE;
END_IF;

// ATC State Machine
CASE #State OF
    0: // Idle
        IF #ATC_Request AND #Actual_Speed < 5.0 THEN
            #State := 1; 
        END_IF;
    1: // Spindle Stopped, Initiate Unclamp
        #Spindle_Ready := FALSE;
        IF #Tool_Unclamp_Sensor THEN
            #State := 2;
        END_IF;
    2: // Wait for New Tool
        IF NOT #ATC_Request AND #Tool_Clamp_Sensor THEN
            #State := 0;
        END_IF;
END_CASE;
#ATC_State := #State;

// Closed-Loop Speed Regulation (PI Controller)
IF #Enable AND #State = 0 AND NOT #Spindle_Fault THEN
    #Speed_Error := #Setpoint_Speed - #Actual_Speed;
    #Integral_Sum := #Integral_Sum + (#Speed_Error * 0.01); 
    #Drive_Speed_Ref := (#Kp * #Speed_Error) + (#Ki * #Integral_Sum);
    #Spindle_Ready := TRUE;
ELSE
    #Drive_Speed_Ref := 0.0;
    #Integral_Sum := 0.0;
    #Spindle_Ready := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Spindle_Controller_M1"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      Setpoint_Speed : Real;
      Actual_Speed : Real;
      Vibration_Level : Real;
      ATC_Request : Bool;
      Tool_Unclamp_Sensor : Bool;
      Tool_Clamp_Sensor : Bool;
      Bearing_Temp : Real; // Celsius
   END_VAR
   VAR_OUTPUT
      Drive_Speed_Ref : Real;
      Spindle_Ready : Bool;
      Tool_Wear_Warning : Bool;
      Spindle_Fault : Bool;
      ATC_State : Int;
   END_VAR
   VAR
      Kp : Real := 0.5;
      Ki : Real := 0.1;
      Speed_Error : Real;
      Integral_Sum : Real;
      Vibration_Limit : Real := 5.0; 
      State : Int;
      Max_Speed : Real;
   END_VAR

BEGIN
// Thermal Compensation
IF #Bearing_Temp > 100.0 THEN
    #Spindle_Fault := TRUE;
    #Max_Speed := 0.0;
ELSIF #Bearing_Temp > 80.0 THEN
    #Max_Speed := 5000.0; // Derate speed due to heating
ELSE
    #Max_Speed := 12000.0; // Nominal max speed
END_IF;

// Vibration Monitoring
IF #Vibration_Level > #Vibration_Limit THEN
    #Tool_Wear_Warning := TRUE;
ELSE
    #Tool_Wear_Warning := FALSE;
END_IF;

// ATC State Machine
CASE #State OF
    0: // Idle
        IF #ATC_Request AND #Actual_Speed < 5.0 THEN
            #State := 1; 
        END_IF;
    1: // Spindle Stopped, Initiate Unclamp
        #Spindle_Ready := FALSE;
        IF #Tool_Unclamp_Sensor THEN
            #State := 2;
        END_IF;
    2: // Wait for New Tool
        IF NOT #ATC_Request AND #Tool_Clamp_Sensor THEN
            #State := 0;
        END_IF;
END_CASE;
#ATC_State := #State;

// Closed-Loop Speed Regulation (PI Controller)
IF #Enable AND #State = 0 AND NOT #Spindle_Fault THEN
    #Speed_Error := #Setpoint_Speed - #Actual_Speed;
    #Integral_Sum := #Integral_Sum + (#Speed_Error * 0.01); 
    #Drive_Speed_Ref := (#Kp * #Speed_Error) + (#Ki * #Integral_Sum);

    // Apply Thermal Limit
    IF #Drive_Speed_Ref > #Max_Speed THEN
        #Drive_Speed_Ref := #Max_Speed;
    END_IF;
    #Spindle_Ready := TRUE;
ELSE
    #Drive_Speed_Ref := 0.0;
    #Integral_Sum := 0.0;
    #Spindle_Ready := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Spindle_Controller_M2"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      Setpoint_Speed : Real;
