    Flow_Moving_Avg : REAL;
    Sum_Flow : REAL;
    Drift_Warning : BOOL;
    Drift_Tolerance : REAL := 5.0;
    i : INT;

    // Self-Test Routine
    Self_Test_Step : INT := 0;
    Self_Test_Complete : BOOL := FALSE;
    Test_TMR : TON;

    LACT_Pump : BOOL;
END_VAR

// Hardware-in-the-Loop (HIL) Bypass
IF HIL_Mode_Active THEN
    Actual_Flow := Sim_Coriolis_Flow;
    Actual_BSW := Sim_BSW_Percent;
ELSE
    Actual_Flow := Raw_Coriolis_Flow;
    Actual_BSW := Raw_BSW_Percent;
END_IF;

