FUNCTION_BLOCK "LeakDetectionBase"
VERSION : 0.1
   VAR_INPUT
      InletFlow : Real;   // kg/s
      OutletFlow : Real;  // kg/s
      InletPressure : Real; // bar
      OutletPressure : Real; // bar
      DeltaTime : Real;   // s
      ThresholdMass : Real; // kg
      ThresholdPressureDrop : Real; // bar/s
   END_VAR
   VAR_OUTPUT
      LeakDetected : Bool;
      IsolationValveCommand : Bool;
   END_VAR
   VAR
      AccumulatedMassIn : Real;
      AccumulatedMassOut : Real;
      MassImbalance : Real;
      PrevInletPressure : Real;
      PressureRateOfChange : Real;
   END_VAR

BEGIN
   // Mass Balance Calculation
   #AccumulatedMassIn := #AccumulatedMassIn + (#InletFlow * #DeltaTime);
   #AccumulatedMassOut := #AccumulatedMassOut + (#OutletFlow * #DeltaTime);
   #MassImbalance := #AccumulatedMassIn - #AccumulatedMassOut;

   // Pressure Wave Transient Detection
   #PressureRateOfChange := (#PrevInletPressure - #InletPressure) / #DeltaTime;
   #PrevInletPressure := #InletPressure;

   // Leak Condition Logic
   IF (#MassImbalance > #ThresholdMass) OR (#PressureRateOfChange > #ThresholdPressureDrop) THEN
       #LeakDetected := TRUE;
       #IsolationValveCommand := TRUE; // Automatic Valve Isolation
   ELSE
       #LeakDetected := FALSE;
       #IsolationValveCommand := FALSE;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "LeakDetectionDepth"
VERSION : 0.1
   VAR_INPUT
      InletFlow : Real;   
      OutletFlow : Real;  
      InletPressure : Real; 
      OutletPressure : Real; 
      AvgTemperature : Real; // C, from distributed temperature sensing
      DeltaTime : Real;   
      ThresholdMass : Real; 
      ThresholdPressureDrop : Real; 
      ThermalCoeff : Real; // Thermal expansion coefficient
   END_VAR
   VAR_OUTPUT
      LeakDetected : Bool;
      IsolationValveCommand : Bool;
   END_VAR
   VAR
      AccumulatedMassIn : Real;
      AccumulatedMassOut : Real;
      MassImbalance : Real;
      CompensatedImbalance : Real;
      PrevInletPressure : Real;
      PressureRateOfChange : Real;
   END_VAR

BEGIN
   // Mass Balance Calculation
   #AccumulatedMassIn := #AccumulatedMassIn + (#InletFlow * #DeltaTime);
   #AccumulatedMassOut := #AccumulatedMassOut + (#OutletFlow * #DeltaTime);
   #MassImbalance := #AccumulatedMassIn - #AccumulatedMassOut;

   // Thermal Expansion Compensation
   // Adjusting mass imbalance based on temperature variations
   #CompensatedImbalance := #MassImbalance - (#MassImbalance * #AvgTemperature * #ThermalCoeff);

   // Pressure Wave Transient Detection
   #PressureRateOfChange := (#PrevInletPressure - #InletPressure) / #DeltaTime;
   #PrevInletPressure := #InletPressure;

   // Leak Condition Logic
   IF (#CompensatedImbalance > #ThresholdMass) OR (#PressureRateOfChange > #ThresholdPressureDrop) THEN
       #LeakDetected := TRUE;
       #IsolationValveCommand := TRUE; 
   ELSE
       #LeakDetected := FALSE;
       #IsolationValveCommand := FALSE;
   END_IF;
END_FUNCTION_BLOCK

