        IF bPressClosed THEN
            iState := 15;
        END_IF;

    15: // Nitrogen Shaping
        PID_Nitrogen.PV := rNitrogenPressPV;
        PID_Nitrogen.SP := 250.0; // 250 PSI for shaping
        rNitrogenValveCV := PID_Nitrogen.CV;

        tonShapingTime(IN:=TRUE, PT:=diShapingTimeSP);
