    AuthLevel := 3;
ELSE
    AuthLevel := 0;
END_IF;

// HIL or Real Sensor Selection
IF bHIL_Mode THEN
    rSteamTempPV_Active := rTwin_TempPV;
ELSE
    // Drift Detection & Failover
    IF ABS(rSteamTempPV_Pri - rSteamTempPV_Sec) > rDriftThreshold THEN
        bSensorDriftDetected := TRUE;
        EIP_FaultCode := 16#03; // Drift warning/fault
    END_IF;

    IF rSteamTempPV_Pri > 250.0 OR rSteamTempPV_Pri < 0.0 THEN
        bPriSensorFail := TRUE;
        rSteamTempPV_Active := rSteamTempPV_Sec;
    ELSE
        bPriSensorFail := FALSE;
        rSteamTempPV_Active := rSteamTempPV_Pri;
    END_IF;
