    rSteamValveCV := 0.0;
    rClampValveCV := 0.0;
    rNitrogenValveCV := 0.0;
END_IF;

CASE iState OF
    0:
        IF bStartCycle AND NOT bEStop AND (AuthLevel >= 3) AND (Scada_Recipe_CureTime > 0) THEN
            iState := 5; // Go to self-test
        END_IF;

    5: // Self-Test Routine
        rClampValveCV := 10.0; // slight pressure to check response
        tonSelfTest(IN:=TRUE, PT:=2000);
        IF tonSelfTest.Q THEN
            tonSelfTest(IN:=FALSE);
            IF rClampPressPV > 5.0 THEN
                rClampValveCV := 0.0;
                iState := 10;
            ELSE
                iState := 99; // Actuator failed test
                EIP_FaultCode := 16#04;
            END_IF;
        END_IF;

    10:
        rClampValveCV := 50.0;
        IF bPressClosed THEN iState := 15; END_IF;

    15:
        PID_Nitrogen.PV := rNitrogenPressPV;
        PID_Nitrogen.SP := 250.0; 
