        tonShapingTime(IN:=TRUE, PT:=diShapingTimeSP);
        IF tonShapingTime.Q THEN
            tonShapingTime(IN:=FALSE);
            iState := 20;
        END_IF;

    20:
        PID_Steam.PV := rSteamTempPV_Active;
        PID_Steam.SP := Scada_Recipe_TempSP;
        rSteamValveCV := PID_Steam.CV;

        PID_Clamp.PV := rClampPressPV;
        PID_Clamp.SP := 2500.0;
        rClampValveCV := PID_Clamp.CV;

