FUNCTION_BLOCK FB_MachiningCenter
VAR_INPUT
    Start_Machining : BOOL;
    Stop_Machining : BOOL;
    Fluid_Flow_Sensor : REAL; // L/min
    Drill_Torque : REAL; // Nm
    Conveyor_Running_Feedback : BOOL;
END_VAR
VAR_OUTPUT
    Fluid_Pump_Cmd : BOOL;
    Conveyor_Cmd : BOOL;
    Spindle_Cmd : BOOL;
    Alarm_Fluid_Low : BOOL;
    Alarm_Tool_Break : BOOL;
    Machine_Ready : BOOL;
END_VAR
VAR
    Conveyor_Timer : TON;
END_VAR

// Fluid control
IF Start_Machining AND NOT Stop_Machining THEN
    Fluid_Pump_Cmd := TRUE;
ELSE
    Fluid_Pump_Cmd := FALSE;
END_IF;

IF Fluid_Pump_Cmd AND (Fluid_Flow_Sensor < 10.0) THEN
    Alarm_Fluid_Low := TRUE;
ELSE
    Alarm_Fluid_Low := FALSE;
END_IF;

// Chip conveyor sequencing
Conveyor_Timer(IN := Start_Machining, PT := T#5s);
IF Conveyor_Timer.Q THEN
    Conveyor_Cmd := TRUE;
ELSE
    Conveyor_Cmd := FALSE;
END_IF;

// Drill torque monitoring
IF Drill_Torque > 50.0 THEN // Threshold
    Alarm_Tool_Break := TRUE;
    Spindle_Cmd := FALSE;
ELSIF Start_Machining AND NOT Stop_Machining AND Conveyor_Running_Feedback AND NOT Alarm_Fluid_Low THEN
    Spindle_Cmd := TRUE;
    Alarm_Tool_Break := FALSE;
END_IF;

Machine_Ready := NOT Alarm_Fluid_Low AND NOT Alarm_Tool_Break AND NOT Stop_Machining;
END_FUNCTION_BLOCK
