FUNCTION_BLOCK FB_MachiningCenter_M3
VAR_INPUT
    Start_Machining : BOOL;
    Stop_Machining : BOOL;
    Fluid_Flow_Sensor : REAL;
    Drill_Torque : REAL;
    Tool_Change_Req : BOOL;
    Requested_Tool : INT;
    ATC_Arm_Pos : INT;
    PN_Comm_Error : BOOL;
    User_Role : INT; // 1=Operator, 2=Maintenance, 3=Admin (IEC 62443)
    Auth_Token_Valid : BOOL;
END_VAR
VAR_OUTPUT
    Fluid_Pump_Main_Cmd : BOOL;
    Fluid_Pump_Aux_Cmd : BOOL;
    Conveyor_Cmd : BOOL;
    Spindle_Cmd : BOOL;
    Global_Fault : BOOL;
    Diagnostic_Code : INT;
    SCADA_Data_Packet : STRUCT
        Machine_State : INT;
        Active_Tool : INT;
        Flow_Rate : REAL;
        Torque_Value : REAL;
    END_STRUCT;
END_VAR
VAR
    Current_Tool : INT := 1;
    Pump_Failover_Active : BOOL := FALSE;
END_VAR

// IEC 62443 Access Control (Add Reasoning)
IF NOT Auth_Token_Valid OR User_Role < 1 THEN
    Global_Fault := TRUE;
    Diagnostic_Code := 99;
    Spindle_Cmd := FALSE;
    RETURN;
END_IF;

// Failover Logic for Fluid Pump
IF Start_Machining AND NOT Stop_Machining THEN
    IF NOT Pump_Failover_Active AND Fluid_Flow_Sensor < 10.0 THEN
        Pump_Failover_Active := TRUE;
    END_IF;

    IF NOT Pump_Failover_Active THEN
        Fluid_Pump_Main_Cmd := TRUE;
        Fluid_Pump_Aux_Cmd := FALSE;
    ELSE
        Fluid_Pump_Main_Cmd := FALSE;
        Fluid_Pump_Aux_Cmd := TRUE;
        IF Fluid_Flow_Sensor < 10.0 THEN
            Global_Fault := TRUE;
            Diagnostic_Code := 2;
        END_IF;
    END_IF;
ELSE
    Fluid_Pump_Main_Cmd := FALSE;
    Fluid_Pump_Aux_Cmd := FALSE;
    Pump_Failover_Active := FALSE;
END_IF;

// SCADA Integration
SCADA_Data_Packet.Machine_State := Diagnostic_Code;
SCADA_Data_Packet.Active_Tool := Current_Tool;
SCADA_Data_Packet.Flow_Rate := Fluid_Flow_Sensor;
SCADA_Data_Packet.Torque_Value := Drill_Torque;

// Torque monitoring
IF Drill_Torque > 50.0 THEN
    Global_Fault := TRUE;
    Diagnostic_Code := 3;
    Spindle_Cmd := FALSE;
END_IF;
END_FUNCTION_BLOCK
