            bProductMissing := TRUE;
            fbCamOut(Slave := KnifeAxis, Execute := TRUE);
            State := 30;
        END_IF

    30: // Wait for product
        IF bProductSensor THEN
            bProductMissing := FALSE;
            fbCamOut(Slave:=KnifeAxis, Execute:=FALSE);
            State := 10;
        END_IF
