VAR
    CIP_State : Int := 0;
    PID_Ctrl : PID_Compact;
    Setpoint_Temp : Real;
    Comm_Send : TSEND_C;
    Comm_Recv : TRCV_C;
    Send_Data : ARRAY[0..9] OF Byte;
    Recv_Data : ARRAY[0..9] OF Byte;
    Diag_Buffer : ARRAY[0..19] OF String[50];
    Diag_Index : Int := 0;
END_VAR

BEGIN
    IF Stop_CIP THEN 
        CIP_State := 0; 
        Diag_Buffer[Diag_Index MOD 20] := 'Emergency Stop Activated';
        Diag_Index := Diag_Index + 1;
    END_IF;

    CASE CIP_State OF
        0: 
            IF Start_CIP THEN 
                CIP_State := 1; 
                Diag_Buffer[Diag_Index MOD 20] := 'Starting Pre-Rinse';
                Diag_Index := Diag_Index + 1;
            END_IF;
        1: 
            Setpoint_Temp := 25.0;
            IF Conductivity_Raw < 0.5 THEN CIP_State := 2; END_IF;
        2:
            Setpoint_Temp := 80.0;
            IF Conductivity_Raw > 50.0 THEN CIP_State := 3; END_IF;
        3:
            Setpoint_Temp := 60.0;
            IF Conductivity_Raw > 30.0 THEN CIP_State := 4; END_IF;
        4:
            Setpoint_Temp := 90.0;
            CIP_State := 5;
        5:
            IF NOT Start_CIP THEN CIP_State := 0; END_IF;
    END_CASE;

    PID_Ctrl(Setpoint := Setpoint_Temp, Input := Temp_Actual);

    Send_Data[0] := INT_TO_BYTE(CIP_State);
    Comm_Send(REQ := TRUE, CONT := TRUE, DATA := Send_Data, LEN := 10);
