END_FOR;

IF bHIL_Mode THEN
    FOR i := 1 TO 8 DO fTempPV[i] := fHIL_SimulatedPV[i]; END_FOR;
END_IF;

IF bSelfTestRunning THEN
    tSelfTestTimer(IN:=TRUE, PT:=T#5S);
    IF tSelfTestTimer.Q THEN
        bSelfTestRunning := FALSE;
        tSelfTestTimer(IN:=FALSE);
    ELSE
        FOR i := 1 TO 8 DO fHeaterCV[i] := 10.0; END_FOR;
        fBlowerSpeedReq := 10.0;
    END_IF;
    RETURN;
END_IF;

IF NOT bHeartbeatRemote THEN bIsPrimaryPLC := TRUE; END_IF;

IF bEcatError OR nEcatState <> 8 THEN
    bAlarmActive := TRUE;
    sAlarmMessage := 'EtherCAT Error';
END_IF;

IF bIsPrimaryPLC AND bAccessGranted AND NOT bAlarmActive THEN
    fThicknessOffset := (fGlassThickness - 5.0) * 10.0;
    FOR i := 1 TO 8 DO
        fTempSP[i] := fBaseSP + fThicknessOffset;
        fbHeaters[i](
            fSetpoint := fTempSP[i],
            fActualValue := fTempPV[i],
            bEnable := TRUE,
            fOutput => fHeaterCV[i]
        );
    END_FOR;
    IF bQuenchRun THEN fBlowerSpeedReq := 60.0 * (fGlassThickness / 5.0); ELSE fBlowerSpeedReq := 0.0; END_IF;
    fScadaMonitorTemp := fTempPV[1];
ELSE
    FOR i := 1 TO 8 DO fHeaterCV[i] := 0.0; END_FOR;
    fBlowerSpeedReq := 0.0;
END_IF;
