FUNCTION_BLOCK "ContinuousCastingControl_Reasoning"
VERSION : 0.1
VAR_INPUT
    MoldLevelRadioactive : Real;
    MoldLevelEddyCurrent : Real;
    CastingSpeedSetpoint : Real;
    StartCasting : Bool;
    StopCasting : Bool;
    UserRoleID : Int; // IEC 62443 RBAC: 1=Operator, 2=Admin, 3=Maintenance
    PartnerHeartbeat : Bool; // Hot-standby heartbeat
END_VAR
VAR_OUTPUT
    StopperPosition : Real;
    OscillatorFreq : Real;
    SprayZone1Flow : Real;
    SprayZone2Flow : Real;
    SprayZone3Flow : Real;
    MyHeartbeat : Bool;
    IsPrimaryController : Bool;
    ScadaData : "SCADA_OPC_UA_DATA";
END_VAR
VAR
    MoldLevelSetpoint : Real := 80.0;
    ActualMoldLevel : Real;
    PID_Error : Real;
    PID_Integral : Real;
    Kp : Real := 1.5;
    Ki : Real := 0.05;
    OscillatorGain : Real := 10.0;
    HeartbeatTimer : TON;
    ToggleBit : Bool;
END_VAR

BEGIN
    // Hot-Standby Failover Logic
    ToggleBit := NOT ToggleBit;
    MyHeartbeat := ToggleBit;

    HeartbeatTimer(IN := NOT PartnerHeartbeat, PT := t#500ms);
    IF HeartbeatTimer.Q THEN
        IsPrimaryController := TRUE; // Assume control if partner dies
    END_IF;

    // CyberSecurity - Role Based Access Control
    IF UserRoleID < 1 THEN
        // Unauthorized
        RETURN;
    END_IF;

    ActualMoldLevel := (MoldLevelRadioactive + MoldLevelEddyCurrent) / 2.0;

    IF IsPrimaryController THEN
        IF StartCasting THEN
            PID_Error := MoldLevelSetpoint - ActualMoldLevel;
            PID_Integral := PID_Integral + (PID_Error * Ki);
            StopperPosition := (PID_Error * Kp) + PID_Integral;

            IF StopperPosition > 100.0 THEN StopperPosition := 100.0; END_IF;
            IF StopperPosition < 0.0 THEN StopperPosition := 0.0; END_IF;

            OscillatorFreq := CastingSpeedSetpoint * OscillatorGain;
            SprayZone1Flow := CastingSpeedSetpoint * 50.0;
            SprayZone2Flow := CastingSpeedSetpoint * 40.0;
            SprayZone3Flow := CastingSpeedSetpoint * 30.0;
            ScadaData.SystemState := 2; // Running
        ELSE
            StopperPosition := 0.0;
            OscillatorFreq := 0.0;
            SprayZone1Flow := 0.0;
            SprayZone2Flow := 0.0;
            SprayZone3Flow := 0.0;
            ScadaData.SystemState := 1; // Standby
        END_IF;
    END_IF;

    IF StopCasting THEN
        StopperPosition := 0.0;
        ScadaData.SystemState := 0; // Stopped
    END_IF;

    // SCADA Updates
    ScadaData.MoldLevel := ActualMoldLevel;
    ScadaData.CastingSpeed := CastingSpeedSetpoint;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "ContinuousCastingControl_Adversarial"
VERSION : 0.1
VAR_INPUT
    MoldLevelRadioactive : Real;
    MoldLevelEddyCurrent : Real;
    CastingSpeedSetpoint : Real;
    StartCasting : Bool;
    StopCasting : Bool;
    StopperPositionFbk : Real;
    HIL_SyncClock : DInt; // HIL Digital Twin Clock
END_VAR
VAR_OUTPUT
    StopperPositionCmd : Real;
    OscillatorFreq : Real;
    SprayZone1Flow : Real;
    SprayZone2Flow : Real;
    SprayZone3Flow : Real;
    SensorDriftAlarm : Bool;
    SystemReady : Bool;
    HIL_AckClock : DInt;
END_VAR
VAR
    MoldLevelSetpoint : Real := 80.0;
    ActualMoldLevel : Real;
    PID_Error : Real;
    PID_Integral : Real;
    Kp : Real := 1.5;
    Ki : Real := 0.05;
    OscillatorGain : Real := 10.0;
    DriftTolerance : Real := 5.0; // % deviation
    SelfTestState : Int := 0; // 0=Init, 1=Test Actuators, 2=Wait Fbk, 3=Done
    SelfTestTimer : TON;
END_VAR

BEGIN
    // HIL Digital Twin Sync
    HIL_AckClock := HIL_SyncClock;

    // Sensor Drift Detection
    IF ABS(MoldLevelRadioactive - MoldLevelEddyCurrent) > DriftTolerance THEN
        SensorDriftAlarm := TRUE;
        ActualMoldLevel := MoldLevelEddyCurrent; // Fallback to Eddy Current
    ELSE
        SensorDriftAlarm := FALSE;
        ActualMoldLevel := (MoldLevelRadioactive + MoldLevelEddyCurrent) / 2.0;
    END_IF;

    // Pre-cast Self-Test Routine
    IF SelfTestState = 0 AND StartCasting THEN
        SelfTestState := 1;
    END_IF;

    CASE SelfTestState OF
        1: // Force Actuators
            StopperPositionCmd := 10.0; // Small safe movement
            SelfTestTimer(IN:=TRUE, PT:=t#2s);
            IF SelfTestTimer.Q THEN
                SelfTestState := 2;
                SelfTestTimer(IN:=FALSE, PT:=t#2s);
            END_IF;
        2: // Verify Feedback
            IF ABS(StopperPositionFbk - 10.0) < 2.0 THEN
                SelfTestState := 3;
                SystemReady := TRUE;
            ELSE
                SelfTestState := 0; // Failed test
                SystemReady := FALSE;
            END_IF;
            StopperPositionCmd := 0.0;
    END_CASE;

    // Normal Control
    IF SystemReady AND StartCasting AND SelfTestState = 3 THEN
        PID_Error := MoldLevelSetpoint - ActualMoldLevel;
        PID_Integral := PID_Integral + (PID_Error * Ki);
        StopperPositionCmd := (PID_Error * Kp) + PID_Integral;

        IF StopperPositionCmd > 100.0 THEN StopperPositionCmd := 100.0; END_IF;
        IF StopperPositionCmd < 0.0 THEN StopperPositionCmd := 0.0; END_IF;

        OscillatorFreq := CastingSpeedSetpoint * OscillatorGain;
        SprayZone1Flow := CastingSpeedSetpoint * 50.0;
        SprayZone2Flow := CastingSpeedSetpoint * 40.0;
        SprayZone3Flow := CastingSpeedSetpoint * 30.0;
    ELSIF SelfTestState = 3 THEN
        StopperPositionCmd := 0.0;
        OscillatorFreq := 0.0;
        SprayZone1Flow := 0.0;
        SprayZone2Flow := 0.0;
        SprayZone3Flow := 0.0;
    END_IF;

    IF StopCasting THEN
        SystemReady := FALSE;
        SelfTestState := 0;
        StopperPositionCmd := 0.0;
    END_IF;
END_FUNCTION_BLOCK

PROGRAM WinderControl
VAR
    bEnable : BOOL;
    fLineSpeed : LREAL; // m/min
    fDancerPos : LREAL; // 0-100%
    fWinderSpeedAct : LREAL;
    fTensionSP : LREAL;
    fDancerPosSP : LREAL := 50.0;
    fNipPressureSP : LREAL;
    fWinderSpeedRef : LREAL;
    fWinderTorqueRef : LREAL;
    fNipPressureValve : LREAL;
    fbDancerPID : FB_BasicPID;
    fDiameterCalc : LREAL;
    fTorqueTaper : LREAL;
    fCoreDiameter : LREAL := 150.0;
END_VAR

fbDancerPID(
    fSetpoint := fDancerPosSP,
    fActualValue := fDancerPos,
    bEnable := bEnable,
    fKp := 2.5, fKi := 0.5, fKd := 0.1,
    fOutput => fWinderSpeedRef
);

IF bEnable AND fWinderSpeedAct > 1.0 THEN
    fDiameterCalc := (fLineSpeed / (fWinderSpeedAct * 3.14159)) * 1000.0;
ELSE
    fDiameterCalc := fCoreDiameter;
END_IF

fTorqueTaper := fTensionSP * (fCoreDiameter / MAX(fDiameterCalc, fCoreDiameter));
fWinderTorqueRef := fTorqueTaper;
fNipPressureValve := fNipPressureSP * (1.0 + (fDiameterCalc - fCoreDiameter)/1000.0);
END_PROGRAM

PROGRAM WinderControl_Depth
VAR
    bEnable : BOOL;
    bWebBreak : BOOL;
    bEStop : BOOL;
    fLineSpeed, fDancerPos, fWinderSpeedAct : LREAL;
    fTensionSP, fNipPressureSP : LREAL;
    fWinderSpeedRef, fWinderTorqueRef, fNipPressureValve : LREAL;
    fbDancerPID : FB_BasicPID;
    fDiameterCalc : LREAL;
    fCoreDiameter : LREAL := 150.0;
    iSpliceState : INT;
    bSpliceReq, bSpliceComplete : BOOL;
    fWebTensionSensor : LREAL;
END_VAR

IF fWebTensionSensor < 5.0 AND fLineSpeed > 50.0 THEN
    bWebBreak := TRUE;
    bEStop := TRUE;
END_IF

IF bEStop THEN
    fWinderSpeedRef := 0.0;
    fWinderTorqueRef := 0.0;
    bEnable := FALSE;
    RETURN;
END_IF

CASE iSpliceState OF
    0:
        IF bSpliceReq THEN iSpliceState := 1; END_IF
    1:
        IF ABS(fWinderSpeedAct - fLineSpeed) < 2.0 THEN iSpliceState := 2; END_IF
    2:
        bSpliceComplete := TRUE;
        iSpliceState := 0;
END_CASE

fbDancerPID(fSetpoint := 50.0, fActualValue := fDancerPos, bEnable := bEnable, fKp := 2.5, fKi := 0.5, fOutput => fWinderSpeedRef);
fDiameterCalc := SEL(fWinderSpeedAct > 1.0, fCoreDiameter, (fLineSpeed / (fWinderSpeedAct * 3.14159)) * 1000.0);
fWinderTorqueRef := fTensionSP * (fCoreDiameter / MAX(fDiameterCalc, fCoreDiameter));
fNipPressureValve := fNipPressureSP * (1.0 + (fDiameterCalc - fCoreDiameter)/1000.0);
END_PROGRAM

