FUNCTION_BLOCK "SMT_Profinet_Diag"
VAR_INPUT
    PN_Recv : ARRAY[0..15] OF Byte; // Profinet inputs
END_VAR
VAR_OUTPUT
    PN_Send : ARRAY[0..15] OF Byte; // Profinet outputs
