PROGRAM MAIN
VAR
    bStart : BOOL;
    bStop : BOOL;
    fSealPressure : REAL;
    bCamPass : BOOL;
    bEncoderPulse : BOOL;

    sOpID : STRING;
    sOpPass : STRING;
    bLoginOk : BOOL;
    bAuditLogReq : BOOL;
    sAuditEvent : STRING;

    aShiftReg : ARRAY[1..100] OF BOOL;
    i : INT;

    bHeater : BOOL;
    bSealActuator : BOOL;
    bReject : BOOL;

    eState : (INIT, IDLE, RUNNING, FAULT);
    fbRTrig : R_TRIG;
END_VAR

IF sOpID = 'Admin' AND sOpPass = '1234' THEN
    bLoginOk := TRUE;
END_IF;

CASE eState OF
    INIT:
        IF bLoginOk THEN eState := IDLE; END_IF;
    IDLE:
        IF bStart THEN eState := RUNNING; END_IF;
    RUNNING:
        bHeater := TRUE;
        bSealActuator := TRUE;
        IF fSealPressure < 1000.0 OR fSealPressure > 1500.0 THEN
            sAuditEvent := 'Pressure Fault'; bAuditLogReq := TRUE; eState := FAULT;
        END_IF;
        fbRTrig(CLK:=bEncoderPulse);
        IF fbRTrig.Q THEN
            FOR i:=100 TO 2 BY -1 DO aShiftReg[i] := aShiftReg[i-1]; END_FOR;
            aShiftReg[1] := bCamPass;
            IF NOT aShiftReg[50] THEN bReject := TRUE; sAuditEvent := 'Reject'; bAuditLogReq := TRUE;
            ELSE bReject := FALSE; END_IF;
        END_IF;
        IF bStop THEN eState := IDLE; END_IF;
    FAULT:
        bHeater := FALSE; bSealActuator := FALSE; bReject := FALSE;
        IF bStop THEN eState := IDLE; END_IF;
END_CASE;
