    #vibration_timer(IN := (#vibration_level > #vibration_limit), PT := T#2S);
    #alarm_vibration := #vibration_timer.Q;

    // Penstock Pressure & Water Hammer Protection (Rate of Change)
    #sample_timer(IN := NOT #sample_timer.Q, PT := T#100MS);
    IF #sample_timer.Q THEN
        #roc_pressure := (#penstock_pressure - #prev_pressure) / 0.1; // bar/s
        #prev_pressure := #penstock_pressure;
