    #alarm_water_hammer := (#penstock_pressure > #penstock_pressure_limit) OR (#roc_pressure > 5.0);

    // Grid Synchronization
    #sync_ok := (ABS(#grid_voltage - #gen_voltage) < 5.0) AND (ABS(#grid_freq - #gen_freq) < 0.1);

