IF DGA_Alarm OR Oil_Level_Low OR Buchholz_Relay_Trip THEN
    Critical_Fault := 1;
ELSE
    Critical_Fault := 0;
END_IF;

// Map Data to EIP Assembly
EIP_Out.Voltage := Voltage_Level;
EIP_Out.Oil_Temp := Top_Oil_Temp;
EIP_Out.Fault_Code := Critical_Fault;

// Predictive Thermal Modeling
Hot_Spot_Temp := Top_Oil_Temp + (Load_Current / Rated_Current) ** 1.6 * Hot_Spot_Gradient;

// DGA Monitoring
DGA_Alarm := (DGA_Hydrogen > 100.0) OR (DGA_Methane > 50.0);

// LTC Control
LTC_Raise := (Voltage_Level < Voltage_Setpoint - Deadband) AND (LTC_Step < 16) AND NOT Critical_Fault;
LTC_Lower := (Voltage_Level > Voltage_Setpoint + Deadband) AND (LTC_Step > -16) AND NOT Critical_Fault;

// Cooling Control
Fan_Bank_1 := (Hot_Spot_Temp > 85.0) OR Critical_Fault;
Fan_Bank_2 := (Hot_Spot_Temp > 105.0);

// IEC 62443 Role-Based Access
IF SCADA_Write_Request THEN
    IF User_Role = ROLE_ADMIN AND Session_Token_Valid THEN
        Voltage_Setpoint := SCADA_Setpoint;
    ELSE
        Security_Violation_Event := 1;
    END_IF;
END_IF;

// Redundancy & Failover
IF Primary_Controller_Fault THEN
    Active_Controller := 0; // Switch to Secondary
    Sync_Data_To_Standby := 1;
END_IF;

// SCADA Heartbeat
SCADA_Watchdog(IN:=NOT SCADA_Heartbeat_Toggle, PT:=T#2s);
IF SCADA_Watchdog.Q THEN
    SCADA_Comm_Loss := 1;
    Active_Mode := MODE_LOCAL; // Fail-safe to local
END_IF;

// Fault Diagnostics & EIP
Comm_Fault := NOT EIP_Connection_Status;
Critical_Fault := DGA_Alarm OR Oil_Level_Low OR Buchholz_Relay_Trip;

// Predictive Thermal Modeling
Hot_Spot_Temp := Top_Oil_Temp + (Load_Current / Rated_Current) ** 1.6 * Hot_Spot_Gradient;
DGA_Alarm := (DGA_Hydrogen > 100.0) OR (DGA_Methane > 50.0);

// LTC Control (Blocked during SCADA loss unless local mode enabled)
IF Active_Mode = MODE_LOCAL OR NOT SCADA_Comm_Loss THEN
    LTC_Raise := (Voltage_Level < Voltage_Setpoint - Deadband) AND (LTC_Step < 16) AND NOT Critical_Fault;
    LTC_Lower := (Voltage_Level > Voltage_Setpoint + Deadband) AND (LTC_Step > -16) AND NOT Critical_Fault;
END_IF;

// Cooling Control
Fan_Bank_1 := (Hot_Spot_Temp > 85.0);
Fan_Bank_2 := (Hot_Spot_Temp > 105.0);

// Startup Self-Test Routine
IF NOT Init_Complete THEN
    Self_Test_Timer(IN:=1, PT:=T#3s);
    Fan_Bank_1 := 1; // Test fan contactors
    Fan_Bank_2 := 1;
    IF Self_Test_Timer.Q THEN
        Init_Complete := 1;
        Fan_Bank_1 := 0;
        Fan_Bank_2 := 0;
    END_IF;
    RETURN;
END_IF;

// Sensor Drift Detection (Redundant Sensors)
Temp_Deviation := ABS(Top_Oil_Temp_A - Top_Oil_Temp_B);
IF Temp_Deviation > 5.0 THEN
    Sensor_Drift_Alarm := 1;
    Top_Oil_Temp := (Top_Oil_Temp_A + Top_Oil_Temp_B) / 2.0; // Average mode
ELSE
    Sensor_Drift_Alarm := 0;
    Top_Oil_Temp := Top_Oil_Temp_A;
END_IF;

// HIL Digital Twin Sync
IF HIL_Simulation_Mode THEN
    Virtual_Hot_Spot := Digital_Twin_Calc(Load_Current, Ambient_Temp, Top_Oil_Temp);
    HIL_Sync_Error := ABS(Hot_Spot_Temp - Virtual_Hot_Spot);
    IF HIL_Sync_Error > 10.0 THEN Twin_Divergence_Alarm := 1; END_IF;
END_IF;

// Cybersecurity & SCADA
IF SCADA_Write_Request AND User_Role = ROLE_ADMIN AND Session_Token_Valid THEN
    Voltage_Setpoint := SCADA_Setpoint;
END_IF;
SCADA_Watchdog(IN:=NOT SCADA_Heartbeat_Toggle, PT:=T#2s);
SCADA_Comm_Loss := SCADA_Watchdog.Q;

// Failover
IF Primary_Controller_Fault THEN Active_Controller := 0; END_IF;

// Thermal Modeling
Hot_Spot_Temp := Top_Oil_Temp + (Load_Current / Rated_Current) ** 1.6 * Hot_Spot_Gradient;
DGA_Alarm := (DGA_Hydrogen > 100.0) OR (DGA_Methane > 50.0);

// LTC & Cooling Control
IF Active_Mode = MODE_LOCAL OR NOT SCADA_Comm_Loss THEN
    LTC_Raise := (Voltage_Level < Voltage_Setpoint - Deadband) AND (LTC_Step < 16) AND NOT (DGA_Alarm OR Sensor_Drift_Alarm);
    LTC_Lower := (Voltage_Level > Voltage_Setpoint + Deadband) AND (LTC_Step > -16) AND NOT (DGA_Alarm OR Sensor_Drift_Alarm);
END_IF;

Fan_Bank_1 := (Hot_Spot_Temp > 85.0) OR Sensor_Drift_Alarm;
Fan_Bank_2 := (Hot_Spot_Temp > 105.0) OR Sensor_Drift_Alarm;

