    fExhaust_Temp_PV : REAL;
    bSystem_Running : BOOL;
    fTarget_Valve_Pos : REAL;
    fCycle_Time : REAL := 0.01;
END_VAR

IF bStart_Cmd THEN bSystem_Running := TRUE; ELSIF bStop_Cmd THEN bSystem_Running := FALSE; END_IF

IF bSystem_Running THEN
    IF fCombustion_Temp_PV < (fCombustion_Temp_SP - 10.0) THEN fTarget_Valve_Pos := fTarget_Valve_Pos + (fMax_Valve_Ramp_Rate * fCycle_Time);
    ELSIF fCombustion_Temp_PV > (fCombustion_Temp_SP + 10.0) THEN fTarget_Valve_Pos := fTarget_Valve_Pos - (fMax_Valve_Ramp_Rate * fCycle_Time); END_IF

    IF fTarget_Valve_Pos > 100.0 THEN fTarget_Valve_Pos := 100.0;
    ELSIF fTarget_Valve_Pos < 15.0 THEN fTarget_Valve_Pos := 15.0; END_IF

    IF (fTarget_Valve_Pos - fFuel_Valve_Pos) > (fMax_Valve_Ramp_Rate * fCycle_Time) THEN fFuel_Valve_Pos := fFuel_Valve_Pos + (fMax_Valve_Ramp_Rate * fCycle_Time);
    ELSIF (fFuel_Valve_Pos - fTarget_Valve_Pos) > (fMax_Valve_Ramp_Rate * fCycle_Time) THEN fFuel_Valve_Pos := fFuel_Valve_Pos - (fMax_Valve_Ramp_Rate * fCycle_Time);
    ELSE fFuel_Valve_Pos := fTarget_Valve_Pos; END_IF

    IF fExhaust_Temp_PV > 650.0 THEN fHRSG_Bypass_Damper_Pos := 100.0;
    ELSIF fExhaust_Temp_PV > 600.0 THEN fHRSG_Bypass_Damper_Pos := (fExhaust_Temp_PV - 600.0) * 2.0;
    ELSE fHRSG_Bypass_Damper_Pos := 0.0; END_IF
ELSE
    fFuel_Valve_Pos := 0.0;
    fTarget_Valve_Pos := 0.0;
    fHRSG_Bypass_Damper_Pos := 100.0;
END_IF
