PROGRAM PRG_GTCC_Depth
VAR
    bStart_Cmd, bStop_Cmd : BOOL;
    bSystem_Running : BOOL;
    fCombustion_Temp_PV, fExhaust_Temp_PV : REAL;
    fCombustion_Temp_SP : REAL := 1200.0;
    fFuel_Valve_Pos, fTarget_Valve_Pos : REAL;
    fMax_Valve_Ramp_Rate : REAL := 5.0;
    fHRSG_Bypass_Damper_Pos : REAL;
    fCycle_Time : REAL := 0.01;

    fSteam_Pressure_PV, fSteam_Pressure_SP : REAL := 150.0;
    fTurbine_Speed_PV : REAL;
    fGrid_Freq_PV, fGrid_Voltage_PV : REAL;
    fGen_Voltage_PV, fGen_Phase_Angle, fGrid_Phase_Angle : REAL;

    bSync_Enable, bBreaker_Close_Cmd : BOOL;
    fMain_Steam_Valve : REAL;
    nSync_State : INT := 0;
END_VAR

IF bStart_Cmd THEN bSystem_Running := TRUE; ELSIF bStop_Cmd THEN bSystem_Running := FALSE; END_IF

IF bSystem_Running THEN
    IF fCombustion_Temp_PV < (fCombustion_Temp_SP - 10.0) THEN fTarget_Valve_Pos := fTarget_Valve_Pos + (fMax_Valve_Ramp_Rate * fCycle_Time);
    ELSIF fCombustion_Temp_PV > (fCombustion_Temp_SP + 10.0) THEN fTarget_Valve_Pos := fTarget_Valve_Pos - (fMax_Valve_Ramp_Rate * fCycle_Time); END_IF
    fTarget_Valve_Pos := LIMIT(15.0, fTarget_Valve_Pos, 100.0);
    fFuel_Valve_Pos := fTarget_Valve_Pos;

    IF fExhaust_Temp_PV > 650.0 THEN fHRSG_Bypass_Damper_Pos := 100.0;
    ELSIF fExhaust_Temp_PV > 600.0 THEN fHRSG_Bypass_Damper_Pos := (fExhaust_Temp_PV - 600.0) * 2.0;
    ELSE fHRSG_Bypass_Damper_Pos := 0.0; END_IF

    IF fSteam_Pressure_PV >= fSteam_Pressure_SP THEN bSync_Enable := TRUE; END_IF

    IF bSync_Enable THEN
        CASE nSync_State OF
            0: fMain_Steam_Valve := 10.0; IF fTurbine_Speed_PV > 2800.0 THEN nSync_State := 1; END_IF
            1: IF fTurbine_Speed_PV < 3000.0 THEN fMain_Steam_Valve := fMain_Steam_Valve + 0.1; ELSIF fTurbine_Speed_PV > 3000.5 THEN fMain_Steam_Valve := fMain_Steam_Valve - 0.1; END_IF
               IF ABS(fTurbine_Speed_PV - 3000.0) < 1.0 AND ABS(fGrid_Freq_PV - 50.0) < 0.1 THEN nSync_State := 2; END_IF
            2: IF ABS(fGen_Voltage_PV - fGrid_Voltage_PV) < 0.5 THEN nSync_State := 3; END_IF
            3: IF ABS(fGen_Phase_Angle - fGrid_Phase_Angle) < 5.0 THEN bBreaker_Close_Cmd := TRUE; nSync_State := 4; END_IF
            4: fMain_Steam_Valve := LIMIT(10.0, fMain_Steam_Valve + 0.05, 100.0);
        END_CASE
    ELSE
        nSync_State := 0; bBreaker_Close_Cmd := FALSE; fMain_Steam_Valve := 0.0;
    END_IF
ELSE
    fFuel_Valve_Pos := 0.0; fHRSG_Bypass_Damper_Pos := 100.0; bBreaker_Close_Cmd := FALSE; fMain_Steam_Valve := 0.0; nSync_State := 0; bSync_Enable := FALSE;
END_IF
