    fTurbine_Speed_PV : REAL;
    fMain_Steam_Valve : REAL;
END_VAR

IF nEcat_State <> 8 THEN bFault_Active := TRUE; nFault_Code := 1;
ELSIF fCombustion_Temp_PV > 1400.0 THEN bFault_Active := TRUE; nFault_Code := 2;
ELSIF ABS(fFuel_Valve_Cmd - fFuel_Valve_Fbk) > 5.0 THEN bFault_Active := TRUE; nFault_Code := 3;
ELSIF fCombustion_Temp_PV < -50.0 OR fCombustion_Temp_PV > 2000.0 THEN bFault_Active := TRUE; nFault_Code := 4;
ELSE bFault_Active := FALSE; nFault_Code := 0; END_IF

IF bFault_Active OR bStop_Cmd THEN bSystem_Running := FALSE;
ELSIF bStart_Cmd AND NOT bFault_Active THEN bSystem_Running := TRUE; END_IF

IF bSystem_Running THEN
    IF fCombustion_Temp_PV < (fCombustion_Temp_SP - 10.0) THEN fFuel_Valve_Cmd := LIMIT(15.0, fFuel_Valve_Cmd + (fMax_Valve_Ramp_Rate * fCycle_Time), 100.0);
    ELSIF fCombustion_Temp_PV > (fCombustion_Temp_SP + 10.0) THEN fFuel_Valve_Cmd := LIMIT(15.0, fFuel_Valve_Cmd - (fMax_Valve_Ramp_Rate * fCycle_Time), 100.0); END_IF

    IF fExhaust_Temp_PV > 650.0 THEN fHRSG_Bypass_Damper_Cmd := 100.0;
    ELSE fHRSG_Bypass_Damper_Cmd := 0.0; END_IF

    IF fTurbine_Speed_PV < 3000.0 THEN fMain_Steam_Valve := fMain_Steam_Valve + 0.1; END_IF
ELSE
    fFuel_Valve_Cmd := 0.0;
    fHRSG_Bypass_Damper_Cmd := 100.0;
    fMain_Steam_Valve := 0.0;
END_IF
