    IF bStart_Cmd THEN
        IF fCombustion_Temp_PV < fCombustion_Temp_SP THEN fFuel_Valve_Cmd := LIMIT(15.0, fFuel_Valve_Cmd + 0.05, 100.0); END_IF
    ELSE fFuel_Valve_Cmd := 0.0; END_IF

    IF fTurbine_Speed_PV >= 3000.0 THEN bBreaker_Close_Cmd := TRUE; END_IF
ELSE
    nSystem_Status := 2;
