PROGRAM PRG_GTCC_Adversarial
VAR
    {attribute 'OPC.UA.DA' := '1'} bStart_Cmd : BOOL;
    nUser_Privilege : INT;
    bIs_Primary_CPU : BOOL := TRUE;

    fTemp_Sensor_A, fTemp_Sensor_B, fTemp_Sensor_C : REAL;
    fCombustion_Temp_PV : REAL;
    fFuel_Valve_Cmd, fFuel_Valve_Fbk : REAL;

    bHIL_Mode_Active : BOOL;
    fDigitalTwin_Temp, fHIL_Deviation : REAL;

    bSensor_Drift_Fault : BOOL;
    fMax_Drift_Allowed : REAL := 15.0;

    bSelf_Test_Active, bSelf_Test_Passed : BOOL;
    nTest_Step : INT;
    fbTest_Timer : TON;

    nState : INT := 0;
END_VAR

IF ABS(fTemp_Sensor_A - fTemp_Sensor_B) > fMax_Drift_Allowed AND ABS(fTemp_Sensor_A - fTemp_Sensor_C) > fMax_Drift_Allowed THEN
    fCombustion_Temp_PV := (fTemp_Sensor_B + fTemp_Sensor_C) / 2.0; bSensor_Drift_Fault := TRUE;
ELSIF ABS(fTemp_Sensor_B - fTemp_Sensor_C) > fMax_Drift_Allowed THEN
    fCombustion_Temp_PV := fTemp_Sensor_A; bSensor_Drift_Fault := TRUE;
ELSE
    fCombustion_Temp_PV := (fTemp_Sensor_A + fTemp_Sensor_B + fTemp_Sensor_C) / 3.0; bSensor_Drift_Fault := FALSE;
END_IF

IF bHIL_Mode_Active THEN
    fDigitalTwin_Temp := fDigitalTwin_Temp + ((fFuel_Valve_Cmd * 12.0) - fDigitalTwin_Temp) * 0.01;
    fHIL_Deviation := ABS(fCombustion_Temp_PV - fDigitalTwin_Temp);
    IF fHIL_Deviation > 300.0 AND nState = 30 THEN nState := 99; END_IF
END_IF

CASE nState OF
    0: IF bIs_Primary_CPU AND nUser_Privilege >= 1 THEN nState := 10; END_IF
    10: 
        bSelf_Test_Active := TRUE;
        CASE nTest_Step OF
            0: fFuel_Valve_Cmd := 50.0; fbTest_Timer(IN:=TRUE, PT:=T#5S); IF fbTest_Timer.Q THEN fbTest_Timer(IN:=FALSE); nTest_Step := 1; END_IF
            1: IF ABS(fFuel_Valve_Cmd - fFuel_Valve_Fbk) < 2.0 THEN fFuel_Valve_Cmd := 0.0; nTest_Step := 2; ELSE nState := 99; END_IF
            2: IF fFuel_Valve_Fbk < 2.0 THEN bSelf_Test_Passed := TRUE; bSelf_Test_Active := FALSE; nState := 20; END_IF
        END_CASE
    20: IF bStart_Cmd AND bSelf_Test_Passed THEN nState := 30; END_IF
    30: IF NOT bStart_Cmd THEN nState := 20; END_IF; fFuel_Valve_Cmd := LIMIT(15.0, fCombustion_Temp_PV * 0.05, 100.0);
    99: fFuel_Valve_Cmd := 0.0; IF NOT bStart_Cmd THEN nState := 0; END_IF
END_CASE
