FUNCTION_BLOCK "BaggageHandling"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    Conv1_PE : Bool;
    Conv2_PE : Bool;
    Merge_PE : Bool;
END_VAR
VAR_OUTPUT
    Conv1_Run : Bool;
    Conv2_Run : Bool;
    Diverter_Actuate : Bool;
END_VAR
VAR
    SystemRunning : Bool;
    MergeTimer : TON;
    DivertTimer : TON;
    CascadeStop : Bool;
END_VAR

BEGIN
    IF Start AND NOT Stop THEN
        SystemRunning := TRUE;
    ELSIF Stop THEN
        SystemRunning := FALSE;
    END_IF;

    // Cascade Stop Logic
    MergeTimer(IN := Merge_PE, PT := T#2S);
    CascadeStop := MergeTimer.Q;

    // Diverter Timing
    DivertTimer(IN := Conv1_PE, PT := T#500MS);
    Diverter_Actuate := DivertTimer.Q;

    Conv1_Run := SystemRunning AND NOT CascadeStop;
    Conv2_Run := SystemRunning AND NOT CascadeStop;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "BaggageHandling_M1"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    Conv1_PE : Bool;
    Merge_PE : Bool;
    RFID_Data : String;
    Bag_Weight : Real;
END_VAR
VAR_OUTPUT
    Conv1_Run : Bool;
    Diverter_Actuate : Bool;
    ExceptionLine_Run : Bool;
END_VAR
VAR
    SystemRunning : Bool;
    MergeTimer : TON;
    CascadeStop : Bool;
    IsOverweight : Bool;
END_VAR

BEGIN
    IF Start AND NOT Stop THEN
        SystemRunning := TRUE;
    ELSIF Stop THEN
        SystemRunning := FALSE;
    END_IF;

    MergeTimer(IN := Merge_PE, PT := T#2S);
    CascadeStop := MergeTimer.Q;

    // RFID & Weighing
    IsOverweight := Bag_Weight > 23.5;

    IF IsOverweight AND Conv1_PE THEN
        Diverter_Actuate := TRUE;
        ExceptionLine_Run := TRUE;
    ELSE
        Diverter_Actuate := FALSE;
        ExceptionLine_Run := FALSE;
    END_IF;

    Conv1_Run := SystemRunning AND NOT CascadeStop;
END_FUNCTION_BLOCK

TYPE "Profinet_Drive_Status"
    STRUCT
        Ready : Bool;
        Fault : Bool;
        ErrorCode : Int;
    END_STRUCT
