        SystemState : Int;
        Heartbeat : Bool;
        UserRole : Int; // 0=None, 1=Operator, 2=Admin
    END_STRUCT
END_TYPE

FUNCTION_BLOCK "BaggageHandling_M3"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    Conv1_PE : Bool;
    Bag_Weight : Real;
    DriveStatus : "Profinet_Drive_Status";
    PLC_IsPrimary : Bool;
    PLC_Partner_Fail : Bool;
END_VAR
VAR_IN_OUT
    SCADA : "SCADA_Interface";
END_VAR
VAR_OUTPUT
    Conv1_Run : Bool;
    Diverter_Actuate : Bool;
END_VAR
VAR
    SystemRunning : Bool;
    ActiveControl : Bool;
END_VAR

BEGIN
    // Failover
    ActiveControl := PLC_IsPrimary OR PLC_Partner_Fail;

    // Security
    IF SCADA.UserRole < 1 THEN
        SystemRunning := FALSE;
    ELSE
        IF ActiveControl AND Start AND NOT Stop THEN
            SystemRunning := TRUE;
        ELSIF Stop THEN
            SystemRunning := FALSE;
        END_IF;
    END_IF;

    IF SystemRunning THEN
        SCADA.SystemState := 1;
    ELSE
        SCADA.SystemState := 0;
    END_IF;

    SCADA.Heartbeat := NOT SCADA.Heartbeat; // Toggle Heartbeat

    IF (Bag_Weight > 23.5) AND Conv1_PE AND ActiveControl THEN
        Diverter_Actuate := TRUE;
    ELSE
        Diverter_Actuate := FALSE;
    END_IF;

    Conv1_Run := SystemRunning AND DriveStatus.Ready AND ActiveControl;
END_FUNCTION_BLOCK

