    STRUCT
        SystemState : Int;
        Heartbeat : Bool;
        UserRole : Int;
    END_STRUCT
END_TYPE

FUNCTION_BLOCK "BaggageHandling_M4"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    Conv1_PE_Raw : Real; // Analog signal for PE
    Bag_Weight : Real;
    PLC_IsPrimary : Bool;
    HIL_Sync_Flag : Bool; // Digital Twin Sync
END_VAR
VAR_IN_OUT
    SCADA : "SCADA_Interface";
END_VAR
VAR_OUTPUT
    Conv1_Run : Bool;
    Diverter_Actuate : Bool;
    SelfTest_Active : Bool;
    Sensor_Drift_Alarm : Bool;
END_VAR
VAR
    SystemRunning : Bool;
    PE_Drift_Avg : Real;
    Conv1_PE_Logical : Bool;
    State : Int; // 0=Off, 1=SelfTest, 2=Run
    TestTimer : TON;
END_VAR

BEGIN
    // HIL Sync
    IF HIL_Sync_Flag THEN
        SCADA.SystemState := 99; // Sim Mode
    END_IF;

    // Sensor Drift Detection (Moving Avg mock)
    PE_Drift_Avg := (PE_Drift_Avg * 0.9) + (Conv1_PE_Raw * 0.1);
    IF PE_Drift_Avg > 8.0 THEN
        Sensor_Drift_Alarm := TRUE;
    END_IF;
    Conv1_PE_Logical := Conv1_PE_Raw > 5.0;

    // Self Test Routine
    IF State = 0 AND Start AND SCADA.UserRole >= 1 THEN
        State := 1;
        SelfTest_Active := TRUE;
    END_IF;

    TestTimer(IN := (State = 1), PT := T#5S);
    IF TestTimer.Q THEN
        State := 2;
        SelfTest_Active := FALSE;
        SystemRunning := TRUE;
    END_IF;

    IF Stop THEN
        State := 0;
        SystemRunning := FALSE;
    END_IF;

    IF State = 2 AND (Bag_Weight > 23.5) AND Conv1_PE_Logical THEN
        Diverter_Actuate := TRUE;
    ELSE
        Diverter_Actuate := FALSE;
    END_IF;

    Conv1_Run := SystemRunning;
END_FUNCTION_BLOCK

