// Allen-Bradley Structured Text (IEC 61131-3)
// Overhead Gantry Crane Control

PROGRAM MainCraneControl
VAR
    // Inputs
    HoistLoadCell : REAL; // Current load in kg
    JoyX : REAL; // Joystick X-axis (Bridge)
    JoyY : REAL; // Joystick Y-axis (Trolley)
    JoyZ : REAL; // Joystick Z-axis (Hoist)

    // Outputs
    CmdBridgeSpeed : REAL;
    CmdTrolleySpeed : REAL;
    CmdHoistSpeed : REAL;
    BrakeResistorEnable : BOOL;

    // Parameters
    MaxLoad : REAL := 5000.0; // 5 Tons
    SwayKp : REAL := 0.5;
    SwayKd : REAL := 0.1;
    SwayKi : REAL := 0.05;

    // State
    OverloadFault : BOOL := FALSE;
    CableLength : REAL := 10.0; // Simulated cable length for anti-sway
    SwayAngleX : REAL := 0.0; // Simulated/Measured sway angle X
    SwayAngleY : REAL := 0.0; // Simulated/Measured sway angle Y
    SwayVelocityX : REAL := 0.0;
    SwayVelocityY : REAL := 0.0;

    // DC Bus / Braking
    DCBusVoltage : REAL;
    MaxDCBus : REAL := 750.0;
END_VAR

// 1. Hoist Load Cell Overload Protection
IF HoistLoadCell > MaxLoad THEN
    OverloadFault := TRUE;
    CmdHoistSpeed := 0.0;
ELSE
    OverloadFault := FALSE;
    CmdHoistSpeed := JoyZ;
END_IF;

// 2. Multi-axis Anti-Sway Algorithm (Simplified PD control based on sway feedback)
// In a real system, SwayAngle would be estimated via a vision system or IMU
IF NOT OverloadFault THEN
    // Bridge (X-axis) Anti-sway compensation
    CmdBridgeSpeed := JoyX - (SwayKp * SwayAngleX + SwayKd * SwayVelocityX);

    // Trolley (Y-axis) Anti-sway compensation
    CmdTrolleySpeed := JoyY - (SwayKp * SwayAngleY + SwayKd * SwayVelocityY);
ELSE
    CmdBridgeSpeed := 0.0;
    CmdTrolleySpeed := 0.0;
END_IF;

// 3. Regenerative Braking Resistors Control
IF DCBusVoltage > MaxDCBus THEN
    BrakeResistorEnable := TRUE;
ELSE
    BrakeResistorEnable := FALSE;
END_IF;

END_PROGRAM

PROGRAM MainCraneControl_M1
VAR
    // Inputs
    HoistLoadCell : REAL; // Current load in kg
    JoyX, JoyY, JoyZ : REAL; 
    DCBusVoltage : REAL;
    CableTensionFeedback : REAL; // Tension in N

    // Outputs
    CmdBridgeSpeed, CmdTrolleySpeed, CmdHoistSpeed : REAL;
    BrakeResistorEnable : BOOL;

    // Parameters
    MaxLoad : REAL := 5000.0; 
    MaxDCBus : REAL := 750.0;
    MinSlackTension : REAL := 50.0; // Minimum tension before considering slack

    // PID Parameters for Tension
    Kp_Tens : REAL := 1.2;
    Ki_Tens : REAL := 0.5;
    Kd_Tens : REAL := 0.1;
    TensionSetpoint : REAL := 1000.0;
    TensionError : REAL;
    TensionErrorPrev : REAL;
    TensionIntegral : REAL;
    TensionDerivative : REAL;

    // State
    OverloadFault : BOOL := FALSE;
    SlackCableFault : BOOL := FALSE;
    SwayAngleX, SwayAngleY : REAL;
    SwayVelocityX, SwayVelocityY : REAL;
    SwayKp : REAL := 0.5; SwayKd : REAL := 0.1;
END_VAR

// 1. Overload & Slack Cable Protection
IF HoistLoadCell > MaxLoad THEN
    OverloadFault := TRUE;
ELSE
    OverloadFault := FALSE;
END_IF;

IF CableTensionFeedback < MinSlackTension AND JoyZ < 0.0 THEN // Hoisting down
    SlackCableFault := TRUE;
ELSE
    SlackCableFault := FALSE;
END_IF;

// 2. Hoist PID Tension Control
TensionError := TensionSetpoint - CableTensionFeedback;
TensionIntegral := TensionIntegral + TensionError;
TensionDerivative := TensionError - TensionErrorPrev;
TensionErrorPrev := TensionError;

IF OverloadFault OR SlackCableFault THEN
    CmdHoistSpeed := 0.0;
ELSE
    // Combine Manual JoyZ with Tension PID override if needed
    CmdHoistSpeed := JoyZ + (Kp_Tens * TensionError + Ki_Tens * TensionIntegral + Kd_Tens * TensionDerivative);
END_IF;

// 3. Anti-Sway
IF NOT OverloadFault AND NOT SlackCableFault THEN
    CmdBridgeSpeed := JoyX - (SwayKp * SwayAngleX + SwayKd * SwayVelocityX);
    CmdTrolleySpeed := JoyY - (SwayKp * SwayAngleY + SwayKd * SwayVelocityY);
ELSE
    CmdBridgeSpeed := 0.0;
    CmdTrolleySpeed := 0.0;
END_IF;

// 4. Regenerative Braking
BrakeResistorEnable := (DCBusVoltage > MaxDCBus);
END_PROGRAM

PROGRAM MainCraneControl_M2
VAR
    // Crane IO
    HoistLoadCell : REAL;
    JoyX, JoyY, JoyZ : REAL; 
    DCBusVoltage, CableTensionFeedback : REAL;

    CmdBridgeSpeed, CmdTrolleySpeed, CmdHoistSpeed : REAL;
    BrakeResistorEnable : BOOL;

    // State & PID
    OverloadFault, SlackCableFault, DriveCommFault : BOOL;
    TensionError, TensionIntegral, TensionDerivative, TensionErrorPrev : REAL;
    SwayAngleX, SwayAngleY, SwayVelocityX, SwayVelocityY : REAL;

    // Diagnostics & Comm
    FaultWord : DINT; // Bit 0: Overload, Bit 1: Slack, Bit 2: DriveComm, Bit 3: HighSway
    TelemetryData : ARRAY[0..9] OF REAL;
    EIP_Message : MESSAGE;
    TriggerTelemetry : BOOL;
    HeartbeatTimer : TON;
END_VAR

// Diagnostics packing
FaultWord.0 := HoistLoadCell > 5000.0; // Overload
FaultWord.1 := (CableTensionFeedback < 50.0) AND (JoyZ < 0.0); // Slack
FaultWord.2 := DriveCommFault;
FaultWord.3 := (ABS(SwayAngleX) > 15.0) OR (ABS(SwayAngleY) > 15.0);

// Fault Handling
IF FaultWord <> 0 THEN
    CmdHoistSpeed := 0.0; CmdBridgeSpeed := 0.0; CmdTrolleySpeed := 0.0;
ELSE
    // PID Tension
    TensionError := 1000.0 - CableTensionFeedback;
    TensionIntegral := TensionIntegral + TensionError;
    TensionDerivative := TensionError - TensionErrorPrev;
    TensionErrorPrev := TensionError;
    CmdHoistSpeed := JoyZ + (1.2 * TensionError + 0.5 * TensionIntegral + 0.1 * TensionDerivative);

    // Anti-Sway
    CmdBridgeSpeed := JoyX - (0.5 * SwayAngleX + 0.1 * SwayVelocityX);
    CmdTrolleySpeed := JoyY - (0.5 * SwayAngleY + 0.1 * SwayVelocityY);
END_IF;

BrakeResistorEnable := (DCBusVoltage > 750.0);

// Telemetry Packing for Ethernet/IP
TelemetryData[0] := HoistLoadCell;
TelemetryData[1] := CableTensionFeedback;
TelemetryData[2] := SwayAngleX;
TelemetryData[3] := SwayAngleY;
TelemetryData[4] := CmdBridgeSpeed;
TelemetryData[5] := CmdTrolleySpeed;
TelemetryData[6] := CmdHoistSpeed;
TelemetryData[7] := DINT_TO_REAL(FaultWord);
TelemetryData[8] := DCBusVoltage;

// Periodic MSG Trigger
HeartbeatTimer(IN:=NOT HeartbeatTimer.Q, PT:=T#500ms);
IF HeartbeatTimer.Q THEN
    TriggerTelemetry := TRUE;
END_IF;

// Send Data (Pseudo-MSG setup)
IF TriggerTelemetry THEN
    // In actual AB, configure MSG properties in controller tags
    MSG(EIP_Message);
    TriggerTelemetry := FALSE;
END_IF;
END_PROGRAM

PROGRAM MainCraneControl_M3
VAR
    // Dual Redundant Load Cells
    LoadCell_A : REAL; 
    LoadCell_B : REAL;
    LoadCell_A_Fault, LoadCell_B_Fault : BOOL;
    ActiveLoad : REAL;

    // SCADA Inputs (Subject to Cyber Check)
    SCADA_CmdX, SCADA_CmdY, SCADA_CmdZ : REAL;
    Validated_CmdX, Validated_CmdY, Validated_CmdZ : REAL;
    Prev_CmdX : REAL;
    Max_Accel : REAL := 5.0; // Max rate of change

    // State & Actuators
    DCBusVoltage, CableTensionFeedback : REAL;
    CmdBridgeSpeed, CmdTrolleySpeed, CmdHoistSpeed : REAL;
    BrakeResistorEnable, OverloadFault, SlackCableFault : BOOL;

    // Anti-sway & PID
    TensionError, TensionIntegral, TensionErrorPrev : REAL;
    SwayAngleX, SwayAngleY : REAL;

    // Comms & Security
    SecurityViolation : BOOL;
    FaultWord : DINT;
    TelemetryData : ARRAY[0..9] OF REAL;
    EIP_Message : MESSAGE;
END_VAR

// 1. Redundant Load Cell Failover (Hot Standby)
IF ABS(LoadCell_A - LoadCell_B) > 200.0 AND NOT LoadCell_A_Fault AND NOT LoadCell_B_Fault THEN
    // Deviation anomaly
    LoadCell_A_Fault := TRUE; // Default safe assumption, request maintenance
END_IF;

IF NOT LoadCell_A_Fault THEN
    ActiveLoad := LoadCell_A;
ELSIF NOT LoadCell_B_Fault THEN
    ActiveLoad := LoadCell_B;
ELSE
    ActiveLoad := 99999.0; // Force Overload
END_IF;

// 2. SCADA Cybersecurity Validation (IEC 62443)
// Check boundaries (Spoofing/Injection protection)
IF SCADA_CmdX > 100.0 OR SCADA_CmdX < -100.0 THEN
    SecurityViolation := TRUE;
    Validated_CmdX := 0.0;
ELSE
    // Check Rate of Change (DDoS / erratic command protection)
    IF ABS(SCADA_CmdX - Prev_CmdX) > Max_Accel THEN
        SecurityViolation := TRUE;
        Validated_CmdX := Prev_CmdX; // Hold last known good
    ELSE
        Validated_CmdX := SCADA_CmdX;
        SecurityViolation := FALSE;
    END_IF;
END_IF;
Prev_CmdX := Validated_CmdX;
// Assume similar validation for Y and Z...
Validated_CmdY := SCADA_CmdY;
Validated_CmdZ := SCADA_CmdZ;

// 3. Diagnostics & Protection
OverloadFault := ActiveLoad > 5000.0;
SlackCableFault := (CableTensionFeedback < 50.0) AND (Validated_CmdZ < 0.0);
FaultWord.0 := OverloadFault; FaultWord.1 := SlackCableFault; FaultWord.4 := SecurityViolation;

// 4. Control Logic
IF FaultWord = 0 THEN
    TensionError := 1000.0 - CableTensionFeedback;
    TensionIntegral := TensionIntegral + TensionError;
    CmdHoistSpeed := Validated_CmdZ + (1.2 * TensionError + 0.5 * TensionIntegral);

    CmdBridgeSpeed := Validated_CmdX - (0.5 * SwayAngleX);
    CmdTrolleySpeed := Validated_CmdY - (0.5 * SwayAngleY);
ELSE
    CmdHoistSpeed := 0.0; CmdBridgeSpeed := 0.0; CmdTrolleySpeed := 0.0;
END_IF;

BrakeResistorEnable := (DCBusVoltage > 750.0);
END_PROGRAM

PROGRAM MainCraneControl_M4
VAR
    // Load Cells & Drift Detection
    LoadCell_A, LoadCell_B : REAL;
    LoadCell_A_Fault, LoadCell_B_Fault : BOOL;
    ActiveLoad : REAL;
    AccumulatedDrift : REAL;
    DriftWarning : BOOL;

    // SCADA & Security
    SCADA_CmdX, SCADA_CmdY, SCADA_CmdZ : REAL;
    Validated_CmdX, Validated_CmdY, Validated_CmdZ, Prev_CmdX : REAL;
    SecurityViolation : BOOL;

    // Digital Twin Sync (HIL)
    HIL_SwayX, HIL_SwayY : REAL;
    HIL_Sync_Error : BOOL;
    UDP_Send_Socket, UDP_Recv_Socket : MESSAGE;

    // Self-Test Routine
    SelfTestActive : BOOL;
    SelfTestTimer : TON;
    SelfTestPassed : BOOL;
    BrakeResistorTestEnable : BOOL;

    // Core Actuation
    DCBusVoltage, CableTensionFeedback, SwayAngleX, SwayAngleY : REAL;
    CmdBridgeSpeed, CmdTrolleySpeed, CmdHoistSpeed : REAL;
    BrakeResistorEnable, OverloadFault, SlackCableFault : BOOL;
    FaultWord : DINT;
END_VAR

// 1. Long-Term Sensor Drift Detection
IF NOT LoadCell_A_Fault AND NOT LoadCell_B_Fault THEN
    // Low pass filter on the difference to detect slow drift vs dynamic spikes
    AccumulatedDrift := AccumulatedDrift + (ABS(LoadCell_A - LoadCell_B) - AccumulatedDrift) * 0.01;
    IF AccumulatedDrift > 50.0 THEN
        DriftWarning := TRUE;
    END_IF;
    ActiveLoad := (LoadCell_A + LoadCell_B) / 2.0; // Use average if both healthy
ELSE
    ActiveLoad := 99999.0; // Safe state on fault
END_IF;

// 2. HIL Digital Twin Sync
// Compare physical sway with simulated HIL sway
IF ABS(SwayAngleX - HIL_SwayX) > 5.0 THEN
    HIL_Sync_Error := TRUE;
ELSE
    HIL_Sync_Error := FALSE;
END_IF;
// Trigger UDP messages to HIL (Pseudo-code for AB sockets)
MSG(UDP_Send_Socket); MSG(UDP_Recv_Socket);

// 3. Daily Brake Resistor Self-Test Routine
// Activates at a specific time (managed by external trigger or RTC)
IF SelfTestActive AND ActiveLoad < 10.0 THEN // Only test when unloaded
    SelfTestTimer(IN:=TRUE, PT:=T#5s);
    BrakeResistorTestEnable := TRUE;
    // Monitor DC Bus drop to verify resistor works
    IF SelfTestTimer.Q THEN
        IF DCBusVoltage < 600.0 THEN
            SelfTestPassed := TRUE;
        ELSE
            SelfTestPassed := FALSE;
        END_IF;
        SelfTestActive := FALSE;
        BrakeResistorTestEnable := FALSE;
    END_IF;
ELSE
    SelfTestTimer(IN:=FALSE);
    BrakeResistorTestEnable := FALSE;
END_IF;

// 4. Cyber Validation
IF ABS(SCADA_CmdX - Prev_CmdX) > 5.0 THEN
    SecurityViolation := TRUE;
    Validated_CmdX := Prev_CmdX;
ELSE
    Validated_CmdX := SCADA_CmdX;
END_IF;
Prev_CmdX := Validated_CmdX;

// 5. Core Protection & Motion
OverloadFault := ActiveLoad > 5000.0;
FaultWord.0 := OverloadFault; FaultWord.1 := DriftWarning; FaultWord.2 := HIL_Sync_Error;

IF FaultWord = 0 AND NOT SelfTestActive THEN
    CmdHoistSpeed := SCADA_CmdZ; // Add PID tension here in real logic
    CmdBridgeSpeed := Validated_CmdX - (0.5 * SwayAngleX);
    CmdTrolleySpeed := SCADA_CmdY - (0.5 * SwayAngleY);
ELSE
    CmdHoistSpeed := 0.0; CmdBridgeSpeed := 0.0; CmdTrolleySpeed := 0.0;
END_IF;

BrakeResistorEnable := (DCBusVoltage > 750.0) OR BrakeResistorTestEnable;
END_PROGRAM

