    IF Encoder_Pulse THEN
        FOR i := 2000 TO 1 BY -1 DO Shift_Reg[i] := Shift_Reg[i-1]; END_FOR;
        Shift_Reg[0] := 0;
        IF Dwell_Count > 0 THEN Dwell_Count := Dwell_Count - 1; ELSE Diverter_Valve := FALSE; END_IF;
    END_IF;

    IF PE_Entry AND NOT PE_Entry_Prev AND RFID_Valid THEN Shift_Reg[0] := RFID_Data; END_IF;
    PE_Entry_Prev := PE_Entry;

    IF Shift_Reg[500] = 1 THEN
        Diverter_Valve := TRUE;
        Dwell_Count := 20;
        Shift_Reg[500] := 0;
    END_IF;
END_FUNCTION_BLOCK
