    fDriftTolerance : REAL := 0.1;
    bSensorDriftAlarm : BOOL;
    stHilStateOut : ST_DigitalTwinData;
    bHilSyncEnable : BOOL := TRUE;
    stScadaData : ST_SCADA_Interface;
    bAccessGranted : BOOL;
    bBlower1Cmd, bBlower2Cmd : BOOL;
    bAirLockEntry, bAirLockExit : BOOL;
END_VAR

IF ABS(fPressureSensor1 - fPressureSensor2) > fDriftTolerance THEN
    bSensorDriftAlarm := TRUE;
    fCompensatedPressure := MIN(fPressureSensor1, fPressureSensor2);
ELSE
    bSensorDriftAlarm := FALSE;
    fCompensatedPressure := (fPressureSensor1 + fPressureSensor2) / 2.0;
END_IF

IF bHilSyncEnable THEN
    stHilStateOut.fPressure := fCompensatedPressure;
    stHilStateOut.nState := nState;
    stHilStateOut.bEntryValve := bAirLockEntry;
    stHilStateOut.bExitValve := bAirLockExit;
END_IF

IF bSystemInitialize THEN
    CASE nState OF
        0:
            bBlower1Cmd := TRUE;
            bBlower2Cmd := TRUE;
            bAirLockEntry := TRUE;
            bAirLockExit := TRUE;
            nState := 1;
        1:
            IF fCompensatedPressure > 0.5 THEN
                nState := 2;
