    END_CASE
ELSE
    CASE nState OF
        10:
            IF bAccessGranted AND NOT bSensorDriftAlarm THEN
                // Normal operations
            END_IF
    END_CASE
END_IF

stScadaData.fCurrentPressure := fCompensatedPressure;
stScadaData.nActiveAlarms.0 := bSensorDriftAlarm;
