    END_IF;

    // Slip Monitoring
    #SlipDetected := (#DriveSpeed > 0.0) AND (#TailSpeed < (#DriveSpeed * (1.0 - #SLIP_TOLERANCE)));
    #SlipTimer(IN := #SlipDetected AND #RunState, PT := T#2s);
    IF #SlipTimer.Q THEN
        #AlarmSlip := TRUE;
        #RunState := FALSE;
    END_IF;

    // Start / Stop Logic
    IF #StartCmd AND NOT #AlarmTear AND NOT #AlarmSlip THEN
        #RunState := TRUE;
    ELSIF #StopCmd THEN
        #RunState := FALSE;
    END_IF;

    #MainDriveRun := #RunState;

    // Tensioning Winch Control
    #TensionLow := #TensionLoadCell < (#TENSION_SP - #TENSION_DB);
    #TensionHigh := #TensionLoadCell > (#TENSION_SP + #TENSION_DB);

    #WinchDriveFwd := #TensionLow AND NOT #TensionHigh; // Increase tension
    #WinchDriveRev := #TensionHigh AND NOT #TensionLow; // Decrease tension

    #SystemReady := NOT #AlarmTear AND NOT #AlarmSlip AND NOT #TensionLow AND NOT #TensionHigh;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "OverlandConveyorDepth"
VERSION : 0.1
   VAR_INPUT 
      StartCmd : Bool;
      StopCmd : Bool;
      BeltTearSensor : Bool;
      DriveSpeedFb : Real;
      TailSpeedFb : Real;
      TensionLoadCell : Real;
      OreFeedRate : Real; // Tons per hour
   END_VAR
   VAR_OUTPUT 
      MainDriveRun : Bool;
      MainDriveSpeedRef : Real; // Speed Setpoint %
      WinchDriveFwd : Bool;
      WinchDriveRev : Bool;
      AlarmActive : Bool;
   END_VAR
   VAR 
      RunState : Bool;
      AlarmTear : Bool;
      AlarmSlip : Bool;
      SlipTimer : TON;
      SpeedPID : "PID_Compact";
   END_VAR
   VAR CONSTANT 
      SLIP_TOLERANCE : Real := 0.05;
      TENSION_SP : Real := 150.0;
      TENSION_DB : Real := 10.0;
   END_VAR

BEGIN
    // Safety & Monitoring Interlocks
    IF #BeltTearSensor THEN
        #AlarmTear := TRUE;
    END_IF;

    #SlipTimer(IN := (#DriveSpeedFb > 10.0) AND (#TailSpeedFb < (#DriveSpeedFb * (1.0 - #SLIP_TOLERANCE))), PT := T#2s);
    IF #SlipTimer.Q THEN
        #AlarmSlip := TRUE;
    END_IF;

    #AlarmActive := #AlarmTear OR #AlarmSlip;

    // Conveyor Control
    IF #StartCmd AND NOT #AlarmActive THEN
        #RunState := TRUE;
    ELSIF #StopCmd OR #AlarmActive THEN
        #RunState := FALSE;
    END_IF;

    #MainDriveRun := #RunState;

    // Winch Tension Control
    #WinchDriveFwd := (#TensionLoadCell < (#TENSION_SP - #TENSION_DB)) AND #RunState;
    #WinchDriveRev := (#TensionLoadCell > (#TENSION_SP + #TENSION_DB)) AND #RunState;

    // PID Speed Regulation based on Ore Feed Rate
    #SpeedPID(Setpoint := #OreFeedRate,
              Input := #DriveSpeedFb * 0.1,
              ManualEnable := NOT #RunState,
              ManualValue := 0.0,
              Output => #MainDriveSpeedRef);
END_FUNCTION_BLOCK

