FUNCTION_BLOCK "AerationBasin_Base"
VAR_INPUT
    DO_ProcessValue : REAL; // Dissolved Oxygen mg/L
    Ammonia_ProcessValue : REAL; // Ammonia mg/L
    DO_Setpoint_Base : REAL; // Base DO SP
    Ammonia_Threshold : REAL; // High Ammonia limit
END_VAR
VAR_OUTPUT
    Total_Air_Demand : REAL; // Total airflow demand 0-100%
    Blower_Run_Cmd : ARRAY[1..3] OF BOOL;
END_VAR
VAR
    DO_PID : "PID_Compact";
    Active_DO_SP : REAL;
    Active_Blowers : INT;
END_VAR
BEGIN
    // Ammonia-based DO setpoint override
    IF Ammonia_ProcessValue > Ammonia_Threshold THEN
        Active_DO_SP := DO_Setpoint_Base + 1.0; // Boost DO to nitrify
    ELSE
        Active_DO_SP := DO_Setpoint_Base;
    END_IF;

    // DO Cascade PID
    DO_PID(Setpoint := Active_DO_SP, Input := DO_ProcessValue);
    Total_Air_Demand := DO_PID.Output;

    // Blower Sequencing Logic
    IF Total_Air_Demand > 80.0 THEN Active_Blowers := 3;
    ELSIF Total_Air_Demand > 45.0 THEN Active_Blowers := 2;
    ELSIF Total_Air_Demand > 10.0 THEN Active_Blowers := 1;
    ELSE Active_Blowers := 0;
    END_IF;

    Blower_Run_Cmd[1] := (Active_Blowers >= 1);
    Blower_Run_Cmd[2] := (Active_Blowers >= 2);
    Blower_Run_Cmd[3] := (Active_Blowers >= 3);
END_FUNCTION_BLOCK

FUNCTION_BLOCK "AerationBasin_Mut1"
VAR_INPUT
    DO_ProcessValue : REAL;
    Ammonia_ProcessValue : REAL;
    Header_Pressure : REAL;
    DO_Setpoint_Base : REAL;
    Ammonia_Threshold : REAL;
    Pressure_Limit_High : REAL;
    Pressure_Limit_Low : REAL;
END_VAR
VAR_OUTPUT
    Total_Air_Demand : REAL;
    Header_Pressure_SP : REAL;
    Blower_Run_Cmd : ARRAY[1..3] OF BOOL;
    Blower_Speed_Ref : REAL;
    Surge_Alarm : BOOL;
END_VAR
VAR
    DO_PID : "PID_Compact";
    Pressure_PID : "PID_Compact";
    Active_DO_SP : REAL;
    Active_Blowers : INT;
END_VAR
BEGIN
    // Ammonia override
    IF Ammonia_ProcessValue > Ammonia_Threshold THEN
        Active_DO_SP := DO_Setpoint_Base + 1.5;
    ELSE
        Active_DO_SP := DO_Setpoint_Base;
    END_IF;

    // Cascade DO -> Pressure
    DO_PID(Setpoint := Active_DO_SP, Input := DO_ProcessValue);
    Header_Pressure_SP := DO_PID.Output * 10.0; // Scaled SP for pressure

    // Pressure PID -> Blower Speed
    Pressure_PID(Setpoint := Header_Pressure_SP, Input := Header_Pressure);
    Blower_Speed_Ref := Pressure_PID.Output;

    // Blower Surge Protection
    Surge_Alarm := (Header_Pressure > Pressure_Limit_High) AND (Blower_Speed_Ref < 40.0);
    IF Surge_Alarm THEN
        Blower_Speed_Ref := 40.0; // Enforce minimum speed to prevent surge
    END_IF;

    // Blower Sequencing
    IF Blower_Speed_Ref > 90.0 THEN Active_Blowers := 3;
    ELSIF Blower_Speed_Ref > 50.0 THEN Active_Blowers := 2;
    ELSIF Blower_Speed_Ref > 20.0 THEN Active_Blowers := 1;
    ELSE Active_Blowers := 0;
    END_IF;

    Blower_Run_Cmd[1] := (Active_Blowers >= 1);
    Blower_Run_Cmd[2] := (Active_Blowers >= 2);
    Blower_Run_Cmd[3] := (Active_Blowers >= 3);
END_FUNCTION_BLOCK

FUNCTION_BLOCK "AerationBasin_Mut2"
VAR_INPUT
    DO_ProcessValue : REAL;
    Ammonia_ProcessValue : REAL;
    Header_Pressure : REAL;
    PN_Status : WORD; // Profinet Status Word
END_VAR
VAR_OUTPUT
    Blower_Run_Cmd : ARRAY[1..3] OF BOOL;
    Blower_Speed_Ref : REAL;
    System_Faults : DWORD; // Diagnostics bitmask
    PN_Control : WORD;
END_VAR
VAR
    DO_PID : "PID_Compact";
    Pressure_PID : "PID_Compact";
    Active_DO_SP : REAL := 2.0;
    PN_Comm_Error : BOOL;
    Sensor_Fault : BOOL;
END_VAR
BEGIN
    // Diagnostics & Comm check
    PN_Comm_Error := (PN_Status AND 16#0001) = 0; // Check Profinet link OK
    Sensor_Fault := (DO_ProcessValue < 0.0) OR (DO_ProcessValue > 20.0);

    IF PN_Comm_Error THEN System_Faults := System_Faults OR 16#0001; END_IF;
    IF Sensor_Fault THEN System_Faults := System_Faults OR 16#0002; END_IF;

    IF NOT PN_Comm_Error AND NOT Sensor_Fault THEN
        // Ammonia override & Control logic
        IF Ammonia_ProcessValue > 3.0 THEN Active_DO_SP := 3.5; END_IF;

        DO_PID(Setpoint := Active_DO_SP, Input := DO_ProcessValue);
        Pressure_PID(Setpoint := DO_PID.Output * 5.0, Input := Header_Pressure);

        Blower_Speed_Ref := Pressure_PID.Output;
        Blower_Run_Cmd[1] := (Blower_Speed_Ref > 10.0);
        PN_Control := 16#000F; // Enable drives via Profinet
    ELSE
        // Fault state - Safe fallback
        Blower_Speed_Ref := 30.0; // Fixed fallback speed
        Blower_Run_Cmd[1] := TRUE;
        PN_Control := 16#0000;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "AerationBasin_Mut3"
VAR_INPUT
    DO_ProcessValue : REAL;
    Ammonia_ProcessValue : REAL;
    Header_Pressure : REAL;
    User_Role : INT; // 0=Guest, 1=Operator, 2=Admin (IEC 62443)
    Partner_PLC_Active : BOOL; // Redundancy heartbeat
    SCADA_Remote_SP : REAL;
END_VAR
VAR_OUTPUT
    Blower_Speed_Ref : REAL;
    System_Faults : DWORD;
    SCADA_Data_Block : ARRAY[0..9] OF REAL; // SCADA Telemetry
END_VAR
VAR
    Active_DO_SP : REAL;
    DO_PID : "PID_Compact";
    Is_Primary_PLC : BOOL := TRUE;
END_VAR
BEGIN
    // Failover Logic
    IF NOT Partner_PLC_Active THEN
        Is_Primary_PLC := TRUE; // Assume control
    END_IF;

    IF Is_Primary_PLC THEN
        // Cybersec / RBAC
        IF User_Role >= 1 THEN
            Active_DO_SP := SCADA_Remote_SP;
        ELSE
            Active_DO_SP := 2.0; // Default secure SP
        END_IF;

        // Control logic
        IF Ammonia_ProcessValue > 3.0 THEN Active_DO_SP := Active_DO_SP + 1.0; END_IF;

        DO_PID(Setpoint := Active_DO_SP, Input := DO_ProcessValue);
        Blower_Speed_Ref := DO_PID.Output;

        // SCADA Integration
        SCADA_Data_Block[0] := DO_ProcessValue;
        SCADA_Data_Block[1] := Active_DO_SP;
        SCADA_Data_Block[2] := Blower_Speed_Ref;
        SCADA_Data_Block[3] := INT_TO_REAL(User_Role);
    ELSE
        Blower_Speed_Ref := 0.0; // Standby mode
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "AerationBasin_Mut4"
VAR_INPUT
    DO_PV_1 : REAL; // Redundant DO sensor 1
    DO_PV_2 : REAL; // Redundant DO sensor 2
    Ammonia_PV : REAL;
    HIL_Sync_Pulse : BOOL; // Hardware-in-the-Loop Twin Heartbeat
    Init_SelfTest : BOOL;
END_VAR
VAR_OUTPUT
    Blower_Speed_Ref : REAL;
    Sensor_Drift_Alarm : BOOL;
    HIL_Loss_Alarm : BOOL;
    SelfTest_Active : BOOL;
END_VAR
VAR
    Validated_DO : REAL;
    DO_PID : "PID_Compact";
    HIL_Timer : TON;
    SelfTest_Step : INT;
END_VAR
BEGIN
    // Sensor Drift Detection (Adversarial Robustness)
    IF ABS(DO_PV_1 - DO_PV_2) > 0.5 THEN
        Sensor_Drift_Alarm := TRUE;
        Validated_DO := MIN(IN1:=DO_PV_1, IN2:=DO_PV_2); // Safe fallback
    ELSE
        Sensor_Drift_Alarm := FALSE;
        Validated_DO := (DO_PV_1 + DO_PV_2) / 2.0;
    END_IF;

    // HIL Digital Twin Sync logic placeholder
    IF NOT HIL_Sync_Pulse THEN HIL_Loss_Alarm := TRUE; ELSE HIL_Loss_Alarm := FALSE; END_IF;

    // Automated Self-Test Routine
    IF Init_SelfTest AND NOT SelfTest_Active THEN
        SelfTest_Active := TRUE;
        SelfTest_Step := 1;
    END_IF;

    IF SelfTest_Active THEN
        // Cycle through outputs safely
        Blower_Speed_Ref := 25.0; // Test speed
        IF HIL_Sync_Pulse THEN SelfTest_Active := FALSE; END_IF;
    ELSE
        // Normal Control
        DO_PID(Setpoint := 2.5, Input := Validated_DO);
        Blower_Speed_Ref := DO_PID.Output;
    END_IF;
END_FUNCTION_BLOCK

