    bHilModeActive : BOOL;
    fHilWindSpeed : REAL;
    fHilWindDirection : REAL;
    fHilGearboxTemp : REAL;

    // Sensor Drift Detection (Adversarial Mutation)
    fWindSpeedDriftThreshold : REAL := 2.5;
    bSensorDriftAlarm : BOOL;

    // Automated Self-Test Routine (Adversarial Mutation)
    nStartupState : INT := 0; 
    // 0: Init, 1: Pitch Sweep Test, 2: Yaw Actuation Test, 3: Operational
    fSelfTestTimer : REAL;
    bSelfTestPassed : BOOL;

    // Security, SCADA, Failover
    bScadaRemoteControl : BOOL;
    nAccessLevel : INT;
    bSecurityLockout : BOOL;
    bPrimaryAnemometerFail : BOOL;

    // Subsystems & Faults
    fGearboxVibration : REAL;
    fGearboxTemp : REAL;
    bCoolingPump : BOOL;
    fbEcMasterState : FB_EcGetMasterState;
    nSystemFaultCode : DWORD;
    bFaultActive : BOOL;
    bSafetyBrakeEngaged : BOOL;

    // Controls
    fPitchSetpoints : ARRAY[1..3] OF LREAL;
    fPitchActual : ARRAY[1..3] OF LREAL;
    fPitchOutput : ARRAY[1..3] OF LREAL;
    fbPitchPID : ARRAY[1..3] OF FB_BasicPID;
    fYawPosition : REAL;
    bYawMotorCW : BOOL;
    bYawMotorCCW : BOOL;

    i : INT;
END_VAR

// 1. HIL Digital Twin Synchronization
IF bHilModeActive THEN
    fWindSpeedPrimary := fHilWindSpeed;
    fWindDirection := fHilWindDirection;
    fGearboxTemp := fHilGearboxTemp;
END_IF

// 2. Sensor Drift Detection Array
IF ABS(fWindSpeedPrimary - fWindSpeedSecondary) > fWindSpeedDriftThreshold THEN
    bSensorDriftAlarm := TRUE;
ELSE
    bSensorDriftAlarm := FALSE;
END_IF

// 3. Failover & Cybersecurity
IF bPrimaryAnemometerFail OR bSensorDriftAlarm THEN fWindSpeed := fWindSpeedSecondary;
ELSE fWindSpeed := fWindSpeedPrimary; END_IF

bSecurityLockout := (bScadaRemoteControl AND nAccessLevel < 3);

// 4. Fault Handling
fbEcMasterState(bExecute := TRUE);
nSystemFaultCode := 0;
IF fbEcMasterState.state <> 8 THEN nSystemFaultCode := nSystemFaultCode OR 16#0001; END_IF;
IF fGearboxVibration > 15.0 THEN nSystemFaultCode := nSystemFaultCode OR 16#0002; END_IF;
IF fGearboxTemp > 90.0 THEN nSystemFaultCode := nSystemFaultCode OR 16#0004; END_IF;
IF bSensorDriftAlarm THEN nSystemFaultCode := nSystemFaultCode OR 16#0010; END_IF;
bFaultActive := (nSystemFaultCode <> 0);

bCoolingPump := (fGearboxTemp > 75.0);

// 5. Automated Self-Test Startup Routine
IF nStartupState = 0 THEN
    IF NOT bFaultActive THEN nStartupState := 1; END_IF;

ELSIF nStartupState = 1 THEN // Pitch Sweep Test
    FOR i:=1 TO 3 DO fPitchSetpoints[i] := 45.0; END_FOR;
    IF ABS(fPitchActual[1] - 45.0) < 1.0 AND ABS(fPitchActual[2] - 45.0) < 1.0 AND ABS(fPitchActual[3] - 45.0) < 1.0 THEN
        nStartupState := 2;
    END_IF

ELSIF nStartupState = 2 THEN // Yaw Test
    bYawMotorCW := TRUE; 
    // Wait for positional delta in real application, simplified here
    nStartupState := 3;
    bYawMotorCW := FALSE;
    bSelfTestPassed := TRUE;

ELSIF nStartupState = 3 THEN // Operational State
    IF fWindSpeed > 25.0 OR bFaultActive THEN
        bSafetyBrakeEngaged := TRUE;
        bYawMotorCW := FALSE; bYawMotorCCW := FALSE;
        FOR i:=1 TO 3 DO fPitchSetpoints[i] := 90.0; END_FOR;
    ELSE
        bSafetyBrakeEngaged := FALSE;
        // Yaw
        IF (fWindDirection - fYawPosition) > 5.0 THEN bYawMotorCW := TRUE; bYawMotorCCW := FALSE;
        ELSIF (fWindDirection - fYawPosition) < -5.0 THEN bYawMotorCW := FALSE; bYawMotorCCW := TRUE;
        ELSE bYawMotorCW := FALSE; bYawMotorCCW := FALSE; END_IF;

        // Pitch
        IF fWindSpeed < 3.0 THEN FOR i:=1 TO 3 DO fPitchSetpoints[i] := 90.0; END_FOR;
        ELSIF fWindSpeed <= 12.0 THEN FOR i:=1 TO 3 DO fPitchSetpoints[i] := 0.0; END_FOR;
        ELSE FOR i:=1 TO 3 DO fPitchSetpoints[i] := MIN((fWindSpeed - 12.0) * 2.5, 90.0); END_FOR; END_IF;
    END_IF
END_IF

// 6. PID Execution
FOR i := 1 TO 3 DO
    fbPitchPID[i](
        fSetpointValue := fPitchSetpoints[i],
        fActualValue := fPitchActual[i],
        bReset := bSafetyBrakeEngaged,
        fCtrlOutput => fPitchOutput[i]
    );
END_FOR
