    MashStep : INT := 0;
    RTD1_Temp : REAL;
    RTD2_Temp : REAL;
    Temperature : REAL;
    TempSP : REAL;
    AgitatorSpeed : REAL;
    FaultActive : BOOL := FALSE;
    SensorDriftFault : BOOL := FALSE;
    SelfTestComplete : BOOL := FALSE;
    SelfTestStep : INT := 0;
    HIL_Sync_Buffer : ARRAY[0..15] OF REAL;
    IsPrimary : BOOL;
    Timer : TON;
END_VAR

// Sensor Drift Detection
IF ABS(RTD1_Temp - RTD2_Temp) > 2.0 THEN
    SensorDriftFault := TRUE;
    FaultActive := TRUE;
ELSE
    Temperature := (RTD1_Temp + RTD2_Temp) / 2.0;
END_IF;

// Automated Startup Self-Test (Fault Injection)
IF NOT SelfTestComplete THEN
    CASE SelfTestStep OF
        0: TempSP := 150.0; Timer(IN:=TRUE, PT:=T#2s); IF Timer.Q THEN Timer(IN:=FALSE); SelfTestStep := 1; END_IF; // Inject over-temp
        1: IF FaultActive THEN SelfTestStep := 2; FaultActive := FALSE; END_IF; // Verify interlock caught it
        2: SensorDriftFault := TRUE; Timer(IN:=TRUE, PT:=T#2s); IF Timer.Q THEN Timer(IN:=FALSE); SelfTestStep := 3; END_IF; // Inject drift
        3: IF FaultActive THEN FaultActive := FALSE; SensorDriftFault := FALSE; SelfTestComplete := TRUE; END_IF;
    END_CASE;
    RETURN; // Halt normal operation until test finishes
END_IF;

IF IsPrimary AND NOT FaultActive THEN
    // HIL Digital Twin Sync
    HIL_Sync_Buffer[0] := Temperature;
    HIL_Sync_Buffer[1] := AgitatorSpeed;

    CASE MashStep OF
        0: TempSP := 50.0; AgitatorSpeed := 30.0; Timer(IN:=TRUE, PT:=T#20m); IF Timer.Q THEN Timer(IN:=FALSE); MashStep := 1; END_IF;
