        2: TempSP := 72.0; AgitatorSpeed := 50.0; Timer(IN:=TRUE, PT:=T#20m); IF Timer.Q THEN Timer(IN:=FALSE); MashStep := 3; END_IF;
        3: TempSP := 78.0; AgitatorSpeed := 20.0; Timer(IN:=TRUE, PT:=T#10m); IF Timer.Q THEN Timer(IN:=FALSE); MashStep := 4; END_IF;
