    DepthError, PrevDepthError, DepthIntegral, DepthDerivative, DepthControlOut : REAL;
END_VAR

TensionAlarm := (TensionSensor > MaxTension);

DepthError := DepthSetpoint - DepthSensor;
DepthIntegral := DepthIntegral + DepthError;
DepthDerivative := DepthError - PrevDepthError;
PrevDepthError := DepthError;
DepthControlOut := (kp * DepthError) + (ki * DepthIntegral) + (kd * DepthDerivative);

ThrusterCmd[1] := JoyX + JoyY + JoyYaw;
ThrusterCmd[2] := -JoyX + JoyY - JoyYaw;
ThrusterCmd[3] := -JoyX - JoyY + JoyYaw;
ThrusterCmd[4] := JoyX - JoyY - JoyYaw;

ThrusterCmd[5] := JoyZ + DepthControlOut + JoyRoll + JoyPitch;
ThrusterCmd[6] := JoyZ + DepthControlOut - JoyRoll + JoyPitch;
ThrusterCmd[7] := JoyZ + DepthControlOut - JoyRoll - JoyPitch;
ThrusterCmd[8] := JoyZ + DepthControlOut + JoyRoll - JoyPitch;
END_PROGRAM

PROGRAM MAIN
VAR
    JoyCmd : ARRAY[1..6] OF REAL;
    DepthSensor1, DepthSensor2, TensionSensor, DepthSetpoint : REAL;
    CurrentVelocity : REAL;
    ThrusterCmd : ARRAY[1..8] OF REAL;
    EstDepth, EstVelocity, P00, P01, P10, P11 : REAL;
    Q : REAL := 0.001; R : REAL := 0.1;
    K0, K1, Y, AvgDepth : REAL;
    DragCoef : REAL := 1.2; VehicleArea : REAL := 2.5; WaterDensity : REAL := 1025.0;
    DragForce : REAL;
    kp: REAL:= 2.0; ki: REAL:= 0.2; kd: REAL:= 0.1;
    DepthError, DepthInt, DepthControlOut : REAL;
END_VAR

AvgDepth := (DepthSensor1 + DepthSensor2) / 2.0;
EstDepth := EstDepth + EstVelocity; 
P00 := P00 + P11 + Q; P01 := P01 + P11; P10 := P10 + P11; P11 := P11 + Q;
Y := AvgDepth - EstDepth;
K0 := P00 / (P00 + R); K1 := P10 / (P00 + R);
EstDepth := EstDepth + K0 * Y;
EstVelocity := EstVelocity + K1 * Y;
P00 := (1 - K0) * P00; P01 := (1 - K0) * P01;
P10 := -K1 * P00 + P10; P11 := -K1 * P01 + P11;

DragForce := 0.5 * WaterDensity * (CurrentVelocity * ABS(CurrentVelocity)) * DragCoef * VehicleArea;

DepthError := DepthSetpoint - EstDepth;
DepthInt := DepthInt + DepthError;
DepthControlOut := (kp * DepthError) + (ki * DepthInt) - (kd * EstVelocity);
JoyCmd[3] := JoyCmd[3] + DragForce;

ThrusterCmd[1] := JoyCmd[1] + JoyCmd[2] + JoyCmd[6];
ThrusterCmd[2] := -JoyCmd[1] + JoyCmd[2] - JoyCmd[6];
ThrusterCmd[3] := -JoyCmd[1] - JoyCmd[2] + JoyCmd[6];
ThrusterCmd[4] := JoyCmd[1] - JoyCmd[2] - JoyCmd[6];
ThrusterCmd[5] := JoyCmd[3] + DepthControlOut + JoyCmd[4] + JoyCmd[5];
ThrusterCmd[6] := JoyCmd[3] + DepthControlOut - JoyCmd[4] + JoyCmd[5];
ThrusterCmd[7] := JoyCmd[3] + DepthControlOut - JoyCmd[4] - JoyCmd[5];
ThrusterCmd[8] := JoyCmd[3] + DepthControlOut + JoyCmd[4] - JoyCmd[5];
END_PROGRAM

PROGRAM MAIN
VAR
    JoyCmd : ARRAY[1..6] OF REAL;
    DepthSensor, DepthSetpoint, TensionSensor : REAL;
    ThrusterCmd : ARRAY[1..8] OF REAL;
    ThrusterState AT %I* : ARRAY[1..8] OF UINT; 
    WcState AT %I* : ARRAY[1..8] OF BOOL;       
    MinorAlarm, MajorAlarm, CriticalAlarm, EmergencyBallastBlow : BOOL;
    ThrusterFault : ARRAY[1..8] OF BOOL;
    FaultCount, i : INT;
    DepthError, DepthInt, PrevError, DepthControlOut : REAL;
END_VAR

FaultCount := 0;
FOR i := 1 TO 8 DO
    ThrusterFault[i] := WcState[i] OR ((ThrusterState[i] AND 16#0008) = 16#0008);
    IF ThrusterFault[i] THEN FaultCount := FaultCount + 1; END_IF
END_FOR

MinorAlarm := (FaultCount = 1);
MajorAlarm := (FaultCount >= 2) OR (TensionSensor > 4000.0);
CriticalAlarm := (FaultCount >= 4) OR (TensionSensor > 6000.0);

IF CriticalAlarm THEN
    EmergencyBallastBlow := TRUE;
    FOR i := 1 TO 8 DO ThrusterCmd[i] := 0.0; END_FOR
ELSE
    EmergencyBallastBlow := FALSE;
    DepthError := DepthSetpoint - DepthSensor;
    DepthInt := DepthInt + DepthError;
    DepthControlOut := (1.5 * DepthError) + (0.1 * DepthInt) + (0.05 * (DepthError - PrevError));
    PrevError := DepthError;

    ThrusterCmd[1] := JoyCmd[1] + JoyCmd[2] + JoyCmd[6];
    ThrusterCmd[2] := -JoyCmd[1] + JoyCmd[2] - JoyCmd[6];
    ThrusterCmd[3] := -JoyCmd[1] - JoyCmd[2] + JoyCmd[6];
    ThrusterCmd[4] := JoyCmd[1] - JoyCmd[2] - JoyCmd[6];
    ThrusterCmd[5] := JoyCmd[3] + DepthControlOut + JoyCmd[4] + JoyCmd[5];
    ThrusterCmd[6] := JoyCmd[3] + DepthControlOut - JoyCmd[4] + JoyCmd[5];
    ThrusterCmd[7] := JoyCmd[3] + DepthControlOut - JoyCmd[4] - JoyCmd[5];
    ThrusterCmd[8] := JoyCmd[3] + DepthControlOut + JoyCmd[4] - JoyCmd[5];

    FOR i := 1 TO 8 DO
        IF ThrusterFault[i] THEN ThrusterCmd[i] := 0.0; END_IF
    END_FOR
END_IF
END_PROGRAM

PROGRAM MAIN
VAR
    JoyCmd : ARRAY[1..6] OF REAL;
    DepthSensor, TensionSensor, DepthSetpoint : REAL;
