Here is the Siemens SCL program designed with cybersecurity, redundancy, and SCADA integration in mind:

```pascal
TYPE "SCADA_Interface"
STRUCT
    Cmd_Start : BOOL;
    Cmd_Stop : BOOL;
    Sp_Temp : REAL;
    Act_Temp : REAL;
    Sys_Status : WORD;
    OperatorLevel : INT; // IEC 62443 Role-based access (1=Op, 2=Eng, 3=Admin)
END_STRUCT;
END_TYPE

FUNCTION_BLOCK "MilkPasteurizer_Secure"
VAR_INPUT
    SCADA_Data : "SCADA_Interface";
    IsPrimaryPLC : BOOL; // Redundancy status
    PartnerAlive : BOOL;
    TempSens1 : REAL;
    TempSens2 : REAL;
END_VAR

VAR_OUTPUT
    Heater_CV : REAL;
    FDV_Fwd : BOOL;
    FDV_Div : BOOL;
END_VAR

VAR
    ProcessActive : BOOL;
    ActiveTemp : REAL;
    PID_Inst : "PID_Compact";
    TMR_Hold : TON;
    SecurityFault : BOOL;
END_VAR

BEGIN
    // Redundancy Failover
    IF NOT IsPrimaryPLC AND PartnerAlive THEN
        // Standby mode, skip logic
        RETURN;
    END_IF;

    // IEC 62443 Access Control
    IF SCADA_Data.OperatorLevel < 1 THEN
        SecurityFault := TRUE;
        ProcessActive := FALSE;
    ELSE
        SecurityFault := FALSE;
    END_IF;

    // Sensor Redundancy / Averaging
    IF ABS(TempSens1 - TempSens2) > 2.0 THEN
        // Sensor deviation fault
        ActiveTemp := TempSens1; // Fallback
    ELSE
        ActiveTemp := (TempSens1 + TempSens2) / 2.0;
    END_IF;
    SCADA_Data.Act_Temp := ActiveTemp;

    // Process Control
    IF SCADA_Data.Cmd_Start AND NOT SCADA_Data.Cmd_Stop AND NOT SecurityFault THEN
        ProcessActive := TRUE;
    ELSIF SCADA_Data.Cmd_Stop OR SecurityFault THEN
        ProcessActive := FALSE;
    END_IF;

    // PID Control
    PID_Inst(
        sMode := 3,
        Setpoint := SCADA_Data.Sp_Temp,
        Input := ActiveTemp,
        Output => Heater_CV
    );

    // Holding and FDV
    TMR_Hold(IN := (ActiveTemp >= SCADA_Data.Sp_Temp) AND ProcessActive, PT := T#15S);

    IF ProcessActive AND TMR_Hold.Q THEN
        FDV_Fwd := TRUE;
        FDV_Div := FALSE;
        SCADA_Data.Sys_Status := 16#0001; // Forward Flow
    ELSE
        FDV_Fwd := FALSE;
        FDV_Div := TRUE;
        SCADA_Data.Sys_Status := 16#0002; // Divert
    END_IF;
END_FUNCTION_BLOCK
```

Here is the Siemens SCL program focusing on adversarial resilience, HIL synchronization, and automated self-testing:

```pascal
FUNCTION_BLOCK "MilkPasteurizer_Adversarial"
VAR_INPUT
    Start : BOOL;
    TempSens1 : REAL;
    TempSens2 : REAL;
    HIL_Twin_Temp : REAL; // Digital twin expected temperature
    FDV_Pos_Fwd_Feedback : BOOL;
    FDV_Pos_Div_Feedback : BOOL;
END_VAR

VAR_OUTPUT
    Heater_Out : REAL;
    FDV_Fwd_Cmd : BOOL;
    FDV_Div_Cmd : BOOL;
    DriftAlarm : BOOL;
    TwinSyncAlarm : BOOL;
    SelfTestFailed : BOOL;
    SystemReady : BOOL;
END_VAR

VAR
    State : INT := 0; // 0=Init, 1=SelfTest_Divert, 2=SelfTest_Fwd, 3=Run
    ActiveTemp : REAL;
    TestTimer : TON;
    PID_Inst : "PID_Compact";
    HoldTimer : TON;
END_VAR

BEGIN
    // 1. Sensor Drift & HIL Sync Detection
    IF ABS(TempSens1 - TempSens2) > 1.5 THEN
        DriftAlarm := TRUE;
    ELSE
        DriftAlarm := FALSE;
    END_IF;

    ActiveTemp := (TempSens1 + TempSens2) / 2.0;

    IF ABS(ActiveTemp - HIL_Twin_Temp) > 3.0 THEN
        TwinSyncAlarm := TRUE; // Twin deviation indicates potential process anomaly
    ELSE
        TwinSyncAlarm := FALSE;
    END_IF;

    // 2. State Machine & Self-Test Routine
    CASE State OF
        0: // Init
            IF Start AND NOT DriftAlarm AND NOT TwinSyncAlarm THEN
                State := 1;
            END_IF;

        1: // Self-Test: Command Divert
            FDV_Fwd_Cmd := FALSE;
            FDV_Div_Cmd := TRUE;
            TestTimer(IN:=TRUE, PT:=T#3S);
            IF TestTimer.Q THEN
                IF FDV_Pos_Div_Feedback AND NOT FDV_Pos_Fwd_Feedback THEN
                    State := 2;
                    TestTimer(IN:=FALSE, PT:=T#3S);
                ELSE
                    SelfTestFailed := TRUE;
                    State := 99; // Fault
                END_IF;
            END_IF;

        2: // Self-Test: Command Forward
            FDV_Fwd_Cmd := TRUE;
            FDV_Div_Cmd := FALSE;
            TestTimer(IN:=TRUE, PT:=T#3S);
            IF TestTimer.Q THEN
                IF FDV_Pos_Fwd_Feedback AND NOT FDV_Pos_Div_Feedback THEN
                    State := 3;
                    SystemReady := TRUE;
                    FDV_Fwd_Cmd := FALSE;
                    FDV_Div_Cmd := TRUE; // Return to safe state
                ELSE
                    SelfTestFailed := TRUE;
                    State := 99;
                END_IF;
            END_IF;

        3: // Run Mode
            PID_Inst(
                sMode := 3,
                Setpoint := 72.0,
                Input := ActiveTemp,
                Output => Heater_Out
            );

            HoldTimer(IN := (ActiveTemp >= 72.0), PT := T#15S);

            IF HoldTimer.Q THEN
                FDV_Fwd_Cmd := TRUE;
                FDV_Div_Cmd := FALSE;
            ELSE
                FDV_Fwd_Cmd := FALSE;
                FDV_Div_Cmd := TRUE;
            END_IF;

        99: // Fault state
            FDV_Fwd_Cmd := FALSE;
            FDV_Div_Cmd := TRUE;
            SystemReady := FALSE;
            Heater_Out := 0.0;
    END_CASE;
END_FUNCTION_BLOCK
```

