FUNCTION_BLOCK "BakeryOven_Base"
VERSION : 0.1
   VAR_INPUT
      Start : Bool;
      Stop : Bool;
      TempZone1_PV : Real;
      TempZone2_PV : Real;
      TempZone3_PV : Real;
      TempZone1_SP : Real;
      TempZone2_SP : Real;
      TempZone3_SP : Real;
      ConveyorSpeed_SP : Real;
      ExhaustDamper_SP : Real;
      ExhaustPressure_PV : Real;
   END_VAR
   VAR_OUTPUT
      Burner1_Cmd : Bool;
      Burner2_Cmd : Bool;
      Burner3_Cmd : Bool;
      ConveyorSpeed_Cmd : Real;
      ExhaustDamper_Pos : Real;
   END_VAR
   VAR
      Running : Bool;
      PID_Damper : "PID_Compact";
   END_VAR

BEGIN
   // System Start/Stop Logic
   IF #Start AND NOT #Stop THEN
       #Running := TRUE;
   ELSIF #Stop THEN
       #Running := FALSE;
   END_IF;

   IF #Running THEN
       // Multi-zone burner temperature profiling (Hysteresis Control)
       #Burner1_Cmd := (#TempZone1_PV < (#TempZone1_SP - 2.0));
       #Burner2_Cmd := (#TempZone2_PV < (#TempZone2_SP - 2.0));
       #Burner3_Cmd := (#TempZone3_PV < (#TempZone3_SP - 2.0));

       // Conveyor speed synchronization
       #ConveyorSpeed_Cmd := #ConveyorSpeed_SP;

       // Exhaust damper PID control
       #PID_Damper(
           Setpoint := #ExhaustDamper_SP,
           Input := #ExhaustPressure_PV,
           Output => #ExhaustDamper_Pos
       );
   ELSE
       // Safe state when stopped
       #Burner1_Cmd := FALSE;
       #Burner2_Cmd := FALSE;
       #Burner3_Cmd := FALSE;
       #ConveyorSpeed_Cmd := 0.0;
       #ExhaustDamper_Pos := 0.0;
   END_IF;
END_FUNCTION_BLOCK
