```pascal
FUNCTION_BLOCK "BakeryOven_Secure"
VERSION : 0.3
   VAR_INPUT
      UserRole : Int; // 0=Operator, 1=Supervisor, 2=Admin
      Req_ParamChange : Bool;
      New_Temp_SP : Real;

      Temp1_Primary_PV : Real;
      Temp1_Primary_Err : Bool;
      Temp1_Secondary_PV : Real;
      Temp1_Secondary_Err : Bool;

      SCADA_Heartbeat : Bool;
   END_VAR
   VAR_OUTPUT
      Active_Temp_PV : Real;
      Sensor_Failover_Active : Bool;
      SCADA_Comms_Loss : Bool;
      Access_Denied : Bool;
   END_VAR
   VAR
      Current_Temp_SP : Real;
      Heartbeat_Timer : TON_TIME;
      Last_Heartbeat : Bool;
   END_VAR

BEGIN
   // IEC 62443 Role-Based Access Control (RBAC)
   IF #Req_ParamChange THEN
       IF #UserRole >= 1 THEN // Requires Supervisor or Admin
           #Current_Temp_SP := #New_Temp_SP;
           #Access_Denied := FALSE;
       ELSE
           #Access_Denied := TRUE;
