PROGRAM MAIN
VAR
    // State Machine
    Step: INT := 0;

    // Torque Tool
    TorqueTarget: REAL := 15.5; // Nm
    TorqueActual: REAL;
    TorqueToolStart AT %Q*: BOOL;
    TorqueToolDone AT %I*: BOOL;
    TorqueToolOk AT %I*: BOOL;

    // IR Testing
    IRTestStart AT %Q*: BOOL;
    IRTestDone AT %I*: BOOL;
    IRTestValue AT %I*: REAL; // mOhm
    IRTargetMax: REAL := 2.5; 

    // Thermal Imaging
    ThermalTrigger AT %Q*: BOOL;
    ThermalDone AT %I*: BOOL;
    ThermalPass AT %I*: BOOL;

    // Station Status
    StationReady: BOOL := TRUE;
    PackAssembled: BOOL := FALSE;
    PackFailed: BOOL := FALSE;
END_VAR

CASE Step OF
    0: // Wait for start
        IF StationReady THEN
            Step := 10;
        END_IF

    10: // Torque fastening
        TorqueToolStart := TRUE;
        IF TorqueToolDone THEN
            TorqueToolStart := FALSE;
            IF TorqueToolOk THEN
                Step := 20;
            ELSE
                Step := 999;
            END_IF
        END_IF

    20: // IR Testing
        IRTestStart := TRUE;
        IF IRTestDone THEN
            IRTestStart := FALSE;
            IF IRTestValue <= IRTargetMax THEN
                Step := 30;
            ELSE
                Step := 999;
            END_IF
        END_IF

    30: // Thermal Imaging
        ThermalTrigger := TRUE;
        IF ThermalDone THEN
            ThermalTrigger := FALSE;
            IF ThermalPass THEN
                Step := 100;
            ELSE
                Step := 999;
            END_IF
        END_IF

    100: // Success
        PackAssembled := TRUE;
        StationReady := FALSE;

    999: // Fail
        PackFailed := TRUE;
        StationReady := FALSE;
END_CASE
