PROGRAM MAIN
VAR
    Step: INT := -100; // Start in Self-Test Phase

    // HIL Digital Twin Sync
    HilExpectedArgonFlow: REAL;
    HilExpectedIRValue: REAL;
    HilSyncDeviationAlert: BOOL;

    // Sensor Drift Tracking
    ArgonFlowSensor: REAL;
    IRTestValue: REAL;
    ArgonDriftIntegral: REAL := 0.0;
    IRDriftIntegral: REAL := 0.0;

    // Self-Test Fault Injection
    InjectFaultMode: BOOL := FALSE;
    SelfTestPassed: BOOL := FALSE;
    SelfTestPhase: INT := 0;

    // Security & Redundancy
    IsActivePLC: BOOL := TRUE;
    SystemLocked: BOOL := FALSE;
    AuditLogMsg: STRING;

    // Process Data
    TorqueToolStart: BOOL;
    TorqueToolDone: BOOL;
    TorqueToolOk: BOOL;
    WeldStart: BOOL;
    WeldDone: BOOL;
    MeltPoolOk: BOOL;
    ArgonFlowValve: BOOL;
    IRTestStart: BOOL;
    IRTestDone: BOOL;
    ThermalTrigger: BOOL;
    ThermalDone: BOOL;
    ThermalPass: BOOL;
    ErrorCode: DWORD;
END_VAR

// Digital Twin Drift Detection
IF ArgonFlowValve THEN
    ArgonDriftIntegral := ArgonDriftIntegral + ABS(ArgonFlowSensor - HilExpectedArgonFlow) * 0.01;
END_IF
IF ArgonDriftIntegral > 50.0 THEN HilSyncDeviationAlert := TRUE; END_IF

// Main Logic
IF IsActivePLC AND NOT SystemLocked THEN
    CASE Step OF
        -100: // Self-Test: Inject Fault
            InjectFaultMode := TRUE;
            ErrorCode := 0;
            Step := -90;

        -90: // Verify Fault Trap
            IF InjectFaultMode THEN
                // Simulate fault
                ErrorCode := 16#FFFF;
                Step := -80;
            END_IF

        -80: // Check Alarm Response
            IF ErrorCode = 16#FFFF THEN
                InjectFaultMode := FALSE;
                ErrorCode := 0;
                SelfTestPassed := TRUE;
                Step := 0;
            ELSE
                Step := 999; // Self-test failed
            END_IF

        0: 
            IF SelfTestPassed THEN Step := 10; END_IF

        10: // Torque
            TorqueToolStart := TRUE;
            IF TorqueToolDone THEN
                TorqueToolStart := FALSE;
                IF TorqueToolOk THEN Step := 20; ELSE ErrorCode := 16#E001; Step := 999; END_IF
            END_IF

        20: // Weld & HIL Compare
            ArgonFlowValve := TRUE;
            IF ArgonFlowSensor > 12.0 AND NOT HilSyncDeviationAlert THEN
                WeldStart := TRUE;
                IF WeldDone THEN
                    WeldStart := FALSE;
                    ArgonFlowValve := FALSE;
                    IF MeltPoolOk THEN Step := 30; ELSE ErrorCode := 16#E002; Step := 999; END_IF
                END_IF
            ELSIF HilSyncDeviationAlert THEN
                ErrorCode := 16#D001; // Drift error
                Step := 999;
            END_IF

        30: // IR Test & HIL Compare
            IRTestStart := TRUE;
            IF IRTestDone THEN
                IRTestStart := FALSE;
                IRDriftIntegral := ABS(IRTestValue - HilExpectedIRValue);
                IF IRDriftIntegral > 1.0 THEN HilSyncDeviationAlert := TRUE; END_IF

                IF IRTestValue <= 2.5 AND NOT HilSyncDeviationAlert THEN 
                    Step := 40; 
                ELSE 
                    ErrorCode := 16#E003; 
                    Step := 999; 
                END_IF
            END_IF

        40: // Thermal
            ThermalTrigger := TRUE;
            IF ThermalDone THEN
                ThermalTrigger := FALSE;
                IF ThermalPass THEN Step := 100; ELSE ErrorCode := 16#E004; Step := 999; END_IF
            END_IF

        100: // Done
            ErrorCode := 0;

        999: // Fault
            AuditLogMsg := 'Assembly or Test Failed';
            TorqueToolStart := FALSE;
            WeldStart := FALSE;
            ArgonFlowValve := FALSE;
            IRTestStart := FALSE;
            ThermalTrigger := FALSE;
    END_CASE
END_IF
