FUNCTION_BLOCK "CNCMachiningCell"
VERSION : 0.1
   VAR_INPUT 
      StartCycle : Bool;
      SpindleLoad : Real; // Current spindle load in %
      SwarfLevel : Real; // Swarf accumulation level in %
   END_VAR

   VAR_OUTPUT 
      ToolOffset : Real; // Tool wear compensation value
      ExtractSwarf : Bool; // Activate swarf extraction
      AlarmSpindleOverload : Bool;
   END_VAR

   VAR 
      CycleActive : Bool;
      ToolWearAccumulator : Real;
   END_VAR

   VAR CONSTANT 
      MAX_SPINDLE_LOAD : Real := 85.0;
      SWARF_EXTRACT_THRESHOLD : Real := 75.0;
      WEAR_FACTOR : Real := 0.001;
   END_VAR

BEGIN
   // Spindle Load Monitoring
   IF SpindleLoad > MAX_SPINDLE_LOAD THEN
      AlarmSpindleOverload := TRUE;
   ELSE
      AlarmSpindleOverload := FALSE;
   END_IF;

   // Automated Tool Wear Compensation
   IF StartCycle AND NOT AlarmSpindleOverload THEN
      CycleActive := TRUE;
      ToolWearAccumulator := ToolWearAccumulator + (SpindleLoad * WEAR_FACTOR);
      ToolOffset := ToolWearAccumulator;
   ELSE
      CycleActive := FALSE;
   END_IF;

   // Swarf Extraction Cycle
   IF SwarfLevel > SWARF_EXTRACT_THRESHOLD THEN
      ExtractSwarf := TRUE;
   ELSE
      ExtractSwarf := FALSE;
   END_IF;
END_FUNCTION_BLOCK
