FUNCTION_BLOCK "CNCMachiningCell_M3"
VERSION : 0.1
   VAR_INPUT 
      StartCycle : Bool;
      UserRole : Int; // 0=Guest, 1=Op, 2=Admin (IEC 62443)
      IsPrimaryPLC : Bool; // Failover status
      SyncData_In : Real;
   END_VAR

   VAR_OUTPUT 
      Alarms : Array[0..15] of Bool;
      SyncData_Out : Real;
   END_VAR

   VAR_IN_OUT 
      ScadaData : "SCADA_Interface"; // OPC UA Interface
   END_VAR

   VAR 
      CycleActive : Bool;
      ToolWearAccumulator : Real;
   END_VAR

BEGIN
   // Redundancy Failover
   IF NOT IsPrimaryPLC THEN
      ToolWearAccumulator := SyncData_In; // Sync from primary
      RETURN; // Standby mode, skip logic
   END_IF;

   // Cybersecurity Access Control
   IF UserRole < 1 THEN
      Alarms[3] := TRUE; // Unauthorized access attempt
      CycleActive := FALSE;
   ELSE
      Alarms[3] := FALSE;
      IF StartCycle THEN CycleActive := TRUE; ELSE CycleActive := FALSE; END_IF;
   END_IF;

   // Process logic
   IF CycleActive THEN
      ToolWearAccumulator := ToolWearAccumulator + 0.01;
   END_IF;
   SyncData_Out := ToolWearAccumulator;

   // SCADA OPC UA Mapping
   ScadaData.ToolOffset := ToolWearAccumulator;
   ScadaData.SysState := 1;
END_FUNCTION_BLOCK
