FUNCTION_BLOCK "DistrictHeatingSubstation_M1"
VAR_INPUT
    OutdoorTemp : REAL;
    SupplyTemp : REAL;
    SupplyPress, ReturnPress : REAL;
    DiffPressSP : REAL;
    TES_TopTemp, TES_BottomTemp : REAL;
    LoadDemand : REAL;
END_VAR
VAR_OUTPUT
    ValveCmd_HX1, ValveCmd_HX2 : REAL;
    PumpSpeed : REAL;
    TES_ChargeCmd : BOOL;
END_VAR
VAR
    PID_Temp_HX1, PID_Temp_HX2 : "PID_Compact";
    PID_Press : "PID_Compact";
    TargetSupplyTemp, DiffPress : REAL;
    TES_SOC : REAL;
END_VAR
BEGIN
    // Weather Compensation
    TargetSupplyTemp := LIMIT(MN:=20.0, IN:=(95.0 - ((OutdoorTemp + 15.0) * (75.0 / 35.0))), MX:=95.0);

    // TES State-of-Charge Management
    TES_SOC := (TES_TopTemp + TES_BottomTemp) / 2.0; // Simplified SOC
    TES_ChargeCmd := (TES_SOC < 50.0) AND (LoadDemand < 60.0);

    // Cascade Control for Multiple HX
    IF LoadDemand < 50.0 THEN
        PID_Temp_HX1(Setpoint := TargetSupplyTemp, ProcessValue := SupplyTemp, Output => ValveCmd_HX1);
        ValveCmd_HX2 := 0.0;
    ELSE
        PID_Temp_HX1(Setpoint := TargetSupplyTemp, ProcessValue := SupplyTemp, Output => ValveCmd_HX1);
        PID_Temp_HX2(Setpoint := TargetSupplyTemp, ProcessValue := SupplyTemp, Output => ValveCmd_HX2);
    END_IF;

    // Diff Pressure Control
    DiffPress := SupplyPress - ReturnPress;
    PID_Press(Setpoint := DiffPressSP, ProcessValue := DiffPress, Output => PumpSpeed);
END_FUNCTION_BLOCK
