FUNCTION_BLOCK "DistrictHeatingSubstation_M3"
VAR_INPUT
    OutdoorTemp, SupplyTemp, SupplyPress, ReturnPress, DiffPressSP : REAL;
    TES_TopTemp, TES_BottomTemp, LoadDemand : REAL;
    VFD1_StatusWord, VFD2_StatusWord : WORD;
    OPC_UA_Data : "SCADA_Data";
END_VAR
VAR_OUTPUT
    ValveCmd_HX1, ValveCmd_HX2 : REAL;
    VFD1_Speed, VFD2_Speed : REAL;
    VFD1_ControlWord, VFD2_ControlWord : WORD;
END_VAR
VAR
    PID_Press : "PID_Compact";
    DiffPress, TargetSupplyTemp : REAL;
    ActivePump : INT := 1;
    VFD1_Fault, VFD2_Fault : BOOL;
END_VAR
BEGIN
    // IEC 62443 Security: Input Validation & RBAC
    IF OPC_UA_Data.UserRole < 1 THEN
        RETURN; // Unauthorized access ignored
    END_IF;
    DiffPress := LIMIT(MN:=0.0, IN:=SupplyPress - ReturnPress, MX:=10.0);

    // Core Control
    TargetSupplyTemp := LIMIT(MN:=20.0, IN:=(95.0 - ((OutdoorTemp + 15.0) * (75.0 / 35.0))), MX:=95.0);
    PID_Press(Setpoint:=DiffPressSP, ProcessValue:=DiffPress);

    // Pump Failover Logic (Duty/Standby)
    VFD1_Fault := (VFD1_StatusWord AND 16#0008) <> 0;
    VFD2_Fault := (VFD2_StatusWord AND 16#0008) <> 0;

    IF ActivePump = 1 AND VFD1_Fault THEN
        ActivePump := 2;
    ELSIF ActivePump = 2 AND VFD2_Fault THEN
        ActivePump := 1;
    END_IF;

    IF ActivePump = 1 AND NOT VFD1_Fault THEN
        VFD1_Speed := PID_Press.Output;
        VFD1_ControlWord := 16#047F;
        VFD2_Speed := 0.0;
        VFD2_ControlWord := 16#047E;
    ELSIF ActivePump = 2 AND NOT VFD2_Fault THEN
        VFD2_Speed := PID_Press.Output;
        VFD2_ControlWord := 16#047F;
        VFD1_Speed := 0.0;
        VFD1_ControlWord := 16#047E;
    ELSE
        VFD1_Speed := 0.0; VFD2_Speed := 0.0;
    END_IF;

    // SCADA Update
    OPC_UA_Data.PumpSpeed := PID_Press.Output;
    OPC_UA_Data.SupplyTemp := SupplyTemp;
END_FUNCTION_BLOCK
