FUNCTION_BLOCK "DistrictHeatingSubstation_M4"
VAR_INPUT
    OutdoorTemp, SupplyTemp1, SupplyTemp2 : REAL;
    SupplyPress, ReturnPress, DiffPressSP : REAL;
    HIL_Mode : BOOL;
    HIL_SupplyTemp, HIL_DiffPress : REAL;
END_VAR
VAR_OUTPUT
    ValveCmd_HX1 : REAL;
    PumpSpeed : REAL;
    SystemState : INT; // 0:Init, 1:SelfTest, 2:Run, 3:Fault
    DriftAlarm : BOOL;
END_VAR
VAR
    PID_Press : "PID_Compact";
    ActiveSupplyTemp, DiffPress : REAL;
    TestTimer : TON;
END_VAR
BEGIN
    // HIL Digital Twin Sync
    IF HIL_Mode THEN
        ActiveSupplyTemp := HIL_SupplyTemp;
        DiffPress := HIL_DiffPress;
    ELSE
        // Sensor Drift Detection (Redundant Sensors)
        IF ABS(SupplyTemp1 - SupplyTemp2) > 2.0 THEN
            DriftAlarm := TRUE;
            SystemState := 3;
        ELSE
            DriftAlarm := FALSE;
            ActiveSupplyTemp := (SupplyTemp1 + SupplyTemp2) / 2.0;
            DiffPress := SupplyPress - ReturnPress;
        END_IF;
    END_IF;

    // Automated Self-Test Routine
    CASE SystemState OF
        0: // Init
            ValveCmd_HX1 := 0.0;
            PumpSpeed := 0.0;
            SystemState := 1;
        1: // Self-Test
            TestTimer(IN:=TRUE, PT:=T#5s);
            ValveCmd_HX1 := 50.0; // Stroke valve to 50%
            PumpSpeed := 20.0; // Bump pump
            IF TestTimer.Q THEN
                TestTimer(IN:=FALSE);
                SystemState := 2; // Move to Run
            END_IF;
        2: // Run
            // Control Logic
            PID_Press(Setpoint:=DiffPressSP, ProcessValue:=DiffPress, Output=>PumpSpeed);
            ValveCmd_HX1 := LIMIT(MN:=0.0, IN:=(95.0 - ActiveSupplyTemp)*2.0, MX:=100.0);
        3: // Fault
            ValveCmd_HX1 := 0.0;
            PumpSpeed := 0.0;
    END_CASE;
END_FUNCTION_BLOCK
