    bEssChargeReq : BOOL;
    bEssDischargeReq : BOOL;
    fEssPowerLimit : REAL := 500.0;
END_VAR

// Synchronization Logic
bSyncOK := (ABS(fGridVoltage - fMicrogridVoltage) < 5.0) AND (ABS(fGridFreq - fMicrogridFreq) < 0.2);

// Island Mode Transition
IF bIslandModeReq AND bGridConnected AND bSyncOK THEN
    bGridConnected := FALSE;
ELSIF NOT bIslandModeReq AND NOT bGridConnected AND bSyncOK THEN
    bGridConnected := TRUE;
END_IF

// ESS SOC Management
IF fEssSOC < 20.0 THEN
    bEssDischargeReq := FALSE;
    bEssChargeReq := bGridConnected;
ELSIF fEssSOC > 90.0 THEN
    bEssChargeReq := FALSE;
    bEssDischargeReq := NOT bGridConnected;
ELSE
    bEssChargeReq := (fAvailableGen > fTotalLoad) AND bGridConnected;
    bEssDischargeReq := (fTotalLoad > fAvailableGen) AND NOT bGridConnected;
END_IF

// Load Shedding Logic with ESS Integration
IF NOT bGridConnected THEN
    IF (fTotalLoad > fAvailableGen + (SEL(bEssDischargeReq, 0.0, fEssPowerLimit))) THEN
        bShedLoadTier1 := TRUE;
        bShedLoadTier2 := (fTotalLoad > ((fAvailableGen + fEssPowerLimit) * 1.2));
    ELSE
        bShedLoadTier1 := FALSE;
        bShedLoadTier2 := FALSE;
    END_IF
ELSE
    bShedLoadTier1 := FALSE;
    bShedLoadTier2 := FALSE;
END_IF
