    IF (fTotalLoad > fAvailableGen + (SEL(bEssDischargeReq, 0.0, fEssPowerLimit))) THEN
        bShedLoadTier1 := TRUE;
        bShedLoadTier2 := (fTotalLoad > ((fAvailableGen + fEssPowerLimit) * 1.2));
