        fGridVoltage := (fGridVoltage1 + fGridVoltage2) / 2.0; // Average value

        // Hardware-In-the-Loop Mode Override
        IF bHilModeActive THEN
            // Bypass physical limits for simulation
            fGridVoltage := 400.0;
        END_IF

        // Security
        IF (sReceivedMAC <> sExpectedMAC) THEN
            bScadaOverride := FALSE;
