        bShedLoadTier1 := TRUE;
        bShedLoadTier2 := TRUE;
        // Require manual reset from SCADA or physical input
        IF bScadaOverride AND NOT bSensorDriftFault THEN
            eState := STATE_INIT;
        END_IF
END_CASE
