FUNCTION_BLOCK "LNG_Regasification_M1"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.1
VAR_INPUT
    Start_Terminal : Bool;
    LNG_Temp : Real;
    BOG_Pressure : Real;
    CoolDown_Target_Rate : Real;
    Seawater_Inlet_Temp : Real; // Deg C
END_VAR
VAR_OUTPUT
    Vaporizer_Valve : Real;
    Compressor_1_Run : Bool;
    Compressor_2_Run : Bool;
    Seawater_Pump_Speed : Real; // %
    System_Ready : Bool;
END_VAR
VAR
    Actual_CoolDown_Rate : Real;
    Prev_Temp : Real;
END_VAR
BEGIN
    // Rapid cool down limits
    Actual_CoolDown_Rate := Prev_Temp - LNG_Temp;
    IF Start_Terminal AND (Actual_CoolDown_Rate < CoolDown_Target_Rate) THEN
        Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve + 1.0, MX:=100.0);
    ELSIF Actual_CoolDown_Rate >= CoolDown_Target_Rate THEN
        Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve - 2.0, MX:=100.0);
    END_IF;
    Prev_Temp := LNG_Temp;

    // Closed-loop Seawater Heating Sub-System
    // Ensure seawater does not freeze in the heat exchanger
    IF Seawater_Inlet_Temp < 5.0 THEN
        Seawater_Pump_Speed := 100.0; // Max circulation to prevent freezing
    ELSIF Seawater_Inlet_Temp >= 5.0 AND Seawater_Inlet_Temp < 15.0 THEN
        Seawater_Pump_Speed := 75.0;
