FUNCTION_BLOCK "LNG_Regasification_M2"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.2
VAR_INPUT
    Start_Terminal : Bool;
    LNG_Temp : Real;
    BOG_Pressure : Real;
    CoolDown_Target_Rate : Real;
    Seawater_Inlet_Temp : Real;
    PN_Device_Status : Word; // Profinet diagnostic word
END_VAR
VAR_OUTPUT
    Vaporizer_Valve : Real;
    Compressor_1_Run : Bool;
    Compressor_2_Run : Bool;
    Seawater_Pump_Speed : Real;
    System_Ready : Bool;
    Fault_Code : Int;
END_VAR
VAR
    Actual_CoolDown_Rate : Real;
    Prev_Temp : Real;
    Comms_OK : Bool;
END_VAR
BEGIN
    // Profinet Industrial Communication Diagnostics
    Comms_OK := (PN_Device_Status AND 16#0001) = 16#0001; // Bit 0: IO Data Valid
    IF NOT Comms_OK THEN
        Fault_Code := 1001; // PN Comms Lost
        Vaporizer_Valve := 0.0;
        Compressor_1_Run := FALSE;
        Compressor_2_Run := FALSE;
        Seawater_Pump_Speed := 100.0; // Keep heating on safe mode
        RETURN;
    END_IF;

    // Advanced Fault Diagnostics for BOG
    IF BOG_Pressure > 4.0 THEN
        Fault_Code := 2001; // BOG Overpressure Trip
        Vaporizer_Valve := 0.0;
    ELSE
        Fault_Code := 0;
    END_IF;

    // Rapid cool down limits
    Actual_CoolDown_Rate := Prev_Temp - LNG_Temp;
    IF Start_Terminal AND Fault_Code = 0 THEN
        IF Actual_CoolDown_Rate < CoolDown_Target_Rate THEN
            Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve + 1.0, MX:=100.0);
        ELSE
            Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve - 2.0, MX:=100.0);
        END_IF;
    END_IF;
    Prev_Temp := LNG_Temp;

    // Closed-loop Seawater Heating Sub-System
    IF Seawater_Inlet_Temp < 5.0 THEN
        Seawater_Pump_Speed := 100.0;
    ELSE
        Seawater_Pump_Speed := 50.0;
    END_IF;

    // BOG Compressor Sequencing
    Compressor_1_Run := (BOG_Pressure > 1.5) AND (Fault_Code = 0);
    Compressor_2_Run := (BOG_Pressure > 2.0) AND (Fault_Code = 0);

    System_Ready := Start_Terminal AND Comms_OK AND (Fault_Code = 0);
END_FUNCTION_BLOCK
