    // PLC Failover Logic
    IF NOT PLC_Is_Primary THEN
        // Standby mode - simply track variables
        SCADA_Telemetry.Status_Word := 16#0002; // Standby
        RETURN;
    END_IF;

    // IEC 62443 Cybersecurity Check
    Auth_OK := (User_Role = 1) OR (User_Role = 2);
    IF NOT Auth_OK THEN
        Fault_Code := 9001; // Security Violation
        Vaporizer_Valve := 0.0;
        Compressor_Run[1] := FALSE;
        Compressor_Run[2] := FALSE;
        RETURN;
    END_IF;

    // SCADA Integration & Profinet Comms
    Comms_OK := (PN_Device_Status AND 16#0001) = 16#0001;
    IF NOT Comms_OK OR NOT SCADA_Heartbeat THEN
        Fault_Code := 1001; // Comms or SCADA Loss
        Vaporizer_Valve := 0.0;
    ELSE
        Fault_Code := 0;
    END_IF;

    // BOG & Vaporizer Logic
    IF Fault_Code = 0 THEN
        Actual_CoolDown_Rate := Prev_Temp - LNG_Temp;
        IF Actual_CoolDown_Rate < 5.0 THEN
            Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve + 1.0, MX:=100.0);
        ELSE
            Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve - 2.0, MX:=100.0);
        END_IF;

        Seawater_Pump_Speed := SEL(G := Seawater_Inlet_Temp < 5.0, IN0 := 50.0, IN1 := 100.0);
        Compressor_Run[1] := (BOG_Pressure > 1.5);
        Compressor_Run[2] := (BOG_Pressure > 2.0);
    END_IF;
    Prev_Temp := LNG_Temp;

    // Update SCADA Telemetry
    SCADA_Telemetry.Status_Word := 16#0001; // Primary Active
    SCADA_Telemetry.Active_Alarms := Fault_Code;
END_FUNCTION_BLOCK
