FUNCTION_BLOCK "LNG_Regasification_M4"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.4
VAR_INPUT
    Start_Terminal : Bool;
    LNG_Temp_A : Real; // Redundant sensor A
    LNG_Temp_B : Real; // Redundant sensor B
    BOG_Pressure : Real;
    Seawater_Inlet_Temp : Real;
    PN_Device_Status : Word;
    User_Role : Int;
    PLC_Is_Primary : Bool;
    HIL_Mode_Active : Bool; // Digital Twin active
END_VAR
VAR_OUTPUT
    Vaporizer_Valve : Real;
    Compressor_Run : Array[1..2] of Bool;
    Fault_Code : Int;
    Self_Test_Passed : Bool;
    HIL_Telemetry_Sync : Array[1..10] of Real;
END_VAR
VAR
    State : Int; // 0=Init, 1=SelfTest, 2=Run, 3=Fault
    Test_Timer : TON_TIME;
    Drift_Detected : Bool;
    Selected_LNG_Temp : Real;
    Prev_Temp : Real;
END_VAR
BEGIN
    // Failover & Cybersecurity
    IF NOT PLC_Is_Primary OR User_Role < 1 THEN
        State := 0;
        RETURN;
    END_IF;

    // Sensor Drift Detection (Adversarial/Failure condition)
    Drift_Detected := ABS(LNG_Temp_A - LNG_Temp_B) > 2.5;
    IF Drift_Detected THEN
        Fault_Code := 8001; // Sensor Drift Alarm
        State := 3;
    ELSE
        Selected_LNG_Temp := (LNG_Temp_A + LNG_Temp_B) / 2.0;
    END_IF;

    // State Machine
    CASE State OF
        0: // Init
            IF Start_Terminal AND NOT Drift_Detected THEN
                State := 1;
            END_IF;
        1: // Mandatory Pre-Start Self-Test
            Test_Timer(IN:=TRUE, PT:=T#5s);
            IF Test_Timer.Q THEN
                Self_Test_Passed := TRUE;
                State := 2;
                Test_Timer(IN:=FALSE, PT:=T#5s);
            END_IF;
        2: // Run
            IF NOT Self_Test_Passed THEN State := 3; END_IF;

            // Core Process Logic
            IF (Prev_Temp - Selected_LNG_Temp) < 5.0 THEN
                Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve + 1.0, MX:=100.0);
            ELSE
                Vaporizer_Valve := LIMIT(MN:=0.0, IN:=Vaporizer_Valve - 2.0, MX:=100.0);
            END_IF;
            Prev_Temp := Selected_LNG_Temp;

            Compressor_Run[1] := (BOG_Pressure > 1.5);
            Compressor_Run[2] := (BOG_Pressure > 2.0);

            // HIL Digital Twin State Synchronization
            IF HIL_Mode_Active THEN
                HIL_Telemetry_Sync[1] := Vaporizer_Valve;
                HIL_Telemetry_Sync[2] := Selected_LNG_Temp;
                HIL_Telemetry_Sync[3] := BOG_Pressure;
            END_IF;
        3: // Fault
            Vaporizer_Valve := 0.0;
            Compressor_Run[1] := FALSE;
            Compressor_Run[2] := FALSE;
            Self_Test_Passed := FALSE;
            IF NOT Start_Terminal THEN State := 0; END_IF;
    END_CASE;
END_FUNCTION_BLOCK
