   END_IF;

   // 2. Redundant Sensor Failover & Validation
   IF ABS(#doLevel_PV1 - #doLevel_PV2) > #SENSOR_DEV_MAX THEN
       #systemFault := TRUE; #faultCode := 16#4001; // DO Sensor Discrepancy
   ELSE
       #active_doPV := (#doLevel_PV1 + #doLevel_PV2) / 2.0; // Average valid readings
   END_IF;

   IF ABS(#pH_PV1 - #pH_PV2) > 0.5 THEN
       #systemFault := TRUE; #faultCode := 16#4002; // pH Sensor Discrepancy
   ELSE
       #active_pHPV := #pH_PV1; // Primary wins if valid
   END_IF;

   #active_tempPV := #temp_PV1; // Simplify

   // 3. Process Control
   IF #authValid AND #startProcess AND NOT #systemFault THEN #processActive := TRUE; END_IF;
   IF NOT #authValid OR #stopProcess OR #systemFault THEN #processActive := FALSE; END_IF;

   IF NOT #processActive THEN
       #agitatorSpeed_CV := 0.0;
       #acidPumpCommand := FALSE; #basePumpCommand := FALSE; #antifoamPumpCommand := FALSE;
       #coolingValve_CV := 0.0; #heatingValve_CV := 0.0;
       RETURN;
   END_IF;

   #doPID(Setpoint:=#doLevel_SP, Input:=#active_doPV);
   #agitatorSpeed_CV := #doPID.Output;

   #acidPumpCommand := (#active_pHPV > (#pH_SP + 0.2));
   #basePumpCommand := (#active_pHPV < (#pH_SP - 0.2));

   #antifoamTimer(IN := #foamDetected, PT := T#5s);
   #antifoamPumpCommand := #antifoamTimer.Q;

   #tempPID(Setpoint:=#temp_SP, Input:=#active_tempPV);
   IF #tempPID.Output > 0.0 THEN
       #heatingValve_CV := #tempPID.Output; #coolingValve_CV := 0.0;
   ELSIF #tempPID.Output < 0.0 THEN
       #heatingValve_CV := 0.0; #coolingValve_CV := ABS(#tempPID.Output);
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "BioreactorControl_Mut4"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      // Core
      startProcess : Bool; stopProcess : Bool; startSelfTest : Bool; hilSyncMode : Bool;
      doLevel_PV1 : Real; doLevel_PV2 : Real; doLevel_SP : Real;
      pH_PV1 : Real; pH_PV2 : Real; pH_SP : Real;
      temp_PV1 : Real; temp_PV2 : Real; temp_SP : Real;
      foamDetected : Bool; profinetNodeStatus : Word;
      scadaControlReq : Bool; scadaToken : DWord;
      // HIL Twin Inputs
      hil_do_PV : Real; hil_pH_PV : Real; hil_temp_PV : Real;
   END_VAR
   VAR_OUTPUT
      agitatorSpeed_CV : Real; acidPumpCommand : Bool; basePumpCommand : Bool; antifoamPumpCommand : Bool;
      coolingValve_CV : Real; heatingValve_CV : Real;
      systemFault : Bool; faultCode : Word; scadaAck : Bool;
      selfTestComplete : Bool; hilSyncActive : Bool; sensorDriftAlarm : Bool;
   END_VAR
   VAR_IN_OUT
      doPID : "PID_Compact"; tempPID : "PID_Compact";
   END_VAR
   VAR
      processActive : Bool; selfTestStep : Int; testTimer : TON; antifoamTimer : TON;
      active_doPV : Real; active_pHPV : Real; active_tempPV : Real;
      driftHistory_pH : Array[1..10] of Real; driftIdx : Int := 1; pH_avg : Real; i : Int;
   END_VAR
   CONST VALID_TOKEN : DWord := 16#A5A5_5A5A; END_CONST

BEGIN
   // 1. Cybersecurity Handshake
   #scadaAck := (#scadaControlReq AND (#scadaToken = #VALID_TOKEN));

   // 2. Digital Twin (HIL) Sync
   #hilSyncActive := #hilSyncMode;
   IF #hilSyncActive THEN
       #active_doPV := #hil_do_PV;
       #active_pHPV := #hil_pH_PV;
       #active_tempPV := #hil_temp_PV;
   ELSE
       // 3. Sensor Failover & Drift Detection (Moving Average for pH)
       #active_doPV := (#doLevel_PV1 + #doLevel_PV2) / 2.0;
       #active_pHPV := (#pH_PV1 + #pH_PV2) / 2.0;
       #active_tempPV := (#temp_PV1 + #temp_PV2) / 2.0;

       #driftHistory_pH[#driftIdx] := #active_pHPV;
       #driftIdx := #driftIdx + 1;
       IF #driftIdx > 10 THEN #driftIdx := 1; END_IF;

       #pH_avg := 0.0;
       FOR #i := 1 TO 10 DO #pH_avg := #pH_avg + #driftHistory_pH[#i]; END_FOR;
       #pH_avg := #pH_avg / 10.0;

       IF ABS(#active_pHPV - #pH_avg) > 1.5 THEN #sensorDriftAlarm := TRUE; ELSE #sensorDriftAlarm := FALSE; END_IF;
   END_IF;

   // 4. Pre-flight Self-Test Routine
   IF #startSelfTest AND NOT #processActive THEN
       #testTimer(IN:=TRUE, PT:=T#10s);
       #selfTestStep := REAL_TO_INT(TIME_TO_REAL(#testTimer.ET) / 2000.0); // 2 sec per step

       CASE #selfTestStep OF
           0: #agitatorSpeed_CV := 10.0; #acidPumpCommand := FALSE; // Test Agitator
           1: #agitatorSpeed_CV := 0.0; #acidPumpCommand := TRUE;   // Test Acid
           2: #acidPumpCommand := FALSE; #basePumpCommand := TRUE;  // Test Base
           3: #basePumpCommand := FALSE; #heatingValve_CV := 50.0;  // Test Heat
           4: #heatingValve_CV := 0.0; #coolingValve_CV := 50.0;    // Test Cool
           5: 
               #coolingValve_CV := 0.0; 
               #selfTestComplete := TRUE; 
               #testTimer(IN:=FALSE, PT:=T#10s);
       END_CASE;
       RETURN;
   END_IF;
   #selfTestComplete := FALSE;

   // 5. Process Control
   IF #scadaAck AND #startProcess AND NOT #systemFault AND NOT #sensorDriftAlarm THEN #processActive := TRUE; END_IF;
   IF NOT #scadaAck OR #stopProcess OR #systemFault OR #sensorDriftAlarm THEN #processActive := FALSE; END_IF;

   IF NOT #processActive THEN
       #agitatorSpeed_CV := 0.0; #acidPumpCommand := FALSE; #basePumpCommand := FALSE; #antifoamPumpCommand := FALSE;
       #coolingValve_CV := 0.0; #heatingValve_CV := 0.0;
       RETURN;
   END_IF;

   #doPID(Setpoint:=#doLevel_SP, Input:=#active_doPV);
   #agitatorSpeed_CV := #doPID.Output;

   #acidPumpCommand := (#active_pHPV > (#pH_SP + 0.2));
   #basePumpCommand := (#active_pHPV < (#pH_SP - 0.2));

   #antifoamTimer(IN := #foamDetected, PT := T#5s);
   #antifoamPumpCommand := #antifoamTimer.Q;

   #tempPID(Setpoint:=#temp_SP, Input:=#active_tempPV);
   IF #tempPID.Output > 0.0 THEN
       #heatingValve_CV := #tempPID.Output; #coolingValve_CV := 0.0;
   ELSE
       #heatingValve_CV := 0.0; #coolingValve_CV := ABS(#tempPID.Output);
   END_IF;
END_FUNCTION_BLOCK

