PROGRAM PRG_Lyophilizer
TYPE E_UserRole : (NONE, OPERATOR, MAINTENANCE, ADMIN); END_TYPE
VAR
    eState : (IDLE, COMPRESSOR1_START, COMPRESSOR2_START, FREEZING, PRIMARY_DRYING, SECONDARY_DRYING, DEFROST, ERROR);
    eCurrentUser : E_UserRole := NONE;
    sActiveUser : STRING := '';
    bLoginOperator, bLoginMaintenance, bLoginAdmin, bLogout : BOOL;
    // OPC UA Batch Data
    stBatchData : STRUCT
        {attribute 'OPC.UA.DA' := '1'}
        sBatchID : STRING := 'BATCH_001';
        {attribute 'OPC.UA.DA' := '1'}
        fAvgVacuum : LREAL;
        {attribute 'OPC.UA.DA' := '1'}
        bProcessComplete : BOOL;
    END_STRUCT;
    // Redundancy / Failover
    bVacuumPump1, bVacuumPump2 : BOOL;
    bPump1Fault, bPump2Fault : BOOL;
    // Process variables
    fActiveVacuum, fPiraniVacuum, fCapacitanceVacuum, fShelfTemp, fCondenserTemp, fVacuumValve, fShelfHeating : LREAL;
    bComp1, bComp2, bDefrostHeater, bStartProcess, bResetFaults : BOOL;
    fbVacuumPID : FB_BasicPID;
    fbTimerProcess : TON;
END_VAR

// IEC 62443 RBAC
IF bLogout THEN eCurrentUser := NONE; bLogout := FALSE; END_IF
IF bLoginOperator THEN eCurrentUser := OPERATOR; bLoginOperator := FALSE; END_IF
IF bLoginMaintenance THEN eCurrentUser := MAINTENANCE; bLoginMaintenance := FALSE; END_IF
IF bLoginAdmin THEN eCurrentUser := ADMIN; bLoginAdmin := FALSE; END_IF

// Security check for start/reset
IF bStartProcess AND (eCurrentUser = NONE) THEN bStartProcess := FALSE; END_IF
IF bResetFaults AND (eCurrentUser <> MAINTENANCE AND eCurrentUser <> ADMIN) THEN bResetFaults := FALSE; END_IF

// Pump Failover Logic
IF eState = PRIMARY_DRYING OR eState = SECONDARY_DRYING THEN
    IF NOT bPump1Fault THEN
        bVacuumPump1 := TRUE;
        bVacuumPump2 := FALSE;
    ELSIF NOT bPump2Fault THEN
        bVacuumPump1 := FALSE;
        bVacuumPump2 := TRUE;
    ELSE
        eState := ERROR;
    END_IF
ELSE
    bVacuumPump1 := FALSE; bVacuumPump2 := FALSE;
END_IF

// Dual-Gauge Crossover
IF fPiraniVacuum < 1.0 THEN fActiveVacuum := fCapacitanceVacuum; ELSE fActiveVacuum := fPiraniVacuum; END_IF

CASE eState OF
    IDLE:
        stBatchData.bProcessComplete := FALSE;
        IF bStartProcess THEN eState := COMPRESSOR1_START; END_IF
    COMPRESSOR1_START:
        bComp1 := TRUE; eState := COMPRESSOR2_START;
    COMPRESSOR2_START:
        bComp2 := TRUE; eState := FREEZING;
    FREEZING:
        fShelfHeating := -40.0;
        IF fShelfTemp <= -35.0 AND fCondenserTemp <= -70.0 THEN eState := PRIMARY_DRYING; fbTimerProcess(IN:=FALSE); END_IF
    PRIMARY_DRYING:
        fbTimerProcess(IN:=TRUE, PT:=T#24H);
        fbVacuumPID(fSetpoint:=0.1, fActual:=fActiveVacuum, bEnable:=TRUE, fOut=>fVacuumValve);
        fShelfHeating := -20.0;
        stBatchData.fAvgVacuum := (stBatchData.fAvgVacuum + fActiveVacuum) / 2.0;
        IF fbTimerProcess.Q THEN fbTimerProcess(IN:=FALSE); eState := SECONDARY_DRYING; END_IF
    SECONDARY_DRYING:
        fbTimerProcess(IN:=TRUE, PT:=T#6H);
        fbVacuumPID(fSetpoint:=0.05, fActual:=fActiveVacuum, bEnable:=TRUE, fOut=>fVacuumValve);
        fShelfHeating := 20.0;
        IF fbTimerProcess.Q THEN eState := DEFROST; END_IF
    DEFROST:
        bDefrostHeater := TRUE;
        stBatchData.bProcessComplete := TRUE;
        eState := IDLE;
        bStartProcess := FALSE;
    ERROR:
        bComp1 := FALSE; bComp2 := FALSE; bDefrostHeater := FALSE;
        IF bResetFaults THEN eState := IDLE; bResetFaults := FALSE; END_IF
END_CASE
