PROGRAM BlisterMachineBase
VAR
    // PID for Rotary Sealing Temp
    SealTempPID : PID;
    SealTemp_PV : REAL;
    SealTemp_CV : REAL;
    SealTemp_SP : REAL := 150.0;

    // Vision Reject Sync
