FUNCTION_BLOCK "Autoclave_Control"
VERSION : 0.1
   VAR_INPUT
      Start_Cycle : Bool;
      Temp_Chamber : Real; // Chamber temperature in Celsius
      Press_Chamber : Real; // Chamber pressure in Bar
      Press_Jacket : Real; // Jacket pressure in Bar
      Door_Closed : Bool;
      Door_Locked : Bool;
   END_VAR
   VAR_OUTPUT
      Valve_Steam_In : Bool;
      Valve_Exhaust : Bool;
      Door_Lock_Cmd : Bool;
      Cycle_Complete : Bool;
      Alarm_Active : Bool;
      F0_Value : Real;
   END_VAR
   VAR
      State : Int; // 0=Idle, 1=Heat, 2=Sterilize, 3=Exhaust, 4=Complete
   END_VAR
   VAR_TEMP
      Kill_Rate : Real;
   END_VAR
   CONST
      T_REF : Real := 121.1;
      Z_VAL : Real := 10.0;
   END_CONST

BEGIN
    // Door Interlock sequence
    IF NOT Door_Closed THEN
        Door_Lock_Cmd := FALSE;
        Alarm_Active := State <> 0;
        State := 0;
    ELSE
        Door_Lock_Cmd := TRUE;
    END_IF;

    // Sterilization F0 value integration
    IF Temp_Chamber >= 115.0 THEN
        Kill_Rate := 10.0 ** ((Temp_Chamber - T_REF) / Z_VAL);
        F0_Value := F0_Value + (Kill_Rate / 60.0); // Assuming 1s execution cycle
    END_IF;

    // State Machine
    CASE State OF
        0: // Idle
            Valve_Steam_In := FALSE;
            Valve_Exhaust := FALSE;
            Cycle_Complete := FALSE;
            F0_Value := 0.0;
            IF Start_Cycle AND Door_Locked THEN
                State := 1;
            END_IF;

        1: // Heating & Jacket/Chamber Pressure Balancing
            // Modulate steam to balance pressure
            Valve_Steam_In := (Press_Chamber < Press_Jacket + 0.1);
            Valve_Exhaust := FALSE;
            IF Temp_Chamber >= 121.1 THEN
                State := 2;
            END_IF;

        2: // Sterilizing
            Valve_Steam_In := Temp_Chamber < 121.5;
            IF F0_Value >= 15.0 THEN
                State := 3;
            END_IF;

        3: // Exhaust
            Valve_Steam_In := FALSE;
            Valve_Exhaust := TRUE;
            IF Press_Chamber <= 1.05 THEN
                State := 4;
            END_IF;

        4: // Complete
            Valve_Exhaust := FALSE;
            Cycle_Complete := TRUE;
            IF NOT Start_Cycle THEN
                State := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK

