FUNCTION_BLOCK "ASRS_Base"
VAR_INPUT
    TargetX : Int;
    TargetY : Int;
    LaserX : Real;
    LaserY : Real;
    ForksRetracted : Bool;
END_VAR
VAR_OUTPUT
    RunX : Bool;
    RunY : Bool;
    ForksEnable : Bool;
END_VAR
VAR
    CoordX : Array[0..100] of Real;
    CoordY : Array[0..100] of Real;
END_VAR
