    IF ForksRetracted THEN
        RunX := ABS(CoordX[TargetX] - LaserX) > 5.0;
        RunY := ABS(CoordY[TargetY] - LaserY) > 5.0;
    ELSE
        RunX := False;
        RunY := False;
    END_IF;
    ForksEnable := NOT RunX AND NOT RunY;
END_FUNCTION_BLOCK
