    Motor2_Speed := 0.0;
ELSE
    Zone1_Brake := FALSE;
    Zone2_Brake := FALSE;
    Zone3_Brake := FALSE;
END_IF

// Gap Optimization
Gap_Timer(IN := NOT Entry_Sensor, PT := Target_Gap_Time);
