PROGRAM PRG_VAV_Control
VAR
    // Inputs
    fZoneTemp : LREAL; // Current zone temperature (*C)
    fZoneTempSetpt : LREAL := 22.0; // Temperature setpoint (*C)
    fCO2Level : LREAL; // Current CO2 level (ppm)
    fCO2Setpt : LREAL := 800.0; // CO2 setpoint (ppm)

    // Outputs
    fDamperPos : LREAL; // 0-100% Damper position

    // Limits
    fMinFlowPos : LREAL := 10.0; // Minimum damper position (%)
    fMaxFlowPos : LREAL := 100.0; // Maximum damper position (%)

    // PID Controller
    fbTempPID : FB_BasicPID;

    // DCV Override
    fCO2OverridePos : LREAL;
END_VAR

// Temperature PID Control
fbTempPID(
    fSetpoint := fZoneTempSetpt,
    fActualValue := fZoneTemp,
    fKp := 2.0,
    fTn := 120.0,
    fTv := 0.0,
    fOutMin := fMinFlowPos,
    fOutMax := fMaxFlowPos
);

// CO2 Demand Controlled Ventilation
IF fCO2Level > fCO2Setpt THEN
    // Proportional override based on CO2 error, up to max flow
    fCO2OverridePos := fMinFlowPos + ((fCO2Level - fCO2Setpt) * 0.1);
    IF fCO2OverridePos > fMaxFlowPos THEN
        fCO2OverridePos := fMaxFlowPos;
    END_IF;
ELSE
    fCO2OverridePos := fMinFlowPos;
END_IF;

// Maximum selection: Temp control vs DCV
fDamperPos := MAX(fbTempPID.fOutput, fCO2OverridePos);
