```pascal
FUNCTION_BLOCK "Escalator_Controller"
VERSION : 0.1
   VAR_INPUT 
      Start_Up : Bool;
      Start_Down : Bool;
      Stop : Bool;
      E_Stop : Bool;
      Step_Sensor_1 : Bool;
      Motor_Speed_RPM : Real;
      Maintenance_Mode : Bool;
   END_VAR

   VAR_OUTPUT 
      Motor_Fwd : Bool;
      Motor_Rev : Bool;
      Brake_Release : Bool;
      Alarm_Step_Missing : Bool;
      Alarm_Under_Speed : Bool;
      System_Fault : Bool;
   END_VAR

   VAR 
      State : Int;
      Nominal_Speed : Real := 100.0;
      Under_Speed_Limit : Real := 80.0;
      Step_Timer : TON;
      Speed_Timer : TON;
   END_VAR

   VAR_TEMP 
      Run_Condition : Bool;
   END_VAR

BEGIN
    // Safety and Interlocks
    IF "E_Stop" OR "System_Fault" THEN
        "Motor_Fwd" := FALSE;
        "Motor_Rev" := FALSE;
        "Brake_Release" := FALSE;
        "State" := 0;
        RETURN;
    END_IF;

    // Step Missing Detection
    "Step_Timer"(IN := ("Motor_Fwd" OR "Motor_Rev") AND NOT "Step_Sensor_1",
                 PT := T#1s);
    IF "Step_Timer".Q THEN
        "Alarm_Step_Missing" := TRUE;
        "System_Fault" := TRUE;
    END_IF;

    // Under-speed Monitoring
    "Speed_Timer"(IN := ("Motor_Fwd" OR "Motor_Rev") AND ("Motor_Speed_RPM" < "Under_Speed_Limit"),
                  PT := T#2s);
    IF "Speed_Timer".Q AND NOT "Maintenance_Mode" THEN
        "Alarm_Under_Speed" := TRUE;
        "System_Fault" := TRUE;
    END_IF;

    // Control Logic
    "Run_Condition" := NOT "Stop" AND NOT "System_Fault" AND NOT "E_Stop";

    CASE "State" OF
        0: // Idle
            "Motor_Fwd" := FALSE;
            "Motor_Rev" := FALSE;
            "Brake_Release" := FALSE;
            IF "Run_Condition" AND "Start_Up" AND NOT "Start_Down" THEN
                "State" := 10;
            ELSIF "Run_Condition" AND "Start_Down" AND NOT "Start_Up" AND "Maintenance_Mode" THEN
                "State" := 20;
            END_IF;

        10: // Running Up
            IF NOT "Run_Condition" OR "Start_Down" THEN
                "State" := 0;
            ELSE
                "Brake_Release" := TRUE;
                "Motor_Fwd" := TRUE;
            END_IF;

        20: // Running Down (Reversal)
            IF NOT "Run_Condition" OR "Start_Up" THEN
                "State" := 0;
            ELSE
                "Brake_Release" := TRUE;
                "Motor_Rev" := TRUE;
            END_IF;

    END_CASE;

END_FUNCTION_BLOCK
