FUNCTION_BLOCK "Escalator_Controller_M1"
VERSION : 0.1
   VAR_INPUT 
      Start_Up : Bool;
      Start_Down : Bool;
      Stop : Bool;
      E_Stop : Bool;
      Step_Sensor_1 : Bool;
      Motor_Speed_RPM : Real;
      Maintenance_Mode : Bool;
      Passenger_Radar : Bool;
   END_VAR

   VAR_OUTPUT 
      Motor_Fwd : Bool;
      Motor_Rev : Bool;
      Brake_Release : Bool;
      VFD_Speed_Ref : Real;
      Alarm_Step_Missing : Bool;
      Alarm_Under_Speed : Bool;
      System_Fault : Bool;
   END_VAR

   VAR 
      State : Int;
      Nominal_Speed : Real := 100.0;
      Eco_Speed : Real := 20.0;
      Under_Speed_Limit : Real := 80.0;
      Step_Timer : TON;
      Speed_Timer : TON;
      Passenger_Timer : TON;
   END_VAR

BEGIN
    // Safety
    IF "E_Stop" OR "System_Fault" THEN
        "Motor_Fwd" := FALSE;
        "Motor_Rev" := FALSE;
        "Brake_Release" := FALSE;
        "VFD_Speed_Ref" := 0.0;
        "State" := 0;
        RETURN;
    END_IF;

    // Step Missing & Under-speed Detection (Same logic)
    "Step_Timer"(IN := ("Motor_Fwd" OR "Motor_Rev") AND NOT "Step_Sensor_1", PT := T#1s);
    IF "Step_Timer".Q THEN "Alarm_Step_Missing" := TRUE; "System_Fault" := TRUE; END_IF;

    "Speed_Timer"(IN := ("Motor_Fwd" OR "Motor_Rev") AND ("Motor_Speed_RPM" < "Under_Speed_Limit") AND ("VFD_Speed_Ref" > "Eco_Speed"), PT := T#2s);
    IF "Speed_Timer".Q AND NOT "Maintenance_Mode" THEN "Alarm_Under_Speed" := TRUE; "System_Fault" := TRUE; END_IF;

    // Eco Mode Logic
    "Passenger_Timer"(IN := NOT "Passenger_Radar", PT := T#60s);

    CASE "State" OF
        0: 
            "Motor_Fwd" := FALSE; "Motor_Rev" := FALSE; "Brake_Release" := FALSE; "VFD_Speed_Ref" := 0.0;
            IF NOT "Stop" AND "Start_Up" THEN "State" := 10;
            ELSIF NOT "Stop" AND "Start_Down" AND "Maintenance_Mode" THEN "State" := 20; END_IF;
        10: 
            IF "Stop" THEN "State" := 0; 
            ELSE 
                "Brake_Release" := TRUE; "Motor_Fwd" := TRUE;
                IF "Passenger_Timer".Q THEN "VFD_Speed_Ref" := "Eco_Speed"; ELSE "VFD_Speed_Ref" := "Nominal_Speed"; END_IF;
            END_IF;
        20: 
            IF "Stop" THEN "State" := 0; 
            ELSE 
                "Brake_Release" := TRUE; "Motor_Rev" := TRUE; "VFD_Speed_Ref" := "Nominal_Speed"; 
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
