TYPE ST_ScadaCommand :
STRUCT
    bRequestShow : BOOL;
    iRequestedUserRole : INT;
    rOverridePowerLimit : REAL;
END_STRUCT
END_TYPE

TYPE ST_ScadaStatus :
STRUCT
    bShowActive : BOOL;
    bLoadSheddingActive : BOOL;
    rCurrentPower : REAL;
    bFailoverActive : BOOL;
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
    {attribute 'OPC.UA.DA' := '1'}
    stScadaCmd : ST_ScadaCommand;
    {attribute 'OPC.UA.DA' := '1'}
    stScadaStatus : ST_ScadaStatus;
    bAccessDenied : BOOL;
    bPrimaryPLC : BOOL := TRUE;
    bHeartbeatIn AT %I* : BOOL;
    bHeartbeatOut AT %Q* : BOOL;
    tHeartbeatTimeout : TON;
    bFailoverTriggered : BOOL;
    aDaliCmd AT %Q* : ARRAY[1..10] OF BYTE;
    bStartShow : BOOL;
    iShowState : INT;
    tShowTimer : TON;
    rTotalPower : REAL;
    rLimit : REAL;
    bToggle : BOOL;
    i : INT;
END_VAR

bToggle := NOT bToggle;
bHeartbeatOut := bToggle;

tHeartbeatTimeout(IN:= bPrimaryPLC AND (bHeartbeatIn = bHeartbeatIn), PT:= T#500MS);
IF tHeartbeatTimeout.Q AND NOT bPrimaryPLC THEN
    bFailoverTriggered := TRUE;
    bPrimaryPLC := TRUE;
END_IF

stScadaStatus.bFailoverActive := bFailoverTriggered;
IF NOT bPrimaryPLC THEN RETURN; END_IF

IF stScadaCmd.bRequestShow THEN
    IF stScadaCmd.iRequestedUserRole >= 2 THEN
        bStartShow := TRUE;
        bAccessDenied := FALSE;
    ELSE
        bAccessDenied := TRUE;
    END_IF
    stScadaCmd.bRequestShow := FALSE;
END_IF

IF stScadaCmd.rOverridePowerLimit > 100.0 THEN
    rLimit := stScadaCmd.rOverridePowerLimit;
ELSE
    rLimit := 500.0;
END_IF

stScadaStatus.rCurrentPower := rTotalPower;
IF rTotalPower > rLimit THEN
    stScadaStatus.bLoadSheddingActive := TRUE;
ELSE
    stScadaStatus.bLoadSheddingActive := FALSE;
END_IF

stScadaStatus.bShowActive := bStartShow;
tShowTimer(IN:= bStartShow, PT:= T#1S);

IF bStartShow THEN
    CASE iShowState OF
        0: aDaliCmd[1] := 255; IF tShowTimer.Q THEN iShowState := 1; tShowTimer(IN:=FALSE); END_IF
        1: aDaliCmd[1] := 0; bStartShow := FALSE; iShowState := 0;
    END_CASE
ELSE
    FOR i := 1 TO 10 DO
        IF stScadaStatus.bLoadSheddingActive AND i > 5 THEN
            aDaliCmd[i] := 100;
        ELSE
            aDaliCmd[i] := 255;
        END_IF
    END_FOR
END_IF

PROGRAM MAIN
VAR
    aDaliCmd : ARRAY[1..10] OF BYTE;
    aDaliFeedbackCurrent : ARRAY[1..10] OF REAL;
    rAmbientLightSensor1 : REAL;
    rAmbientLightSensor2 : REAL;
    bSensorDriftDetected : BOOL;
    rDriftTolerance : REAL := 15.0;
    {attribute 'TcDisplayString' := 'HIL_Sync'}
    aTwinDaliState : ARRAY[1..10] OF BYTE;
    bStartSelfTest : BOOL;
    iTestStep : INT;
    tTestDelay : TON;
    aTestResultFlags : ARRAY[1..10] OF BOOL;
    bTestComplete : BOOL;
    bStartShow : BOOL;
    bLoadSheddingActive : BOOL;
    rTotalPower : REAL;
    i : INT;
END_VAR

IF ABS(rAmbientLightSensor1 - rAmbientLightSensor2) > rDriftTolerance THEN
    bSensorDriftDetected := TRUE;
ELSE
    bSensorDriftDetected := FALSE;
END_IF

tTestDelay(IN:= bStartSelfTest, PT:= T#2S);
IF bStartSelfTest THEN
    IF iTestStep = 0 THEN
        FOR i := 1 TO 10 DO aTestResultFlags[i] := FALSE; aDaliCmd[i] := 0; END_FOR
        iTestStep := 1;
    ELSIF iTestStep >= 1 AND iTestStep <= 10 THEN
        aDaliCmd[iTestStep] := 255;
        IF tTestDelay.Q THEN
            IF aDaliFeedbackCurrent[iTestStep] > 0.5 THEN
                aTestResultFlags[iTestStep] := TRUE;
            ELSE
                aTestResultFlags[iTestStep] := FALSE;
            END_IF
            aDaliCmd[iTestStep] := 0;
            iTestStep := iTestStep + 1;
            tTestDelay(IN:=FALSE);
        END_IF
    ELSIF iTestStep = 11 THEN
        bTestComplete := TRUE;
        bStartSelfTest := FALSE;
        iTestStep := 0;
    END_IF

    FOR i := 1 TO 10 DO aTwinDaliState[i] := aDaliCmd[i]; END_FOR
    RETURN;
END_IF

IF rTotalPower > 500.0 THEN bLoadSheddingActive := TRUE; ELSE bLoadSheddingActive := FALSE; END_IF

IF bStartShow THEN
    aDaliCmd[1] := 255;
ELSE
    FOR i := 1 TO 10 DO
        IF bLoadSheddingActive AND i > 5 THEN
            aDaliCmd[i] := 128;
        ELSE
            aDaliCmd[i] := 255;
        END_IF
    END_FOR
END_IF

FOR i := 1 TO 10 DO
    aTwinDaliState[i] := aDaliCmd[i];
END_FOR

FUNCTION_BLOCK "FB_BatchReactor"
VERSION : 0.1
   VAR_INPUT 
      start_batch : Bool;
      reactor_temp : Real;
      reactor_press : Real;
      catalyst_flow : Real;
      setpoint_temp : Real;
      setpoint_dosing : Real;
   END_VAR

   VAR_OUTPUT 
      cooling_valve : Real;
      dosing_pump : Bool;
      alarm_high_press : Bool;
      interlock_rupture : Bool;
   END_VAR

   VAR 
      pid_cooling : "PID_Compact";
      total_catalyst : Real;
      batch_active : Bool;
   END_VAR

BEGIN
   // Interlocks
   IF #reactor_press > 10.0 THEN
       #interlock_rupture := TRUE;
       #alarm_high_press := TRUE;
       #batch_active := FALSE;
   END_IF;

   IF #interlock_rupture THEN
       #cooling_valve := 100.0;
       #dosing_pump := FALSE;
       RETURN;
   END_IF;

   IF #start_batch AND NOT #interlock_rupture THEN
       #batch_active := TRUE;
   END_IF;

   IF #batch_active THEN
       // Cooling PID
       #pid_cooling(Setpoint := #setpoint_temp, Input := #reactor_temp, Output => #cooling_valve);

       // Dosing
       IF #total_catalyst < #setpoint_dosing THEN
           #dosing_pump := TRUE;
           #total_catalyst := #total_catalyst + (#catalyst_flow * 0.1); // integration step
       ELSE
           #dosing_pump := FALSE;
       END_IF;
   ELSE
       #cooling_valve := 0.0;
       #dosing_pump := FALSE;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "FB_BatchReactor_Depth"
VERSION : 0.1
   VAR_INPUT 
      start_batch : Bool;
      reactor_temp : Real;
      reactor_press : Real;
      catalyst_flow : Real;
      agitator_load : Real;
      setpoint_temp : Real;
      setpoint_dosing : Real;
   END_VAR

   VAR_OUTPUT 
      cooling_valve : Real;
      dosing_pump : Bool;
      agitator_speed_ref : Real;
      alarm_high_press : Bool;
      interlock_rupture : Bool;
   END_VAR

   VAR 
      pid_cooling : "PID_Compact";
      total_catalyst : Real;
      batch_active : Bool;
   END_VAR

BEGIN
   // Interlocks
   IF #reactor_press > 10.0 THEN
       #interlock_rupture := TRUE;
       #alarm_high_press := TRUE;
       #batch_active := FALSE;
   END_IF;

   IF #interlock_rupture THEN
       #cooling_valve := 100.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
       RETURN;
   END_IF;

   IF #start_batch AND NOT #interlock_rupture THEN
       #batch_active := TRUE;
   END_IF;

   IF #batch_active THEN
       // Cooling PID
       #pid_cooling(Setpoint := #setpoint_temp, Input := #reactor_temp, Output => #cooling_valve);

       // Dosing
       IF #total_catalyst < #setpoint_dosing THEN
           #dosing_pump := TRUE;
           #total_catalyst := #total_catalyst + (#catalyst_flow * 0.1);
       ELSE
           #dosing_pump := FALSE;
       END_IF;

       // Agitator VFD Control
       IF #agitator_load > 85.0 THEN
           #agitator_speed_ref := 40.0; // Load shedding
       ELSE
           #agitator_speed_ref := 100.0;
       END_IF;
   ELSE
