PROGRAM PRG_DistillationMutation4
VAR
    // Sensor Drift Detection
    fTemp_A AT %I* : REAL;
    fTemp_B AT %I* : REAL;
    fTemp_C AT %I* : REAL;
    fDriftThreshold : REAL := 2.5; // [C]
    bDriftAlarm : BOOL;
    fVotedTemp : REAL;

    // HIL Digital Twin Sync
    {attribute 'OPC.UA.DA' := '1'}
    bTwinSyncActive : BOOL;
    fTwinPredictedLevel : REAL;
    fTwinLevelDeviation : REAL;
    bTwinDeviationAlarm : BOOL;

    // Automated Self-Test
    eSelfTestState : (IDLE, TEST_VALVE_OPEN, TEST_VALVE_CLOSE, TEST_PUMP, COMPLETE, FAILED) := IDLE;
    bSelfTestRequest : BOOL;
    bSelfTestPassed : BOOL;
    tTestTimer : TON;
    fTestValvePos : REAL;
END_VAR

// Sensor Drift Detection (Triple Modular Redundancy with Voting)
IF ABS(fTemp_A - fTemp_B) > fDriftThreshold OR ABS(fTemp_B - fTemp_C) > fDriftThreshold THEN
    bDriftAlarm := TRUE;
    // Simple median logic for voted temp
    IF (fTemp_A > fTemp_B AND fTemp_A < fTemp_C) OR (fTemp_A < fTemp_B AND fTemp_A > fTemp_C) THEN fVotedTemp := fTemp_A;
    ELSIF (fTemp_B > fTemp_A AND fTemp_B < fTemp_C) OR (fTemp_B < fTemp_A AND fTemp_B > fTemp_C) THEN fVotedTemp := fTemp_B;
    ELSE fVotedTemp := fTemp_C; END_IF
ELSE
    bDriftAlarm := FALSE;
    fVotedTemp := (fTemp_A + fTemp_B + fTemp_C) / 3.0;
END_IF

// HIL Digital Twin Sync
IF bTwinSyncActive THEN
    fTwinLevelDeviation := ABS(fVotedTemp - fTwinPredictedLevel); // Mock usage
    IF fTwinLevelDeviation > 10.0 THEN bTwinDeviationAlarm := TRUE; ELSE bTwinDeviationAlarm := FALSE; END_IF
END_IF

// Self-Test Routine
CASE eSelfTestState OF
    IDLE:
        IF bSelfTestRequest THEN
            eSelfTestState := TEST_VALVE_OPEN;
            bSelfTestPassed := FALSE;
        END_IF
    TEST_VALVE_OPEN:
        fTestValvePos := 100.0;
        tTestTimer(IN:= TRUE, PT:= T#2S);
        IF tTestTimer.Q THEN
            tTestTimer(IN:= FALSE);
            eSelfTestState := TEST_VALVE_CLOSE;
        END_IF
    TEST_VALVE_CLOSE:
        fTestValvePos := 0.0;
        tTestTimer(IN:= TRUE, PT:= T#2S);
        IF tTestTimer.Q THEN
             tTestTimer(IN:= FALSE);
             eSelfTestState := COMPLETE;
        END_IF
    COMPLETE:
        bSelfTestPassed := TRUE;
        bSelfTestRequest := FALSE;
        eSelfTestState := IDLE;
    FAILED:
        bSelfTestPassed := FALSE;
        bSelfTestRequest := FALSE;
END_CASE

