EIP_Output_Data[0] := REAL_TO_DINT(MeltPressure_PreScreen);
EIP_Output_Data[1] := REAL_TO_DINT(ScrewTorque);
EIP_Output_Data[2] := FaultBuffer[0];

// Read from input block
ScrewSpeedSP := DINT_TO_REAL(EIP_Input_Data[0]);
ExtruderRun := EIP_Input_Data[1].0;

// Fault Diagnostics Logic
NewFaultCode := 0;
IF Alarm_HighPressure THEN NewFaultCode := 1001; END_IF;
IF Alarm_HighTorque THEN NewFaultCode := 1002; END_IF;
IF ScreenDP >= 800.0 THEN NewFaultCode := 1003; END_IF;

// Ring Buffer Insertion
IF NewFaultCode <> 0 AND NOT FaultActive THEN
    FaultBuffer[FaultIndex] := NewFaultCode;
    FaultIndex := FaultIndex + 1;
    IF FaultIndex > 9 THEN FaultIndex := 0; END_IF;
    FaultActive := 1;
ELSIF NewFaultCode = 0 THEN
    FaultActive := 0;
END_IF;
END_PROGRAM
```

### Reasoning
When adding IEC 62443 cybersecurity, we must ensure that critical actions (like modifying PID setpoints or overriding safety limits) are restricted to authenticated roles (e.g., Engineer or Admin). This minimizes the attack surface against unauthorized parameter changes. Redundant PLC failover requires a heartbeat signal (a toggling bit or counter) exchanged between the Primary and Standby PLCs. If the Primary misses the heartbeat within a defined watchdog window, the Standby assumes control to prevent extrusion process freezing, which could cause catastrophic polymer degradation. Timestamped SCADA logging ensures that all critical events and access attempts are recorded for auditing and forensic analysis.

### ST Code
```pascal
PROGRAM Extruder_Reasoning
VAR
    ActiveUserRole : DINT; // 0=None, 1=Operator, 2=Engineer, 3=Admin
    Req_TempSP_Change : BOOL;
    New_TempSP : REAL;
    Partner_Heartbeat : DINT;
    Last_Partner_Heartbeat : DINT;
    Failover_Watchdog : TON;
    Is_Primary : BOOL;
    Take_Control : BOOL;
    Log_Trigger : BOOL;
    Sys_Time : LDT;
END_VAR

// IEC 62443 Role-Based Access Control
IF Req_TempSP_Change THEN
    IF ActiveUserRole >= 2 THEN
        TempZone_SP[1] := New_TempSP;
        Log_Trigger := 1;
    ELSE
        NewFaultCode := 403; // Unauthorized
    END_IF;
    Req_TempSP_Change := 0;
END_IF;

// Redundant PLC Failover Heartbeat
Failover_Watchdog(IN := (Partner_Heartbeat = Last_Partner_Heartbeat), PT := T#500MS);
IF Failover_Watchdog.Q AND NOT Is_Primary THEN
    Take_Control := 1; // Partner failed, assume control
END_IF;
Last_Partner_Heartbeat := Partner_Heartbeat;

// SCADA Timestamped Logging
IF Log_Trigger THEN
    // Example: GSV(WallClockTime, ?, DateTime, Sys_Time);
    EIP_Output_Data[10] := LDT_TO_DINT(Sys_Time);
    Log_Trigger := 0;
END_IF;
END_PROGRAM
```

