IF PressureDrift_Dev > DriftAlarmThreshold THEN
    SensorDriftFault := 1;
    MeltPressure_PreScreen := (PressureSensor_A + PressureSensor_B) / 2.0; // Graceful degradation
ELSE
    SensorDriftFault := 0;
    MeltPressure_PreScreen := PressureSensor_A;
