// 3. Pre-Start Actuator Self-Test
IF ExtruderStart AND NOT SelfTest_Complete THEN
    CASE SelfTest_Step OF
        0:  // Ping Heaters
            HeaterOutput[1] := 10.0;
            SelfTest_Timer(IN:=1, PT:=T#2S);
            IF SelfTest_Timer.Q THEN SelfTest_Step := 1; END_IF;
        1:  // Verify Feedback
