```scl
FUNCTION_BLOCK "FB_CentrifugalSeparator"
TITLE = 'Centrifugal Separator Control'

VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    bReset : BOOL;
    rSpeedSetpoint : REAL;
    rActualSpeed : REAL;
    rVibration : REAL;
    rVibrationLimit : REAL := 5.0;
    tDischargeInterval : TIME := T#30M;
    tDischargeDuration : TIME := T#5S;
END_VAR

VAR_OUTPUT
    bVFD_Run : BOOL;
    rVFD_SpeedRef : REAL;
    bDischargeValve : BOOL;
    bFault : BOOL;
    iState : INT;
END_VAR

VAR
    tonDischargeInt : TON;
    tonDischargeDur : TON;
    bVibrationFault : BOOL;
END_VAR

BEGIN
    IF rVibration > rVibrationLimit THEN bVibrationFault := TRUE; END_IF;
    IF bVibrationFault THEN
        bFault := TRUE;
        iState := 3;
    END_IF;
    IF bReset THEN
        bVibrationFault := FALSE;
        bFault := FALSE;
        IF iState = 3 THEN iState := 0; END_IF;
    END_IF;

    CASE iState OF
        0:
            bVFD_Run := FALSE;
            rVFD_SpeedRef := 0.0;
            IF bStart AND NOT bFault THEN iState := 1; END_IF;
        1:
            bVFD_Run := TRUE;
            rVFD_SpeedRef := rSpeedSetpoint;
            IF ABS(rActualSpeed - rSpeedSetpoint) < 20.0 THEN iState := 2; END_IF;
            IF bStop THEN iState := 0; END_IF;
        2:
            bVFD_Run := TRUE;
            rVFD_SpeedRef := rSpeedSetpoint;
            IF bStop THEN iState := 0; END_IF;
        3:
            bVFD_Run := FALSE;
            rVFD_SpeedRef := 0.0;
    END_CASE;

    tonDischargeInt(IN := (iState = 2) AND NOT tonDischargeDur.Q, PT := tDischargeInterval);
    tonDischargeDur(IN := tonDischargeInt.Q, PT := tDischargeDuration);
    bDischargeValve := tonDischargeInt.Q;
END_FUNCTION_BLOCK
