```scl
FUNCTION_BLOCK "FB_CentrifugalSeparator_Reasoning"
TITLE = 'Centrifugal Separator with RBAC & Failover'

VAR_INPUT
    bLocalStart : BOOL;
    bLocalStop : BOOL;
    rVibration : REAL;
    iUserRole : INT; // 0: None, 1: Operator, 2: Maintenance, 3: Admin
    bMaintenanceBypassReq : BOOL;
    bIsPrimaryUnit : BOOL;
    bPartnerFaulted : BOOL;
    PN_Cmd : "udtProfinetCmd";
END_VAR

VAR_OUTPUT
    bVFD_Run : BOOL;
    wErrorCode : WORD;
    bFailoverTrigger : BOOL;
    SCADA_StatusWord : WORD;
    SCADA_CurrentState : INT;
END_VAR

VAR
    iState : INT;
    bAccessDenied : BOOL;
    bSystemFault : BOOL;
    tonFailover : TON;
END_VAR

BEGIN
    IF bMaintenanceBypassReq AND (iUserRole < 2) THEN
        bAccessDenied := TRUE;
        wErrorCode := wErrorCode OR 16#0080;
    ELSE
        bAccessDenied := FALSE;
    END_IF;

    IF (bLocalStart OR PN_Cmd.RemoteStart) AND (iUserRole < 1) THEN
        bAccessDenied := TRUE;
    END_IF;

    IF rVibration > 5.0 THEN
        bSystemFault := TRUE;
        wErrorCode := wErrorCode OR 16#0001;
    END_IF;

    tonFailover(IN := (NOT bIsPrimaryUnit) AND bPartnerFaulted, PT := T#10S);

    IF bIsPrimaryUnit AND bSystemFault THEN
        bFailoverTrigger := TRUE;
    ELSE
        bFailoverTrigger := FALSE;
    END_IF;

    CASE iState OF
        0:
            bVFD_Run := FALSE;
            IF ((bLocalStart OR PN_Cmd.RemoteStart) AND NOT bAccessDenied AND NOT bSystemFault) 
               OR tonFailover.Q THEN
                iState := 1;
            END_IF;
        1:
            bVFD_Run := TRUE;
            IF bSystemFault OR bLocalStop OR PN_Cmd.RemoteStop THEN iState := 0; END_IF;
    END_CASE;

    SCADA_CurrentState := iState;
    SCADA_StatusWord := 0;
    SCADA_StatusWord.%X0 := bVFD_Run;
    SCADA_StatusWord.%X1 := bSystemFault;
    SCADA_StatusWord.%X2 := bIsPrimaryUnit;
    SCADA_StatusWord.%X3 := bAccessDenied;
    SCADA_StatusWord.%X8 := bFailoverTrigger;
END_FUNCTION_BLOCK
