// Adversarial Defenses
IF ABS(fCondProbe1 - fCondProbe2) > 2.0 THEN
    bSensorDriftFault := TRUE;
END_IF

fbHIL_Watchdog(IN := NOT bHIL_Heartbeat, PT := T#2S);
IF fbHIL_Watchdog.Q THEN
    eState := 99; // Fault due to HIL sync loss
END_IF

CASE eState OF
    0: // INIT
        IF NOT bSelfTestComplete THEN
            eState := 10; // Self-test
        ELSE
            eState := 1;
        END_IF
    10: // SELF-TEST
        bVFD_Run := TRUE; // Pulse VFD
        // Validate response...
        bSelfTestComplete := TRUE;
        eState := 1;
    1: // STANDBY
        bVFD_Run := FALSE;
        IF bStart AND NOT bSensorDriftFault THEN
            eState := 2;
        END_IF
    2: // PRODUCTION
        bVFD_Run := TRUE;
    99: // FAULT
        bVFD_Run := FALSE;
END_CASE
```

Here is a complete Siemens SCL implementation for a Marine Dynamic Positioning System (DP2). This code includes a TMR (Triple Modular Redundancy) voter for GPS and Gyro sensors, a simplified Kalman filter for state estimation, and a basic thruster allocation algorithm.

```pascal
FUNCTION_BLOCK "DP2_Controller"
VERSION : 0.1
VAR_INPUT
    gps_1_pos : REAL;
    gps_2_pos : REAL;
    gps_3_pos : REAL;
    gyro_1_hdg : REAL;
    gyro_2_hdg : REAL;
    gyro_3_hdg : REAL;
    setpoint_pos : REAL;
    setpoint_hdg : REAL;
END_VAR

VAR_OUTPUT
    thruster_bow_cmd : REAL;
    thruster_port_cmd : REAL;
    thruster_stbd_cmd : REAL;
    system_fault : BOOL;
END_VAR

VAR
    // Kalman Filter variables
    est_pos : REAL;
    est_vel : REAL;
    est_hdg : REAL;
    est_rate : REAL;
    P_pos : REAL := 1.0;
    P_hdg : REAL := 1.0;
    // Voter outputs
    voted_pos : REAL;
    voted_hdg : REAL;
    voted_pos_valid : BOOL;
    voted_hdg_valid : BOOL;
END_VAR

BEGIN
    // 1. Triple Modular Redundancy (TMR) Voting for GPS
    // Simple median voter or majority voter with tolerance
    IF ABS(gps_1_pos - gps_2_pos) < 2.0 THEN
        voted_pos := (gps_1_pos + gps_2_pos) / 2.0;
        voted_pos_valid := TRUE;
    ELSIF ABS(gps_2_pos - gps_3_pos) < 2.0 THEN
        voted_pos := (gps_2_pos + gps_3_pos) / 2.0;
        voted_pos_valid := TRUE;
    ELSIF ABS(gps_1_pos - gps_3_pos) < 2.0 THEN
        voted_pos := (gps_1_pos + gps_3_pos) / 2.0;
        voted_pos_valid := TRUE;
    ELSE
        voted_pos_valid := FALSE;
    END_IF;

    // TMR for Gyro
    IF ABS(gyro_1_hdg - gyro_2_hdg) < 1.0 THEN
        voted_hdg := (gyro_1_hdg + gyro_2_hdg) / 2.0;
        voted_hdg_valid := TRUE;
    ELSIF ABS(gyro_2_hdg - gyro_3_hdg) < 1.0 THEN
        voted_hdg := (gyro_2_hdg + gyro_3_hdg) / 2.0;
        voted_hdg_valid := TRUE;
    ELSIF ABS(gyro_1_hdg - gyro_3_hdg) < 1.0 THEN
        voted_hdg := (gyro_1_hdg + gyro_3_hdg) / 2.0;
        voted_hdg_valid := TRUE;
    ELSE
        voted_hdg_valid := FALSE;
    END_IF;

    system_fault := NOT(voted_pos_valid) OR NOT(voted_hdg_valid);

    // 2. Kalman Filter (Simplified 1D for Pos/Hdg)
    IF NOT system_fault THEN
        // Prediction step
        est_pos := est_pos + est_vel * 0.1; // dt = 0.1s
        P_pos := P_pos + 0.01; // Q covariance

        // Update step
        VAR
            K_pos : REAL;
        END_VAR
        K_pos := P_pos / (P_pos + 0.5); // R = 0.5
        est_pos := est_pos + K_pos * (voted_pos - est_pos);
        P_pos := (1.0 - K_pos) * P_pos;

        // Hdg Prediction
        est_hdg := est_hdg + est_rate * 0.1;
        P_hdg := P_hdg + 0.01;

        // Hdg Update
        VAR
            K_hdg : REAL;
        END_VAR
        K_hdg := P_hdg / (P_hdg + 0.1);
        est_hdg := est_hdg + K_hdg * (voted_hdg - est_hdg);
        P_hdg := (1.0 - K_hdg) * P_hdg;
    END_IF;

    // 3. PID Control & Thruster Allocation
    VAR
        err_pos : REAL;
        err_hdg : REAL;
        force_cmd : REAL;
        moment_cmd : REAL;
    END_VAR

    err_pos := setpoint_pos - est_pos;
    err_hdg := setpoint_hdg - est_hdg;

    // Simple Proportional Control
    force_cmd := err_pos * 50.0;
    moment_cmd := err_hdg * 20.0;

    // Thruster Allocation Logic (3 thrusters: 1 bow tunnel, 2 azimuth stern)
    thruster_bow_cmd := moment_cmd * 0.5;
    thruster_port_cmd := (force_cmd / 2.0) - (moment_cmd * 0.25);
    thruster_stbd_cmd := (force_cmd / 2.0) + (moment_cmd * 0.25);

    // Saturate commands
    IF thruster_bow_cmd > 100.0 THEN thruster_bow_cmd := 100.0; END_IF;
    IF thruster_port_cmd > 100.0 THEN thruster_port_cmd := 100.0; END_IF;
    IF thruster_stbd_cmd > 100.0 THEN thruster_stbd_cmd := 100.0; END_IF;

END_FUNCTION_BLOCK
```

This basic DP2 controller processes redundant sensor data, filters noise using a Kalman estimator, and allocates force commands to a three-thruster setup.

Here is an advanced Siemens SCL implementation for a Marine Dynamic Positioning System (DP2) featuring wind feed-forward compensation and environmental current drag estimation.

```pascal
FUNCTION_BLOCK "DP2_Advanced_Controller"
VERSION : 1.0
VAR_INPUT
    gps_array : ARRAY[1..3] OF REAL;
    gyro_array : ARRAY[1..3] OF REAL;
    anemometer_speed : REAL;
    anemometer_dir : REAL;
    setpoint_pos : REAL;
    setpoint_hdg : REAL;
END_VAR

VAR_OUTPUT
    thruster_cmd : ARRAY[1..3] OF REAL; // 1: Bow, 2: Port, 3: Stbd
    current_drag_est : REAL;
    system_fault : BOOL;
END_VAR

VAR
    est_pos : REAL;
    est_vel : REAL;
    P_pos : REAL := 1.0;
    voted_pos : REAL;
    voted_pos_valid : BOOL;
    wind_force_ff : REAL;
END_VAR

BEGIN
    // 1. TMR Voting
    IF ABS(gps_array[1] - gps_array[2]) < 2.0 THEN
        voted_pos := (gps_array[1] + gps_array[2]) / 2.0;
        voted_pos_valid := TRUE;
    ELSE
        voted_pos_valid := FALSE;
    END_IF;
    system_fault := NOT(voted_pos_valid);

    // 2. Wind Feed-Forward Compensation
    // Calculate wind force acting on the vessel profile
    VAR
        wind_density : REAL := 1.225;
        vessel_area : REAL := 500.0;
        drag_coeff : REAL := 0.8;
    END_VAR
    wind_force_ff := 0.5 * wind_density * vessel_area * drag_coeff * (anemometer_speed * anemometer_speed) * COS(anemometer_dir);

    // 3. Kalman Filter with Current Drag Estimation
    IF NOT system_fault THEN
        // Prediction step including wind force and estimated current drag
        est_vel := est_vel + (wind_force_ff + current_drag_est) * 0.1 / 10000.0; // 10000kg mass
        est_pos := est_pos + est_vel * 0.1;
        P_pos := P_pos + 0.05;

        VAR
            K_pos : REAL;
            residual : REAL;
        END_VAR
        K_pos := P_pos / (P_pos + 0.5);
        residual := voted_pos - est_pos;
        est_pos := est_pos + K_pos * residual;
        P_pos := (1.0 - K_pos) * P_pos;

        // Estimate current drag based on persistent residual (integral action in observer)
        current_drag_est := current_drag_est + (0.01 * residual);
    END_IF;

    // 4. Control & Allocation
    VAR
        err_pos : REAL;
        pid_out : REAL;
    END_VAR
    err_pos := setpoint_pos - est_pos;
    pid_out := (err_pos * 50.0) - wind_force_ff; // Subtract wind force proactively

    thruster_cmd[1] := pid_out * 0.2;
    thruster_cmd[2] := pid_out * 0.4;
    thruster_cmd[3] := pid_out * 0.4;
END_FUNCTION_BLOCK
```

This mutation incorporates wind feed-forward to preemptively counteract wind gusts before they cause positional deviation, while simultaneously using a Kalman residual observer to slowly estimate and counteract ocean current drag.

To fulfill the requirements of integrating Profinet diagnostics along with a DP2 control system, the following SCL code demonstrates reading Profinet diagnostic interrupts (OB82) and validating network health before executing thruster allocation.

```pascal
FUNCTION_BLOCK "DP2_Profinet_Diag"
VERSION : 1.1
VAR_INPUT
    gps_array : ARRAY[1..3] OF REAL;
    pn_device_status : ARRAY[1..3] OF WORD; // Profinet status words for thrusters
    setpoint_pos : REAL;
END_VAR

VAR_OUTPUT
    thruster_cmd : ARRAY[1..3] OF REAL;
    network_fault : BOOL;
    drive_faults : ARRAY[1..3] OF BOOL;
END_VAR

VAR
    est_pos : REAL;
    P_pos : REAL := 1.0;
    voted_pos : REAL;
END_VAR

BEGIN
    // 1. Profinet Fault Diagnostics
    network_fault := FALSE;
    FOR i := 1 TO 3 DO
        // Check if Profinet IO Data is valid (Bit 15 usually indicates Error in standard PN profiles)
        IF (pn_device_status[i] AND 16#8000) <> 0 THEN
            drive_faults[i] := TRUE;
            network_fault := TRUE;
        ELSE
            drive_faults[i] := FALSE;
        END_IF;
    END_FOR;

    // 2. TMR Voting
    IF ABS(gps_array[1] - gps_array[2]) < 2.0 THEN
        voted_pos := (gps_array[1] + gps_array[2]) / 2.0;
    ELSE
        voted_pos := gps_array[3]; // Fallback
    END_IF;

    // 3. Kalman Filter
    IF NOT network_fault THEN
        est_pos := est_pos + 0.0;
        P_pos := P_pos + 0.01;

        VAR
            K_pos : REAL;
        END_VAR
        K_pos := P_pos / (P_pos + 0.5);
        est_pos := est_pos + K_pos * (voted_pos - est_pos);
        P_pos := (1.0 - K_pos) * P_pos;
    END_IF;

    // 4. Fault-Tolerant Thruster Allocation
    VAR
        err_pos : REAL;
        total_cmd : REAL;
    END_VAR
    err_pos := setpoint_pos - est_pos;
    total_cmd := err_pos * 50.0;

    // Reallocate based on Profinet diagnostic flags
    IF NOT drive_faults[1] AND NOT drive_faults[2] AND NOT drive_faults[3] THEN
        thruster_cmd[1] := total_cmd * 0.33;
        thruster_cmd[2] := total_cmd * 0.33;
        thruster_cmd[3] := total_cmd * 0.33;
    ELSIF drive_faults[1] AND NOT drive_faults[2] AND NOT drive_faults[3] THEN
        // Bow thruster failed, use aft thrusters heavily
        thruster_cmd[1] := 0.0;
        thruster_cmd[2] := total_cmd * 0.5;
        thruster_cmd[3] := total_cmd * 0.5;
    ELSE
        // Critical failure mode
        thruster_cmd[1] := 0.0;
        thruster_cmd[2] := 0.0;
        thruster_cmd[3] := 0.0;
    END_IF;
END_FUNCTION_BLOCK
```

This block extends the DP2 functionality by monitoring the Profinet cyclic data status words from the thruster Variable Frequency Drives (VFDs). If a drive goes offline or reports a fault over Profinet, the thruster allocation dynamically redistributes the thrust to the healthy drives.

### Architectural Reasoning

1. **IEC 62443 Cybersecurity (RBAC):** To comply with IEC 62443-3-3, the DP system must enforce Role-Based Access Control before accepting setpoints from the SCADA interface. We implement an access level check mapped to cryptographically secure tokens (abstracted here as a session ID and role level).
2. **Hot-Standby Failover:** A DP2 system requires redundancy. We use a primary/secondary PLC architecture. The `is_primary` flag dictates which PLC drives the physical outputs, but *both* PLCs run the Kalman filter to maintain identical internal state matrices. If the primary's heartbeat is lost, the secondary takes over bumplessly.
3. **Secure SCADA Integration:** SCADA setpoints are passed through a validation block checking rate-of-change and bounds to prevent malicious or accidental extreme setpoint injection.

### Siemens SCL Implementation

```pascal
FUNCTION_BLOCK "DP2_Secure_HighAvail"
VERSION : 2.0
VAR_INPUT
    is_primary : BOOL;
    peer_heartbeat_valid : BOOL;
    gps_array : ARRAY[1..3] OF REAL;

    // SCADA Interface
    scada_setpoint : REAL;
    scada_session_role : INT; // 0: Guest, 1: Operator, 2: DPO (Dynamic Positioning Operator)
    scada_session_valid : BOOL;
END_VAR

VAR_OUTPUT
    thruster_cmd : ARRAY[1..3] OF REAL;
    active_plc : BOOL;
    security_alarm : BOOL;
END_VAR

VAR
    est_pos : REAL;
    P_pos : REAL := 1.0;
    voted_pos : REAL;
    secure_setpoint : REAL;
    last_secure_setpoint : REAL;
END_VAR

BEGIN
    // 1. IEC 62443 Role-Based Access & Setpoint Sanitization
    IF scada_session_valid AND (scada_session_role >= 2) THEN
        // Rate-of-change limiter for security
        IF ABS(scada_setpoint - last_secure_setpoint) < 5.0 THEN
            secure_setpoint := scada_setpoint;
        ELSE
            security_alarm := TRUE; // Potential manipulation or operator error
        END_IF;
    ELSE
        security_alarm := TRUE;
    END_IF;
    last_secure_setpoint := secure_setpoint;

    // 2. Hot-Standby Failover Logic
    IF is_primary THEN
        active_plc := TRUE;
    ELSIF NOT is_primary AND NOT peer_heartbeat_valid THEN
        active_plc := TRUE; // Takeover
    ELSE
        active_plc := FALSE; // Standby
    END_IF;

    // 3. TMR Voting
    voted_pos := (gps_array[1] + gps_array[2] + gps_array[3]) / 3.0; // Simplified average

    // 4. Kalman Filter (Runs on BOTH Primary and Standby for bumpless transfer)
    est_pos := est_pos + 0.0;
    P_pos := P_pos + 0.01;
    VAR
        K_pos : REAL;
    END_VAR
    K_pos := P_pos / (P_pos + 0.5);
    est_pos := est_pos + K_pos * (voted_pos - est_pos);
    P_pos := (1.0 - K_pos) * P_pos;

    // 5. Thruster Allocation (Only active PLC drives outputs)
    IF active_plc THEN
        VAR
            err_pos : REAL;
        END_VAR
        err_pos := secure_setpoint - est_pos;
        thruster_cmd[1] := err_pos * 20.0;
        thruster_cmd[2] := err_pos * 20.0;
        thruster_cmd[3] := err_pos * 20.0;
    ELSE
        thruster_cmd[1] := 0.0;
        thruster_cmd[2] := 0.0;
        thruster_cmd[3] := 0.0;
    END_IF;
END_FUNCTION_BLOCK
```

Here is the advanced Siemens SCL program implementing adversarial sensor drift detection, HIL digital twin synchronization, and a pre-start autonomous self-test.

```pascal
FUNCTION_BLOCK "DP2_Adversarial_HIL"
VERSION : 3.0
VAR_INPUT
    enable_dp : BOOL;
    gps_array : ARRAY[1..3] OF REAL;
    hil_digital_twin_pos : REAL; // Feedback from HIL simulation
    hil_sync_valid : BOOL;
END_VAR

VAR_OUTPUT
    thruster_cmd : ARRAY[1..3] OF REAL;
    system_state : INT; // 0: Off, 1: Self-Test, 2: Active, 3: Degraded, 4: Fault
    drift_alarm : BOOL;
END_VAR

VAR
    est_pos : REAL;
    P_pos : REAL := 1.0;
    voted_pos : REAL;

    // Self-Test vars
    test_step : INT := 0;
    test_timer : TIME := T#0s;

    // Drift detection vars
    drift_integrator : REAL := 0.0;
END_VAR

BEGIN
    // State Machine
    IF NOT enable_dp THEN
        system_state := 0;
        test_step := 0;
    ELSIF enable_dp AND system_state = 0 THEN
        system_state := 1; // Enter Self-Test
    END_IF;

    // 1. Autonomous Self-Test Routine
    IF system_state = 1 THEN
        // Test thruster responses incrementally without moving vessel significantly
        IF test_step = 0 THEN
            thruster_cmd[1] := 5.0;
            test_step := 1;
        ELSIF test_step = 1 THEN
            thruster_cmd[1] := 0.0;
            test_step := 2;
            system_state := 2; // Test passed, go Active
        END_IF;
        RETURN; // Skip control logic during test
    END_IF;

    // 2. TMR Voting
    voted_pos := (gps_array[1] + gps_array[2] + gps_array[3]) / 3.0;

    // 3. Adversarial Sensor Drift Detection (Spoofing Check)
    // Compare TMR voted position against the Physics-Based Digital Twin (HIL)
    VAR
        twin_deviation : REAL;
    END_VAR
    IF hil_sync_valid THEN
        twin_deviation := voted_pos - hil_digital_twin_pos;
        drift_integrator := drift_integrator + (twin_deviation * 0.1);

        IF ABS(drift_integrator) > 50.0 THEN
            drift_alarm := TRUE;
            system_state := 3; // Degraded state due to possible GPS spoofing
        END_IF;
    ELSE
        system_state := 3; // Degraded if HIL sync lost
    END_IF;

    // 4. Kalman Filter
    est_pos := est_pos + 0.0;
    P_pos := P_pos + 0.01;
    VAR
        K_pos : REAL;
        sensor_feed : REAL;
    END_VAR

    // Graceful degradation: Rely on Digital Twin if GPS is spoofed
    IF drift_alarm AND hil_sync_valid THEN
        sensor_feed := hil_digital_twin_pos;
    ELSE
        sensor_feed := voted_pos;
    END_IF;

    K_pos := P_pos / (P_pos + 0.5);
    est_pos := est_pos + K_pos * (sensor_feed - est_pos);
    P_pos := (1.0 - K_pos) * P_pos;

    // 5. Thruster Allocation
    IF system_state = 2 OR system_state = 3 THEN
        VAR
            err_pos : REAL;
        END_VAR
        err_pos := 0.0 - est_pos; // Assuming setpoint is 0.0 for station keeping

        // If degraded, limit max thrust to prevent erratic runaway
        VAR
            thrust_limit : REAL := 100.0;
        END_VAR
        IF system_state = 3 THEN thrust_limit := 30.0; END_IF;

        thruster_cmd[1] := LIMIT(MN := -thrust_limit, IN := err_pos * 10.0, MX := thrust_limit);
        thruster_cmd[2] := LIMIT(MN := -thrust_limit, IN := err_pos * 10.0, MX := thrust_limit);
        thruster_cmd[3] := LIMIT(MN := -thrust_limit, IN := err_pos * 10.0, MX := thrust_limit);
    ELSE
        thruster_cmd[1] := 0.0;
        thruster_cmd[2] := 0.0;
        thruster_cmd[3] := 0.0;
    END_IF;
END_FUNCTION_BLOCK
```

This logic protects the vessel against subtle GPS spoofing by constantly verifying the physical reality of the sensors against a trusted Digital Twin dynamic model. If an anomaly is detected, it triggers a drift alarm and smoothly degrades into a thrust-limited state, falling back on the HIL model for navigation if necessary.

