IF Breaker_Closed AND Sync_Enable THEN
    FOR i := 1 TO 4 DO
        Total_System_Load := Total_System_Load + Load_Share_In[i];
    END_FOR;
    Average_Load := Total_System_Load / 4.0;
    Load_Error := Average_Load - Active_Power_kW;
ELSE
    Load_Error := 0.0;
END_IF;

