      TakeoverActive : Bool;
   END_VAR
BEGIN
// IEC 62443 RBAC
IF #SCADA_AuthLevel < 2 AND #PN_ControlWord.%X0 THEN
    RETURN; // Unauthorized
END_IF;

// Failover Logic
#WatchdogTimer(IN := NOT #Heartbeat_Primary, PT := T#500ms);
IF NOT #IsPrimaryPLC AND #WatchdogTimer.Q THEN
    #TakeoverActive := TRUE;
END_IF;
END_FUNCTION_BLOCK

