FUNCTION_BLOCK "FB_EngineBlockCNC"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      startMachining : Bool;
      spindleTempSensor : Real; // Coolant temp in C
      toolWearValue : Real; // Measured tool wear in mm
      conveyorStart : Bool;
   END_VAR

   VAR_OUTPUT 
      spindleCoolantValve : Real; // PID Output 0.0 - 100.0%
      toolOffsetActive : Real; // Active offset
      conveyorMotorFwd : Bool;
      conveyorMotorRev : Bool;
   END_VAR

   VAR 
      pidCoolant : "PID_Compact";
      conveyorState : Int; // 0=Stop, 1=Fwd, 2=Rev
      timerConveyor : TON_TIME;
   END_VAR

BEGIN
    // 1. Tool Wear Compensation
    IF #toolWearValue > 0.05 THEN
        #toolOffsetActive := #toolWearValue;
    ELSE
        #toolOffsetActive := 0.0;
    END_IF;

    // 2. Spindle Coolant Temperature PID
    #pidCoolant(
        Setpoint := 22.0, // Target temperature 22C
        Input := #spindleTempSensor,
        Output => #spindleCoolantValve
    );

    // 3. Chip Conveyor Sequencing (Simple Fwd/Rev clearing cycle)
    IF #conveyorStart THEN
        CASE #conveyorState OF
            0: // Stop
                #conveyorState := 1;
            1: // Forward running
                #conveyorMotorFwd := TRUE;
                #conveyorMotorRev := FALSE;
                #timerConveyor(IN := TRUE, PT := T#10s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 2;
                    #timerConveyor(IN := FALSE, PT := T#10s);
                END_IF;
            2: // Reverse (anti-jam)
                #conveyorMotorFwd := FALSE;
                #conveyorMotorRev := TRUE;
                #timerConveyor(IN := TRUE, PT := T#3s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 1;
                    #timerConveyor(IN := FALSE, PT := T#3s);
                END_IF;
        END_CASE;
    ELSE
        #conveyorState := 0;
        #conveyorMotorFwd := FALSE;
        #conveyorMotorRev := FALSE;
        #timerConveyor(IN := FALSE, PT := T#10s);
    END_IF;
END_FUNCTION_BLOCK
