FUNCTION_BLOCK "FB_EngineBlockCNC_Secure"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      startMachining : Bool;
      // Redundant Sensors
      spindleTempSensorA : Real;
      spindleTempSensorB : Real;
      toolWearValue : Real;
      conveyorStart : Bool;
      reqToolChange : Bool;
      targetToolSlot : Int;
      carouselInPosition : Bool;

      pnIoDevice1_Status : Word;

      // Cyber & SCADA
      activeUserRole : Int; // 0=None, 1=Operator, 2=Maintenance, 3=Admin
      opc_ScadaOverrideActive : Bool;
      opc_ScadaCoolantSetpt : Real;
   END_VAR

   VAR_OUTPUT 
      spindleCoolantValve : Real;
      toolOffsetActive : Real;
      conveyorMotorFwd : Bool;
      conveyorMotorRev : Bool;
      carouselIndexFwd : Bool;
      atcReady : Bool;
      alarmWord1 : Word;
      systemFault : Bool;

      // SCADA telemetry
      scada_ActualTemp : Real;
      scada_CurrentToolSlot : Int;
   END_VAR

   VAR 
      pidCoolant : "PID_Compact";
      conveyorState : Int;
      timerConveyor : TON_TIME;
      atcState : Int;
      currentSlot : Int := 1;
      timerATC : TON_TIME;

      selectedTempSensor : Real;
      activeCoolantSetpt : Real;
   END_VAR

BEGIN
    // A. IEC 62443 Role-Based Access Control (RBAC) Check
    IF #activeUserRole = 0 THEN
        // Unauthorized access, halt operations
        #alarmWord1.%X3 := TRUE; // Auth Error
        #systemFault := TRUE;
    END_IF;

    // B. Redundant Sensor Failover Logic
    IF ABS(#spindleTempSensorA - #spindleTempSensorB) > 5.0 THEN
        #alarmWord1.%X4 := TRUE; // Sensor mismatch warning
        // Failover strategy: take the higher reading for safety
        IF #spindleTempSensorA > #spindleTempSensorB THEN
            #selectedTempSensor := #spindleTempSensorA;
        ELSE
            #selectedTempSensor := #spindleTempSensorB;
        END_IF;
    ELSE
        // Average if healthy
        #selectedTempSensor := (#spindleTempSensorA + #spindleTempSensorB) / 2.0;
    END_IF;
    #scada_ActualTemp := #selectedTempSensor; // Telemetry to SCADA

    // C. SCADA OPC UA Setpoint Integration
    IF #opc_ScadaOverrideActive AND (#activeUserRole >= 2) THEN
        #activeCoolantSetpt := #opc_ScadaCoolantSetpt;
    ELSE
        #activeCoolantSetpt := 22.0; // Local default
    END_IF;

    // Diagnostics Matrix
    IF #pnIoDevice1_Status <> 16#0000 THEN
        #alarmWord1.%X0 := TRUE; 
        #systemFault := TRUE;
    END_IF;
    IF #toolWearValue > 0.5 THEN
        #alarmWord1.%X2 := TRUE;
        #systemFault := TRUE;
    END_IF;

    IF #systemFault THEN
        #conveyorMotorFwd := FALSE;
        #conveyorMotorRev := FALSE;
        #carouselIndexFwd := FALSE;
        #spindleCoolantValve := 0.0;
        RETURN; 
    END_IF;

    // 1. Tool Wear
    IF #toolWearValue > 0.05 THEN
        #toolOffsetActive := #toolWearValue;
    ELSE
        #toolOffsetActive := 0.0;
    END_IF;

    // 2. Coolant PID
    #pidCoolant(
        Setpoint := #activeCoolantSetpt,
        Input := #selectedTempSensor,
        Output => #spindleCoolantValve
    );

    // 3. Chip Conveyor
    IF #conveyorStart THEN
        CASE #conveyorState OF
            0: #conveyorState := 1;
            1:
                #conveyorMotorFwd := TRUE; #conveyorMotorRev := FALSE;
                #timerConveyor(IN := TRUE, PT := T#15s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 2; #timerConveyor(IN := FALSE, PT := T#15s);
                END_IF;
            2:
                #conveyorMotorFwd := FALSE; #conveyorMotorRev := TRUE;
                #timerConveyor(IN := TRUE, PT := T#2s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 1; #timerConveyor(IN := FALSE, PT := T#2s);
                END_IF;
        END_CASE;
    ELSE
        #conveyorState := 0; #conveyorMotorFwd := FALSE; #conveyorMotorRev := FALSE;
        #timerConveyor(IN := FALSE, PT := T#15s);
    END_IF;

    // 4. ATC Logic
    #scada_CurrentToolSlot := #currentSlot;
    CASE #atcState OF
        0:
            #atcReady := TRUE; #carouselIndexFwd := FALSE;
            IF #reqToolChange AND (#targetToolSlot <> #currentSlot) AND (#activeUserRole >= 1) THEN
                #atcReady := FALSE; #atcState := 1;
            END_IF;
        1:
            IF NOT #carouselInPosition THEN
                #carouselIndexFwd := TRUE;
            ELSE
                #carouselIndexFwd := FALSE;
                #currentSlot := #targetToolSlot;
                #atcState := 0; // Simplified
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
