      driftAccumulator : Real;
      driftSamples : DInt;
      selfTestState : Int;
      timerSelfTest : TON_TIME;
      internalTempA : Real;
      internalTempB : Real;
   END_VAR

BEGIN
    // I. Hardware-in-the-Loop (HIL) Data Routing
    IF #hilModeActive THEN
        #internalTempA := #hilSim_TempA;
        #internalTempB := #hilSim_TempB;
        // Ignore real hardware I/O faults during simulation
        #alarmWord1.%X0 := FALSE;
    ELSE
        #internalTempA := #spindleTempSensorA;
        #internalTempB := #spindleTempSensorB;
        IF #pnIoDevice1_Status <> 16#0000 THEN
            #alarmWord1.%X0 := TRUE; 
            #systemFault := TRUE;
        END_IF;
    END_IF;

    // II. Automated Startup Self-Test Routine
    IF #triggerSelfTest AND NOT #machineReady THEN
        CASE #selfTestState OF
            0: // Init test
                #selfTestState := 1;
            1: // Test ATC Index
                #carouselIndexFwd := TRUE;
                #timerSelfTest(IN := TRUE, PT := T#2s);
                IF #timerSelfTest.Q THEN
                    #carouselIndexFwd := FALSE;
                    #selfTestState := 2;
                    #timerSelfTest(IN := FALSE, PT := T#2s);
                END_IF;
            2: // Test Conveyor
                #conveyorMotorFwd := TRUE;
                #timerSelfTest(IN := TRUE, PT := T#1s);
                IF #timerSelfTest.Q THEN
                    #conveyorMotorFwd := FALSE;
                    #machineReady := TRUE;
                    #selfTestState := 0;
                    #timerSelfTest(IN := FALSE, PT := T#1s);
                END_IF;
        END_CASE;
        RETURN; // Block normal execution during test
    END_IF;

    IF NOT #machineReady AND NOT #hilModeActive THEN
        // Must pass self-test first
        RETURN;
    END_IF;

    // III. Statistical Sensor Drift Detection
    IF ABS(#internalTempA - #internalTempB) > 0.5 THEN
        #driftAccumulator := #driftAccumulator + (#internalTempA - #internalTempB);
        #driftSamples := #driftSamples + 1;
    END_IF;
    IF #driftSamples > 10000 THEN
        IF ABS(#driftAccumulator / DINT_TO_REAL(#driftSamples)) > 2.0 THEN
            #alarmWord1.%X5 := TRUE; // Long-term sensor drift detected
        END_IF;
        #driftAccumulator := 0.0;
        #driftSamples := 0;
    END_IF;

    // Redundant Sensor Failover Logic
    IF ABS(#internalTempA - #internalTempB) > 5.0 THEN
        #alarmWord1.%X4 := TRUE; // Immediate Sensor mismatch
        IF #internalTempA > #internalTempB THEN
            #selectedTempSensor := #internalTempA;
        ELSE
            #selectedTempSensor := #internalTempB;
        END_IF;
    ELSE
        #selectedTempSensor := (#internalTempA + #internalTempB) / 2.0;
    END_IF;
    #scada_ActualTemp := #selectedTempSensor;

    // IEC 62443 RBAC & SCADA OPC UA Setpoint
    IF #activeUserRole = 0 THEN
        #alarmWord1.%X3 := TRUE; 
        #systemFault := TRUE;
    END_IF;
    IF #opc_ScadaOverrideActive AND (#activeUserRole >= 2) THEN
        #activeCoolantSetpt := #opc_ScadaCoolantSetpt;
    ELSE
        #activeCoolantSetpt := 22.0;
    END_IF;

    IF #toolWearValue > 0.5 THEN
        #alarmWord1.%X2 := TRUE;
        #systemFault := TRUE;
    END_IF;

    IF #systemFault THEN
        #conveyorMotorFwd := FALSE; #conveyorMotorRev := FALSE;
        #spindleCoolantValve := 0.0;
        RETURN; 
    END_IF;

    // Normal Operations (Tool Wear, PID, Conveyor)
    IF #toolWearValue > 0.05 THEN
        #toolOffsetActive := #toolWearValue;
    ELSE
        #toolOffsetActive := 0.0;
    END_IF;

    #pidCoolant(
        Setpoint := #activeCoolantSetpt,
        Input := #selectedTempSensor,
        Output => #spindleCoolantValve
    );

    IF #conveyorStart THEN
        CASE #conveyorState OF
            0: #conveyorState := 1;
            1:
                #conveyorMotorFwd := TRUE; #conveyorMotorRev := FALSE;
                #timerConveyor(IN := TRUE, PT := T#15s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 2; #timerConveyor(IN := FALSE, PT := T#15s);
                END_IF;
            2:
                #conveyorMotorFwd := FALSE; #conveyorMotorRev := TRUE;
                #timerConveyor(IN := TRUE, PT := T#2s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 1; #timerConveyor(IN := FALSE, PT := T#2s);
                END_IF;
        END_CASE;
    ELSE
        #conveyorState := 0; #conveyorMotorFwd := FALSE; #conveyorMotorRev := FALSE;
        #timerConveyor(IN := FALSE, PT := T#15s);
    END_IF;

    // Simplified ATC Logic
    CASE #atcState OF
        0:
            #carouselIndexFwd := FALSE;
            IF #reqToolChange AND (#targetToolSlot <> #currentSlot) AND (#activeUserRole >= 1) THEN
                #atcState := 1;
            END_IF;
        1:
            IF NOT #carouselInPosition THEN
                #carouselIndexFwd := TRUE;
            ELSE
                #carouselIndexFwd := FALSE;
                #currentSlot := #targetToolSlot;
                #atcState := 0; 
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
