            Timer(IN:=FALSE); CurveIndex := CurveIndex + 1;
            IF CurveIndex > 4 THEN State := 15; END_IF;
        END_IF;
        TopPID(SetPoint:=TargetPressure, ProcessVariable:=TopPlatenPressure, ControlVariable=>TopPlatenValve);
        BottomPID(SetPoint:=TargetPressure, ProcessVariable:=BottomPlatenPressure, ControlVariable=>BottomPlatenValve);

    15: // High-Pressure Nitrogen Curing
        SteamValve := FALSE;
        NitrogenInletValve := TRUE;
        IF N2Pressure >= 300.0 THEN State := 18; END_IF;

    18: // Nitrogen Recovery
        NitrogenInletValve := FALSE;
        NitrogenRecoveryValve := TRUE;
        IF N2Pressure < 10.0 THEN State := 20; END_IF;

    20: // Blow-down
        NitrogenRecoveryValve := FALSE; BlowDownValve := TRUE;
        IF BladderPressure < 5.0 THEN State := 30; END_IF;

    30: // Complete
        BlowDownValve := FALSE; State := 0;

    99: // Fault
        SteamValve := FALSE; BlowDownValve := TRUE;
        NitrogenInletValve := FALSE; NitrogenRecoveryValve := FALSE;
        IF NOT EStop THEN State := 0; END_IF;
END_CASE;
