PROGRAM TireCuringPress
VAR
    // I/O & Core
    StartCycle, EStop : BOOL;
    CurrentTemp, TopPlatenPressure, BottomPlatenPressure, BladderPressure, N2Pressure : REAL;
    SteamValve, BlowDownValve, NitrogenInletValve, NitrogenRecoveryValve : BOOL;
    TopPlatenValve, BottomPlatenValve : REAL;
    State : INT := 0;

    // Cybersecurity (IEC 62443 Role-based Access)
    CurrentUserRole : INT; // 0=Guest, 1=Operator, 2=Admin
    ActionPermitted : BOOL;

    // Hot-Standby Failover
    PrimaryHeartbeat : BOOL;
    PartnerHeartbeat : BOOL;
    HeartbeatTimer : TON;
    IsPrimaryActive : BOOL := TRUE;

    // SCADA OPC UA
    ScadaData : SCADA_UDT;
END_VAR

// Role-Based Access Control Interlock
ActionPermitted := (CurrentUserRole >= 1);
IF StartCycle AND NOT ActionPermitted THEN
    StartCycle := FALSE; // Block unauthorized start
END_IF;

// PLC Hot-Standby Failover
HeartbeatTimer(IN:=NOT PartnerHeartbeat, PT:=1000);
IF HeartbeatTimer.Q THEN
    IsPrimaryActive := TRUE; // Partner failed, take over
END_IF;

// SCADA Data Population
ScadaData.SystemState := State;
ScadaData.LiveTemp := CurrentTemp;
ScadaData.N2Level := N2Pressure;

// Only execute control if Primary
IF IsPrimaryActive THEN
    CASE State OF
        0:
            IF StartCycle AND ActionPermitted THEN State := 10; END_IF;
        10:
            SteamValve := TRUE;
            State := 15;
        15:
            SteamValve := FALSE; NitrogenInletValve := TRUE;
            IF N2Pressure >= 300.0 THEN State := 18; END_IF;
        18:
            NitrogenInletValve := FALSE; NitrogenRecoveryValve := TRUE;
            IF N2Pressure < 10.0 THEN State := 20; END_IF;
        20:
            NitrogenRecoveryValve := FALSE; BlowDownValve := TRUE;
            IF BladderPressure < 5.0 THEN State := 30; END_IF;
        30:
            BlowDownValve := FALSE; State := 0;
        99:
            SteamValve := FALSE; BlowDownValve := TRUE;
    END_CASE;
END_IF;
END_PROGRAM

PROGRAM TireCuringPress
VAR
    StartCycle, EStop : BOOL;
    CurrentTemp, TopTemp, BottomTemp, BladderPressure, N2Pressure : REAL;
    SteamValve, BlowDownValve, NitrogenInletValve, NitrogenRecoveryValve : BOOL;
    State : INT := -10; // Start in Self-Test

    // Adversarial Resilience: Sensor Drift Detection
    DriftTolerance : REAL := 5.0;
    DriftDetected : BOOL;

    // HIL Digital Twin Sync
    HIL_SyncActive : BOOL;
    HIL_StateHash : DINT;
    Local_StateHash : DINT;
    TwinMismatchFault : BOOL;

    // Self-Test Routine
    SelfTestTimer : TON;
    SelfTestStep : INT := 0;
    ValvesOK : BOOL;

    IsPrimaryActive : BOOL := TRUE;
END_VAR

// 1. Sensor Drift Detection
IF ABS(TopTemp - BottomTemp) > DriftTolerance AND State > 0 THEN
    DriftDetected := TRUE;
    State := 99; // Abort on sensor degradation
END_IF;

// 2. HIL Digital Twin Synchronization Check
IF HIL_SyncActive THEN
    Local_StateHash := (State * 100) + REAL_TO_DINT(TopTemp);
    IF Local_StateHash <> HIL_StateHash THEN
        TwinMismatchFault := TRUE; // Possible adversarial injection or simulation drift
    END_IF;
END_IF;

IF IsPrimaryActive THEN
    CASE State OF
        -10: // Self-Test Routine (Startup)
            SelfTestTimer(IN:=TRUE, PT:=500);
            IF SelfTestTimer.Q THEN
                SelfTestTimer(IN:=FALSE);
                CASE SelfTestStep OF
                    0: SteamValve := TRUE; SelfTestStep := 1;
                    1: SteamValve := FALSE; BlowDownValve := TRUE; SelfTestStep := 2;
                    2: BlowDownValve := FALSE; ValvesOK := TRUE; State := 0;
                END_CASE;
            END_IF;

        0: // Idle
            IF StartCycle AND ValvesOK AND NOT TwinMismatchFault THEN State := 10; END_IF;
        10:
            SteamValve := TRUE; State := 15;
        15:
            SteamValve := FALSE; NitrogenInletValve := TRUE;
            IF N2Pressure >= 300.0 THEN State := 18; END_IF;
        18:
            NitrogenInletValve := FALSE; NitrogenRecoveryValve := TRUE;
            IF N2Pressure < 10.0 THEN State := 20; END_IF;
        20:
            NitrogenRecoveryValve := FALSE; BlowDownValve := TRUE;
            IF BladderPressure < 5.0 THEN State := 30; END_IF;
        30:
            BlowDownValve := FALSE; State := 0;
        99: // Fault Handler
            SteamValve := FALSE; BlowDownValve := TRUE;
            NitrogenInletValve := FALSE; NitrogenRecoveryValve := FALSE;
    END_CASE;
END_IF;
END_PROGRAM

FUNCTION_BLOCK FB_PaintBooth
TITLE = 'Robotic Paint Booth Control'
VERSION : 1.0

VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    rAtomizerSetpoint : REAL;
    rAtomizerFeedback : REAL;
    rExhaustFlow : REAL;
END_VAR

VAR_OUTPUT
    rAtomizerOutput : REAL;
    bPurgeValve : BOOL;
    bAlarmExhaust : BOOL;
END_VAR

VAR
    instPID : PID_Compact;
    tonPurge : TON;
    iState : INT;
END_VAR

BEGIN
    // State Machine
    IF bStop THEN
        iState := 0;
    ELSIF bStart AND iState = 0 THEN
        iState := 1;
    END_IF;

    // Atomization PID
    instPID(
        Setpoint := rAtomizerSetpoint,
        Input := rAtomizerFeedback,
        Output => rAtomizerOutput
    );

    // Solvent Purge Timing
    tonPurge(IN := (iState = 2), PT := T#5S);
    IF tonPurge.Q THEN
        iState := 1; // Return to ready after purge
    END_IF;
    bPurgeValve := (iState = 2);

    // Exhaust Flow Monitoring
    bAlarmExhaust := (rExhaustFlow < 100.0);
END_FUNCTION_BLOCK

