    State : Int := 0; // 0=Init, 1=Self-Test, 2=Run, 3=Fault
    Drift_Tolerance : Real := 5.0;
    Test_Step : Int := 0;
END_VAR
BEGIN
    // HIL Digital Twin State Synchronization Hook
    IF HIL_Mode_Active THEN
        HIL_State_Sync := REAL_TO_DWORD(PV_Voltage_1) OR SHL(IN:=INT_TO_DWORD(State), N:=16);
    END_IF;

    // Security Check
    IF Auth_Token <> 16#A5A5_5A5A THEN
        State := 3;
        Error_Buffer[0] := 401; // Security Breach
        PWM_Duty_Cycle := 0.0;
        RETURN;
    END_IF;

    // Sensor Drift Detection (Adversarial Robustness)
    IF ABS(PV_Voltage_1 - PV_Voltage_2) > Drift_Tolerance THEN
        State := 3;
        Error_Buffer[1] := 501; // Sensor Drift Detected
        PWM_Duty_Cycle := 0.0;
        RETURN;
    END_IF;

    // State Machine
    CASE State OF
        0: // Init
            IF Enable THEN State := 1; END_IF;

        1: // Pre-Startup Self-Test Routine
            CASE Test_Step OF
                0: // Inject Simulated Overvoltage Fault
                    IF (HIL_Mode_Active AND HIL_Injected_Fault = 1) OR (Grid_Voltage > 500.0) THEN
                        Test_Step := 1;
                    END_IF;
                1: // Verify Thermal Loop
                    IF IGBT_Temp > 90.0 THEN
                        Test_Step := 2;
                    ELSE
                        Test_Step := 2; // Simulated pass
                    END_IF;
                2:
                    Self_Test_Passed := TRUE;
                    State := 2; // Move to Run
            END_CASE;

        2: // Run (MPPT & Grid Sync)
            IF IGBT_Temp > 90.0 THEN
                State := 3;
                Error_Buffer[2] := 101;
            ELSE
                // Simplified MPPT
                PWM_Duty_Cycle := Duty_Cycle; 
                Profinet_Stat_Word := 16#0001; // Running
            END_IF;

        3: // Fault
            PWM_Duty_Cycle := 0.0;
