Here is a Beckhoff ST (Structured Text) program implementing the core control logic for a Wind Turbine. This program handles the overspeed brake, blade pitch PID control, and yaw motor sequencing.

```pascal
PROGRAM MAIN
VAR
    // Inputs
    rWindSpeed : REAL; // m/s
    rRotorSpeed : REAL; // rpm
    rWindDirection : REAL; // degrees (0-360)
    rNacelleDirection : REAL; // degrees (0-360)

    // Outputs
    rPitchAngle : REAL; // degrees
    bYawMotorCW : BOOL;
    bYawMotorCCW : BOOL;
    bOverspeedBrake : BOOL;

    // Internal Variables
    fbPitchPID : FB_PID; // Assuming standard PID function block
    rYawError : REAL;

    // Configurable Parameters
    rMaxRotorSpeed : REAL := 25.0; // rpm threshold for braking
    rYawTolerance : REAL := 5.0; // Deadband in degrees
    rTargetRotorSpeed : REAL := 15.0; // Setpoint for PID
END_VAR

// 1. Overspeed Brake Logic
IF rRotorSpeed > rMaxRotorSpeed THEN
    bOverspeedBrake := TRUE;
    rPitchAngle := 90.0; // Feather blades completely
ELSE
    bOverspeedBrake := FALSE;
END_IF

// 2. Blade Pitch Control PID
IF NOT bOverspeedBrake THEN
    fbPitchPID(
        fSetpoint := rTargetRotorSpeed,
        fActualValue := rRotorSpeed,
        bEnable := TRUE,
        fKp := 2.5,
        fKi := 0.8,
        fKd := 0.2,
        fOutput => rPitchAngle
    );

    IF rPitchAngle < 0.0 THEN
        rPitchAngle := 0.0;
    ELSIF rPitchAngle > 90.0 THEN
        rPitchAngle := 90.0;
    END_IF
END_IF

// 3. Yaw Motor Sequencing
rYawError := rWindDirection - rNacelleDirection;

IF rYawError > 180.0 THEN
    rYawError := rYawError - 360.0;
ELSIF rYawError < -180.0 THEN
    rYawError := rYawError + 360.0;
END_IF

IF ABS(rYawError) > rYawTolerance AND NOT bOverspeedBrake THEN
    IF rYawError > 0 THEN
        bYawMotorCW := TRUE;
        bYawMotorCCW := FALSE;
    ELSE
        bYawMotorCW := FALSE;
        bYawMotorCCW := TRUE;
    END_IF
ELSE
    bYawMotorCW := FALSE;
    bYawMotorCCW := FALSE;
END_IF
