Here is the updated Beckhoff ST program. A moving average filter subsystem has been added to smooth the anemometer and wind vane inputs over time, effectively reducing noisy measurements and preventing rapid, fatigue-inducing oscillations in the yaw motors.

```pascal
PROGRAM MAIN
VAR
    // Inputs
    rRawWindSpeed : REAL; 
    rRawWindDirection : REAL; 
    rRotorSpeed : REAL; 
    rNacelleDirection : REAL; 

    // Outputs
    rPitchAngle : REAL; 
    bYawMotorCW : BOOL;
    bYawMotorCCW : BOOL;
    bOverspeedBrake : BOOL;

    // Filtering Subsystem Variables
    aWindSpeedBuffer : ARRAY[1..100] OF REAL;
    aWindDirBuffer : ARRAY[1..100] OF REAL;
    iFilterIdx : INT := 1;
    rFilteredWindSpeed : REAL;
    rFilteredWindDir : REAL;
    rSumSpeed : REAL;
    rSumDir : REAL;
    i : INT;
    bFilterInitialized : BOOL := FALSE;

    // Controllers & Internal
    fbPitchPID : FB_PID;
    rYawError : REAL;

    // Parameters
    rMaxRotorSpeed : REAL := 25.0; 
    rYawTolerance : REAL := 5.0; 
    rTargetRotorSpeed : REAL := 15.0; 
END_VAR

// 1. Moving Average Filter Subsystem
IF NOT bFilterInitialized THEN
    FOR i := 1 TO 100 DO
        aWindSpeedBuffer[i] := rRawWindSpeed;
        aWindDirBuffer[i] := rRawWindDirection;
    END_FOR
    bFilterInitialized := TRUE;
END_IF

aWindSpeedBuffer[iFilterIdx] := rRawWindSpeed;
aWindDirBuffer[iFilterIdx] := rRawWindDirection;
iFilterIdx := iFilterIdx + 1;
IF iFilterIdx > 100 THEN iFilterIdx := 1; END_IF

rSumSpeed := 0.0;
rSumDir := 0.0;
FOR i := 1 TO 100 DO
    rSumSpeed := rSumSpeed + aWindSpeedBuffer[i];
    rSumDir := rSumDir + aWindDirBuffer[i];
END_FOR
rFilteredWindSpeed := rSumSpeed / 100.0;
rFilteredWindDir := rSumDir / 100.0;

// 2. Overspeed Brake Logic 
IF rRotorSpeed > rMaxRotorSpeed OR rFilteredWindSpeed > 30.0 THEN
    bOverspeedBrake := TRUE;
    rPitchAngle := 90.0; 
ELSE
    bOverspeedBrake := FALSE;
END_IF

// 3. Blade Pitch Control PID
IF NOT bOverspeedBrake THEN
    fbPitchPID(
        fSetpoint := rTargetRotorSpeed, fActualValue := rRotorSpeed, bEnable := TRUE,
        fKp := 2.5, fKi := 0.8, fKd := 0.2, fOutput => rPitchAngle
    );
    IF rPitchAngle < 0.0 THEN rPitchAngle := 0.0;
    ELSIF rPitchAngle > 90.0 THEN rPitchAngle := 90.0; END_IF
END_IF

// 4. Yaw Motor Sequencing 
rYawError := rFilteredWindDir - rNacelleDirection;
IF rYawError > 180.0 THEN rYawError := rYawError - 360.0;
ELSIF rYawError < -180.0 THEN rYawError := rYawError + 360.0; END_IF

IF ABS(rYawError) > rYawTolerance AND NOT bOverspeedBrake THEN
    IF rYawError > 0 THEN bYawMotorCW := TRUE; bYawMotorCCW := FALSE;
    ELSE bYawMotorCW := FALSE; bYawMotorCCW := TRUE; END_IF
ELSE
    bYawMotorCW := FALSE; bYawMotorCCW := FALSE;
END_IF
