END_VAR

// 1. Cybersecurity: Role-Based Access Control
CASE iUserLevel OF
    0: stScadaData.sActiveRole := 'GUEST';
    1: stScadaData.sActiveRole := 'OPERATOR';
    2: stScadaData.sActiveRole := 'ADMIN';
ELSE
    stScadaData.sActiveRole := 'UNAUTHORIZED';
    iUserLevel := 0; 
END_CASE

// 2. High Availability & Failover Logic
iHeartbeatOut := iHeartbeatOut + 1; 
IF iHeartbeatOut > 32767 THEN iHeartbeatOut := 0; END_IF

tHeartbeatTimer(IN := (iHeartbeatIn = iLastHeartbeat), PT := T#500MS);
IF tHeartbeatTimer.Q THEN
    bRedundancyFailover := TRUE; 
ELSE
    bRedundancyFailover := FALSE;
END_IF
iLastHeartbeat := iHeartbeatIn;

IF NOT bPrimaryActive AND NOT bRedundancyFailover THEN
    RETURN; // Standby PLC yields control
END_IF

// 3. Overspeed Brake 
IF rRotorSpeed > 25.0 OR bDriveFault OR bRedundancyFailover THEN
    bOverspeedBrake := TRUE;
    rPitchAngleSetpoint := 90.0;
ELSE
    bOverspeedBrake := FALSE;
END_IF

