PROGRAM MAIN
VAR
    // Base I/O
    rRawWindSpeed AT %I* : REAL; 
    rRotorSpeed AT %I* : REAL; 
    rPitchAngleSetpoint AT %Q* : REAL; 
    bOverspeedBrake AT %Q* : BOOL;

    // HIL Digital Twin State Estimator
    rTwinEstimatedRotorSpeed : REAL;
    rSensorDriftResidual : REAL;
    bAdversarialDriftDetected : BOOL;

    // Daily Self-Test Routine
    fbSysTime : GETSYSTEMTIME;
    stSysTime : TIMESTRUCT;
    bSelfTestActive : BOOL;
    iSelfTestState : INT := 0;
    tTestTimer : TON;
    bTestPassed : BOOL;

    // Controllers & Faults
    fbPitchPID : FB_PID;
    bSystemFault : BOOL;
END_VAR

// 1. HIL Digital Twin State Estimator (Adversarial Drift Detection)
rTwinEstimatedRotorSpeed := (rRawWindSpeed * 1.5) - (rPitchAngleSetpoint * 0.2); 
IF rTwinEstimatedRotorSpeed < 0 THEN rTwinEstimatedRotorSpeed := 0; END_IF

rSensorDriftResidual := ABS(rRotorSpeed - rTwinEstimatedRotorSpeed);

IF rSensorDriftResidual > 8.0 THEN 
    bAdversarialDriftDetected := TRUE;
    bSystemFault := TRUE;
ELSE
    bAdversarialDriftDetected := FALSE;
END_IF

// 2. Daily Automated Self-Test Routine
fbSysTime(timeLoDW => , timeHiDW => );
// Pseudocode for time check: if 02:00:00 and low wind
IF rRawWindSpeed < 5.0 AND NOT bSystemFault THEN
    // Placeholder trigger logic for 2AM
    // bSelfTestActive := TRUE;
END_IF

IF bSelfTestActive THEN
    CASE iSelfTestState OF
        0: 
            bOverspeedBrake := TRUE; 
            rPitchAngleSetpoint := 90.0; 
            tTestTimer(IN:=TRUE, PT:=T#5S);
            IF tTestTimer.Q THEN
                iSelfTestState := 1;
                tTestTimer(IN:=FALSE);
            END_IF

        1: 
            IF rRotorSpeed < 1.0 THEN bTestPassed := TRUE;
            ELSE bTestPassed := FALSE; bSystemFault := TRUE; END_IF
            iSelfTestState := 2;

        2: 
            bSelfTestActive := FALSE;
            iSelfTestState := 0;
            bOverspeedBrake := FALSE;
    END_CASE
    RETURN; 
END_IF

// 3. Normal Control Logic
IF rRotorSpeed > 25.0 OR bSystemFault THEN
    bOverspeedBrake := TRUE;
    rPitchAngleSetpoint := 90.0;
ELSE
    bOverspeedBrake := FALSE;
END_IF

IF NOT bOverspeedBrake AND NOT bSelfTestActive THEN
    fbPitchPID(
        fSetpoint := 15.0, fActualValue := rRotorSpeed, bEnable := TRUE,
        fKp := 2.5, fKi := 0.8, fKd := 0.2, fOutput => rPitchAngleSetpoint
    );
    IF rPitchAngleSetpoint < 0.0 THEN rPitchAngleSetpoint := 0.0;
    ELSIF rPitchAngleSetpoint > 90.0 THEN rPitchAngleSetpoint := 90.0; END_IF
END_IF
```

Here is the base Allen-Bradley Structured Text (ST) program for a BESS calculating State of Charge (SOC) and executing Peak Shaving grid injection.

```pascal
// BESS SOC and Peak Shaving Base Logic

// 1. SOC Calculation (Coulomb Counting)
// Delta_Time_Hours is based on the periodic task scan time (e.g., 100ms = 0.0000277 hours)
Delta_Time_Hours := (Task_Scan_Time_ms / 1000.0) / 3600.0;
SOC := SOC + ((Battery_Current_A * Delta_Time_Hours) / Total_Capacity_Ah) * 100.0;

// Limit SOC bounds
IF SOC > 100.0 THEN 
    SOC := 100.0; 
END_IF;
IF SOC < 0.0 THEN 
    SOC := 0.0; 
END_IF;

// 2. Peak Shaving Logic
IF (Grid_Load_kW > Peak_Limit_kW) AND (SOC > Min_SOC_Limit) THEN
    // Grid demand exceeds limit, discharge battery to shave peak
    Inject_Power_kW := Grid_Load_kW - Peak_Limit_kW;

    // Ensure we do not exceed BESS max inverter rating
    IF Inject_Power_kW > BESS_Max_Power_kW THEN
        Inject_Power_kW := BESS_Max_Power_kW;
    END_IF;

    Discharge_Cmd := 1;
    Charge_Cmd := 0;

ELSIF (Grid_Load_kW < (Peak_Limit_kW - Hysteresis_kW)) AND (SOC < Max_SOC_Limit) THEN
    // Grid load is low, opportunistic charging
    Inject_Power_kW := 0.0;
    Discharge_Cmd := 0;
    Charge_Cmd := 1;

ELSE
    // Idle state
    Inject_Power_kW := 0.0;
    Discharge_Cmd := 0;
    Charge_Cmd := 0;
END_IF;
```

