// 2. Thermal Management Sub-system
Max_Cell_Temp := 0.0;
Min_Cell_Temp := 100.0;

// Calculate max, min, and gradient temperatures across the battery pack
FOR i := 0 TO (Num_Cells - 1) DO
    IF Cell_Temp[i] > Max_Cell_Temp THEN 
        Max_Cell_Temp := Cell_Temp[i]; 
    END_IF;
    IF Cell_Temp[i] < Min_Cell_Temp THEN 
        Min_Cell_Temp := Cell_Temp[i]; 
    END_IF;
END_FOR;

Temp_Gradient := Max_Cell_Temp - Min_Cell_Temp;

// Thermal Runaway Prevention
IF Max_Cell_Temp > Critical_Temp_Limit THEN
    Emergency_Stop := 1;
    HVAC_Cmd := 1;
    BESS_Fault := 1;
ELSIF (Max_Cell_Temp > Warning_Temp_Limit) OR (Temp_Gradient > Max_Gradient_Limit) THEN
    HVAC_Cmd := 1; // Active cooling engaged
ELSE
    HVAC_Cmd := 0;
END_IF;

// 3. Peak Shaving Logic (Disabled if Emergency Stop is active)
IF NOT Emergency_Stop THEN
    IF (Grid_Load_kW > Peak_Limit_kW) AND (SOC > Min_SOC_Limit) THEN
        Inject_Power_kW := Grid_Load_kW - Peak_Limit_kW;
        IF Inject_Power_kW > BESS_Max_Power_kW THEN
            Inject_Power_kW := BESS_Max_Power_kW;
        END_IF;
        Discharge_Cmd := 1;
        Charge_Cmd := 0;
    ELSIF (Grid_Load_kW < (Peak_Limit_kW - Hysteresis_kW)) AND (SOC < Max_SOC_Limit) THEN
        Inject_Power_kW := 0.0;
        Discharge_Cmd := 0;
        Charge_Cmd := 1;
    ELSE
        Inject_Power_kW := 0.0;
        Discharge_Cmd := 0;
        Charge_Cmd := 0;
    END_IF;
ELSE
    Inject_Power_kW := 0.0;
    Discharge_Cmd := 0;
    Charge_Cmd := 0;
END_IF;
