Here is the complete, robust Allen-Bradley ST program including sensor drift detection, HIL digital twin synchronization, and a daily contactor self-test routine.

```pascal
// BESS Ultimate Control: Adversarial Resilience, HIL, Self-Test, Cyber, EIP

// 1. Hardware-in-the-Loop (HIL) Digital Twin Synchronization
IF HIL_Mode_Enable THEN
    HIL_Sync_Tx := HIL_Sync_Tx + 1;
    IF HIL_Sync_Rx <> Last_HIL_Sync_Rx THEN
        HIL_Comm_Active := 1;
        HIL_Timeout_TON.TimerEnable := 0;
    ELSE
        HIL_Timeout_TON.TimerEnable := 1;
    END_IF;
    Last_HIL_Sync_Rx := HIL_Sync_Rx;

    TON(HIL_Timeout_TON);
    IF HIL_Timeout_TON.DN THEN
        Alarms.Warning[4] := 1; // HIL Desync / Timeout
    END_IF;
END_IF;

// 2. Sensor Drift Detection (Redundant Current Sensors)
Current_Diff := ABS(Sensor1_Current_A - Sensor2_Current_A);
IF Current_Diff > Max_Drift_Allowed_A THEN
    Alarms.Warning[5] := 1; // Sensor drift detected
    // Fallback to the sensor value closer to the known inverter state
    IF Discharge_Cmd OR Charge_Cmd THEN
        Battery_Current_A := Sensor1_Current_A; // Assume Primary is trusted
    ELSE
        Battery_Current_A := 0.0;
    END_IF;
ELSE
    Alarms.Warning[5] := 0;
    Battery_Current_A := (Sensor1_Current_A + Sensor2_Current_A) / 2.0; // Average
END_IF;

// 3. Daily Contactor Self-Test Routine
// Trigger daily at 2:00 AM if not currently shaving peaks
IF (System_Clock.Hour = 2) AND (System_Clock.Minute = 0) AND NOT Self_Test_Done AND NOT Discharge_Cmd THEN
    Self_Test_Active := 1;
END_IF;

IF Self_Test_Active THEN
    Peak_Shave_Lockout := 1; // Prevent operational state changes
    Contactor_Test_TON.TimerEnable := 1;
    Main_Contactor_Cmd := 1;

    TON(Contactor_Test_TON);
    IF Contactor_Test_TON.DN THEN
        IF Main_Contactor_Aux_FB = 1 THEN
            Self_Test_Passed := 1;
            Alarms.Critical[2] := 0;
        ELSE
            Self_Test_Passed := 0;
            Alarms.Critical[2] := 1; // Contactor failed to close
            Emergency_Stop := 1;
        END_IF;
        Self_Test_Active := 0;
        Self_Test_Done := 1;
        Main_Contactor_Cmd := 0; // Return to open state
        Peak_Shave_Lockout := 0;
    END_IF;
ELSE
    Contactor_Test_TON.TimerEnable := 0;
END_IF;

// Reset self-test daily flag at 3:00 AM
IF System_Clock.Hour = 3 THEN Self_Test_Done := 0; END_IF;

// 4. Hot-Standby Failover
Heartbeat_Tx := Heartbeat_Tx + 1;
IF Last_Partner_Heartbeat = Partner_Heartbeat_Rx THEN Failover_TON.TimerEnable := 1;
ELSE Failover_TON.TimerEnable := 0; END_IF;
Last_Partner_Heartbeat := Partner_Heartbeat_Rx;
TON(Failover_TON);
IF Failover_TON.DN THEN System_Is_Primary := 1; Alarms.Critical[1] := 1; END_IF;

// 5. IEC 62443 RBAC
IF HMI_Setpoint_Write_Req THEN
    IF (Active_User_Role = ROLE_ADMIN) THEN
        Peak_Limit_kW := HMI_New_Peak_Limit;
    ELSE
        Alarms.Warning[3] := 1; Security_Event_Log := 1;
    END_IF;
    HMI_Setpoint_Write_Req := 0;
END_IF;

// 6. SOC & Thermal
Delta_Time_Hours := (Task_Scan_Time_ms / 1000.0) / 3600.0;
SOC := SOC + ((Battery_Current_A * Delta_Time_Hours) / Total_Capacity_Ah) * 100.0;
IF SOC > 100.0 THEN SOC := 100.0; ELSIF SOC < 0.0 THEN SOC := 0.0; END_IF;

Max_Cell_Temp := 0.0;
FOR i := 0 TO (Num_Cells - 1) DO
    IF Cell_Temp[i] > Max_Cell_Temp THEN Max_Cell_Temp := Cell_Temp[i]; END_IF;
END_FOR;
IF Max_Cell_Temp > Critical_Temp_Limit THEN Emergency_Stop := 1; HVAC_Cmd := 1; Alarms.Fatal[0] := 1; END_IF;

// 7. Peak Shaving Logic
IF System_Is_Primary AND NOT Emergency_Stop AND NOT Peak_Shave_Lockout THEN
    IF (Grid_Load_kW > Peak_Limit_kW) AND (SOC > Min_SOC_Limit) THEN
        Inject_Power_kW := Grid_Load_kW - Peak_Limit_kW;
        Discharge_Cmd := 1; Charge_Cmd := 0;
    ELSIF (Grid_Load_kW < (Peak_Limit_kW - Hysteresis_kW)) AND (SOC < Max_SOC_Limit) THEN
        Inject_Power_kW := 0.0; Discharge_Cmd := 0; Charge_Cmd := 1;
    ELSE
        Inject_Power_kW := 0.0; Discharge_Cmd := 0; Charge_Cmd := 0;
    END_IF;
END_IF;

// 8. SCADA Data
SCADA_Real_Data[0] := SOC;
SCADA_Real_Data[1] := Grid_Load_kW;
SCADA_Real_Data[2] := Max_Cell_Temp;
