FUNCTION_BLOCK "HydroDam_Control"
VAR_INPUT
    Set_Freq : REAL;
    Act_Freq : REAL;
    Water_Level : REAL;
    Penstock_Flow : REAL;
END_VAR
VAR_OUTPUT
    Valve_Pos : REAL;
    Sync_Breaker : BOOL;
END_VAR
VAR
    PID_Valve : "PID_Compact";
    Freq_Error : REAL;
END_VAR
BEGIN
    #Freq_Error := #Set_Freq - #Act_Freq;
    IF ABS(#Freq_Error) < 0.05 THEN
        #Sync_Breaker := TRUE;
    ELSE
        #Sync_Breaker := FALSE;
    END_IF;
    #PID_Valve(Setpoint := #Water_Level * 10.0, Feedback := #Penstock_Flow, Output => #Valve_Pos);
END_FUNCTION_BLOCK
