FUNCTION_BLOCK "FB_Clarifier_Secure_Control"
TITLE = 'Secure Clarifier Control with Redundancy & SCADA'
VERSION : '1.3'

VAR_INPUT
    SCADA_Start : Bool;
    SCADA_Stop : Bool;
    SCADA_Reset : Bool;
    SCADA_Heartbeat : Bool;
    User_Role : Int; // 0=Guest, 1=Operator, 2=Admin, 3=Maintenance
    Local_Override : Bool;
    Partner_PLC_Active : Bool; // For failover redundancy
    Partner_PLC_Fault : Bool;
    Sludge_Blanket_Level : Real; 
    Level_Sensor_Error : Bool; 
    Influent_Flow : Real; 
    Influent_Turbidity : Real; 
    VFD_Rake_In : "UDT_Profinet_VFD_In";
    VFD_Pump_In : "UDT_Profinet_VFD_In";
END_VAR

VAR_OUTPUT
    VFD_Rake_Out : "UDT_Profinet_VFD_Out";
    VFD_Pump_Out : "UDT_Profinet_VFD_Out";
    Dosing_Pump_Speed : Real; 
    Torque_Warning : Bool;
    System_Fault : Bool;
    Diagnostic_Code : Int;
    SCADA_Comm_Loss : Bool;
    Active_PLC_Role : Bool; // TRUE if this PLC is primary
END_VAR

VAR
    System_Active : Bool;
    Pump_Active : Bool;
    Rake_Torque : Real;
    Heartbeat_Timer : TON_TIME;
    Prev_Heartbeat : Bool;
    Start_Cmd_Validated : Bool;
    Stop_Cmd_Validated : Bool;
    Reset_Cmd_Validated : Bool;
END_VAR

BEGIN
    // PLC Redundancy Role Election
    IF NOT #Partner_PLC_Active OR #Partner_PLC_Fault THEN
        #Active_PLC_Role := TRUE;
    ELSE
        #Active_PLC_Role := TRUE; 
    END_IF;

    // Proceed only if this PLC is active
    IF NOT #Active_PLC_Role THEN
        RETURN;
    END_IF;

    // IEC 62443: SCADA Heartbeat Monitoring
    #Heartbeat_Timer(IN := (#SCADA_Heartbeat = #Prev_Heartbeat), PT := T#5s);
    IF #Heartbeat_Timer.Q THEN
        #SCADA_Comm_Loss := TRUE;
    ELSE
        #SCADA_Comm_Loss := FALSE;
    END_IF;
    #Prev_Heartbeat := #SCADA_Heartbeat;

    // IEC 62443: Role-Based Command Validation
    IF NOT #Local_Override AND NOT #SCADA_Comm_Loss THEN
        #Start_Cmd_Validated := #SCADA_Start AND (#User_Role = 1 OR #User_Role = 2);
        #Stop_Cmd_Validated := #SCADA_Stop AND (#User_Role = 1 OR #User_Role = 2);
        #Reset_Cmd_Validated := #SCADA_Reset AND (#User_Role = 2 OR #User_Role = 3);
    ELSIF #Local_Override THEN
        #Start_Cmd_Validated := #SCADA_Start; 
        #Stop_Cmd_Validated := #SCADA_Stop;
        #Reset_Cmd_Validated := #SCADA_Reset;
    ELSE
        #Start_Cmd_Validated := FALSE;
        #Stop_Cmd_Validated := FALSE;
        #Reset_Cmd_Validated := FALSE;
    END_IF;

    #Rake_Torque := #VFD_Rake_In.Actual_Torque;

    // Diagnostics
    IF #VFD_Rake_In.Comm_Error OR #VFD_Pump_In.Comm_Error THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 5;
    ELSIF #Level_Sensor_Error THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 4;
    ELSIF #Rake_Torque >= 95.0 THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 1;
    ELSIF #VFD_Rake_In.Fault_Active THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 2;
    ELSIF #VFD_Pump_In.Fault_Active THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 3;
    END_IF;

    IF #Reset_Cmd_Validated AND NOT (#VFD_Rake_In.Comm_Error OR #VFD_Pump_In.Comm_Error OR #Level_Sensor_Error OR #VFD_Rake_In.Fault_Active OR #VFD_Pump_In.Fault_Active OR (#Rake_Torque >= 95.0)) THEN
        #System_Fault := FALSE;
        #Diagnostic_Code := 0;
        #Torque_Warning := FALSE;
    END_IF;

    // Fail-safe Shutdown on SCADA loss (if configured) or Fault
    IF #Stop_Cmd_Validated OR #System_Fault OR #SCADA_Comm_Loss THEN
        #System_Active := FALSE;
    ELSIF #Start_Cmd_Validated AND NOT #System_Fault AND NOT #SCADA_Comm_Loss THEN
        #System_Active := TRUE;
    END_IF;

    IF #Rake_Torque >= 80.0 AND NOT #System_Fault THEN
        #Torque_Warning := TRUE;
    ELSIF #Rake_Torque < 75.0 THEN
        #Torque_Warning := FALSE;
    END_IF;

    // Profinet Control
    IF #System_Active THEN
        #VFD_Rake_Out.Control_Word := 16#047F;
        #VFD_Rake_Out.Speed_Setpoint := 16#4000;

        IF #Sludge_Blanket_Level >= 2.5 THEN
            #Pump_Active := TRUE;
        ELSIF #Sludge_Blanket_Level <= 1.0 THEN
            #Pump_Active := FALSE;
        END_IF;
    ELSE
        #VFD_Rake_Out.Control_Word := 16#047E;
        #VFD_Rake_Out.Speed_Setpoint := 0;
        #Pump_Active := FALSE;
    END_IF;

    IF #Pump_Active THEN
        #VFD_Pump_Out.Control_Word := 16#047F;
        #VFD_Pump_Out.Speed_Setpoint := 16#4000;
    ELSE
        #VFD_Pump_Out.Control_Word := 16#047E;
        #VFD_Pump_Out.Speed_Setpoint := 0;
    END_IF;

    // Dosing
    IF #System_Active THEN
        #Dosing_Pump_Speed := LIMIT(MN:=0.0, IN:=((#Influent_Flow * #Influent_Turbidity * 0.5) / 1000.0) * 100.0, MX:=100.0);
    ELSE
        #Dosing_Pump_Speed := 0.0;
    END_IF;

END_FUNCTION_BLOCK
