    SCADA_Heartbeat : Bool;
    User_Role : Int; 
    HIL_Simulation_Mode : Bool; // Activates Digital Twin Mode
    Sludge_Level_Sensor_1 : Real; 
    Sludge_Level_Sensor_2 : Real; 
    Simulated_Sludge_Level : Real; // HIL Input
    Simulated_Torque : Real;       // HIL Input
    VFD_Rake_In : "UDT_Profinet_VFD_In";
    VFD_Pump_In : "UDT_Profinet_VFD_In";
END_VAR

VAR_OUTPUT
    VFD_Rake_Out : "UDT_Profinet_VFD_Out";
    VFD_Pump_Out : "UDT_Profinet_VFD_Out";
    System_Fault : Bool;
    Diagnostic_Code : Int; // + 6=Sensor Drift, 7=Self-Test Failed, 8=Twin Deviation
    Self_Test_Active : Bool;
    Self_Test_Passed : Bool;
    Effective_Sludge_Level : Real;
END_VAR

VAR
    System_Active : Bool;
    Pump_Active : Bool;
    Rake_Torque : Real;
    Start_Cmd_Validated : Bool;
    Drift_Deviation : Real;
    Twin_Level_Deviation : Real;
    Self_Test_Step : Int;
    Self_Test_Timer : TON_TIME;
END_VAR

BEGIN
    // Role Validation (Simplified)
    #Start_Cmd_Validated := #SCADA_Start AND (#User_Role = 1 OR #User_Role = 2);

    // Select I/O based on HIL Mode
    IF #HIL_Simulation_Mode THEN
        #Effective_Sludge_Level := #Simulated_Sludge_Level;
        #Rake_Torque := #Simulated_Torque;
    ELSE
        // Sensor Drift Detection (Dual Redundant Sensors)
        #Drift_Deviation := ABS(#Sludge_Level_Sensor_1 - #Sludge_Level_Sensor_2);
        IF #Drift_Deviation > 0.5 THEN // 0.5m allowable drift
            #System_Fault := TRUE;
            #Diagnostic_Code := 6;
        END_IF;
        #Effective_Sludge_Level := (#Sludge_Level_Sensor_1 + #Sludge_Level_Sensor_2) / 2.0; // Average
        #Rake_Torque := #VFD_Rake_In.Actual_Torque;

        // Digital Twin Deviation Check (running concurrently in background)
        #Twin_Level_Deviation := ABS(#Effective_Sludge_Level - #Simulated_Sludge_Level);
        IF #Twin_Level_Deviation > 1.0 AND #System_Active THEN
            #System_Fault := TRUE;
            #Diagnostic_Code := 8;
        END_IF;
    END_IF;

    // Self-Test Routine on Startup
    IF #Start_Cmd_Validated AND NOT #System_Active AND NOT #System_Fault AND NOT #Self_Test_Passed THEN
        #Self_Test_Active := TRUE;
    END_IF;

    IF #Self_Test_Active THEN
        #Self_Test_Timer(IN:=TRUE, PT:=T#3s);
        IF #Self_Test_Step = 0 THEN
            // Pulse VFDs briefly to check comms
            #VFD_Rake_Out.Control_Word := 16#047F;
            #VFD_Rake_Out.Speed_Setpoint := 16#0100; // tiny speed
            IF #Self_Test_Timer.Q THEN
                IF #VFD_Rake_In.Status_Word <> 0 THEN // Assume some valid status
                    #Self_Test_Step := 1;
                    #Self_Test_Timer(IN:=FALSE, PT:=T#3s); // Reset
                ELSE
                    #System_Fault := TRUE;
                    #Diagnostic_Code := 7;
                    #Self_Test_Active := FALSE;
                END_IF;
            END_IF;
        ELSIF #Self_Test_Step = 1 THEN
            // Test passed
            #Self_Test_Passed := TRUE;
            #Self_Test_Active := FALSE;
            #System_Active := TRUE;
            #VFD_Rake_Out.Speed_Setpoint := 0;
        END_IF;
    ELSIF #Start_Cmd_Validated AND #Self_Test_Passed AND NOT #System_Fault THEN
        #System_Active := TRUE;
    END_IF;

    IF #SCADA_Stop OR #System_Fault THEN
        #System_Active := FALSE;
        #Self_Test_Passed := FALSE; // Require self-test next start
        #Self_Test_Step := 0;
    END_IF;

    // Normal Control Operation
    IF #System_Active AND NOT #Self_Test_Active THEN
        #VFD_Rake_Out.Control_Word := 16#047F;
        #VFD_Rake_Out.Speed_Setpoint := 16#4000;

        IF #Effective_Sludge_Level >= 2.5 THEN
            #Pump_Active := TRUE;
        ELSIF #Effective_Sludge_Level <= 1.0 THEN
            #Pump_Active := FALSE;
        END_IF;
    ELSE
        IF NOT #Self_Test_Active THEN
            #VFD_Rake_Out.Control_Word := 16#047E;
            #VFD_Rake_Out.Speed_Setpoint := 0;
        END_IF;
        #Pump_Active := FALSE;
    END_IF;

    IF #Pump_Active THEN
        #VFD_Pump_Out.Control_Word := 16#047F;
        #VFD_Pump_Out.Speed_Setpoint := 16#4000;
    ELSE
        #VFD_Pump_Out.Control_Word := 16#047E;
        #VFD_Pump_Out.Speed_Setpoint := 0;
    END_IF;

END_FUNCTION_BLOCK
