PROGRAM MAIN
VAR
    eState : (INIT, STANDBY, PRIMING, PRESSURIZING, RUNNING, CIP_MODE, SHUTDOWN, FAULT);
    eCIPState : (CIP_IDLE, CIP_FLUSH, CIP_DOSING, CIP_SOAK, CIP_RINSE);

    // Standard IO
    bStartCmd, bStopCmd, bResetCmd, bStartCIP : BOOL;
    fInletPressure, fPermeateFlow, fBrinePressure, fConductivity : REAL;

    // Outputs
    bFeedPumpCmd, bHighPressurePumpCmd, bPermeateValve : BOOL;
    fERDSpeedCmd, fDosingPumpSpeedCmd : REAL;
    bCIPValveInlet, bCIPValveOutlet : BOOL;

    // Timers & Controls
    fbTimerMain : TON;
    fbTimerCIP : TON;
    fCIPTargetCond : REAL := 15.0; // mS/cm
END_VAR

// Main State Machine
CASE eState OF
    INIT:
        bFeedPumpCmd := FALSE; bHighPressurePumpCmd := FALSE; fERDSpeedCmd := 0.0;
        bCIPValveInlet := FALSE; bCIPValveOutlet := FALSE; fDosingPumpSpeedCmd := 0.0;
        eState := STANDBY;

    STANDBY:
        IF bStartCmd THEN eState := PRIMING;
        ELSIF bStartCIP THEN eState := CIP_MODE; eCIPState := CIP_FLUSH; END_IF

    PRIMING:
        bFeedPumpCmd := TRUE;
        fbTimerMain(IN:=TRUE, PT:=T#10S);
        IF fbTimerMain.Q AND fInletPressure > 2.0 THEN
            fbTimerMain(IN:=FALSE); eState := PRESSURIZING;
        END_IF

    PRESSURIZING:
        bHighPressurePumpCmd := TRUE;
        fbTimerMain(IN:=TRUE, PT:=T#30S);
        IF fbTimerMain.Q THEN
            fbTimerMain(IN:=FALSE); bPermeateValve := TRUE; eState := RUNNING;
        END_IF

    RUNNING:
        IF bStopCmd THEN eState := SHUTDOWN; END_IF

    CIP_MODE:
        CASE eCIPState OF
            CIP_IDLE:
                // Wait
            CIP_FLUSH:
                bCIPValveInlet := TRUE; bCIPValveOutlet := TRUE; bFeedPumpCmd := TRUE;
                fbTimerCIP(IN:=TRUE, PT:=T#5M);
                IF fbTimerCIP.Q THEN fbTimerCIP(IN:=FALSE); eCIPState := CIP_DOSING; END_IF

            CIP_DOSING:
                fDosingPumpSpeedCmd := 50.0; // Start dosing
                IF fConductivity >= fCIPTargetCond THEN
                    fDosingPumpSpeedCmd := 10.0; // Maintain
                    fbTimerCIP(IN:=TRUE, PT:=T#10M);
                    IF fbTimerCIP.Q THEN fbTimerCIP(IN:=FALSE); fDosingPumpSpeedCmd := 0.0; eCIPState := CIP_SOAK; END_IF
                END_IF

            CIP_SOAK:
                bFeedPumpCmd := FALSE;
                fbTimerCIP(IN:=TRUE, PT:=T#30M);
                IF fbTimerCIP.Q THEN fbTimerCIP(IN:=FALSE); eCIPState := CIP_RINSE; END_IF

            CIP_RINSE:
                bFeedPumpCmd := TRUE;
                IF fConductivity < 0.5 THEN // Clean water threshold
                    bCIPValveInlet := FALSE; bCIPValveOutlet := FALSE; bFeedPumpCmd := FALSE;
                    eState := STANDBY;
                END_IF
        END_CASE

    SHUTDOWN:
        bHighPressurePumpCmd := FALSE; bPermeateValve := FALSE; fERDSpeedCmd := 0.0;
        IF fBrinePressure < 2.0 THEN bFeedPumpCmd := FALSE; eState := STANDBY; END_IF

    FAULT:
        // Safe state
        bFeedPumpCmd := FALSE; bHighPressurePumpCmd := FALSE; fERDSpeedCmd := 0.0;
        fDosingPumpSpeedCmd := 0.0; bCIPValveInlet := FALSE; bCIPValveOutlet := FALSE;
        IF bResetCmd THEN eState := INIT; END_IF
END_CASE
