    fPermeateFlow_A : REAL;
    fPermeateFlow_B : REAL;
    fFlowDeviation : REAL;
    bSensorDriftAlarm : BOOL;

    // Self-Test Routine
    bStartSelfTest : BOOL;
    eSelfTestState : (TEST_IDLE, TEST_VALVES, TEST_DRIVES_LOW_SPEED, TEST_COMPLETE, TEST_FAIL);
    fbTestTimer : TON;

    // Failover, Comm, Core
    bIsActivePLC : BOOL;
    eState : INT; 
    bFeedPumpCmd, bHighPressurePumpCmd, bPermeateValve : BOOL;
END_VAR

IF NOT bIsActivePLC THEN RETURN; END_IF

// 1. Sensor Drift Detection (Redundancy check)
fFlowDeviation := ABS(fPermeateFlow_A - fPermeateFlow_B);
IF fFlowDeviation > 5.0 THEN // > 5 m3/h diff
    bSensorDriftAlarm := TRUE;
ELSE
    bSensorDriftAlarm := FALSE;
END_IF

// 2. Hardware-in-the-Loop (HIL) Data Sync
aHilStateData[0] := INT_TO_REAL(eState);
aHilStateData[1] := fPermeateFlow_A;
aHilStateData[2] := fPermeateFlow_B;
aHilStateData[3] := SEL(bFeedPumpCmd, 0.0, 1.0);
aHilStateData[4] := SEL(bHighPressurePumpCmd, 0.0, 1.0);

// 3. Self-Test Diagnostic Routine
IF bStartSelfTest AND eState = 1 THEN // Only in STANDBY
    eState := 10; // SELF TEST MODE
    eSelfTestState := TEST_VALVES;
END_IF

IF eState = 10 THEN
    CASE eSelfTestState OF
        TEST_VALVES:
            bPermeateValve := TRUE;
            fbTestTimer(IN:=TRUE, PT:=T#2S);
            IF fbTestTimer.Q THEN
                bPermeateValve := FALSE;
                fbTestTimer(IN:=FALSE);
                eSelfTestState := TEST_DRIVES_LOW_SPEED;
            END_IF

        TEST_DRIVES_LOW_SPEED:
            bFeedPumpCmd := TRUE; // Assume drives limit speed in test mode via safe-torque configuration
            fbTestTimer(IN:=TRUE, PT:=T#5S);
            IF fbTestTimer.Q THEN
                bFeedPumpCmd := FALSE;
                fbTestTimer(IN:=FALSE);
                eSelfTestState := TEST_COMPLETE;
            END_IF

        TEST_COMPLETE:
            eState := 1; // Back to STANDBY
            bStartSelfTest := FALSE;

        TEST_FAIL:
            eState := 99; // FAULT
    END_CASE
END_IF

// 4. Main State Control (Abbreviated)
CASE eState OF
    1: // STANDBY
        // Normal standby logic
    99: // FAULT
        bFeedPumpCmd := FALSE; bHighPressurePumpCmd := FALSE; bPermeateValve := FALSE;
