```pascal
FUNCTION_BLOCK "Dairy_Pasteurizer_Depth"
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      CIP_Mode : Bool; // Clean-In-Place mode active
      ProductTemp : Real;
      HeatingMediumTemp : Real;
      RegenSectionTemp : Real; // Temp after regenerative heat exchanger
      SetpointTemp : Real;
   END_VAR

   VAR_OUTPUT
      HeatingValveOut : Real;
      ForwardFlowValve : Bool;
      DivertFlowValve : Bool;
      SystemAlarm : Bool;
      CIP_Active_Indication : Bool;
      RegenEfficiencyWarning : Bool;
   END_VAR

   VAR
      PID_Master : "PID_Compact";
      PID_Slave : "PID_Compact";
      MasterOutSetpoint : Real;
      LegalTempMet : Bool;
      DivertTimer : TON;
      State : Int;
   END_VAR

   VAR_CONSTANT
      STATE_OFF := 0;
      STATE_PROD := 1;
      STATE_CIP := 2;
   END_VAR

BEGIN
   // State Machine
   IF #CIP_Mode THEN
       #State := #STATE_CIP;
   ELSIF #Enable THEN
       #State := #STATE_PROD;
   ELSE
       #State := #STATE_OFF;
   END_IF;

   CASE #State OF
       #STATE_OFF:
           #HeatingValveOut := 0.0;
           #ForwardFlowValve := FALSE;
           #DivertFlowValve := TRUE;
           #CIP_Active_Indication := FALSE;

       #STATE_PROD:
           #CIP_Active_Indication := FALSE;
           // Cascade PID
           #PID_Master(Reset := FALSE, Setpoint := #SetpointTemp, Input := #ProductTemp, Output => #MasterOutSetpoint);
           #PID_Slave(Reset := FALSE, Setpoint := #MasterOutSetpoint, Input := #HeatingMediumTemp, Output => #HeatingValveOut);

           // Flow Divert
           #LegalTempMet := (#ProductTemp >= #SetpointTemp);
           #DivertTimer(IN := #LegalTempMet, PT := T#15s);

           IF #DivertTimer.Q THEN
               #ForwardFlowValve := TRUE;
               #DivertFlowValve := FALSE;
           ELSE
               #ForwardFlowValve := FALSE;
               #DivertFlowValve := TRUE;
           END_IF;

           // Regenerative Efficiency Check (Expected pre-heat temp)
           #RegenEfficiencyWarning := (#RegenSectionTemp < 50.0); // Arbitrary warning threshold

       #STATE_CIP:
           #CIP_Active_Indication := TRUE;
           // During CIP, PID controls for cleaning temp (e.g., 85 C)
           #PID_Master(Reset := FALSE, Setpoint := 85.0, Input := #ProductTemp, Output => #MasterOutSetpoint);
           #PID_Slave(Reset := FALSE, Setpoint := #MasterOutSetpoint, Input := #HeatingMediumTemp, Output => #HeatingValveOut);

           // Force Flow Divert Valve to toggle for cleaning both paths (managed by external CIP sequencer, default to open both if supported, or cycle)
           #ForwardFlowValve := TRUE;
           #DivertFlowValve := TRUE;
           #RegenEfficiencyWarning := FALSE;
   END_CASE;
END_FUNCTION_BLOCK
```

