```pascal
TYPE "UDT_Profinet_Status"
    STRUCT
        Running : Bool;
        CIP_Active : Bool;
        ForwardFlow : Bool;
        CurrentTemp : Real;
        FaultCode : Int;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "Dairy_Pasteurizer_Breadth"
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      CIP_Mode : Bool;
      ProductTemp_IW : Int; // Raw analog input (PIW)
      HeatingMediumTemp_IW : Int; 
      SetpointTemp : Real;
   END_VAR

   VAR_OUTPUT
      HeatingValveOut : Real;
      ForwardFlowValve : Bool;
      DivertFlowValve : Bool;
      PN_Status : "UDT_Profinet_Status"; // Mapped to Profinet DB/Output
   END_VAR

   VAR
      PID_Master : "PID_Compact";
      PID_Slave : "PID_Compact";
      MasterOutSetpoint : Real;
      DivertTimer : TON;
      ProductTemp : Real;
      HeatingMediumTemp : Real;
      SensorFault : Bool;
   END_VAR

BEGIN
   // Sensor Diagnostics & Scaling (Assuming 0-27648 = 0-100.0 C)
   #SensorFault := FALSE;
   #PN_Status.FaultCode := 0;

   // Wire break check (Under-range) or Over-range
   IF #ProductTemp_IW < 0 OR #ProductTemp_IW > 27648 THEN
       #SensorFault := TRUE;
       #PN_Status.FaultCode := 1; // Product Temp Fault
   END_IF;

   IF #HeatingMediumTemp_IW < 0 OR #HeatingMediumTemp_IW > 27648 THEN
       #SensorFault := TRUE;
       #PN_Status.FaultCode := 2; // Heating Temp Fault
   END_IF;

   // Scale inputs if valid
   IF NOT #SensorFault THEN
       #ProductTemp := INT_TO_REAL(#ProductTemp_IW) / 27648.0 * 100.0;
       #HeatingMediumTemp := INT_TO_REAL(#HeatingMediumTemp_IW) / 27648.0 * 100.0;
   ELSE
       #ProductTemp := 0.0;
       #HeatingMediumTemp := 0.0;
   END_IF;

   // Main Logic
   IF #SensorFault THEN
       // Fail-safe state
       #HeatingValveOut := 0.0;
       #ForwardFlowValve := FALSE;
       #DivertFlowValve := TRUE;
       #PID_Master(Reset := TRUE);
       #PID_Slave(Reset := TRUE);
   ELSIF #CIP_Mode THEN
       #PID_Master(Reset := FALSE, Setpoint := 85.0, Input := #ProductTemp, Output => #MasterOutSetpoint);
       #PID_Slave(Reset := FALSE, Setpoint := #MasterOutSetpoint, Input := #HeatingMediumTemp, Output => #HeatingValveOut);
       #ForwardFlowValve := TRUE;
       #DivertFlowValve := TRUE;
   ELSIF #Enable THEN
       #PID_Master(Reset := FALSE, Setpoint := #SetpointTemp, Input := #ProductTemp, Output => #MasterOutSetpoint);
       #PID_Slave(Reset := FALSE, Setpoint := #MasterOutSetpoint, Input := #HeatingMediumTemp, Output => #HeatingValveOut);

       #DivertTimer(IN := (#ProductTemp >= #SetpointTemp), PT := T#15s);
       IF #DivertTimer.Q THEN
           #ForwardFlowValve := TRUE;
           #DivertFlowValve := FALSE;
       ELSE
           #ForwardFlowValve := FALSE;
           #DivertFlowValve := TRUE;
       END_IF;
   ELSE
       #HeatingValveOut := 0.0;
       #ForwardFlowValve := FALSE;
       #DivertFlowValve := TRUE;
   END_IF;

   // Profinet Data Mapping
   #PN_Status.Running := #Enable AND NOT #SensorFault;
   #PN_Status.CIP_Active := #CIP_Mode;
   #PN_Status.ForwardFlow := #ForwardFlowValve;
   #PN_Status.CurrentTemp := #ProductTemp;
END_FUNCTION_BLOCK
```

### Reasoning & Architecture

**Cascade PID Tuning:**
The master PID controls the product temperature (slow dynamics) by manipulating the setpoint of the slave PID. The slave PID controls the heating medium temperature (fast dynamics). This cascade setup rejects disturbances in the steam/hot water supply before they affect the product. Tuning rules:
- **Slave PID (Heating Medium):** Tuned aggressively (high Proportional gain, short Integral time) to rapidly correct steam fluctuations.
- **Master PID (Product Temp):** Tuned conservatively (lower P gain, longer I time) to prevent overshoot of the pasteurization temperature, which could burn the product.

**Safety Interlock Sequence:**
The Flow Divert Valve (FDV) is the critical safety component. It must fail to the "Divert" position to prevent unpasteurized milk from reaching the finished product tank. The sequence requires the product to be at or above the legal setpoint for a strict continuous 15 seconds (holding tube time) before the FDV opens to the forward path.

### Siemens SCL Code

```pascal
FUNCTION_BLOCK "Dairy_Pasteurizer_Reasoning"
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      CIP_Mode : Bool;
      ProdTempA_IW : Int; // Redundant Sensor A
      ProdTempB_IW : Int; // Redundant Sensor B
      HeatingTemp_IW : Int;
      SCADA_Setpoint : Real;
      SCADA_Handshake : Bool;
      SecurityKey : DInt; // IEC 62443 Basic Access Control
   END_VAR

   VAR_OUTPUT
      HeatingValveOut : Real;
      ForwardFlowValve : Bool;
      DivertFlowValve : Bool;
      SCADA_Heartbeat : Bool;
   END_VAR

   VAR
      PID_Master : "PID_Compact";
      PID_Slave : "PID_Compact";
      MasterOutSetpoint : Real;
      DivertTimer : TON;
      ProductTemp : Real;
      HeatingMediumTemp : Real;
      SensorFaultA : Bool;
      SensorFaultB : Bool;
      ActiveSetpoint : Real := 72.0;
      ToggleBit : Bool;
   END_VAR

BEGIN
   // IEC 62443 Parameter Access Control
   // Only accept SCADA setpoint if accompanied by correct security key (simplified role-based access)
   IF #SecurityKey = 16#A5A5_5A5A THEN
       IF #SCADA_Setpoint >= 70.0 AND #SCADA_Setpoint <= 80.0 THEN
           #ActiveSetpoint := #SCADA_Setpoint;
       END_IF;
   END_IF;

   // Dual-Redundant Sensor Failover
   #SensorFaultA := (#ProdTempA_IW < 0 OR #ProdTempA_IW > 27648);
   #SensorFaultB := (#ProdTempB_IW < 0 OR #ProdTempB_IW > 27648);

   IF NOT #SensorFaultA AND NOT #SensorFaultB THEN
       // Average if both healthy
       #ProductTemp := ((INT_TO_REAL(#ProdTempA_IW) + INT_TO_REAL(#ProdTempB_IW)) / 2.0) / 27648.0 * 100.0;
   ELSIF NOT #SensorFaultA THEN
       // Failover to A
       #ProductTemp := INT_TO_REAL(#ProdTempA_IW) / 27648.0 * 100.0;
   ELSIF NOT #SensorFaultB THEN
       // Failover to B
       #ProductTemp := INT_TO_REAL(#ProdTempB_IW) / 27648.0 * 100.0;
   ELSE
       #ProductTemp := 0.0; // Both failed
   END_IF;

   #HeatingMediumTemp := INT_TO_REAL(#HeatingTemp_IW) / 27648.0 * 100.0;

   // SCADA Handshake / Heartbeat
   #ToggleBit := NOT #ToggleBit;
   #SCADA_Heartbeat := #SCADA_Handshake AND #ToggleBit;

   // Process Control
   IF (#SensorFaultA AND #SensorFaultB) OR NOT #Enable THEN
       // Failsafe
       #HeatingValveOut := 0.0;
       #ForwardFlowValve := FALSE;
       #DivertFlowValve := TRUE;
       #PID_Master(Reset := TRUE);
       #PID_Slave(Reset := TRUE);
   ELSE
       #PID_Master(Reset := FALSE, Setpoint := #ActiveSetpoint, Input := #ProductTemp, Output => #MasterOutSetpoint);
       #PID_Slave(Reset := FALSE, Setpoint := #MasterOutSetpoint, Input := #HeatingMediumTemp, Output => #HeatingValveOut);

       #DivertTimer(IN := (#ProductTemp >= #ActiveSetpoint), PT := T#15s);
       IF #DivertTimer.Q THEN
           #ForwardFlowValve := TRUE;
           #DivertFlowValve := FALSE;
       ELSE
           #ForwardFlowValve := FALSE;
           #DivertFlowValve := TRUE;
       END_IF;
   END_IF;
END_FUNCTION_BLOCK
```

Here is the final advanced Siemens SCL implementation incorporating Adversarial/Edge-case features: HIL simulation, continuous sensor drift detection, and an automated FDV self-test routine.

```pascal
FUNCTION_BLOCK "Dairy_Pasteurizer_Adversarial"
VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      ProdTempA_IW : Int;
      ProdTempB_IW : Int;
      HIL_Mode : Bool; // Hardware-in-the-Loop simulation active
      HIL_SimTempA : Real; // Simulated temperature from digital twin
      HIL_SimTempB : Real;
      SecurityKey : DInt;
      StartSelfTest : Bool;
   END_VAR

   VAR_OUTPUT
      ForwardFlowValve : Bool;
      DivertFlowValve : Bool;
      DriftAlarm : Bool;
      SelfTestActive : Bool;
      SelfTestPassed : Bool;
   END_VAR

   VAR
      TempA_Real : Real;
      TempB_Real : Real;
      ProductTemp : Real;
      DriftTimer : TON;
      TestStep : Int;
      TestTimer : TON;
   END_VAR

BEGIN
   // HIL Digital Twin Synchronization
   IF #HIL_Mode AND (#SecurityKey = 16#A5A5_5A5A) THEN
       // Bypass physical I/O, inject simulation data
       #TempA_Real := #HIL_SimTempA;
       #TempB_Real := #HIL_SimTempB;
   ELSE
       // Use physical I/O
       #TempA_Real := INT_TO_REAL(#ProdTempA_IW) / 27648.0 * 100.0;
       #TempB_Real := INT_TO_REAL(#ProdTempB_IW) / 27648.0 * 100.0;
   END_IF;

   // Sensor Drift Detection (Adversarial check)
   // If sensors deviate by more than 0.5 degrees for over 10 seconds, flag drift
   #DriftTimer(
       IN := (ABS(#TempA_Real - #TempB_Real) > 0.5),
       PT := T#10s
   );
   #DriftAlarm := #DriftTimer.Q;

   // Failover Logic
   IF #DriftAlarm THEN
       // In drift, default to the lower (safer) temperature reading to guarantee pasteurization
       IF #TempA_Real < #TempB_Real THEN
           #ProductTemp := #TempA_Real;
       ELSE
           #ProductTemp := #TempB_Real;
       END_IF;
   ELSE
       #ProductTemp := (#TempA_Real + #TempB_Real) / 2.0;
   END_IF;

   // Automated Self-Test Routine for FDV
   IF #StartSelfTest AND NOT #Enable THEN
       #SelfTestActive := TRUE;
       #TestStep := 1;
   END_IF;

   IF #SelfTestActive THEN
       #TestTimer(IN := (#TestStep > 0), PT := T#5s);

       CASE #TestStep OF
           1: // Force Divert
               #ForwardFlowValve := FALSE;
               #DivertFlowValve := TRUE;
               IF #TestTimer.Q THEN
                   #TestStep := 2;
                   #TestTimer(IN := FALSE, PT := T#5s);
               END_IF;
           2: // Force Forward (Dry test)
               #ForwardFlowValve := TRUE;
               #DivertFlowValve := FALSE;
               IF #TestTimer.Q THEN
                   #TestStep := 3;
               END_IF;
           3: // Complete
               #SelfTestPassed := TRUE;
               #SelfTestActive := FALSE;
               #TestStep := 0;
               #ForwardFlowValve := FALSE;
               #DivertFlowValve := TRUE;
       END_CASE;
   ELSE
       // Normal Operation Mode
       #SelfTestPassed := FALSE;
       IF NOT #Enable THEN
           #ForwardFlowValve := FALSE;
           #DivertFlowValve := TRUE;
       ELSE
           // Simplified normal logic for brevity
           IF #ProductTemp >= 72.0 THEN
               #ForwardFlowValve := TRUE;
               #DivertFlowValve := FALSE;
           ELSE
               #ForwardFlowValve := FALSE;
               #DivertFlowValve := TRUE;
           END_IF;
       END_IF;
   END_IF;

END_FUNCTION_BLOCK
```

