            IF NOT bCapAppliedOk THEN
                bRejectGate := TRUE;
            ELSE
                bRejectGate := FALSE;
            END_IF;
        ELSE
            rFillerSpeed := 0.0;
            bConveyorActive := FALSE;
            bFillerValveOpen := FALSE;
            bCapSorterActive := FALSE;
            bCapperDown := FALSE;
        END_IF;
        IF bStopProcess THEN
            eState := IDLE;
