        IF bStartProcess AND bEcNetworkOk AND NOT bCIPMode THEN
            eState := PRODUCTION;
        END_IF;
    PRODUCTION:
        bPumpActive := TRUE;
        IF bStopProcess THEN
            eState := IDLE;
        END_IF;
    FAULT:
        bPumpActive := FALSE;
        bFillerValveOpen := FALSE;
        bConveyorActive := FALSE;
        IF bEcNetworkOk AND NOT bEmergencyStop THEN
            eState := IDLE;
        END_IF;
END_CASE;
