FUNCTION_BLOCK "WetBench_Profinet_Diagnostics"
VAR_INPUT
    bWafer_Present : Bool;
    bExhaust_Running : Bool;
    rTemp_PV : Real;
    PN_Cmd : "UDT_Profinet_Cmd";
END_VAR
VAR_OUTPUT
    bHF_Valve : Bool;
    bDI_Valve : Bool;
    rHeater_Output : Real;
    PN_Status : "UDT_Profinet_Status";
END_VAR
VAR
    tTimer : TON;
    PID_Temp : PID_Compact;
    iState : Int;
    bWarn_Temp : Bool;
    bCrit_Exhaust : Bool;
END_VAR

BEGIN
    // Diagnostics
    bWarn_Temp := (rTemp_PV > 26.0) OR (rTemp_PV < 24.0);
    bCrit_Exhaust := NOT bExhaust_Running;

    IF PN_Cmd.Ack_Alarms THEN
        bCrit_Exhaust := FALSE; // Reset latch if needed
    END_IF;

    PN_Status.Active_Warning := bWarn_Temp;
    PN_Status.Active_Critical := bCrit_Exhaust;
    PN_Status.State := iState;

    // PID Temp
    PID_Temp(Setpoint := 25.0, Input := rTemp_PV, Output => rHeater_Output);

    IF PN_Cmd.Stop_Cmd OR bCrit_Exhaust THEN
        iState := 99;
    END_IF;

    CASE iState OF
        0: // Idle
            bHF_Valve := FALSE;
            bDI_Valve := FALSE;
            PN_Status.Process_Complete := FALSE;
            IF PN_Cmd.Start_Cmd AND bWafer_Present AND NOT bCrit_Exhaust THEN
                iState := 10;
            END_IF;

        10: // HF Dosing
            bHF_Valve := TRUE;
            tTimer(IN:=TRUE, PT:=T#30s);
            IF tTimer.Q THEN
                bHF_Valve := FALSE;
                tTimer(IN:=FALSE, PT:=T#30s);
                iState := 20;
            END_IF;

        20: // DI Rinse
            bDI_Valve := TRUE;
            tTimer(IN:=TRUE, PT:=T#60s);
            IF tTimer.Q THEN
                bDI_Valve := FALSE;
                tTimer(IN:=FALSE, PT:=T#60s);
                iState := 30;
            END_IF;

        30: // Complete
            PN_Status.Process_Complete := TRUE;
            IF NOT PN_Cmd.Start_Cmd THEN
                iState := 0;
            END_IF;

        99: // Error
            bHF_Valve := FALSE;
            bDI_Valve := FALSE;
            IF NOT bCrit_Exhaust AND NOT PN_Cmd.Start_Cmd THEN
                iState := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
