FUNCTION_BLOCK "WetBench_Secure_Failover"
VAR_INPUT
    SCADA : "UDT_SCADA_Data";
    bPumpA_Fault : Bool;
    PN_Cmd_Start : Bool;
END_VAR
VAR_OUTPUT
    bPumpA_Cmd : Bool;
    bPumpB_Cmd : Bool;
    bParameter_Locked : Bool;
END_VAR
VAR
    iState : Int;
    rActive_Temp_SP : Real;
END_VAR

BEGIN
    // IEC 62443 RBAC: Only Engineer or Admin can change Setpoint
    IF SCADA.User_Role >= 2 THEN
        rActive_Temp_SP := SCADA.Target_Temp;
        bParameter_Locked := FALSE;
    ELSE
        bParameter_Locked := TRUE;
    END_IF;

    // Failover Logic for HF Pump
    IF iState = 10 THEN
        IF NOT bPumpA_Fault THEN
            bPumpA_Cmd := TRUE;
            bPumpB_Cmd := FALSE;
            SCADA.PumpA_Active := TRUE;
            SCADA.PumpB_Active := FALSE;
        ELSE
            bPumpA_Cmd := FALSE;
            bPumpB_Cmd := TRUE; // Failover
            SCADA.PumpA_Active := FALSE;
            SCADA.PumpB_Active := TRUE;
        END_IF;
    ELSE
        bPumpA_Cmd := FALSE;
        bPumpB_Cmd := FALSE;
        SCADA.PumpA_Active := FALSE;
        SCADA.PumpB_Active := FALSE;
    END_IF;

    // Simplified State Machine
    SCADA.Process_State := iState;
    CASE iState OF
        0: 
            IF PN_Cmd_Start THEN iState := 10; END_IF;
        10:
            // Dosing logic with external failover
            IF NOT PN_Cmd_Start THEN iState := 0; END_IF;
    END_CASE;
END_FUNCTION_BLOCK
