```pascal
FUNCTION_BLOCK "WetBench_Adversarial_HIL"
VAR_INPUT
    bSim_Mode : Bool;         // HIL Digital Twin Mode
    rHF_Conc_Physical : Real; // Physical IO
    rHF_Conc_Sim : Real;      // Simulation IO
    bStart_Sequence : Bool;
END_VAR
VAR_OUTPUT
    bSystem_Ready : Bool;
    bDrift_Alarm : Bool;
    iState : Int;
    bValve_Test_Cmd : Bool;
END_VAR
VAR
    rHF_Conc_Active : Real;
    rHF_Conc_History : ARRAY[1..10] OF Real;
    iIdx : Int := 1;
    tTestTimer : TON;
END_VAR

BEGIN
    // HIL Digital Twin Sync: Bypass Physical IO
    IF bSim_Mode THEN
        rHF_Conc_Active := rHF_Conc_Sim;
    ELSE
        rHF_Conc_Active := rHF_Conc_Physical;
    END_IF;

    // Sensor Drift Detection (Moving average baseline check vs current)
    rHF_Conc_History[iIdx] := rHF_Conc_Active;
    iIdx := (iIdx MOD 10) + 1;

    IF ABS(rHF_Conc_Active - rHF_Conc_History[iIdx]) > 5.0 THEN
        bDrift_Alarm := TRUE; // >5% drift detected
    ELSE
        bDrift_Alarm := FALSE;
    END_IF;

    // State Machine with Self-Test Routine
    CASE iState OF
        0: // Idle
            bSystem_Ready := FALSE;
            bValve_Test_Cmd := FALSE;
            IF bStart_Sequence AND NOT bDrift_Alarm THEN
                iState := 5; // Go to Self-Test
            END_IF;

        5: // Self-Test Routine (Check valves before HF)
            bValve_Test_Cmd := TRUE; // Pulse valves quickly
            tTestTimer(IN:=TRUE, PT:=T#2s);
            IF tTestTimer.Q THEN
                bValve_Test_Cmd := FALSE;
                tTestTimer(IN:=FALSE, PT:=T#2s);
                bSystem_Ready := TRUE; // Passed
                iState := 10;
            END_IF;

        10: // Process start
            // Dosing and Rinse logic continues...
            IF NOT bStart_Sequence THEN
                iState := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
