        Primary_Fan_Cmd := TRUE;
        Standby_Fan_Cmd := FALSE;
    ELSIF Primary_Fan_Fault AND NOT Standby_Fan_Fault THEN
        Primary_Fan_Cmd := FALSE;
        Standby_Fan_Cmd := TRUE;
    ELSE
        Primary_Fan_Cmd := FALSE;
        Standby_Fan_Cmd := FALSE;
        System_Fault_Word.6 := 1; // Both fans failed
    END_IF;

    // Pressure Control
    IF Primary_Fan_Cmd OR Standby_Fan_Cmd THEN
        PID_Pressure.PV := Room_Pressure;
        PID_Pressure.SP := Target_Pressure;
        PID_Pressure();
        Active_Fan_Speed := PID_Pressure.CV;
    END_IF;

ELSE
    Primary_Fan_Cmd := FALSE;
    Standby_Fan_Cmd := FALSE;
    Active_Fan_Speed := 0.0;
END_IF;

IF (HEPA_Diff_Pressure >= HEPA_Max_DP) THEN System_Fault_Word.4 := 1; END_IF;

END_PROGRAM
