    IF fVibPhase >= 0.0 AND fVibPhase < 90.0 THEN bFluidInjectionValve[3] := TRUE;
    ELSIF fVibPhase >= 90.0 AND fVibPhase < 180.0 THEN bFluidInjectionValve[4] := TRUE;
