            tDischargeDuration(IN := FALSE);
            tRunTime(IN := FALSE);
            nState := 2;
        END_IF
    4: // Decel
        fSpeedSetpoint := fSpeedSetpoint - 10.0;
        IF fSpeedFeedback <= 5.0 THEN nState := 0; END_IF
    5: // Fault
        bDriveEnable := FALSE;
        fSpeedSetpoint := 0.0;
        bDischargeValve := FALSE;
        IF bReset AND fVibAmp < 5.0 THEN
            bVibAlarm := FALSE;
            nState := 0;
        END_IF
END_CASE

