PROGRAM Distillation_Reasoning
VAR
    SCADA : SCADA_Interface;
    SecurityKey : DINT := 16#A5A5;
    LastHeartbeat : DINT;
    CommLossTimer : TON;
    SCADA_Comm_Loss : BOOL;

    IsPrimaryController : BOOL;
    SyncData : ARRAY[0..10] OF REAL;

    RefluxRatioSP : REAL := 2.5;
    SysFault : BOOL;
END_VAR

IF NOT IsPrimaryController THEN
    RefluxRatioSP := SyncData[0];
    RETURN;
END_IF;

CommLossTimer(IN := (SCADA.Heartbeat = LastHeartbeat), PT := T#5s);
SCADA_Comm_Loss := CommLossTimer.Q;
LastHeartbeat := SCADA.Heartbeat;

IF SCADA.WriteReq THEN
    IF SCADA.WriteUnlockKey = SecurityKey THEN
        IF (SCADA.NewRefluxRatioSP >= 1.0) AND (SCADA.NewRefluxRatioSP <= 5.0) THEN
            RefluxRatioSP := SCADA.NewRefluxRatioSP;
            SCADA.WriteAck := TRUE;
        END_IF;
    END_IF;
    SCADA.WriteReq := FALSE;
END_IF;

SyncData[0] := RefluxRatioSP;

SCADA.StatusFault := SysFault OR SCADA_Comm_Loss;

END_PROGRAM
