    fExhaustHumid        : LREAL;

    // Drift Detection
    fbMovingAvg          : FB_MovingAverage; // Assumed custom block
    fFilteredHumid       : LREAL;
    fDriftThreshold      : LREAL := 2.5; // % RH
    bSensorDriftAlarm    : BOOL;

    // Pre-start Self-Test
    bSelfTestInit        : BOOL;
    nTestState           : INT;
    fbTestTimeout        : TON;
    bTestPassed          : BOOL;

    // Actuator Feedback
    bHeaterContactorFdbk AT %I* : BOOL;
END_VAR

// 1. Digital Twin Bidirectional Sync
IF bHIL_ModeActive THEN
    // Use simulated data from Digital Twin
    fExhaustHumid := fHIL_SimExhaustHumid;
    // Send actuator commands back to HIL...
ELSE
    // Use physical IO
END_IF

// 2. Sensor Drift Detection (Moving Average Comparison)
fbMovingAvg(fInput := fExhaustHumid, nWindowSize := 100, fAverage => fFilteredHumid);
IF ABS(fExhaustHumid - fFilteredHumid) > fDriftThreshold THEN
    bSensorDriftAlarm := TRUE;
    // Dispatch Tc3_EventLogger Critical Alarm
END_IF

// 3. Pre-Start Self-Test Routine
CASE nTestState OF
    1: // INIT
        IF bSelfTestInit THEN
            bTestPassed := FALSE;
            nTestState := 2;
        END_IF

    2: // CHECK_HEATER
        // Assert HeaterCmd := TRUE;
        fbTestTimeout(IN:=TRUE, PT:=T#2S);
        IF bHeaterContactorFdbk THEN
            // Assert HeaterCmd := FALSE;
            fbTestTimeout(IN:=FALSE);
            nTestState := 3;
        ELSIF fbTestTimeout.Q THEN
            nTestState := 99; // FAIL
        END_IF

    3: // CHECK_BLOWER
        // Similar check for blower feedback...
        nTestState := 10; // PASS

    10: // PASS
        bTestPassed := TRUE;
        bSelfTestInit := FALSE;

    99: // FAIL
        bTestPassed := FALSE;
END_CASE

// 4. Main Sequence
IF bTestPassed THEN
    // Standard execution...
END_IF
