FUNCTION_BLOCK "FB_Autoclave_Cure_Base"
TITLE = 'Aerospace Autoclave Base'
VERSION : '1.0'

VAR_INPUT
    bStart_Cycle : Bool;
    rAct_Temp : Real;
    rAct_Pressure : Real;
    rAct_N2_Level : Real;
END_VAR

VAR_OUTPUT
    bCmd_Heater : Bool;
    bCmd_PressValve : Bool;
    bCmd_N2_Purge : Bool;
    iStep_ID : Int;
END_VAR

VAR
    iState : Int;
    tDwell_Timer : TON_TIME;
END_VAR

BEGIN
    CASE iState OF
        0: // Idle
            IF bStart_Cycle THEN iState := 10; END_IF;
        10: // N2 Purge Phase
            bCmd_N2_Purge := TRUE;
            IF rAct_N2_Level > 95.0 THEN
                bCmd_N2_Purge := FALSE;
                iState := 20;
            END_IF;
        20: // Heat and Pressurize
            bCmd_Heater := (rAct_Temp < 180.0);
            bCmd_PressValve := (rAct_Pressure < 7.0);
            IF (rAct_Temp >= 180.0) AND (rAct_Pressure >= 7.0) THEN
                iState := 30;
            END_IF;
        30: // Dwell Phase
            tDwell_Timer(IN := TRUE, PT := T#120M);
            bCmd_Heater := (rAct_Temp < 180.0);
            bCmd_PressValve := (rAct_Pressure < 7.0);
            IF tDwell_Timer.Q THEN
                bCmd_Heater := FALSE;
                bCmd_PressValve := FALSE;
                iState := 40;
            END_IF;
        40: // Cool Down Phase
            IF rAct_Temp < 50.0 THEN
                iState := 0;
                tDwell_Timer(IN := FALSE, PT := T#0S);
            END_IF;
    END_CASE;
    iStep_ID := iState;
END_FUNCTION_BLOCK
