VAR_INPUT
    Start : Bool;
    Stop : Bool;
    PN_Status_Word : Word;
    Sensor_Raw_Tuyere : Int;
    Sensor_Raw_TopGas : Int;
END_VAR

VAR_OUTPUT
    PN_Control_Word : Word;
    Fault_Code : DInt;
    System_Ready : Bool;
END_VAR

BEGIN
    // Profinet Status Check
    IF (#PN_Status_Word AND 16#0001) = 0 THEN
        #Fault_Code := 1001; // PN Link Down
        #System_Ready := FALSE;
    ELSE
        #System_Ready := TRUE;
    END_IF;

    // Diagnostics
    IF #Sensor_Raw_Tuyere > 27648 OR #Sensor_Raw_Tuyere < -27648 THEN
        #Fault_Code := 2001; // Tuyere Sensor Wire Break/Overrange
    END_IF;
    IF #Sensor_Raw_TopGas > 27648 OR #Sensor_Raw_TopGas < -27648 THEN
        #Fault_Code := 2002; // Top Gas Sensor Wire Break/Overrange
    END_IF;

    // Profinet Control
    IF #System_Ready AND #Fault_Code = 0 THEN
        #PN_Control_Word := 16#0001; // Run OK
    ELSE
        #PN_Control_Word := 16#0002; // Fault
    END_IF;
END_FUNCTION_BLOCK
