    // 5. Update SCADA Telemetry
    #SCADA.PV_Level_Active := #Active_Level_PV;
    #SCADA.Sts_Running := #State_Running;
    #SCADA.Sts_AgitatorCmd := (#PN_VFD_Control = 16#047F);

