TYPE "UDT_HIL_DigitalTwin"
    STRUCT
        HIL_Mode_Active : Bool;
        Sim_Level_PV : Real;
        Sim_Torque_PV : Real;
        Max_Allowed_Deviation : Real;
        Alm_TwinMismatch : Bool;
