FUNCTION_BLOCK "FlotationCell_M4"
VERSION : 0.1
   VAR_INPUT 
      PN_Raw_Ultrasonic_A : Int; 
      PN_Raw_Ultrasonic_B : Int; 
      SCADA_Role : Int;
      Cmd_SelfTest : Bool;
      HIL : "UDT_HIL_DigitalTwin";
   END_VAR
   VAR_OUTPUT 
      Valve_CV : Real; 
      Dosing_Run : Bool;
      Alm_SensorDrift : Bool;
      SysState : Int; // 0=Off, 1=SelfTest, 2=Run, 99=Fault
   END_VAR
   VAR 
      instPID : "PID_Compact"; 
      Level_A_PV, Level_B_PV, Active_Level_PV : Real;
      Drift_Deviation : Real;
      SelfTest_Timer : TON_TIME;
      SelfTest_Step : Int;
   END_VAR
   VAR_CONSTANT
      MAX_DRIFT_TOLERANCE : Real := 5.0; // 5% drift tolerance
   END_VAR

BEGIN
    // 1. Process Raw Inputs
    #Level_A_PV := INT_TO_REAL(#PN_Raw_Ultrasonic_A) / 276.48;
    #Level_B_PV := INT_TO_REAL(#PN_Raw_Ultrasonic_B) / 276.48;

    // 2. Statistical Sensor Drift Detection
    #Drift_Deviation := ABS(#Level_A_PV - #Level_B_PV);
    IF (#Drift_Deviation > #MAX_DRIFT_TOLERANCE) THEN
        #Alm_SensorDrift := TRUE;
        // Degrade gracefully: Use lower value to prevent overflow spills
        #Active_Level_PV := MIN(IN1:=#Level_A_PV, IN2:=#Level_B_PV);
    ELSE
        #Alm_SensorDrift := FALSE;
        #Active_Level_PV := (#Level_A_PV + #Level_B_PV) / 2.0; // Average
    END_IF;

    // 3. HIL Digital Twin Synchronization & Adversarial Check
    IF #HIL.HIL_Mode_Active THEN
        IF ABS(#Active_Level_PV - #HIL.Sim_Level_PV) > #HIL.Max_Allowed_Deviation THEN
