    // 4. Automated Startup Self-Test Routine
    IF #Cmd_SelfTest AND #SysState = 0 THEN
        #SysState := 1; // Enter Self-Test
        #SelfTest_Step := 1;
    END_IF;

    IF #SysState = 1 THEN
        #SelfTest_Timer(IN:=TRUE, PT:=T#5s);
