```pascal
PROGRAM PRG_StackerReclaimer_Base
VAR
    // Kinematics Inputs
    fBoomAngle_Deg      : LREAL; // Luffing angle
    fSlewAngle_Deg      : LREAL; // Slewing angle
    fTravelPos_m        : LREAL; // Machine travel position

    // Commands
    bEnable             : BOOL;
    fLuffCmd_Speed      : LREAL;
    fSlewCmd_Speed      : LREAL;

    // Outputs to Drives
    fLuffOut_Speed      : LREAL;
    fSlewOut_Speed      : LREAL;

