VAR
    Machine_State : INT := 0;
    Spindle_Torque_Raw : REAL;
    Spindle_Torque_Filtered : REAL;
    Baseline_Torque : REAL := 5.0;
    Drift_Tolerance : REAL := 2.5;
    Torque_Sensor_Fault : BOOL;
    HIL_Sync_Pulse : BOOL;
    HIL_State_Vector : ARRAY[0..9] OF REAL;
    Twin_Divergence_Error : REAL;
    Max_Divergence : REAL := 1.0;
    POST_Step : INT := 0;
    POST_Timer : TON;
    POST_Complete : BOOL;
    Fault_Code : INT;
END_VAR

IF Machine_State = 0 THEN
    CASE POST_Step OF
        0:
            POST_Timer(IN:=TRUE, PT:=T#1S);
            IF POST_Timer.Q THEN POST_Step := 1; POST_Timer(IN:=FALSE); END_IF;
        1:
            IF ABS(Spindle_Torque_Raw - Baseline_Torque) > Drift_Tolerance THEN
                Torque_Sensor_Fault := TRUE;
                Machine_State := 4; Fault_Code := 701;
            ELSE
                POST_Step := 2;
            END_IF;
        2:
            IF HIL_Sync_Pulse THEN 
                POST_Complete := TRUE; 
                Machine_State := 1;
            ELSE
                Machine_State := 4; Fault_Code := 702;
            END_IF;
    END_CASE;
END_IF;

IF Machine_State = 2 THEN
    Spindle_Torque_Filtered := (Spindle_Torque_Raw * 0.1) + (Spindle_Torque_Filtered * 0.9);
    IF (Spindle_Torque_Filtered > (Baseline_Torque + Drift_Tolerance * 2.0)) THEN
        Torque_Sensor_Fault := TRUE;
        Machine_State := 4;
        Fault_Code := 703;
    END_IF;
END_IF;

IF Machine_State = 1 OR Machine_State = 2 THEN
    HIL_State_Vector[5] := Spindle_Torque_Filtered;
    IF Twin_Divergence_Error > Max_Divergence THEN
        Machine_State := 4;
        Fault_Code := 801;
    END_IF;
END_IF;
END_PROGRAM
