FUNCTION_BLOCK "FB_AGV_SLAM_Reasoning"
VERSION : 1.0
VAR_INPUT
    LidarData : ARRAY[0..359] OF REAL;
    PN_State : WORD;
    Sec_AuthToken : DWORD;
    SCADA_Heartbeat : BOOL;
    PrimaryPLC_Active : BOOL;
END_VAR
VAR_OUTPUT
    CmdVelocity : REAL;
    SysStateCode : DWORD;
    MQTT_PublishReq : BOOL;
END_VAR
VAR
    ActiveController : BOOL;
    AuthValid : BOOL;
END_VAR
BEGIN
    // PLC Failover Mechanism
    ActiveController := NOT PrimaryPLC_Active;
    IF NOT ActiveController THEN
        RETURN; // Standby PLC yields control
    END_IF;

    // IEC 62443 Cybersecurity & SCADA Validation
    AuthValid := (Sec_AuthToken = 16#A5A5_5A5A) AND SCADA_Heartbeat;
    IF NOT AuthValid THEN
        SysStateCode := 16#E001; // Security Lockout
        CmdVelocity := 0.0;
        MQTT_PublishReq := TRUE;
        RETURN;
    END_IF;

    SysStateCode := 16#0000; // System OK
    IF (PN_State AND 16#0001) > 0 THEN
        CmdVelocity := 1.5; // Normal SLAM operation simulated
        MQTT_PublishReq := TRUE; // Publish state
    ELSE
        CmdVelocity := 0.0;
    END_IF;
END_FUNCTION_BLOCK
