FUNCTION_BLOCK "HVDC_Control_Secure_Failover"
VERSION : 1.0
VAR_INPUT
    SCADA_Data : "OPC_UA_SCADA_Data";
    Local_SetAlpha : REAL;
    GridFreq : REAL;
END_VAR
VAR_OUTPUT
    AlphaOut : REAL;
    FilterSync : BOOL;
    ActiveController : BOOL;
    SecurityAlarm : BOOL;
END_VAR
VAR
    Authorized : BOOL;
    ValidToken : DWORD := 16#A5A5_5A5A;
END_VAR
BEGIN
    // IEC 62443 Cybersecurity: Access Control Check
    IF SCADA_Data.Access_Level >= 3 AND SCADA_Data.Token = ValidToken THEN
        Authorized := TRUE;
        SecurityAlarm := FALSE;
    ELSE
        Authorized := FALSE;
        SecurityAlarm := TRUE;
    END_IF;

    // Failover Logic
    IF SCADA_Data.ControllerRole = 1 THEN
        ActiveController := TRUE;
    ELSIF SCADA_Data.ControllerRole = 2 AND NOT SCADA_Data.Heartbeat_Partner THEN
        ActiveController := TRUE; // Takeover
    ELSE
        ActiveController := FALSE;
    END_IF;

    // Logic execution only if active
    IF ActiveController THEN
        IF Authorized THEN
            AlphaOut := SCADA_Data.SetAlpha_SCADA;
        ELSE
            AlphaOut := Local_SetAlpha; // Fallback to local secure console
        END_IF;

        IF GridFreq > 49.8 AND GridFreq < 50.2 THEN
            FilterSync := TRUE;
        ELSE
            FilterSync := FALSE;
        END_IF;
    ELSE
        AlphaOut := 0.0; // Standby
        FilterSync := FALSE;
    END_IF;
END_FUNCTION_BLOCK
