FUNCTION_BLOCK "HVDC_Control_Adversarial"
VERSION : 1.0
VAR_INPUT
    SetAlpha : REAL;
    GridVolt_Sensor1 : REAL;
    GridVolt_Sensor2 : REAL;
    GridFreq : REAL;
    HIL_Mode_Active : BOOL;
    HIL_GridVolt_Sim : REAL;
    Start_SelfTest : BOOL;
