            fTargetPitch := 90.0;
            IF fActualPitch >= 89.0 THEN eState := IDLE; END_IF

        FAULT:
            bHydraulicPumpOn := TRUE; fHydraulicValveCmd := 0.0; bSafetyFeatherSolenoid := FALSE; 
