    Self_Test_TMR : TON;
    Self_Test_Pass : BOOL;
    Cmd_Tap_Up : BOOL;
    Cmd_Tap_Down : BOOL;
    Sys_Ready : BOOL;
END_VAR

HIL_Heartbeat_Out := HIL_Heartbeat_In + 1;
IF HIL_Heartbeat_In = 0 THEN 
    HIL_Sync_Lost := TRUE;
END_IF;

Avg_Voltage := (V_Sensors[0] + V_Sensors[1] + V_Sensors[2]) / 3.0;
Sensor_Drift_Alarm[0] := ABS(V_Sensors[0] - Avg_Voltage) > Drift_Limit;
Sensor_Drift_Alarm[1] := ABS(V_Sensors[1] - Avg_Voltage) > Drift_Limit;
Sensor_Drift_Alarm[2] := ABS(V_Sensors[2] - Avg_Voltage) > Drift_Limit;

IF Self_Test_Active THEN
    Self_Test_TMR(IN := TRUE, PT := T#2s);
    CASE Self_Test_Step OF
        0:
            Cmd_Tap_Up := FALSE; Cmd_Tap_Down := FALSE;
            IF Self_Test_TMR.Q THEN Self_Test_Step := 1; Self_Test_TMR(IN:=FALSE); END_IF;
        1:
            IF NOT HIL_Sync_Lost THEN Self_Test_Step := 2; ELSE Self_Test_Pass := FALSE; Self_Test_Active := FALSE; END_IF;
