FUNCTION_BLOCK "FrancisTurbine_GuideVane_Base"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Enable_Control : Bool;
      Target_Gate_Position : Real; // 0.0 to 100.0%
      Actual_Gate_Position : Real; // Feedback from LVDT
   END_VAR

   VAR_OUTPUT 
      Servo_Control_Signal : Real; // -100.0 to 100.0%
      Gate_Sync_Achieved : Bool;
   END_VAR

   VAR 
      Position_Error : Real;
      Kp : Real := 2.5;
      Deadband : Real := 0.5;
   END_VAR

BEGIN
    IF NOT #Enable_Control THEN
        #Servo_Control_Signal := 0.0;
        #Gate_Sync_Achieved := FALSE;
        RETURN;
    END_IF;

    // Calculate position error
    #Position_Error := #Target_Gate_Position - #Actual_Gate_Position;

    // Control logic with deadband
    IF ABS(#Position_Error) > #Deadband THEN
        #Servo_Control_Signal := #Position_Error * #Kp;
        #Gate_Sync_Achieved := FALSE;
    ELSE
        #Servo_Control_Signal := 0.0;
        #Gate_Sync_Achieved := TRUE;
    END_IF;

    // Limit servo control signal
    IF #Servo_Control_Signal > 100.0 THEN
        #Servo_Control_Signal := 100.0;
    ELSIF #Servo_Control_Signal < -100.0 THEN
        #Servo_Control_Signal := -100.0;
    END_IF;
END_FUNCTION_BLOCK

