      Deadband : Real := 0.5;
      Drift_Tolerance : Real := 2.0;
      Self_Test_Active : Bool;
      Test_Timer : Time;
   END_VAR

BEGIN
    // Sensor Drift Detection (LVDT 1 vs 2)
    IF ABS(#Actual_Gate_Position_LVDT1 - #Actual_Gate_Position_LVDT2) > #Drift_Tolerance THEN
        #LVDT_Drift_Fault := TRUE;
        #Diagnostic_Code := 16#D001;
