        #Servo_Control_Signal := IF #Emergency_Stop THEN -100.0 ELSE 0.0;
        #Gate_Sync_Achieved := FALSE;
        RETURN;
    END_IF;

    #Position_Error := #Target_Gate_Position - #Actual_Position;

    IF ABS(#Position_Error) > #Deadband THEN
        #Servo_Control_Signal := #Position_Error * #Kp;
        #Gate_Sync_Achieved := FALSE;
