            1:
                IF #ActualSpeed1_kmh < 1.0 THEN
                    #TestStep := 2;
                ELSE
                    #SysState := #STATE_FAULT; #FaultCode := 301;
                END_IF;
            2:
                #TestTimer(IN:=TRUE, PT:=T#1S);
                IF #TestTimer.Q THEN
                    #TestTimer(IN:=FALSE, PT:=T#1S);
                    #TestStep := 3;
                END_IF;
            3:
                #SysState := #STATE_READY;
                #SelfTestComplete := TRUE;
        END_CASE;
        #TorqueCmd_Nm := 0.0;
        RETURN;
    END_IF;
    IF NOT #SysEnable THEN
        #SysState := #STATE_OFF;
        #TorqueCmd_Nm := 0.0;
        RETURN;
    END_IF;
    IF #SysState = #STATE_READY AND #SysEnable THEN
        #SysState := #STATE_RUN;
    END_IF;
    #DriftIntegrator := #DriftIntegrator + ABS(#ActualSpeed1_kmh - #ActualSpeed2_kmh);
    IF #DriftIntegrator > #DRIFT_THRESHOLD THEN
        #SysState := #STATE_FAULT;
        #FaultCode := 302;
