// Trigger secure state if unauthorized write attempt occurs or session expires
IF NOT bAuthenticationValid AND stScadaData.bRemoteDPEnable THEN
    bSecureStateActive := TRUE;
    stScadaData.bRemoteDPEnable := FALSE; // Reject unauthorized command
END_IF;

// 2. Hot-Standby PLC Failover Logic
// Monitor the peer PLC via dedicated cross-link heartbeat
nHeartbeatWatchdog(IN := NOT bPeerHeartbeat, PT := T#100MS);

// Arbitration logic: Take control if peer fails or heartbeat is lost
IF nHeartbeatWatchdog.Q OR bPeerFault THEN
    bIsActiveController := TRUE;
END_IF;
stScadaData.bActivePLCStatus := bIsActiveController;

// 3. System Execution Core
IF bIsActiveController THEN
    IF NOT bSecureStateActive THEN
        // DP and Vectoring Logic execution
        // ... (Logic executing based on stScadaData.bRemoteDPEnable) ...
        fCalculatedThrust := 50.0; // Simulated output

        stScadaData.fTotalPropulsionLoad := fCalculatedThrust * 2.0;
        fThrusterSpeedCmd := fCalculatedThrust;
    ELSE
        // Secure Fallback State: Hold position / Zero thrust to prevent unauthorized actuation
        fThrusterSpeedCmd := 0.0;
        stScadaData.fTotalPropulsionLoad := 0.0;
    END_IF;
ELSE
