FUNCTION_BLOCK "CBTC_Advanced_System"
VERSION : 1.2
VAR_INPUT
    Train_Position : REAL;
    Train_Speed : REAL;
    Track_Gradient : REAL;
    Switch_Req : BOOL;
    PN_Rx : "Profinet_Telegram_Rx"; // Data from Trackside via Profinet
END_VAR

VAR_OUTPUT
    ATO_Accel_Cmd : REAL;
    ATO_Brake_Cmd : REAL;
    Point_Machine_Error : BOOL; // Diagnostic Error Flag
    PN_Tx : "Profinet_Telegram_Tx"; // Data to Trackside via Profinet
END_VAR

VAR
    Safety_Margin : REAL := 50.0;
    Dist_To_Stop : REAL;
    Req_Decel : REAL;
    Switch_Timeout : TON;
    Switch_InProgress : BOOL;
END_VAR

BEGIN
    // 1. Point Machine Command & Diagnostics
    IF Switch_Req AND (Train_Speed < 0.1) THEN
        PN_Tx.Switch_Cmd := 1;
    ELSE
        PN_Tx.Switch_Cmd := 0;
    END_IF;

    // Diagnostics: Check if feedback matches command within timeout
    Switch_InProgress := (PN_Tx.Switch_Cmd <> PN_Rx.Switch_Pos_FB);
    Switch_Timeout(IN := Switch_InProgress, PT := T#3s);

    IF Switch_Timeout.Q OR PN_Rx.Switch_Fault THEN
        Point_Machine_Error := TRUE;
        PN_Tx.Emergency_Stop := TRUE;
    ELSE
        Point_Machine_Error := FALSE;
    END_IF;

    // 2. Moving Block & ATO (using Profinet Data)
    Dist_To_Stop := (PN_Rx.Ahead_Train_Pos - Safety_Margin) - Train_Position;

    IF Dist_To_Stop <= 0.0 OR Point_Machine_Error THEN
        ATO_Accel_Cmd := 0.0;
        ATO_Brake_Cmd := 2.5; // Emergency brake
        PN_Tx.Emergency_Stop := TRUE;
        RETURN;
    END_IF;

    // ATO Profile calculation
    Req_Decel := (Train_Speed * Train_Speed) / (2.0 * Dist_To_Stop);
    Req_Decel := Req_Decel - (9.81 * (Track_Gradient / 100.0));

    IF Req_Decel > 0.5 THEN
        ATO_Brake_Cmd := LIMIT(MN:=0.0, IN:=Req_Decel, MX:=1.5);
        ATO_Accel_Cmd := 0.0;
    ELSIF Train_Speed < PN_Rx.Speed_Limit THEN
        ATO_Brake_Cmd := 0.0;
        ATO_Accel_Cmd := LIMIT(MN:=0.0, IN:=(PN_Rx.Speed_Limit - Train_Speed)*0.5, MX:=1.0);
    ELSE
        ATO_Accel_Cmd := 0.0;
        ATO_Brake_Cmd := 0.0;
    END_IF;

    // 3. Populate Profinet Tx
    PN_Tx.Train_Position := Train_Position;
    PN_Tx.Train_Speed := Train_Speed;
    IF NOT Point_Machine_Error THEN
        PN_Tx.Emergency_Stop := FALSE;
    END_IF;
END_FUNCTION_BLOCK
