            Pump1_Speed := 0.0; Pump2_Speed := 0.0;
            Cap_Sorter_Running := FALSE; Cap_Sorter_Speed := 0.0;
            Fault_Active := FALSE; Fault_Code := 0;
            SCADA_Diag := 'IDLE';
        1: // Filling
            Filler_Running := TRUE; CIP_Active := FALSE;
            IF Active_Pump = 1 THEN Pump1_Speed := Speed_Setpoint; Pump2_Speed := 0.0;
