FUNCTION_BLOCK "Bottling_Full_Adversarial"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    CIP_Start : Bool;
    Bottle_Present : Bool;
    Cap_Level_Low : Bool;
    Speed_Setpoint : Real;
    PN_Status_Word : Word;
    User_Role : Int;
    Primary_Pump_OK : Bool;
    Flowmeter_Val : Real;
    Expected_Flow : Real;
    HIL_Sync_Req : Bool;
END_VAR
VAR_OUTPUT
    Filler_Running : Bool;
    CIP_Active : Bool;
    Valve_Open : Bool;
    Pump1_Speed : Real;
    Pump2_Speed : Real;
    Cap_Sorter_Running : Bool;
    Cap_Sorter_Speed : Real;
    Fault_Active : Bool;
    Fault_Code : Int;
    SCADA_State : Int;
    SCADA_Diag : String[32];
    HIL_State_Data : Struct State:Int; Flow:Real; Drift:Real; End_Struct;
END_VAR
VAR
    State : Int; // 0: Idle, 1: Filling, 2: CIP, 99: Fault, 100: Self-Test
    CIP_Step : Int;
    Test_Step : Int;
    Timer : TON;
    Drive_Fault : Bool;
    Active_Pump : Int := 1;
    Flow_Drift : Real;
    Drift_Warning : Bool;
    Self_Test_Pass : Bool := FALSE;
END_VAR

BEGIN
    // Security
    IF User_Role < 1 THEN Start := FALSE; END_IF;
    IF CIP_Start AND User_Role < 2 THEN CIP_Start := FALSE; END_IF;

    // HIL Digital Twin Sync
    IF HIL_Sync_Req THEN
        HIL_State_Data.State := State;
        HIL_State_Data.Flow := Flowmeter_Val;
        HIL_State_Data.Drift := Flow_Drift;
    END_IF;

    // Sensor Drift Detection
    IF Valve_Open AND Pump1_Speed > 0.0 THEN
        Flow_Drift := ABS(Expected_Flow - Flowmeter_Val);
        IF Flow_Drift > (Expected_Flow * 0.05) THEN
            Drift_Warning := TRUE; // 5% drift threshold
        ELSE
            Drift_Warning := FALSE;
        END_IF;
    END_IF;

    Drive_Fault := (PN_Status_Word AND 16#0008) <> 0;
    IF NOT Primary_Pump_OK AND Active_Pump = 1 THEN Active_Pump := 2; END_IF;

    IF Drive_Fault THEN
        State := 99; Fault_Code := 101;
    ELSIF Stop THEN
        State := 0;
    ELSIF Start AND NOT Self_Test_Pass THEN
        State := 100; // Force self-test before run
    ELSIF CIP_Start AND State = 0 THEN
        State := 2;
    ELSIF Start AND State = 0 AND Self_Test_Pass THEN
        State := 1;
    END_IF;

    CASE State OF
        0: // Idle
            Filler_Running := FALSE; Valve_Open := FALSE; Pump1_Speed := 0.0; Pump2_Speed := 0.0;
            Cap_Sorter_Running := FALSE; Fault_Active := FALSE; Fault_Code := 0;
            IF Drift_Warning THEN SCADA_Diag := 'IDLE - DRIFT WARN'; ELSE SCADA_Diag := 'IDLE'; END_IF;
        1: // Filling
            Filler_Running := TRUE;
            IF Active_Pump = 1 THEN Pump1_Speed := Speed_Setpoint; Pump2_Speed := 0.0;
            ELSE Pump2_Speed := Speed_Setpoint; Pump1_Speed := 0.0; END_IF;
            Valve_Open := Bottle_Present;
            IF NOT Cap_Level_Low THEN Cap_Sorter_Running := TRUE; Cap_Sorter_Speed := Speed_Setpoint * 1.1;
            ELSE State := 99; Fault_Code := 201; END_IF;
            SCADA_Diag := 'FILLING';
        2: // CIP Sequence
            CIP_Active := TRUE; Pump1_Speed := 50.0; Pump2_Speed := 50.0;
            CASE CIP_Step OF
                0: Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#5m); IF Timer.Q THEN CIP_Step:=1; Timer(IN:=FALSE, PT:=T#5m); END_IF;
                1: Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#10m); IF Timer.Q THEN CIP_Step:=2; Timer(IN:=FALSE, PT:=T#10m); END_IF;
                2: Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#5m); IF Timer.Q THEN CIP_Step:=0; State:=0; Timer(IN:=FALSE, PT:=T#5m); CIP_Active:=FALSE; END_IF;
            END_CASE;
            SCADA_Diag := 'CIP ACTIVE';
        99: // Fault
            Filler_Running := FALSE; CIP_Active := FALSE; Valve_Open := FALSE;
            Pump1_Speed := 0.0; Pump2_Speed := 0.0; Cap_Sorter_Running := FALSE;
            Fault_Active := TRUE;
            IF Stop THEN State := 0; END_IF;
        100: // Self-Test Routine
            CASE Test_Step OF
                0: // Test Pumps
                    Pump1_Speed := 10.0; Timer(IN:=TRUE, PT:=T#2s);
                    IF Timer.Q THEN Pump1_Speed := 0.0; Test_Step := 1; Timer(IN:=FALSE, PT:=T#2s); END_IF;
                1: // Test Valves
                    Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#1s);
                    IF Timer.Q THEN Valve_Open := FALSE; Test_Step := 2; Timer(IN:=FALSE, PT:=T#1s); END_IF;
                2: // Finish
                    Self_Test_Pass := TRUE; State := 0; Test_Step := 0;
            END_CASE;
            SCADA_Diag := 'SELF-TEST';
    END_CASE;
    SCADA_State := State;
END_FUNCTION_BLOCK
