            ELSE
                ScrubberPumpCommand := ScrubberPumpCommand - 0.1;
            END_IF;
            IF ScrubberPumpCommand > 100.0 THEN ScrubberPumpCommand := 100.0; END_IF;
            IF ScrubberPumpCommand < 0.0 THEN ScrubberPumpCommand := 0.0; END_IF;
        ELSE
            ScrubberPumpCommand := 0.0;
        END_IF;

        IF TurbineActive THEN
            PID_Error := TurbineTempSP - TurbineTempPV;
            PID_Integral := PID_Integral + PID_Error * 0.05;
            TurbineBypassValve := (PID_Error * 1.5) + PID_Integral;
            IF TurbineBypassValve > 100.0 THEN TurbineBypassValve := 100.0; END_IF;
            IF TurbineBypassValve < 0.0 THEN TurbineBypassValve := 0.0; END_IF;
        ELSE
            TurbineBypassValve := 100.0;
            PID_Integral := 0.0;
        END_IF;

        // Sync critical data
        SyncDataToStandby := PID_Integral;
    ELSE
        // Standby Mode - Keep integral term synced
        PID_Integral := SyncDataToStandby;
    END_IF;
END_FUNCTION_BLOCK
