    {attribute 'OPC.UA.DA' := '1'}
    fDigitalTwinTemp      : LREAL;
    bTwinSyncActive       : BOOL;
    fTwinDeviation        : LREAL;

    // Self-Test Variables
    tTestTimer            : TON;
    bSelfTestPassed       : BOOL;

    // Actuators
    fRefluxValve          AT %Q* : LREAL;
    fReboilerValve        AT %Q* : LREAL;
END_VAR

CASE nState OF
    0: // Automated Startup Self-Test
        // Stroke valves to 10% and verify feedback (abstracted)
        fRefluxValve := 10.0;
        fReboilerValve := 10.0;
        tTestTimer(IN:= TRUE, PT:= T#5S);
        IF tTestTimer.Q THEN
            bSelfTestPassed := TRUE; // Assume passed for logic
            fRefluxValve := 0.0;
            fReboilerValve := 0.0;
            nState := 1;
        END_IF

    1: // HIL Digital Twin Sync
        fTwinDeviation := ABS(fActiveTopTemp - fDigitalTwinTemp);
        IF fTwinDeviation < 5.0 THEN
            bTwinSyncActive := TRUE;
            nState := 2; // Transition to run
        END_IF

    2: // Run Mode with Drift Detection & Control
        // Drift Detection
        IF ABS(fTopTemp_A - fTopTemp_B) > fDriftThreshold THEN
            bDriftAlarm := TRUE;
            // Fallback to Digital Twin if sensors drift significantly
            fActiveTopTemp := fDigitalTwinTemp;
        ELSE
            bDriftAlarm := FALSE;
            fActiveTopTemp := (fTopTemp_A + fTopTemp_B) / 2.0;
        END_IF

        // PID Control Logic (Abstracted for brevity)
        fRefluxValve := 50.0; // Modulated by PID
        fReboilerValve := 30.0; // Modulated by PID

    3: // Fault State
        fRefluxValve := 100.0; // Total reflux (Safe)
        fReboilerValve := 0.0; // Cool down
END_CASE
