FUNCTION_BLOCK FB_ExtruderControl_Mut2
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    MeltPressure_SP : REAL;
    MeltPressure_PV : REAL;
    HW_ID_VFD : HW_IO;
END_VAR
VAR_OUTPUT
    Running : BOOL;
    Fault : BOOL;
    FaultCode : INT;
END_VAR
VAR
    PID_Melt : PID_Compact;
    VFD_Status : ARRAY[0..11] OF BYTE;
    VFD_Control : ARRAY[0..11] OF BYTE;
    RetVal_Read : INT;
    RetVal_Write : INT;
    ScrewSpeed_CV : REAL;
    CommFault : BOOL;
    DriveFault : BOOL;
    OverPressure : BOOL;
    State : INT := 0;
END_VAR

BEGIN
    // Profinet Read
    RetVal_Read := DPRD_DAT(LADDR := HW_ID_VFD, RECORD => VFD_Status);
    CommFault := (RetVal_Read <> 0);
    DriveFault := (VFD_Status[0] AND 16#08) <> 0; // Assuming Bit 3 represents Drive Fault
    OverPressure := (MeltPressure_PV > MeltPressure_SP * 1.2);

    IF CommFault THEN
        FaultCode := 1;
    ELSIF DriveFault THEN
        FaultCode := 2;
    ELSIF OverPressure THEN
        FaultCode := 3;
    ELSE
        FaultCode := 0;
    END_IF;

    Fault := (FaultCode <> 0);

    IF Fault OR Stop THEN
        State := 0;
    ELSIF Start AND NOT Fault AND State = 0 THEN
        State := 1;
    END_IF;

    Running := (State = 1);

    IF State = 1 THEN
        PID_Melt(Setpoint := MeltPressure_SP, Input := MeltPressure_PV);
        ScrewSpeed_CV := PID_Melt.Output;
        // Map Control Value to Profinet Word (e.g. 0-16384 for 0-100% speed)
        VFD_Control[2] := REAL_TO_BYTE(ScrewSpeed_CV * 163.84);
        VFD_Control[0] := 16#0F; // Run command bits
    ELSE
        VFD_Control[2] := 0;
        VFD_Control[0] := 16#04; // Stop command bits
        PID_Melt(Reset := TRUE);
    END_IF;

    // Profinet Write
    RetVal_Write := DPWR_DAT(LADDR := HW_ID_VFD, RECORD := VFD_Control);
END_FUNCTION_BLOCK
