FUNCTION_BLOCK FB_BlastFurnace_Base
VAR_INPUT
    TuyereFlowRate_SP : REAL; // Setpoint for Tuyere Injection Flow Rate (Nm3/h)
    TuyereFlowRate_PV : REAL; // Process Value for Tuyere Injection Flow Rate
    TopGasPressure_SP : REAL; // Setpoint for Top Gas Pressure (bar)
    TopGasPressure_PV : REAL; // Process Value for Top Gas Pressure
    Kp_Tuyere, Ki_Tuyere : REAL;
    Kp_TopGas, Ki_TopGas : REAL;
    CycleTime : REAL; // in seconds
END_VAR
VAR_OUTPUT
    TuyereValvePos : REAL; // 0-100%
    TopGasValvePos : REAL; // 0-100%
END_VAR
VAR
    Tuyere_Integral : REAL := 0.0;
    TopGas_Integral : REAL := 0.0;
    Tuyere_Error : REAL;
    TopGas_Error : REAL;
END_VAR

BEGIN
    // Tuyere Injection PI Control
    Tuyere_Error := TuyereFlowRate_SP - TuyereFlowRate_PV;
    Tuyere_Integral := Tuyere_Integral + (Tuyere_Error * CycleTime);
    TuyereValvePos := (Kp_Tuyere * Tuyere_Error) + (Ki_Tuyere * Tuyere_Integral);

    IF TuyereValvePos > 100.0 THEN TuyereValvePos := 100.0;
    ELSIF TuyereValvePos < 0.0 THEN TuyereValvePos := 0.0; END_IF;

    // Top Gas Pressure PI Control
    TopGas_Error := TopGasPressure_SP - TopGasPressure_PV;
    TopGas_Integral := TopGas_Integral + (TopGas_Error * CycleTime);
    TopGasValvePos := (Kp_TopGas * TopGas_Error) + (Ki_TopGas * TopGas_Integral);

    IF TopGasValvePos > 100.0 THEN TopGasValvePos := 100.0;
    ELSIF TopGasValvePos < 0.0 THEN TopGasValvePos := 0.0; END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_BlastFurnace_Depth
VAR_INPUT
    TuyereFlowRate_SP, TuyereFlowRate_PV : REAL;
    TopGasPressure_SP, TopGasPressure_PV : REAL;
    BlastTemp_SP, BlastTemp_PV : REAL;
    Kp, Ki : REAL; 
    CycleTime : REAL; 
    StoveHeatingMode : BOOL; // True = Heating, False = Blast
END_VAR
VAR_OUTPUT
    TuyereValvePos : REAL; 
    TopGasValvePos : REAL; 
    ColdBlastValvePos : REAL; 
    HotBlastValvePos : REAL; 
    GasBurnerValvePos : REAL;
END_VAR
VAR
    Tuyere_Int, TopGas_Int, BlastTemp_Int : REAL := 0.0;
    Err_Tuyere, Err_TopGas, Err_Temp : REAL;
END_VAR

BEGIN
    // Tuyere Control
    Err_Tuyere := TuyereFlowRate_SP - TuyereFlowRate_PV;
    Tuyere_Int := Tuyere_Int + (Err_Tuyere * CycleTime);
    TuyereValvePos := LIMIT(MN:=0.0, IN:=(Kp * Err_Tuyere) + (Ki * Tuyere_Int), MX:=100.0);

    // Top Gas Pressure Control
    Err_TopGas := TopGasPressure_SP - TopGasPressure_PV;
    TopGas_Int := TopGas_Int + (Err_TopGas * CycleTime);
    TopGasValvePos := LIMIT(MN:=0.0, IN:=(Kp * Err_TopGas) + (Ki * TopGas_Int), MX:=100.0);

    // Hot Stove Control
    IF StoveHeatingMode THEN
        GasBurnerValvePos := 100.0;
        HotBlastValvePos := 0.0;
        ColdBlastValvePos := 0.0;
    ELSE
        GasBurnerValvePos := 0.0;
        HotBlastValvePos := 100.0; // Open to blast furnace

        Err_Temp := BlastTemp_SP - BlastTemp_PV;
        BlastTemp_Int := BlastTemp_Int + (Err_Temp * CycleTime);
        // Regulate Cold Blast bypass to control final blast temp
        ColdBlastValvePos := LIMIT(MN:=0.0, IN:=(Kp * Err_Temp) + (Ki * BlastTemp_Int), MX:=100.0);
    END_IF;

END_FUNCTION_BLOCK

