FUNCTION_BLOCK FB_BlastFurnace_Reasoning
VAR_INPUT
    SCADA_In : "UDT_SCADA_Comms";
    SCADA_IP : STRING;
    PartnerPLC_Heartbeat : BOOL;
    ProcessValues : ARRAY[0..2] OF REAL; // 0:Tuyere, 1:TopGas, 2:Temp
