FUNCTION_BLOCK FB_BlastFurnace_Adversarial
VAR_INPUT
    Real_PV, Twin_PV : REAL;
    SCADA_Token : DWORD;
    RunSelfTest : BOOL;
END_VAR
VAR_OUTPUT
    ValveCommand : REAL;
    DriftDetected : BOOL;
    SecurityLockdown : BOOL;
    SelfTestActive : BOOL;
    SelfTestPassed : BOOL;
END_VAR
VAR
    DriftAccumulator : REAL;
    TestSequenceStep : INT;
    TestTimer : DINT;
END_VAR
CONST
    MAX_DRIFT : REAL := 5.0;
    AUTH_KEY : DWORD := 16#F00D_CAFE;
END_CONST

BEGIN
    // 1. Cybersecurity Lockdown
    IF SCADA_Token <> AUTH_KEY THEN
        SecurityLockdown := TRUE;
        ValveCommand := 0.0; 
        RETURN;
    END_IF;

    // 2. Sensor Drift Detection & HIL Sync
    DriftAccumulator := DriftAccumulator + ABS(Real_PV - Twin_PV);
    IF DriftAccumulator > 1000.0 THEN // Adversarial condition detected over time
        DriftDetected := TRUE;
        // Fallback to Digital Twin PV
    ELSE
        DriftDetected := FALSE;
    END_IF;

    // 3. Self-Test Routine
    IF RunSelfTest THEN
        SelfTestActive := TRUE;
        TestTimer := TestTimer + 1;
        CASE TestSequenceStep OF
            0: 
                ValveCommand := 10.0; 
                IF TestTimer > 100 THEN TestSequenceStep := 1; TestTimer:=0; END_IF;
            1:
                IF ABS(Real_PV - 10.0) < 2.0 THEN
                    ValveCommand := 90.0;
                    IF TestTimer > 100 THEN TestSequenceStep := 2; TestTimer:=0; END_IF;
                ELSE
                    SelfTestPassed := FALSE;
                    TestSequenceStep := 99; // Fail
                END_IF;
            2:
                SelfTestPassed := TRUE;
                TestSequenceStep := 99;
            99: // End
                SelfTestActive := FALSE;
        END_CASE;
        RETURN;
    ELSE
        TestSequenceStep := 0;
        TestTimer := 0;
        SelfTestActive := FALSE;
    END_IF;

    // 4. Normal Operation
    IF DriftDetected THEN
        ValveCommand := LIMIT(MN:=0.0, IN:=(50.0 - Twin_PV)*2.0, MX:=100.0);
    ELSE
        ValveCommand := LIMIT(MN:=0.0, IN:=(50.0 - Real_PV)*2.0, MX:=100.0);
    END_IF;

END_FUNCTION_BLOCK

