PROGRAM PRG_ContinuousCasting
VAR
    // Redundant Inputs
    rMouldLevelSensor1 AT %I* : REAL; // Primary (e.g., radiometric)
    rMouldLevelSensor2 AT %I* : REAL; // Secondary (e.g., eddy current)
    rActiveMouldLevel : REAL;
    bSensor1Healthy : BOOL := TRUE;
    bSensor2Healthy : BOOL := TRUE;

    // Outputs
    rStopperPosition AT %Q* : REAL;

    // SCADA Integration (OPC UA Variables via Pragma)
    {attribute 'OPC.UA.DA' := '1'}
    bScadaStartCmd : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    bScadaStopCmd : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    sScadaToken : STRING; // Cybersecurity auth token

    // Security & IEC 62443 Logging
    sValidToken : STRING := 'CasterAuth_V3_89xK';
    bAuthenticated : BOOL;
    sSecurityLog : ARRAY[1..10] OF STRING;
    iLogIndex : INT := 1;

    // Control
    rMouldLevelSetpoint : REAL := 100.0;
    rIntegral : REAL;
    eState : (IDLE, CASTING, STOPPING, SENSOR_FAIL) := IDLE;
END_VAR

// IEC 62443 Role-based Authentication for SCADA Commands
bAuthenticated := (sScadaToken = sValidToken);

IF (bScadaStartCmd OR bScadaStopCmd) AND NOT bAuthenticated THEN
    sSecurityLog[iLogIndex] := 'WARN: Unauthorized SCADA command attempt';
    iLogIndex := (iLogIndex MOD 10) + 1;
    bScadaStartCmd := FALSE; bScadaStopCmd := FALSE; // Block execution
END_IF

// Sensor Failover Logic (Reasoning on sensor reliability)
// Detect if sensor is out of physical bounds
bSensor1Healthy := (rMouldLevelSensor1 > -50.0 AND rMouldLevelSensor1 < 250.0);
bSensor2Healthy := (rMouldLevelSensor2 > -50.0 AND rMouldLevelSensor2 < 250.0);

IF bSensor1Healthy AND bSensor2Healthy THEN
    // If deviation is too high, trust the one closer to setpoint or historical average
    IF ABS(rMouldLevelSensor1 - rMouldLevelSensor2) > 15.0 THEN
        rActiveMouldLevel := (rMouldLevelSensor1 + rMouldLevelSensor2) / 2.0; // Average
        sSecurityLog[iLogIndex] := 'WARN: High deviation between Level Sensors';
        iLogIndex := (iLogIndex MOD 10) + 1;
    ELSE
        rActiveMouldLevel := rMouldLevelSensor1; // Default to primary
    END_IF
ELSIF bSensor1Healthy AND NOT bSensor2Healthy THEN
    rActiveMouldLevel := rMouldLevelSensor1;
ELSIF NOT bSensor1Healthy AND bSensor2Healthy THEN
    rActiveMouldLevel := rMouldLevelSensor2;
ELSE
    // Both failed
    eState := SENSOR_FAIL;
END_IF

CASE eState OF
    IDLE:
        rStopperPosition := 0.0;
        IF bScadaStartCmd AND bAuthenticated THEN
            bScadaStartCmd := FALSE;
            eState := CASTING;
            sSecurityLog[iLogIndex] := 'INFO: Casting started by SCADA';
            iLogIndex := (iLogIndex MOD 10) + 1;
        END_IF

    CASTING:
        // PI Control
        rIntegral := LIMIT(-50.0, rIntegral + ((rMouldLevelSetpoint - rActiveMouldLevel) * 0.01), 50.0);
        rStopperPosition := LIMIT(0.0, (2.0 * (rMouldLevelSetpoint - rActiveMouldLevel)) + (0.5 * rIntegral), 100.0);

        IF bScadaStopCmd AND bAuthenticated THEN
            bScadaStopCmd := FALSE;
            eState := STOPPING;
        END_IF

    STOPPING:
        rStopperPosition := MAX(0.0, rStopperPosition - 1.0);
        IF rStopperPosition = 0.0 THEN eState := IDLE; END_IF

    SENSOR_FAIL:
        rStopperPosition := 0.0; // Immediate closure
        sSecurityLog[iLogIndex] := 'CRITICAL: Total level sensor failure';
        iLogIndex := (iLogIndex MOD 10) + 1;
END_CASE
