```pascal
FUNCTION_BLOCK "FB_ReheatFurnace_Adv"
VERSION : 0.5
VAR_INPUT
    xSystemEn : BOOL;
    rTC1 : REAL;
    rTC2 : REAL;
    xHIL_HeartbeatIn : BOOL;
END_VAR
VAR_OUTPUT
    xHIL_HeartbeatOut : BOOL;
    iState : INT;
    rValidTemp : REAL;
END_VAR
VAR
    rDrift : REAL;
    xDriftFault : BOOL;
    iTestStep : INT;
    fbTestTimer : TON;
END_VAR
BEGIN
    xHIL_HeartbeatOut := NOT xHIL_HeartbeatIn;
    rDrift := ABS(rTC1 - rTC2);
    IF rDrift > 5.0 THEN
        xDriftFault := TRUE; iState := 3;
    ELSE
        rValidTemp := (rTC1 + rTC2) / 2.0;
    END_IF;
    IF xSystemEn AND iState = 0 THEN iState := 1; iTestStep := 10; END_IF;
    IF iState = 1 THEN
        CASE iTestStep OF
            10: fbTestTimer(IN:=TRUE, PT:=T#2S); IF fbTestTimer.Q THEN fbTestTimer(IN:=FALSE); iTestStep := 20; END_IF;
            20: iState := 2;
        END_CASE;
    END_IF;
END_FUNCTION_BLOCK
