PROGRAM PRG_SAG_Mill_Monitor_M2
VAR
    // Inputs mapped via EtherCAT
    rTrunnionFeedEndPressure AT %I* : REAL;
    rTrunnionDischargeEndPressure AT %I* : REAL;
    rTrunnionBearingTemp AT %I* : REAL;
    rMillMotorPower AT %I* : REAL;
    rMillSpeed AT %I* : REAL;

    // EtherCAT Diagnostics
    bEcSlaveError AT %I* : BOOL;
    bWcState AT %I* : BOOL; // Working counter state

    // Outputs
    bHighPressureAlarm : BOOL;
    rEstimatedChargeVolume : REAL;
    rCoolingValveCommand AT %Q* : REAL;
    bSystemFault : BOOL;

    // Fault diagnostics
    bSensorFaultPressure : BOOL;
    bSensorFaultTemp : BOOL;

    // Control vars
    rAvgPressure : REAL;
    rTempError : REAL;
    rIntegralTemp : REAL;
    rTempSetpoint : REAL := 45.0;
    rKp : REAL := 2.5;
    rKi : REAL := 0.1;
END_VAR

// Diagnostic check
bSystemFault := bEcSlaveError OR bWcState;

// Sensor validation
bSensorFaultPressure := rTrunnionFeedEndPressure < -1.0 OR rTrunnionDischargeEndPressure < -1.0;
bSensorFaultTemp := rTrunnionBearingTemp < -20.0 OR rTrunnionBearingTemp > 150.0;

IF NOT bSystemFault AND NOT bSensorFaultPressure THEN
    rAvgPressure := (rTrunnionFeedEndPressure + rTrunnionDischargeEndPressure) / 2.0;
    bHighPressureAlarm := rAvgPressure > 150.0;

    IF rMillSpeed > 0 THEN
        rEstimatedChargeVolume := LIMIT(0.0, (rMillMotorPower / 12000.0) * 100.0 * (rAvgPressure / 100.0), 100.0);
    ELSE
        rEstimatedChargeVolume := 0.0;
    END_IF
ELSE
    bHighPressureAlarm := TRUE; // Fail-safe
    rEstimatedChargeVolume := 0.0;
END_IF

IF NOT bSystemFault AND NOT bSensorFaultTemp THEN
    rTempError := rTrunnionBearingTemp - rTempSetpoint;
    IF rTempError > 0.0 THEN
        rIntegralTemp := LIMIT(0.0, rIntegralTemp + rTempError, 1000.0);
        rCoolingValveCommand := LIMIT(0.0, (rKp * rTempError) + (rKi * rIntegralTemp), 100.0);
    ELSE
        rCoolingValveCommand := 0.0;
        rIntegralTemp := 0.0;
    END_IF
ELSE
    rCoolingValveCommand := 100.0; // Fail-safe full cooling
END_IF
