PROGRAM PRG_SAG_Mill_Monitor_M4
VAR
    // Hardware Inputs
    rPressureFeed AT %I* : REAL;
    rPressureFeed_Redundant AT %I* : REAL;
    rPressureDischarge AT %I* : REAL;
    rBearingTemp AT %I* : REAL;
