        END_IF

    20: // Compression & Monitoring Phase
        bRejectTablet := FALSE;

        // Pre-compression check
        IF fPreCompressionForce > fPreForceLimitHigh OR fPreCompressionForce < fPreForceLimitLow THEN
            bRejectTablet := TRUE;
        END_IF

        // Main compression check
        IF fMainCompressionForce > fMainForceLimitHigh OR fMainCompressionForce < fMainForceLimitLow THEN
            bRejectTablet := TRUE;
        END_IF

        // Ejection phase transition
        IF fRotorPosition >= 270.0 THEN
            IF bRejectTablet THEN
                // Trigger reject mechanism
            END_IF
            nState := 10; // Loop back for next station
        END_IF

        IF bStopPress THEN
            nState := 0;
        END_IF
END_CASE

PROGRAM PRG_TabletPress_AWC
VAR
    bStartPress : BOOL;
    bStopPress : BOOL;

    // Dosing Synchronization
    fRotorPosition : LREAL;
    bDosingActive : BOOL;
    fTargetDoseVolume : LREAL := 10.0;
    fActualDoseVolume : LREAL;

    // Compression Force Monitoring
    fMainCompressionForce : LREAL;
    fMainForceLimitHigh : LREAL := 25.0;
    fMainForceLimitLow : LREAL := 15.0;

    // Automatic Weight Control (AWC)
    fAverageForce : LREAL;
    fForceSum : LREAL;
    nTabletCount : INT;
    nSampleWindow : INT := 100;
    fNominalForce : LREAL := 20.0;
    fCorrectionFactor : LREAL := 0.05; // 5% correction per kN deviation

    bRejectTablet : BOOL;
    nState : INT;
END_VAR

CASE nState OF
    0: // Idle
        fForceSum := 0.0;
        nTabletCount := 0;
        IF bStartPress AND NOT bStopPress THEN
            nState := 10;
        END_IF

    10: // Dosing Phase
        IF fRotorPosition > 0.0 AND fRotorPosition < 45.0 THEN
            bDosingActive := TRUE;
        ELSE
            bDosingActive := FALSE;
        END_IF

        IF fRotorPosition >= 180.0 AND fRotorPosition < 270.0 THEN
            nState := 20;
        END_IF

        IF bStopPress THEN nState := 0; END_IF

    20: // Compression & Monitoring Phase
        bRejectTablet := (fMainCompressionForce > fMainForceLimitHigh OR fMainCompressionForce < fMainForceLimitLow);

        // AWC Feedback Loop - moving average of force
        IF NOT bRejectTablet THEN
            fForceSum := fForceSum + fMainCompressionForce;
            nTabletCount := nTabletCount + 1;

            IF nTabletCount >= nSampleWindow THEN
                fAverageForce := fForceSum / INT_TO_LREAL(nSampleWindow);

                // Adjust target dose volume based on average force deviation
                IF fAverageForce > fNominalForce THEN
                    fTargetDoseVolume := fTargetDoseVolume - ((fAverageForce - fNominalForce) * fCorrectionFactor);
                ELSIF fAverageForce < fNominalForce THEN
                    fTargetDoseVolume := fTargetDoseVolume + ((fNominalForce - fAverageForce) * fCorrectionFactor);
                END_IF

                // Reset for next window
                fForceSum := 0.0;
                nTabletCount := 0;
            END_IF
        END_IF

        IF fRotorPosition >= 270.0 THEN
            nState := 10;
        END_IF

        IF bStopPress THEN nState := 0; END_IF
END_CASE

PROGRAM PRG_TabletPress_EtherCAT
VAR
    bStartPress : BOOL;
    bStopPress : BOOL;

    // EtherCAT Diagnostics
    fbEcMasterState : FB_EcMasterState; // From Tc2_EtherCAT library
    bEthercatOk : BOOL;
    nEcMasterNetId : T_AmsNetId := '192.168.1.2.1.1';

    // Hardware I/O linked to EtherCAT terminals
    fRawForceInput AT %I* : INT; // EL3102 Analog Input
    bDosingValve AT %Q* : BOOL; // EL2004 Digital Output
    bRejectGate AT %Q* : BOOL; // EL2004 Digital Output

    // Dosing Synchronization
    fRotorPosition : LREAL;
    fTargetDoseVolume : LREAL := 10.0;

    // Compression Force Monitoring
    fMainCompressionForce : LREAL;
    fMainForceLimitHigh : LREAL := 25.0;
    fMainForceLimitLow : LREAL := 15.0;

    // AWC
    fAverageForce : LREAL;
    fForceSum : LREAL;
    nTabletCount : INT;
    nSampleWindow : INT := 100;
    fNominalForce : LREAL := 20.0;
    fCorrectionFactor : LREAL := 0.05;

    bRejectTablet : BOOL;
    bFault : BOOL;
    nErrorID : UDINT;
    nState : INT;
END_VAR

// EtherCAT Diagnostic Check
fbEcMasterState(
    sNetId := nEcMasterNetId,
    bExecute := TRUE,
    tTimeout := T#1S
);
IF fbEcMasterState.bError THEN
    bEthercatOk := FALSE;
    bFault := TRUE;
    nErrorID := fbEcMasterState.nErrId;
ELSE
    bEthercatOk := (fbEcMasterState.nState = 8); // 8 = OP State
    IF NOT bEthercatOk THEN
        bFault := TRUE;
        nErrorID := 16#E001; // Custom Error: EtherCAT not in OP
    END_IF
END_IF

// Scale raw force input (0-32767 to 0-50 kN)
fMainCompressionForce := INT_TO_LREAL(fRawForceInput) * 50.0 / 32767.0;

CASE nState OF
    0: // Idle / Fault State
        bDosingValve := FALSE;
        bRejectGate := FALSE;
        IF bStartPress AND NOT bStopPress AND NOT bFault THEN
            nState := 10;
        END_IF

    10: // Dosing Phase
        IF fRotorPosition > 0.0 AND fRotorPosition < 45.0 THEN
            bDosingValve := TRUE;
        ELSE
            bDosingValve := FALSE;
        END_IF

        IF fRotorPosition >= 180.0 AND fRotorPosition < 270.0 THEN
            nState := 20;
        END_IF

        IF bStopPress OR bFault THEN nState := 0; END_IF

    20: // Compression & Monitoring Phase
        bRejectTablet := (fMainCompressionForce > fMainForceLimitHigh OR fMainCompressionForce < fMainForceLimitLow);

        IF bRejectTablet THEN
            bRejectGate := TRUE;
        ELSE
            bRejectGate := FALSE;
            fForceSum := fForceSum + fMainCompressionForce;
            nTabletCount := nTabletCount + 1;

            IF nTabletCount >= nSampleWindow THEN
                fAverageForce := fForceSum / INT_TO_LREAL(nSampleWindow);
                fTargetDoseVolume := fTargetDoseVolume + ((fNominalForce - fAverageForce) * fCorrectionFactor);
                fForceSum := 0.0;
                nTabletCount := 0;
            END_IF
        END_IF

        IF fRotorPosition >= 270.0 THEN
            nState := 10;
            bRejectGate := FALSE;
        END_IF

        IF bStopPress OR bFault THEN nState := 0; END_IF
END_CASE

PROGRAM PRG_TabletPress_Secure_SCADA
VAR
    bStartPress : BOOL;
    bStopPress : BOOL;

    // IEC 62443 Cybersecurity & SCADA Integration
    sActiveUser : STRING := '';
    nAccessLevel : INT := 0; // 0=None, 1=Operator, 2=Admin, 3=Engineer
    bScadaCommActive : BOOL;
    fbOpcUaServerStatus : FB_OpcUaServerStatus;
    tWatchdogScada : TON;
    bSecurityLockout : BOOL;

    // Failover Redundancy
    bPrimaryPLCActive : BOOL := TRUE;
    bSecondaryPLCReady : BOOL;
    bTriggerFailover : BOOL;

    // EtherCAT Diagnostics
    fbEcMasterState : FB_EcMasterState;
    bEthercatOk : BOOL;
    bFault : BOOL;
    nErrorID : UDINT;

    // I/O
    fRawForceInput AT %I* : INT;
    bDosingValve AT %Q* : BOOL;
    bRejectGate AT %Q* : BOOL;

    // Process Variables
    fRotorPosition : LREAL;
    fMainCompressionForce : LREAL;
    fMainForceLimitHigh : LREAL := 25.0;
    fMainForceLimitLow : LREAL := 15.0;
    fTargetDoseVolume : LREAL := 10.0;

    // AWC Variables omitted for brevity but conceptually active
    fAverageForce : LREAL;
    fForceSum : LREAL;
    nTabletCount : INT;
    nSampleWindow : INT := 100;
    fNominalForce : LREAL := 20.0;
    fCorrectionFactor : LREAL := 0.05;

    nState : INT;
END_VAR

// Cybersecurity - Role Based Access Control (IEC 62443-3-3 SR 1.1)
IF nAccessLevel < 1 THEN
    bSecurityLockout := TRUE;
    bStartPress := FALSE;
ELSE
    bSecurityLockout := FALSE;
END_IF

// SCADA Watchdog for Comm loss detection
tWatchdogScada(IN := NOT bScadaCommActive, PT := T#5S);
IF tWatchdogScada.Q THEN
    bFault := TRUE;
    nErrorID := 16#F001; // SCADA connection lost
END_IF

// Failover Logic
IF bFault AND bPrimaryPLCActive AND bSecondaryPLCReady THEN
    bTriggerFailover := TRUE;
    bPrimaryPLCActive := FALSE; // Hand over control
END_IF

// Only execute process if this PLC is primary and no security lockout
IF bPrimaryPLCActive AND NOT bSecurityLockout THEN

    // EtherCAT Diagnostics
    fbEcMasterState(sNetId := '192.168.1.2.1.1', bExecute := TRUE, tTimeout := T#1S);
    bEthercatOk := (fbEcMasterState.nState = 8);
    IF NOT bEthercatOk THEN
        bFault := TRUE;
    END_IF

    fMainCompressionForce := INT_TO_LREAL(fRawForceInput) * 50.0 / 32767.0;

    CASE nState OF
        0: // Safe / Idle
            bDosingValve := FALSE;
            bRejectGate := FALSE;
            IF bStartPress AND NOT bStopPress AND NOT bFault THEN
                nState := 10;
            END_IF

        10: // Dosing
            bDosingValve := (fRotorPosition > 0.0 AND fRotorPosition < 45.0);
            IF fRotorPosition >= 180.0 AND fRotorPosition < 270.0 THEN
                nState := 20;
            END_IF
            IF bStopPress OR bFault THEN nState := 0; END_IF

        20: // Compression & AWC
            IF (fMainCompressionForce > fMainForceLimitHigh OR fMainCompressionForce < fMainForceLimitLow) THEN
                bRejectGate := TRUE;
            ELSE
                bRejectGate := FALSE;
                fForceSum := fForceSum + fMainCompressionForce;
                nTabletCount := nTabletCount + 1;
                IF nTabletCount >= nSampleWindow THEN
                    fAverageForce := fForceSum / INT_TO_LREAL(nSampleWindow);
                    fTargetDoseVolume := fTargetDoseVolume + ((fNominalForce - fAverageForce) * fCorrectionFactor);
                    fForceSum := 0.0;
                    nTabletCount := 0;
                END_IF
            END_IF

            IF fRotorPosition >= 270.0 THEN nState := 10; END_IF
            IF bStopPress OR bFault THEN nState := 0; END_IF
    END_CASE
ELSE
    // Set outputs to safe state when inactive or locked out
    bDosingValve := FALSE;
    bRejectGate := FALSE;
END_IF

PROGRAM PRG_TabletPress_Adversarial
VAR
    bStartPress : BOOL;
    bStopPress : BOOL;
    nState : INT;
    bFault : BOOL;
    nErrorID : UDINT;

    // I/O & EtherCAT
    fRawForceInput AT %I* : INT;
    bDosingValve AT %Q* : BOOL;
    bRejectGate AT %Q* : BOOL;
