END_IF

IF bPrimaryPLCActive AND NOT bSecurityLockout THEN
    IF bSelfTestMode THEN
        // Startup Self-Test Routine
        CASE nSelfTestStep OF
            0: 
                bDosingValve := TRUE; 
                bRejectGate := FALSE;
                tSelfTestTimer(IN:=TRUE, PT:=T#1S);
                IF tSelfTestTimer.Q THEN
                    tSelfTestTimer(IN:=FALSE);
                    nSelfTestStep := 1;
                END_IF
            1:
                bDosingValve := FALSE;
                bRejectGate := TRUE;
                tSelfTestTimer(IN:=TRUE, PT:=T#1S);
                IF tSelfTestTimer.Q THEN
                    bSelfTestPassed := TRUE;
                    bSelfTestMode := FALSE;
                    bRejectGate := FALSE;
                END_IF
        END_CASE
    ELSE
        // Normal Operation
        CASE nState OF
            0: // Idle
                IF bStartPress AND NOT bStopPress AND NOT bFault THEN
                    nState := 10;
                END_IF

            10: // Dosing
                bDosingValve := (fRotorPosition > 0.0 AND fRotorPosition < 45.0);
                IF fRotorPosition >= 180.0 THEN nState := 20; END_IF
                IF bStopPress OR bFault THEN nState := 0; END_IF

            20: // Compression
                IF fMainCompressionForce > fMainForceLimitHigh THEN
                    bRejectGate := TRUE;
                ELSE
