                END_IF

                IF fRotorPosition >= 270.0 THEN nState := 10; END_IF
                IF bStopPress OR bFault THEN nState := 0; END_IF
        END_CASE
    END_IF
ELSE
    bDosingValve := FALSE;
    bRejectGate := FALSE;
END_IF

Below is the Allen-Bradley ST (Structured Text) base code to coordinate a Heat Sealing Temperature Profile and a Vision Reject Sync for a Blister Packaging machine.

### Allen-Bradley ST Code
```pascal
PROGRAM Blister_Base
VAR
    // Temperature Control
    HeatTemp_PV : REAL; // Present Value from Thermocouple
    HeatTemp_SP : REAL := 150.0; // Setpoint
    Heater_CV : REAL; // Control Variable to SSR
    Temp_PID : PID;

    // Vision Sync & Reject
    Vision_Pass : BOOL;
    Vision_Fail : BOOL;
    Machine_Index_Pulse : BOOL; // Fires once per machine cycle
    Reject_ShiftReg : DINT; // 32-bit shift register
    Reject_Station_Sensor : BOOL; // Part present at reject station
    Reject_Actuator : BOOL; // Air blow-off
END_VAR

// 1. Heat Sealing Temperature Control
// Using standard Allen-Bradley PID instruction
Temp_PID(
    PV := HeatTemp_PV,
    SP := HeatTemp_SP,
    KP := 2.5,
    KI := 0.1,
    KD := 0.05,
    CV => Heater_CV
);

// 2. Vision Reject Sync (Shift Register)
// On every machine index pulse, shift the tracking register
IF Machine_Index_Pulse THEN
    // Shift the register left by multiplying by 2 (Bit Shift Left equivalent in ST)
    Reject_ShiftReg := Reject_ShiftReg * 2;

    // If the vision system flagged a failure, insert a '1' into the 0th bit position
    IF Vision_Fail THEN
        Reject_ShiftReg.0 := 1;
    END_IF;
END_IF;

// 3. Reject Actuation
// Assuming the reject station is 5 indexes downstream (Bit 5)
IF Reject_Station_Sensor THEN
    Reject_Actuator := Reject_ShiftReg.5;
ELSE
    Reject_Actuator := 0;
END_IF;

END_PROGRAM
```

### Explanation
1. **Temperature Control**: Uses a standard PID control block calculating the `Heater_CV` based on `HeatTemp_PV`.
2. **Vision Sync**: Utilizes a `DINT` as a 32-position shift register. On every `Machine_Index_Pulse`, the register shifts. A failed vision inspection writes a `1` to the LSB.
3. **Reject Station**: Triggers the `Reject_Actuator` when a part reaches the station and the 5th bit (5 indexes away) is true.

