    Flow_AI : Real;
    Flow_SP : Real;
    Temp_AI : Real;
    Temp_SP : Real;
END_VAR
VAR_OUTPUT
    Flow_CV : Real;
    Temp_CV : Real;
    Dosing_Pump_Run : Bool;
    Phase : Int;
END_VAR
VAR
    State : Int;
    PID_Flow_Int : Real;
    PID_Temp_Int : Real;
END_VAR

BEGIN
    // Phase Transition & Dosing Control
    IF Cond_AI < 1.0 THEN
        State := 1; // Rinse
        Dosing_Pump_Run := FALSE;
    ELSIF Cond_AI >= 1.0 AND Cond_AI <= 50.0 THEN
        State := 2; // Acid
        Dosing_Pump_Run := TRUE;
    ELSE
        State := 3; // Caustic
        Dosing_Pump_Run := TRUE;
    END_IF;
    Phase := State;

    IF Execute THEN
        // Flow Control
        PID_Flow_Int := PID_Flow_Int + ((Flow_SP - Flow_AI) * 0.1);
        Flow_CV := ((Flow_SP - Flow_AI) * 2.0) + PID_Flow_Int;

        // Temperature Control Sub-system
        PID_Temp_Int := PID_Temp_Int + ((Temp_SP - Temp_AI) * 0.05);
        Temp_CV := ((Temp_SP - Temp_AI) * 1.5) + PID_Temp_Int;

        // Limits
        IF Flow_CV > 100.0 THEN Flow_CV := 100.0; ELSIF Flow_CV < 0.0 THEN Flow_CV := 0.0; END_IF;
        IF Temp_CV > 100.0 THEN Temp_CV := 100.0; ELSIF Temp_CV < 0.0 THEN Temp_CV := 0.0; END_IF;
    ELSE
        Flow_CV := 0.0; Temp_CV := 0.0;
        PID_Flow_Int := 0.0; PID_Temp_Int := 0.0;
        Dosing_Pump_Run := FALSE;
    END_IF;
END_FUNCTION_BLOCK
