PROGRAM PRG_ReactionVessel
VAR
    // Process Variables
    rPressure_PV       : REAL;
    rPressure_SP       : REAL := 2.5; // Target pressure in bar
    rTemp_PV           : REAL;
    rTempRate_PV       : REAL; // dT/dt
    rTempRate_Limit    : REAL := 0.5; // Max allowed C/sec

    // Actuators
    rValve_PressureOut : REAL; // 0-100%
    rValve_Cooling     : REAL; // 0-100%

    // PID Variables
    fbPID_Pressure     : FB_CTRL_PID;
    stPIDParams        : ST_CTRL_PID_PARAMS;

    // Rate Calculation Variables
    fbTimer            : TON;
    rLastTemp          : REAL;
    bInit              : BOOL := TRUE;
END_VAR

IF bInit THEN
    stPIDParams.fKp := 2.5;
    stPIDParams.tTn := T#10S;
    stPIDParams.tTv := T#0S;
    stPIDParams.tTd := T#0S;
    stPIDParams.fOutMaxLimit := 100.0;
    stPIDParams.fOutMinLimit := 0.0;
    bInit := FALSE;
END_IF

// Calculate Exothermic Rate (dT/dt) every 1 second
fbTimer(IN := TRUE, PT := T#1S);
IF fbTimer.Q THEN
    rTempRate_PV := rTemp_PV - rLastTemp;
    rLastTemp := rTemp_PV;
    fbTimer(IN := FALSE);
END_IF

// Pressure Control Loop
fbPID_Pressure(
    fSetpointValue := rPressure_SP,
    fActualValue   := rPressure_PV,
    stParams       := stPIDParams,
    eMode          := eCTRL_MODE_ACTIVE,
    fOut           => rValve_PressureOut
);

// Exothermic Rate Safety Override
IF rTempRate_PV > rTempRate_Limit THEN
    rValve_Cooling := 100.0; // Max cooling if exothermic reaction runs away
ELSE
    rValve_Cooling := 20.0; // Steady state cooling
END_IF
