FUNCTION_BLOCK FB_BESS_EtherCAT_Node
VAR_INPUT
    aRacks         : ARRAY[1..4] OF ST_BatteryRack_Thermal;
    bGridSyncCmd   : BOOL;
    stEcDiag       : ST_EtherCAT_Diag;
    bResetFault    : BOOL;
END_VAR
VAR_OUTPUT
    aRacksOut      : ARRAY[1..4] OF ST_BatteryRack_Thermal;
    bInverterSync  AT %Q* : BOOL;
    eState         : E_BESS_State := E_BESS_State.INIT;
    bEcError       : BOOL;
    nErrorCode     : UDINT;
END_VAR
VAR
    i : INT;
    fTotalSOC, fAvgSOC : LREAL;
END_VAR

// 1. EtherCAT Diagnostics
bEcError := stEcDiag.bWcState OR (stEcDiag.nState <> 8); // 8 = OP State

IF bEcError THEN
    eState := E_BESS_State.FAULT;
    nErrorCode := 16#E001; // EtherCAT Comm Error
END_IF;

// 2. State Machine
CASE eState OF
    E_BESS_State.INIT:
        bInverterSync := FALSE;
        IF NOT bEcError THEN
            eState := E_BESS_State.STANDBY;
        END_IF;

    E_BESS_State.STANDBY:
        // Thermal & SOC Logic here...
        fTotalSOC := 0.0;
        FOR i := 1 TO 4 DO
            fTotalSOC := fTotalSOC + aRacks[i].fSOC;
            aRacksOut[i] := aRacks[i];

            // Thermal Faults
            IF aRacksOut[i].fTempC > 50.0 THEN
                eState := E_BESS_State.FAULT;
                nErrorCode := 16#F002; // OverTemp
            END_IF;
        END_FOR;

        IF eState <> E_BESS_State.FAULT THEN
            fAvgSOC := fTotalSOC / 4.0;
            IF bGridSyncCmd THEN
                eState := E_BESS_State.SYNCED;
            ELSE
                eState := E_BESS_State.BALANCING;
            END_IF;
        END_IF;

    E_BESS_State.BALANCING:
        // Balancing implementation
        IF bGridSyncCmd THEN eState := E_BESS_State.SYNCED; END_IF;

    E_BESS_State.SYNCED:
        bInverterSync := TRUE;
        IF NOT bGridSyncCmd THEN 
            bInverterSync := FALSE;
            eState := E_BESS_State.STANDBY; 
        END_IF;

    E_BESS_State.FAULT:
        bInverterSync := FALSE;
        FOR i := 1 TO 4 DO
            aRacksOut[i].bChargeCmd := FALSE;
            aRacksOut[i].bDischargeCmd := FALSE;
        END_FOR;
        IF bResetFault AND NOT bEcError THEN
            nErrorCode := 0;
            eState := E_BESS_State.INIT;
        END_IF;
END_CASE;
