TraverseSpeed := SpoolBaseRPM * 2.0;
IF TraverseDirection THEN
    TraversePosition := TraversePosition + (TraverseSpeed * 0.01);
    IF TraversePosition >= SpoolWidth THEN TraverseDirection := 0; END_IF;
ELSE
    TraversePosition := TraversePosition - (TraverseSpeed * 0.01);
    IF TraversePosition <= 0.0 THEN
        TraverseDirection := 1;
        SpoolDiameter := SpoolDiameter + 4.0;
