    PN_IO_Status : Word; 
    User_Role : Int; // 1=Op, 2=Admin, 3=Maint
    Token_Valid : Bool;
    CPU_Is_Primary : Bool;
    Peer_CPU_Status : Word;
END_VAR
VAR_OUTPUT
    Heater_Ctrl : Real;
    Vacuum_Pump : Bool;
    Vent_Valve : Bool;
    Steam_Inject_Valve : Real;
    State : Int;
    Alarm_Word : Word;
    SCADA_Data : Struct
        Current_State : Int;
        Temp_PV : Real;
        Pressure_PV : Real;
        Active_Alarms : Word;
        Security_Lockout : Bool;
    END_STRUCT;
END_VAR
VAR
    PID_Temp {InstructionName := 'PID_Compact'; LibVersion := '2.2'} : PID_Compact;
    PID_Steam {InstructionName := 'PID_Compact'; LibVersion := '2.2'} : PID_Compact;
    Ramp_SP : Real;
    Pressure_Comp_SP : Real;
    Timer_Soak {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
    Security_Lockout_Active : Bool;
END_VAR

BEGIN
    // Reasoning: Cybersecurity & Redundancy

    // IEC 62443 - Access Control and Command Validation
    IF NOT #Token_Valid OR (#User_Role < 1) THEN
        #Security_Lockout_Active := TRUE;
    ELSE
        #Security_Lockout_Active := FALSE;
    END_IF;

    // Failover Logic
    IF NOT #CPU_Is_Primary AND (#Peer_CPU_Status = 16#0001) THEN
        // Standby Mode - Update SCADA but skip control logic
        #SCADA_Data.Current_State := #State;
        #SCADA_Data.Temp_PV := #Temp_Process;
        RETURN;
    END_IF;

    #Alarm_Word := 16#0000;

    IF (#PN_IO_Status AND 16#0001) = 0 THEN
        #Alarm_Word.%X0 := TRUE; 
    END_IF;

    IF #Temp_Process < 0.0 OR #Temp_Process > 150.0 THEN
        #Alarm_Word.%X1 := TRUE; 
    END_IF;

    IF #Alarm_Word <> 0 OR #Security_Lockout_Active THEN
        #State := 99; 
    END_IF;

    IF #Stop_Cycle AND (#User_Role >= 1) THEN
        #State := 0; 
    ELSIF #Start_Cycle AND #State = 0 AND #Alarm_Word = 0 AND NOT #Security_Lockout_Active THEN
        IF #User_Role >= 1 THEN // Minimum operator role
            #State := 1; 
        END_IF;
    END_IF;

    CASE #State OF
        0: 
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
            #Steam_Inject_Valve := 0.0;
        1: 
            #Vent_Valve := FALSE;
            IF #Vacuum_Level > 0.05 THEN
                #Vacuum_Pump := TRUE;
            ELSE
                #Vacuum_Pump := FALSE;
                #Ramp_SP := 121.0; 
            END_IF;

            #Pressure_Comp_SP := (#Temp_Process / 100.0) * 2.0; 

            #PID_Temp(Setpoint:=#Ramp_SP, Input:=#Temp_Process);
            #Heater_Ctrl := #PID_Temp.Output;

            #PID_Steam(Setpoint:=#Pressure_Comp_SP, Input:=#Chamber_Pressure);
            #Steam_Inject_Valve := #PID_Steam.Output;

            IF #Temp_Process >= 121.0 AND #Chamber_Pressure >= 2.05 THEN
                #State := 2; 
            END_IF;
        2: 
            #Timer_Soak(IN:=TRUE, PT:=T#15M);
            #PID_Temp(Setpoint:=121.0, Input:=#Temp_Process);
            #Heater_Ctrl := #PID_Temp.Output;
            #PID_Steam(Setpoint:=2.05, Input:=#Chamber_Pressure);
            #Steam_Inject_Valve := #PID_Steam.Output;
            IF #Timer_Soak.Q THEN
                #State := 3; 
            END_IF;
        3: 
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
            #Steam_Inject_Valve := 0.0;
            #Timer_Soak(IN:=FALSE, PT:=T#15M);
            IF #Vacuum_Level > 0.95 AND #Chamber_Pressure < 1.05 THEN
                #State := 0;
            END_IF;
        99: 
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
            #Steam_Inject_Valve := 0.0;
    END_CASE;

    // Update SCADA integration block
    #SCADA_Data.Current_State := #State;
    #SCADA_Data.Temp_PV := #Temp_Process;
    #SCADA_Data.Pressure_PV := #Chamber_Pressure;
    #SCADA_Data.Active_Alarms := #Alarm_Word;
    #SCADA_Data.Security_Lockout := #Security_Lockout_Active;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "FB_Autoclave_Mut4"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
VAR_INPUT
    Start_Cycle : Bool;
    Stop_Cycle : Bool;
    Temp_Sens_1 : Real;
    Temp_Sens_2 : Real; // Redundant sensor for drift detection
    Vacuum_Level : Real;
    Chamber_Pressure : Real;
    PN_IO_Status : Word; 
    User_Role : Int;
    Token_Valid : Bool;
    CPU_Is_Primary : Bool;
    Peer_CPU_Status : Word;
    HIL_Sync_Data : Word; // Digital Twin heartbeat
END_VAR
VAR_OUTPUT
    Heater_Ctrl : Real;
    Vacuum_Pump : Bool;
    Vent_Valve : Bool;
    Steam_Inject_Valve : Real;
    State : Int;
    Alarm_Word : Word;
    SCADA_Data : Struct
        Current_State : Int;
        Temp_PV : Real;
        Pressure_PV : Real;
        Active_Alarms : Word;
        HIL_Sync_Status : Bool;
    END_STRUCT;
END_VAR
VAR
    PID_Temp {InstructionName := 'PID_Compact'; LibVersion := '2.2'} : PID_Compact;
    PID_Steam {InstructionName := 'PID_Compact'; LibVersion := '2.2'} : PID_Compact;
    Ramp_SP : Real;
    Pressure_Comp_SP : Real;
    Timer_Soak {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
    Self_Test_Step : Int;
    Self_Test_Timer {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
    Valid_Temp : Real;
    Drift_Error : Real;
END_VAR

BEGIN
    // Adversarial: Sensor drift, HIL Sync, Self-Test, Adversarial Input Resistance

    // Cybersecurity & Access
    IF NOT #Token_Valid OR (#User_Role < 1) THEN
        #State := 99; // Force Fault/Lockout on bad token
    END_IF;

    // HIL Digital Twin Synchronization
    #SCADA_Data.HIL_Sync_Status := (#HIL_Sync_Data = 16#A5A5);
    IF NOT #SCADA_Data.HIL_Sync_Status THEN
        #Alarm_Word.%X5 := TRUE; // HIL Desync
    END_IF;

    // Redundancy Failover
    IF NOT #CPU_Is_Primary AND (#Peer_CPU_Status = 16#0001) THEN
        #SCADA_Data.Current_State := #State;
        RETURN;
    END_IF;

    // Sensor Drift Detection & Mitigation (Transient failure resistance)
    #Drift_Error := ABS(#Temp_Sens_1 - #Temp_Sens_2);
    IF #Drift_Error > 2.5 THEN
        #Alarm_Word.%X6 := TRUE; // Sensor Drift Detected
        // Mitigate by taking the lower, safer value for control
        IF #Temp_Sens_1 < #Temp_Sens_2 THEN
            #Valid_Temp := #Temp_Sens_1;
        ELSE
            #Valid_Temp := #Temp_Sens_2;
        END_IF;
    ELSE
        #Valid_Temp := (#Temp_Sens_1 + #Temp_Sens_2) / 2.0; // Average for smooth control
    END_IF;

    // Bounds checking (Adversarial input mitigation)
    IF #Valid_Temp < -50.0 OR #Valid_Temp > 200.0 THEN
        #Alarm_Word.%X1 := TRUE; 
    END_IF;
    IF #Vacuum_Level < -0.1 OR #Vacuum_Level > 1.5 THEN
        #Alarm_Word.%X2 := TRUE;
    END_IF;

    IF #Alarm_Word <> 0 THEN
        #State := 99; 
    END_IF;

    IF #Stop_Cycle THEN
        #State := 0; 
        #Self_Test_Step := 0;
    ELSIF #Start_Cycle AND #State = 0 AND #Alarm_Word = 0 THEN
        #State := 10; // Init Self-Test before cycle
    END_IF;

    CASE #State OF
        0: // IDLE
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
            #Steam_Inject_Valve := 0.0;

        10: // SELF-TEST ROUTINE
            CASE #Self_Test_Step OF
                0: // Test Vent Valve
                    #Vent_Valve := TRUE;
                    #Self_Test_Timer(IN:=TRUE, PT:=T#2S);
                    IF #Self_Test_Timer.Q THEN
                        #Self_Test_Timer(IN:=FALSE, PT:=T#2S);
                        #Self_Test_Step := 1;
                    END_IF;
                1: // Test Vacuum 
                    #Vent_Valve := FALSE;
                    #Vacuum_Pump := TRUE;
                    #Self_Test_Timer(IN:=TRUE, PT:=T#3S);
                    IF #Self_Test_Timer.Q THEN
                        IF #Vacuum_Level < 0.9 THEN
                            #Self_Test_Timer(IN:=FALSE, PT:=T#2S);
                            #Vacuum_Pump := FALSE;
                            #Self_Test_Step := 2;
                        ELSE
                            #Alarm_Word.%X7 := TRUE; // Vacuum self-test failed
                            #State := 99;
                        END_IF;
                    END_IF;
                2: // Self-Test Pass -> Proceed to cycle
                    #State := 1; 
            END_CASE;

        1: // RAMP
            #Vent_Valve := FALSE;
            IF #Vacuum_Level > 0.05 THEN
                #Vacuum_Pump := TRUE;
            ELSE
                #Vacuum_Pump := FALSE;
                #Ramp_SP := 121.0; 
            END_IF;

            #Pressure_Comp_SP := (#Valid_Temp / 100.0) * 2.0; 

            #PID_Temp(Setpoint:=#Ramp_SP, Input:=#Valid_Temp);
            #Heater_Ctrl := #PID_Temp.Output;

            #PID_Steam(Setpoint:=#Pressure_Comp_SP, Input:=#Chamber_Pressure);
            #Steam_Inject_Valve := #PID_Steam.Output;

            IF #Valid_Temp >= 121.0 AND #Chamber_Pressure >= 2.05 THEN
                #State := 2; 
            END_IF;

        2: // SOAK
            #Timer_Soak(IN:=TRUE, PT:=T#15M);
            #PID_Temp(Setpoint:=121.0, Input:=#Valid_Temp);
            #Heater_Ctrl := #PID_Temp.Output;
            #PID_Steam(Setpoint:=2.05, Input:=#Chamber_Pressure);
            #Steam_Inject_Valve := #PID_Steam.Output;
            IF #Timer_Soak.Q THEN
                #State := 3; 
            END_IF;

        3: // VENT
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
            #Steam_Inject_Valve := 0.0;
            #Timer_Soak(IN:=FALSE, PT:=T#15M);
            IF #Vacuum_Level > 0.95 AND #Chamber_Pressure < 1.05 THEN
                #State := 0;
            END_IF;

        99: // FAULT
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
            #Steam_Inject_Valve := 0.0;
            #Self_Test_Step := 0;
    END_CASE;

    // SCADA Update
    #SCADA_Data.Current_State := #State;
    #SCADA_Data.Temp_PV := #Valid_Temp;
    #SCADA_Data.Pressure_PV := #Chamber_Pressure;
    #SCADA_Data.Active_Alarms := #Alarm_Word;
END_FUNCTION_BLOCK

