```scl
FUNCTION_BLOCK "PaintBooth_Base"
VERSION : 1.0
VAR_INPUT
    bStart_PB : Bool;
    bStop_PB : Bool;
    bCar_In_Position : Bool;
    rOverspray_Concentration : Real; // 0.0 - 100.0 %
END_VAR

VAR_OUTPUT
    bConveyor_Motor : Bool;
    bRobot_Enable : Bool;
    bExhaust_Fan : Bool;
    bCapture_Pump : Bool;
END_VAR

VAR
    bSystem_Running : Bool;
    iState : Int; // 0=Stop, 1=Index, 2=Paint
END_VAR

BEGIN
    // System Start/Stop
    IF #bStop_PB THEN
        #bSystem_Running := FALSE;
    ELSIF #bStart_PB THEN
        #bSystem_Running := TRUE;
    END_IF;

    IF NOT #bSystem_Running THEN
        #iState := 0;
    ELSIF #bSystem_Running AND #iState = 0 THEN
        #iState := 1;
    END_IF;

    // Main State Machine
    CASE #iState OF
        0: // Stop
            #bConveyor_Motor := FALSE;
            #bRobot_Enable := FALSE;

        1: // Index Conveyor
            #bRobot_Enable := FALSE;
            IF NOT #bCar_In_Position THEN
                #bConveyor_Motor := TRUE;
            ELSE
                #bConveyor_Motor := FALSE;
                #iState := 2; // Transition to Painting
            END_IF;

        2: // Painting
            #bConveyor_Motor := FALSE;
            #bRobot_Enable := TRUE;
    END_CASE;

    // Overspray Capture Management
    IF #bSystem_Running AND (#rOverspray_Concentration > 20.0) THEN
        #bExhaust_Fan := TRUE;
    ELSE
        #bExhaust_Fan := FALSE;
    END_IF;

    IF #bSystem_Running AND (#rOverspray_Concentration > 60.0) THEN
        #bCapture_Pump := TRUE;
    ELSE
        #bCapture_Pump := FALSE;
    END_IF;
