    IF (CoolantPressure < MinCoolantPressure) OR (CoolantTemp > MaxCoolantTemp) THEN
        AlarmCoolant := TRUE;
    END_IF;
ELSE
    CoolantPump := FALSE;
END_IF;

// Main Control
IF StartPB AND NOT StopPB AND NOT AlarmLoad AND NOT AlarmToolWear AND NOT AlarmCoolant THEN
    MachiningActive := TRUE;
    SpindleMotor := TRUE;
ELSIF StopPB OR AlarmLoad OR AlarmToolWear OR AlarmCoolant THEN
    MachiningActive := FALSE;
    SpindleMotor := FALSE;
END_IF;

// Spindle Load Monitoring
IF SpindleLoad > MaxSpindleLoad THEN AlarmLoad := TRUE; END_IF;

// Tool Wear Compensation
IF MachiningActive THEN
    ToolLifeCycles := ToolLifeCycles + 1;
END_IF;

IF ToolLifeCycles >= MaxToolLifeCycles THEN
    AlarmToolWear := TRUE;
ELSE
    ToolWearOffset := (DINT_TO_REAL(ToolLifeCycles) / DINT_TO_REAL(MaxToolLifeCycles)) * 0.05;
