FUNCTION_BLOCK "Autoclave_Base"
VERSION : 1.0
   VAR_INPUT
      Start : Bool;
      TargetTemp : Real;
      TargetVac : Real;
      PartTemp : Real;
      ChamberVac : Real;
   END_VAR
   VAR_OUTPUT
      Heater : Real;
      Cooler : Real;
      Pump : Bool;
      ExoAlarm : Bool;
   END_VAR
   VAR
      LastTemp : Real;
      TempRate : Real;
   END_VAR
BEGIN
   Pump := Start AND (ChamberVac > TargetVac);
   TempRate := PartTemp - LastTemp;
   LastTemp := PartTemp;
   ExoAlarm := TempRate > 2.0;
   IF Start AND NOT ExoAlarm THEN
      Heater := LIMIT(MN:=0.0, IN:=(TargetTemp - PartTemp)*5.0, MX:=100.0);
      Cooler := 0.0;
   ELSIF Start AND ExoAlarm THEN
      Heater := 0.0;
      Cooler := 100.0;
   ELSE
      Heater := 0.0;
      Cooler := 0.0;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Autoclave_Mutation1"
VERSION : 1.0
   VAR_INPUT
      Start : Bool;
      TargetTemp : Real;
      TargetPress : Real;
      PartTemp : Real;
      Zone1Press : Real;
      Zone2Press : Real;
   END_VAR
   VAR_OUTPUT
      Heater : Real;
      Cooler : Real;
      N2ValveZone1 : Real;
      N2ValveZone2 : Real;
      ExoAlarm : Bool;
   END_VAR
   VAR
      LastTemp : Real;
      TempRate : Real;
      PressMasterCmd : Real;
   END_VAR
BEGIN
   TempRate := PartTemp - LastTemp;
   LastTemp := PartTemp;
   ExoAlarm := TempRate > 2.0;

   // Cascade Pressure Control
   PressMasterCmd := (TargetPress - ((Zone1Press + Zone2Press)/2.0)) * 2.0;
   N2ValveZone1 := LIMIT(MN:=0.0, IN:=PressMasterCmd + (TargetPress - Zone1Press)*1.5, MX:=100.0);
   N2ValveZone2 := LIMIT(MN:=0.0, IN:=PressMasterCmd + (TargetPress - Zone2Press)*1.5, MX:=100.0);

   IF Start AND NOT ExoAlarm THEN
      Heater := LIMIT(MN:=0.0, IN:=(TargetTemp - PartTemp)*5.0, MX:=100.0);
      Cooler := 0.0;
   ELSIF Start AND ExoAlarm THEN
      Heater := 0.0;
      Cooler := 100.0;
   ELSE
      Heater := 0.0;
      Cooler := 0.0;
      N2ValveZone1 := 0.0;
      N2ValveZone2 := 0.0;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Autoclave_Mutation2"
VERSION : 1.0
   VAR_INPUT
      Start : Bool;
      PartTemp : Real;
      Zone1Press : Real;
      Zone2Press : Real;
      Profinet_MES_Recipe : Struct
         TargetTemp : Real;
         TargetPress : Real;
         ExoLimit : Real;
      End_Struct;
   END_VAR
   VAR_OUTPUT
      Heater : Real;
      Cooler : Real;
      N2ValveZone1 : Real;
      N2ValveZone2 : Real;
      Profinet_MES_Status : Struct
         Active : Bool;
         AlarmCode : Int;
      End_Struct;
   END_VAR
   VAR
      LastTemp : Real;
      TempRate : Real;
      ExoAlarm : Bool;
   END_VAR
BEGIN
   Profinet_MES_Status.Active := Start;
   TempRate := PartTemp - LastTemp;
   LastTemp := PartTemp;
   ExoAlarm := TempRate > Profinet_MES_Recipe.ExoLimit;

   IF ExoAlarm THEN
      Profinet_MES_Status.AlarmCode := 101; // Exothermic Error
   ELSIF (Zone1Press - Zone2Press) > 5.0 THEN
      Profinet_MES_Status.AlarmCode := 102; // Pressure Imbalance
   ELSE
      Profinet_MES_Status.AlarmCode := 0;
   END_IF;

   IF Start AND NOT ExoAlarm THEN
      Heater := LIMIT(MN:=0.0, IN:=(Profinet_MES_Recipe.TargetTemp - PartTemp)*5.0, MX:=100.0);
      N2ValveZone1 := LIMIT(MN:=0.0, IN:=(Profinet_MES_Recipe.TargetPress - Zone1Press)*2.5, MX:=100.0);
      N2ValveZone2 := LIMIT(MN:=0.0, IN:=(Profinet_MES_Recipe.TargetPress - Zone2Press)*2.5, MX:=100.0);
   ELSE
      Heater := 0.0;
      N2ValveZone1 := 0.0;
      N2ValveZone2 := 0.0;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Autoclave_Mutation3"
VERSION : 1.0
   VAR_INPUT
      Start : Bool;
      PartTemp : Real;
      UserRole : Int; // 1=Oper, 2=Admin
      PartnerPLC_Alive : Bool;
   END_VAR
   VAR_OUTPUT
      Heater : Real;
      SafeStateActive : Bool;
      SCADA_Telemetry : Struct
         Temp : Real;
         State : Int;
      End_Struct;
   END_VAR
   VAR
      IsPrimary : Bool := TRUE;
      HeartbeatFailTimer : Int;
   END_VAR
BEGIN
   // Redundancy Failover
   IF NOT PartnerPLC_Alive THEN
      HeartbeatFailTimer := HeartbeatFailTimer + 1;
      IF HeartbeatFailTimer > 10 THEN
         IsPrimary := TRUE;
      END_IF;
   ELSE
      HeartbeatFailTimer := 0;
   END_IF;

   // Cybersecurity RBAC
   IF UserRole < 1 THEN
      SafeStateActive := TRUE; // Unauthorized
      Heater := 0.0;
      SCADA_Telemetry.State := 99;
      RETURN;
   END_IF;

   IF IsPrimary AND Start THEN
      Heater := 50.0; // Simplified Control
      SafeStateActive := FALSE;
      SCADA_Telemetry.State := 1;
   ELSE
      Heater := 0.0;
      SafeStateActive := TRUE;
      SCADA_Telemetry.State := 0;
   END_IF;
   SCADA_Telemetry.Temp := PartTemp;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Autoclave_Mutation4"
VERSION : 1.0
   VAR_INPUT
      Start : Bool;
      Thermo1 : Real;
      Thermo2 : Real;
      Thermo3 : Real;
      HIL_TwinTemp : Real;
      SelfTestCmd : Bool;
   END_VAR
   VAR_OUTPUT
      Heater : Real;
      DriftAlarm : Bool;
      SelfTestPass : Bool;
   END_VAR
   VAR
      AvgTemp : Real;
      MaxDiff : Real;
      State : Int;
   END_VAR
BEGIN
   // Sensor Drift Detection
   AvgTemp := (Thermo1 + Thermo2 + Thermo3) / 3.0;
   MaxDiff := MAX(IN1:=ABS(AvgTemp-Thermo1), IN2:=MAX(IN1:=ABS(AvgTemp-Thermo2), IN2:=ABS(AvgTemp-Thermo3)));
   DriftAlarm := (MaxDiff > 2.5);

   // HIL Digital Twin Sync
   IF ABS(AvgTemp - HIL_TwinTemp) > 10.0 THEN
      State := 900; // Model divergence anomaly
   END_IF;

   // Pre-flight Self-test
   IF SelfTestCmd THEN
      State := 10;
      Heater := 100.0;
      // Simulate actuator failure check...
      SelfTestPass := TRUE;
   ELSIF Start AND NOT DriftAlarm AND State = 0 THEN
      Heater := 50.0;
   ELSE
      Heater := 0.0;
   END_IF;
END_FUNCTION_BLOCK

