                    eSelfTestState := ST_SENSORS;
                ST_SENSORS:
                    bCoolingPump := FALSE;
                    IF NOT bSensorDriftFault THEN eSelfTestState := ST_DONE; END_IF
                ST_DONE:
                    eState := INIT;
            END_CASE

        INIT:
            // Waiting for Cell
            eState := TEST;

        TEST:
            eState := WELD;

        WELD:
            IF fActiveTemp > 45.0 THEN
                bWeldLaser := FALSE;
                bCoolingPump := TRUE;
            ELSE
                bWeldLaser := TRUE;
                bCoolingPump := FALSE;
            END_IF

        FAULT:
            bWeldLaser := FALSE;
            bCoolingPump := TRUE; // Default safe state
            IF bAdminActive AND NOT bSensorDriftFault THEN
                eState := SELF_TEST;
                nFaultCode := 0;
            END_IF
    END_CASE
END_IF
