Here is the highly resilient Siemens SCL code managing AS/RS operations while detecting sensor drift, maintaining HIL digital twin states, and handling adversarial sensor spikes:

```scl
FUNCTION_BLOCK "ASRS_Adversarial"
VAR_INPUT
    Req_X, Prim_X, Sec_X, Load_Weight : REAL;
    Execute : BOOL;
    Security_Token : DWORD;
    HIL_Mode_Active, Startup_Pulse : BOOL;
END_VAR
VAR_OUTPUT
    Target_Speed : REAL;
    Error : BOOL;
    Error_Code : INT;
    Digital_Twin_X : REAL;
    Digital_Twin_Status : INT;
END_VAR
VAR
    Self_Test_Done : BOOL := FALSE;
    Filtered_X, Last_Valid_X, Drift_Accum : REAL;
END_VAR
CONST
    VALID_TOKEN : DWORD := 16#A1B2C3D4;
    DRIFT_TOLERANCE : REAL := 5.0;
    SPIKE_LIMIT : REAL := 50.0;
END_CONST
BEGIN
    Error := FALSE;
    Error_Code := 0;
    IF Startup_Pulse THEN
        Self_Test_Done := TRUE;
        Last_Valid_X := Prim_X;
        Digital_Twin_Status := 0;
    END_IF;
    IF NOT Self_Test_Done THEN Error := TRUE; Error_Code := 999; RETURN; END_IF;
    IF Security_Token <> VALID_TOKEN THEN Error := TRUE; Error_Code := 401; RETURN; END_IF;
    IF ABS(Prim_X - Last_Valid_X) > SPIKE_LIMIT THEN
        Filtered_X := Last_Valid_X;
    ELSE
        Filtered_X := Prim_X;
        Last_Valid_X := Prim_X;
    END_IF;
    Drift_Accum := ABS(Filtered_X - Sec_X);
    IF Drift_Accum > DRIFT_TOLERANCE THEN Error := TRUE; Error_Code := 500; RETURN; END_IF;
    IF Execute THEN Target_Speed := 2.0; END_IF;
    IF HIL_Mode_Active THEN
        Digital_Twin_X := Filtered_X;
        Digital_Twin_Status := Error_Code;
    END_IF;
END_FUNCTION_BLOCK
```

