    bTensionFault : BOOL;
    bColorFault : BOOL;
    bSystemFault : BOOL;
END_VAR

// EtherCAT Diagnostics
IF nEcatState <> 8 THEN // 8 = OP state in EtherCAT
    bEcatError := TRUE;
    bSystemFault := TRUE;
ELSE
