        IF ABS(fColorError) > 20.0 THEN
            bColorFault := TRUE; // Diagnostic limit
        ELSE
            bColorFault := FALSE;
            fPhaseCorrection := fColorError * 0.1;
        END_IF
    END_IF

    // Splicer Synchronization
    IF bSpliceReq THEN
