IF nEcatState <> 8 THEN
    bEcatError := TRUE;
    bRedundantBusActive := TRUE; // Switch to failover communication
    bSplicerFailoverActive := TRUE;
ELSE
    bEcatError := FALSE;
    bRedundantBusActive := FALSE;
END_IF

// SCADA publish
fScadaTensionData := fActualTension;
bScadaSystemStatus := NOT bSystemFault;

