    bColorRegActive : BOOL := TRUE; bSplicerSync : BOOL := FALSE;
    fMarkPosition : LREAL; fTargetPosition : LREAL := 100.0; fColorError : LREAL; fPhaseCorrection : LREAL;
    bSpliceReq : BOOL := FALSE; fOldRollDiameter : LREAL := 500.0; fNewRollDiameter : LREAL := 1000.0; bSpliceComplete : BOOL := FALSE;
    fTensionSetpoint : LREAL := 50.0; fActualTension : LREAL; fTensionError : LREAL; fTensionOut : LREAL; fTensionInt : LREAL;

    nEcatState AT %I* : UINT; bEcatError : BOOL; bSystemFault : BOOL; bTensionFault : BOOL; bColorFault : BOOL;
    nCurrentRole : INT := 2; bAccessDenied : BOOL; bRedundantBusActive : BOOL; bSplicerFailoverActive : BOOL;

    {attribute 'OPC.UA.DA' := '1'} fScadaTensionData : LREAL;
    {attribute 'OPC.UA.DA' := '1'} bScadaSystemStatus : BOOL;

    // Sensor Drift Detection
    fColorMarkHistory : ARRAY[0..99] OF LREAL;
    nDriftIdx : INT := 0;
    fDriftMovingAvg : LREAL;
    bDriftWarning : BOOL;

    // HIL Digital Twin Mode
    bHilTwinSyncMode : BOOL := FALSE;
    fTwinSimTension : LREAL := 50.0; // Simulated feedback

    // Start-up Self-Test
    bRunSelfTest : BOOL := TRUE;
    bSelfTestPassed : BOOL := FALSE;
    nTestStep : INT := 0;
END_VAR

// Self-Test Routine
IF bRunSelfTest THEN
    CASE nTestStep OF
        0: // Check Cyber Access
            IF nCurrentRole >= 1 THEN nTestStep := 1; ELSE bSystemFault := TRUE; END_IF
        1: // Verify Comms
            IF nEcatState = 8 THEN nTestStep := 2; END_IF
        2: // Test Complete
            bSelfTestPassed := TRUE;
            bRunSelfTest := FALSE;
    END_CASE
    RETURN; // Block normal operation until self-test passes
END_IF

// Cybersecurity & SCADA Update
bAccessDenied := (nCurrentRole < 1);
bScadaSystemStatus := NOT bSystemFault;
fScadaTensionData := fActualTension;

IF bHilTwinSyncMode THEN
    fActualTension := fTwinSimTension; // Digital Twin feedback sync
END_IF

IF bStartPrint AND bSelfTestPassed AND NOT bSystemFault AND NOT bAccessDenied THEN
    // Color Registration & Drift Detection
    fColorError := fTargetPosition - fMarkPosition;
    fColorMarkHistory[nDriftIdx] := fColorError;
    nDriftIdx := (nDriftIdx + 1) MOD 100;

    // Calculate Drift (simple moving average over sample)
    fDriftMovingAvg := (fDriftMovingAvg * 99.0 + fColorError) / 100.0;
    IF ABS(fDriftMovingAvg) > 5.0 THEN
        bDriftWarning := TRUE; // Sensor requires calibration
    END_IF

    bColorFault := (ABS(fColorError) > 20.0);
    IF NOT bColorFault THEN fPhaseCorrection := fColorError * 0.1; END_IF

    // Splicer Synchronization
    IF bSpliceReq OR bSplicerFailoverActive THEN
        bSplicerSync := TRUE;
        fOldRollDiameter := fOldRollDiameter - 0.1; 
        IF fOldRollDiameter < 50.0 THEN
            bSpliceComplete := TRUE; bSpliceReq := FALSE; bSplicerSync := FALSE; fOldRollDiameter := fNewRollDiameter; 
            bSplicerFailoverActive := FALSE;
        END_IF
    END_IF

    // Web Tension PID
    fTensionError := fTensionSetpoint - fActualTension;
    bTensionFault := (ABS(fTensionError) > 15.0);
    fTensionInt := fTensionInt + (fTensionError * 0.01);
    fTensionOut := (1.5 * fTensionError) + (0.2 * fTensionInt);

    IF bHilTwinSyncMode THEN
        fTwinSimTension := fTwinSimTension + (fTensionOut * 0.05); // Simulate response
    END_IF

    IF bColorFault OR bTensionFault THEN
        bSystemFault := TRUE; bStartPrint := FALSE;
    END_IF
END_IF

Here is an Allen-Bradley ST program for a Pulp Digester that estimates the Kappa Number (using H-Factor) and sequences the Blow Valve.

```iecst
PROGRAM Pulp_Digester_Base
VAR
    // Inputs
    Temperature_C : REAL;
    Alkali_Conc : REAL;
    Start_Cook : BOOL;
    Reset : BOOL;

    // Outputs
    Blow_Valve_Cmd : BOOL;
    Kappa_Estimate : REAL;
    Cook_Complete : BOOL;

    // Internal
    H_Factor : REAL;
    Reaction_Rate : REAL;
    Temp_K : REAL;
END_VAR

IF Reset THEN
    H_Factor := 0.0;
    Kappa_Estimate := 0.0;
    Cook_Complete := FALSE;
    Blow_Valve_Cmd := FALSE;
END_IF;

IF Start_Cook AND NOT Cook_Complete THEN
    Temp_K := Temperature_C + 273.15;
    Reaction_Rate := EXP(43.2 - (118400.0 / (8.314 * Temp_K)));
    H_Factor := H_Factor + (Reaction_Rate / 3600.0);
    Kappa_Estimate := 110.0 - (0.04 * H_Factor) - (0.15 * Alkali_Conc);
    IF H_Factor >= 1200.0 THEN
        Cook_Complete := TRUE;
    END_IF;
END_IF;

IF Cook_Complete THEN
    Blow_Valve_Cmd := TRUE;
ELSE
    Blow_Valve_Cmd := FALSE;
END_IF;
END_PROGRAM
```

