```iecst
PROGRAM Pulp_Digester_Mut1
VAR
    Temperature_C : REAL; 
    Alkali_Conc : REAL; 
    Start_Cook : BOOL;
    Reset : BOOL;
    Temp_Setpoint : REAL := 170.0;
    Liquor_Level : REAL;
    Blow_Valve_Cmd : BOOL;
    Recirc_Pump_Cmd : BOOL;
    Heater_Valve_CV : REAL;
    Kappa_Estimate : REAL;
    Cook_Complete : BOOL;
    Error : REAL;
    Integral : REAL;
    Derivative : REAL;
    LastError : REAL;
    Kp : REAL := 2.5;
    Ki : REAL := 0.1;
    Kd : REAL := 0.05;
    H_Factor : REAL;
    Temp_K : REAL;
    Reaction_Rate : REAL;
END_VAR

IF Reset THEN
    H_Factor := 0.0;
    Cook_Complete := FALSE;
    Integral := 0.0;
    Blow_Valve_Cmd := FALSE;
    Recirc_Pump_Cmd := FALSE;
    Heater_Valve_CV := 0.0;
END_IF;

IF Start_Cook AND NOT Cook_Complete THEN
    IF Liquor_Level > 20.0 THEN
        Recirc_Pump_Cmd := TRUE;
    ELSE
        Recirc_Pump_Cmd := FALSE;
    END_IF;

    IF Recirc_Pump_Cmd THEN
        Error := Temp_Setpoint - Temperature_C;
        Integral := Integral + Error;
        Derivative := Error - LastError;
        Heater_Valve_CV := (Kp * Error) + (Ki * Integral) + (Kd * Derivative);
        IF Heater_Valve_CV > 100.0 THEN Heater_Valve_CV := 100.0; END_IF;
        IF Heater_Valve_CV < 0.0 THEN Heater_Valve_CV := 0.0; END_IF;
        LastError := Error;
    ELSE
        Heater_Valve_CV := 0.0;
    END_IF;

    Temp_K := Temperature_C + 273.15;
    Reaction_Rate := EXP(43.2 - (118400.0 / (8.314 * Temp_K)));
    H_Factor := H_Factor + (Reaction_Rate / 3600.0);
    Kappa_Estimate := 110.0 - (0.04 * H_Factor) - (0.15 * Alkali_Conc);

    IF H_Factor >= 1200.0 THEN
        Cook_Complete := TRUE;
    END_IF;
END_IF;

IF Cook_Complete THEN
    Recirc_Pump_Cmd := FALSE;
    Heater_Valve_CV := 0.0;
    Blow_Valve_Cmd := TRUE;
END_IF;
END_PROGRAM
