BEGIN
    // Profinet Control Word parsing (e.g. Bit 0 = Enable)
    #Local_Enable := (IN:=#PN_ControlWord AND 16#0001) > 0;

    // Fault Diagnostics
    #PN_AlarmWord := 16#0000;
    IF #Camera_BreakageDetected THEN
        #PN_AlarmWord := #PN_AlarmWord OR 16#0001; // Bit 0: Warp Breakage
    END_IF;
    IF #Drive_Fault THEN
        #PN_AlarmWord := #PN_AlarmWord OR 16#0002; // Bit 1: Drive Fault
    END_IF;

    // Update Status Word
    IF #Local_Enable THEN
        #PN_StatusWord := #PN_StatusWord OR 16#0001;
    ELSE
        #PN_StatusWord := #PN_StatusWord AND 16#FFFE;
    END_IF;
END_FUNCTION_BLOCK
