    IF #HIL_Mode_Active THEN
        #Active_Tension := #HIL_Simulated_Tension;
    ELSE
        #Active_Tension := (#TensionSensor_1_Actual + #TensionSensor_2_Actual) / 2.0;
    END_IF;

    // Sensor Drift Detection
    IF ABS(#TensionSensor_1_Actual - #TensionSensor_2_Actual) > #Drift_Tolerance THEN
        #Sensor_Drift_Alarm := TRUE;
    ELSE
        #Sensor_Drift_Alarm := FALSE;
    END_IF;

    // Automated Self-Test Routine
    CASE #State_Machine OF
        0: // Init
            #Self_Test_Complete := FALSE;
            #State_Machine := 10;
        10: // Check Interlocks and Sensors
            IF NOT #Sensor_Drift_Alarm THEN
                #State_Machine := 20;
            END_IF;
        20: // Test Complete, Ready for Start
            #Self_Test_Complete := TRUE;
