PROGRAM PRG_Corrugator_Tension
VAR
    bStart : BOOL;
    bStop : BOOL;
    rLineSpeed : REAL;
    rTargetLength : REAL;
    bWebPresent : BOOL;
    rTensionFeedback : REAL;
    rTargetTension : REAL := 150.0;
