    IF rCurrentPos * 1000.0 >= rTargetLength THEN
        bFireShear := TRUE;
        rCurrentPos := 0.0;
    ELSE
        bFireShear := FALSE;
    END_IF
    fbTensionPID(
        fSetpoint := rTargetTension,
        fActual := rTensionFeedback,
        bEnable := TRUE,
        fKp := 0.5, fKi := 0.1, fKd := 0.05,
        fOutput => rBrakeTorque
    );
ELSE
    bRunGlue := FALSE;
    rGlueSpeed := 0.0;
    bFireShear := FALSE;
    fbTensionPID(bEnable := FALSE);
    rBrakeTorque := 0.0;
END_IF

