Here is the Siemens SCL program incorporating Profinet communication and advanced diagnostics:

```pascal
FUNCTION_BLOCK "RO_Skid_Profinet_Diag"
VAR_INPUT
    PN_ControlWord : Word;
    FeedPres_Raw : Int;
END_VAR
VAR_OUTPUT
    PN_StatusWord : Word;
    Fault_Code : Int;
END_VAR
VAR
    Sensor_Wire_Break : Bool;
    Dry_Run_Fault : Bool;
END_VAR
BEGIN
    // Diagnostics
    Sensor_Wire_Break := (FeedPres_Raw < -27648) OR (FeedPres_Raw > 27648);
    Dry_Run_Fault := (FeedFlow_PV < 1.0) AND HPPump_Run;

    IF Sensor_Wire_Break THEN
        Fault_Code := 101;
        State := 0;
    ELSIF Dry_Run_Fault THEN
        Fault_Code := 102;
        State := 0;
    END_IF;

    // Profinet Mapping
    PN_StatusWord.%X0 := (State = 1); // Running bit
    PN_StatusWord.%X1 := (Fault_Code > 0); // Fault bit

    // Control logic triggered via Profinet
    IF PN_ControlWord.%X0 THEN 
        StartCmd := True; 
    END_IF;
END_FUNCTION_BLOCK
