```pascal
FUNCTION_BLOCK "RO_Skid_Adversarial"
VAR_INPUT
    FeedPres_A : Real;
    FeedPres_B : Real;
    HIL_Mode_Active : Bool;
END_VAR
VAR
    Sensor_Drift_Alarm : Bool;
