    IF HIL_Mode_Active THEN
        // Bypass physical I/O mappings, read from Twin arrays
        FeedFlow_PV := Twin_Flow_Sim;
        ORP_PV := Twin_ORP_Sim;
    END_IF;

    // Automated Startup Self-Test (Valve Proving)
    IF State = 10 THEN // State 10 = Self Test
        CASE SelfTest_Step OF
            0:
                InletValve := True;
                SelfTest_Timer(IN:=True, PT:=T#2s);
                IF SelfTest_Timer.Q AND FeedPres_A > 1.0 THEN
                    SelfTest_Step := 1;
                    SelfTest_Timer(IN:=False, PT:=T#2s);
                END_IF;
            1:
                FlushValve := True;
                State := 1; // Transition to run
        END_CASE;
    END_IF;
END_FUNCTION_BLOCK
