FUNCTION_BLOCK "FB_Desalination_Evaporator"
VERSION : 0.1
   VAR_INPUT
      i_Start : Bool;
      i_Stop : Bool;
      i_BrineConcentration : Real; // Current brine concentration (ppm or %)
      i_SteamPressure : Real; // Current steam pressure (bar)
      i_ConcSetpoint : Real; // Maximum allowed brine concentration
