    // IEC 62443 Cybersecurity & SCADA
    {attribute 'OPC.UA.DA' := '1'}
    bAuthorizedUser : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    nSecurityLevel : INT; // 0=None, 1=Read, 2=Write, 3=Admin

    {attribute 'OPC.UA.DA' := '1'}
    fDiffPressure_SP_SCADA : REAL := 50.0;

    // Process variables
    fOutdoorTemp : REAL;
    fSupplyTemp_SP : REAL;
    fActualSupplyTemp : REAL;
    fActualReturnTemp : REAL;
    fPrimaryValveCmd : REAL;
    fDiffPressure : REAL;
    fPumpSpeedCmd : REAL;

    fbPID_Temp : FB_BasicPID;
    fbPID_Pressure : FB_BasicPID;

    // Failover Pump Control
    bPump1_Cmd : BOOL;
    bPump2_Cmd : BOOL;
    bPump1_Fault : BOOL;
    bPump2_Fault : BOOL;
    tDutyTimer : TON;
    bSwitchDuty : BOOL;
    nActivePump : INT := 1;

    bSystemFault : BOOL;
END_VAR

// Duty standby switch every 24h
tDutyTimer(IN := TRUE, PT := T#24H, Q => bSwitchDuty);
IF bSwitchDuty THEN
    nActivePump := SEL(nActivePump = 1, 1, 2);
    tDutyTimer(IN := FALSE);
END_IF

// Failover logic
IF nActivePump = 1 AND bPump1_Fault THEN nActivePump := 2; END_IF
IF nActivePump = 2 AND bPump2_Fault THEN nActivePump := 1; END_IF

// Control execution restricted by security level
IF nSecurityLevel >= 2 AND bAuthorizedUser AND NOT bSystemFault THEN
    bPump1_Cmd := (nActivePump = 1);
    bPump2_Cmd := (nActivePump = 2);

    fSupplyTemp_SP := LIMIT(40.0, 90.0 - (1.5 * fOutdoorTemp), 90.0);
    fbPID_Temp(fSetpoint := fSupplyTemp_SP, fActualValue := fActualSupplyTemp, fKp := 2.5, fTi := 100.0, fControlValue => fPrimaryValveCmd);

    IF (fActualSupplyTemp - fActualReturnTemp) < 15.0 THEN
        fPrimaryValveCmd := fPrimaryValveCmd * 0.85;
    END_IF

    fbPID_Pressure(fSetpoint := fDiffPressure_SP_SCADA, fActualValue := fDiffPressure, fKp := 1.0, fTi := 50.0, fControlValue => fPumpSpeedCmd);
ELSE
    fPrimaryValveCmd := 0.0;
    fPumpSpeedCmd := 0.0;
    bPump1_Cmd := FALSE;
