FUNCTION_BLOCK "BlastFurnace_Mut3"
VAR_INPUT
    Auth_Role : INT; // 1: Operator, 2: Engineer, 3: Admin
    Auth_Token_Valid : BOOL;
    Redundant_PLC_Active : BOOL;
    Redundant_PLC_Heartbeat : INT;
    SCADA_Watchdog_In : INT;

    // Process Inputs...
    Tuyere_Flow_SP : REAL;
    Tuyere_Flow_PV : REAL;
END_VAR
VAR_OUTPUT
    SCADA_Watchdog_Out : INT;
    System_Mode : INT; // 0: Offline, 1: Primary, 2: Standby, 3: SafeMode
    Security_Alert : BOOL;

    Tuyere_Valve_CV : REAL;
END_VAR
VAR
    Last_SCADA_Watchdog : INT;
    SCADA_Timeout_Counter : INT;
    Failover_Timer : INT;
END_VAR

BEGIN
    // IEC 62443 Role-based access check for setpoint changes
    IF NOT #Auth_Token_Valid OR #Auth_Role < 1 THEN
        #Security_Alert := TRUE;
        #System_Mode := 3; // Safe Mode
        RETURN;
    ELSE
        #Security_Alert := FALSE;
    END_IF;

    // SCADA Watchdog
    IF #SCADA_Watchdog_In = #Last_SCADA_Watchdog THEN
        #SCADA_Timeout_Counter := #SCADA_Timeout_Counter + 1;
        IF #SCADA_Timeout_Counter > 100 THEN
            #System_Mode := 3; // SCADA Lost - Safe Mode
        END_IF;
    ELSE
        #SCADA_Timeout_Counter := 0;
        #Last_SCADA_Watchdog := #SCADA_Watchdog_In;
    END_IF;
    #SCADA_Watchdog_Out := #SCADA_Watchdog_In + 1;

    // Hardware Failover Logic
    IF #Redundant_PLC_Active AND #Redundant_PLC_Heartbeat > 0 THEN
        #System_Mode := 2; // Standby
        #Tuyere_Valve_CV := 0.0; // Let primary control
    ELSE
        #System_Mode := 1; // Primary
        // Simplified PI Control Execution
        #Tuyere_Valve_CV := LIMIT(MN:=0.0, IN:=(#Tuyere_Flow_SP - #Tuyere_Flow_PV), MX:=100.0);
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "BlastFurnace_Mut4"
VAR_INPUT
    HIL_Mode_Active : BOOL;
    HIL_DigitalTwin_Pressure : REAL;

    Pressure_Sensor_1 : REAL;
    Pressure_Sensor_2 : REAL;

    Startup_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    Drift_Alarm : BOOL;
    Pressure_Consolidated : REAL;

    Startup_Phase : INT; // 0: Idle, 1: Self-Test, 2: Ready, 3: Fault
    Valve_Test_Command : REAL;
END_VAR
VAR
    Sensor_Diff : REAL;
    Drift_Filter : REAL;
    Test_Timer : INT;
END_VAR

BEGIN
    // HIL Digital Twin Synchronization
    IF #HIL_Mode_Active THEN
        #Pressure_Consolidated := #HIL_DigitalTwin_Pressure; // Override physical
    ELSE
        // Sensor Drift Detection (Adversarial Robustness)
        #Sensor_Diff := ABS(#Pressure_Sensor_1 - #Pressure_Sensor_2);
        // EWMA Filter for drift
        #Drift_Filter := (#Drift_Filter * 0.9) + (#Sensor_Diff * 0.1);

        IF #Drift_Filter > 5.0 THEN
            #Drift_Alarm := TRUE;
            #Pressure_Consolidated := (#Pressure_Sensor_1 + #Pressure_Sensor_2) / 2.0; // Best effort
        ELSE
            #Drift_Alarm := FALSE;
            #Pressure_Consolidated := #Pressure_Sensor_1; // Primary valid
        END_IF;
    END_IF;

    // Automated Startup Self-Test Routine
    IF #Startup_Cmd AND #Startup_Phase = 0 THEN
        #Startup_Phase := 1; // Begin Test
        #Test_Timer := 0;
    END_IF;

    IF #Startup_Phase = 1 THEN
        #Test_Timer := #Test_Timer + 1;
        // Inject fault simulation - pulse valve
        IF #Test_Timer < 50 THEN
            #Valve_Test_Command := 100.0;
        ELSIF #Test_Timer < 100 THEN
            #Valve_Test_Command := 0.0;
            // Validate feedback here in a real system
        ELSE
            IF NOT #Drift_Alarm THEN
                #Startup_Phase := 2; // Ready
            ELSE
                #Startup_Phase := 3; // Failed Test
            END_IF;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK

