```pascal
PROGRAM PRG_ContinuousCasting
VAR
    // IO
    rMoldLevelSensor_1 AT %I* : REAL;
    rMoldLevelSensor_2 AT %I* : REAL; 
    rCoolingWaterTemp AT %I* : REAL;
    rTundishHydraulicPress AT %I* : REAL;
    bSystemEnable AT %I* : BOOL;

    rStopperRodPos AT %Q* : REAL;
    rCoolingValvePos AT %Q* : REAL;
    rSlideGateValvePos AT %Q* : REAL;

    // SCADA & Security
    rMoldLevelSP : REAL := 500.0;
    sActiveRole : STRING := 'Engineer';
    bPrimaryPLCActive : BOOL := TRUE;

    // Adv: Sensor Drift & Twin
    rMoldLevelTwin : REAL; // From HIL simulation
    rMoldLevelConsensus : REAL;
    bSensorDriftDetected : BOOL;
    rDriftThreshold : REAL := 15.0; // mm

    // Adv: Self-Test
    bSelfTestRunning : BOOL;
    bSelfTestPassed : BOOL;
    nSelfTestStep : INT;

    // Controllers
    fbMoldLevelPID : FB_BasicPID;
    fbCoolingPID : FB_BasicPID;
END_VAR

// Pre-cast Self-Test Routine
IF bSystemEnable AND NOT bSelfTestPassed THEN
    bSelfTestRunning := TRUE;
    CASE nSelfTestStep OF
        0: 
            rStopperRodPos := 10.0; // Stroke test
            IF rTundishHydraulicPress > 140.0 THEN nSelfTestStep := 1; END_IF;
        1:
            rCoolingValvePos := 50.0;
            nSelfTestStep := 2;
        2:
            bSelfTestRunning := FALSE;
            bSelfTestPassed := TRUE;
    END_CASE;
    RETURN;
END_IF;

// Sensor Drift Detection & HIL Sync
IF ABS(rMoldLevelSensor_1 - rMoldLevelSensor_2) > rDriftThreshold THEN
    bSensorDriftDetected := TRUE;
    // Fallback to HIL Digital Twin estimation
    rMoldLevelConsensus := (rMoldLevelTwin + rMoldLevelSensor_1) / 2.0;
ELSE
    bSensorDriftDetected := FALSE;
    rMoldLevelConsensus := (rMoldLevelSensor_1 + rMoldLevelSensor_2) / 2.0;
    rMoldLevelTwin := rMoldLevelConsensus; // Sync Twin
END_IF;

// Core Control Logic
IF bSelfTestPassed AND NOT bSensorDriftDetected THEN
    fbMoldLevelPID(
        fSetpoint := rMoldLevelSP,
        fActual := rMoldLevelConsensus,
        bEnable := TRUE,
        fKp := 2.5, fTi := 1.0, fTd := 0.1,
        fOutput => rStopperRodPos
    );
    rSlideGateValvePos := rStopperRodPos;

    fbCoolingPID(
        fSetpoint := 30.0,
        fActual := rCoolingWaterTemp,
        bEnable := TRUE,
        fKp := 1.2, fTi := 2.0, fTd := 0.0,
        fOutput => rCoolingValvePos
    );
ELSE
    // Safe state if drift exceeds twin bounds or self-test fails
    rStopperRodPos := 0.0;
    rSlideGateValvePos := 0.0;
    rCoolingValvePos := 100.0;
END_IF;
