FUNCTION_BLOCK FB_SAF_Base
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    ElectrodeCurrent : REAL;
    CO_Level : REAL;
END_VAR
VAR_OUTPUT
    SlipElectrode : BOOL;
    ExhaustFanSpeed : REAL;
END_VAR
VAR
    Running : BOOL;
END_VAR
BEGIN
    IF Start AND NOT Stop THEN Running := TRUE; ELSIF Stop THEN Running := FALSE; END_IF;
    IF Running THEN
        SlipElectrode := (ElectrodeCurrent > 15000.0);
        ExhaustFanSpeed := LIMIT(MN:=0.0, IN:=(CO_Level * 0.2), MX:=100.0);
    ELSE
        SlipElectrode := FALSE; ExhaustFanSpeed := 0.0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_SAF_Depth
VAR_INPUT
    Start, Stop : BOOL;
    ElectrodeCurrent, CO_Level, WaterTempIn, WaterTempOut : REAL;
END_VAR
VAR_OUTPUT
    SlipElectrode, Alarm_Cooling : BOOL;
    ExhaustFanSpeed, PumpSpeed : REAL;
END_VAR
VAR
    Running : BOOL;
    DeltaT : REAL;
END_VAR
BEGIN
    IF Start AND NOT Stop THEN Running := TRUE; ELSIF Stop THEN Running := FALSE; END_IF;
    IF Running THEN
        SlipElectrode := (ElectrodeCurrent > 15000.0);
        ExhaustFanSpeed := LIMIT(MN:=0.0, IN:=(CO_Level * 0.2), MX:=100.0);
        DeltaT := WaterTempOut - WaterTempIn;
        Alarm_Cooling := (DeltaT > 25.0);
        PumpSpeed := 50.0 + (DeltaT * 2.0);
    ELSE
        SlipElectrode := FALSE; Alarm_Cooling := FALSE; ExhaustFanSpeed := 0.0; PumpSpeed := 0.0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_SAF_Breadth
VAR_INPUT
    Start, Stop : BOOL;
    ElectrodeCurrent, CO_Level : REAL;
    PN_Status : WORD;
END_VAR
VAR_OUTPUT
    SlipElectrode : BOOL;
    ExhaustFanSpeed : REAL;
    FaultCode : WORD;
    PN_Control : WORD;
END_VAR
VAR
    Running : BOOL;
    CommError : BOOL;
END_VAR
BEGIN
    CommError := (PN_Status AND 16#0001) = 0;
    IF CommError THEN
        FaultCode := 16#E001; Running := FALSE;
    ELSIF Start AND NOT Stop THEN
        Running := TRUE; FaultCode := 16#0000;
    ELSIF Stop THEN
        Running := FALSE;
    END_IF;
    IF Running THEN
        SlipElectrode := (ElectrodeCurrent > 15000.0);
        ExhaustFanSpeed := LIMIT(MN:=0.0, IN:=(CO_Level * 0.2), MX:=100.0);
        PN_Control := 16#0001;
    ELSE
        SlipElectrode := FALSE; ExhaustFanSpeed := 0.0; PN_Control := 16#0000;
    END_IF;
END_FUNCTION_BLOCK

