            IF HIL_Mode THEN CO_Value := HIL_DataIn; END_IF;
            HIL_DataOut := CO_Value;
            ExhaustFanSpeed := LIMIT(MN:=0.0, IN:=(CO_Value * 0.5), MX:=100.0);
    END_CASE;
