PROGRAM PRG_MineHoist_M4
TYPE E_HoistState :
(
    STATE_INIT := 0,
    STATE_SELF_TEST := 1,
    STATE_READY := 2,
    STATE_RUNNING := 3,
    STATE_FAULT := 99
);
END_TYPE

VAR
    eState : E_HoistState := STATE_INIT;

    bHIL_ModeActive : BOOL;
    fDigitalTwinPosition : REAL;
    fPositionDeviation : REAL;

    fHoistPosition_Enc1 AT %I* : REAL;
    fHoistPosition_Enc2 AT %I* : REAL;
    fEncoderDrift : REAL;
    fMaxAllowedDrift : REAL := 0.05;
    bDriftFault : BOOL;

    fActualPosition : REAL;

    bScadaStartCommand : BOOL;
    bScadaStopCommand : BOOL;
    nUserRole : INT;

    bHoistMotorRun AT %Q* : BOOL;
    bHoistBrakeRelease AT %Q* : BOOL;
    fMotorSpeedSetpoint AT %Q* : REAL;

    tSelfTestTimer : TON;
    bSelfTestPassed : BOOL;

    fTargetPosition : REAL := 500.0;
END_VAR

fEncoderDrift := ABS(fHoistPosition_Enc1 - fHoistPosition_Enc2);
IF fEncoderDrift > fMaxAllowedDrift THEN
    bDriftFault := TRUE;
    eState := STATE_FAULT;
ELSE
    fActualPosition := (fHoistPosition_Enc1 + fHoistPosition_Enc2) / 2.0;
END_IF

IF bHIL_ModeActive THEN
    fPositionDeviation := ABS(fActualPosition - fDigitalTwinPosition);
    IF fPositionDeviation > 1.0 THEN
        eState := STATE_FAULT;
    END_IF
END_IF

CASE eState OF
    STATE_INIT:
        bHoistMotorRun := FALSE;
        bHoistBrakeRelease := FALSE;
        IF NOT bDriftFault THEN
            eState := STATE_SELF_TEST;
        END_IF

    STATE_SELF_TEST:
        bHoistBrakeRelease := TRUE;
        tSelfTestTimer(IN:=TRUE, PT:=T#2S);
        IF tSelfTestTimer.Q THEN
            bHoistBrakeRelease := FALSE;
            bSelfTestPassed := TRUE;
            tSelfTestTimer(IN:=FALSE);
            eState := STATE_READY;
        END_IF

    STATE_READY:
        IF bScadaStartCommand AND nUserRole >= 1 AND bSelfTestPassed THEN
            eState := STATE_RUNNING;
        END_IF

    STATE_RUNNING:
        IF bScadaStopCommand OR bDriftFault THEN
            eState := STATE_FAULT;
        ELSE
            bHoistBrakeRelease := TRUE;
            IF ABS(fTargetPosition - fActualPosition) > 0.1 THEN
                bHoistMotorRun := TRUE;
                fMotorSpeedSetpoint := SEL(fActualPosition < fTargetPosition, -2.0, 2.0);
            ELSE
                bHoistMotorRun := FALSE;
                fMotorSpeedSetpoint := 0.0;
                eState := STATE_READY;
            END_IF
        END_IF

    STATE_FAULT:
        bHoistMotorRun := FALSE;
        bHoistBrakeRelease := FALSE;
        fMotorSpeedSetpoint := 0.0;
        IF bScadaStopCommand THEN
            IF NOT bDriftFault THEN eState := STATE_INIT; END_IF
        END_IF
END_CASE
```

FUNCTION_BLOCK "Azipod_Control"
TITLE = 'Azipod Thruster Control'
VERSION : 1.0

VAR_INPUT
    Enable : BOOL; // System enable
    Setpoint_Angle : REAL; // Desired azimuth angle (0.0 to 360.0 degrees)
    Setpoint_Speed : REAL; // Desired thruster speed (RPM)
    Actual_Angle : REAL; // Feedback azimuth angle
    Actual_Speed : REAL; // Feedback thruster speed
    Motor_Current : REAL; // Actual motor current (Amps)
    Max_Allowed_Current : REAL; // Maximum allowed current (Amps)
END_VAR

VAR_OUTPUT
    Angle_Command : REAL; // Output command for azimuth angle
    Speed_Command : REAL; // Output command for thruster speed
    Overload_Active : BOOL; // Overload protection status
    System_Ready : BOOL; // Ready for operation
END_VAR

VAR
    Current_Filter : REAL;
    Filter_Coeff : REAL := 0.1;
    Speed_Limit : REAL;
END_VAR

BEGIN
    // Initialization
    System_Ready := Enable AND NOT Overload_Active;

    IF NOT Enable THEN
        Angle_Command := Actual_Angle;
        Speed_Command := 0.0;
        Overload_Active := FALSE;
        Current_Filter := 0.0;
        RETURN;
    END_IF;

    // Filter motor current
    Current_Filter := Current_Filter + Filter_Coeff * (Motor_Current - Current_Filter);

    // Overload Protection Logic
    IF Current_Filter > Max_Allowed_Current THEN
        Overload_Active := TRUE;
    ELSIF Current_Filter < (Max_Allowed_Current * 0.8) THEN
        Overload_Active := FALSE;
    END_IF;

    // Speed Control & Synchronization
    IF Overload_Active THEN
        // Reduce speed to prevent trip
        Speed_Limit := Actual_Speed * 0.5;
        IF Setpoint_Speed > Speed_Limit THEN
            Speed_Command := Speed_Limit;
        ELSE
            Speed_Command := Setpoint_Speed;
        END_IF;
    ELSE
        Speed_Command := Setpoint_Speed;
    END_IF;

    // Azimuth Control
    Angle_Command := Setpoint_Angle;

END_FUNCTION_BLOCK

FUNCTION_BLOCK "Azipod_DP_Control"
TITLE = 'Azipod Control with DP Thrust Allocation'
VERSION : 1.1

VAR_INPUT
    Enable : BOOL;
    DP_Force_X : REAL; // Desired surge force (kN)
    DP_Force_Y : REAL; // Desired sway force (kN)
    DP_Moment_Z : REAL; // Desired yaw moment (kNm)
    Actual_Angle : REAL;
    Actual_Speed : REAL;
    Motor_Current : REAL;
    Max_Allowed_Current : REAL;
    Hull_Resistance_Factor : REAL; // Dynamic resistance factor
END_VAR

VAR_OUTPUT
    Angle_Command : REAL;
    Speed_Command : REAL;
    Overload_Active : BOOL;
END_VAR

VAR
    Current_Filter : REAL;
    Req_Thrust : REAL;
    Req_Angle : REAL;
END_VAR

BEGIN
    IF NOT Enable THEN
        Angle_Command := Actual_Angle;
        Speed_Command := 0.0;
        Overload_Active := FALSE;
        RETURN;
    END_IF;

    // Thrust Allocation Algorithm (Simplified Cartesian to Polar)
    Req_Thrust := SQRT(DP_Force_X**2 + DP_Force_Y**2) * Hull_Resistance_Factor;
    IF DP_Force_X <> 0.0 THEN
        Req_Angle := ATAN(DP_Force_Y / DP_Force_X) * 57.2958; // Convert Rad to Deg
    ELSE
        Req_Angle := 0.0;
    END_IF;

    // Add yaw moment contribution
    Req_Angle := Req_Angle + (DP_Moment_Z * 0.1); 

    // Filter motor current
    Current_Filter := Current_Filter + 0.1 * (Motor_Current - Current_Filter);

    // Overload Protection
    IF Current_Filter > Max_Allowed_Current THEN
        Overload_Active := TRUE;
    ELSIF Current_Filter < (Max_Allowed_Current * 0.8) THEN
        Overload_Active := FALSE;
    END_IF;

    // Synchronization and Commands
    IF Overload_Active THEN
        Speed_Command := Req_Thrust * 0.5; // Load shedding
    ELSE
        Speed_Command := Req_Thrust;
    END_IF;

    Angle_Command := Req_Angle;

END_FUNCTION_BLOCK

