FUNCTION_BLOCK "Azipod_Secure_Control"
VAR_INPUT
    Primary_PN_Cmd : "Secure_Profinet_Cmd";
    Secondary_PN_Cmd : "Secure_Profinet_Cmd";
    Primary_PLC_Active : BOOL;
    Expected_Auth_Token : DWORD;
    Actual_Angle : REAL;
    Actual_Speed : REAL;
    Motor_Current : REAL;
    Max_Allowed_Current : REAL;
END_VAR

VAR_OUTPUT
    Angle_Command : REAL;
    Speed_Command : REAL;
    SCADA_Status : WORD;
    Cyber_Incident : BOOL;
    Active_Cmd : "Secure_Profinet_Cmd";
END_VAR

VAR
    Enable : BOOL;
    Req_Thrust : REAL;
    Req_Angle : REAL;
    Current_Filter : REAL;
    Overload_Active : BOOL;
END_VAR

BEGIN
    Cyber_Incident := FALSE;

    // Failover Logic
    IF Primary_PLC_Active THEN
        Active_Cmd := Primary_PN_Cmd;
    ELSE
        Active_Cmd := Secondary_PN_Cmd;
    END_IF;

    // IEC 62443 Security Check
    IF Active_Cmd.Auth_Token <> Expected_Auth_Token THEN
        Cyber_Incident := TRUE;
        SCADA_Status := 16#F000; // Security Breach
        Speed_Command := 0.0;
        Angle_Command := Actual_Angle;
        RETURN;
    END_IF;

    Enable := (Active_Cmd.Control_Word AND 16#0001) <> 0;

    IF NOT Enable THEN
        Speed_Command := 0.0;
        Angle_Command := Actual_Angle;
        SCADA_Status := 16#0000;
        RETURN;
    END_IF;

    // Safe state confirmed
    SCADA_Status := 16#0001; // Healthy

    // DP Logic
    Req_Thrust := SQRT(Active_Cmd.DP_Force_X**2 + Active_Cmd.DP_Force_Y**2);
    IF Active_Cmd.DP_Force_X <> 0.0 THEN
        Req_Angle := ATAN(Active_Cmd.DP_Force_Y / Active_Cmd.DP_Force_X) * 57.2958;
    ELSE
        Req_Angle := 0.0;
    END_IF;
    Req_Angle := Req_Angle + (Active_Cmd.DP_Moment_Z * 0.1);

    // Overload Protection
    Current_Filter := Current_Filter + 0.1 * (Motor_Current - Current_Filter);
    IF Current_Filter > Max_Allowed_Current THEN
        Overload_Active := TRUE;
        SCADA_Status := SCADA_Status OR 16#0002; // Overload Bit
    ELSIF Current_Filter < (Max_Allowed_Current * 0.8) THEN
        Overload_Active := FALSE;
    END_IF;

    IF Overload_Active THEN
        Speed_Command := Req_Thrust * 0.5;
    ELSE
        Speed_Command := Req_Thrust;
    END_IF;

    Angle_Command := Req_Angle;
END_FUNCTION_BLOCK

