    fRollTolerance     : REAL := 0.5;
    bBallastRequired   : BOOL;
    bActivePumpIsA     : BOOL := TRUE;
    tDutyCycleTimer    : TON;
END_VAR

// Determine Ballast Requirement
bBallastRequired := ABS(fInclinometerRoll) > fRollTolerance;

// Valve Control
IF fInclinometerRoll > fRollTolerance THEN
    bValvePort := TRUE;
    bValveStbd := FALSE;
ELSIF fInclinometerRoll < -fRollTolerance THEN
    bValvePort := FALSE;
    bValveStbd := TRUE;
ELSE
    bValvePort := FALSE;
    bValveStbd := FALSE;
END_IF

// Pump Duty Cycle Timer (Swap every 24 hours of operation)
tDutyCycleTimer(IN := bBallastRequired, PT := T#24H);
IF tDutyCycleTimer.Q THEN
    bActivePumpIsA := NOT bActivePumpIsA;
    tDutyCycleTimer(IN := FALSE); // Reset timer
END_IF

// Redundant Pump Sequencing
IF bBallastRequired THEN
    IF bActivePumpIsA AND NOT bPumpA_Fail THEN
        bPumpA_Cmd := TRUE;
        bPumpB_Cmd := FALSE;
    ELSIF NOT bActivePumpIsA AND NOT bPumpB_Fail THEN
        bPumpA_Cmd := FALSE;
        bPumpB_Cmd := TRUE;
    ELSIF bPumpA_Fail AND NOT bPumpB_Fail THEN
        bPumpA_Cmd := FALSE;
        bPumpB_Cmd := TRUE; // Auto failover to B
    ELSIF bPumpB_Fail AND NOT bPumpA_Fail THEN
        bPumpA_Cmd := TRUE; // Auto failover to A
        bPumpB_Cmd := FALSE;
    ELSE
        // Both pumps failed
        bPumpA_Cmd := FALSE;
        bPumpB_Cmd := FALSE;
    END_IF
ELSE
    bPumpA_Cmd := FALSE;
    bPumpB_Cmd := FALSE;
END_IF
