```iecst
PROGRAM PRG_BallastSystem_Breadth
VAR
    // Process Variables
    fInclinometerRoll  : REAL;
    bPumpA_Fail        : BOOL;
    bPumpB_Fail        : BOOL;

    bValvePort         : BOOL;
    bValveStbd         : BOOL;
    bPumpA_Cmd         : BOOL;
    bPumpB_Cmd         : BOOL;

    // Parameters & Control
    fRollTolerance     : REAL := 0.5;
    bBallastRequired   : BOOL;
    bActivePumpIsA     : BOOL := TRUE;
    tDutyCycleTimer    : TON;

    // EtherCAT Diagnostics
    fbGetMasterState   : FB_EcGetMasterState;
    nEcatMasterState   : UINT;
    bEcatError         : BOOL;
    nMasterDevId       : UINT := 1;

    // System Diagnostics
    bSystemFault       : BOOL;
    iFaultCode         : INT; // 0=OK, 1=PumpA Fail, 2=PumpB Fail, 3=Total Pump Fail, 4=ECAT Fault
END_VAR

// 1. EtherCAT Communication Diagnostics
fbGetMasterState(
    sNetId := '',
    bExecute := TRUE,
    tTimeout := T#2S,
    state => nEcatMasterState,
    bError => bEcatError
);

// Verify EtherCAT is in OP state (State 8 = OP)
IF nEcatMasterState <> 8 OR bEcatError THEN
    bSystemFault := TRUE;
    iFaultCode := 4;
END_IF

// 2. Trim & Ballast Logic
bBallastRequired := ABS(fInclinometerRoll) > fRollTolerance AND NOT bSystemFault;

IF bBallastRequired THEN
    bValvePort := (fInclinometerRoll > fRollTolerance);
    bValveStbd := (fInclinometerRoll < -fRollTolerance);
ELSE
    bValvePort := FALSE;
    bValveStbd := FALSE;
END_IF

// 3. Pump Sequencing & Fault Diagnostics
tDutyCycleTimer(IN := bBallastRequired, PT := T#24H);
IF tDutyCycleTimer.Q THEN
    bActivePumpIsA := NOT bActivePumpIsA;
    tDutyCycleTimer(IN := FALSE);
END_IF

IF bBallastRequired THEN
    IF bActivePumpIsA AND NOT bPumpA_Fail THEN
        bPumpA_Cmd := TRUE; bPumpB_Cmd := FALSE;
        iFaultCode := 0;
    ELSIF NOT bActivePumpIsA AND NOT bPumpB_Fail THEN
        bPumpA_Cmd := FALSE; bPumpB_Cmd := TRUE;
        iFaultCode := 0;
    ELSIF bPumpA_Fail AND NOT bPumpB_Fail THEN
        bPumpA_Cmd := FALSE; bPumpB_Cmd := TRUE;
        iFaultCode := 1; // Pump A failed, running B
    ELSIF bPumpB_Fail AND NOT bPumpA_Fail THEN
        bPumpA_Cmd := TRUE; bPumpB_Cmd := FALSE;
        iFaultCode := 2; // Pump B failed, running A
    ELSE
        bPumpA_Cmd := FALSE; bPumpB_Cmd := FALSE;
        bSystemFault := TRUE;
        iFaultCode := 3; // Total Pump Failure
    END_IF
ELSE
    bPumpA_Cmd := FALSE;
    bPumpB_Cmd := FALSE;
END_IF

// Safe state enforcement on network fault
IF bSystemFault AND iFaultCode = 4 THEN
    bValvePort := FALSE;
    bValveStbd := FALSE;
    bPumpA_Cmd := FALSE;
    bPumpB_Cmd := FALSE;
END_IF
```

The program now safely defaults to shutting off valves and pumps if the EtherCAT network leaves the Operational (OP) state, ensuring physical safety during communication loss. System-wide fault codes facilitate easy HMI alarm mapping.

