    END_IF

    IF bBallastRequired THEN
        IF bActivePumpIsA AND NOT bPumpA_Fail THEN
            bPumpA_Cmd := TRUE; bPumpB_Cmd := FALSE; stScadaData.iFaultCode := 0;
        ELSIF NOT bActivePumpIsA AND NOT bPumpB_Fail THEN
            bPumpA_Cmd := FALSE; bPumpB_Cmd := TRUE; stScadaData.iFaultCode := 0;
        ELSIF bPumpA_Fail AND NOT bPumpB_Fail THEN
            bPumpA_Cmd := FALSE; bPumpB_Cmd := TRUE; stScadaData.iFaultCode := 1;
        ELSIF bPumpB_Fail AND NOT bPumpA_Fail THEN
            bPumpA_Cmd := TRUE; bPumpB_Cmd := FALSE; stScadaData.iFaultCode := 2;
        ELSE
            bPumpA_Cmd := FALSE; bPumpB_Cmd := FALSE;
            stScadaData.bSystemFault := TRUE;
            stScadaData.iFaultCode := 3;
        END_IF
    ELSE
        bPumpA_Cmd := FALSE; bPumpB_Cmd := FALSE;
    END_IF
ELSE
    // Secure State Fallback (Zero Energy State)
    bValvePort := FALSE;
    bValveStbd := FALSE;
    bPumpA_Cmd := FALSE;
    bPumpB_Cmd := FALSE;
END_IF

// 4. Update SCADA mapping
stScadaData.fInclinometerRoll := fInclinometerRoll;
