END_TYPE

PROGRAM PRG_BallastSystem_Adversarial
VAR
    eMode              : E_SystemMode := MODE_INIT;

    // Redundant Sensors for Drift Detection
    fInclinometerRollA : REAL;
    fInclinometerRollB : REAL;
    fInclinometerRoll  : REAL; // Fused value
    fDriftThreshold    : REAL := 0.2;
    bSensorDriftFault  : BOOL;

    // HIL Digital Twin Sync
    bHilModeEnabled    : BOOL;
    fHilSimulatedRoll  : REAL;
    bHilSyncActive     : BOOL;

    // Self-Test Routine
    tSelfTestTimer     : TON;
    iTestStep          : INT := 0;
    bSelfTestRequest   : BOOL;
    bSelfTestPassed    : BOOL;

    // Core Actuators & Sequencing
    bPumpA_Fail        : BOOL;
    bPumpB_Fail        : BOOL;
    bValvePort         : BOOL;
    bValveStbd         : BOOL;
    bPumpA_Cmd         : BOOL;
    bPumpB_Cmd         : BOOL;
    bActivePumpIsA     : BOOL := TRUE;
    bBallastRequired   : BOOL;
    fRollTolerance     : REAL := 0.5;

    // Diagnostics & Security
    stScadaData        : ST_ScadaInterface; // From previous definitions
    bSecureLockout     : BOOL;
    bSystemFault       : BOOL;
END_VAR

// 1. Sensor Drift Detection (Adversarial Data Protection)
IF ABS(fInclinometerRollA - fInclinometerRollB) > fDriftThreshold THEN
    bSensorDriftFault := TRUE;
    bSystemFault := TRUE;
    stScadaData.iFaultCode := 5; // Sensor Drift Detected
    eMode := MODE_SECURE_HALT;
ELSE
    // Sensor Fusion (Averaging)
    fInclinometerRoll := (fInclinometerRollA + fInclinometerRollB) / 2.0;
END_IF

// 2. Hardware-In-The-Loop (HIL) Synchronization
IF bHilModeEnabled AND stScadaData.iAccessLevel = 3 THEN
    eMode := MODE_HIL_SYNC;
    fInclinometerRoll := fHilSimulatedRoll; // Inject simulated data
    bHilSyncActive := TRUE;
ELSE
    bHilSyncActive := FALSE;
END_IF

// 3. State Machine & Automated Self-Test
CASE eMode OF
    MODE_INIT:
        IF NOT bSystemFault THEN eMode := MODE_AUTO; END_IF

    MODE_AUTO, MODE_HIL_SYNC:
        // Cybersecurity Check
        IF bSecureLockout THEN
            eMode := MODE_SECURE_HALT;
        END_IF

        // Core Trim Logic
        bBallastRequired := ABS(fInclinometerRoll) > fRollTolerance;
        bValvePort := (fInclinometerRoll > fRollTolerance);
        bValveStbd := (fInclinometerRoll < -fRollTolerance);

        // Redundant Pump Logic
        IF bBallastRequired THEN
            IF bActivePumpIsA AND NOT bPumpA_Fail THEN
                bPumpA_Cmd := TRUE; bPumpB_Cmd := FALSE;
            ELSIF NOT bActivePumpIsA AND NOT bPumpB_Fail THEN
                bPumpA_Cmd := FALSE; bPumpB_Cmd := TRUE;
            ELSIF bPumpA_Fail AND NOT bPumpB_Fail THEN
                bPumpA_Cmd := FALSE; bPumpB_Cmd := TRUE;
            ELSIF bPumpB_Fail AND NOT bPumpA_Fail THEN
                bPumpA_Cmd := TRUE; bPumpB_Cmd := FALSE;
            ELSE
                bSystemFault := TRUE;
                eMode := MODE_SECURE_HALT;
            END_IF
        ELSE
            bPumpA_Cmd := FALSE; bPumpB_Cmd := FALSE;
        END_IF

        // Self-Test Transition
        IF bSelfTestRequest AND NOT bBallastRequired THEN
            eMode := MODE_SELF_TEST;
            iTestStep := 1;
        END_IF

    MODE_SELF_TEST:
        // Safe non-destabilizing self-test (Micro-pulsing valves and pumps)
        tSelfTestTimer(IN := TRUE, PT := T#2S);
        CASE iTestStep OF
            1: // Pulse Valve Port safely
               bValvePort := TRUE; bPumpA_Cmd := FALSE;
               IF tSelfTestTimer.Q THEN bValvePort := FALSE; tSelfTestTimer(IN:=FALSE); iTestStep := 2; END_IF
            2: // Pulse Valve Stbd safely
               bValveStbd := TRUE; bPumpB_Cmd := FALSE;
               IF tSelfTestTimer.Q THEN bValveStbd := FALSE; tSelfTestTimer(IN:=FALSE); iTestStep := 3; END_IF
            3: // Test Complete
               bSelfTestPassed := TRUE;
               bSelfTestRequest := FALSE;
               eMode := MODE_AUTO;
        END_CASE

    MODE_SECURE_HALT:
        // Zero-Energy Safe State
        bValvePort := FALSE;
        bValveStbd := FALSE;
        bPumpA_Cmd := FALSE;
        bPumpB_Cmd := FALSE;
        IF NOT bSystemFault AND NOT bSecureLockout THEN
            eMode := MODE_INIT;
        END_IF
END_CASE

// Update SCADA
stScadaData.fInclinometerRoll := fInclinometerRoll;
stScadaData.bSystemFault := bSystemFault;
