SCADA_Watchdog(IN:= NOT SCADA_Heartbeat, PT:= T#3s);
IF SCADA_Watchdog.Q THEN System_Fault := TRUE; END_IF;

IF System_Fault AND PLC_Standby_Ready THEN PLC_Active := FALSE; END_IF;

