    IF Ram_Open_Cmd THEN Ram_Opened := TRUE; Ram_Closed := FALSE; END_IF;
ELSE
    PumpA_Run := FALSE; PumpB_Run := FALSE;
END_IF;

EIP_BOP_Status.0 := PLC_Active;
EIP_BOP_Status.1 := Ram_Closed;
EIP_BOP_Status.2 := System_Fault;
EIP_BOP_Status.3 := Security_Lockout;
END_PROGRAM

PROGRAM SubseaBOP_M4
VAR
    Sys_Start : BOOL;
    Hyd_Pressure_PT1, Hyd_Pressure_PT2 : REAL;
    Hyd_Pressure_Avg : REAL;
    Set_Pressure : REAL := 3000.0;
    Sensor_Drift_Fault : BOOL;
    Max_Allowed_Drift : REAL := 50.0;
    HIL_Sync_Enable : BOOL;
    HIL_Ram_State : INT;
    Digital_Twin_Error : BOOL;
    Self_Test_Req, Self_Test_Active, Self_Test_Passed : BOOL;
    Self_Test_Timer : TON;
    Auth_Token_Valid, SCADA_Heartbeat, Security_Lockout : BOOL;
    PLC_Active : BOOL := TRUE;
    EIP_Cmds, EIP_Stats : WORD;
    PumpA_Run, PumpB_Run : BOOL;
    Ram_Close_Cmd, Ram_Open_Cmd, Ram_Closed, Ram_Opened : BOOL;
    System_Fault : BOOL;
END_VAR

IF ABS(Hyd_Pressure_PT1 - Hyd_Pressure_PT2) > Max_Allowed_Drift THEN
    Sensor_Drift_Fault := TRUE; System_Fault := TRUE;
ELSE
    Sensor_Drift_Fault := FALSE; Hyd_Pressure_Avg := (Hyd_Pressure_PT1 + Hyd_Pressure_PT2) / 2.0;
END_IF;

IF Self_Test_Req AND NOT Sys_Start AND Hyd_Pressure_Avg > 2000.0 THEN
    Self_Test_Active := TRUE;
    Self_Test_Timer(IN:= Self_Test_Active, PT:= T#2s);
    IF Self_Test_Timer.Q THEN Self_Test_Passed := TRUE; Self_Test_Active := FALSE; Self_Test_Req := FALSE; END_IF;
END_IF;

IF HIL_Sync_Enable THEN
    IF (Ram_Closed AND HIL_Ram_State <> 1) OR (Ram_Opened AND HIL_Ram_State <> 2) THEN
        Digital_Twin_Error := TRUE;
    ELSE
        Digital_Twin_Error := FALSE;
    END_IF;
END_IF;

IF PLC_Active AND Auth_Token_Valid AND NOT System_Fault THEN
    IF Hyd_Pressure_Avg < (Set_Pressure - 200.0) THEN PumpA_Run := TRUE;
    ELSIF Hyd_Pressure_Avg >= Set_Pressure THEN PumpA_Run := FALSE; END_IF;
    Ram_Close_Cmd := EIP_Cmds.1;
    Ram_Open_Cmd := EIP_Cmds.2;
    IF Ram_Close_Cmd THEN Ram_Closed := TRUE; Ram_Opened := FALSE; END_IF;
    IF Ram_Open_Cmd THEN Ram_Opened := TRUE; Ram_Closed := FALSE; END_IF;
END_IF;

EIP_Stats.0 := Sensor_Drift_Fault;
EIP_Stats.1 := Digital_Twin_Error;
EIP_Stats.2 := Self_Test_Passed;
END_PROGRAM

