   VAR_INPUT 
      reqTotalTension : Real; // Total requested tension across all winches [kN]
      actTensionW1 : Real; // Actual tension winch 1 [kN]
      actTensionW2 : Real; // Actual tension winch 2 [kN]
      actTensionW3 : Real; // Actual tension winch 3 [kN]
      actTensionW4 : Real; // Actual tension winch 4 [kN]
      enableSystem : Bool;
   END_VAR

   VAR_OUTPUT 
      cmdTorqueW1 : Real; // Commanded torque reference winch 1 [%]
      cmdTorqueW2 : Real; // Commanded torque reference winch 2 [%]
      cmdTorqueW3 : Real; // Commanded torque reference winch 3 [%]
      cmdTorqueW4 : Real; // Commanded torque reference winch 4 [%]
   END_VAR

   VAR 
      targetPerWinch : Real;
      errW1, errW2, errW3, errW4 : Real;
      Kp : Real := 1.5;
   END_VAR

BEGIN
    IF #enableSystem THEN
        #targetPerWinch := #reqTotalTension / 4.0;

        #errW1 := #targetPerWinch - #actTensionW1;
        #errW2 := #targetPerWinch - #actTensionW2;
        #errW3 := #targetPerWinch - #actTensionW3;
        #errW4 := #targetPerWinch - #actTensionW4;

        #cmdTorqueW1 := #targetPerWinch + (#errW1 * #Kp);
        #cmdTorqueW2 := #targetPerWinch + (#errW2 * #Kp);
        #cmdTorqueW3 := #targetPerWinch + (#errW3 * #Kp);
        #cmdTorqueW4 := #targetPerWinch + (#errW4 * #Kp);
    ELSE
        #cmdTorqueW1 := 0.0;
        #cmdTorqueW2 := 0.0;
        #cmdTorqueW3 := 0.0;
        #cmdTorqueW4 := 0.0;
    END_IF;
END_FUNCTION_BLOCK
