FUNCTION_BLOCK "FB_Turret_Load_Sharing_AHC"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT 
      reqTotalTension : Real;
      actTensionW1, actTensionW2, actTensionW3, actTensionW4 : Real;
      mruHeaveVelocity : Real; // Vessel heave velocity from MRU [m/s]
      mruHeavePosition : Real; // Vessel heave position [m]
      enableSystem : Bool;
   END_VAR

   VAR_OUTPUT 
      cmdTorqueW1, cmdTorqueW2, cmdTorqueW3, cmdTorqueW4 : Real;
