    IF #enableSystem THEN
        // AHC Calculation: Feed-forward adjustment based on vessel motion
        #ahcOffset := (#mruHeavePosition * #K_ahc_pos) + (#mruHeaveVelocity * #K_ahc_vel);

        // Base tension distribution + AHC offset
        #targetPerWinch := (#reqTotalTension / 4.0) + #ahcOffset;

        #cmdTorqueW1 := #targetPerWinch + ((#targetPerWinch - #actTensionW1) * #Kp);
        #cmdTorqueW2 := #targetPerWinch + ((#targetPerWinch - #actTensionW2) * #Kp);
        #cmdTorqueW3 := #targetPerWinch + ((#targetPerWinch - #actTensionW3) * #Kp);
        #cmdTorqueW4 := #targetPerWinch + ((#targetPerWinch - #actTensionW4) * #Kp);
    ELSE
        #cmdTorqueW1 := 0.0;
        #cmdTorqueW2 := 0.0;
        #cmdTorqueW3 := 0.0;
        #cmdTorqueW4 := 0.0;
    END_IF;
