FUNCTION_BLOCK "CRAC_Control_Cascade"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.1
   VAR_INPUT 
      Enable : Bool;   
      DeltaP_Sensor : Real;   
      DeltaP_SP : Real;   
      ReturnAir_Temp : Real;   
      SupplyAir_Temp : Real;   
      ReturnTemp_SP : Real;   
      MinSupplyAir_Temp : Real; // Limit constraint to prevent condensation
   END_VAR

   VAR_OUTPUT 
      Fan_Speed : Real;   
      Cooling_Valve : Real;   
      Running : Bool;   
   END_VAR

   VAR 
      instPID_DeltaP : "PID_Compact";
      instPID_Temp_Master : "PID_Compact";
      instPID_Temp_Slave : "PID_Compact";
      SupplyTemp_SP_Cascade : Real;
   END_VAR

BEGIN
	#Running := #Enable;

	// Differential Pressure Control (Fan Speed)
	#instPID_DeltaP(Setpoint := #DeltaP_SP,
	                Input := #DeltaP_Sensor,
	                Reset := NOT #Running,
	                Output => #Fan_Speed);

	// Temperature Control - Cascade Master (Return Air)
	#instPID_Temp_Master(Setpoint := #ReturnTemp_SP,
	                     Input := #ReturnAir_Temp,
	                     Reset := NOT #Running,
	                     Output => #SupplyTemp_SP_Cascade);

	// Apply Supply Air Lower Limit Constraint
	IF #SupplyTemp_SP_Cascade < #MinSupplyAir_Temp THEN
	    #SupplyTemp_SP_Cascade := #MinSupplyAir_Temp;
	END_IF;

	// Temperature Control - Cascade Slave (Supply Air)
	#instPID_Temp_Slave(Setpoint := #SupplyTemp_SP_Cascade,
	                    Input := #SupplyAir_Temp,
	                    Reset := NOT #Running,
	                    Output => #Cooling_Valve);

	IF NOT #Running THEN
	    #Fan_Speed := 0.0;
	    #Cooling_Valve := 0.0;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "CRAC_Control_Profinet_Diag"
