      MinSupplyAir_Temp : Real;
      VFD_Status_Word : Word; // Profinet Status word from VFD
      VFD_Fault_Code : Int;   // Profinet Fault code from VFD
      PN_IO_State : Bool;     // Profinet IO system state
   END_VAR

   VAR_OUTPUT 
      Fan_Speed : Real;   
      Cooling_Valve : Real;   
      VFD_Control_Word : Word; // Profinet Control word to VFD
      Running : Bool;   
      System_Fault : Bool;
      Alarm_Code : Int;
   END_VAR

   VAR 
      instPID_DeltaP : "PID_Compact";
      instPID_Temp_Master : "PID_Compact";
      instPID_Temp_Slave : "PID_Compact";
      SupplyTemp_SP_Cascade : Real;
      VFD_Ready : Bool;
      VFD_Faulted : Bool;
   END_VAR

BEGIN
	// Profinet Diagnostics
	#System_Fault := NOT #PN_IO_State;
	IF #System_Fault THEN
	    #Alarm_Code := 100; // PN failure
	    #Running := FALSE;
	ELSE
	    #Alarm_Code := 0;
	END_IF;

	// VFD Diagnostics parsing
	#VFD_Ready := (#VFD_Status_Word AND 16#0001) <> 0;
	#VFD_Faulted := (#VFD_Status_Word AND 16#0008) <> 0;

	IF #VFD_Faulted THEN
	    #System_Fault := TRUE;
	    #Alarm_Code := #VFD_Fault_Code;
	    #Running := FALSE;
	ELSIF NOT #System_Fault THEN
	    #Running := #Enable AND #VFD_Ready;
	END_IF;

	// Control Word Generation
	IF #Running THEN
	    #VFD_Control_Word := 16#047F; // ON command sequence
	ELSE
	    #VFD_Control_Word := 16#047E; // OFF command sequence
	END_IF;

	// Differential Pressure Control (Fan Speed)
	#instPID_DeltaP(Setpoint := #DeltaP_SP,
	                Input := #DeltaP_Sensor,
	                Reset := NOT #Running,
	                Output => #Fan_Speed);

	// Cascade Temperature Control
	#instPID_Temp_Master(Setpoint := #ReturnTemp_SP,
	                     Input := #ReturnAir_Temp,
	                     Reset := NOT #Running,
	                     Output => #SupplyTemp_SP_Cascade);

	IF #SupplyTemp_SP_Cascade < #MinSupplyAir_Temp THEN
	    #SupplyTemp_SP_Cascade := #MinSupplyAir_Temp;
	END_IF;

	#instPID_Temp_Slave(Setpoint := #SupplyTemp_SP_Cascade,
	                    Input := #SupplyAir_Temp,
	                    Reset := NOT #Running,
	                    Output => #Cooling_Valve);

	IF NOT #Running THEN
	    #Fan_Speed := 0.0;
	    #Cooling_Valve := 0.0;
	END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "CRAC_Control_Advanced_Redundancy"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.3
   VAR_INPUT 
      Enable : Bool;   
      DeltaP_Sensor : Real;   
      DeltaP_SP : Real;   
      ReturnAir_Temp : Real;   
      SupplyAir_Temp : Real;   
      ReturnTemp_SP : Real;   
      MinSupplyAir_Temp : Real;
      VFD_Status_Word : Word; 
      VFD_Fault_Code : Int;   
      PN_IO_State : Bool;     

      // Cyber Security & SCADA
      SCADA_Heartbeat : Bool;
      Secure_Access_Token : DWord;
      SCADA_Override_Cmd : Bool;

      // Redundancy N+1
      Unit_ID : Int;
      Peer_Running : Array[1..4] of Bool;
      Peer_Faulted : Array[1..4] of Bool;
      Max_Required_Units : Int;
   END_VAR

   VAR_OUTPUT 
      Fan_Speed : Real;   
      Cooling_Valve : Real;   
      VFD_Control_Word : Word; 
      Running : Bool;   
      System_Fault : Bool;
      Alarm_Code : Int;

      // SCADA Mapping
      SCADA_Data_Map : Struct
         Unit_State : Int;
         Active_Alarms : Int;
         Current_Load : Real;
      END_STRUCT;
   END_VAR

   VAR 
      instPID_DeltaP : "PID_Compact";
      instPID_Temp_Master : "PID_Compact";
      instPID_Temp_Slave : "PID_Compact";
      SupplyTemp_SP_Cascade : Real;
      VFD_Ready : Bool;
      VFD_Faulted : Bool;
      Heartbeat_Timer : TON_TIME;
      SCADA_Comm_Loss : Bool;
      i : Int;
      Active_Units_Count : Int;
      Duty_Request : Bool;
   END_VAR

   CONST
      VALID_TOKEN : DWord := 16#A5A5_5A5A;
   END_CONST

BEGIN
	// Cyber Security & SCADA Heartbeat
	#Heartbeat_Timer(IN := NOT #SCADA_Heartbeat, PT := T#5s);
	IF #Heartbeat_Timer.Q THEN
	    #SCADA_Comm_Loss := TRUE;
	ELSE
	    #SCADA_Comm_Loss := FALSE;
	END_IF;

	// SCADA Override Authentication (IEC 62443 Concept)
	IF #SCADA_Override_Cmd AND (#Secure_Access_Token = #VALID_TOKEN) AND NOT #SCADA_Comm_Loss THEN
	    #Duty_Request := TRUE; // SCADA forcing unit ON
	ELSE
	    // N+1 Redundancy Logic Negotiation
	    #Active_Units_Count := 0;
	    FOR #i := 1 TO 4 DO
	        IF #Peer_Running[#i] AND NOT #Peer_Faulted[#i] AND (#i <> #Unit_ID) THEN
	            #Active_Units_Count := #Active_Units_Count + 1;
	        END_IF;
	    END_FOR;

	    // Auto start if required units not met and unit ID is next in priority
	    IF #Active_Units_Count < #Max_Required_Units AND #Enable THEN
	        #Duty_Request := TRUE;
	    ELSE
	        #Duty_Request := FALSE;
	    END_IF;
	END_IF;

	// Diagnostics & Faults
	#System_Fault := NOT #PN_IO_State;
	IF #System_Fault THEN
	    #Alarm_Code := 100; 
	    #Running := FALSE;
	ELSE
	    #Alarm_Code := 0;
	END_IF;

	#VFD_Ready := (#VFD_Status_Word AND 16#0001) <> 0;
	#VFD_Faulted := (#VFD_Status_Word AND 16#0008) <> 0;

	IF #VFD_Faulted THEN
	    #System_Fault := TRUE;
	    #Alarm_Code := #VFD_Fault_Code;
	    #Running := FALSE;
	ELSIF NOT #System_Fault THEN
	    #Running := #Duty_Request AND #VFD_Ready;
	END_IF;

	// Control Word Generation
	IF #Running THEN
	    #VFD_Control_Word := 16#047F;
	ELSE
	    #VFD_Control_Word := 16#047E;
	END_IF;

	// Control Loops
	#instPID_DeltaP(Setpoint := #DeltaP_SP, Input := #DeltaP_Sensor, Reset := NOT #Running, Output => #Fan_Speed);
	#instPID_Temp_Master(Setpoint := #ReturnTemp_SP, Input := #ReturnAir_Temp, Reset := NOT #Running, Output => #SupplyTemp_SP_Cascade);

	IF #SupplyTemp_SP_Cascade < #MinSupplyAir_Temp THEN
	    #SupplyTemp_SP_Cascade := #MinSupplyAir_Temp;
	END_IF;

	#instPID_Temp_Slave(Setpoint := #SupplyTemp_SP_Cascade, Input := #SupplyAir_Temp, Reset := NOT #Running, Output => #Cooling_Valve);

	IF NOT #Running THEN
	    #Fan_Speed := 0.0;
	    #Cooling_Valve := 0.0;
	END_IF;

	// SCADA Data Mapping Update
	#SCADA_Data_Map.Unit_State := BOOL_TO_INT(#Running);
	#SCADA_Data_Map.Active_Alarms := #Alarm_Code;
	#SCADA_Data_Map.Current_Load := #Fan_Speed;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "CRAC_Control_DigitalTwin_Adversarial"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 2.0
   VAR_INPUT 
      Enable : Bool;   
      // Redundant Sensors
      DeltaP_Sensor_1 : Real;   
      DeltaP_Sensor_2 : Real;
      DeltaP_Sensor_3 : Real;
      DeltaP_SP : Real;   
      ReturnAir_Temp : Real;   
      SupplyAir_Temp : Real;   
      ReturnTemp_SP : Real;   
      MinSupplyAir_Temp : Real;

      VFD_Status_Word : Word; 
      VFD_Fault_Code : Int;   
      PN_IO_State : Bool;     

      // Cyber Security & SCADA
      SCADA_Heartbeat : Bool;
      Secure_Access_Token : DWord;
      SCADA_Override_Cmd : Bool;

      // Redundancy N+1
      Unit_ID : Int;
      Peer_Running : Array[1..4] of Bool;
      Peer_Faulted : Array[1..4] of Bool;
      Max_Required_Units : Int;

      // HIL Digital Twin Sync
      HIL_Mode_Active : Bool;
      HIL_Simulated_States : Array[1..10] of Real;
   END_VAR

   VAR_OUTPUT 
      Fan_Speed : Real;   
      Cooling_Valve : Real;   
      VFD_Control_Word : Word; 
      Running : Bool;   
      System_Fault : Bool;
      Alarm_Code : Int;

      // SCADA Mapping
      SCADA_Data_Map : Struct
         Unit_State : Int;
         Active_Alarms : Int;
         Current_Load : Real;
      END_STRUCT;

      // HIL Sync
      HIL_Actual_States : Array[1..10] of Real;
   END_VAR

   VAR 
      instPID_DeltaP : "PID_Compact";
      instPID_Temp_Master : "PID_Compact";
      instPID_Temp_Slave : "PID_Compact";
      SupplyTemp_SP_Cascade : Real;
      VFD_Ready : Bool;
      VFD_Faulted : Bool;
      Heartbeat_Timer : TON_TIME;
      SCADA_Comm_Loss : Bool;
      i : Int;
      Active_Units_Count : Int;
      Duty_Request : Bool;

      // Advanced diagnostics
      Validated_DeltaP : Real;
      Drift_Fault : Bool;

      // Self-Test
      Self_Test_Active : Bool;
      Self_Test_Step : Int;
      Self_Test_Timer : TON_TIME;
   END_VAR

   CONST
      VALID_TOKEN : DWord := 16#A5A5_5A5A;
      MAX_DRIFT : Real := 5.0; // max Pa drift between sensors
   END_CONST

BEGIN
	// HIL Digital Twin Data Mux
	IF #HIL_Mode_Active THEN
	    // Inject simulated states
	    #Validated_DeltaP := #HIL_Simulated_States[1];
	    #Drift_Fault := FALSE;
	ELSE
	    // Sensor Drift Detection (2 out of 3 logic / Median or Average mapping)
	    // Simple check: compare delta between 1 and 2, 2 and 3, 1 and 3
	    IF ABS(#DeltaP_Sensor_1 - #DeltaP_Sensor_2) > #MAX_DRIFT THEN
	        IF ABS(#DeltaP_Sensor_1 - #DeltaP_Sensor_3) > #MAX_DRIFT THEN
	            #Validated_DeltaP := #DeltaP_Sensor_2; // 1 is drifting
	            #Drift_Fault := TRUE;
	        ELSE
	            #Validated_DeltaP := #DeltaP_Sensor_1; // 2 is drifting
	            #Drift_Fault := TRUE;
	        END_IF;
	    ELSE
	        #Validated_DeltaP := (#DeltaP_Sensor_1 + #DeltaP_Sensor_2) / 2.0;
	        #Drift_Fault := FALSE;
	    END_IF;
	END_IF;

	// Self-Test Routine (Startup Sequence)
	IF #Enable AND NOT #Running AND NOT #System_Fault AND #Self_Test_Step = 0 THEN
	    #Self_Test_Active := TRUE;
	    #Self_Test_Step := 10; // Start Fan low speed test
	END_IF;

	#Self_Test_Timer(IN := #Self_Test_Active, PT := T#3s);
	IF #Self_Test_Timer.Q THEN
	    IF #Self_Test_Step = 10 THEN
	        // Check Fan VFD feedback
	        #Self_Test_Step := 20; // Valve stroke test
	        #Self_Test_Timer(IN := FALSE, PT := T#3s);
	    ELSIF #Self_Test_Step = 20 THEN
	        #Self_Test_Step := 30; // Test complete
	        #Self_Test_Active := FALSE;
	    END_IF;
	END_IF;

	// Cyber Security & SCADA Heartbeat
	#Heartbeat_Timer(IN := NOT #SCADA_Heartbeat, PT := T#5s);
	#SCADA_Comm_Loss := #Heartbeat_Timer.Q;

	IF #SCADA_Override_Cmd AND (#Secure_Access_Token = #VALID_TOKEN) AND NOT #SCADA_Comm_Loss THEN
	    #Duty_Request := TRUE; 
	ELSE
	    #Active_Units_Count := 0;
	    FOR #i := 1 TO 4 DO
	        IF #Peer_Running[#i] AND NOT #Peer_Faulted[#i] AND (#i <> #Unit_ID) THEN
	            #Active_Units_Count := #Active_Units_Count + 1;
	        END_IF;
	    END_FOR;

	    IF #Active_Units_Count < #Max_Required_Units AND #Enable AND NOT #Self_Test_Active AND (#Self_Test_Step = 30) THEN
	        #Duty_Request := TRUE;
	    ELSE
	        #Duty_Request := FALSE;
	    END_IF;
	END_IF;

	// Diagnostics & Faults
	#System_Fault := NOT #PN_IO_State OR #Drift_Fault;
	IF #System_Fault THEN
	    #Alarm_Code := 100; 
	    #Running := FALSE;
	    #Self_Test_Step := 0; // reset test
	ELSE
	    #Alarm_Code := 0;
	END_IF;

	#VFD_Ready := (#VFD_Status_Word AND 16#0001) <> 0;
	#VFD_Faulted := (#VFD_Status_Word AND 16#0008) <> 0;

	IF #VFD_Faulted THEN
	    #System_Fault := TRUE;
	    #Alarm_Code := #VFD_Fault_Code;
	    #Running := FALSE;
	ELSIF NOT #System_Fault AND NOT #Self_Test_Active THEN
	    #Running := #Duty_Request AND #VFD_Ready;
	END_IF;

	// Control Logic
	IF #Self_Test_Active THEN
	    IF #Self_Test_Step = 10 THEN
	        #Fan_Speed := 15.0; // Test speed
	        #Cooling_Valve := 0.0;
	        #VFD_Control_Word := 16#047F;
	    ELSIF #Self_Test_Step = 20 THEN
	        #Fan_Speed := 0.0;
	        #Cooling_Valve := 10.0; // Valve stroke
	        #VFD_Control_Word := 16#047E;
	    END_IF;
	ELSE
	    IF #Running THEN
	        #VFD_Control_Word := 16#047F;
	    ELSE
	        #VFD_Control_Word := 16#047E;
	    END_IF;

	    #instPID_DeltaP(Setpoint := #DeltaP_SP, Input := #Validated_DeltaP, Reset := NOT #Running, Output => #Fan_Speed);
	    #instPID_Temp_Master(Setpoint := #ReturnTemp_SP, Input := #ReturnAir_Temp, Reset := NOT #Running, Output => #SupplyTemp_SP_Cascade);

	    IF #SupplyTemp_SP_Cascade < #MinSupplyAir_Temp THEN
	        #SupplyTemp_SP_Cascade := #MinSupplyAir_Temp;
	    END_IF;

	    #instPID_Temp_Slave(Setpoint := #SupplyTemp_SP_Cascade, Input := #SupplyAir_Temp, Reset := NOT #Running, Output => #Cooling_Valve);

	    IF NOT #Running THEN
	        #Fan_Speed := 0.0;
	        #Cooling_Valve := 0.0;
	    END_IF;
	END_IF;

	// HIL Map
	#HIL_Actual_States[1] := #Fan_Speed;
	#HIL_Actual_States[2] := #Cooling_Valve;

	// SCADA Data Mapping
	#SCADA_Data_Map.Unit_State := BOOL_TO_INT(#Running);
	#SCADA_Data_Map.Active_Alarms := #Alarm_Code;
	#SCADA_Data_Map.Current_Load := #Fan_Speed;
END_FUNCTION_BLOCK

