PID_Error := CondWaterSupplyTemp - CondWaterResetSetpoint;
TowerFanSpeed_Pct := TowerFanSpeed_Pct + (PID_Error * 0.5);

CompressorLift := CondWaterSupplyTemp - 42.0;
SurgeMargin := (ChillerLoad_Pct * 2.5) - CompressorLift;
IF SurgeMargin < 10.0 THEN SurgeAlarm := TRUE; ELSE SurgeAlarm := FALSE; END_IF;
END_PROGRAM

PROGRAM ChillerPlantOptimizer_Mut4
VAR
    OAT_WetBulb : REAL;
    CondWaterSupplyTemp : REAL;
    CondWaterResetSetpoint : REAL;
    ChillerLoad_Pct : REAL;
    CompressorLift : REAL;
    SurgeMargin : REAL;
    SurgeAlarm : BOOL;
    TowerFanSpeed_Pct : REAL;
    PID_Error : REAL;
    PrimarySensorFailed : BOOL;
    RedundantSensorReading : REAL;
    PrimarySensorReading : REAL;
    ValidatedOAT : REAL;
    SensorDriftDeviation : REAL;
    DiagnosticMsg : STRING;
    HIL_TwinStateSync : BOOL;
    SelfTestActive : BOOL;
    SelfTestStep : INT;
END_VAR

IF SelfTestActive THEN
    CASE SelfTestStep OF
        0: SelfTestStep := 1;
        1: SelfTestStep := 2;
        2: SelfTestActive := FALSE;
    END_CASE;
    RETURN;
END_IF;

SensorDriftDeviation := ABS(PrimarySensorReading - RedundantSensorReading);
IF SensorDriftDeviation > 2.0 THEN
    DiagnosticMsg := 'Sensor Drift Detected - Calibration Required';
END_IF;

IF PrimarySensorFailed THEN
    ValidatedOAT := RedundantSensorReading;
ELSE
    ValidatedOAT := PrimarySensorReading;
END_IF;
OAT_WetBulb := ValidatedOAT;

CondWaterResetSetpoint := OAT_WetBulb + 7.0;
IF CondWaterResetSetpoint < 65.0 THEN CondWaterResetSetpoint := 65.0; END_IF;
IF CondWaterResetSetpoint > 85.0 THEN CondWaterResetSetpoint := 85.0; END_IF;

PID_Error := CondWaterSupplyTemp - CondWaterResetSetpoint;
TowerFanSpeed_Pct := TowerFanSpeed_Pct + (PID_Error * 0.5);

CompressorLift := CondWaterSupplyTemp - 42.0;
SurgeMargin := (ChillerLoad_Pct * 2.5) - CompressorLift;
IF SurgeMargin < 10.0 THEN SurgeAlarm := TRUE; ELSE SurgeAlarm := FALSE; END_IF;

HIL_TwinStateSync := TRUE;
END_PROGRAM

