    // Redundancy Failover
    IF NOT #Primary_PLC_Active THEN
        RETURN;
    END_IF;

    // IEC 62443 Security check
    #Security_Alert := FALSE;
    #Valid_Auth := (#SCADA_Auth_Token = 16#A1B2C3D4); 

    IF #SCADA_Override AND NOT #Valid_Auth THEN
