    fSupplyFanCV : LREAL;
    fbTempPID, fbHumidityPID, fbPressPID : FB_CTRL_PID;

    // Particle and HEPA Sub-System
    nParticleCount0_5um : UDINT; // Particles >= 0.5um per cubic meter
    nParticleLimit      : UDINT := 3520; // ISO Class 5 limit
    fHepaDiffPress      : LREAL; // HEPA filter differential pressure
    fHepaDiffLimit      : LREAL := 250.0; // Max DP before filter change (Pa)

    // Purge Sequence
    bPurgeRequired      : BOOL;
    bPurgeActive        : BOOL;
    tPurgeTimer         : TON;
    tPurgeDuration      : TIME := T#15M;
    bHepaAlarm          : BOOL;
END_VAR

// Evaluate HEPA Filter Status
bHepaAlarm := (fHepaDiffPress > fHepaDiffLimit);

// Particle Counting and Purge Logic
IF nParticleCount0_5um > nParticleLimit THEN
    bPurgeRequired := TRUE;
END_IF

// Purge Timer
tPurgeTimer(IN := bPurgeActive, PT := tPurgeDuration);

IF bPurgeRequired AND NOT bPurgeActive THEN
    bPurgeActive := TRUE;
ELSIF tPurgeTimer.Q THEN
    bPurgeActive := FALSE;
    bPurgeRequired := FALSE;
END_IF

// Pressure Control Override during Purge
IF bPurgeActive THEN
    // Maximize air changes
    fSupplyFanCV := 100.0;
ELSE
    // Normal Cascading Pressure Control
    fbPressPID(
        fSetpointValue  := fDiffPressSP,
        fActualValue    := (fPressCleanroom - fPressAnteroom),
        fManSyncValue   := 0.0,
        bSync           := FALSE,
        eMode           := eCTRL_MODE_ACTIVE,
