    INIT:
        nSampleIndex := 1;
        bStimulusOutput := FALSE;
        bTestComplete := FALSE;
        eState := IDLE;

    IDLE:
        IF bStartTest THEN
            // Calculate next DC sync time (e.g., 5ms in the future)
            nNextSyncTime := nCurrentDcTime + 5000000;
            eState := WAIT_DC_SYNC;
            bStartTest := FALSE;
        END_IF

    WAIT_DC_SYNC:
        // Use Distributed Clocks to trigger stimulus exactly at nNextSyncTime
        IF nCurrentDcTime >= nNextSyncTime THEN
            bStimulusOutput := TRUE;
            eState := ACQUIRE;
        END_IF

    ACQUIRE:
        // In real DC applications, XFC terminals handle timestamps.
        // Here we simulate synchronized capture following the stimulus.
        aDataBuffer[nSampleIndex] := fFastAnalogIn;
        nSampleIndex := nSampleIndex + 1;

        // Turn off stimulus next cycle
        bStimulusOutput := FALSE;

        IF nSampleIndex > 1000 THEN
            bTestComplete := TRUE;
            eState := STOP;
        END_IF

    STOP:
        eState := INIT;

    FAULT:
        bStimulusOutput := FALSE;
END_CASE
