PROGRAM MAIN
VAR
    eState : (INIT, SELF_TEST, HIL_SYNC, ACQUIRE, DRIFT_ANALYSIS, STOP, FAULT) := INIT;

    // Data & Sync
    aDataBuf : ARRAY[1..1000] OF LREAL;
    nIdx : INT;
    bStart : BOOL;

    // Self-Test & Drift
    fCalibrationRef : LREAL := 5.0; // Known reference voltage
    fSensorVal AT %I* : LREAL;
    fBaselineOffset : LREAL;
    bDriftWarning : BOOL;
    fDriftThreshold : LREAL := 0.05;

    // HIL Digital Twin
    fHilSimulatedVal AT %I* : LREAL; // From EtherCAT simulation node
    fModelDeviation : LREAL;
    bHilMismatch : BOOL;

    // I/O
    bStimulus AT %Q* : BOOL;
    bConnectRefVoltage AT %Q* : BOOL; // Relay to connect known ref
END_VAR

CASE eState OF
    INIT:
        nIdx := 1;
        bStimulus := FALSE;
        bConnectRefVoltage := FALSE;
        IF bStart THEN
            bStart := FALSE;
            eState := SELF_TEST;
        END_IF

    SELF_TEST:
        // Connect reference voltage to validate measurement chain
        bConnectRefVoltage := TRUE;
        // Assume simple wait logic here (e.g. TON)
        fBaselineOffset := fSensorVal - fCalibrationRef;

        IF ABS(fBaselineOffset) > fDriftThreshold THEN
            eState := FAULT; // Self-test failed
        ELSE
            bConnectRefVoltage := FALSE;
            eState := HIL_SYNC;
        END_IF

    HIL_SYNC:
        // Sync real-time hardware state with the digital twin model
        // Compare simulated expected initial value with actual
        fModelDeviation := ABS(fSensorVal - fHilSimulatedVal);
        IF fModelDeviation > 0.1 THEN
            bHilMismatch := TRUE;
            eState := FAULT;
        ELSE
            bStimulus := TRUE;
            eState := ACQUIRE;
        END_IF

    ACQUIRE:
        bStimulus := FALSE;
        aDataBuf[nIdx] := fSensorVal - fBaselineOffset; // Apply offset compensation
        nIdx := nIdx + 1;

        IF nIdx > 1000 THEN
            eState := DRIFT_ANALYSIS;
        END_IF

    DRIFT_ANALYSIS:
        // Post-test drift analysis: compare end state with digital twin expected end state
        fModelDeviation := ABS(aDataBuf[1000] - fHilSimulatedVal);
        IF fModelDeviation > fDriftThreshold THEN
            bDriftWarning := TRUE;
        END_IF
        eState := STOP;

    STOP:
        eState := INIT;

    FAULT:
        bStimulus := FALSE;
        bConnectRefVoltage := FALSE;
END_CASE
