```pascal
FUNCTION_BLOCK "FB_Lyophilizer_Base"
VERSION : 0.1
   VAR_INPUT
      Start_Process : Bool;
      Stop_Process : Bool;
      Target_Temp : Real;
      Target_Vacuum : Real;
      Actual_Temp : Real;
      Actual_Vacuum : Real;
   END_VAR

   VAR_OUTPUT
      Heater_Output : Real;
      Vacuum_Valve_Output : Real;
      Process_Running : Bool;
   END_VAR

   VAR
      State : Int; // 0: Idle, 1: Running
      Kp_Temp : Real := 2.5;
      Kp_Vac : Real := 1.0;
   END_VAR

BEGIN
   IF "Stop_Process" THEN
      "State" := 0;
   ELSIF "Start_Process" AND "State" = 0 THEN
      "State" := 1;
   END_IF;

   IF "State" = 1 THEN
      "Process_Running" := TRUE;
      // Proportional control for Temperature
      IF "Actual_Temp" < "Target_Temp" THEN
         "Heater_Output" := ("Target_Temp" - "Actual_Temp") * "Kp_Temp";
         IF "Heater_Output" > 100.0 THEN "Heater_Output" := 100.0; END_IF;
      ELSE
         "Heater_Output" := 0.0;
      END_IF;

      // Proportional control for Vacuum
      IF "Actual_Vacuum" > "Target_Vacuum" THEN
         "Vacuum_Valve_Output" := ("Actual_Vacuum" - "Target_Vacuum") * "Kp_Vac";
         IF "Vacuum_Valve_Output" > 100.0 THEN "Vacuum_Valve_Output" := 100.0; END_IF;
      ELSE
         "Vacuum_Valve_Output" := 0.0;
      END_IF;
   ELSE
      "Process_Running" := FALSE;
      "Heater_Output" := 0.0;
      "Vacuum_Valve_Output" := 0.0;
   END_IF;
END_FUNCTION_BLOCK
