```scl
FUNCTION_BLOCK "BESS_Manager"
VAR_INPUT
    NumCells : INT; // Number of battery cells
    CellVoltages : ARRAY[1..100] OF REAL; // Cell voltages
    CellSoC : ARRAY[1..100] OF REAL; // State of Charge per cell (0-100%)
    CellTemps : ARRAY[1..100] OF REAL; // Cell temperatures (C)
    AvgSoC : REAL; // Average SoC
    DischargeCmd : BOOL;
    ChargeCmd : BOOL;
END_VAR

VAR_OUTPUT
    BalanceCmds : ARRAY[1..100] OF BOOL; // Commands to balance (bleed) specific cells
    ThermalRunawayAlarm : BOOL;
    SystemFault : BOOL;
    ContactorOpen : BOOL; // Open main contactor if fault
END_VAR

VAR
    i : INT;
    MaxTemp : REAL;
    TempLimit : REAL := 60.0; // Thermal runaway threshold
    SoC_BalanceThreshold : REAL := 5.0; // % diff to trigger balancing
END_VAR

BEGIN
    ThermalRunawayAlarm := FALSE;
    SystemFault := FALSE;
    ContactorOpen := FALSE;
    MaxTemp := 0.0;

    // Check for thermal runaway
    FOR i := 1 TO NumCells DO
        IF CellTemps[i] > MaxTemp THEN
            MaxTemp := CellTemps[i];
        END_IF;

        IF CellTemps[i] >= TempLimit THEN
            ThermalRunawayAlarm := TRUE;
            SystemFault := TRUE;
            ContactorOpen := TRUE; // Immediate shutdown
        END_IF;
    END_FOR;

    // SoC Balancing
    FOR i := 1 TO NumCells DO
        BalanceCmds[i] := FALSE;
        IF NOT SystemFault THEN
            // If charging and cell SoC is higher than average by threshold, bleed energy
            IF ChargeCmd AND (CellSoC[i] - AvgSoC > SoC_BalanceThreshold) THEN
                BalanceCmds[i] := TRUE;
            END_IF;
        END_IF;
    END_FOR;
END_FUNCTION_BLOCK
```

