```scl
FUNCTION_BLOCK "BESS_Profinet_Diagnostics"
VAR_INPUT
    NumCells : INT;
    CellVoltages : ARRAY[1..100] OF REAL;
    CellSoC : ARRAY[1..100] OF REAL;
    CellTemps : ARRAY[1..100] OF REAL;
    AvgSoC : REAL;
    // Profinet Inputs from EMS
    EMS_ControlWord : WORD; 
END_VAR

VAR_OUTPUT
    BalanceCmds : ARRAY[1..100] OF BOOL;
    CoolingPumpCmd : BOOL;
    HeatingHeaterCmd : BOOL;
    ChillerCmd : BOOL;
    ContactorOpen : BOOL;
    // Profinet Outputs to EMS
    BESS_StatusWord : WORD;
    BESS_ErrorCode : INT;
END_VAR

VAR
    i : INT;
    MaxTemp : REAL;
    MinTemp : REAL;
    TempLimitRunaway : REAL := 60.0;
    TempLimitCooling : REAL := 45.0;
    TempLimitHeating : REAL := 15.0;
    SoC_BalanceThreshold : REAL := 5.0;

    ChargeCmd : BOOL;
    ResetFaults : BOOL;
    SystemFault : BOOL;
END_VAR

BEGIN
    // Decode Profinet Control Word
    ChargeCmd := (EMS_ControlWord AND 16#0001) > 0;
    ResetFaults := (EMS_ControlWord AND 16#0002) > 0;

    IF ResetFaults THEN
        SystemFault := FALSE;
        BESS_ErrorCode := 0;
        ContactorOpen := FALSE;
    END_IF;

    MaxTemp := -100.0;
    MinTemp := 1000.0;

    FOR i := 1 TO NumCells DO
        IF CellTemps[i] > MaxTemp THEN MaxTemp := CellTemps[i]; END_IF;
        IF CellTemps[i] < MinTemp THEN MinTemp := CellTemps[i]; END_IF;

        IF CellTemps[i] >= TempLimitRunaway THEN
            SystemFault := TRUE;
            BESS_ErrorCode := 101; // Thermal Runaway Error
            ContactorOpen := TRUE;
        END_IF;

        IF CellVoltages[i] > 4.2 OR CellVoltages[i] < 2.5 THEN
            SystemFault := TRUE;
            BESS_ErrorCode := 102; // Over/Under Voltage Error
            ContactorOpen := TRUE;
        END_IF;
    END_FOR;

    // Thermal Management
    CoolingPumpCmd := FALSE; HeatingHeaterCmd := FALSE; ChillerCmd := FALSE;
    IF MaxTemp > TempLimitCooling THEN CoolingPumpCmd := TRUE; ChillerCmd := TRUE; END_IF;
    IF MinTemp < TempLimitHeating THEN CoolingPumpCmd := TRUE; HeatingHeaterCmd := TRUE; END_IF;

    // Balancing
    FOR i := 1 TO NumCells DO
        BalanceCmds[i] := FALSE;
        IF NOT SystemFault AND ChargeCmd AND (CellSoC[i] - AvgSoC > SoC_BalanceThreshold) THEN
            BalanceCmds[i] := TRUE;
        END_IF;
    END_FOR;

    // Encode Profinet Status Word
    BESS_StatusWord := 0;
    IF SystemFault THEN BESS_StatusWord := BESS_StatusWord OR 16#0001; END_IF;
    IF ContactorOpen THEN BESS_StatusWord := BESS_StatusWord OR 16#0002; END_IF;
    IF CoolingPumpCmd THEN BESS_StatusWord := BESS_StatusWord OR 16#0004; END_IF;
END_FUNCTION_BLOCK
```

