PROGRAM Flywheel_Energy_Storage
VAR
    // Inputs
    Magnetic_Bearing_Pos_X : REAL; // X-axis position
    Magnetic_Bearing_Pos_Y : REAL; // Y-axis position
    Magnetic_Bearing_Pos_Z : REAL; // Z-axis position
    Vacuum_Pressure : REAL; // Current vacuum pressure (mbar)
    Flywheel_Speed : REAL; // RPM
    Start_Cmd : BOOL;
    Stop_Cmd : BOOL;

    // Outputs
    Mag_Bearing_Ctrl_X : REAL;
    Mag_Bearing_Ctrl_Y : REAL;
    Mag_Bearing_Ctrl_Z : REAL;
    Vacuum_Pump_Cmd : BOOL;
    Motor_Drive_Cmd : REAL;

    // Parameters
    Target_Pos_X : REAL := 0.0;
    Target_Pos_Y : REAL := 0.0;
    Target_Pos_Z : REAL := 0.0;
    Kp_Mag : REAL := 50.0; // Proportional gain for magnetic bearing
    Vacuum_Threshold_High : REAL := 1.0e-3; // Max allowable pressure
    Vacuum_Threshold_Low : REAL := 1.0e-4; // Target pressure
    Target_Speed : REAL := 15000.0; // Target RPM
    Kp_Speed : REAL := 0.5;

    // State
    System_Active : BOOL := FALSE;
END_VAR

// Control state
IF Start_Cmd THEN
    System_Active := TRUE;
ELSIF Stop_Cmd THEN
    System_Active := FALSE;
END_IF;

IF System_Active THEN
    // Magnetic Bearing Levitation Control (Proportional only for simplicity)
    Mag_Bearing_Ctrl_X := (Target_Pos_X - Magnetic_Bearing_Pos_X) * Kp_Mag;
    Mag_Bearing_Ctrl_Y := (Target_Pos_Y - Magnetic_Bearing_Pos_Y) * Kp_Mag;
    Mag_Bearing_Ctrl_Z := (Target_Pos_Z - Magnetic_Bearing_Pos_Z) * Kp_Mag;

    // Vacuum Chamber Control
    IF Vacuum_Pressure > Vacuum_Threshold_High THEN
        Vacuum_Pump_Cmd := TRUE;
ELSIF Vacuum_Pressure <= Vacuum_Threshold_Low THEN
        Vacuum_Pump_Cmd := FALSE;
    END_IF;

    // Flywheel Speed Control
    Motor_Drive_Cmd := (Target_Speed - Flywheel_Speed) * Kp_Speed;
    IF Motor_Drive_Cmd > 100.0 THEN Motor_Drive_Cmd := 100.0; END_IF;
    IF Motor_Drive_Cmd < 0.0 THEN Motor_Drive_Cmd := 0.0; END_IF;
ELSE
    Mag_Bearing_Ctrl_X := 0.0;
    Mag_Bearing_Ctrl_Y := 0.0;
    Mag_Bearing_Ctrl_Z := 0.0;
    Vacuum_Pump_Cmd := FALSE;
    Motor_Drive_Cmd := 0.0;
END_IF;
END_PROGRAM

PROGRAM Flywheel_Energy_Storage_Mutation1
VAR
    // Inputs
    Magnetic_Bearing_Pos_X : REAL;
    Magnetic_Bearing_Pos_Y : REAL;
    Magnetic_Bearing_Pos_Z : REAL;
    Vacuum_Pressure : REAL;
    Flywheel_Speed : REAL;
    Bearing_Temp : REAL; // Active cooling addition
    Motor_Temp : REAL;   // Active cooling addition
    Start_Cmd : BOOL;
    Stop_Cmd : BOOL;

    // Outputs
    Mag_Bearing_Ctrl_X : REAL;
    Mag_Bearing_Ctrl_Y : REAL;
    Mag_Bearing_Ctrl_Z : REAL;
    Vacuum_Pump_Cmd : BOOL;
    Motor_Drive_Cmd : REAL;
    Cooling_Pump_Cmd : BOOL; // Cooling output
    Cooling_Fan_Cmd : REAL;  // Cooling output 0-100%
    System_Fault : BOOL;

    // Parameters
    Target_Pos_X : REAL := 0.0;
    Target_Pos_Y : REAL := 0.0;
    Target_Pos_Z : REAL := 0.0;
    Kp_Mag : REAL := 50.0;
    Vacuum_Threshold_High : REAL := 1.0e-3;
    Vacuum_Threshold_Low : REAL := 1.0e-4;
    Target_Speed : REAL := 15000.0;
    Kp_Speed : REAL := 0.5;
    Max_Safe_Temp : REAL := 85.0; // Thermal limit
    Target_Temp : REAL := 45.0;   // Thermal target
    Kp_Temp : REAL := 2.0;

    // State
    System_Active : BOOL := FALSE;
END_VAR

// Thermal Monitoring
IF Bearing_Temp > Max_Safe_Temp OR Motor_Temp > Max_Safe_Temp THEN
    System_Fault := TRUE;
    System_Active := FALSE; // Emergency Stop
END_IF;

IF Start_Cmd AND NOT System_Fault THEN
    System_Active := TRUE;
ELSIF Stop_Cmd THEN
    System_Active := FALSE;
END_IF;

IF System_Active THEN
    // Levitation
    Mag_Bearing_Ctrl_X := (Target_Pos_X - Magnetic_Bearing_Pos_X) * Kp_Mag;
    Mag_Bearing_Ctrl_Y := (Target_Pos_Y - Magnetic_Bearing_Pos_Y) * Kp_Mag;
    Mag_Bearing_Ctrl_Z := (Target_Pos_Z - Magnetic_Bearing_Pos_Z) * Kp_Mag;

    // Vacuum
    IF Vacuum_Pressure > Vacuum_Threshold_High THEN
        Vacuum_Pump_Cmd := TRUE;
    ELSIF Vacuum_Pressure <= Vacuum_Threshold_Low THEN
        Vacuum_Pump_Cmd := FALSE;
    END_IF;

    // Speed
    Motor_Drive_Cmd := (Target_Speed - Flywheel_Speed) * Kp_Speed;
    IF Motor_Drive_Cmd > 100.0 THEN Motor_Drive_Cmd := 100.0; END_IF;
    IF Motor_Drive_Cmd < 0.0 THEN Motor_Drive_Cmd := 0.0; END_IF;

    // Active Cooling
    Cooling_Pump_Cmd := TRUE;
    Cooling_Fan_Cmd := (MAX(Bearing_Temp, Motor_Temp) - Target_Temp) * Kp_Temp;
    IF Cooling_Fan_Cmd > 100.0 THEN Cooling_Fan_Cmd := 100.0; END_IF;
    IF Cooling_Fan_Cmd < 20.0 THEN Cooling_Fan_Cmd := 20.0; END_IF; // Min fan speed
ELSE
    Mag_Bearing_Ctrl_X := 0.0;
    Mag_Bearing_Ctrl_Y := 0.0;
    Mag_Bearing_Ctrl_Z := 0.0;
    Vacuum_Pump_Cmd := FALSE;
    Motor_Drive_Cmd := 0.0;
    Cooling_Pump_Cmd := (Bearing_Temp > Target_Temp); // Keep cooling until safe
    Cooling_Fan_Cmd := 50.0;
END_IF;
END_PROGRAM

PROGRAM Flywheel_Energy_Storage_Mutation2
VAR
    // Inputs (from sensors)
    Magnetic_Bearing_Pos_X : REAL;
    Magnetic_Bearing_Pos_Y : REAL;
    Magnetic_Bearing_Pos_Z : REAL;
    Vacuum_Pressure : REAL;
    Flywheel_Speed : REAL;
    Bearing_Temp : REAL;
    Motor_Temp : REAL;
    Vibration_Level : REAL;

    // Ethernet/IP Inputs (from SCADA/HMI)
    EIP_Start_Cmd : BOOL;
    EIP_Stop_Cmd : BOOL;
    EIP_Reset_Fault : BOOL;
    EIP_Target_Speed : REAL;

    // Outputs
    Mag_Bearing_Ctrl_X : REAL;
    Mag_Bearing_Ctrl_Y : REAL;
    Mag_Bearing_Ctrl_Z : REAL;
    Vacuum_Pump_Cmd : BOOL;
    Motor_Drive_Cmd : REAL;
    Cooling_Pump_Cmd : BOOL;
    Cooling_Fan_Cmd : REAL;

    // Ethernet/IP Outputs (to SCADA/HMI)
    EIP_System_Status : DINT; // 0=Off, 1=Running, 2=Fault
    EIP_Fault_Code : DINT;    // Bitmap of faults

    // Internal State & Params
    System_Active : BOOL := FALSE;
    Target_Pos : REAL := 0.0;
    Kp_Mag : REAL := 50.0;
    Vacuum_Max : REAL := 1.0e-3;
    Vacuum_Min : REAL := 1.0e-4;
    Safe_Temp : REAL := 85.0;
    Max_Vib : REAL := 5.0; // mm/s

    // Fault Diagnostics Bits
    Flt_Overtemp : BOOL;
    Flt_VacuumLoss : BOOL;
    Flt_HighVibration : BOOL;
    Flt_BearingDrift : BOOL;
END_VAR

// Ethernet/IP Parameter Handling
IF EIP_Target_Speed <= 0.0 THEN EIP_Target_Speed := 15000.0; END_IF;

// Fault Diagnostics
Flt_Overtemp := (Bearing_Temp > Safe_Temp) OR (Motor_Temp > Safe_Temp);
Flt_VacuumLoss := (Vacuum_Pressure > 5.0e-3); // Critical loss
Flt_HighVibration := (Vibration_Level > Max_Vib);
Flt_BearingDrift := (ABS(Magnetic_Bearing_Pos_X) > 0.5) OR (ABS(Magnetic_Bearing_Pos_Y) > 0.5);

// Pack Fault Code for Ethernet/IP
EIP_Fault_Code := 0;
IF Flt_Overtemp THEN EIP_Fault_Code := EIP_Fault_Code OR 1; END_IF;
IF Flt_VacuumLoss THEN EIP_Fault_Code := EIP_Fault_Code OR 2; END_IF;
IF Flt_HighVibration THEN EIP_Fault_Code := EIP_Fault_Code OR 4; END_IF;
IF Flt_BearingDrift THEN EIP_Fault_Code := EIP_Fault_Code OR 8; END_IF;

// Reset Faults
IF EIP_Reset_Fault THEN
    EIP_Fault_Code := 0;
END_IF;

// State Machine
IF EIP_Fault_Code <> 0 THEN
    System_Active := FALSE;
    EIP_System_Status := 2; // Fault
ELSIF EIP_Start_Cmd THEN
    System_Active := TRUE;
    EIP_System_Status := 1; // Running
ELSIF EIP_Stop_Cmd THEN
    System_Active := FALSE;
    EIP_System_Status := 0; // Off
END_IF;

// Control Logic
IF System_Active THEN
    Mag_Bearing_Ctrl_X := (Target_Pos - Magnetic_Bearing_Pos_X) * Kp_Mag;
    Mag_Bearing_Ctrl_Y := (Target_Pos - Magnetic_Bearing_Pos_Y) * Kp_Mag;
    Mag_Bearing_Ctrl_Z := (Target_Pos - Magnetic_Bearing_Pos_Z) * Kp_Mag;

    IF Vacuum_Pressure > Vacuum_Max THEN Vacuum_Pump_Cmd := TRUE;
    ELSIF Vacuum_Pressure <= Vacuum_Min THEN Vacuum_Pump_Cmd := FALSE; END_IF;

    Motor_Drive_Cmd := (EIP_Target_Speed - Flywheel_Speed) * 0.5;
    IF Motor_Drive_Cmd > 100.0 THEN Motor_Drive_Cmd := 100.0; END_IF;
    IF Motor_Drive_Cmd < 0.0 THEN Motor_Drive_Cmd := 0.0; END_IF;

    Cooling_Pump_Cmd := TRUE;
    Cooling_Fan_Cmd := 80.0;
ELSE
    Mag_Bearing_Ctrl_X := 0.0;
    Mag_Bearing_Ctrl_Y := 0.0;
    Mag_Bearing_Ctrl_Z := 0.0;
    Vacuum_Pump_Cmd := FALSE;
    Motor_Drive_Cmd := 0.0;
    Cooling_Pump_Cmd := (Bearing_Temp > 40.0);
    Cooling_Fan_Cmd := 0.0;
END_IF;
END_PROGRAM

PROGRAM Flywheel_Energy_Storage_Mutation3
VAR
    // Field Inputs
    Mag_Pos_X : REAL; Mag_Pos_Y : REAL; Mag_Pos_Z : REAL;
    Vac_Pressure : REAL; Flywheel_RPM : REAL;
    Temp_Sensors : ARRAY[0..1] OF REAL; // 0: Bearing, 1: Motor

    // SCADA & Security (IEC 62443)
    SCADA_Heartbeat : DINT;
    Last_SCADA_Heartbeat : DINT;
    Comm_Timeout_Timer : TON;
    Auth_Token : DINT;
    Expected_Token : DINT := 16#A5A5_5A5A;
    Security_Lockout : BOOL;

    // Failover
    PLC_Is_Primary : BOOL;
    Partner_PLC_Alive : BOOL;
    Takeover_Cmd : BOOL;

    // Outputs
    Mag_Ctrl : ARRAY[0..2] OF REAL;
    Vac_Pump : BOOL; Drive_Cmd : REAL; Cool_Pump : BOOL;

    // State & Timers
    State : DINT := 0; // 0=Init, 1=Standby, 2=Run, 3=Failover, 4=SecureLock
    Sys_Faults : DINT;
END_VAR

// IEC 62443 Security: SCADA Authentication & Heartbeat
Comm_Timeout_Timer(IN:= (SCADA_Heartbeat = Last_SCADA_Heartbeat), PT:= T#2s);
IF Comm_Timeout_Timer.Q THEN
    Sys_Faults := Sys_Faults OR 16#0001; // Comm Loss
END_IF;
Last_SCADA_Heartbeat := SCADA_Heartbeat;

IF Auth_Token <> Expected_Token THEN
    Security_Lockout := TRUE;
    State := 4; // Secure Lockout Mode
    Drive_Cmd := 0.0; // Immediate safe stop
END_IF;

// Redundancy Failover Logic
IF NOT PLC_Is_Primary THEN
    IF NOT Partner_PLC_Alive THEN
        Takeover_Cmd := TRUE;
        PLC_Is_Primary := TRUE;
        State := 1; // Enter standby to resume operations safely
    ELSE
        RETURN; // Execute nothing else if secondary
    END_IF;
END_IF;

// Main State Machine
CASE State OF
    0: // Init
        IF NOT Security_Lockout THEN State := 1; END_IF;

    1: // Standby
        Mag_Ctrl[0]:=0.0; Mag_Ctrl[1]:=0.0; Mag_Ctrl[2]:=0.0;
        Vac_Pump := FALSE; Drive_Cmd := 0.0; Cool_Pump := FALSE;
        IF (Sys_Faults = 0) AND (SCADA_Heartbeat > 0) THEN State := 2; END_IF;

    2: // Run
        // Levitation PI
        Mag_Ctrl[0] := (0.0 - Mag_Pos_X) * 50.0;
        Mag_Ctrl[1] := (0.0 - Mag_Pos_Y) * 50.0;
        Mag_Ctrl[2] := (0.0 - Mag_Pos_Z) * 50.0;

        // Vacuum Management
        IF Vac_Pressure > 1.0e-3 THEN Vac_Pump := TRUE;
        ELSIF Vac_Pressure < 1.0e-4 THEN Vac_Pump := FALSE; END_IF;

        // Drive Control
        Drive_Cmd := (15000.0 - Flywheel_RPM) * 0.5;

        // Cooling
        Cool_Pump := (Temp_Sensors[0] > 45.0) OR (Temp_Sensors[1] > 45.0);

        // Fault Check
        IF Temp_Sensors[0] > 85.0 THEN Sys_Faults := Sys_Faults OR 16#0002; State := 3; END_IF;

    3: // Failover/Fault
        Drive_Cmd := 0.0;
        // Keep levitation active during spin-down
        Mag_Ctrl[0] := (0.0 - Mag_Pos_X) * 50.0;
        Mag_Ctrl[1] := (0.0 - Mag_Pos_Y) * 50.0;
        Mag_Ctrl[2] := (0.0 - Mag_Pos_Z) * 50.0;
        IF Flywheel_RPM < 10.0 THEN State := 1; END_IF; // Wait till stopped

    4: // Secure Lockout
        Drive_Cmd := 0.0; Vac_Pump := FALSE; Cool_Pump := FALSE;
END_CASE;
END_PROGRAM

PROGRAM Flywheel_Energy_Storage_Mutation4
VAR
    // Physical Sensors
    Mag_Pos_Real : ARRAY[0..2] OF REAL;
    Vac_Pressure : REAL;
    Flywheel_RPM : REAL;

    // HIL Digital Twin Inputs
    HIL_Mag_Pos_Expected : ARRAY[0..2] OF REAL;
    HIL_Sync_Token : DINT;
    HIL_Drift_Tolerance : REAL := 0.05;

    // Security & Comm
    Auth_Token : DINT;
    Expected_Token : DINT := 16#A5A5_5A5A;
    Partner_Alive : BOOL;
    Is_Primary : BOOL;

    // Outputs
    Mag_Ctrl : ARRAY[0..2] OF REAL;
    Vac_Pump : BOOL;
    Drive_Cmd : REAL;

    // Internal States
    State : DINT := 0; // 0=Init, 1=Self-Test, 2=Run, 3=SafeStop
    Self_Test_Step : DINT := 0;
    Test_Timer : TON;
    Sensor_Drift_Fault : BOOL;
    Cyber_Fault : BOOL;
END_VAR

// 1. Cybersecurity & Redundancy
IF Auth_Token <> Expected_Token THEN Cyber_Fault := TRUE; State := 3; END_IF;
IF NOT Is_Primary AND NOT Partner_Alive THEN Is_Primary := TRUE; END_IF;
IF NOT Is_Primary THEN RETURN; END_IF; // Yield to primary

// 2. Adversarial Sensor Drift Detection (Comparison with Digital Twin)
Sensor_Drift_Fault := FALSE;
IF ABS(Mag_Pos_Real[0] - HIL_Mag_Pos_Expected[0]) > HIL_Drift_Tolerance THEN Sensor_Drift_Fault := TRUE; END_IF;
IF ABS(Mag_Pos_Real[1] - HIL_Mag_Pos_Expected[1]) > HIL_Drift_Tolerance THEN Sensor_Drift_Fault := TRUE; END_IF;
IF ABS(Mag_Pos_Real[2] - HIL_Mag_Pos_Expected[2]) > HIL_Drift_Tolerance THEN Sensor_Drift_Fault := TRUE; END_IF;

IF Sensor_Drift_Fault THEN State := 3; END_IF; // Enter SafeStop on adversarial manipulation

// 3. Main State Machine
CASE State OF
    0: // Init
        IF NOT Cyber_Fault THEN State := 1; Self_Test_Step := 0; END_IF;

    1: // Automated Self-Test Routine
        Test_Timer(IN:=TRUE, PT:=T#1s);
        CASE Self_Test_Step OF
            0: // Test Vacuum
                Vac_Pump := TRUE;
                IF Test_Timer.Q THEN
                    IF Vac_Pressure < 0.9 THEN // Simple drop check
                        Self_Test_Step := 1; Test_Timer(IN:=FALSE);
                    ELSE State := 3; END_IF; // Fail test
                END_IF;
            1: // Test Levitation Ping
                Mag_Ctrl[0] := 0.1; // Small excitation
                IF Test_Timer.Q THEN
                    IF Mag_Pos_Real[0] > 0.01 THEN // Confirm movement
                        Self_Test_Step := 2; Test_Timer(IN:=FALSE);
                    ELSE State := 3; END_IF;
                END_IF;
            2: // Finish
                Vac_Pump := FALSE; Mag_Ctrl[0] := 0.0;
                State := 2; // Move to Run
        END_CASE;

    2: // Run Mode
        // Standard Levitation PI
        Mag_Ctrl[0] := (0.0 - Mag_Pos_Real[0]) * 50.0;
        Mag_Ctrl[1] := (0.0 - Mag_Pos_Real[1]) * 50.0;
        Mag_Ctrl[2] := (0.0 - Mag_Pos_Real[2]) * 50.0;

        // Standard Vacuum
        IF Vac_Pressure > 1.0e-3 THEN Vac_Pump := TRUE;
        ELSIF Vac_Pressure < 1.0e-4 THEN Vac_Pump := FALSE; END_IF;

        // Standard Spin
        Drive_Cmd := (15000.0 - Flywheel_RPM) * 0.5;

    3: // Safe Stop / Fault
        Drive_Cmd := 0.0;
        // Maintain levitation while slowing down to prevent catastrophic physical crash
        Mag_Ctrl[0] := (0.0 - Mag_Pos_Real[0]) * 50.0;
        Mag_Ctrl[1] := (0.0 - Mag_Pos_Real[1]) * 50.0;
        Mag_Ctrl[2] := (0.0 - Mag_Pos_Real[2]) * 50.0;
        Vac_Pump := TRUE; // Max vacuum during fault to reduce friction
END_CASE;
END_PROGRAM

Here is a Base Siemens SCL program implementing Maximum Power Point Tracking (MPPT) using the Perturb and Observe algorithm, along with basic Grid Synchronization checks.

```scl
FUNCTION_BLOCK "Solar_Inverter_Base"
VAR_INPUT
    PV_Voltage : REAL;
    PV_Current : REAL;
    Grid_Voltage : REAL;
    Grid_Freq : REAL;
END_VAR
VAR_OUTPUT
    PWM_Duty_Cycle : REAL;
    Sync_OK : BOOL;
END_VAR
VAR
    Prev_Power : REAL;
    Prev_Voltage : REAL;
    Step_Size : REAL := 0.01;
END_VAR
BEGIN
    // MPPT (Perturb and Observe)
    VAR Current_Power : REAL := PV_Voltage * PV_Current;
    VAR deltaP : REAL := Current_Power - Prev_Power;
    VAR deltaV : REAL := PV_Voltage - Prev_Voltage;

    IF deltaP > 0.0 THEN
        IF deltaV > 0.0 THEN
            PWM_Duty_Cycle := PWM_Duty_Cycle - Step_Size;
        ELSE
            PWM_Duty_Cycle := PWM_Duty_Cycle + Step_Size;
        END_IF;
    ELSIF deltaP < 0.0 THEN
        IF deltaV > 0.0 THEN
            PWM_Duty_Cycle := PWM_Duty_Cycle + Step_Size;
        ELSE
            PWM_Duty_Cycle := PWM_Duty_Cycle - Step_Size;
        END_IF;
    END_IF;

    Prev_Power := Current_Power;
    Prev_Voltage := PV_Voltage;

    // Grid Sync
    IF (Grid_Voltage > 210.0 AND Grid_Voltage < 250.0) AND (Grid_Freq > 49.5 AND Grid_Freq < 50.5) THEN
        Sync_OK := TRUE;
    ELSE
        Sync_OK := FALSE;
    END_IF;
END_FUNCTION_BLOCK
```

