bDriftAlarm[1] := ABS(fPressureSensors[1] - fVotedPressure) > fMaxDeviation;
bDriftAlarm[2] := ABS(fPressureSensors[2] - fVotedPressure) > fMaxDeviation;
bDriftAlarm[3] := ABS(fPressureSensors[3] - fVotedPressure) > fMaxDeviation;

IF bDriftAlarm[1] AND bDriftAlarm[2] AND bDriftAlarm[3] THEN
