    Local_Grate_SP : REAL := 950.0;
END_VAR

// Redundancy Failover Logic (High Availability)
Heartbeat_Timer(IN := NOT Heartbeat_Partner, PT := T#2S);
IF Primary_PLC_Active OR Heartbeat_Timer.Q THEN
    Is_Active_PLC := TRUE;
ELSE
    Is_Active_PLC := FALSE;
END_IF;

// IEC 62443 Role-based Access for SCADA writes
IF SCADA_Write_Req THEN
    IF SCADA_Role_ID = 5 THEN // Role 5 = Authorized Operator
        Local_Grate_SP := 980.0; // SCADA override accepted
        Security_Alarm := FALSE;
    ELSE
        Security_Alarm := TRUE; // Unauthorized access attempt
    END_IF;
END_IF;

// Control execution only if this PLC is active
IF Is_Active_PLC THEN
    Grate_Speed := Local_Grate_SP / 10.0;
    Scrubber_Lime_Dosing := SO2_Emissions * 2.0;
ELSE
    Grate_Speed := 0.0;
    Scrubber_Lime_Dosing := 0.0;
END_IF;

END_FUNCTION_BLOCK
