Here is the Base Siemens SCL program for Railway Tunnel Ventilation. It handles jet fan thrust reversal based on smoke detection and airflow direction, incorporating a coast-down timer to protect the fan motors during reversal.

```pascal
FUNCTION_BLOCK "Tunnel_Vent_Base"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.0
   VAR_INPUT
      xAutoMode : Bool;
      xSmokeDetected : Bool;
      xFireLocationFwd : Bool; // True if fire is towards forward portal
      xFireLocationRev : Bool; // True if fire is towards reverse portal
   END_VAR

   VAR_OUTPUT
      xCmdStartFwd : Bool;
      xCmdStartRev : Bool;
      xCmdStop : Bool;
   END_VAR

   VAR
      tonCoastDown : TON_TIME;
      statState : Int; // 0=Stop, 1=Fwd, 2=Rev, 3=Coasting
      statCoastActive : Bool;
   END_VAR

   VAR_CONSTANT
      COAST_TIME : Time := T#30s;
   END_VAR

BEGIN
    // Coast Down Timer for Thrust Reversal
    tonCoastDown(IN := statCoastActive, PT := COAST_TIME);

    IF xAutoMode THEN
        IF xSmokeDetected THEN
            IF xFireLocationFwd AND NOT xFireLocationRev THEN
                // Blow smoke towards forward portal
                IF statState = 2 THEN
                    // Currently Reverse, need to coast down
                    xCmdStop := TRUE;
                    xCmdStartRev := FALSE;
                    statCoastActive := TRUE;
                    statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartFwd := TRUE;
                    xCmdStop := FALSE;
                    statCoastActive := FALSE;
                    statState := 1;
                END_IF;
            ELSIF xFireLocationRev AND NOT xFireLocationFwd THEN
                // Blow smoke towards reverse portal
                IF statState = 1 THEN
                    // Currently Forward, need to coast down
                    xCmdStop := TRUE;
                    xCmdStartFwd := FALSE;
                    statCoastActive := TRUE;
                    statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartRev := TRUE;
                    xCmdStop := FALSE;
                    statCoastActive := FALSE;
                    statState := 2;
                END_IF;
            END_IF;
        ELSE
            // Normal operation - stop fans
            xCmdStop := TRUE;
            xCmdStartFwd := FALSE;
            xCmdStartRev := FALSE;
            statState := 0;
            statCoastActive := FALSE;
        END_IF;
    ELSE
        // Manual or off mode - logic handled elsewhere
        statCoastActive := FALSE;
    END_IF;
END_FUNCTION_BLOCK
```

Here is the code with added depth. It integrates a zoned fire deluge system and damper control, ensuring the fire zone is isolated before the fans are engaged or reversed.

```pascal
FUNCTION_BLOCK "Tunnel_Vent_Depth"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.1
   VAR_INPUT
      xAutoMode : Bool;
      xSmokeDetected : Bool;
      iFireZone : Int; // 1=Fwd, 2=Mid, 3=Rev
      xDamperOpened : Bool;
      xDamperClosed : Bool;
   END_VAR

   VAR_OUTPUT
      xCmdStartFwd : Bool;
      xCmdStartRev : Bool;
      xCmdStop : Bool;
      xCmdOpenDamper : Bool;
      xCmdCloseDamper : Bool;
      xCmdDelugeActive : Bool;
   END_VAR

   VAR
      tonCoastDown : TON_TIME;
      tonDelugeDelay : TON_TIME;
      statState : Int; 
      statCoastActive : Bool;
      statIsolating : Bool;
   END_VAR

   VAR_CONSTANT
      COAST_TIME : Time := T#30s;
      DELUGE_DELAY : Time := T#10s;
   END_VAR

BEGIN
    tonCoastDown(IN := statCoastActive, PT := COAST_TIME);
    tonDelugeDelay(IN := xSmokeDetected AND statIsolating, PT := DELUGE_DELAY);

    IF xAutoMode THEN
        IF xSmokeDetected THEN
            // 1. Isolate Zone and Activate Deluge
            xCmdOpenDamper := TRUE;
            xCmdCloseDamper := FALSE;
            statIsolating := TRUE;

            IF tonDelugeDelay.Q AND xDamperOpened THEN
                xCmdDelugeActive := TRUE;

                // 2. Control Fans Based on Zone
                IF iFireZone = 1 THEN // Fire Fwd, blow Fwd
                    IF statState = 2 THEN
                        xCmdStop := TRUE; xCmdStartRev := FALSE; statCoastActive := TRUE; statState := 3;
                    ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                        xCmdStartFwd := TRUE; xCmdStop := FALSE; statCoastActive := FALSE; statState := 1;
                    END_IF;
                ELSIF iFireZone = 3 THEN // Fire Rev, blow Rev
                    IF statState = 1 THEN
                        xCmdStop := TRUE; xCmdStartFwd := FALSE; statCoastActive := TRUE; statState := 3;
                    ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                        xCmdStartRev := TRUE; xCmdStop := FALSE; statCoastActive := FALSE; statState := 2;
                    END_IF;
                END_IF;
            END_IF;
        ELSE
            xCmdStop := TRUE; xCmdStartFwd := FALSE; xCmdStartRev := FALSE; xCmdDelugeActive := FALSE;
            xCmdOpenDamper := FALSE; xCmdCloseDamper := TRUE;
            statState := 0; statCoastActive := FALSE; statIsolating := FALSE;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
```

Here is the code with added breadth. It introduces Profinet status monitoring, extracting specific VFD fault codes, and diagnostic flags to ensure safe operation during communication failures.

```pascal
FUNCTION_BLOCK "Tunnel_Vent_Breadth"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.2
   VAR_INPUT
      xAutoMode : Bool;
      xSmokeDetected : Bool;
      iFireZone : Int;
      xDamperOpened : Bool;
      wProfinetStatusVFD : Word; // Status word from VFD
      wVFDFaultCode : Word;      // Fault code from VFD
   END_VAR

   VAR_OUTPUT
      xCmdStartFwd : Bool;
      xCmdStartRev : Bool;
      xCmdDelugeActive : Bool;
      xCommError : Bool;
      xVFDError : Bool;
      iAlarmCode : Int;
   END_VAR

   VAR
      tonCoastDown : TON_TIME;
      statState : Int; 
      statCoastActive : Bool;
   END_VAR

BEGIN
    // Diagnostics & Profinet Monitoring
    xCommError := (wProfinetStatusVFD AND 16#8000) = 0; // Bit 15: Comm OK
    xVFDError := (wProfinetStatusVFD AND 16#0008) <> 0; // Bit 3: Fault Active

    IF xCommError THEN
        iAlarmCode := 101; // Comm failure
    ELSIF xVFDError THEN
        iAlarmCode := WORD_TO_INT(wVFDFaultCode);
    ELSE
        iAlarmCode := 0;
    END_IF;

    tonCoastDown(IN := statCoastActive, PT := T#30s);

    IF xAutoMode AND NOT xCommError AND NOT xVFDError THEN
        IF xSmokeDetected AND xDamperOpened THEN
            xCmdDelugeActive := TRUE;
            IF iFireZone = 1 THEN 
                IF statState = 2 THEN
                    xCmdStartRev := FALSE; statCoastActive := TRUE; statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartFwd := TRUE; statCoastActive := FALSE; statState := 1;
                END_IF;
            ELSIF iFireZone = 3 THEN 
                IF statState = 1 THEN
                    xCmdStartFwd := FALSE; statCoastActive := TRUE; statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartRev := TRUE; statCoastActive := FALSE; statState := 2;
                END_IF;
            END_IF;
        ELSE
            xCmdStartFwd := FALSE; xCmdStartRev := FALSE; xCmdDelugeActive := FALSE;
            statState := 0; statCoastActive := FALSE;
        END_IF;
    ELSE
        // Safe state on error or manual mode
        xCmdStartFwd := FALSE; xCmdStartRev := FALSE;
    END_IF;
END_FUNCTION_BLOCK
