        System_Ready := FALSE;
        Anti_Surge_Valve := 100.0; // Fail-safe open
    ELSIF Sensor_Error THEN
        Fault_Code := 201; // Instrument out of range
        System_Ready := FALSE;
        Anti_Surge_Valve := 100.0;
    ELSE
        Fault_Code := 0;
        System_Ready := TRUE;

        // Normal Control Logic
        Anti_Surge_Valve := 50.0; // Placeholder for PID
        Seal_Gas_Valve := 50.0; // Placeholder for PID
        Drain_Valve_Cmd := Knockout_Drum_Level > 80.0;
