PROGRAM CustodyTransfer
VAR
    Coriolis_Flow_Rate : REAL;
    Coriolis_Totalizer : LREAL;
    Prover_Loop_Active : BOOL;
    Prover_Volume : REAL;
    Sync_Status : BOOL;
    Meter_Factor : REAL;
    Flow_Mismatch : BOOL;
END_VAR

// Monitor Flow Rate and Totalizer
IF Prover_Loop_Active THEN
    IF ABS(Coriolis_Flow_Rate - Prover_Volume) > 1.5 THEN
        Sync_Status := FALSE;
        Flow_Mismatch := TRUE;
    ELSE
        Sync_Status := TRUE;
        Flow_Mismatch := FALSE;
        Meter_Factor := Prover_Volume / Coriolis_Flow_Rate;
    END_IF;
ELSE
    Sync_Status := TRUE; // Assume sync when not proving
END_IF;

// Update Totalizer based on flow and meter factor
Coriolis_Totalizer := Coriolis_Totalizer + (Coriolis_Flow_Rate * Meter_Factor);

END_PROGRAM

PROGRAM CustodyTransfer_Depth
VAR
    Coriolis_Flow_Rate : REAL;
    Coriolis_Totalizer : LREAL;
    Prover_Loop_Active : BOOL;
    Prover_Volume : REAL;
    Sync_Status : BOOL;
    Meter_Factor : REAL := 1.0;
    Flow_Mismatch : BOOL;
    Process_Temperature : REAL;
    Process_Pressure : REAL;
    Base_Temperature : REAL := 15.0;
    Base_Pressure : REAL := 101.325;
    CTL : REAL;
    CPL : REAL;
    API_Gravity : REAL := 35.0;
    Alpha_T : REAL;
    Compressibility_Factor : REAL;
    Net_Standard_Volume : LREAL;
END_VAR

Alpha_T := 341.0 / (API_Gravity + 131.5) * 0.001;
CTL := EXP(-Alpha_T * (Process_Temperature - Base_Temperature) * (1.0 + 0.8 * Alpha_T * (Process_Temperature - Base_Temperature)));
Compressibility_Factor := EXP(1.38315 + 0.00343204 * Process_Temperature - 5.62688 / (API_Gravity + 131.5)) * 0.00001;
CPL := 1.0 / (1.0 - (Process_Pressure - Base_Pressure) * Compressibility_Factor);

IF Prover_Loop_Active THEN
    IF ABS(Coriolis_Flow_Rate - Prover_Volume) > 1.5 THEN
        Sync_Status := FALSE;
        Flow_Mismatch := TRUE;
    ELSE
        Sync_Status := TRUE;
        Flow_Mismatch := FALSE;
        Meter_Factor := Prover_Volume / Coriolis_Flow_Rate;
    END_IF;
END_IF;

Coriolis_Totalizer := Coriolis_Totalizer + (Coriolis_Flow_Rate * Meter_Factor);
Net_Standard_Volume := Net_Standard_Volume + (Coriolis_Flow_Rate * Meter_Factor * CTL * CPL);
END_PROGRAM

PROGRAM CustodyTransfer_Breadth
VAR
    Coriolis_Flow_Rate : REAL;
    Coriolis_Totalizer : LREAL;
    Prover_Loop_Active : BOOL;
    Prover_Volume : REAL;
    Sync_Status : BOOL;
    Meter_Factor : REAL := 1.0;
    Flow_Mismatch : BOOL;
    Process_Temperature : REAL;
    Process_Pressure : REAL;
    CTL : REAL;
    CPL : REAL;
    Net_Standard_Volume : LREAL;
    EIP_Input_Data : ARRAY[0..31] OF SINT;
    EIP_Output_Data : ARRAY[0..31] OF SINT;
    EIP_Comm_Fault : BOOL;
    Temp_Sensor_Fault : BOOL;
    Press_Sensor_Fault : BOOL;
    Coriolis_Fault : BOOL;
    System_Healthy : BOOL;
    Alarm_Code : INT;
END_VAR

EIP_Comm_Fault := (EIP_Input_Data[0] = 16#FF);
Temp_Sensor_Fault := (Process_Temperature < -50.0) OR (Process_Temperature > 150.0);
Press_Sensor_Fault := (Process_Pressure < 0.0) OR (Process_Pressure > 10000.0);
Coriolis_Fault := (Coriolis_Flow_Rate < 0.0);

System_Healthy := NOT(EIP_Comm_Fault OR Temp_Sensor_Fault OR Press_Sensor_Fault OR Coriolis_Fault);

IF NOT System_Healthy THEN
    Alarm_Code := 1001;
    Coriolis_Flow_Rate := 0.0;
ELSE
    Alarm_Code := 0;
END_IF;

IF System_Healthy THEN
    CTL := 1.0 - 0.001 * (Process_Temperature - 15.0);
    CPL := 1.0 + 0.00005 * (Process_Pressure - 101.325);
    IF Prover_Loop_Active THEN
        IF ABS(Coriolis_Flow_Rate - Prover_Volume) > 1.5 THEN
            Sync_Status := FALSE;
            Flow_Mismatch := TRUE;
            Alarm_Code := 2001;
        ELSE
            Sync_Status := TRUE;
            Flow_Mismatch := FALSE;
            Meter_Factor := Prover_Volume / Coriolis_Flow_Rate;
        END_IF;
    END_IF;
    Coriolis_Totalizer := Coriolis_Totalizer + (Coriolis_Flow_Rate * Meter_Factor);
    Net_Standard_Volume := Net_Standard_Volume + (Coriolis_Flow_Rate * Meter_Factor * CTL * CPL);
END_IF;

EIP_Output_Data[0] := SINT_TO_B(Alarm_Code AND 16#FF);
END_PROGRAM

PROGRAM CustodyTransfer_Reasoning
VAR
    Coriolis_Flow_Rate : REAL;
