FUNCTION_BLOCK "AmineSweetening_Breadth"
VAR_INPUT
    Profinet_In AT %I0.0 : ARRAY[0..15] OF BYTE;
    CycleTime : REAL := 0.1;
END_VAR
VAR_OUTPUT
    Profinet_Out AT %Q0.0 : ARRAY[0..15] OF BYTE;
    RichAmineValve : REAL;
    LeanAmineValve : REAL;
    ReboilerSteamValve : REAL;
    SystemFault : BOOL;
    FaultCode : INT;
