    RichAmineFlow_PV := BYTE_TO_REAL(Profinet_In[0]) * 10.0;
    ReboilerTemp_PV := BYTE_TO_REAL(Profinet_In[4]) * 5.0;

    SystemFault := FALSE;
    FaultCode := 0;

    IF RichAmineFlow_PV < 0.0 THEN SystemFault := TRUE; FaultCode := 101; END_IF;
    IF ReboilerTemp_PV > 150.0 THEN SystemFault := TRUE; FaultCode := 102; END_IF;

    IF NOT SystemFault THEN
        VAR TempErr := 120.0 - ReboilerTemp_PV;
        TempErrSum := TempErrSum + (TempErr * CycleTime);
        ReboilerSteamValve := (2.0 * TempErr) + (0.1 * TempErrSum);
        IF ReboilerSteamValve > 100.0 THEN ReboilerSteamValve := 100.0; ELSIF ReboilerSteamValve < 0.0 THEN ReboilerSteamValve := 0.0; END_IF;
    ELSE
        ReboilerSteamValve := 0.0;
    END_IF;

    Profinet_Out[0] := REAL_TO_BYTE(ReboilerSteamValve);
    Profinet_Out[1] := BOOL_TO_BYTE(SystemFault);
    Profinet_Out[2] := INT_TO_BYTE(FaultCode);
