VAR_OUTPUT
    Cmd_Pitch : REAL;
    Cmd_Azimuth : REAL;
END_VAR
VAR
    Err_X : REAL;
    Err_Y : REAL;
    Err_H : REAL;
    Kp_Pos : REAL := 1.5;
    Kp_Head : REAL := 2.5;
END_VAR
BEGIN
    IF Enable THEN
        Err_X := Setpoint_X - Actual_X;
        Err_Y := Setpoint_Y - Actual_Y;
        Err_H := Setpoint_Heading - Actual_Heading;

        Cmd_Pitch := SQRT(Err_X**2 + Err_Y**2) * Kp_Pos;
        Cmd_Azimuth := Actual_Heading + Err_H * Kp_Head;
    ELSE
        Cmd_Pitch := 0.0;
        Cmd_Azimuth := Actual_Heading;
    END_IF;
END_FUNCTION_BLOCK
