```pascal
// Base Code
PROGRAM MooringWinch_Base
VAR
    AutoMode : BOOL;
    TensionSetpoint : REAL;
    TensionFeedback : REAL;
    WinchSpeedCMD : REAL;
    EmergencyQuickRelease : BOOL;
    BrakeReleaseCMD : BOOL;
    ClutchEngaged : BOOL;

    // PI Controller Variables
    Kp : REAL := 1.5;
    Ki : REAL := 0.5;
    Error : REAL;
    Integral : REAL;
    MaxSpeed : REAL := 100.0;
END_VAR

// Emergency Quick Release Logic
IF EmergencyQuickRelease THEN
    BrakeReleaseCMD := TRUE;
    ClutchEngaged := FALSE;
    WinchSpeedCMD := 0.0;
    Integral := 0.0; // Reset integrator
ELSIF AutoMode AND ClutchEngaged THEN
    // Tension Spooling PI Control
    Error := TensionSetpoint - TensionFeedback;
    Integral := Integral + (Error * Ki);

    // Anti-windup
    IF Integral > MaxSpeed THEN
        Integral := MaxSpeed;
    ELSIF Integral < -MaxSpeed THEN
        Integral := -MaxSpeed;
    END_IF;

    WinchSpeedCMD := (Error * Kp) + Integral;

    // Speed limit
    IF WinchSpeedCMD > MaxSpeed THEN
        WinchSpeedCMD := MaxSpeed;
    ELSIF WinchSpeedCMD < -MaxSpeed THEN
        WinchSpeedCMD := -MaxSpeed;
    END_IF;

    BrakeReleaseCMD := TRUE;
ELSE
    WinchSpeedCMD := 0.0;
    BrakeReleaseCMD := FALSE;
END_IF;
END_PROGRAM
```

