FUNCTION_BLOCK "RO_Desalination"
VERSION : 0.1
   VAR_INPUT
      Feed_Pressure : Real;
      Permeate_Salinity : Real;
      Start_Cmd : Bool;
      Stop_Cmd : Bool;
   END_VAR
   VAR_OUTPUT
      HP_Pump_Run : Bool;
      ERV_Position : Real;
      High_Salinity_Alarm : Bool;
   END_VAR
   VAR
      State : Int := 0;
   END_VAR
   VAR_CONSTANT
      MAX_SALINITY : Real := 500.0;
      SETPOINT_PRESSURE : Real := 60.0;
   END_VAR
BEGIN
    IF #Stop_Cmd THEN
        #State := 0;
    ELSIF #Start_Cmd AND #State = 0 THEN
        #State := 1;
    END_IF;

    CASE #State OF
        0:
            #HP_Pump_Run := FALSE;
            #ERV_Position := 0.0;
            #High_Salinity_Alarm := FALSE;
        1:
            #HP_Pump_Run := TRUE;
            IF #Feed_Pressure < #SETPOINT_PRESSURE THEN
                #ERV_Position := 100.0;
            ELSE
                #ERV_Position := 50.0;
            END_IF;
            IF #Permeate_Salinity > #MAX_SALINITY THEN
                #High_Salinity_Alarm := TRUE;
                #State := 0;
            ELSE
                #High_Salinity_Alarm := FALSE;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "RO_Desalination_M1"
VERSION : 0.1
   VAR_INPUT
      Feed_Pressure : Real;
      Permeate_Salinity : Real;
      UV_Intensity : Real;
      Dosing_Tank_Level : Real;
      Start_Cmd : Bool;
      Stop_Cmd : Bool;
   END_VAR
   VAR_OUTPUT
      HP_Pump_Run : Bool;
      ERV_Position : Real;
      UV_Lamp_Cmd : Bool;
      Dosing_Pump_Cmd : Bool;
      System_Alarm : Bool;
   END_VAR
   VAR
      State : Int := 0;
   END_VAR
   VAR_CONSTANT
      MAX_SALINITY : Real := 500.0;
      MIN_UV : Real := 40.0;
      MIN_DOSING_LEVEL : Real := 10.0;
   END_VAR
BEGIN
    IF #Stop_Cmd OR (#State > 0 AND (#UV_Intensity < #MIN_UV OR #Dosing_Tank_Level < #MIN_DOSING_LEVEL)) THEN
        #State := 0;
        #System_Alarm := TRUE;
    ELSIF #Start_Cmd AND #State = 0 AND #UV_Intensity >= #MIN_UV AND #Dosing_Tank_Level >= #MIN_DOSING_LEVEL THEN
        #State := 1;
        #System_Alarm := FALSE;
    END_IF;

    CASE #State OF
        0:
            #HP_Pump_Run := FALSE;
            #ERV_Position := 0.0;
            #UV_Lamp_Cmd := FALSE;
            #Dosing_Pump_Cmd := FALSE;
        1:
            #HP_Pump_Run := TRUE;
            #UV_Lamp_Cmd := TRUE;
            #Dosing_Pump_Cmd := TRUE;
            IF #Permeate_Salinity > #MAX_SALINITY THEN
                #System_Alarm := TRUE;
                #State := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "RO_Desalination_M2"
VERSION : 0.1
   VAR_INPUT
      PN_IO_Status : Word;
      Feed_Pressure : Real;
      Permeate_Salinity : Real;
      UV_Intensity : Real;
      Start_Cmd : Bool;
   END_VAR
   VAR_OUTPUT
      HP_Pump_Run : Bool;
      Fault_Code : Int;
      PN_Status_Out : Word;
   END_VAR
BEGIN
    #PN_Status_Out := 16#0001;
    IF (#PN_IO_Status AND 16#0001) = 0 THEN
        #Fault_Code := 1001;
        #HP_Pump_Run := FALSE;
        RETURN;
    END_IF;
    IF #Permeate_Salinity > 500.0 THEN
        #Fault_Code := 2001;
        #HP_Pump_Run := FALSE;
    ELSIF #UV_Intensity < 40.0 THEN
        #Fault_Code := 3001;
        #HP_Pump_Run := FALSE;
    ELSE
        #Fault_Code := 0;
        #HP_Pump_Run := #Start_Cmd;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "RO_Desalination_M3"
VERSION : 0.1
   VAR_INPUT
      SCADA_Auth_Token : DInt;
      Network_MAC_Valid : Bool;
      Start_Cmd : Bool;
      Pump1_Fault : Bool;
      Pump2_Fault : Bool;
   END_VAR
   VAR_OUTPUT
      Pump1_Run : Bool;
      Pump2_Run : Bool;
      Security_Alert : Bool;
      SCADA_Data_Block : Struct
         Active_Pump : Int;
         System_Status : Int;
      End_Struct;
   END_VAR
   VAR_CONSTANT
      VALID_TOKEN : DInt := 16#A1B2C3D4;
   END_VAR
BEGIN
    IF NOT #Network_MAC_Valid OR #SCADA_Auth_Token <> #VALID_TOKEN THEN
        #Security_Alert := TRUE;
        #Pump1_Run := FALSE;
        #Pump2_Run := FALSE;
        #SCADA_Data_Block.System_Status := 99;
        RETURN;
    END_IF;
    #Security_Alert := FALSE;

    IF #Start_Cmd THEN
        IF NOT #Pump1_Fault THEN
            #Pump1_Run := TRUE;
            #Pump2_Run := FALSE;
            #SCADA_Data_Block.Active_Pump := 1;
        ELSIF NOT #Pump2_Fault THEN
            #Pump1_Run := FALSE;
            #Pump2_Run := TRUE;
            #SCADA_Data_Block.Active_Pump := 2;
        ELSE
            #Pump1_Run := FALSE;
            #Pump2_Run := FALSE;
            #SCADA_Data_Block.System_Status := 2;
        END_IF;
    ELSE
        #Pump1_Run := FALSE;
        #Pump2_Run := FALSE;
        #SCADA_Data_Block.System_Status := 0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "RO_Desalination_M4"
VERSION : 0.1
   VAR_INPUT
      Salinity_Sensor_1 : Real;
      Salinity_Sensor_2 : Real;
      HIL_Mode_Active : Bool;
      HIL_Sim_Salinity : Real;
      Start_Self_Test : Bool;
   END_VAR
   VAR_OUTPUT
      Drift_Alarm : Bool;
      Self_Test_Passed : Bool;
      Actual_Salinity : Real;
   END_VAR
   VAR
      State : Int := 0;
   END_VAR
   VAR_CONSTANT
      MAX_DRIFT : Real := 15.0;
   END_VAR
BEGIN
    IF #HIL_Mode_Active THEN
        #Actual_Salinity := #HIL_Sim_Salinity;
        #Drift_Alarm := FALSE;
    ELSE
        IF ABS(#Salinity_Sensor_1 - #Salinity_Sensor_2) > #MAX_DRIFT THEN
            #Drift_Alarm := TRUE;
        ELSE
            #Drift_Alarm := FALSE;
        END_IF;
        #Actual_Salinity := (#Salinity_Sensor_1 + #Salinity_Sensor_2) / 2.0;
    END_IF;

    IF #Start_Self_Test THEN
        #State := 99;
        #Self_Test_Passed := NOT #Drift_Alarm;
    ELSE
        #State := 0;
    END_IF;
END_FUNCTION_BLOCK

