PROGRAM PRG_Subsea_BOP_EtherCAT
VAR
    bEmergencyDisconnect AT %I* : BOOL;
    fAccumulatorPressure AT %I* : REAL;
    bAnnularRamClosed    AT %I* : BOOL;
    bShearRamClosed      AT %I* : BOOL;

    bAnnularRamCloseCmd  AT %Q* : BOOL;
    bShearRamCloseCmd    AT %Q* : BOOL;

    fMinAccPressure      : REAL := 200.0;
    bSystemReady         : BOOL;
    bAlarmLowPressure    : BOOL;

    // Deadman System
    bCommLoss            : BOOL;
    bHydraulicPowerLoss  : BOOL;
    bDeadmanArmed        : BOOL := TRUE;
    bDeadmanTriggered    : BOOL;

    fbTimerCommLoss      : TON;
    fbTimerHydLoss       : TON;

    // EtherCAT Diagnostics
    uiEcatMasterState    AT %I* : UINT;
    uiEcatSlaveState     AT %I* : ARRAY[1..4] OF UINT;
    bEcatError           : BOOL;
    iErrorID             : INT;

    // Fault Logging
    sFaultLog            : ARRAY[1..10] OF STRING(80);
    iLogIndex            : INT := 1;
END_VAR

// EtherCAT Monitoring
bEcatError := FALSE;
IF uiEcatMasterState <> 8 THEN // 8 = OP state
    bEcatError := TRUE;
    sFaultLog[iLogIndex] := 'EtherCAT Master not in OP';
END_IF

FOR iErrorID := 1 TO 4 DO
    IF uiEcatSlaveState[iErrorID] <> 8 THEN
        bEcatError := TRUE;
        bCommLoss := TRUE;
        sFaultLog[iLogIndex] := 'Subsea Slave Comm Error';
    END_IF
END_FOR

IF bEcatError THEN
    iLogIndex := (iLogIndex MOD 10) + 1;
END_IF

// Pressure Monitoring
IF fAccumulatorPressure < fMinAccPressure THEN
    bSystemReady := FALSE;
    bAlarmLowPressure := TRUE;
    bHydraulicPowerLoss := TRUE;
ELSE
    bSystemReady := TRUE;
    bAlarmLowPressure := FALSE;
    bHydraulicPowerLoss := FALSE;
END_IF

// Deadman Auto-Shear
fbTimerCommLoss(IN := bCommLoss, PT := T#5S);
fbTimerHydLoss(IN := bHydraulicPowerLoss, PT := T#5S);

IF bDeadmanArmed AND fbTimerCommLoss.Q AND fbTimerHydLoss.Q THEN
    bDeadmanTriggered := TRUE;
    sFaultLog[iLogIndex] := 'Deadman Sequence Triggered';
    iLogIndex := (iLogIndex MOD 10) + 1;
END_IF

// Actuation Sequence
IF (bEmergencyDisconnect AND bSystemReady) OR bDeadmanTriggered THEN
    bAnnularRamCloseCmd := TRUE;
    IF bAnnularRamClosed THEN
        bShearRamCloseCmd := TRUE;
    END_IF
END_IF
END_PROGRAM
