FUNCTION_BLOCK "EAF_Control_Depth"
VERSION : 0.1
   VAR_INPUT 
      Arc_Voltage : Real;
      Arc_Current : Real;
      Setpoint_Voltage : Real;
      Setpoint_Current : Real;
      Water_Temp_In : Real;
      Water_Temp_Out : Real;
   END_VAR
   VAR_OUTPUT 
      Electrode_Position : Real;
      Arc_Stable : Bool;
      Cooling_Valve_Pos : Real;
      Cooling_Alarm : Bool;
   END_VAR
   VAR 
      Kp : Real := 1.5;
      Ki : Real := 0.5;
      Error_V : Real;
      Integral_V : Real;
      Delta_T : Real;
   END_VAR

BEGIN
   // Electrode Control
   #Error_V := #Setpoint_Voltage - #Arc_Voltage;
   #Integral_V := #Integral_V + (#Error_V * 0.1);
   #Electrode_Position := (#Kp * #Error_V) + (#Ki * #Integral_V);
   IF #Electrode_Position > 100.0 THEN #Electrode_Position := 100.0; END_IF;
   IF #Electrode_Position < 0.0 THEN #Electrode_Position := 0.0; END_IF;

   // Arc Stability Check
   #Arc_Stable := ABS(#Arc_Current - #Setpoint_Current) < (#Setpoint_Current * 0.1);

   // Water Cooling Sub-system
   #Delta_T := #Water_Temp_Out - #Water_Temp_In;
   IF #Delta_T > 20.0 THEN
       #Cooling_Valve_Pos := 100.0; // Fully open
       #Cooling_Alarm := TRUE;
   ELSIF #Delta_T > 10.0 THEN
       #Cooling_Valve_Pos := 50.0 + (#Delta_T - 10.0) * 5.0;
       #Cooling_Alarm := FALSE;
   ELSE
       #Cooling_Valve_Pos := 50.0; // Nominal flow
       #Cooling_Alarm := FALSE;
   END_IF;
END_FUNCTION_BLOCK
