Here is a basic Allen-Bradley Structured Text (ST) program for a Longwall Shearer that implements Coal Face Profiling and Roof Support Advance.

```pascal
PROGRAM Longwall_Shearer_Base
VAR
    // Inputs
    Shearer_Position : REAL; // Current position of shearer along the face (meters)
    Coal_Face_Profile : ARRAY[0..100] OF REAL; // Scanned profile of the coal face
    Auto_Mode : BOOL; // System in automatic mode
    Start_Advance : BOOL; // Command to start roof support advance

    // Outputs
    Advance_Roof_Support : ARRAY[0..100] OF BOOL; // Commands to advance individual shields
    Shearer_Speed : REAL; // Speed of the shearer (m/s)

    // Internal
    Current_Shield_Index : DINT;
    Target_Shield : DINT;
END_VAR

// 1. Coal Face Profiling - Adjust shearer speed based on profile
IF Auto_Mode THEN
    // Calculate target shield based on shearer position (e.g., 1 shield per 1.5 meters)
    Target_Shield := REAL_TO_DINT(Shearer_Position / 1.5);

    IF Target_Shield >= 0 AND Target_Shield <= 100 THEN
        // Adjust speed based on coal face thickness/profile at current position
        IF Coal_Face_Profile[Target_Shield] > 2.0 THEN
            Shearer_Speed := 0.1; // Slow down for thick coal seam
        ELSE
            Shearer_Speed := 0.25; // Normal speed
        END_IF;
    END_IF;
ELSE
    Shearer_Speed := 0.0;
END_IF;

// 2. Roof Support Advance
// Automatically advance the roof support slightly behind the shearer
IF Auto_Mode AND Start_Advance THEN
    // Advance shields that are 10 meters behind the shearer (approx 6-7 shields)
    Current_Shield_Index := Target_Shield - 7;

    IF Current_Shield_Index >= 0 AND Current_Shield_Index <= 100 THEN
        Advance_Roof_Support[Current_Shield_Index] := TRUE;
    END_IF;

    // Reset previous shields
    IF Current_Shield_Index > 0 THEN
        Advance_Roof_Support[Current_Shield_Index - 1] := FALSE;
    END_IF;
END_IF;
END_PROGRAM
```

