IF Partner_PLC_Heartbeat = 0 THEN // Simplified heartbeat check
    Failover_Active := TRUE;
    PLC_Is_Primary := TRUE;
ELSE
    Failover_Active := FALSE;
END_IF;

// Execute control only if this PLC is primary
IF PLC_Is_Primary THEN

    // 2. IEC 62443 Cybersecurity: Payload Validation & RBAC
    Valid_Payload := (SCADA_Command_Token > 1000) AND (SCADA_Command_Token < 9999);

    IF SCADA_Start_Cmd AND Valid_Payload THEN
        IF SCADA_Active_User_Role >= 1 THEN // Minimum Operator role required
