PROGRAM Longwall_Shearer_Adversarial
VAR
    // Physical Sensors
    Raw_Shearer_Position : REAL;
    Raw_Radar_Thickness : REAL;

    // Adversarial Robustness: Sensor Drift Detection
    Filtered_Shearer_Position : REAL;
    Filtered_Radar_Thickness : REAL;
