```scl
FUNCTION_BLOCK "SagMill_Control"
VERSION : 0.1
   VAR_INPUT 
      start_cmd : Bool;   // Start command for SAG Mill
      stop_cmd : Bool;    // Stop command for SAG Mill
      mill_speed_act : Real; // Actual mill speed
      lube_pressure_act : Real; // Trunnion bearing lube pressure (bar)
      lube_temp_act : Real; // Trunnion bearing lube temperature (deg C)
      ore_feed_rate_sp : Real; // Setpoint for ore feed rate (tph)
      mill_weight_act : Real; // Actual mill weight (tons)
   END_VAR

   VAR_OUTPUT 
      lube_pump_cmd : Bool;   // Command to start lube pump
      mill_motor_cmd : Bool;  // Command to start mill main motor
      ore_feeder_cmd : Real;  // Command to ore feeder speed/rate (0-100%)
      fault_active : Bool;    // Fault present
   END_VAR

   VAR 
      state : Int; // 0=Stop, 1=LubeStart, 2=MillRun, 3=Fault
      lube_timer : TON_TIME;
      pid_feeder : "PID_Compact"; // Assuming a PID block is used
      pid_ctrl_val : Real;
   END_VAR

   VAR_CONSTANT 
      MIN_LUBE_PRESSURE : Real := 2.5; // Minimum lube pressure to run mill
      MAX_LUBE_TEMP : Real := 60.0;    // Maximum lube temperature
      MAX_MILL_WEIGHT : Real := 500.0; // Maximum mill weight
   END_VAR

BEGIN
    // Fault detection
    IF state > 0 AND (lube_pressure_act < MIN_LUBE_PRESSURE OR lube_temp_act > MAX_LUBE_TEMP OR mill_weight_act > MAX_MILL_WEIGHT) THEN
        state := 3; // Fault
    END_IF;

    // Stop command processing
    IF stop_cmd THEN
        state := 0;
    END_IF;

    // State machine
    CASE state OF
        0: // Stop
            lube_pump_cmd := FALSE;
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;
            fault_active := FALSE;
            IF start_cmd AND NOT stop_cmd THEN
                state := 1;
            END_IF;

        1: // Start Lube
            lube_pump_cmd := TRUE;
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;
            // Wait for lube pressure
            lube_timer(IN:=lube_pump_cmd AND (lube_pressure_act >= MIN_LUBE_PRESSURE), PT:=T#5s);
            IF lube_timer.Q THEN
                state := 2;
            END_IF;

        2: // Mill Run
            lube_pump_cmd := TRUE;
            mill_motor_cmd := TRUE;

            // Regulate Ore Feed Rate based on SP and Mill Weight (simplified PID call)
            pid_feeder(Setpoint := ore_feed_rate_sp,
                       Feedback := mill_weight_act, // Example proxy for feed rate matching
                       Output => pid_ctrl_val);

            ore_feeder_cmd := pid_ctrl_val;

        3: // Fault
            lube_pump_cmd := TRUE; // Keep lube on while stopping
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;
            fault_active := TRUE;
    END_CASE;
END_FUNCTION_BLOCK
```

