```scl
FUNCTION_BLOCK "SagMill_Control_With_HPLift"
VERSION : 0.1
   VAR_INPUT 
      start_cmd : Bool;   
      stop_cmd : Bool;    
      reset_cmd : Bool;
      mill_speed_act : Real; // Actual mill speed (RPM)
      lp_lube_pressure_act : Real; // LP trunnion bearing lube pressure (bar)
      hp_lube_pressure_act : Real; // HP lift pressure (bar)
      trunnion_lift_act : Real; // Measured lift distance (mm)
      lube_temp_act : Real; 
      ore_feed_rate_sp : Real; 
      mill_weight_act : Real; 
   END_VAR

   VAR_OUTPUT 
      lp_lube_pump_cmd : Bool;   
      hp_lube_pump_cmd : Bool;
      mill_motor_cmd : Bool;  
      ore_feeder_cmd : Real;  
      fault_active : Bool;
      state_out : Int;
   END_VAR

   VAR 
      state : Int; 
      lp_timer : TON_TIME;
      hp_timer : TON_TIME;
      pid_feeder : "PID_Compact"; 
      pid_ctrl_val : Real;
   END_VAR

   VAR_CONSTANT 
      MIN_LP_PRESSURE : Real := 2.5; 
      MIN_HP_PRESSURE : Real := 150.0;
      MIN_LIFT_MM : Real := 0.15;
      MIN_RUN_RPM : Real := 5.0;
      MAX_LUBE_TEMP : Real := 60.0;    
      MAX_MILL_WEIGHT : Real := 500.0; 
   END_VAR

BEGIN
    // Fault conditions
    IF state > 0 AND (lp_lube_pressure_act < MIN_LP_PRESSURE OR lube_temp_act > MAX_LUBE_TEMP OR mill_weight_act > MAX_MILL_WEIGHT) THEN
        state := 99; // Fault
    END_IF;
    IF (state = 30 OR state = 40) AND (hp_lube_pressure_act < MIN_HP_PRESSURE OR trunnion_lift_act < MIN_LIFT_MM) AND mill_speed_act < MIN_RUN_RPM THEN
        state := 99; // HP Lift Fault
    END_IF;

    IF stop_cmd THEN
        state := 0;
    END_IF;

    IF reset_cmd AND state = 99 THEN
        state := 0;
    END_IF;

    CASE state OF
        0: // Stop
            lp_lube_pump_cmd := FALSE;
            hp_lube_pump_cmd := FALSE;
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;
            fault_active := FALSE;
            IF start_cmd AND NOT stop_cmd THEN
                state := 10;
            END_IF;

        10: // Start LP Lube
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := FALSE;
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;

            lp_timer(IN:=(lp_lube_pressure_act >= MIN_LP_PRESSURE), PT:=T#5s);
            IF lp_timer.Q THEN
                state := 20;
            END_IF;

        20: // Start HP Lift
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := TRUE;

            hp_timer(IN:=(hp_lube_pressure_act >= MIN_HP_PRESSURE) AND (trunnion_lift_act >= MIN_LIFT_MM), PT:=T#3s);
            IF hp_timer.Q THEN
                state := 30; // Ready for main motor
            END_IF;

        30: // Start Main Motor
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := TRUE;
            mill_motor_cmd := TRUE;

            IF mill_speed_act >= MIN_RUN_RPM THEN
                state := 40; // Running, disable HP
            END_IF;

        40: // Normal Run
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := FALSE; // Turn off HP lift once hydrodynamic lubrication is established
            mill_motor_cmd := TRUE;

            // PI control for Feeder
            pid_feeder(Setpoint := ore_feed_rate_sp,
                       Feedback := mill_weight_act, 
                       Output => pid_ctrl_val);
            ore_feeder_cmd := pid_ctrl_val;

        99: // Fault
            lp_lube_pump_cmd := TRUE; 
            hp_lube_pump_cmd := TRUE; // Keep lift on to protect bearings while stopping
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;
            fault_active := TRUE;

            // If stopped, can turn off HP
            IF mill_speed_act < 0.1 THEN
                hp_lube_pump_cmd := FALSE;
            END_IF;
    END_CASE;

    state_out := state;
END_FUNCTION_BLOCK
