   END_VAR

   VAR_OUTPUT 
      lp_pump_1_cmd : Bool;   
      lp_pump_2_cmd : Bool;   
      hp_lube_pump_cmd : Bool;
      mill_motor_cmd : Bool;  
      ore_feeder_cmd : Real;  
      fault_active : Bool;
      fault_code : Word; 
      state_out : Int;
      self_test_pass : Bool;
   END_VAR

   VAR 
      state : Int; 
      lp_timer : TON_TIME;
      hp_timer : TON_TIME;
      test_timer : TON_TIME;
      pid_feeder : "PID_Compact"; 
      pid_ctrl_val : Real;
      active_lp_pump : Int := 1; 
      validated_lift : Real;
   END_VAR

   VAR_CONSTANT 
      MIN_LP_PRESSURE : Real := 2.5; 
      MIN_HP_PRESSURE : Real := 150.0;
      MIN_LIFT_MM : Real := 0.15;
      MAX_LIFT_DEVIATION : Real := 0.05; // 50 microns max drift
      MIN_RUN_RPM : Real := 5.0;

      F_NONE : Word := 16#0000;
      F_SENSOR_DRIFT : Word := 16#00B1;
      F_SELF_TEST_FAIL : Word := 16#00B2;
   END_VAR

BEGIN
    // Sensor Drift Detection & Validation (Adversarial Defense)
    IF ABS(trunnion_lift_act_A - trunnion_lift_act_B) > MAX_LIFT_DEVIATION THEN
        fault_code := F_SENSOR_DRIFT;
        state := 99;
    ELSE
        validated_lift := (trunnion_lift_act_A + trunnion_lift_act_B) / 2.0;
    END_IF;

    // Standard Failover
    IF state > 0 AND state < 90 THEN
        IF active_lp_pump = 1 AND lp_lube_press_act_1 < MIN_LP_PRESSURE THEN active_lp_pump := 2;
        ELSIF active_lp_pump = 2 AND lp_lube_press_act_2 < MIN_LP_PRESSURE THEN active_lp_pump := 1; END_IF;
    END_IF;

    IF stop_cmd THEN state := 0; END_IF;
    IF reset_cmd AND state = 99 THEN fault_code := F_NONE; state := 0; self_test_pass := FALSE; END_IF;

    CASE state OF
        0: // Stop
            lp_pump_1_cmd := FALSE; lp_pump_2_cmd := FALSE; hp_lube_pump_cmd := FALSE; mill_motor_cmd := FALSE; ore_feeder_cmd := 0.0;
            fault_active := FALSE;
            IF start_cmd AND NOT stop_cmd AND fault_code = F_NONE THEN state := 10; END_IF;
            IF run_self_test_cmd AND NOT start_cmd THEN state := 90; END_IF; // Enter Self-Test

        10: // LP Lube
            lp_pump_1_cmd := (active_lp_pump = 1); lp_pump_2_cmd := (active_lp_pump = 2);
            lp_timer(IN:=((active_lp_pump=1 AND lp_lube_press_act_1 >= MIN_LP_PRESSURE) OR (active_lp_pump=2 AND lp_lube_press_act_2 >= MIN_LP_PRESSURE)), PT:=T#5s);
            IF lp_timer.Q THEN state := 20; END_IF;

        20: // HP Lift
            hp_lube_pump_cmd := TRUE;
            hp_timer(IN:=(hp_lube_press_act >= MIN_HP_PRESSURE) AND (validated_lift >= MIN_LIFT_MM), PT:=T#3s);
            IF hp_timer.Q THEN state := 30; END_IF;

        30: // Main Motor
            mill_motor_cmd := TRUE;
            IF mill_speed_act >= MIN_RUN_RPM THEN state := 40; END_IF;

        40: // Normal Run
            hp_lube_pump_cmd := FALSE; 
            pid_feeder(Setpoint := ore_feed_rate_sp, Feedback := mill_weight_act, Output => pid_ctrl_val);
            ore_feeder_cmd := pid_ctrl_val;

        90: // Self-Test Routine
            lp_pump_1_cmd := TRUE; lp_pump_2_cmd := TRUE; hp_lube_pump_cmd := TRUE;
            test_timer(IN:=TRUE, PT:=T#10s);
            IF test_timer.Q THEN
                IF (lp_lube_press_act_1 >= MIN_LP_PRESSURE) AND (lp_lube_press_act_2 >= MIN_LP_PRESSURE) AND (hp_lube_press_act >= MIN_HP_PRESSURE) THEN
                    self_test_pass := TRUE;
                    state := 0;
                ELSE
                    fault_code := F_SELF_TEST_FAIL;
                    state := 99;
                END_IF;
            END_IF;

        99: // Fault
            lp_pump_1_cmd := TRUE; lp_pump_2_cmd := TRUE; hp_lube_pump_cmd := TRUE; 
            mill_motor_cmd := FALSE; ore_feeder_cmd := 0.0;
            fault_active := TRUE;
            IF mill_speed_act < 0.1 THEN hp_lube_pump_cmd := FALSE; END_IF;
    END_CASE;

    // HIL Digital Twin Output Muting (Bypass Physical IO if Simulation Mode is Active)
    IF hil_sim_mode THEN
        // In physical PLC mapping, this flag disables hardware IO writes 
        // while outputs continue updating memory DBs for the simulator.
    END_IF;

    state_out := state;
END_FUNCTION_BLOCK
