// Siemens SCL - Mutation 3 (Add Reasoning)
FUNCTION_BLOCK "FB_ECoat_Reasoning"
VERSION : 0.1
   VAR_INPUT
      SCADA_Cmd_Token : DWORD;
      SCADA_Setpoint : REAL;
      Rectifier_1_Status : WORD;
      Rectifier_2_Status : WORD;
   END_VAR
   VAR_OUTPUT
      Rectifier_1_Cmd : WORD;
      Rectifier_2_Cmd : WORD;
      System_Voltage : REAL;
      SCADA_Status : STRUCT
         Active_Rectifier : INT;
         Fault_Code : INT;
         Security_Alert : BOOL;
      END_STRUCT;
   END_VAR
   VAR
      Active_Rectifier : INT := 1;
      Valid_Token : DWORD := 16#A5A5_5A5A;
   END_VAR

BEGIN
   // IEC 62443 Security Check
   IF SCADA_Cmd_Token <> Valid_Token THEN
      SCADA_Status.Security_Alert := TRUE;
      RETURN;
   ELSE
      SCADA_Status.Security_Alert := FALSE;
   END_IF;

   // Hot-Standby Failover
   IF (Rectifier_1_Status AND 16#0002) > 0 AND Active_Rectifier = 1 THEN
      Active_Rectifier := 2;
   ELSIF (Rectifier_2_Status AND 16#0002) > 0 AND Active_Rectifier = 2 THEN
      Active_Rectifier := 1;
   END_IF;

   SCADA_Status.Active_Rectifier := Active_Rectifier;
   System_Voltage := SCADA_Setpoint * 1.5;

   IF Active_Rectifier = 1 THEN
      Rectifier_1_Cmd := 16#0001;
      Rectifier_2_Cmd := 16#0000;
   ELSE
      Rectifier_1_Cmd := 16#0000;
      Rectifier_2_Cmd := 16#0001;
   END_IF;
END_FUNCTION_BLOCK
