FUNCTION_BLOCK FB_WaferStepper
TITLE = 'Wafer Stepper Control'
VERSION : '1.0'
AUTHOR : 'Evol'

VAR_INPUT
    Enable : BOOL; // Enable Wafer Stepper
    StagePosRef : REAL; // Reference position for stage (nm)
    FocusPitchRef : REAL; // Reference focus pitch (urad)
    InterferometerFb : REAL; // Feedback from Stage Interferometer (nm)
    FocusPitchFb : REAL; // Feedback from Focus Pitch sensor (urad)
    Kp_Stage : REAL := 0.5;
    Ki_Stage : REAL := 0.01;
    Kp_Focus : REAL := 0.5;
    Ki_Focus : REAL := 0.01;
END_VAR

VAR_OUTPUT
    StageDriveCmd : REAL; // Command to stage motor
    FocusActuatorCmd : REAL; // Command to focus pitch actuator
    InPosition : BOOL;
    InFocus : BOOL;
END_VAR

VAR
    StageError : REAL;
    StageErrorInt : REAL;
    FocusError : REAL;
    FocusErrorInt : REAL;
END_VAR

CONST
    TOLERANCE_POS : REAL := 5.0; // 5 nm tolerance
    TOLERANCE_FOCUS : REAL := 1.0; // 1 urad tolerance
END_CONST

BEGIN
    IF NOT Enable THEN
        StageDriveCmd := 0.0;
        FocusActuatorCmd := 0.0;
        StageErrorInt := 0.0;
        FocusErrorInt := 0.0;
        InPosition := FALSE;
        InFocus := FALSE;
        RETURN;
    END_IF;

    // Stage Interferometer Control (PI Controller)
    StageError := StagePosRef - InterferometerFb;
    StageErrorInt := StageErrorInt + StageError;
    StageDriveCmd := (Kp_Stage * StageError) + (Ki_Stage * StageErrorInt);

    // Focus Pitch Control (PI Controller)
    FocusError := FocusPitchRef - FocusPitchFb;
    FocusErrorInt := FocusErrorInt + FocusError;
    FocusActuatorCmd := (Kp_Focus * FocusError) + (Ki_Focus * FocusErrorInt);

    // Status Flags
    InPosition := ABS(StageError) <= TOLERANCE_POS;
    InFocus := ABS(FocusError) <= TOLERANCE_FOCUS;

END_FUNCTION_BLOCK
