FUNCTION_BLOCK FB_WaferStepper_Profinet
TITLE = 'Wafer Stepper Control with Profinet & Diagnostics'
VERSION : '1.2'

VAR_INPUT
    Enable : BOOL; 
    // Profinet Inputs (Mapped from HW)
    PN_StagePosRef : REAL; 
    PN_FocusPitchRef : REAL; 
    PN_InterferometerFb : REAL; 
    PN_FocusPitchFb : REAL; 
    PN_TargetUVDose : REAL; 
    PN_UVIntensityFb : REAL; 
    PN_InterferometerStatus : WORD; // Hardware status
    PN_LaserStatus : WORD;
    Clock_1ms : BOOL; 
END_VAR

VAR_OUTPUT
    // Profinet Outputs
    PN_StageDriveCmd : REAL; 
    PN_FocusActuatorCmd : REAL; 
    PN_UvShutterOpenCmd : BOOL;
    PN_ExposureComplete : BOOL;
    PN_StatusWord : WORD;
    PN_FaultCode : INT;
END_VAR

VAR
    StageError, StageErrorInt : REAL;
    FocusError, FocusErrorInt : REAL;
    AccumulatedDose : REAL;
    ExposureActive : BOOL;
    ClockPulse_R_TRIG, ClockPulse_M : BOOL;
    StateFault : BOOL;
    FaultTimer : INT;
END_VAR

CONST
    TOLERANCE_POS : REAL := 5.0; 
    TOLERANCE_FOCUS : REAL := 1.0; 
    FAULT_INTERFEROMETER : INT := 101;
    FAULT_LASER_SOURCE : INT := 102;
    FAULT_FOLLOWING_ERR : INT := 103;
END_CONST

BEGIN
    ClockPulse_R_TRIG := Clock_1ms AND NOT ClockPulse_M;
    ClockPulse_M := Clock_1ms;

    // Diagnostics
    StateFault := FALSE;
    PN_FaultCode := 0;

    IF (PN_InterferometerStatus AND 16#0001) = 0 THEN
        StateFault := TRUE;
        PN_FaultCode := FAULT_INTERFEROMETER;
    ELSIF (PN_LaserStatus AND 16#0001) = 0 THEN
        StateFault := TRUE;
        PN_FaultCode := FAULT_LASER_SOURCE;
    END_IF;

    IF ABS(StageError) > 500.0 THEN // Huge following error
        StateFault := TRUE;
        PN_FaultCode := FAULT_FOLLOWING_ERR;
    END_IF;

    IF StateFault OR NOT Enable THEN
        PN_StageDriveCmd := 0.0;
        PN_FocusActuatorCmd := 0.0;
        PN_UvShutterOpenCmd := FALSE;
        PN_ExposureComplete := FALSE;
        ExposureActive := FALSE;
        AccumulatedDose := 0.0;
        StageErrorInt := 0.0;
        FocusErrorInt := 0.0;

        IF StateFault THEN
            PN_StatusWord := 16#000F; // Faulted status
        ELSE
            PN_StatusWord := 16#0000; // Disabled
        END_IF;
        RETURN;
    END_IF;

    PN_StatusWord := 16#0001; // Running

    // Stage & Focus Control (Simplified Gains for demo)
    StageError := PN_StagePosRef - PN_InterferometerFb;
    StageErrorInt := StageErrorInt + StageError;
    PN_StageDriveCmd := (0.5 * StageError) + (0.01 * StageErrorInt);

    FocusError := PN_FocusPitchRef - PN_FocusPitchFb;
    FocusErrorInt := FocusErrorInt + FocusError;
    PN_FocusActuatorCmd := (0.5 * FocusError) + (0.01 * FocusErrorInt);

    // UV Exposure
    IF ABS(StageError) <= TOLERANCE_POS AND ABS(FocusError) <= TOLERANCE_FOCUS AND NOT PN_ExposureComplete THEN
        ExposureActive := TRUE;
        PN_UvShutterOpenCmd := TRUE;
        PN_StatusWord := 16#0003; // Exposing
    ELSE
        ExposureActive := FALSE;
        PN_UvShutterOpenCmd := FALSE;
    END_IF;

    IF ExposureActive AND ClockPulse_R_TRIG THEN
        AccumulatedDose := AccumulatedDose + (PN_UVIntensityFb * 0.001);
        IF AccumulatedDose >= PN_TargetUVDose THEN
            PN_ExposureComplete := TRUE;
            PN_UvShutterOpenCmd := FALSE;
            ExposureActive := FALSE;
            PN_StatusWord := 16#0005; // Done
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
