FUNCTION_BLOCK FB_WaferStepper_Adversarial
TITLE = 'Wafer Stepper - Adversarial Resilience & Digital Twin'
VERSION : '1.4'

VAR_INPUT
    Enable : BOOL; 
    StartSelfTest : BOOL;
    SCADA_AuthToken : DWORD; 
    InterferometerFb_A : REAL; 
    InterferometerFb_B : REAL; 
    DigitalTwin_Fb : REAL; // Feedback from HIL simulation
    StagePosRef : REAL; 
END_VAR

VAR_OUTPUT
    StageDriveCmd : REAL; 
    SystemState : INT; // 0=Off, 1=SelfTest, 2=Sync, 3=Run, 99=Fault
    DriftAlert : BOOL;
    DigitalTwinDesync : BOOL;
END_VAR

VAR
    SensorAvg : REAL;
    HistoryBuffer : ARRAY[0..99] OF REAL;
    BufferIdx : INT;
    DriftIntegral : REAL;
    SelfTestStep : INT;
    SelfTestTimer : INT;
END_VAR

CONST
    VALID_TOKEN : DWORD := 16#A1B2C3D4;
    DRIFT_THRESHOLD : REAL := 50.0;
    TWIN_DESYNC_LIMIT : REAL := 15.0;
END_CONST

BEGIN
    IF SCADA_AuthToken <> VALID_TOKEN THEN
        SystemState := 99; // Security Lockout
        StageDriveCmd := 0.0;
        RETURN;
    END_IF;

    // Startup Self-Test Routine
    IF StartSelfTest AND SystemState = 0 THEN
        SystemState := 1;
        SelfTestStep := 1;
        SelfTestTimer := 0;
    END_IF;

    IF SystemState = 1 THEN
        SelfTestTimer := SelfTestTimer + 1;
        CASE SelfTestStep OF
            1: // Test Actuator Response
                StageDriveCmd := 10.0; // Small test pulse
                IF SelfTestTimer > 100 THEN 
                    SelfTestStep := 2; 
                    SelfTestTimer := 0; 
                END_IF;
            2: // Verify Twin Sync
                IF ABS(InterferometerFb_A - DigitalTwin_Fb) < 5.0 THEN
                    SystemState := 2; // Move to Sync State
                ELSE
                    SystemState := 99; // Failed Self-Test
                END_IF;
        END_CASE;
        RETURN;
    END_IF;

    IF SystemState >= 2 AND Enable THEN
        // Sensor Drift Detection (Moving average or integration of difference)
        SensorAvg := (InterferometerFb_A + InterferometerFb_B) / 2.0;
        DriftIntegral := DriftIntegral + (InterferometerFb_A - InterferometerFb_B);

        IF ABS(DriftIntegral) > DRIFT_THRESHOLD THEN
            DriftAlert := TRUE;
        ELSE
            DriftAlert := FALSE;
        END_IF;

        // Digital Twin HIL Sync Check
        IF ABS(SensorAvg - DigitalTwin_Fb) > TWIN_DESYNC_LIMIT THEN
            DigitalTwinDesync := TRUE;
            SystemState := 99; // HIL desync fault, adversarial manipulation possible
        ELSE
            DigitalTwinDesync := FALSE;
        END_IF;

        IF SystemState <> 99 THEN
            SystemState := 3; // Running
            StageDriveCmd := (StagePosRef - SensorAvg) * 0.5;
        ELSE
            StageDriveCmd := 0.0;
        END_IF;
    ELSE
        StageDriveCmd := 0.0;
        IF SystemState = 3 THEN SystemState := 0; END_IF;
    END_IF;

END_FUNCTION_BLOCK
