PROGRAM MAIN
VAR
    bEnable : BOOL;
    rChilledWaterTemp, rChilledWaterSetpoint : REAL := 7.0;
    rCondenserPressure, rZoneMaxValvePos, rDifferentialPressure : REAL;
    rDPSetpoint : REAL := 1.5;

    // Outputs
    rCompressorSpeedRef, rSecPumpSpeedRef : REAL;
    bCompressorRun, bPrimPumpRun : BOOL;
    bCondenserFan1, bCondenserFan2 : BOOL;

    // EtherCAT Diagnostics & Alarms
    uiCompDriveStatus AT %I* : UINT; // CoE Status Word
    uiPumpDriveStatus AT %I* : UINT;
    bEtherCATError AT %I* : BOOL;

    bCriticalFault, bWarning : BOOL;
    iAlarmCode : INT; // 1=ECAT, 2=CompDrv, 3=PumpDrv

    fbCompPID, fbPumpPID : FB_BasicPID;
    tFan1Delay, tFan2Delay : TON;
END_VAR

// Fault Management & EtherCAT Diagnostics
bCriticalFault := FALSE;
bWarning := FALSE;
iAlarmCode := 0;

IF bEtherCATError THEN
    bCriticalFault := TRUE;
    iAlarmCode := 1;
END_IF

// Check Drive Faults (Bit 3 of DS402 Status Word)
IF (uiCompDriveStatus AND 16#0008) <> 0 THEN
    bCriticalFault := TRUE;
    iAlarmCode := 2;
END_IF
IF (uiPumpDriveStatus AND 16#0008) <> 0 THEN
    bCriticalFault := TRUE;
    iAlarmCode := 3;
END_IF

// DP Reset Logic
IF rZoneMaxValvePos > 90.0 THEN rDPSetpoint := rDPSetpoint + 0.01;
ELSIF rZoneMaxValvePos < 60.0 THEN rDPSetpoint := rDPSetpoint - 0.01; END_IF
rDPSetpoint := LIMIT(1.0, rDPSetpoint, 2.0);

// Control Execution
IF bEnable AND NOT bCriticalFault THEN
    bPrimPumpRun := TRUE;
    fbPumpPID(fSetpointValue:=rDPSetpoint, fActualValue:=rDifferentialPressure, bReset:=FALSE, fKp:=1.5, fTn:=5.0, fMaxCtrlOutput:=100.0, fMinCtrlOutput:=20.0);
    rSecPumpSpeedRef := fbPumpPID.fCtrlOutput;

    bCompressorRun := TRUE;
    fbCompPID(fSetpointValue:=rChilledWaterSetpoint, fActualValue:=rChilledWaterTemp, bReset:=FALSE, fKp:=2.5, fTn:=10.0, fMaxCtrlOutput:=100.0, fMinCtrlOutput:=0.0);
    rCompressorSpeedRef := fbCompPID.fCtrlOutput;
ELSE
    bPrimPumpRun := FALSE;
    bCompressorRun := FALSE;
    rSecPumpSpeedRef := 0.0;
    rCompressorSpeedRef := 0.0;
    fbPumpPID(bReset:=TRUE);
    fbCompPID(bReset:=TRUE);
END_IF

// Fans
tFan1Delay(IN := rCondenserPressure > 12.0 AND NOT bCriticalFault, PT := T#5S);
IF tFan1Delay.Q THEN bCondenserFan1 := TRUE; ELSIF rCondenserPressure < 10.0 OR bCriticalFault THEN bCondenserFan1 := FALSE; END_IF

tFan2Delay(IN := rCondenserPressure > 15.0 AND bCondenserFan1 AND NOT bCriticalFault, PT := T#5S);
IF tFan2Delay.Q THEN bCondenserFan2 := TRUE; ELSIF rCondenserPressure < 13.0 OR bCriticalFault THEN bCondenserFan2 := FALSE; END_IF
