Timer_Purge(IN := (State_Reversal = 1) OR (State_Reversal = 3), PT := T#30s);

CASE State_Reversal OF
    0: DO_FireLeft := TRUE; DO_FireRight := FALSE; DO_PurgeValve := FALSE; IF Timer_Firing.Q THEN State_Reversal := 1; END_IF;
    1: DO_FireLeft := FALSE; DO_FireRight := FALSE; DO_PurgeValve := TRUE; IF Timer_Purge.Q THEN State_Reversal := 2; END_IF;
    2: DO_FireLeft := FALSE; DO_FireRight := TRUE; DO_PurgeValve := FALSE; IF Timer_Firing.Q THEN State_Reversal := 3; END_IF;
    3: DO_FireLeft := FALSE; DO_FireRight := FALSE; DO_PurgeValve := TRUE; IF Timer_Purge.Q THEN State_Reversal := 0; END_IF;
END_CASE;

IF (State_Reversal = 1) OR (State_Reversal = 3) THEN
    AO_AirValveCmd := 0.0;
