FUNCTION_BLOCK FB_KilnOptimizer
VAR_INPUT
    KilnTemp : REAL; // Current kiln temperature
    TargetTemp : REAL; // Target kiln temperature
    ProductionRate : REAL; // Target production rate
END_VAR
VAR_OUTPUT
    CoalMillFeed : REAL; // Coal mill feed rate (t/h)
    KilnSpeed : REAL; // Kiln rotational speed (rpm)
