VAR
    TempError : REAL;
END_VAR

BEGIN
    // Calculate temperature error
    TempError := TargetTemp - KilnTemp;

    // Optimize Coal Mill Feed
    CoalMillFeed := (ProductionRate * 0.15) + (TempError * 0.5);
    IF CoalMillFeed > 50.0 THEN CoalMillFeed := 50.0; END_IF;
    IF CoalMillFeed < 5.0 THEN CoalMillFeed := 5.0; END_IF;

    // Optimize Kiln Speed
    KilnSpeed := (ProductionRate * 0.05) + (TempError * 0.02);
    IF KilnSpeed > 5.0 THEN KilnSpeed := 5.0; END_IF;
    IF KilnSpeed < 0.5 THEN KilnSpeed := 0.5; END_IF;

END_FUNCTION_BLOCK
