PROGRAM MAIN
VAR
    // HIL Digital Twin Sync
    bHIL_Mode : BOOL := FALSE;
    rHIL_SimTemp : REAL;
    rHIL_SimPressure : REAL;

    // Redundant Sensors
    rTemp1 AT %I* : REAL;
    rTemp2 AT %I* : REAL;
    rActiveTemp : REAL;

