Here is a Beckhoff Structured Text (ST) program for managing a Hypersonic Sled Track's Linear Synchronous Motor (LSM) propulsion and braking system. The code uses a finite state machine to progress through idle, arming, propulsion, coasting, braking, and safe states.

```iecst
PROGRAM PRG_HypersonicSled
VAR
    eState : (IDLE, ARMING, PROPULSION, COASTING, BRAKING, SAFE, FAULT) := IDLE;
    bStartCmd : BOOL;
    bStopCmd : BOOL;

    fPosition : LREAL; // Sled position in meters
    fVelocity : LREAL; // Sled velocity in m/s

    // Parameters
    fTargetVelocity : LREAL := 3000.0;
    fBrakingStartPos : LREAL := 8000.0;
    fTrackEndPos : LREAL := 10000.0;

    // Outputs
    bEnablePropulsion : BOOL;
    fThrustCommand : LREAL;
    bEnableBraking : BOOL;
    fBrakingForceCommand : LREAL;
END_VAR

CASE eState OF
    IDLE:
        bEnablePropulsion := FALSE;
        bEnableBraking := FALSE;
        fThrustCommand := 0.0;
        fBrakingForceCommand := 0.0;
        IF bStartCmd THEN
            eState := ARMING;
        END_IF

    ARMING:
        // Check safety interlocks here
        eState := PROPULSION;

    PROPULSION:
        bEnablePropulsion := TRUE;
        fThrustCommand := 100.0; // Max thrust
        IF fVelocity >= fTargetVelocity THEN
            eState := COASTING;
        ELSIF fPosition >= fBrakingStartPos THEN
            eState := BRAKING;
        END_IF

    COASTING:
        bEnablePropulsion := FALSE;
        fThrustCommand := 0.0;
        IF fPosition >= fBrakingStartPos THEN
            eState := BRAKING;
        END_IF

    BRAKING:
        bEnablePropulsion := FALSE;
        bEnableBraking := TRUE;
        fBrakingForceCommand := 100.0; // Max braking force
        IF fVelocity <= 0.1 THEN
            eState := SAFE;
        END_IF

    SAFE:
        bEnableBraking := TRUE; // Hold brakes
        IF bStopCmd THEN
            eState := IDLE;
        END_IF

    FAULT:
        bEnablePropulsion := FALSE;
        bEnableBraking := TRUE;
        fBrakingForceCommand := 100.0;
END_CASE
```

