        IF bScadaAuth THEN eState := SELF_TEST; END_IF
    SELF_TEST:
        // Pulse actuators lightly and verify response
        fbSelfTestTimer(IN := TRUE);
        IF fbSelfTestTimer.Q THEN
            IF bActuatorOk THEN eState := HIL_SYNC; ELSE eState := FAULT; END_IF
            fbSelfTestTimer(IN := FALSE);
        END_IF
    HIL_SYNC:
        // Check digital twin state sync
        IF ABS(fEnc1Pos - fHilSimPosition) < 0.1 THEN
            bHilSynced := TRUE;
            eState := ARMING;
        ELSE
            eState := FAULT;
        END_IF
    ARMING:
        eState := PROPULSION;
    PROPULSION:
        bEnablePropulsion := TRUE;
        fThrustCommand := 100.0;
        IF fEnc1Pos >= 8000.0 THEN eState := BRAKING; END_IF
    BRAKING:
        bEnablePropulsion := FALSE;
        bEnableBraking := TRUE;
        IF fEnc1Pos >= 10000.0 THEN eState := SAFE; END_IF
    SAFE:
        bEnableBraking := TRUE;
    FAULT:
        bEnablePropulsion := FALSE;
        bEnableBraking := TRUE;
END_CASE
