    Self_Test_Step : INT := 0;
    Self_Test_Passed : BOOL;
    Motor_Speed_Cmd : REAL;
    Emergency_Stop : BOOL;
END_VAR

IF (Sensor_A >= Sensor_B AND Sensor_A <= Sensor_C) OR (Sensor_A >= Sensor_C AND Sensor_A <= Sensor_B) THEN
    Voted_G_Force := Sensor_A;
ELSIF (Sensor_B >= Sensor_A AND Sensor_B <= Sensor_C) OR (Sensor_B >= Sensor_C AND Sensor_B <= Sensor_A) THEN
    Voted_G_Force := Sensor_B;
ELSE
    Voted_G_Force := Sensor_C;
END_IF;

IF ABS(Sensor_A - Voted_G_Force) > 0.5 OR ABS(Sensor_B - Voted_G_Force) > 0.5 OR ABS(Sensor_C - Voted_G_Force) > 0.5 THEN
    Sensor_Drift_Fault := TRUE;
END_IF;

HIL_Deviation := ABS(Voted_G_Force - HIL_G_Force_Sim);
IF HIL_Deviation > 1.0 THEN
    HIL_Sync_Fault := TRUE;
    Emergency_Stop := TRUE;
END_IF;

IF Self_Test_Active THEN
    CASE Self_Test_Step OF
        0:
            Motor_Speed_Cmd := 5.0;
            Self_Test_Step := 1;
        1:
            IF Voted_G_Force > 0.1 THEN
                Self_Test_Step := 2;
            END_IF;
        2:
            Motor_Speed_Cmd := 0.0;
            Self_Test_Passed := TRUE;
            Self_Test_Active := FALSE;
    END_CASE;
END_IF;

IF NOT Self_Test_Active AND NOT Emergency_Stop THEN
    Motor_Speed_Cmd := 100.0;
END_IF;
END_PROGRAM

