        State := 0;
    ELSIF StartMode_Generate AND State = 0 THEN
        State := 10;
    ELSIF StartMode_Pump AND State = 0 THEN
        State := 20;
    END_IF;
    CASE State OF
        0:
            ClosePenstockValve := TRUE;
            OpenPenstockValve := FALSE;
            TurbineGuideVanePos := 0.0;
            ModeActive_Generate := FALSE;
            ModeActive_Pump := FALSE;
        10:
            ModeActive_Generate := TRUE;
            IF PenstockPressure > 10.0 THEN
                OpenPenstockValve := TRUE;
                ClosePenstockValve := FALSE;
                TurbineGuideVanePos := 50.0;
            END_IF;
        20:
            ModeActive_Pump := TRUE;
            IF PenstockPressure < 5.0 THEN
                OpenPenstockValve := TRUE;
                ClosePenstockValve := FALSE;
                TurbineGuideVanePos := 25.0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
