FUNCTION_BLOCK FB_HydroPlant_Sync
VAR_INPUT
    Cmd_Generate : BOOL;
    Cmd_Stop : BOOL;
    Grid_Voltage : REAL;
    Gen_Voltage : REAL;
    Phase_Angle_Diff : REAL;
END_VAR
VAR_OUTPUT
    Valve_Open : BOOL;
    Sync_Breaker_Close : BOOL;
    Status : STRING;
END_VAR
VAR
    State : INT := 0;
    Sync_OK : BOOL := FALSE;
END_VAR
BEGIN
    IF Cmd_Stop THEN State := 0; END_IF;
    IF Cmd_Generate AND State = 0 THEN State := 10; END_IF;

    Sync_OK := (ABS(Grid_Voltage - Gen_Voltage) < 5.0) AND (ABS(Phase_Angle_Diff) < 5.0);

    CASE State OF
        0:
            Valve_Open := FALSE;
            Sync_Breaker_Close := FALSE;
            Status := 'STOPPED';
        10:
            Valve_Open := TRUE;
            Status := 'SYNCHRONIZING';
            IF Sync_OK THEN
                Sync_Breaker_Close := TRUE;
                State := 20;
            END_IF;
        20:
            Status := 'GENERATING';
    END_CASE;
END_FUNCTION_BLOCK
