FUNCTION_BLOCK FB_HydroPlant_SecureFailover
VAR_INPUT
    SCADA_Cmd : WORD;
    SCADA_Auth_Token : DWORD;
    Partner_PLC_Heartbeat : BOOL;
    Local_PLC_ID : INT;
END_VAR
VAR_OUTPUT
    Active_PLC : INT;
    SCADA_Status : WORD;
    Security_Alert : BOOL;
END_VAR
VAR
    Is_Active_Node : BOOL;
    Heartbeat_Timer : TON;
    Valid_Token : DWORD := 16#A5A5_5A5A;
    Failover_Triggered : BOOL;
END_VAR
BEGIN
    IF SCADA_Auth_Token <> Valid_Token THEN
        Security_Alert := TRUE;
        SCADA_Status := 16#E000;
        RETURN;
    ELSE
        Security_Alert := FALSE;
    END_IF;

    Heartbeat_Timer(IN := NOT Partner_PLC_Heartbeat, PT := T#500MS);
    IF Heartbeat_Timer.Q THEN Failover_Triggered := TRUE; END_IF;

    IF Local_PLC_ID = 1 OR Failover_Triggered THEN
        Is_Active_Node := TRUE;
        Active_PLC := Local_PLC_ID;
    ELSE
        Is_Active_Node := FALSE;
        Active_PLC := 2;
    END_IF;

    IF Is_Active_Node THEN
        IF (SCADA_Cmd AND 16#0001) = 1 THEN
            SCADA_Status := 16#0001;
        ELSE
            SCADA_Status := 16#0000;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
