FUNCTION_BLOCK FB_HydroPlant_Adversarial
VAR_INPUT
    Pressure_Sensor_A : REAL;
    Pressure_Sensor_B : REAL;
    HIL_Mode_Enable : BOOL;
    HIL_Pressure_Sim : REAL;
    SCADA_Auth_Token : DWORD;
    Start_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    Drift_Alarm : BOOL;
    System_Ready : BOOL;
    Valve_SetPoint : REAL;
    SelfTest_Active : BOOL;
END_VAR
VAR
    Active_Pressure : REAL;
    Drift_Tolerance : REAL := 2.5;
    State : INT := 0;
    Test_Timer : TON;
END_VAR
BEGIN
    IF SCADA_Auth_Token <> 16#DEAD_BEEF THEN RETURN; END_IF;

    IF HIL_Mode_Enable THEN
        Active_Pressure := HIL_Pressure_Sim;
        Drift_Alarm := FALSE;
    ELSE
        IF ABS(Pressure_Sensor_A - Pressure_Sensor_B) > Drift_Tolerance THEN
            Drift_Alarm := TRUE;
            Active_Pressure := 0.0;
        ELSE
            Drift_Alarm := FALSE;
            Active_Pressure := (Pressure_Sensor_A + Pressure_Sensor_B) / 2.0;
        END_IF;
    END_IF;

    CASE State OF
        0:
            System_Ready := FALSE;
            SelfTest_Active := FALSE;
            IF Start_Cmd AND NOT Drift_Alarm THEN State := 10; END_IF;
        10:
            SelfTest_Active := TRUE;
            Valve_SetPoint := 5.0;
            Test_Timer(IN := TRUE, PT := T#2S);
            IF Test_Timer.Q THEN
                IF Active_Pressure > 10.0 THEN 
                    State := 20;
                ELSE
                    State := 99;
                END_IF;
                Test_Timer(IN := FALSE, PT := T#2S);
            END_IF;
        20:
            SelfTest_Active := FALSE;
            System_Ready := TRUE;
            Valve_SetPoint := 100.0;
