    IF RackTemp[i] > MaxTempLimit THEN
        PowerScaling := 0.0; // Over-temperature, shut down rack
    ELSIF RackTemp[i] > TargetTemp THEN
        PowerScaling := 1.0 - ((RackTemp[i] - TargetTemp) / (MaxTempLimit - TargetTemp));
    ELSE
        PowerScaling := 1.0;
