    IF AvgSOC > 0 THEN
        RackPowerCmd[i] := (TargetPower / 10.0) * (RackSOC[i] / AvgSOC) * PowerScaling;
    ELSE
        RackPowerCmd[i] := 0;
    END_IF

    // HVAC Cooling logic based on temp and power throughput
    HVAC_CoolingCmd[i] := LIMIT(0.0, ((RackTemp[i] - TargetTemp) * 2.0) + (ABS(RackPowerCmd[i]) * 0.1), 100.0);
END_FOR
