IF SystemFault THEN
    // Safe State: Disable power, max cooling
    FOR i := 1 TO 10 DO
        RackPowerCmd[i] := 0.0;
        HVAC_CoolingCmd[i] := 100.0;
    END_FOR
    RETURN;
END_IF

// Normal Operation
TotalSOC := 0;
FOR i := 1 TO 10 DO
    TotalSOC := TotalSOC + RackSOC[i];
END_FOR
AvgSOC := TotalSOC / 10.0;
TargetPower := LIMIT(-1000.0, GridPowerReq, 1000.0);

