        PowerScaling := LIMIT(0.0, 1.0 - ((RackTemp[i] - 25.0) / 20.0), 1.0);
    END_IF

    RackPowerCmd[i] := (TargetPower / 10.0) * (RackSOC[i] / MAX(AvgSOC, 0.1)) * PowerScaling;
    HVAC_CoolingCmd[i] := LIMIT(0.0, ((RackTemp[i] - 25.0) * 2.0) + (ABS(RackPowerCmd[i]) * 0.1), 100.0);
