```scl
FUNCTION_BLOCK "Microgrid_Islanding_Controller"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Grid_Lost : Bool;
      Grid_Voltage : Real;
      DG_Available : Bool;
   END_VAR
   VAR_OUTPUT 
      Main_Breaker_Open : Bool;
      DG_Start_Cmd : Bool;
      DG_Breaker_Close : Bool;
      Islanding_Mode_Active : Bool;
   END_VAR
   VAR 
      State : Int; 
      TMR_Warmup : TON_TIME;
   END_VAR
BEGIN
    IF Grid_Lost OR (Grid_Voltage < 360.0) THEN
        IF #State = 0 THEN #State := 1; END_IF;
    END_IF;
    CASE #State OF
        0:
            #Main_Breaker_Open := FALSE;
            #DG_Start_Cmd := FALSE;
            #DG_Breaker_Close := FALSE;
            #Islanding_Mode_Active := FALSE;
        1:
            #Main_Breaker_Open := TRUE;
            IF #DG_Available THEN
                #DG_Start_Cmd := TRUE;
                #State := 2;
            END_IF;
        2:
            #Main_Breaker_Open := TRUE;
            #DG_Start_Cmd := TRUE;
            #TMR_Warmup(IN:=TRUE, PT:=T#10s);
            IF #TMR_Warmup.Q THEN
                #DG_Breaker_Close := TRUE;
                #State := 3;
            END_IF;
        3:
            #Islanding_Mode_Active := TRUE;
    END_CASE;
    IF #State <> 2 THEN
        #TMR_Warmup(IN:=FALSE, PT:=T#10s);
    END_IF;
END_FUNCTION_BLOCK
