    V_Actual := V_Secondary;
    // Adversarial Resilience: Sensor Drift Check
    IF ABS(V_Secondary - V_Secondary_Redundant) > Drift_Tolerance THEN
        Sensor_Fault := TRUE;
    ELSE
        Sensor_Fault := FALSE;
    END_IF;
END_IF;

// Distance Protection
IF Sensor_Fault THEN
    Trip_Breaker := TRUE; // Fail-safe on sensor anomaly
ELSIF I_Line > 0.1 THEN
    Z_Measured := V_Actual / I_Line;
    Trip_Breaker := (Z_Measured < 10.0);
ELSE
    Trip_Breaker := FALSE;
END_IF;

// AVR
Timer_AVR(IN := (ABS(V_Actual - V_Setpoint) > Deadband) AND NOT Trip_Breaker AND NOT Sensor_Fault, PT := T#5S);
Raise_Tap := FALSE; 
Lower_Tap := FALSE;

IF Timer_AVR.Q AND NOT Remote_Override THEN
    IF V_Actual < V_Setpoint THEN 
        Raise_Tap := TRUE; 
    ELSE 
        Lower_Tap := TRUE; 
    END_IF;
    Timer_AVR(IN := FALSE);
END_IF;
