    CapperMotor : Bool;
    Ready : Bool;
    FaultID : Int;
END_VAR
VAR
    FillingState : Int;
    FaultActive : Bool;
    TimeoutTimer : TON;
END_VAR

BEGIN
    // Diagnostics
    IF PN_Status <> 16#0000 THEN
        FaultActive := TRUE;
        FaultID := 1; // PN Error
    ELSIF TimeoutTimer.Q THEN
        FaultActive := TRUE;
        FaultID := 2; // Process Timeout
    END_IF;

    IF FaultActive THEN
        FillValve := FALSE;
        CO2Valve := FALSE;
        ConveyorMotor := FALSE;
        CapperMotor := FALSE;
        Ready := FALSE;
        IF Reset AND PN_Status = 16#0000 THEN
            FaultActive := FALSE;
            FaultID := 0;
            FillingState := 0;
        END_IF;
        RETURN;
    END_IF;

    IF Stop THEN
        FillingState := 0;
        RETURN;
    END_IF;

    CASE FillingState OF
        0: // Idle
            ConveyorMotor := Start;
            Ready := TRUE;
            TimeoutTimer(IN:=FALSE, PT:=T#0s);
            IF BottlePresent THEN
                ConveyorMotor := FALSE;
                FillingState := 1;
            END_IF;
        1: // Carbonation
            Ready := FALSE;
            TimeoutTimer(IN:=TRUE, PT:=T#5s);
            IF CarbonationPressure < TargetPressure THEN
                CO2Valve := TRUE;
            ELSE
                CO2Valve := FALSE;
                FillingState := 2;
            END_IF;
        2: // Filling
            TimeoutTimer(IN:=TRUE, PT:=T#10s);
            IF FillLevelSensor < TargetLevel THEN
                FillValve := TRUE;
            ELSE
                FillValve := FALSE;
                FillingState := 3;
            END_IF;
        3: // Capping
            TimeoutTimer(IN:=TRUE, PT:=T#3s);
            IF CapPresent AND ActualTorque < TargetTorque THEN
                CapperMotor := TRUE;
            ELSE
                CapperMotor := FALSE;
                FillingState := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
