FUNCTION_BLOCK "BeverageFiller_Adversarial"
VAR_INPUT
    UserRole : Int;
    HIL_Mode : Bool;
    HIL_FillLevelSim : Real;
    FillLevelSensor : Real; 
    PrevLevelSensor : Real;
    StartTest : Bool;
    Stop : Bool;
    CarbonationPressure : Real; 
    TargetLevel : Real;
    TargetPressure : Real;
    TargetTorque : Real;
    ActualTorque : Real;
END_VAR
VAR_OUTPUT
    FillValve : Bool;
    CO2Valve : Bool;
    CapperMotor : Bool;
    SystemState : Int;
    FaultID : Int;
    SelfTestPassed : Bool;
END_VAR
VAR
    FillingState : Int;
    DriftDetected : Bool;
    ActiveFillLevel : Real;
END_VAR

BEGIN
    // HIL Digital Twin Synchronization
    IF HIL_Mode THEN
        ActiveFillLevel := HIL_FillLevelSim;
    ELSE
        ActiveFillLevel := FillLevelSensor;
    END_IF;

    // Sensor Drift Detection (Adversarial)
    IF ABS(FillLevelSensor - PrevLevelSensor) > 5.0 THEN
        DriftDetected := TRUE;
        FaultID := 15; // Sensor Drift
    END_IF;

    // Startup Self-Test
    IF StartTest AND NOT SelfTestPassed THEN
        SystemState := 99; // Test mode
        CO2Valve := TRUE; // Pulse valves
        FillValve := TRUE;
        SelfTestPassed := TRUE;
        RETURN;
    END_IF;

    IF DriftDetected OR Stop THEN
        FillValve := FALSE;
        CO2Valve := FALSE;
        SystemState := 0;
        RETURN;
    END_IF;

    SystemState := FillingState;

    CASE FillingState OF
        0: // Idle
            IF StartTest THEN
                FillingState := 1;
            END_IF;
        1: // Carbonation
            IF CarbonationPressure < TargetPressure THEN
                CO2Valve := TRUE;
            ELSE
                CO2Valve := FALSE;
                FillingState := 2;
            END_IF;
        2: // Filling
            IF ActiveFillLevel < TargetLevel THEN
                FillValve := TRUE;
            ELSE
                FillValve := FALSE;
                FillingState := 3;
            END_IF;
        3: // Capping
            IF ActualTorque < TargetTorque THEN
                CapperMotor := TRUE;
            ELSE
                CapperMotor := FALSE;
                FillingState := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
