    fH2O2_Temp_SensorB AT %I* : REAL;
    fH2O2_Temp_Voted : REAL;
    bDriftDetected : BOOL;
    bHilModeActive : BOOL;
    {attribute 'TcNetId' := '127.0.0.1.1.1'}
    fDigitalTwin_H2O2_Temp AT %Q* : REAL;
    iDigitalTwin_State AT %Q* : INT;
    bSelfTestPassed : BOOL;
