        TempError := TargetTemp - ActualTemp;
        IF TempError > 0.0 THEN
            HeaterOutput := TempError * 5.0;
            CoolerOutput := 0.0;
        ELSE
            CoolerOutput := ABS(TempError) * 5.0;
            HeaterOutput := 0.0;
        END_IF;
        BlowerVelocity := 50.0 + (BeltSpeed * 0.5) - (TempError * 2.0);
        IF BlowerVelocity > 100.0 THEN BlowerVelocity := 100.0; END_IF;
        IF BlowerVelocity < 10.0 THEN BlowerVelocity := 10.0; END_IF;
    ELSE
        HeaterOutput := 0.0;
        CoolerOutput := 0.0;
        BlowerVelocity := 0.0;
    END_IF;
END_FUNCTION_BLOCK
