FUNCTION_BLOCK FB_EnroberReasoning
VAR_INPUT
    Enable : BOOL;
    UserRole : INT;
    TempPrimary : REAL;
    TempRedundant : REAL;
    BeltSpeed : REAL;
    MotorOverload : BOOL;
END_VAR
VAR_OUTPUT
    HeaterOutput : REAL;
    BlowerVelocity : REAL;
    FaultCode : INT;
    SCADA_Data : "UDT_SCADA_OEE";
END_VAR
VAR
    ActiveTemp : REAL;
    SensorFail : BOOL;
END_VAR
BEGIN
    // Security Check
    IF UserRole < 1 THEN
        FaultCode := 99;
        RETURN;
    END_IF;

    // Sensor Failover
    IF ABS(TempPrimary - TempRedundant) > 5.0 THEN
        SensorFail := True;
        ActiveTemp := TempRedundant;
        FaultCode := 3;
    ELSE
        SensorFail := False;
        ActiveTemp := TempPrimary;
    END_IF;

    // Control Logic
    IF Enable AND NOT MotorOverload AND (UserRole >= 1) THEN
        SCADA_Data.RunTime := SCADA_Data.RunTime + 1;
        HeaterOutput := LIMIT(MN:=0.0, IN:=((45.0 - ActiveTemp) * 5.0), MX:=100.0);
        BlowerVelocity := LIMIT(MN:=10.0, IN:=(BeltSpeed * 1.2), MX:=100.0);
        SCADA_Data.QualityYield := 99.5;
    ELSE
        SCADA_Data.Downtime := SCADA_Data.Downtime + 1;
        HeaterOutput := 0.0;
        BlowerVelocity := 0.0;
        IF MotorOverload THEN FaultCode := 1; END_IF;
    END_IF;
END_FUNCTION_BLOCK
