```pascal
FUNCTION_BLOCK FB_EnroberAdversarial
VAR_INPUT
    Start : BOOL;
    TempSensors : ARRAY[0..2] OF REAL;
    HIL_PredictionTemp : REAL;
    BeltSpeed : REAL;
END_VAR
VAR_OUTPUT
    HeaterCmd : REAL;
    BlowerCmd : REAL;
    SelfTestPassed : BOOL;
    DriftAlarm : BOOL;
END_VAR
VAR
    State : INT := 0;
    TestTimer : INT;
    AvgTemp : REAL;
    MaxDiff : REAL;
END_VAR
BEGIN
    // Sensor Drift Detection
    MaxDiff := ABS(TempSensors[0] - TempSensors[1]);
    IF ABS(TempSensors[1] - TempSensors[2]) > MaxDiff THEN MaxDiff := ABS(TempSensors[1] - TempSensors[2]); END_IF;
    IF ABS(TempSensors[0] - TempSensors[2]) > MaxDiff THEN MaxDiff := ABS(TempSensors[0] - TempSensors[2]); END_IF;
    DriftAlarm := (MaxDiff > 2.5);
    AvgTemp := (TempSensors[0] + TempSensors[1] + TempSensors[2]) / 3.0;

    CASE State OF
        0: // Off
            SelfTestPassed := False;
            TestTimer := 0;
            HeaterCmd := 0.0;
            BlowerCmd := 0.0;
            IF Start THEN State := 1; END_IF;

        1: // Self-Test
            TestTimer := TestTimer + 1;
            HeaterCmd := 10.0; 
            BlowerCmd := 100.0; 
            IF (TestTimer > 100) THEN
                IF NOT DriftAlarm THEN
                    SelfTestPassed := True;
                    State := 2;
                ELSE
                    State := 0; 
                END_IF;
            END_IF;

        2: // Run with HIL
            IF NOT Start THEN State := 0; END_IF;
            HeaterCmd := LIMIT(MN:=0.0, IN:=((45.0 - AvgTemp) * 4.0) + (HIL_PredictionTemp * 0.5), MX:=100.0);
            BlowerCmd := LIMIT(MN:=10.0, IN:=(BeltSpeed * 1.5), MX:=100.0);
    END_CASE;
END_FUNCTION_BLOCK
