ELSE
    sFaultMsg := 'System OK';
END_IF

// Critical Safety Interlock
bTempOK := (rHoldingTubeTemp >= rPasteurizationTemp) AND NOT bSensorFault AND bEtherCAT_OK;
fbTimer(IN := bTempOK AND bFlowSwitch, PT := tHoldingTime);

IF fbTimer.Q THEN
    bFlowDiversionValve := TRUE;
ELSE
    bFlowDiversionValve := FALSE; // Fail-safe state
END_IF

// PID Loops (Only execute if no sensor fault)
IF NOT bSensorFault THEN
    fbHeatingPID(fSetpointValue := rHeatingSetpoint, fActualValue := rHeatingSectTemp, fCtrlOutput => rSteamValveCmd);
    fbCoolingPID(fSetpointValue := rCoolingSetpoint, fActualValue := rCoolingSectTemp, fCtrlOutput => rChilledWaterValveCmd);
