    #Sum := 0.0;
    #DO_History[#History_Index] := #DO_PV;
    FOR #i := 1 TO 10 DO
        #Sum := #Sum + #DO_History[#i];
    END_FOR;
    #Moving_Avg := #Sum / 10.0;

    #History_Index := #History_Index + 1;
    IF #History_Index > 10 THEN #History_Index := 1; END_IF;

    // Compare statistical average against HIL twin for adversarial drift detection
    IF #HIL_Mode_Active THEN
        #DO_Drift_Alarm := ABS(#Moving_Avg - #HIL_Simulated_DO) > 5.0;
