        #DO_Drift_Alarm := ABS(#DO_PV - #Moving_Avg) > 8.0;
    END_IF;

    // 2. Automated Self-Test Routine prior to Batch
    IF #Batch_Start_Req AND NOT #Batch_Running THEN
        CASE #Self_Test_Step OF
            0: // Initialize physical equipment test
                #Self_Test_Passed := FALSE;
                #Agitator_Speed_SP := 10.0; // Command safe low speed
                #Self_Test_Step := 1;
            1: // Allow process to stabilize
                #Test_Timer(IN := TRUE, PT := T#5s);
                IF #Test_Timer.Q THEN
                    #Test_Timer(IN := FALSE, PT := T#5s); // Reset for next use
                    #Self_Test_Step := 2;
                END_IF;
            2: // Evaluate sensor integrity before launch
                IF NOT #DO_Drift_Alarm THEN
                    #Self_Test_Passed := TRUE;
                    #Batch_Running := TRUE;
                    #Self_Test_Step := 0;
                ELSE
                    #Self_Test_Passed := FALSE;
                    #Batch_Running := FALSE;
                    #Self_Test_Step := 0; // Abort launch
                END_IF;
        END_CASE;
    END_IF;

    // 3. Main Run State (Simplified for adversarial scope)
    IF #Batch_Running THEN
        IF #HIL_Mode_Active THEN
            // Synchronize with Digital Twin simulated response
            #Agitator_Speed_SP := 150.0; 
        ELSE
            // Normal local cascade loop logic
            #Agitator_Speed_SP := 250.0; 
        END_IF;
    ELSIF #Self_Test_Step = 0 THEN
        // Default rest state
        #Agitator_Speed_SP := 0.0;
    END_IF;

END_FUNCTION_BLOCK
