PROGRAM MAIN
VAR
    bStartCIP : BOOL;
    nStep : INT;
    fConductivity AT %I* : REAL;
    fPumpSuctionPressure AT %I* : REAL;
    fActualTemp AT %I* : REAL;
    bSupplyPumpRun AT %Q* : BOOL;
    bReturnPumpRun AT %Q* : BOOL;
    bWaterValve AT %Q* : BOOL;
    bCausticValve AT %Q* : BOOL;
    fSteamValvePos AT %Q* : INT;
    nEcMasterState AT %I* : UINT;
    bEcSlaveError AT %I* : BOOL;
    nWcState AT %I* : BOOL;
    bGlobalFault : BOOL;
    bPumpCavitationFault : BOOL;
    bSensorRangeFault : BOOL;
    bCommFault : BOOL;
    fbPID : FB_BasicPID;
    fSetpointTemp : REAL;
    fSteamPIDOut : LREAL;
    bHeatEnable : BOOL;
    tStepTimer : TON;
END_VAR

bCommFault := (nEcMasterState <> 8) OR bEcSlaveError OR nWcState;
bSensorRangeFault := (fConductivity < 0.0 OR fConductivity > 200.0) OR (fActualTemp < 0.0 OR fActualTemp > 150.0);
bPumpCavitationFault := (bSupplyPumpRun OR bReturnPumpRun) AND (fPumpSuctionPressure < 0.2);

bGlobalFault := bCommFault OR bSensorRangeFault OR bPumpCavitationFault;

IF bGlobalFault THEN
    bSupplyPumpRun := FALSE;
    bReturnPumpRun := FALSE;
    bHeatEnable := FALSE;
    fSteamValvePos := 0;
    nStep := 999;
END_IF

fbPID(
    fSetpointValue := fSetpointTemp,
    fActualValue := fActualTemp,
    bReset := NOT bHeatEnable OR bGlobalFault,
    fCtrlCycleTime := 0.1,
    fKp := 2.0, fTn := 15.0,
    fMaxCtrlOutput := 32767.0, fMinCtrlOutput := 0.0,
    fCtrlOutput => fSteamPIDOut
);
IF bHeatEnable AND NOT bGlobalFault THEN
    fSteamValvePos := LREAL_TO_INT(fSteamPIDOut);
ELSE
    fSteamValvePos := 0;
END_IF

CASE nStep OF
    0:
        IF bStartCIP AND NOT bGlobalFault THEN nStep := 10; END_IF
    10:
        bWaterValve := TRUE;
        bSupplyPumpRun := TRUE; bReturnPumpRun := TRUE;
        tStepTimer(IN:=TRUE, PT:=T#5M);
        IF tStepTimer.Q THEN
            tStepTimer(IN:=FALSE); nStep := 0; bWaterValve := FALSE;
            bSupplyPumpRun := FALSE; bReturnPumpRun := FALSE;
        END_IF
    999:
        IF NOT bGlobalFault THEN nStep := 0; END_IF
END_CASE

{attribute 'qualified_only'}
TYPE E_UserRole : (Operator := 0, Maintenance := 1, Admin := 2); END_TYPE

TYPE ST_SCADA_Data :
STRUCT
    {attribute 'OPC.UA.DA' := '1'} bStartCIP : BOOL;
    {attribute 'OPC.UA.DA' := '1'} nActiveStep : INT;
    {attribute 'OPC.UA.DA' := '1'} bSystemFault : BOOL;
    {attribute 'OPC.UA.DA' := '1'} eCurrentUserRole : E_UserRole;
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
    stSCADA : ST_SCADA_Data;
    nStep : INT;
    bSupplyPump1Run AT %Q* : BOOL;
    bSupplyPump2Run AT %Q* : BOOL;
    bPump1Fault : BOOL;
    bPump2Fault : BOOL;
    nActivePump : INT := 1;
    fSuctionPressure AT %I* : REAL;
    sUsername : STRING;
    sPassword : STRING;
    bLoginReq : BOOL;
    nEcMasterState AT %I* : UINT;
    bCavitationAlarm : BOOL;
    bCommFault : BOOL;
    tStepTimer : TON;
END_VAR

IF bLoginReq THEN
    IF sUsername = 'Admin' AND sPassword = 'SecureAdmin123!' THEN
        stSCADA.eCurrentUserRole := E_UserRole.Admin;
    ELSIF sUsername = 'Oper' AND sPassword = 'OperPassword' THEN
        stSCADA.eCurrentUserRole := E_UserRole.Operator;
    END_IF
    bLoginReq := FALSE;
END_IF

bCavitationAlarm := fSuctionPressure < 0.2 AND (bSupplyPump1Run OR bSupplyPump2Run);
IF bCavitationAlarm THEN
    IF nActivePump = 1 THEN bPump1Fault := TRUE; nActivePump := 2;
    ELSE bPump2Fault := TRUE; nActivePump := 1; END_IF
END_IF

IF stSCADA.bStartCIP AND (stSCADA.eCurrentUserRole < E_UserRole.Operator) THEN
    stSCADA.bStartCIP := FALSE;
END_IF

bCommFault := nEcMasterState <> 8;
stSCADA.bSystemFault := bCommFault OR (bPump1Fault AND bPump2Fault);

CASE nStep OF
    0:
        bSupplyPump1Run := FALSE; bSupplyPump2Run := FALSE;
        IF stSCADA.bStartCIP AND NOT stSCADA.bSystemFault THEN nStep := 10; END_IF
    10:
        IF nActivePump = 1 AND NOT bPump1Fault THEN
            bSupplyPump1Run := TRUE; bSupplyPump2Run := FALSE;
        ELSIF nActivePump = 2 AND NOT bPump2Fault THEN
            bSupplyPump1Run := FALSE; bSupplyPump2Run := TRUE;
        ELSE
            nStep := 999;
        END_IF
        tStepTimer(IN:=TRUE, PT:=T#10M);
        IF tStepTimer.Q THEN
            tStepTimer(IN:=FALSE); nStep := 0; stSCADA.bStartCIP := FALSE;
        END_IF
    999:
        bSupplyPump1Run := FALSE; bSupplyPump2Run := FALSE;
END_CASE
stSCADA.nActiveStep := nStep;

TYPE ST_SCADA_Data :
STRUCT
    {attribute 'OPC.UA.DA' := '1'} bStartCIP : BOOL;
    {attribute 'OPC.UA.DA' := '1'} nActiveStep : INT;
    {attribute 'OPC.UA.DA' := '1'} bDriftAlarm : BOOL;
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
    stSCADA : ST_SCADA_Data;
    nStep : INT;
    bValveCmd AT %Q* : BOOL;
    bValveFbk AT %I* : BOOL;
    fConductivityRaw AT %I* : REAL;
    bSupplyPumpRun AT %Q* : BOOL;
    arrCondBuffer : ARRAY[1..100] OF REAL;
    nBufferIdx : INT := 1;
    fCondMovingAvg : REAL;
    fCondSum : REAL;
    fMaxDriftAllowed : REAL := 2.5;
    bSyncDigitalTwin AT %I* : BOOL;
    fSimulatedConductivity AT %I* : REAL;
    fRealConductivity : REAL;
    fModelError : REAL;
    tTestTimer : TON;
    bPreFlightDone : BOOL;
    bPreFlightFail : BOOL;
    i : INT;
END_VAR

IF bSyncDigitalTwin THEN
    fRealConductivity := fSimulatedConductivity;
ELSE
    fRealConductivity := fConductivityRaw;
    fModelError := ABS(fConductivityRaw - fSimulatedConductivity);
END_IF

arrCondBuffer[nBufferIdx] := fRealConductivity;
nBufferIdx := nBufferIdx + 1;
IF nBufferIdx > 100 THEN nBufferIdx := 1; END_IF

fCondSum := 0;
FOR i := 1 TO 100 DO fCondSum := fCondSum + arrCondBuffer[i]; END_FOR
fCondMovingAvg := fCondSum / 100.0;

IF ABS(fRealConductivity - fCondMovingAvg) > fMaxDriftAllowed THEN
    stSCADA.bDriftAlarm := TRUE;
END_IF

CASE nStep OF
    0:
        IF stSCADA.bStartCIP THEN
            bPreFlightDone := FALSE; bPreFlightFail := FALSE; nStep := 5;
        END_IF
    5:
        bValveCmd := TRUE;
        tTestTimer(IN:=TRUE, PT:=T#2S);
        IF tTestTimer.Q THEN
            tTestTimer(IN:=FALSE);
            IF bValveFbk THEN
                bValveCmd := FALSE; bPreFlightDone := TRUE; nStep := 10;
            ELSE
                bValveCmd := FALSE; bPreFlightFail := TRUE; stSCADA.bStartCIP := FALSE; nStep := 999;
            END_IF
        END_IF
    10:
        bSupplyPumpRun := TRUE;
        nStep := 0;
    999:
        bSupplyPumpRun := FALSE;
END_CASE
stSCADA.nActiveStep := nStep;

