FUNCTION_BLOCK "TBM_Cyber_SCADA_Control"
VERSION : 0.4
   VAR_INPUT
      SCADA_Data : "SCADA_Interface";
      Act_Thrust_Primary : Real;
      Act_Thrust_Secondary : Real;
   END_VAR

   VAR_OUTPUT
      Thrust_Valve_Cmd : Real;
      Active_Sensor_ID : Int;
      Security_Alert : Bool;
   END_VAR

   VAR
      Validated_Setpoint : Real;
      Prev_Heartbeat : Int;
      Comm_Loss_Timer : Int;
   END_VAR

   VAR_CONSTANT
      VALID_AUTH_TOKEN : DInt := 123456789;
   END_VAR

BEGIN
    // IEC 62443 Cyber Security: Command Validation and Auth
    IF #SCADA_Data.Auth_Token <> #VALID_AUTH_TOKEN THEN
        #Security_Alert := TRUE;
        #Thrust_Valve_Cmd := 0.0;
        RETURN;
    ELSE
        #Security_Alert := FALSE;
    END_IF;

    // Heartbeat check for SCADA comms loss
    IF #SCADA_Data.Heartbeat = #Prev_Heartbeat THEN
        #Comm_Loss_Timer := #Comm_Loss_Timer + 1;
    ELSE
        #Comm_Loss_Timer := 0;
    END_IF;
    #Prev_Heartbeat := #SCADA_Data.Heartbeat;

    IF #Comm_Loss_Timer > 1000 THEN
        #Thrust_Valve_Cmd := 0.0; // Safe state
        RETURN;
    END_IF;

    // Setpoint bounds validation
    IF #SCADA_Data.Setpoint_Thrust >= 0.0 AND #SCADA_Data.Setpoint_Thrust <= 350.0 THEN
        #Validated_Setpoint := #SCADA_Data.Setpoint_Thrust;
    ELSE
        #Validated_Setpoint := 0.0;
    END_IF;

    // Redundant Sensor Failover
    IF ABS(#Act_Thrust_Primary - #Act_Thrust_Secondary) > 20.0 THEN
        // Sensor discrepancy - use secondary if primary seems frozen or out of bounds (simplified logic)
        IF #Act_Thrust_Primary < 0.0 THEN
            #Active_Sensor_ID := 2;
        ELSE
            #Active_Sensor_ID := 1;
        END_IF;
    ELSE
        #Active_Sensor_ID := 1;
    END_IF;

    // Basic Control Loop
    IF #Active_Sensor_ID = 1 THEN
        #Thrust_Valve_Cmd := (#Validated_Setpoint - #Act_Thrust_Primary) * 0.5;
    ELSE
        #Thrust_Valve_Cmd := (#Validated_Setpoint - #Act_Thrust_Secondary) * 0.5;
    END_IF;

    IF #Thrust_Valve_Cmd < 0.0 THEN #Thrust_Valve_Cmd := 0.0; END_IF;
    IF #Thrust_Valve_Cmd > 100.0 THEN #Thrust_Valve_Cmd := 100.0; END_IF;
END_FUNCTION_BLOCK
