PROGRAM PileDriver_M2
VAR
    State : INT := 0; // 0=Init, 1=Ready, 2=Running, 3=Fault

    // Ethernet/IP Data Mapping
    EIP_Input_Data : ARRAY[0..15] OF DINT;
    EIP_Output_Data : ARRAY[0..15] OF DINT;

    // Equipment
    Hammer_Valve : BOOL;
    Winch_Drive_Ref : REAL;
    HPU_Pump_Run : BOOL;

    // Process Values (From EIP)
    Soil_Resistance : REAL;
    HPU_Pressure : REAL;
    HPU_Temp : REAL;
    Comm_Status : DINT;

    // Diagnostics
    Alarm_Word : DINT := 0;
    // Bit 0 = HPU Low Pressure
    // Bit 1 = HPU Over Temp
    // Bit 2 = Comm Failure
    // Bit 3 = E-Stop

    Reset_Alarms : BOOL;
END_VAR

// Unpack EIP Inputs
Soil_Resistance := DINT_TO_REAL(EIP_Input_Data[0]) / 100.0;
HPU_Pressure := DINT_TO_REAL(EIP_Input_Data[1]) / 10.0;
HPU_Temp := DINT_TO_REAL(EIP_Input_Data[2]) / 10.0;
Comm_Status := EIP_Input_Data[15];

// Fault Diagnostics
Alarm_Word.0 := (State = 2) AND (HPU_Pressure < 100.0);
Alarm_Word.1 := (HPU_Temp > 75.0);
Alarm_Word.2 := (Comm_Status <> 1); // 1 = OK
Alarm_Word.3 := (EIP_Input_Data[3].0 = 0); // E-Stop is NC

IF Alarm_Word > 0 THEN
    State := 3; // Fault State
END_IF;

IF Reset_Alarms AND Alarm_Word = 0 THEN
    State := 0;
END_IF;

// State Machine
CASE State OF
    0: // Init
        HPU_Pump_Run := FALSE;
        Hammer_Valve := FALSE;
        Winch_Drive_Ref := 0.0;
        IF Comm_Status = 1 AND Alarm_Word = 0 THEN
            State := 1;
        END_IF;

    1: // Ready
        IF EIP_Input_Data[4].0 THEN // Start Cmd
            State := 2;
        END_IF;

    2: // Running
        HPU_Pump_Run := TRUE;
        IF HPU_Pressure > 150.0 THEN
            Hammer_Valve := NOT Hammer_Valve; // Oscillation logic placeholder
            Winch_Drive_Ref := 50.0;
        ELSE
            Hammer_Valve := FALSE;
            Winch_Drive_Ref := 0.0;
        END_IF;

        IF EIP_Input_Data[4].1 THEN // Stop Cmd
            State := 1;
        END_IF;

    3: // Fault
        HPU_Pump_Run := FALSE;
        Hammer_Valve := FALSE;
        Winch_Drive_Ref := 0.0;
END_CASE;

// Pack EIP Outputs
EIP_Output_Data[0] := REAL_TO_DINT(Winch_Drive_Ref * 100.0);
EIP_Output_Data[1].0 := Hammer_Valve;
EIP_Output_Data[1].1 := HPU_Pump_Run;
EIP_Output_Data[2] := Alarm_Word;
EIP_Output_Data[15] := State;

END_PROGRAM
