PROGRAM MAIN
VAR
    bEStop : BOOL;

    // Block System
    bZone1Clear AT %I* : BOOL;
    bZone2Clear AT %I* : BOOL;

    // EtherCAT Diagnostics
    bEcSlaveError AT %I* : BOOL;
    nEcMasterState AT %I* : UINT;

    // Drives and Brakes
    stLSM_DriveIn AT %I* : ST_DriveIn;
    stLSM_DriveOut AT %Q* : ST_DriveOut;
    bStationBrake AT %Q* : BOOL; // FALSE = Engaged
    bMidCourseBrake AT %Q* : BOOL;

    // Diagnostics
    bSystemFault : BOOL;
    nErrorCode : INT;
END_VAR

// Diagnostic Check
IF nEcMasterState <> 8 OR bEcSlaveError THEN // 8 = OP State
    bSystemFault := TRUE;
    nErrorCode := 1001; // EtherCAT Network Fault
END_IF
IF stLSM_DriveIn.bError THEN
    bSystemFault := TRUE;
    nErrorCode := 1002; // Drive Fault
END_IF

// Fail-safe on fault
IF bEStop OR bSystemFault THEN
    stLSM_DriveOut.bEnable := FALSE;
    stLSM_DriveOut.fSpeedSetpoint := 0.0;
    bStationBrake := FALSE; 
    bMidCourseBrake := FALSE;
    RETURN;
END_IF

// Launch sequence
IF bZone1Clear AND bZone2Clear AND stLSM_DriveIn.bReady THEN
    bStationBrake := TRUE; // Disengage
    stLSM_DriveOut.bEnable := TRUE;
    stLSM_DriveOut.fSpeedSetpoint := 120.0;
ELSE
    stLSM_DriveOut.bEnable := FALSE;
END_IF

PROGRAM MAIN
VAR
    // Access Control (IEC 62443)
    nAccessLevel : INT := 0; // 0=None, 1=Operator, 2=Admin
    bScadaOverride : BOOL;

    // Redundancy
    bHeartbeatRemote AT %I* : BOOL;
    bIsActiveNode : BOOL := TRUE;
    fbTonHeartbeat : TON;

    // Block System & Faults
    bZone1Clear AT %I* : BOOL;
    bEStop AT %I* : BOOL;
    bSystemFault : BOOL;

    // Outputs
    stLSM_DriveOut AT %Q* : ST_DriveOut;
    bStationBrake AT %Q* : BOOL; // FALSE=Engage

    // OPC UA Data
    fTrainSpeed AT %I* : REAL;
    fScadaTargetSpeed : REAL := 120.0;
END_VAR

// Redundancy Check
fbTonHeartbeat(IN:= NOT bHeartbeatRemote, PT:= T#500MS);
IF fbTonHeartbeat.Q THEN
    bIsActiveNode := TRUE; // Take over if remote dies
END_IF

IF NOT bIsActiveNode THEN
    RETURN; // Standby mode
END_IF

// Access Control
IF nAccessLevel < 1 THEN
    bSystemFault := TRUE; // Unauthorized operation
END_IF

// Fail-safe
IF bEStop OR bSystemFault THEN
    stLSM_DriveOut.bEnable := FALSE;
    bStationBrake := FALSE;
    RETURN;
END_IF

// Operation
IF bZone1Clear AND nAccessLevel >= 1 THEN
    bStationBrake := TRUE;
    stLSM_DriveOut.bEnable := TRUE;
    IF bScadaOverride AND nAccessLevel = 2 THEN
        stLSM_DriveOut.fSpeedSetpoint := fScadaTargetSpeed;
    ELSE
        stLSM_DriveOut.fSpeedSetpoint := 120.0;
    END_IF
END_IF

PROGRAM MAIN
VAR
    bEStop : BOOL;
    bSystemFault : BOOL;

    // Modes
    bHilMode : BOOL; // Hardware-in-loop mode
    bSelfTestActive : BOOL := TRUE;
    bSelfTestPassed : BOOL;

    // Sensors & Drift Detection
    fSpeedSensor1 AT %I* : REAL;
    fSpeedSensor2 AT %I* : REAL;
    fSimulatedSpeed : REAL; // For HIL

    fCurrentSpeed : REAL;
    fSpeedTolerance : REAL := 5.0; // max allowed drift

    // Outputs
    stLSM_DriveOut AT %Q* : ST_DriveOut;
    bMagneticBrake AT %Q* : BOOL;
END_VAR

// HIL Digital Twin Sync
IF bHilMode THEN
    fCurrentSpeed := fSimulatedSpeed;
ELSE
    // Sensor Drift Detection (Adversarial conditions)
    IF ABS(fSpeedSensor1 - fSpeedSensor2) > fSpeedTolerance THEN
        bSystemFault := TRUE; // Sensors diverging
    ELSE
        fCurrentSpeed := (fSpeedSensor1 + fSpeedSensor2) / 2.0;
    END_IF
END_IF

// Self-Test Routine
IF bSelfTestActive THEN
    bMagneticBrake := FALSE; // Engage brake
    stLSM_DriveOut.bEnable := TRUE;
    stLSM_DriveOut.fSpeedSetpoint := 5.0; // Apply small force

    // If we move while brake is applied, brake failed
    IF fCurrentSpeed > 0.1 THEN
        bSystemFault := TRUE;
        bSelfTestActive := FALSE;
    ELSE
        bSelfTestPassed := TRUE;
        stLSM_DriveOut.bEnable := FALSE;
        bSelfTestActive := FALSE;
    END_IF
END_IF

// Failsafe
IF bEStop OR bSystemFault THEN
    stLSM_DriveOut.bEnable := FALSE;
    bMagneticBrake := FALSE; // Engage fail-safe
    RETURN;
END_IF

// Normal Launch
IF bSelfTestPassed AND NOT bSystemFault THEN
    bMagneticBrake := TRUE; // Disengage
    stLSM_DriveOut.bEnable := TRUE;
    stLSM_DriveOut.fSpeedSetpoint := 120.0;
END_IF

FUNCTION_BLOCK FB_CNC_Mill_Base
VAR_INPUT
    Enable : BOOL;
    SpindleTemp : REAL;
    TempSetpoint : REAL;
    ToolIndexCmd : INT;
    MagEncoderPos : INT;
END_VAR
VAR_OUTPUT
    ChillerPumpOn : BOOL;
    ChillerFanOn : BOOL;
    MagMotorFwd : BOOL;
    MagMotorRev : BOOL;
    ToolInPosition : BOOL;
END_VAR
VAR
    TempHysteresis : REAL := 2.0;
    IndexTolerance : INT := 5;
END_VAR
BEGIN
    // Spindle Chiller Control
    IF Enable THEN
        IF SpindleTemp > (TempSetpoint + TempHysteresis) THEN
            ChillerPumpOn := TRUE;
            ChillerFanOn := TRUE;
        ELSIF SpindleTemp <= TempSetpoint THEN
            ChillerPumpOn := FALSE;
            ChillerFanOn := FALSE;
        END_IF;
    ELSE
        ChillerPumpOn := FALSE;
        ChillerFanOn := FALSE;
    END_IF;

    // Tool Mag Indexer Control
    IF Enable AND (ToolIndexCmd > 0) THEN
        IF ABS(MagEncoderPos - ToolIndexCmd) <= IndexTolerance THEN
            MagMotorFwd := FALSE;
            MagMotorRev := FALSE;
            ToolInPosition := TRUE;
        ELSIF MagEncoderPos < ToolIndexCmd THEN
            MagMotorFwd := TRUE;
            MagMotorRev := FALSE;
            ToolInPosition := FALSE;
        ELSE
            MagMotorFwd := FALSE;
            MagMotorRev := TRUE;
            ToolInPosition := FALSE;
        END_IF;
    ELSE
        MagMotorFwd := FALSE;
        MagMotorRev := FALSE;
        ToolInPosition := FALSE;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_CNC_Mill_Depth
VAR_INPUT
    Enable : BOOL;
    SpindleTemp : REAL;
    TempSetpoint : REAL;
    ToolIndexCmd : INT;
    MagEncoderPos : INT;
    CoolantPressure : REAL;
    CoolantFlow : REAL;
END_VAR
VAR_OUTPUT
    ChillerPumpOn : BOOL;
    ChillerFanOn : BOOL;
    MagMotorFwd : BOOL;
    MagMotorRev : BOOL;
    ToolInPosition : BOOL;
    CoolantPumpOn : BOOL;
    CoolantAlarm : BOOL;
END_VAR
VAR
    ReqPressure : REAL;
    ReqFlow : REAL;
END_VAR
BEGIN
    // Dynamic Coolant Setpoints based on Tool ID
    CASE ToolIndexCmd OF
        1..10:  // Heavy Roughing Tools
            ReqPressure := 50.0;
            ReqFlow := 20.0;
        11..20: // Finishing Tools
            ReqPressure := 20.0;
            ReqFlow := 10.0;
    ELSE
        ReqPressure := 10.0;
        ReqFlow := 5.0;
    END_CASE;

    // Coolant Subsystem
    IF Enable AND ToolInPosition THEN
        CoolantPumpOn := TRUE;
        IF CoolantPressure < (ReqPressure * 0.8) OR CoolantFlow < (ReqFlow * 0.8) THEN
            CoolantAlarm := TRUE;
        ELSE
            CoolantAlarm := FALSE;
        END_IF;
    ELSE
        CoolantPumpOn := FALSE;
        CoolantAlarm := FALSE;
    END_IF;

    // Chiller and Indexer Logic omitted for brevity but assumed operational
    ChillerPumpOn := Enable AND (SpindleTemp > TempSetpoint + 2.0);
    ToolInPosition := (ToolIndexCmd = MagEncoderPos);
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_CNC_Mill_Breadth
VAR_INPUT
    Enable : BOOL;
    PN_VFD_StatusWord : WORD;
    PN_VFD_ActualSpeed : INT;
    SpindleTemp : REAL;
END_VAR
VAR_OUTPUT
    PN_VFD_ControlWord : WORD;
    PN_VFD_SpeedSetpt : INT;
    Alarms_Warning : ARRAY[0..15] OF BOOL;
    Alarms_Fault : ARRAY[0..15] OF BOOL;
    Alarms_Critical : ARRAY[0..15] OF BOOL;
END_VAR
VAR
    VFD_Ready : BOOL;
    VFD_Fault : BOOL;
END_VAR
BEGIN
    // Profinet VFD Mapping
    VFD_Ready := (PN_VFD_StatusWord AND 16#0001) > 0;
    VFD_Fault := (PN_VFD_StatusWord AND 16#0008) > 0;

    IF Enable AND VFD_Ready AND NOT VFD_Fault THEN
        PN_VFD_ControlWord := 16#047F; // Run command
        PN_VFD_SpeedSetpt := 1500;
    ELSE
        PN_VFD_ControlWord := 16#047E; // Stop command
        PN_VFD_SpeedSetpt := 0;
    END_IF;

    // Diagnostics
    // Warning: Temp High
    Alarms_Warning[0] := SpindleTemp > 35.0 AND SpindleTemp <= 45.0;
    // Fault: VFD Fault from Profinet
    Alarms_Fault[0] := VFD_Fault;
    // Critical: Temp Critical
    Alarms_Critical[0] := SpindleTemp > 45.0;

    // Auto-stop on Critical
    IF Alarms_Critical[0] THEN
        PN_VFD_ControlWord := 16#047E;
    END_IF;
END_FUNCTION_BLOCK

