PROGRAM PRG_TurbofanTest
VAR
    // Inputs
    fThrustLoadCell     AT %I* : LREAL; // Thrust reading in kN
    bStartTest          AT %I* : BOOL;
    bEmergencyStop      AT %I* : BOOL;

