VAR
    VoltageProfileCurve : ARRAY[0..10] OF Real := [0.0, 50.0, 150.0, 300.0, 350.0, 350.0, 350.0, 350.0, 200.0, 50.0, 0.0];
    Index : Int;
    pH_Setpoint : Real := 5.5;
    Cond_Setpoint : Real := 1500.0;
    FaultActive : Bool;
    FaultID : Int;
    Clock_1Hz : Bool;
END_VAR
BEGIN
    PN_OUT.Heartbeat := Clock_1Hz;

    IF PN_IN.EmergencyStop THEN
        FaultActive := TRUE;
        FaultID := 1;
    ELSIF PN_IN.Anolyte_pH_Sensor < 1.0 OR PN_IN.Anolyte_pH_Sensor > 14.0 THEN
