VAR
    VoltageProfileCurve : ARRAY[0..10] OF Real := [0.0, 50.0, 150.0, 300.0, 350.0, 350.0, 350.0, 350.0, 200.0, 50.0, 0.0];
    Index : Int;
    TargetVolt : Real;
    ActiveRect : Int := 1;
    SecurityValid : Bool;
END_VAR
BEGIN
    IF PN_IN.SecurityToken = 16#A1B2C3D4 AND PN_IN.UserLevel >= 1 THEN
        SecurityValid := TRUE;
        SCADA_Out.SecurityAlert := FALSE;
    ELSE
        SecurityValid := FALSE;
        SCADA_Out.SecurityAlert := TRUE;
