    IF ActiveRect = 1 AND NOT Rectifier1_OK THEN
        IF Rectifier2_OK THEN ActiveRect := 2; ELSE SystemFault := TRUE; END_IF;
    ELSIF ActiveRect = 2 AND NOT Rectifier2_OK THEN
        IF Rectifier1_OK THEN ActiveRect := 1; ELSE SystemFault := TRUE; END_IF;
    END_IF;
    SCADA_Out.ActiveRectifier := ActiveRect;

    IF PN_IN.MasterEnable AND SecurityValid AND NOT SystemFault AND NOT PN_IN.EmergencyStop THEN
        ConveyorAngleCmd := PN_IN.SetDipAngle;
        IF PN_IN.ConveyorPos >= 0.0 AND PN_IN.ConveyorPos <= 100.0 THEN
            Index := REAL_TO_INT(PN_IN.ConveyorPos / 10.0);
            IF Index > 10 THEN Index := 10; END_IF;
            IF Index < 0 THEN Index := 0; END_IF;
            TargetVolt := VoltageProfileCurve[Index];
        ELSE
            TargetVolt := 0.0;
        END_IF;

        IF ActiveRect = 1 THEN
            Rectifier1_Volt := TargetVolt;
            Rectifier2_Volt := 0.0;
        ELSE
            Rectifier1_Volt := 0.0;
            Rectifier2_Volt := TargetVolt;
