// ============================================================
// FB: DiffusionFurnaceControl
// Desc: Controls quartz tube temperature ramp rate and
//       gas manifold valve switching for a semiconductor
//       diffusion furnace.
// IEC 61131-3 Siemens SCL (TIA Portal V17)
// ============================================================
FUNCTION_BLOCK DiffusionFurnaceControl
VAR_INPUT
    Enable          : BOOL;         // Master enable
    SetpointTemp    : REAL;         // Target zone temperature [deg C]
    RampRate        : REAL;         // Desired ramp rate [deg C/min]
    ActualTemp      : REAL;         // PV from thermocouple [deg C]
    ProcessPhase    : INT;          // 0=Idle,1=Ramp,2=Soak,3=Cool,4=Purge
END_VAR
VAR_OUTPUT
    HeaterOutput    : REAL;         // 0-100% to SCR power controller
    Valve_N2        : BOOL;         // Nitrogen purge valve
    Valve_O2        : BOOL;         // Oxidation gas valve
    Valve_DCS       : BOOL;         // Dichlorosilane valve
    Valve_Exhaust   : BOOL;         // Exhaust manifold valve
    RampDone        : BOOL;         // Ramp segment complete
    FaultActive     : BOOL;         // General fault flag
END_VAR
VAR
    RampTarget      : REAL;
    RampIncrement   : REAL;
    PID_Error       : REAL;
    PID_Integral    : REAL;
    PID_Derivative  : REAL;
    PID_PrevError   : REAL;
    Kp              : REAL := 2.5;
    Ki              : REAL := 0.08;
    Kd              : REAL := 0.4;
    CycleTime       : REAL := 0.1;
    TempHighLimit   : REAL := 1200.0;
    TempLowLimit    : REAL := 20.0;
END_VAR

IF ActualTemp > TempHighLimit OR ActualTemp < TempLowLimit THEN
    FaultActive    := TRUE;
    HeaterOutput   := 0.0;
    Valve_O2       := FALSE;
    Valve_DCS      := FALSE;
    Valve_N2       := TRUE;
    Valve_Exhaust  := TRUE;
    RETURN;
END_IF;

FaultActive := FALSE;

IF NOT Enable THEN
    HeaterOutput  := 0.0;
    Valve_N2      := FALSE;
    Valve_O2      := FALSE;
    Valve_DCS     := FALSE;
    Valve_Exhaust := FALSE;
    RampDone      := FALSE;
    RETURN;
END_IF;

RampIncrement := RampRate / 600.0;

CASE ProcessPhase OF
    1:
        IF RampTarget < SetpointTemp THEN
            RampTarget := RampTarget + RampIncrement;
            IF RampTarget > SetpointTemp THEN RampTarget := SetpointTemp; END_IF;
            RampDone := FALSE;
        ELSE
            RampDone := TRUE;
        END_IF;
    2:
        RampTarget := SetpointTemp;
        RampDone   := TRUE;
    3:
        IF RampTarget > 200.0 THEN
            RampTarget := RampTarget - RampIncrement;
        ELSE
            RampTarget := 200.0;
            RampDone   := TRUE;
        END_IF;
    4:
        HeaterOutput := 0.0;
        RampTarget   := 0.0;
    ELSE:
        HeaterOutput := 0.0;
        RampTarget   := ActualTemp;
        RampDone     := FALSE;
END_CASE;

IF ProcessPhase = 1 OR ProcessPhase = 2 OR ProcessPhase = 3 THEN
    PID_Error      := RampTarget - ActualTemp;
    PID_Integral   := PID_Integral + (PID_Error * CycleTime);
    PID_Derivative := (PID_Error - PID_PrevError) / CycleTime;
    PID_PrevError  := PID_Error;
    HeaterOutput   := (Kp * PID_Error) + (Ki * PID_Integral) + (Kd * PID_Derivative);
    IF HeaterOutput > 100.0 THEN HeaterOutput := 100.0; END_IF;
    IF HeaterOutput < 0.0   THEN HeaterOutput := 0.0;   END_IF;
    IF HeaterOutput >= 100.0 OR HeaterOutput <= 0.0 THEN
        PID_Integral := PID_Integral - (PID_Error * CycleTime);
    END_IF;
END_IF;

CASE ProcessPhase OF
    0:  Valve_N2:=FALSE; Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=FALSE;
    1:  Valve_N2:=TRUE;  Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    2:  Valve_N2:=FALSE; Valve_O2:=TRUE;  Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    3:  Valve_N2:=TRUE;  Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    4:  Valve_N2:=TRUE;  Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    ELSE: Valve_N2:=FALSE; Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=FALSE;
END_CASE;

END_FUNCTION_BLOCK
