```scl
// ============================================================
// FB: DiffusionFurnace_Profinet
// Desc: 3-zone furnace + Profinet I/O + structured fault
//       diagnostics with 64-entry ring-buffer event log.
// IEC 61131-3 Siemens SCL (TIA Portal V17)
// ============================================================

TYPE FaultRecord
    STRUCT
        FaultCode    : INT;
        ZoneID       : INT;
        Severity     : INT;
        ActualValue  : REAL;
        LimitValue   : REAL;
    END_STRUCT;
END_TYPE

// Fault Codes:
//  1000=Over-temp  1001=Under-temp  1002=Zone deviation
//  1003=Valve feedback mismatch  1004=Profinet comm loss
//  1005=SCR saturation >10s  1006=Sensor open-circuit

FUNCTION_BLOCK DiffusionFurnace_Profinet
VAR_INPUT
    Enable           : BOOL;
    SetpointTemp     : REAL;
    RampRate         : REAL;
    ProcessPhase     : INT;
    ZoneDevLimit     : REAL := 3.0;
    PN_TempRaw_Top   : INT;
    PN_TempRaw_Ctr   : INT;
    PN_TempRaw_Bot   : INT;
    PN_ValveFB_N2    : BOOL;
    PN_ValveFB_O2    : BOOL;
    PN_ValveFB_DCS   : BOOL;
    PN_ValveFB_Exh   : BOOL;
    PN_CommStatus    : WORD;
END_VAR
VAR_OUTPUT
    PN_SCR_Top       : INT;
    PN_SCR_Ctr       : INT;
    PN_SCR_Bot       : INT;
    PN_Valve_N2      : BOOL;
    PN_Valve_O2      : BOOL;
    PN_Valve_DCS     : BOOL;
    PN_Valve_Exh     : BOOL;
    RampDone         : BOOL;
    ZoneDevAlarm     : BOOL;
    FaultActive      : BOOL;
    ActiveFaultCode  : INT;
    FaultLogCount    : INT;
END_VAR
VAR
    ActTemp_Top : REAL;  ActTemp_Ctr : REAL;  ActTemp_Bot : REAL;
    RampTarget    : REAL;
    RampIncrement : REAL;
    Err_T,Int_T,Drv_T,PErr_T : REAL;
    Err_C,Int_C,Drv_C,PErr_C : REAL;
    Err_B,Int_B,Drv_B,PErr_B : REAL;
    Kp:REAL:=2.8; Ki:REAL:=0.09; Kd:REAL:=0.45; Ts:REAL:=0.1;
    Out_T, Out_C, Out_B : REAL;
    AvgTemp, Dev_T, Dev_C, Dev_B, MaxDev : REAL;
    Cmd_N2,Cmd_O2,Cmd_DCS,Cmd_Exh : BOOL;
    ValveMismatchCnt : INT;
    SCR_T_SatCnt : INT;  SCR_SAT_LIMIT : INT := 100;
    FaultLog     : ARRAY[0..63] OF FaultRecord;
    FaultHead    : INT := 0;
    TempHiLim : REAL := 1200.0;  TempLoLim : REAL := 15.0;
END_VAR

ActTemp_Top := INT_TO_REAL(PN_TempRaw_Top) * 1300.0 / 32767.0;
ActTemp_Ctr := INT_TO_REAL(PN_TempRaw_Ctr) * 1300.0 / 32767.0;
ActTemp_Bot := INT_TO_REAL(PN_TempRaw_Bot) * 1300.0 / 32767.0;

IF PN_CommStatus <> 0 THEN
    FaultLog[FaultHead]:=(FaultCode:=1004,ZoneID:=0,Severity:=3,
        ActualValue:=INT_TO_REAL(WORD_TO_INT(PN_CommStatus)),LimitValue:=0.0);
    FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1;
    FaultActive:=TRUE; ActiveFaultCode:=1004;
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=TRUE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=TRUE;
    RETURN;
END_IF;

FaultActive:=FALSE; ActiveFaultCode:=0;

IF ActTemp_Top > TempHiLim THEN
    FaultLog[FaultHead]:=(FaultCode:=1000,ZoneID:=1,Severity:=3,ActualValue:=ActTemp_Top,LimitValue:=TempHiLim);
    FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1;
    FaultActive:=TRUE; ActiveFaultCode:=1000;
END_IF;
IF ActTemp_Ctr > TempHiLim THEN
    FaultLog[FaultHead]:=(FaultCode:=1000,ZoneID:=2,Severity:=3,ActualValue:=ActTemp_Ctr,LimitValue:=TempHiLim);
    FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1;
    FaultActive:=TRUE; ActiveFaultCode:=1000;
END_IF;
IF ActTemp_Bot > TempHiLim THEN
    FaultLog[FaultHead]:=(FaultCode:=1000,ZoneID:=3,Severity:=3,ActualValue:=ActTemp_Bot,LimitValue:=TempHiLim);
    FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1;
    FaultActive:=TRUE; ActiveFaultCode:=1000;
END_IF;
IF Enable AND (PN_TempRaw_Top=0 OR PN_TempRaw_Ctr=0 OR PN_TempRaw_Bot=0) THEN
    FaultLog[FaultHead]:=(FaultCode:=1006,ZoneID:=0,Severity:=3,ActualValue:=0.0,LimitValue:=1.0);
    FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1;
    FaultActive:=TRUE; ActiveFaultCode:=1006;
END_IF;

IF FaultActive THEN
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=TRUE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=TRUE;
    RETURN;
END_IF;

IF NOT Enable THEN
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=FALSE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=FALSE;
    RETURN;
END_IF;

RampIncrement := RampRate / 600.0;
CASE ProcessPhase OF
    1:  RampTarget:=LIMIT(0.0,RampTarget+RampIncrement,SetpointTemp);
        RampDone:=(RampTarget>=SetpointTemp);
    2:  RampTarget:=SetpointTemp; RampDone:=TRUE;
    3:  RampTarget:=LIMIT(200.0,RampTarget-RampIncrement,1200.0);
        RampDone:=(RampTarget<=200.0);
    4:  PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    ELSE: RampTarget:=ActTemp_Ctr; RampDone:=FALSE;
END_CASE;

AvgTemp:=(ActTemp_Top+ActTemp_Ctr+ActTemp_Bot)/3.0;
Dev_T:=ABS(ActTemp_Top-AvgTemp); Dev_C:=ABS(ActTemp_Ctr-AvgTemp); Dev_B:=ABS(ActTemp_Bot-AvgTemp);
MaxDev:=MAX(Dev_T,MAX(Dev_C,Dev_B)); ZoneDevAlarm:=MaxDev>ZoneDevLimit;
IF ZoneDevAlarm THEN
    FaultLog[FaultHead]:=(FaultCode:=1002,ZoneID:=0,Severity:=2,ActualValue:=MaxDev,LimitValue:=ZoneDevLimit);
    FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1;
END_IF;

IF ProcessPhase>=1 AND ProcessPhase<=3 THEN
    Err_T:=RampTarget-ActTemp_Top; Int_T:=Int_T+Err_T*Ts;
    Drv_T:=(Err_T-PErr_T)/Ts; PErr_T:=Err_T;
    Out_T:=LIMIT(0.0,Kp*Err_T+Ki*Int_T+Kd*Drv_T,100.0);
    IF Out_T>=100.0 OR Out_T<=0.0 THEN Int_T:=Int_T-Err_T*Ts; END_IF;

    Err_C:=RampTarget-ActTemp_Ctr; Int_C:=Int_C+Err_C*Ts;
    Drv_C:=(Err_C-PErr_C)/Ts; PErr_C:=Err_C;
    Out_C:=LIMIT(0.0,Kp*Err_C+Ki*Int_C+Kd*Drv_C,100.0);
    IF Out_C>=100.0 OR Out_C<=0.0 THEN Int_C:=Int_C-Err_C*Ts; END_IF;

    Err_B:=RampTarget-ActTemp_Bot; Int_B:=Int_B+Err_B*Ts;
    Drv_B:=(Err_B-PErr_B)/Ts; PErr_B:=Err_B;
    Out_B:=LIMIT(0.0,Kp*Err_B+Ki*Int_B+Kd*Drv_B,100.0);
    IF Out_B>=100.0 OR Out_B<=0.0 THEN Int_B:=Int_B-Err_B*Ts; END_IF;

    IF Out_T>=100.0 THEN SCR_T_SatCnt:=SCR_T_SatCnt+1;
    ELSE SCR_T_SatCnt:=0; END_IF;
    IF SCR_T_SatCnt>SCR_SAT_LIMIT THEN
        FaultLog[FaultHead]:=(FaultCode:=1005,ZoneID:=1,Severity:=2,ActualValue:=Out_T,LimitValue:=100.0);
        FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1; SCR_T_SatCnt:=0;
    END_IF;

    PN_SCR_Top:=REAL_TO_INT(Out_T*327.67);
    PN_SCR_Ctr:=REAL_TO_INT(Out_C*327.67);
    PN_SCR_Bot:=REAL_TO_INT(Out_B*327.67);
END_IF;

CASE ProcessPhase OF
    0:  Cmd_N2:=FALSE; Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=FALSE;
    1:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    2:  Cmd_N2:=FALSE; Cmd_O2:=TRUE;  Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    3:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    4:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    ELSE: Cmd_N2:=FALSE; Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=FALSE;
END_CASE;
PN_Valve_N2:=Cmd_N2; PN_Valve_O2:=Cmd_O2; PN_Valve_DCS:=Cmd_DCS; PN_Valve_Exh:=Cmd_Exh;

IF (Cmd_N2<>PN_ValveFB_N2) OR (Cmd_O2<>PN_ValveFB_O2) OR
   (Cmd_DCS<>PN_ValveFB_DCS) OR (Cmd_Exh<>PN_ValveFB_Exh) THEN
    ValveMismatchCnt:=ValveMismatchCnt+1;
    IF ValveMismatchCnt>30 THEN
        FaultLog[FaultHead]:=(FaultCode:=1003,ZoneID:=0,Severity:=2,ActualValue:=1.0,LimitValue:=0.0);
        FaultHead:=(FaultHead+1) MOD 64; FaultLogCount:=FaultLogCount+1; ValveMismatchCnt:=0;
    END_IF;
ELSE  ValveMismatchCnt:=0;
END_IF;

END_FUNCTION_BLOCK
```

```scl
// ============================================================
// FB: DiffusionFurnace_Secure
// Desc: Full furnace with IEC 62443 cybersecurity,
//       hot-standby failover, and SCADA OPC-UA export DB.
// IEC 61131-3 Siemens SCL (TIA Portal V17)
// ============================================================

TYPE CommandPacket
    STRUCT
        CmdID        : INT;
        AccessLevel  : INT;
        CmdCode      : INT;
        CmdValue     : REAL;
        CRC16        : WORD;
        SessionToken : DWORD;
    END_STRUCT;
END_TYPE

TYPE AuditRecord
    STRUCT
        UserLevel    : INT;
        CmdCode      : INT;
        CmdValue     : REAL;
        Accepted     : BOOL;
        RejectReason : INT;
    END_STRUCT;
END_TYPE

TYPE SCADA_DataBlock
    STRUCT
        Temp_Top,Temp_Ctr,Temp_Bot         : REAL;
        Heater_Top,Heater_Ctr,Heater_Bot   : REAL;
        RampTarget                          : REAL;
        ProcessPhase                        : INT;
        Valve_N2,Valve_O2,Valve_DCS,Valve_Exh : BOOL;
        FaultActive                         : BOOL;
        ActiveFault                         : INT;
        ZoneDevAlarm                        : BOOL;
        MaxDeviation                        : REAL;
        PrimaryActive,StandbyReady          : BOOL;
        LastCmdUser,LastCmdCode,CmdRejCount : INT;
    END_STRUCT;
END_TYPE

FUNCTION ComputeCRC16 : WORD
VAR_INPUT DataWord : DWORD; END_VAR
    ComputeCRC16 := WORD#16#A001 XOR WORD(DataWord AND DWORD#16#FFFF);
END_FUNCTION

FUNCTION_BLOCK DiffusionFurnace_Secure
VAR_INPUT
    Enable              : BOOL;
    ZoneDevLimit        : REAL := 3.0;
    PN_TempRaw_Top,PN_TempRaw_Ctr,PN_TempRaw_Bot : INT;
    PN_ValveFB_N2,PN_ValveFB_O2,PN_ValveFB_DCS,PN_ValveFB_Exh : BOOL;
    PN_CommStatus       : WORD;
    IncomingCmd         : CommandPacket;
    CmdNew              : BOOL;
    StandbyHeartbeat    : BOOL;
    StandbyTakeoverReq  : BOOL;
    Standby_RampTarget  : REAL;
    Standby_Int_T,Standby_Int_C,Standby_Int_B : REAL;
END_VAR
VAR_OUTPUT
    PN_SCR_Top,PN_SCR_Ctr,PN_SCR_Bot : INT;
    PN_Valve_N2,PN_Valve_O2,PN_Valve_DCS,PN_Valve_Exh : BOOL;
    RampDone,ZoneDevAlarm,FaultActive : BOOL;
    ActiveFaultCode     : INT;
    PrimaryActive       : BOOL;
    CmdAccepted,CmdRejected : BOOL;
    CmdRejectReason     : INT;
    SCADA_DB            : SCADA_DataBlock;
END_VAR
VAR
    SetpointTemp : REAL := 900.0;
    RampRate     : REAL := 5.0;
    ProcessPhase : INT  := 0;
    RampTarget,RampIncrement : REAL;
    Err_T,Int_T,Drv_T,PErr_T : REAL;
    Err_C,Int_C,Drv_C,PErr_C : REAL;
    Err_B,Int_B,Drv_B,PErr_B : REAL;
    Kp:REAL:=2.8; Ki:REAL:=0.09; Kd:REAL:=0.45; Ts:REAL:=0.1;
    Out_T,Out_C,Out_B : REAL;
    ActTemp_T,ActTemp_C,ActTemp_B : REAL;
    AvgTemp,MaxDev : REAL;
    CurrentSessionToken : DWORD := DWORD#16#DEADBEEF;
    CmdRejCount : INT;
    ComputedCRC : WORD;
    AuditLog    : ARRAY[0..127] OF AuditRecord;
    AuditHead   : INT := 0;
    FailoverActive : BOOL;
    Cmd_N2,Cmd_O2,Cmd_DCS,Cmd_Exh : BOOL;
    TempHiLim : REAL := 1200.0;
END_VAR

IF StandbyTakeoverReq AND NOT FailoverActive THEN
    PrimaryActive:=FALSE; FailoverActive:=TRUE;
END_IF;
IF NOT FailoverActive THEN PrimaryActive:=TRUE; END_IF;

IF NOT PrimaryActive THEN
    RampTarget:=Standby_RampTarget;
    Int_T:=Standby_Int_T; Int_C:=Standby_Int_C; Int_B:=Standby_Int_B;
    RETURN;
END_IF;

CmdAccepted:=FALSE; CmdRejected:=FALSE; CmdRejectReason:=0;
IF CmdNew THEN
    IF IncomingCmd.SessionToken <> CurrentSessionToken THEN
        CmdRejected:=TRUE; CmdRejectReason:=3; CmdRejCount:=CmdRejCount+1;
    ELSE
        ComputedCRC:=ComputeCRC16(DWORD(IncomingCmd.CmdID) XOR DWORD(IncomingCmd.CmdCode));
        IF ComputedCRC <> IncomingCmd.CRC16 THEN
            CmdRejected:=TRUE; CmdRejectReason:=1; CmdRejCount:=CmdRejCount+1;
        ELSE
            CASE IncomingCmd.CmdCode OF
                1:  IF IncomingCmd.AccessLevel >= 2 THEN
                        ProcessPhase:=INT(IncomingCmd.CmdValue); CmdAccepted:=TRUE;
                    ELSE CmdRejected:=TRUE; CmdRejectReason:=2; CmdRejCount:=CmdRejCount+1; END_IF;
                2:  IF IncomingCmd.AccessLevel >= 1 THEN
                        SetpointTemp:=IncomingCmd.CmdValue; CmdAccepted:=TRUE;
                    ELSE CmdRejected:=TRUE; CmdRejectReason:=2; CmdRejCount:=CmdRejCount+1; END_IF;
                3:  IF IncomingCmd.AccessLevel >= 1 THEN
                        RampRate:=IncomingCmd.CmdValue; CmdAccepted:=TRUE;
                    ELSE CmdRejected:=TRUE; CmdRejectReason:=2; CmdRejCount:=CmdRejCount+1; END_IF;
                ELSE: CmdRejected:=TRUE; CmdRejectReason:=4; CmdRejCount:=CmdRejCount+1;
            END_CASE;
        END_IF;
    END_IF;
    AuditLog[AuditHead].UserLevel:=IncomingCmd.AccessLevel;
    AuditLog[AuditHead].CmdCode:=IncomingCmd.CmdCode;
    AuditLog[AuditHead].CmdValue:=IncomingCmd.CmdValue;
    AuditLog[AuditHead].Accepted:=CmdAccepted;
    AuditLog[AuditHead].RejectReason:=CmdRejectReason;
    AuditHead:=(AuditHead+1) MOD 128;
END_IF;

ActTemp_T:=INT_TO_REAL(PN_TempRaw_Top)*1300.0/32767.0;
ActTemp_C:=INT_TO_REAL(PN_TempRaw_Ctr)*1300.0/32767.0;
ActTemp_B:=INT_TO_REAL(PN_TempRaw_Bot)*1300.0/32767.0;

FaultActive:=FALSE; ActiveFaultCode:=0;
IF PN_CommStatus<>0 THEN
    FaultActive:=TRUE; ActiveFaultCode:=1004;
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=TRUE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=TRUE; RETURN;
END_IF;
IF (ActTemp_T>TempHiLim) OR (ActTemp_C>TempHiLim) OR (ActTemp_B>TempHiLim) THEN
    FaultActive:=TRUE; ActiveFaultCode:=1000;
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=TRUE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=TRUE; RETURN;
END_IF;
IF NOT Enable THEN
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=FALSE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=FALSE; RETURN;
END_IF;

RampIncrement:=RampRate/600.0;
CASE ProcessPhase OF
    1:  RampTarget:=LIMIT(0.0,RampTarget+RampIncrement,SetpointTemp);
        RampDone:=(RampTarget>=SetpointTemp);
    2:  RampTarget:=SetpointTemp; RampDone:=TRUE;
    3:  RampTarget:=LIMIT(200.0,RampTarget-RampIncrement,1200.0);
        RampDone:=(RampTarget<=200.0);
    4:  PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    ELSE: RampTarget:=ActTemp_C; RampDone:=FALSE;
END_CASE;

AvgTemp:=(ActTemp_T+ActTemp_C+ActTemp_B)/3.0;
MaxDev:=MAX(ABS(ActTemp_T-AvgTemp),MAX(ABS(ActTemp_C-AvgTemp),ABS(ActTemp_B-AvgTemp)));
ZoneDevAlarm:=MaxDev>ZoneDevLimit;

IF ProcessPhase>=1 AND ProcessPhase<=3 THEN
    Err_T:=RampTarget-ActTemp_T; Int_T:=Int_T+Err_T*Ts;
    Drv_T:=(Err_T-PErr_T)/Ts; PErr_T:=Err_T;
    Out_T:=LIMIT(0.0,Kp*Err_T+Ki*Int_T+Kd*Drv_T,100.0);
    IF Out_T>=100.0 OR Out_T<=0.0 THEN Int_T:=Int_T-Err_T*Ts; END_IF;
    Err_C:=RampTarget-ActTemp_C; Int_C:=Int_C+Err_C*Ts;
    Drv_C:=(Err_C-PErr_C)/Ts; PErr_C:=Err_C;
    Out_C:=LIMIT(0.0,Kp*Err_C+Ki*Int_C+Kd*Drv_C,100.0);
    IF Out_C>=100.0 OR Out_C<=0.0 THEN Int_C:=Int_C-Err_C*Ts; END_IF;
    Err_B:=RampTarget-ActTemp_B; Int_B:=Int_B+Err_B*Ts;
    Drv_B:=(Err_B-PErr_B)/Ts; PErr_B:=Err_B;
    Out_B:=LIMIT(0.0,Kp*Err_B+Ki*Int_B+Kd*Drv_B,100.0);
    IF Out_B>=100.0 OR Out_B<=0.0 THEN Int_B:=Int_B-Err_B*Ts; END_IF;
    PN_SCR_Top:=REAL_TO_INT(Out_T*327.67);
    PN_SCR_Ctr:=REAL_TO_INT(Out_C*327.67);
    PN_SCR_Bot:=REAL_TO_INT(Out_B*327.67);
END_IF;

CASE ProcessPhase OF
    0:  Cmd_N2:=FALSE; Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=FALSE;
    1:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    2:  Cmd_N2:=FALSE; Cmd_O2:=TRUE;  Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    3:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    4:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    ELSE: Cmd_N2:=FALSE; Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=FALSE;
END_CASE;
PN_Valve_N2:=Cmd_N2; PN_Valve_O2:=Cmd_O2; PN_Valve_DCS:=Cmd_DCS; PN_Valve_Exh:=Cmd_Exh;

SCADA_DB.Temp_Top:=ActTemp_T; SCADA_DB.Temp_Ctr:=ActTemp_C; SCADA_DB.Temp_Bot:=ActTemp_B;
SCADA_DB.Heater_Top:=Out_T; SCADA_DB.Heater_Ctr:=Out_C; SCADA_DB.Heater_Bot:=Out_B;
SCADA_DB.RampTarget:=RampTarget; SCADA_DB.ProcessPhase:=ProcessPhase;
SCADA_DB.Valve_N2:=Cmd_N2; SCADA_DB.Valve_O2:=Cmd_O2;
SCADA_DB.Valve_DCS:=Cmd_DCS; SCADA_DB.Valve_Exh:=Cmd_Exh;
SCADA_DB.FaultActive:=FaultActive; SCADA_DB.ActiveFault:=ActiveFaultCode;
SCADA_DB.ZoneDevAlarm:=ZoneDevAlarm; SCADA_DB.MaxDeviation:=MaxDev;
SCADA_DB.PrimaryActive:=PrimaryActive; SCADA_DB.StandbyReady:=StandbyHeartbeat;
SCADA_DB.LastCmdUser:=AuditLog[(AuditHead-1+128) MOD 128].UserLevel;
SCADA_DB.LastCmdCode:=AuditLog[(AuditHead-1+128) MOD 128].CmdCode;
SCADA_DB.CmdRejCount:=CmdRejCount;

END_FUNCTION_BLOCK
