TYPE E_HV_State : (HV_OFF, HV_RAMPING, HV_READY, HV_FAULT); END_TYPE

PROGRAM PRG_IonImplanter_M1
VAR
    // IO
    fBeamCurrent AT %I* : REAL;
    bImplantEnable AT %I* : BOOL;
    fStageX_Cmd AT %Q* : LREAL;
    fStageY_Cmd AT %Q* : LREAL;

    // HV IO
    bHV_Enable AT %Q* : BOOL;
    fHV_VoltageAct AT %I* : REAL;
    fHV_VoltageCmd AT %Q* : REAL;

    // State
    eHVState : E_HV_State := HV_OFF;
    fHV_Target : REAL := 200.0;
    fHV_RampRate : REAL := 10.0;
    fCycleTime : LREAL := 0.01;
    fAccumulatedDose : LREAL;
END_VAR

CASE eHVState OF
    HV_OFF:
        bHV_Enable := FALSE;
        fHV_VoltageCmd := 0.0;
        IF bImplantEnable THEN
            bHV_Enable := TRUE;
            eHVState := HV_RAMPING;
        END_IF
    HV_RAMPING:
        fHV_VoltageCmd := fHV_VoltageCmd + (fHV_RampRate * REAL_TO_LREAL(fCycleTime));
        IF fHV_VoltageCmd >= fHV_Target THEN
            fHV_VoltageCmd := fHV_Target;
            IF ABS(fHV_VoltageAct - fHV_Target) < 5.0 THEN
                eHVState := HV_READY;
            END_IF
        END_IF
        IF NOT bImplantEnable THEN eHVState := HV_OFF; END_IF
    HV_READY:
        IF NOT bImplantEnable THEN eHVState := HV_OFF; END_IF
        IF ABS(fHV_VoltageAct - fHV_Target) > 15.0 THEN eHVState := HV_FAULT; END_IF
    HV_FAULT:
        bHV_Enable := FALSE;
        fHV_VoltageCmd := 0.0;
END_CASE

// Implant only when ready
IF eHVState = HV_READY THEN
    fAccumulatedDose := fAccumulatedDose + (fBeamCurrent * fCycleTime);
    fStageX_Cmd := fStageX_Cmd + (10.0 * fCycleTime);
END_IF
