TYPE E_SysState : (SYS_INIT, SYS_READY, SYS_IMPLANT, SYS_FAULT); END_TYPE

PROGRAM PRG_IonImplanter_M2
VAR
    eState : E_SysState := SYS_INIT;
    bImplantEnable : BOOL;

    // EtherCAT Diagnostics
    wEcatMasterState AT %I* : WORD;
    wEcatStageSlaveState AT %I* : WORD;
    bWcStateError AT %I* : BOOL;

    // Faults
    bFault_Ecat : BOOL;
    bFault_StageFollowing : BOOL;
    bFault_HVOvercurrent : BOOL;

    fStageX_Act AT %I* : LREAL;
    fStageX_Cmd AT %Q* : LREAL;
    fHV_CurrentAct AT %I* : REAL;
END_VAR

// EtherCAT checks (State 8 = OP)
bFault_Ecat := (wEcatMasterState <> 8) OR (wEcatStageSlaveState <> 8) OR bWcStateError;

// Process limits
bFault_StageFollowing := ABS(fStageX_Cmd - fStageX_Act) > 1.5;
bFault_HVOvercurrent := fHV_CurrentAct > 50.0;

IF bFault_Ecat OR bFault_StageFollowing OR bFault_HVOvercurrent THEN
    eState := SYS_FAULT;
END_IF

CASE eState OF
    SYS_INIT:
        IF NOT bFault_Ecat THEN eState := SYS_READY; END_IF
    SYS_READY:
        IF bImplantEnable THEN eState := SYS_IMPLANT; END_IF
    SYS_IMPLANT:
        // Dosimetry and stage control here
        fStageX_Cmd := fStageX_Cmd + 0.1;
        IF NOT bImplantEnable THEN eState := SYS_READY; END_IF
    SYS_FAULT:
        // Safe state
        fStageX_Cmd := fStageX_Act;
END_CASE
