```pascal
(* ============================================================
   CVD CHAMBER CONTROL — BASE PROGRAM
   Platform : Allen-Bradley ControlLogix / Studio 5000
   Standard : IEC 61131-3 Structured Text
   Rev      : 1.0
   Desc     : Regulates Precursor Mass Flow (MFC) and
              Chamber Pressure via a throttle valve.
   ============================================================ *)

(* ---------- USER-DEFINED TYPES ---------- *)
TYPE
  eProcState : (
    ST_IDLE,
    ST_PURGE,
    ST_RAMP_FLOW,
    ST_DEPOSIT,
    ST_VENT,
    ST_FAULT
  );
END_TYPE

(* ---------- VARIABLE DECLARATIONS ---------- *)
VAR
  (* Process State *)
  eState          : eProcState := ST_IDLE;

  (* Setpoints *)
  rFlowSP         : REAL := 50.0;   (* sccm  — precursor MFC setpoint *)
  rPressSP        : REAL := 1.0;    (* Torr  — chamber pressure setpoint *)

  (* Process Values (from AI modules, 0-100 % scaled) *)
  rFlowPV         : REAL;           (* sccm  *)
  rPressPV        : REAL;           (* Torr  *)

  (* PID blocks (built-in PIDE function block) *)
  fbFlowPID       : PIDE;
  fbPressPID      : PIDE;

  (* PID tuning *)
  rFlow_KP        : REAL := 1.2;
  rFlow_KI        : REAL := 0.5;
  rFlow_KD        : REAL := 0.05;
  rPress_KP       : REAL := 2.0;
  rPress_KI       : REAL := 0.8;
  rPress_KD       : REAL := 0.10;

  (* Outputs (AO modules, 0-100 % → 4-20 mA) *)
  rMFC_CV         : REAL;           (* MFC control valve command   *)
  rThrottle_CV    : REAL;           (* Throttle valve command       *)

  (* Interlocks *)
  bEmgStop        : BOOL := FALSE;
  bPurgeComplete  : BOOL := FALSE;

  (* Timers *)
  tPurge          : TON;
  tDeposit        : TON;

  (* Limits *)
  rMaxFlow        : REAL := 200.0;  (* sccm *)
  rMaxPress       : REAL := 10.0;  (* Torr *)

  (* Alarm flags *)
  bFlowAlarm      : BOOL;
  bPressAlarm     : BOOL;
END_VAR

(* ============================================================
   MAIN CONTROL LOGIC
   ============================================================ *)

(* --- Safety interlock check — highest priority --- *)
IF bEmgStop THEN
  eState      := ST_FAULT;
  rMFC_CV     := 0.0;
  rThrottle_CV:= 0.0;
  fbFlowPID.EnableIn  := FALSE;
  fbPressPID.EnableIn := FALSE;
END_IF;

(* --- Alarm detection --- *)
bFlowAlarm  := (rFlowPV  > rMaxFlow);
bPressAlarm := (rPressPV > rMaxPress);

IF bFlowAlarm OR bPressAlarm THEN
  eState := ST_FAULT;
END_IF;

(* --- State Machine --- *)
CASE eState OF

  ST_IDLE:
    fbFlowPID.EnableIn  := FALSE;
    fbPressPID.EnableIn := FALSE;
    rMFC_CV             := 0.0;
    rThrottle_CV        := 0.0;
    tPurge(IN := FALSE);
    tDeposit(IN := FALSE);
    (* Transition: operator start *)
    (* Set eState := ST_PURGE from HMI *)

  ST_PURGE:
    (* Purge chamber with N2 for 60 s before introducing precursor *)
    rMFC_CV      := 0.0;   (* precursor MFC closed *)
    rThrottle_CV := 50.0;  (* partially open throttle *)
    tPurge(IN := TRUE, PT := T#60S);
    IF tPurge.Q THEN
      bPurgeComplete := TRUE;
      tPurge(IN := FALSE);
      eState := ST_RAMP_FLOW;
    END_IF;

  ST_RAMP_FLOW:
    (* Ramp MFC to setpoint under open-loop first pass *)
    rMFC_CV := rMFC_CV + 1.0;   (* 1 % per scan until SP reached *)
    IF rFlowPV >= (rFlowSP * 0.95) THEN
      eState := ST_DEPOSIT;
    END_IF;
    IF rMFC_CV > 100.0 THEN rMFC_CV := 100.0; END_IF;

  ST_DEPOSIT:
    (* Closed-loop PID on both flow and pressure *)
    fbFlowPID.SP        := rFlowSP;
    fbFlowPID.PV        := rFlowPV;
    fbFlowPID.Kp        := rFlow_KP;
    fbFlowPID.Ki        := rFlow_KI;
    fbFlowPID.Kd        := rFlow_KD;
    fbFlowPID.EnableIn  := TRUE;
    fbFlowPID.CVEU_HI   := 100.0;
    fbFlowPID.CVEU_LO   := 0.0;
    fbFlowPID();
    rMFC_CV := fbFlowPID.CV;

    fbPressPID.SP       := rPressSP;
    fbPressPID.PV       := rPressPV;
    fbPressPID.Kp       := rPress_KP;
    fbPressPID.Ki       := rPress_KI;
    fbPressPID.Kd       := rPress_KD;
    fbPressPID.EnableIn := TRUE;
    fbPressPID.CVEU_HI  := 100.0;
    fbPressPID.CVEU_LO  := 0.0;
    fbPressPID();
    rThrottle_CV := fbPressPID.CV;

    (* Deposit timer — 300 s run *)
    tDeposit(IN := TRUE, PT := T#300S);
    IF tDeposit.Q THEN
      tDeposit(IN := FALSE);
      eState := ST_VENT;
    END_IF;

  ST_VENT:
    fbFlowPID.EnableIn  := FALSE;
    fbPressPID.EnableIn := FALSE;
    rMFC_CV             := 0.0;
    rThrottle_CV        := 100.0;  (* fully open throttle to vent *)
    (* After pressure PV < 0.01 Torr, return to IDLE *)
    IF rPressPV < 0.01 THEN
      eState := ST_IDLE;
    END_IF;

  ST_FAULT:
    fbFlowPID.EnableIn  := FALSE;
    fbPressPID.EnableIn := FALSE;
    rMFC_CV             := 0.0;
    rThrottle_CV        := 0.0;
    (* Operator must acknowledge and reset *)

END_CASE;
