```pascal
(* ============================================================
   CVD CHAMBER CONTROL — MUTATION 1 (Add Depth)
   Platform : Allen-Bradley ControlLogix / Studio 5000
   Standard : IEC 61131-3 Structured Text
   Rev      : 2.0
   Added    : Substrate Heater PID + Over-Temp Protection +
              Multi-Layer Recipe Management
   ============================================================ *)

(* ---------- USER-DEFINED TYPES ---------- *)
TYPE
  eProcState : (
    ST_IDLE, ST_PURGE, ST_HEAT_RAMP, ST_RAMP_FLOW,
    ST_DEPOSIT, ST_INTER_PURGE, ST_VENT, ST_FAULT
  );

  tRecipeLayer : STRUCT
    rFlowSP     : REAL;   (* sccm *)
    rPressSP    : REAL;   (* Torr *)
    rTempSP     : REAL;   (* °C  *)
    tDuration   : TIME;   (* deposition time for this layer *)
  END_STRUCT;
END_TYPE

VAR CONSTANT
  MAX_LAYERS  : INT := 8;
END_VAR

VAR
  (* --- State & Recipe --- *)
  eState          : eProcState := ST_IDLE;
  aRecipe         : ARRAY [0..7] OF tRecipeLayer;
  iLayerIdx       : INT := 0;
  iTotalLayers    : INT := 3;   (* loaded by operator / HMI *)

  (* --- Precursor Flow --- *)
  rFlowPV         : REAL;
  fbFlowPID       : PIDE;
  rMFC_CV         : REAL;
  rFlow_KP        : REAL := 1.2;
  rFlow_KI        : REAL := 0.5;
  rFlow_KD        : REAL := 0.05;

  (* --- Chamber Pressure --- *)
  rPressPV        : REAL;
  fbPressPID      : PIDE;
  rThrottle_CV    : REAL;
  rPress_KP       : REAL := 2.0;
  rPress_KI       : REAL := 0.8;
  rPress_KD       : REAL := 0.10;

  (* --- Substrate Heater --- *)
  rTempPV         : REAL;           (* °C — thermocouple AI *)
  rTempSP_Active  : REAL := 400.0;  (* °C — set from active recipe layer *)
  rTempMaxLimit   : REAL := 700.0;  (* °C — hard over-temp limit *)
  rTempHysteresis : REAL := 5.0;    (* °C *)
  fbTempPID       : PIDE;
  rHeater_CV      : REAL;           (* 0-100 % — SCR power controller *)
  rTemp_KP        : REAL := 3.5;
  rTemp_KI        : REAL := 0.1;
  rTemp_KD        : REAL := 0.2;
  bOverTempTrip   : BOOL := FALSE;
  bOverTempLatch  : BOOL := FALSE;
  bHeaterEnable   : BOOL := FALSE;

  (* --- Timers --- *)
  tPurge          : TON;
  tHeatRamp       : TON;
  tDeposit        : TON;
  tInterPurge     : TON;

  (* --- Interlocks & Alarms --- *)
  bEmgStop        : BOOL := FALSE;
  bFlowAlarm      : BOOL;
  bPressAlarm     : BOOL;
  bTempAlarm      : BOOL;

  rMaxFlow        : REAL := 200.0;
  rMaxPress       : REAL := 10.0;
END_VAR

(* ============================================================
   HELPER: Load recipe layer setpoints into active variables
   ============================================================ *)
ACTION LoadLayer:
  IF iLayerIdx < iTotalLayers THEN
    fbFlowPID.SP    := aRecipe[iLayerIdx].rFlowSP;
    fbPressPID.SP   := aRecipe[iLayerIdx].rPressSP;
    rTempSP_Active  := aRecipe[iLayerIdx].rTempSP;
  END_IF;
END_ACTION

(* ============================================================
   HEATER SUB-SYSTEM (called every scan)
   ============================================================ *)
ACTION HeaterControl:
  (* Over-temperature protection — latching *)
  IF rTempPV >= rTempMaxLimit THEN
    bOverTempLatch := TRUE;
  END_IF;

  IF bOverTempLatch THEN
    bOverTempTrip  := TRUE;
    bHeaterEnable  := FALSE;
    rHeater_CV     := 0.0;
    fbTempPID.EnableIn := FALSE;
    eState := ST_FAULT;
    RETURN;
  END_IF;

  IF bHeaterEnable THEN
    fbTempPID.SP       := rTempSP_Active;
    fbTempPID.PV       := rTempPV;
    fbTempPID.Kp       := rTemp_KP;
    fbTempPID.Ki       := rTemp_KI;
    fbTempPID.Kd       := rTemp_KD;
    fbTempPID.EnableIn := TRUE;
    fbTempPID.CVEU_HI  := 100.0;
    fbTempPID.CVEU_LO  := 0.0;
    fbTempPID();
    rHeater_CV := fbTempPID.CV;
  ELSE
    fbTempPID.EnableIn := FALSE;
    rHeater_CV := 0.0;
  END_IF;
END_ACTION

(* ============================================================
   MAIN CONTROL LOGIC
   ============================================================ *)

(* Safety interlock *)
IF bEmgStop THEN
  eState := ST_FAULT;
END_IF;

(* Alarm detection *)
bFlowAlarm := (rFlowPV  > rMaxFlow);
bPressAlarm:= (rPressPV > rMaxPress);
bTempAlarm := (rTempPV  > rTempMaxLimit - rTempHysteresis);

IF bFlowAlarm OR bPressAlarm THEN
  eState := ST_FAULT;
END_IF;

(* Always run heater sub-system *)
HeaterControl();

CASE eState OF

  ST_IDLE:
    bHeaterEnable       := FALSE;
    fbFlowPID.EnableIn  := FALSE;
    fbPressPID.EnableIn := FALSE;
    rMFC_CV             := 0.0;
    rThrottle_CV        := 0.0;
    iLayerIdx           := 0;
    tPurge(IN := FALSE);

  ST_PURGE:
    rMFC_CV      := 0.0;
    rThrottle_CV := 50.0;
    tPurge(IN := TRUE, PT := T#60S);
    IF tPurge.Q THEN
      tPurge(IN := FALSE);
      bHeaterEnable := TRUE;   (* start heating during ramp *)
      LoadLayer();
      eState := ST_HEAT_RAMP;
    END_IF;

  ST_HEAT_RAMP:
    (* Wait until substrate reaches within 2 °C of setpoint *)
    IF ABS(rTempPV - rTempSP_Active) <= 2.0 THEN
      eState := ST_RAMP_FLOW;
    END_IF;
    (* Watchdog — if heater not at SP in 30 min, fault *)
    tHeatRamp(IN := TRUE, PT := T#1800S);
    IF tHeatRamp.Q THEN
      tHeatRamp(IN := FALSE);
      eState := ST_FAULT;
    END_IF;

  ST_RAMP_FLOW:
    rMFC_CV := rMFC_CV + 1.0;
    IF rMFC_CV > 100.0 THEN rMFC_CV := 100.0; END_IF;
    IF rFlowPV >= (aRecipe[iLayerIdx].rFlowSP * 0.95) THEN
      eState := ST_DEPOSIT;
    END_IF;

  ST_DEPOSIT:
    (* Flow PID *)
    fbFlowPID.PV       := rFlowPV;
    fbFlowPID.Kp       := rFlow_KP;
    fbFlowPID.Ki       := rFlow_KI;
    fbFlowPID.Kd       := rFlow_KD;
    fbFlowPID.EnableIn := TRUE;
    fbFlowPID.CVEU_HI  := 100.0;
    fbFlowPID.CVEU_LO  := 0.0;
    fbFlowPID();
    rMFC_CV := fbFlowPID.CV;

    (* Pressure PID *)
    fbPressPID.PV       := rPressPV;
    fbPressPID.Kp       := rPress_KP;
    fbPressPID.Ki       := rPress_KI;
    fbPressPID.Kd       := rPress_KD;
    fbPressPID.EnableIn := TRUE;
    fbPressPID.CVEU_HI  := 100.0;
    fbPressPID.CVEU_LO  := 0.0;
    fbPressPID();
    rThrottle_CV := fbPressPID.CV;

    (* Deposit layer timer *)
    tDeposit(IN := TRUE, PT := aRecipe[iLayerIdx].tDuration);
    IF tDeposit.Q THEN
      tDeposit(IN := FALSE);
      fbFlowPID.EnableIn  := FALSE;
      fbPressPID.EnableIn := FALSE;
      iLayerIdx := iLayerIdx + 1;
      IF iLayerIdx < iTotalLayers THEN
        eState := ST_INTER_PURGE;   (* purge between layers *)
      ELSE
        eState := ST_VENT;           (* all layers done *)
      END_IF;
    END_IF;

  ST_INTER_PURGE:
    (* Brief N2 purge between layers, update recipe SP *)
    rMFC_CV      := 0.0;
    rThrottle_CV := 50.0;
    tInterPurge(IN := TRUE, PT := T#30S);
    IF tInterPurge.Q THEN
      tInterPurge(IN := FALSE);
      LoadLayer();
      eState := ST_HEAT_RAMP;   (* re-stabilise temp for new layer SP *)
    END_IF;

  ST_VENT:
    bHeaterEnable       := FALSE;
    fbFlowPID.EnableIn  := FALSE;
    fbPressPID.EnableIn := FALSE;
    rMFC_CV             := 0.0;
    rThrottle_CV        := 100.0;
    IF rPressPV < 0.01 THEN
      eState := ST_IDLE;
    END_IF;

  ST_FAULT:
    bHeaterEnable       := FALSE;
    fbFlowPID.EnableIn  := FALSE;
    fbPressPID.EnableIn := FALSE;
    rMFC_CV             := 0.0;
    rThrottle_CV        := 0.0;
    rHeater_CV          := 0.0;

END_CASE;
