```pascal
(* ============================================================
   CVD CHAMBER CONTROL — MUTATION 3 (Add Reasoning)
   Platform : Allen-Bradley ControlLogix Redundancy / Studio 5000
   Standard : IEC 61131-3 Structured Text
   Rev      : 4.0
   Added    : IEC 62443 RBAC + Session Tokens,
              Automatic Redundancy Failover,
              OPC-UA SCADA tag publishing,
              SCADA Historian alarm events
   ============================================================ *)

(* ---------- USER-DEFINED TYPES ---------- *)
TYPE
  eProcState : (
    ST_IDLE, ST_PURGE, ST_HEAT_RAMP, ST_RAMP_FLOW,
    ST_DEPOSIT, ST_INTER_PURGE, ST_VENT, ST_FAULT
  );

  eAccessRole : (ROLE_NONE, ROLE_VIEWER, ROLE_OPERATOR, ROLE_ENGINEER, ROLE_ADMIN);

  tSession : STRUCT
    iSessionID   : DINT;
    eRole        : eAccessRole;
    bValid       : BOOL;
    tExpiry      : TIME;          (* relative countdown *)
    tExpTimer    : TON;
    sUserHash    : STRING[64];    (* SHA-256 HMAC of user+nonce *)
  END_STRUCT;

  tRecipeLayer : STRUCT
    rFlowSP    : REAL;
    rPressSP   : REAL;
    rTempSP    : REAL;
    tDuration  : TIME;
    iMinRole   : INT;             (* minimum role ordinal to modify *)
  END_STRUCT;

  tFaultRecord : STRUCT
    iCode      : INT;
    sDesc      : STRING[64];
    dtStamp    : DATE_AND_TIME;
    eState     : eProcState;
  END_STRUCT;

  tRedundancyStatus : STRUCT
    bPrimaryActive   : BOOL;
    bStandbyOK       : BOOL;
    bFailoverInProg  : BOOL;
    iFailoverCount   : INT;
    tHeartbeatTimer  : TON;
    bHeartbeatMissed : BOOL;
  END_STRUCT;

  tOPCUATag : STRUCT
    sNodeID  : STRING[32];
    rValue   : REAL;
    bDirty   : BOOL;             (* set TRUE to trigger publish *)
  END_STRUCT;
END_TYPE

VAR CONSTANT
  MAX_LAYERS        : INT := 8;
  FAULT_LOG_SZ      : INT := 32;
  MAX_SESSIONS      : INT := 4;
  SESSION_TIMEOUT   : TIME := T#15M;
  HB_INTERVAL       : TIME := T#500MS;
  HB_MISS_LIMIT     : INT  := 3;
  (* Fault codes *)
  FC_NONE           : INT := 0;
  FC_OVERTEMP       : INT := 101;
  FC_FLOW_HIGH      : INT := 102;
  FC_PRESS_HIGH     : INT := 103;
  FC_EMG_STOP       : INT := 104;
  FC_EIP_LOSS       : INT := 105;
  FC_HEAT_WATCHDOG  : INT := 106;
  FC_MSG_TIMEOUT    : INT := 107;
  FC_SEC_VIOLATION  : INT := 201;
  FC_FAILOVER       : INT := 301;
  FC_OPCUA_ERR      : INT := 401;
END_VAR

VAR
  (* --- State & Recipe --- *)
  eState           : eProcState := ST_IDLE;
  aRecipe          : ARRAY [0..7] OF tRecipeLayer;
  iLayerIdx        : INT := 0;
  iTotalLayers     : INT := 3;

  (* --- Process Variables --- *)
  rFlowPV, rPressPV, rTempPV : REAL;
  rMFC_CV, rThrottle_CV, rHeater_CV : REAL;
  rTempSP_Active   : REAL;

  (* --- PID Blocks --- *)
  fbFlowPID, fbPressPID, fbTempPID : PIDE;
  rFlow_KP  : REAL := 1.2; rFlow_KI  : REAL := 0.5; rFlow_KD  : REAL := 0.05;
  rPress_KP : REAL := 2.0; rPress_KI : REAL := 0.8; rPress_KD : REAL := 0.10;
  rTemp_KP  : REAL := 3.5; rTemp_KI  : REAL := 0.1; rTemp_KD  : REAL := 0.2;

  (* --- Heater --- *)
  rTempMaxLimit    : REAL := 700.0;
  bOverTempLatch   : BOOL := FALSE;
  bHeaterEnable    : BOOL := FALSE;

  (* --- Timers --- *)
  tPurge, tHeatRamp, tDeposit, tInterPurge : TON;

  (* --- Interlocks --- *)
  bEmgStop         : BOOL := FALSE;

  (* --- IEC 62443 Security --- *)
  aSessions        : ARRAY [0..3] OF tSession;
  iSecViolations   : INT := 0;
  bSecLockout      : BOOL := FALSE;
  iCommandNonce    : DINT := 0;          (* monotonic nonce counter *)
  sLastCmdHash     : STRING[64];
  bCmdAuthenticated: BOOL := FALSE;

  (* --- Redundancy --- *)
  stRedund         : tRedundancyStatus;
  iHBMissCount     : INT := 0;
  msgHB_Send       : MESSAGE;            (* heartbeat to standby *)
  msgHB_Recv       : MESSAGE;            (* heartbeat from standby *)
  bForceFailover   : BOOL := FALSE;      (* operator-triggered *)

  (* --- OPC-UA Publishing --- *)
  aOPCTags         : ARRAY [0..7] OF tOPCUATag;
  msgOPCUA         : MESSAGE;
  tOPCPublishTimer : TON;
  bOPCUA_Error     : BOOL := FALSE;

  (* --- Fault subsystem --- *)
  aFaultLog        : ARRAY [0..31] OF tFaultRecord;
  iFaultHead       : INT := 0;
  iFaultCount      : INT := 0;
  iActiveFaultCode : INT := FC_NONE;
  bFaultAck        : BOOL := FALSE;

  (* Scratch *)
  i                : INT;
  rMaxFlow         : REAL := 200.0;
  rMaxPress        : REAL := 10.0;
END_VAR

(* ============================================================
   ACTION: IEC 62443 — Validate session token before any command
   ============================================================ *)
ACTION SEC_ValidateSession:
  (* Called with iSessionID and required eRole as input params via
     convention: caller sets scratch vars iCheckID, eCheckRole *)
  bCmdAuthenticated := FALSE;
  FOR i := 0 TO MAX_SESSIONS - 1 DO
    IF aSessions[i].iSessionID = iCommandNonce
       AND aSessions[i].bValid
       AND (INT_TO_DINT(aSessions[i].eRole) >= INT_TO_DINT(ROLE_OPERATOR))
    THEN
      (* Validate HMAC token — compare stored hash *)
      IF aSessions[i].sUserHash = sLastCmdHash THEN
        bCmdAuthenticated := TRUE;
      END_IF;
    END_IF;
  END_FOR;
  IF NOT bCmdAuthenticated THEN
    iSecViolations := iSecViolations + 1;
    IF iSecViolations >= 5 THEN
      bSecLockout := TRUE;
      iActiveFaultCode := FC_SEC_VIOLATION;
      (* LogFault() called from main *)
      eState := ST_FAULT;
    END_IF;
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Session expiry management
   ============================================================ *)
ACTION SEC_ManageSessions:
  FOR i := 0 TO MAX_SESSIONS - 1 DO
    IF aSessions[i].bValid THEN
      aSessions[i].tExpTimer(IN := TRUE, PT := SESSION_TIMEOUT);
      IF aSessions[i].tExpTimer.Q THEN
        aSessions[i].bValid    := FALSE;
        aSessions[i].eRole     := ROLE_NONE;
        aSessions[i].iSessionID:= 0;
        aSessions[i].tExpTimer(IN := FALSE);
      END_IF;
    END_IF;
  END_FOR;
END_ACTION

(* ============================================================
   ACTION: Redundancy — heartbeat & failover
   ============================================================ *)
ACTION Redundancy_Manager:
  (* Send heartbeat to standby *)
  stRedund.tHeartbeatTimer(IN := TRUE, PT := HB_INTERVAL);
  IF stRedund.tHeartbeatTimer.Q THEN
    stRedund.tHeartbeatTimer(IN := FALSE);
    IF NOT msgHB_Send.EN THEN
      msgHB_Send.EN := TRUE;
    END_IF;
    (* Check if standby heartbeat received *)
    IF NOT msgHB_Recv.DN THEN
      iHBMissCount := iHBMissCount + 1;
    ELSE
      iHBMissCount := 0;
      stRedund.bStandbyOK := TRUE;
      msgHB_Recv.EN := FALSE;
    END_IF;
    IF iHBMissCount >= HB_MISS_LIMIT THEN
      stRedund.bStandbyOK := FALSE;
    END_IF;
  END_IF;

  (* Failover decision: primary faults AND standby is healthy *)
  IF (eState = ST_FAULT OR bForceFailover)
     AND stRedund.bStandbyOK
     AND stRedund.bPrimaryActive
  THEN
    stRedund.bFailoverInProg := TRUE;
    stRedund.bPrimaryActive  := FALSE;
    stRedund.iFailoverCount  := stRedund.iFailoverCount + 1;
    iActiveFaultCode := FC_FAILOVER;
    (* Transfer crosslink data to standby via MSG *)
    (* Standby PLC takes control automatically via Logix redundancy *)
    (* module — MSC command triggers switchover *)
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Fault log
   ============================================================ *)
ACTION LogFault:
  aFaultLog[iFaultHead].iCode  := iActiveFaultCode;
  aFaultLog[iFaultHead].eState := eState;
  iFaultHead := (iFaultHead + 1) MOD FAULT_LOG_SZ;
  IF iFaultCount < FAULT_LOG_SZ THEN iFaultCount := iFaultCount + 1; END_IF;
END_ACTION

(* ============================================================
   ACTION: OPC-UA — Publish tags to SCADA historian
   ============================================================ *)
ACTION OPCUA_Publish:
  (* Update tag values every 1 s *)
  tOPCPublishTimer(IN := TRUE, PT := T#1S);
  IF tOPCPublishTimer.Q THEN
    tOPCPublishTimer(IN := FALSE);
    (* Map process values into OPC-UA node array *)
    aOPCTags[0].sNodeID := 'ns=2;s=CVD.FlowPV';    aOPCTags[0].rValue := rFlowPV;    aOPCTags[0].bDirty := TRUE;
    aOPCTags[1].sNodeID := 'ns=2;s=CVD.PressPV';   aOPCTags[1].rValue := rPressPV;   aOPCTags[1].bDirty := TRUE;
    aOPCTags[2].sNodeID := 'ns=2;s=CVD.TempPV';    aOPCTags[2].rValue := rTempPV;    aOPCTags[2].bDirty := TRUE;
    aOPCTags[3].sNodeID := 'ns=2;s=CVD.MFC_CV';    aOPCTags[3].rValue := rMFC_CV;    aOPCTags[3].bDirty := TRUE;
    aOPCTags[4].sNodeID := 'ns=2;s=CVD.ThrottleCV';aOPCTags[4].rValue := rThrottle_CV;aOPCTags[4].bDirty := TRUE;
    aOPCTags[5].sNodeID := 'ns=2;s=CVD.HeaterCV';  aOPCTags[5].rValue := rHeater_CV; aOPCTags[5].bDirty := TRUE;
    aOPCTags[6].sNodeID := 'ns=2;s=CVD.FaultCode'; aOPCTags[6].rValue := INT_TO_REAL(iActiveFaultCode); aOPCTags[6].bDirty := TRUE;
    aOPCTags[7].sNodeID := 'ns=2;s=CVD.LayerIdx';  aOPCTags[7].rValue := INT_TO_REAL(iLayerIdx); aOPCTags[7].bDirty := TRUE;

    (* Trigger MSG to OPC-UA server gateway (e.g. KEPServer) *)
    IF NOT msgOPCUA.EN THEN
      msgOPCUA.MessageType := MESSAGE_CIP_GENERIC;
      msgOPCUA.EN := TRUE;
    END_IF;
    IF msgOPCUA.ER THEN
      bOPCUA_Error := TRUE;
      iActiveFaultCode := FC_OPCUA_ERR;
      LogFault();
    ELSIF msgOPCUA.DN THEN
      bOPCUA_Error := FALSE;
      msgOPCUA.EN := FALSE;
    END_IF;
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Heater
   ============================================================ *)
ACTION HeaterControl:
  IF rTempPV >= rTempMaxLimit THEN bOverTempLatch := TRUE; END_IF;
  IF bOverTempLatch THEN
    bHeaterEnable := FALSE; rHeater_CV := 0.0;
    fbTempPID.EnableIn := FALSE;
    iActiveFaultCode := FC_OVERTEMP; LogFault();
    eState := ST_FAULT; RETURN;
  END_IF;
  IF bHeaterEnable THEN
    fbTempPID.SP := rTempSP_Active; fbTempPID.PV := rTempPV;
    fbTempPID.Kp := rTemp_KP; fbTempPID.Ki := rTemp_KI; fbTempPID.Kd := rTemp_KD;
    fbTempPID.EnableIn := TRUE; fbTempPID.CVEU_HI := 100.0; fbTempPID.CVEU_LO := 0.0;
    fbTempPID(); rHeater_CV := fbTempPID.CV;
  ELSE
    fbTempPID.EnableIn := FALSE; rHeater_CV := 0.0;
  END_IF;
END_ACTION

ACTION LoadLayer:
  IF iLayerIdx < iTotalLayers THEN
    fbFlowPID.SP := aRecipe[iLayerIdx].rFlowSP;
    fbPressPID.SP:= aRecipe[iLayerIdx].rPressSP;
    rTempSP_Active := aRecipe[iLayerIdx].rTempSP;
  END_IF;
END_ACTION

(* ============================================================
   MAIN SCAN
   ============================================================ *)
SEC_ManageSessions();
Redundancy_Manager();
HeaterControl();
OPCUA_Publish();

IF bEmgStop THEN
  iActiveFaultCode := FC_EMG_STOP; LogFault(); eState := ST_FAULT;
END_IF;
IF rFlowPV > rMaxFlow THEN
  iActiveFaultCode := FC_FLOW_HIGH; LogFault(); eState := ST_FAULT;
END_IF;
IF rPressPV > rMaxPress THEN
  iActiveFaultCode := FC_PRESS_HIGH; LogFault(); eState := ST_FAULT;
END_IF;
IF bSecLockout THEN
  LogFault(); eState := ST_FAULT;
END_IF;

IF bFaultAck AND (eState = ST_FAULT)
   AND (iActiveFaultCode <> FC_OVERTEMP)
   AND (iActiveFaultCode <> FC_SEC_VIOLATION)
THEN
  bOverTempLatch := FALSE; iActiveFaultCode := FC_NONE;
  eState := ST_IDLE; bFaultAck := FALSE;
END_IF;

CASE eState OF
  ST_IDLE:
    bHeaterEnable := FALSE;
    fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 0.0; iLayerIdx := 0;

  ST_PURGE:
    rMFC_CV := 0.0; rThrottle_CV := 50.0;
    tPurge(IN := TRUE, PT := T#60S);
    IF tPurge.Q THEN
      tPurge(IN := FALSE); bHeaterEnable := TRUE; LoadLayer();
      eState := ST_HEAT_RAMP;
    END_IF;

  ST_HEAT_RAMP:
    IF ABS(rTempPV - rTempSP_Active) <= 2.0 THEN
      tHeatRamp(IN := FALSE); eState := ST_RAMP_FLOW;
    END_IF;
    tHeatRamp(IN := TRUE, PT := T#1800S);
    IF tHeatRamp.Q THEN
      iActiveFaultCode := FC_HEAT_WATCHDOG; LogFault(); eState := ST_FAULT;
    END_IF;

  ST_RAMP_FLOW:
    rMFC_CV := rMFC_CV + 1.0;
    IF rMFC_CV > 100.0 THEN rMFC_CV := 100.0; END_IF;
    IF rFlowPV >= (aRecipe[iLayerIdx].rFlowSP * 0.95) THEN eState := ST_DEPOSIT; END_IF;

  ST_DEPOSIT:
    fbFlowPID.PV := rFlowPV; fbFlowPID.Kp := rFlow_KP; fbFlowPID.Ki := rFlow_KI; fbFlowPID.Kd := rFlow_KD;
    fbFlowPID.EnableIn := TRUE; fbFlowPID.CVEU_HI := 100.0; fbFlowPID.CVEU_LO := 0.0; fbFlowPID();
    rMFC_CV := fbFlowPID.CV;
    fbPressPID.PV := rPressPV; fbPressPID.Kp := rPress_KP; fbPressPID.Ki := rPress_KI; fbPressPID.Kd := rPress_KD;
    fbPressPID.EnableIn := TRUE; fbPressPID.CVEU_HI := 100.0; fbPressPID.CVEU_LO := 0.0; fbPressPID();
    rThrottle_CV := fbPressPID.CV;
    tDeposit(IN := TRUE, PT := aRecipe[iLayerIdx].tDuration);
    IF tDeposit.Q THEN
      tDeposit(IN := FALSE); fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
      iLayerIdx := iLayerIdx + 1;
      IF iLayerIdx < iTotalLayers THEN eState := ST_INTER_PURGE;
      ELSE eState := ST_VENT; END_IF;
    END_IF;

  ST_INTER_PURGE:
    rMFC_CV := 0.0; rThrottle_CV := 50.0;
    tInterPurge(IN := TRUE, PT := T#30S);
    IF tInterPurge.Q THEN
      tInterPurge(IN := FALSE); LoadLayer(); eState := ST_HEAT_RAMP;
    END_IF;

  ST_VENT:
    bHeaterEnable := FALSE; fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 100.0;
    IF rPressPV < 0.01 THEN eState := ST_IDLE; END_IF;

  ST_FAULT:
    bHeaterEnable := FALSE; fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 0.0; rHeater_CV := 0.0;

END_CASE;
