```scl
FUNCTION_BLOCK FB_WaferCMP_Breadth
VAR_INPUT
    Start_CMP : Bool;
    Wafer_Present : Bool;
    Setpoint_Slurry_Flow : Real;
    Setpoint_Platen_Pressure : Real;
    Actual_Slurry_Flow : Real;
    Actual_Platen_Pressure : Real;
    Profinet_Status : Word;
    Drive_Fault : Bool;
END_VAR
VAR_OUTPUT
    Cmd_Slurry_Pump : Real;
    Cmd_Platen_Pneumatic : Real;
    CMP_Active : Bool;
    Profinet_Control_Word : Word;
    Fault_Active : Bool;
    Fault_Code : Int;
END_VAR
VAR
    PID_Slurry : PID_Compact;
    PID_Platen : PID_Compact;
    Comm_Timeout : TON;
END_VAR

BEGIN
    // Diagnostics and Profinet Comms
    Comm_Timeout(IN := (Profinet_Status = 16#0000), PT := T#1S);

    IF Comm_Timeout.Q THEN
        Fault_Active := TRUE;
        Fault_Code := 101; // Comm Loss
    ELSIF Drive_Fault THEN
        Fault_Active := TRUE;
        Fault_Code := 102; // Drive Error
    ELSE
        Fault_Active := FALSE;
        Fault_Code := 0;
    END_IF;

    IF Start_CMP AND Wafer_Present AND NOT Fault_Active THEN
        CMP_Active := TRUE;
        Profinet_Control_Word := 16#047F; // Run Command
    ELSE
        CMP_Active := FALSE;
        Profinet_Control_Word := 16#047E; // Stop Command
    END_IF;

    PID_Slurry(Setpoint := Setpoint_Slurry_Flow, Input := Actual_Slurry_Flow, Run := CMP_Active, Output => Cmd_Slurry_Pump);
    PID_Platen(Setpoint := Setpoint_Platen_Pressure, Input := Actual_Platen_Pressure, Run := CMP_Active, Output => Cmd_Platen_Pneumatic);

END_FUNCTION_BLOCK
