    Kp_Stage : LREAL := 10.0;
    Kd_Stage : LREAL := 0.1;
    fWaferPrevError : LREAL;
    fWaferError : LREAL;
END_VAR

IF bEnableReticle AND bEnableWafer THEN
    fWaferPosSP := fReticlePosSP / -4.0;
    fWaferError := fWaferPosSP - fWaferPosAct;
    fWaferVel := (fWaferError * Kp_Stage) + ((fWaferError - fWaferPrevError) * Kd_Stage);
    fWaferPrevError := fWaferError;
    fReticleVel := (fReticlePosSP - fReticlePosAct) * Kp_Stage;
    fSyncError := ABS(fWaferPosAct - (fReticlePosAct / -4.0));
    bSyncAchieved := fSyncError < 0.0001;
ELSE
    fWaferVel := 0.0;
    fReticleVel := 0.0;
    bSyncAchieved := FALSE;
END_IF

IF bSyncAchieved AND bEnablePiezo THEN
    fPiezoVolSP := fPiezoVolAct + ((fPiezoVolSP - fPiezoVolAct) * 0.5);
END_IF
