Here is an advanced IEC 61131-3 (Structured Text) implementation for a Multi-Zone Routing Sorter. 

It evolves a basic conveyor logic into a highly complex, production-ready system by introducing:
1. **Hardware Abstraction Layer (HAL)**: Encapsulates all I/O, preventing the core logic from being tied to specific hardware addresses.
2. **Safety Interlocks**: Monitors E-Stops, Thermal Overloads, and Motor Contactor Feedback, halting operation securely.
3. **Anti-Jam Detection**: Leverages timers across multiple zones to identify blocked photoeyes and trigger jam faults.
4. **Complex State Machine**: Manages the operational states (Init, Ready, Feeding, Scanning, Diverting, Fault) and handles the barcode scanner interface and routing logic.

```pascal
TYPE "UDT_Sorter_HW_IO"
    STRUCT
        // Inputs
        iEStop_OK          : BOOL; // TRUE = E-Stop circuit healthy
        iThermalOverload   : BOOL; // TRUE = Motor thermal overload tripped
        iMotorContactorFB  : BOOL; // Motor contactor auxiliary feedback
        iPE_Zone1_Entry    : BOOL; // Photoeye: Zone 1 Entry
        iPE_Zone2_Scan     : BOOL; // Photoeye: Zone 2 Barcode Scanner
        iPE_Zone3_Divert   : BOOL; // Photoeye: Zone 3 Diverter Lane
        iBarcodeDataValid  : BOOL; // Scanner signal: Data valid
        iBarcodeData       : DINT; // Scanned destination code

        // Outputs
        qMotorRunCmd       : BOOL; // Command to run main conveyor motor
        qDiverterCmd       : BOOL; // Command to actuate pneumatic diverter
        qScannerTrigger    : BOOL; // Trigger signal for barcode scanner
        qAlarmHorn         : BOOL; // General fault alarm horn
    END_STRUCT;
END_TYPE

TYPE "UDT_ZoneStatus"
    STRUCT
        PackagePresent : BOOL;
        JamDetected    : BOOL;
        MotorRunning   : BOOL;
        DiverterActive : BOOL;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "FB_AdvancedRoutingSorter"
TITLE = 'Multi-Zone Routing Sorter'
AUTHOR : 'Lumina Elite'
FAMILY : 'MaterialHandling'
VERSION : '3.0'

//=============================================================================
//  DESCRIPTION:
//  This function block controls a multi-zone conveyor routing sorter. It 
//  features hardware abstraction for I/O, safety interlocks, anti-jam timers, 
//  a barcode scanning interface, and a deterministic state machine for routing.
//=============================================================================

VAR_INPUT
    xEnable          : BOOL;   // System Enable command
    xReset           : BOOL;   // Reset faults and alarms
END_VAR

VAR_IN_OUT
    hwIO             : "UDT_Sorter_HW_IO"; // Hardware Abstraction Layer
END_VAR

VAR_OUTPUT
    xSystemReady     : BOOL;   // System is ready and fault-free
    xActiveFault     : BOOL;   // Any active fault present
    iCurrentState    : INT;    // State Machine Current State
    ZoneStatus       : ARRAY[1..3] OF "UDT_ZoneStatus"; // HMI telemetry
END_VAR

VAR
    // State Machine Enumerations
    STAT_INIT        : INT := 0;
    STAT_READY       : INT := 10;
    STAT_FEEDING     : INT := 20;
    STAT_SCANNING    : INT := 30;
    STAT_DIVERTING   : INT := 40;
    STAT_FAULT       : INT := 99;

    // Internal States
    iState           : INT;
    xSafetyOK        : BOOL;
    xJamFault        : BOOL;
    xHwFault         : BOOL;

    // Timers
    tonJamZone1      : TON; // Anti-jam timer for Zone 1
    tonJamZone2      : TON; // Anti-jam timer for Zone 2
    tonJamZone3      : TON; // Anti-jam timer for Zone 3
    tonMotorFB       : TON; // Motor contactor feedback timer
    tonDiverterHold  : TON; // Hold time for diverter mechanism

    // Data Storage
    dScannedDest     : DINT;
END_VAR

BEGIN
    // =====================================================================
    // 1. SAFETY & HARDWARE INTERLOCKS
    // =====================================================================
    // E-Stop must be healthy and thermal overload must NOT be tripped.
    xSafetyOK := hwIO.iEStop_OK AND NOT hwIO.iThermalOverload;

    // Contactor Feedback Monitoring (2s allowance for auxiliary contact closure)
    tonMotorFB(IN := hwIO.qMotorRunCmd AND NOT hwIO.iMotorContactorFB, PT := T#2s);

    IF NOT xSafetyOK OR tonMotorFB.Q THEN
        xHwFault := TRUE;
    END_IF;

    // =====================================================================
    // 2. ANTI-JAM DETECTION (Timeouts if photoeye blocked too long)
    // =====================================================================
    // If a motor is running but a photoeye remains blocked, a jam occurred.
    tonJamZone1(IN := hwIO.iPE_Zone1_Entry AND hwIO.qMotorRunCmd, PT := T#5s);
    tonJamZone2(IN := hwIO.iPE_Zone2_Scan  AND hwIO.qMotorRunCmd, PT := T#5s);
    tonJamZone3(IN := hwIO.iPE_Zone3_Divert AND hwIO.qMotorRunCmd,PT := T#7s);

    IF tonJamZone1.Q OR tonJamZone2.Q OR tonJamZone3.Q THEN
        xJamFault := TRUE;
    END_IF;

    // Fault Aggregation
    xActiveFault := xHwFault OR xJamFault;

    // Fault Reset Logic (requires trailing edge or level reset depending on spec)
    IF xReset THEN
        xJamFault := FALSE;
        IF xSafetyOK THEN
            xHwFault := FALSE;
        END_IF;
    END_IF;

    // =====================================================================
    // 3. DETERMINISTIC STATE MACHINE
    // =====================================================================
    IF xActiveFault THEN
        iState := STAT_FAULT;
    END_IF;

    CASE iState OF
        STAT_INIT:
            // Safe initialization state, all outputs off
            hwIO.qMotorRunCmd    := FALSE;
            hwIO.qDiverterCmd    := FALSE;
            hwIO.qScannerTrigger := FALSE;

            IF xEnable AND NOT xActiveFault THEN
                iState := STAT_READY;
            END_IF;

        STAT_READY:
            xSystemReady := TRUE;
            hwIO.qMotorRunCmd := TRUE; // Start main transport
            hwIO.qDiverterCmd := FALSE;
            hwIO.qScannerTrigger := FALSE;

            // Package entry detected
            IF hwIO.iPE_Zone1_Entry THEN
                iState := STAT_FEEDING;
            END_IF;

            IF NOT xEnable THEN
                iState := STAT_INIT;
            END_IF;

        STAT_FEEDING:
            // Package reaches Zone 2 (Scanner threshold)
            IF hwIO.iPE_Zone2_Scan THEN
                hwIO.qScannerTrigger := TRUE;
                iState := STAT_SCANNING;
            END_IF;

        STAT_SCANNING:
            // Await valid barcode payload from the scanner module
            IF hwIO.iBarcodeDataValid THEN
                dScannedDest := hwIO.iBarcodeData;
                hwIO.qScannerTrigger := FALSE;

                // Routing Logic: Destination 999 requires diverting, others pass-through
                IF dScannedDest = 999 THEN
                    iState := STAT_DIVERTING;
                ELSE
                    iState := STAT_READY; 
                END_IF;
            END_IF;

        STAT_DIVERTING:
            // Actuate diverter pneumatics once the package reaches Zone 3
            IF hwIO.iPE_Zone3_Divert THEN
                hwIO.qDiverterCmd := TRUE;
            END_IF;

            // Hold diverter output to allow physical actuation to complete
            tonDiverterHold(IN := hwIO.qDiverterCmd, PT := T#3s);
            IF tonDiverterHold.Q THEN
                hwIO.qDiverterCmd := FALSE;
                iState := STAT_READY;
            END_IF;

        STAT_FAULT:
            // Isolate hazards and sound alarms
            xSystemReady := FALSE;
            hwIO.qMotorRunCmd    := FALSE;
            hwIO.qDiverterCmd    := FALSE;
            hwIO.qScannerTrigger := FALSE;
            hwIO.qAlarmHorn      := TRUE;

            IF NOT xActiveFault THEN
                hwIO.qAlarmHorn := FALSE;
                iState := STAT_INIT;
            END_IF;

    END_CASE;

    // =====================================================================
    // 4. ZONE STATUS TELEMETRY (For HMI/SCADA/OPC UA Mapping)
    // =====================================================================
    iCurrentState := iState;

    // Zone 1 Mapping
    ZoneStatus[1].PackagePresent := hwIO.iPE_Zone1_Entry;
    ZoneStatus[1].JamDetected    := tonJamZone1.Q;
    ZoneStatus[1].MotorRunning   := hwIO.qMotorRunCmd AND hwIO.iMotorContactorFB;
    ZoneStatus[1].DiverterActive := FALSE;

    // Zone 2 Mapping
    ZoneStatus[2].PackagePresent := hwIO.iPE_Zone2_Scan;
    ZoneStatus[2].JamDetected    := tonJamZone2.Q;
    ZoneStatus[2].MotorRunning   := hwIO.qMotorRunCmd AND hwIO.iMotorContactorFB;
    ZoneStatus[2].DiverterActive := FALSE;

    // Zone 3 Mapping
    ZoneStatus[3].PackagePresent := hwIO.iPE_Zone3_Divert;
    ZoneStatus[3].JamDetected    := tonJamZone3.Q;
    ZoneStatus[3].MotorRunning   := hwIO.qMotorRunCmd AND hwIO.iMotorContactorFB;
    ZoneStatus[3].DiverterActive := hwIO.qDiverterCmd;

END_FUNCTION_BLOCK
```

(*
================================================================================
Function Block: FB_ReactorTempCascadeCtrl
Author: Lumina Elite Synthetic Data Architect
Description: 
Complex cascade PID temperature control loop for a chemical reactor.
Features include:
1. Deadband filtering for analog scaling (hardware abstraction).
2. Cascade Control: Primary (Reactor Temp) sets Secondary (Jacket Temp) setpoint.
3. Advanced State Machine: INIT, HEAT_UP, STEADY_STATE, COOL_DOWN, SAFE_STOP, FAULT.
4. Safety Interlocks: E-Stop, Thermal Overloads, and Coolant Flow monitoring.

Hardware Abstraction Concept:
Raw byte signals from field instruments are filtered through a deadband
and scaled into physical engineering units (Real).
================================================================================
*)

TYPE E_ReactorState :
(
    STATE_INIT := 0,
    STATE_HEAT_UP := 10,
    STATE_STEADY_STATE := 20,
    STATE_COOL_DOWN := 30,
    STATE_SAFE_STOP := 40,
    STATE_FAULT := 99
);
END_TYPE

FUNCTION_BLOCK FB_ReactorTempCascadeCtrl
VAR_INPUT
    // Hardware Abstraction Layer - Raw Inputs
    bRawReactorTemp     : BYTE; // 0-255 mapped to 0.0 - 200.0 C
    bRawJacketTemp      : BYTE; // 0-255 mapped to 0.0 - 150.0 C
    bRawCoolantFlow     : BYTE; // 0-255 mapped to 0.0 - 100.0 L/min

    // Safety Interlocks
    xEmergencyStop      : BOOL; // TRUE = Healthy, FALSE = Tripped
    xThermalOverload    : BOOL; // TRUE = Tripped, FALSE = Healthy

    // Operational Commands
    xCmdStart           : BOOL;
    xCmdStop            : BOOL;
    rPrimarySetpoint    : REAL; // Target Reactor Temperature (C)

    // Tuning Parameters
    rDeadband           : REAL := 0.5;
END_VAR

VAR_OUTPUT
    // Hardware Abstraction Layer - Raw Outputs
    rSteamValveCmd      : REAL; // 0.0 - 100.0 %
    rCoolantValveCmd    : REAL; // 0.0 - 100.0 %

    // Status
    eCurrentState       : E_ReactorState;
    xAlarmActive        : BOOL;
    sStatusMsg          : STRING(50);
END_VAR

VAR
    // Internal Scaled Values
    rReactorTemp        : REAL;
    rJacketTemp         : REAL;
    rCoolantFlow        : REAL;

    // Previous Values for Deadband Filtering
    rPrevReactorTemp    : REAL;
    rPrevJacketTemp     : REAL;

    // PID Controllers (Abstracted standard instances)
    fbPrimaryPID        : FB_StandardPID; // Reactor Temp -> Jacket Temp SP
    fbSecondaryPID      : FB_StandardPID; // Jacket Temp -> Valve Output

    rJacketTempSP       : REAL; // Output of primary PID
    rSecondaryOutput    : REAL; // Output of secondary PID (-100% to +100%)

    // Timers
    tonHeatUpTimeout    : TON;
    tonCoolDownDelay    : TON;

    // State Tracking
    eNextState          : E_ReactorState;
END_VAR

VAR CONSTANT
    CRIT_TEMP_LIMIT     : REAL := 180.0; // Critical temperature threshold
    MIN_COOLANT_FLOW    : REAL := 10.0;  // Minimum safe flow rate
END_VAR

// ==============================================================================
// 1. HARDWARE ABSTRACTION & DEADBAND FILTERING
// ==============================================================================
// Helper inline scaling logic based on the original SCALE_B concept
rReactorTemp := SCALE_BYTE_TO_REAL(bRawReactorTemp, 0, 255, 0.0, 200.0);
IF ABS(rReactorTemp - rPrevReactorTemp) < rDeadband THEN
    rReactorTemp := rPrevReactorTemp; // Apply deadband
ELSE
    rPrevReactorTemp := rReactorTemp;
END_IF

rJacketTemp := SCALE_BYTE_TO_REAL(bRawJacketTemp, 0, 255, 0.0, 150.0);
IF ABS(rJacketTemp - rPrevJacketTemp) < rDeadband THEN
    rJacketTemp := rPrevJacketTemp;
ELSE
    rPrevJacketTemp := rJacketTemp;
END_IF

rCoolantFlow := SCALE_BYTE_TO_REAL(bRawCoolantFlow, 0, 255, 0.0, 100.0);

// ==============================================================================
// 2. SAFETY INTERLOCKS EVALUATION
// ==============================================================================
IF NOT xEmergencyStop OR xThermalOverload OR (rReactorTemp > CRIT_TEMP_LIMIT) THEN
    eNextState := STATE_FAULT;
    sStatusMsg := 'CRITICAL SAFETY TRIP - E-STOP/OVERLOAD';
END_IF

// ==============================================================================
// 3. MAIN STATE MACHINE
// ==============================================================================
CASE eCurrentState OF

    STATE_INIT:
        rSteamValveCmd   := 0.0;
        rCoolantValveCmd := 100.0; // Fail-safe cooling
        fbPrimaryPID.xReset := TRUE;
        fbSecondaryPID.xReset := TRUE;
        xAlarmActive := FALSE;
        sStatusMsg := 'System Initialized. Awaiting Start.';

        IF xCmdStart AND NOT (eNextState = STATE_FAULT) THEN
            eNextState := STATE_HEAT_UP;
        END_IF

    STATE_HEAT_UP:
        fbPrimaryPID.xReset := FALSE;
        fbSecondaryPID.xReset := FALSE;
        sStatusMsg := 'Heating Up Reactor...';

        // Check if we reached steady state condition
        IF ABS(rReactorTemp - rPrimarySetpoint) <= 2.0 THEN
            eNextState := STATE_STEADY_STATE;
        END_IF

        IF xCmdStop THEN eNextState := STATE_COOL_DOWN; END_IF

    STATE_STEADY_STATE:
        sStatusMsg := 'Reactor in Steady State';

        IF xCmdStop THEN eNextState := STATE_COOL_DOWN; END_IF

        // Monitoring for excessive deviation
        IF ABS(rReactorTemp - rPrimarySetpoint) > 10.0 THEN
            xAlarmActive := TRUE;
            sStatusMsg := 'Warning: Temp Deviation High';
        ELSE
            xAlarmActive := FALSE;
        END_IF

    STATE_COOL_DOWN:
        sStatusMsg := 'Cooling Down Sequence';
        // Override cascade, force cooling
        rJacketTempSP := 20.0; // Safe jacket temperature

        // Delay for full cooling before safe stop
        tonCoolDownDelay(IN:=TRUE, PT:=T#5M);
        IF tonCoolDownDelay.Q OR rReactorTemp < 30.0 THEN
            eNextState := STATE_SAFE_STOP;
            tonCoolDownDelay(IN:=FALSE);
        END_IF

    STATE_SAFE_STOP:
        rSteamValveCmd := 0.0;
        rCoolantValveCmd := 0.0;
        fbPrimaryPID.xReset := TRUE;
        fbSecondaryPID.xReset := TRUE;
        sStatusMsg := 'Safe Stop Achieved';

        IF NOT xCmdStart THEN
            eNextState := STATE_INIT;
        END_IF

    STATE_FAULT:
        xAlarmActive := TRUE;
        // Fail-safe logic
        rSteamValveCmd := 0.0;
        rCoolantValveCmd := 100.0; // Max cooling immediately
        fbPrimaryPID.xReset := TRUE;
        fbSecondaryPID.xReset := TRUE;

        IF xEmergencyStop AND NOT xThermalOverload AND (rReactorTemp < CRIT_TEMP_LIMIT) AND xCmdStop THEN
            eNextState := STATE_INIT; // Reset fault via stop command when safe
            sStatusMsg := 'Fault Cleared. Awaiting Reset.';
        END_IF

END_CASE

// Update state
eCurrentState := eNextState;

// ==============================================================================
// 4. CASCADE PID EXECUTION
// ==============================================================================
// Only active in Heat Up or Steady State
IF (eCurrentState = STATE_HEAT_UP) OR (eCurrentState = STATE_STEADY_STATE) THEN

    // Primary Loop: Reactor Temp (PV) -> Jacket Temp Setpoint (CV)
    fbPrimaryPID(
        rPV := rReactorTemp,
        rSP := rPrimarySetpoint,
        rKp := 2.5,
        rKi := 0.1,
        rKd := 0.5,
        rMinOut := 10.0,
        rMaxOut := 140.0,
        rCV => rJacketTempSP
    );

END_IF

// Secondary Loop always active unless reset (follows forced rJacketTempSP in COOL_DOWN)
fbSecondaryPID(
    rPV := rJacketTemp,
    rSP := rJacketTempSP,
    rKp := 5.0,
    rKi := 0.2,
    rKd := 0.0,
    rMinOut := -100.0, // -100% means full cooling
    rMaxOut := 100.0,  // +100% means full heating
    rCV => rSecondaryOutput
);

// Split-range output logic based on secondary loop
IF rSecondaryOutput > 0.0 THEN
    rSteamValveCmd   := rSecondaryOutput;
    rCoolantValveCmd := 0.0;
ELSE
    rSteamValveCmd   := 0.0;
    rCoolantValveCmd := ABS(rSecondaryOutput);
END_IF

// Flow interlock for heating
IF rCoolantFlow < MIN_COOLANT_FLOW AND rCoolantValveCmd > 0.0 THEN
    sStatusMsg := 'Warning: Low Coolant Flow';
    xAlarmActive := TRUE;
END_IF

END_FUNCTION_BLOCK

// Internal Helper Function for Scaling
FUNCTION SCALE_BYTE_TO_REAL : REAL
VAR_INPUT
    X, I_LO, I_HI : BYTE;
    O_LO, O_HI : REAL;
END_VAR
IF I_HI = I_LO THEN 
    SCALE_BYTE_TO_REAL := O_LO;
ELSE 
    SCALE_BYTE_TO_REAL := (O_HI - O_LO) / BYTE_TO_REAL(I_HI - I_LO) * BYTE_TO_REAL(LIMIT(I_LO, X, I_HI)); 
END_IF
END_FUNCTION

FUNCTION_BLOCK "EM_PharmaMixer_ISA88"
TITLE = 'ISA-88 Equipment Module: Pharmaceutical Liquid Mixer'
AUTHOR : 'Lumina Elite Architect'
FAMILY : 'BatchControl'
VERSION : '3.1'

// ==============================================================================
// DESCRIPTION:
// Highly complex ISA-88 compliant state machine for a pharmaceutical liquid 
// mixing station. This Equipment Module (EM) orchestrates the dosing, mixing, 
// and transfer of pharmaceutical products while strictly adhering to ISA-88 
// batch states and commanding abstract control modules (CMs).
// It includes rigorous safety interlocks, E-Stop handling, thermal overload 
// monitoring, and valve feedback discrepancy checks.
// ==============================================================================

TYPE
    // ISA-88 State Enum
    "Udt_ISA88_States" : INT (
        IDLE := 1,
        STARTING := 2,
        RUNNING := 3,
        HOLDING := 4,
        HELD := 5,
        UNHOLDING := 6,
        COMPLETING := 7,
        COMPLETE := 8,
        STOPPING := 9,
        STOPPED := 10,
        ABORTING := 11,
        ABORTED := 12
    );
END_TYPE

VAR_INPUT
    // Command Inputs (From Phase/Batch Manager)
    cmdStart      : BOOL;
    cmdHold       : BOOL;
    cmdUnhold     : BOOL;
    cmdStop       : BOOL;
    cmdAbort      : BOOL;
    cmdReset      : BOOL;

    // Safety & Hardware Interlocks
    xEstopOk      : BOOL;  // TRUE = E-Stop is healthy (Not pressed)
    xThermalOk    : BOOL;  // TRUE = Agitator thermal overload healthy
    xTankHighLvl  : BOOL;  // TRUE = Tank is full (High-High Level Switch)
    xTankLowLvl   : BOOL;  // TRUE = Tank is empty (Low-Low Level Switch)

    // Process Parameters
    rTargetMixTime : REAL; // Mix duration in seconds
END_VAR

VAR_OUTPUT
    // Module State
    eCurrentState : "Udt_ISA88_States";
    xFault        : BOOL;
    iFaultCode    : INT;

    // Hardware Abstraction Commands (To Control Modules)
    cmdInletValve  : BOOL; // TRUE = Open Fill Valve
    cmdOutletValve : BOOL; // TRUE = Open Drain Valve
    cmdAgitatorRun : BOOL; // TRUE = Run Mixer
END_VAR

VAR
    // Internal State
    eState        : "Udt_ISA88_States" := 1; // Default to IDLE
    rMixTimer     : REAL := 0.0;
    fbTimer       : TON;
    xSafetyInterlock : BOOL;
END_VAR

BEGIN
    // ==============================================================================
    // 1. SAFETY & INTERLOCK EVALUATION
    // ==============================================================================
    // In a pharmaceutical environment, safety overrides all batch states.
    // If an E-Stop is pressed or a thermal overload trips, we must force an Abort.
    xSafetyInterlock := xEstopOk AND xThermalOk;

    IF NOT xEstopOk THEN
        iFaultCode := 99; // E-Stop pressed
    ELSIF NOT xThermalOk THEN
        iFaultCode := 98; // Motor Thermal Trip
    END_IF;

    IF NOT xSafetyInterlock AND (eState <> 11 AND eState <> 12) THEN
        // Immediately transition to Aborting on safety loss
        eState := 11; // ABORTING
    END_IF;

    // ==============================================================================
    // 2. ISA-88 STATE MACHINE
    // ==============================================================================
    CASE eState OF

        // ----------------------------------------------------------------------
        1: // IDLE
        // ----------------------------------------------------------------------
            // Ensure equipment is in safe default state
            cmdInletValve  := FALSE;
            cmdOutletValve := FALSE;
            cmdAgitatorRun := FALSE;
            rMixTimer      := 0.0;

            IF cmdStart AND xSafetyInterlock THEN
                eState := 2; // STARTING
            END_IF;

        // ----------------------------------------------------------------------
        2: // STARTING
        // ----------------------------------------------------------------------
            // Prepare equipment for dosing
            IF NOT xTankHighLvl THEN
                eState := 3; // RUNNING
            ELSE
                iFaultCode := 10; // Already Full
                eState := 4; // HOLDING
            END_IF;

        // ----------------------------------------------------------------------
        3: // RUNNING
        // ----------------------------------------------------------------------
            // Sequence: Fill -> Mix -> Drain

            IF NOT xTankHighLvl AND rMixTimer = 0.0 THEN
                // Phase 1: Dosing (Filling)
                cmdInletValve  := TRUE;
                cmdAgitatorRun := FALSE;
                cmdOutletValve := FALSE;
            ELSIF xTankHighLvl AND rMixTimer < rTargetMixTime THEN
                // Phase 2: Mixing
                cmdInletValve  := FALSE;
                cmdAgitatorRun := TRUE;
                cmdOutletValve := FALSE;
            ELSIF rMixTimer >= rTargetMixTime AND NOT xTankLowLvl THEN
                // Phase 3: Discharging
                cmdInletValve  := FALSE;
                cmdAgitatorRun := FALSE;
                cmdOutletValve := TRUE;
            ELSIF xTankLowLvl THEN
                // Phase 4: Empty and Done
                cmdOutletValve := FALSE;
                eState := 7; // COMPLETING
            END_IF;

            // External Commands
            IF cmdHold THEN
                eState := 4; // HOLDING
            ELSIF cmdStop THEN
                eState := 9; // STOPPING
            ELSIF cmdAbort THEN
                eState := 11; // ABORTING
            END_IF;

        // ----------------------------------------------------------------------
        4: // HOLDING
        // ----------------------------------------------------------------------
            // Safely pause the process. Close inlet/outlet, keep agitator running 
            // if we are full to prevent product settling/separation.
            cmdInletValve  := FALSE;
            cmdOutletValve := FALSE;
            IF xTankHighLvl THEN
                cmdAgitatorRun := TRUE; 
            ELSE
                cmdAgitatorRun := FALSE;
            END_IF;

            // Transition immediately to HELD
            eState := 5; // HELD

        // ----------------------------------------------------------------------
        5: // HELD
        // ----------------------------------------------------------------------
            // Awaiting operator unhold command
            IF cmdUnhold AND xSafetyInterlock THEN
                eState := 6; // UNHOLDING
            ELSIF cmdStop THEN
                eState := 9; // STOPPING
            ELSIF cmdAbort THEN
                eState := 11; // ABORTING
            END_IF;

        // ----------------------------------------------------------------------
        6: // UNHOLDING
        // ----------------------------------------------------------------------
            // Restore context and return to running
            eState := 3; // RUNNING

        // ----------------------------------------------------------------------
        7: // COMPLETING
        // ----------------------------------------------------------------------
            // Process finished successfully
            cmdInletValve  := FALSE;
            cmdOutletValve := FALSE;
            cmdAgitatorRun := FALSE;
            eState := 8; // COMPLETE

        // ----------------------------------------------------------------------
        8: // COMPLETE
        // ----------------------------------------------------------------------
            // Waiting for Batch Manager to reset the unit
            IF cmdReset THEN
                eState := 1; // IDLE
            END_IF;

        // ----------------------------------------------------------------------
        9: // STOPPING
        // ----------------------------------------------------------------------
            // Controlled shutdown requested by operator
            cmdInletValve  := FALSE;
            cmdOutletValve := FALSE;
            cmdAgitatorRun := FALSE;
            eState := 10; // STOPPED

        // ----------------------------------------------------------------------
        10: // STOPPED
        // ----------------------------------------------------------------------
            IF cmdReset THEN
                eState := 1; // IDLE
            END_IF;

        // ----------------------------------------------------------------------
        11: // ABORTING
        // ----------------------------------------------------------------------
            // Emergency/Rapid shutdown (Hard isolation)
            cmdInletValve  := FALSE;
            cmdOutletValve := FALSE;
            cmdAgitatorRun := FALSE;
            eState := 12; // ABORTED

        // ----------------------------------------------------------------------
        12: // ABORTED
        // ----------------------------------------------------------------------
            // Latched failure state. Requires manual intervention and reset.
            xFault := TRUE;
            IF cmdReset AND xSafetyInterlock THEN
                xFault := FALSE;
                iFaultCode := 0;
                eState := 1; // IDLE
            END_IF;

    END_CASE;

    // ==============================================================================
    // 3. MIX TIMER LOGIC
    // ==============================================================================
    // Only accumulate mix time when in RUNNING state, full, and agitator is ON.
    // 1-second pulse logic (simplified for example, typically use real CPU clock)
    fbTimer(IN := (eState = 3 AND cmdAgitatorRun) AND NOT fbTimer.Q, PT := T#1s);
    IF fbTimer.Q THEN
        rMixTimer := rMixTimer + 1.0;
    END_IF;

    // Map internal state to output
    eCurrentState := eState;

END_FUNCTION_BLOCK

