(*
    ================================================================================
    FB_DeltaRobot_NCI_PickAndPlace
    ================================================================================
    Description:
    Advanced Delta Robot (Spider Robot) Pick-and-Place routine using TwinCAT 3 NC-I.
    Features:
      - NC-I Circular interpolation (G02/G03 or via TwinCAT Kinematic Transformation / NC-I libraries)
      - Dynamic offset tracking for moving conveyors (Conveyor Tracking / Sync)
      - 3D Collision Bounding Box enforcement
      - Comprehensive Safety Interlocks (E-Stop, Thermal, Drives)
      - Complex State Machine for complete pick-and-place lifecycle.

    Notes:
    This block interfaces with the TwinCAT NC-I channel and Kinematics.
    Axes are abstracted via AXIS_REF and NCI channel structures.
    ================================================================================
*)
FUNCTION_BLOCK FB_DeltaRobot_NCI_PickAndPlace
VAR_INPUT
    // Command Inputs
    bEnable                 : BOOL;                 // Enable robot drives and systems
    bStartCycle             : BOOL;                 // Start automated pick-and-place cycle
    bStopCycle              : BOOL;                 // Normal stop after current cycle
    bEStop                  : BOOL;                 // Emergency Stop (NC, TRUE = Safe)
    bReset                  : BOOL;                 // Reset faults

    // Conveyor Tracking Data
    fConveyorPos            : LREAL;                // Current position of the conveyor [mm]
    fConveyorVel            : LREAL;                // Current velocity of the conveyor [mm/s]
    bProductDetected        : BOOL;                 // Trigger when product passes vision/sensor
    fProductOffsetX         : LREAL;                // Product X offset from conveyor datum
    fProductOffsetY         : LREAL;                // Product Y offset from conveyor datum

    // Hardware Abstractions & Safety
    stThermalOverload       : ST_ThermalSensors;    // Delta arm motor thermal status
    stSafetyInterlocks      : ST_SafetyStatus;      // Guard doors, light curtains

    // Pick and Place Targets
    stPlacePos              : ST_Position3D;        // Static drop-off location
    fApproachHeight         : LREAL := 50.0;        // Hover height above target [mm]
    fPickDepth              : LREAL := -5.0;        // Z-depth for picking [mm]
END_VAR

VAR_OUTPUT
    bReady                  : BOOL;
    bActive                 : BOOL;
    bDone                   : BOOL;
    bError                  : BOOL;
    nErrorID                : UDINT;
    eCurrentState           : E_DeltaRobotState;
    bGripperActuate         : BOOL;
END_VAR

VAR_IN_OUT
    // Axis References
    stAxis1                 : AXIS_REF;
    stAxis2                 : AXIS_REF;
    stAxis3                 : AXIS_REF;
    stAxis4                 : AXIS_REF; // Optional rotational axis for tool

    // NC-I Channel Reference
    stNciChannel            : NCTOPLC_NCICHANNEL_REF;
END_VAR

VAR
    // State Machine
    eState                  : E_DeltaRobotState := E_DeltaRobotState.INIT;
    eNextState              : E_DeltaRobotState;

    // Interpolation / Move Blocks (Using TwinCAT Kinematics/NC-I FB abstractions)
    fbPower1                : MC_Power;
    fbPower2                : MC_Power;
    fbPower3                : MC_Power;
    fbPower4                : MC_Power;
    fbReset                 : MC_Reset;

    // Kinematic Transformation & NC-I FBs
    fbGroupEnable           : HLB_GroupEnable; // Hypothetical high-level block for NC-I Group
    fbMoveLinear            : MC_MoveLinearAbsolute;
    fbMoveCircular          : MC_MoveCircularAbsolute;
    fbTrackConveyor         : MC_TrackConveyorBelt; // Sync robot to moving belt

    // Bounding Box Parameters
    stBoundingBoxMin        : ST_Position3D := (X:=-400.0, Y:=-400.0, Z:=-600.0);
    stBoundingBoxMax        : ST_Position3D := (X:=400.0, Y:=400.0, Z:=100.0);

    // Internal Variables
    fCurrentX, fCurrentY, fCurrentZ : LREAL;
    bHardwareSafe           : BOOL;
    fbTonGripper            : TON;
    fSyncPositionX          : LREAL;
    fSyncPositionY          : LREAL;

    // Diagnostic
    sStatusMsg              : STRING(80);
END_VAR

(* --- SAFETY & INTERLOCK EVALUATION --- *)
// Verify all hardware is safe to operate
bHardwareSafe := bEStop AND 
                 stSafetyInterlocks.bDoorsClosed AND 
                 stSafetyInterlocks.bLightCurtainClear AND 
                 NOT stThermalOverload.bMotor1Overtemp AND 
                 NOT stThermalOverload.bMotor2Overtemp AND 
                 NOT stThermalOverload.bMotor3Overtemp;

IF NOT bHardwareSafe AND (eState > E_DeltaRobotState.FAULTED) THEN
    eState := E_DeltaRobotState.FAULTED;
    nErrorID := 16#F001; // Safety interlock broken
    sStatusMsg := 'CRITICAL: Safety interlock breached or E-Stop pressed.';
END_IF

(* --- MAIN STATE MACHINE --- *)
CASE eState OF

    E_DeltaRobotState.INIT:
        bReady := FALSE;
        bActive := FALSE;
        bError := FALSE;
        bGripperActuate := FALSE;
        sStatusMsg := 'Initializing robot group...';

        IF bHardwareSafe THEN
            eState := E_DeltaRobotState.POWER_ON;
        END_IF

    E_DeltaRobotState.POWER_ON:
        // Energize all individual axes
        fbPower1(Axis:=stAxis1, Enable:=bEnable, Enable_Positive:=TRUE, Enable_Negative:=TRUE);
        fbPower2(Axis:=stAxis2, Enable:=bEnable, Enable_Positive:=TRUE, Enable_Negative:=TRUE);
        fbPower3(Axis:=stAxis3, Enable:=bEnable, Enable_Positive:=TRUE, Enable_Negative:=TRUE);
        fbPower4(Axis:=stAxis4, Enable:=bEnable, Enable_Positive:=TRUE, Enable_Negative:=TRUE);

        IF fbPower1.Status AND fbPower2.Status AND fbPower3.Status AND fbPower4.Status THEN
            eState := E_DeltaRobotState.ENABLE_GROUP;
        ELSIF NOT bEnable THEN
            eState := E_DeltaRobotState.INIT;
        END_IF

    E_DeltaRobotState.ENABLE_GROUP:
        // Enable kinematic transformation / NC-I channel
        fbGroupEnable(bExecute := TRUE, stNciChannel := stNciChannel);

        IF fbGroupEnable.bDone THEN
            bReady := TRUE;
            eState := E_DeltaRobotState.IDLE;
            sStatusMsg := 'Robot ready. Waiting for start command.';
        ELSIF fbGroupEnable.bError THEN
            eState := E_DeltaRobotState.FAULTED;
            nErrorID := fbGroupEnable.nErrorId;
        END_IF

    E_DeltaRobotState.IDLE:
        bActive := FALSE;
        IF bStartCycle AND bReady THEN
            bActive := TRUE;
            eState := E_DeltaRobotState.WAIT_FOR_PRODUCT;
            sStatusMsg := 'Waiting for product on conveyor...';
        END_IF

    E_DeltaRobotState.WAIT_FOR_PRODUCT:
        // Wait for vision system or photoeye to latch product
        IF bProductDetected THEN
            eState := E_DeltaRobotState.SYNC_CONVEYOR;
            sStatusMsg := 'Product detected. Synchronizing to moving belt.';
        ELSIF bStopCycle THEN
            eState := E_DeltaRobotState.IDLE;
        END_IF

    E_DeltaRobotState.SYNC_CONVEYOR:
        // Engage dynamic offset tracking. The TCP will overlay the moving product coordinate system.
        fbTrackConveyor(
            Execute := TRUE, 
            ConveyorPosition := fConveyorPos, 
            ConveyorVelocity := fConveyorVel,
            ProductOffsetX := fProductOffsetX,
            ProductOffsetY := fProductOffsetY
        );

        IF fbTrackConveyor.InSync THEN
            eState := E_DeltaRobotState.APPROACH_PICK;
        END_IF

    E_DeltaRobotState.APPROACH_PICK:
        // Move to approach height above the tracked product
        // Note: The coordinates are now relative to the moving conveyor frame
        fbMoveLinear(
            Execute := TRUE,
            PositionX := 0.0, // Relative to product
            PositionY := 0.0,
            PositionZ := fApproachHeight,
            Velocity := 1500.0,
            stNciChannel := stNciChannel
        );

        IF fbMoveLinear.Done THEN
            fbMoveLinear(Execute := FALSE);
            eState := E_DeltaRobotState.PICK_CIRCULAR_INTERPOLATE;
            sStatusMsg := 'Executing circular interpolation to pick depth.';
        END_IF

    E_DeltaRobotState.PICK_CIRCULAR_INTERPOLATE:
        // Smooth semi-circular dive into the pick position to maintain TCP velocity and reduce mechanical shock
        fbMoveCircular(
            Execute := TRUE,
            CircMode := MC_CIRC_MODE_CENTER,
            AuxPointX := 0.0, 
            AuxPointY := 0.0, 
            AuxPointZ := (fApproachHeight + fPickDepth) / 2.0, // Midpoint
            EndPointX := 0.0, 
            EndPointY := 0.0, 
            EndPointZ := fPickDepth,
            Velocity := 800.0,
            stNciChannel := stNciChannel
        );

        IF fbMoveCircular.Done THEN
            fbMoveCircular(Execute := FALSE);
            bGripperActuate := TRUE; // Fire vacuum or pneumatic gripper
            fbTonGripper(IN := FALSE);
            eState := E_DeltaRobotState.GRIP_DELAY;
        END_IF

    E_DeltaRobotState.GRIP_DELAY:
        fbTonGripper(IN := TRUE, PT := T#50MS);
        IF fbTonGripper.Q THEN
            eState := E_DeltaRobotState.RETRACT_CONVEYOR;
        END_IF

    E_DeltaRobotState.RETRACT_CONVEYOR:
        // Pull straight up from the moving product
        fbMoveLinear(
            Execute := TRUE,
            PositionX := 0.0,
            PositionY := 0.0,
            PositionZ := fApproachHeight,
            Velocity := 2000.0,
            stNciChannel := stNciChannel
        );

        IF fbMoveLinear.Done THEN
            fbMoveLinear(Execute := FALSE);
            fbTrackConveyor(Execute := FALSE); // Disengage conveyor tracking
            eState := E_DeltaRobotState.MOVE_TO_PLACE;
            sStatusMsg := 'Moving to place location.';
        END_IF

    E_DeltaRobotState.MOVE_TO_PLACE:
        // Absolute move in world coordinates to drop-off
        fbMoveLinear(
            Execute := TRUE,
            PositionX := stPlacePos.X,
            PositionY := stPlacePos.Y,
            PositionZ := stPlacePos.Z + fApproachHeight,
            Velocity := 2500.0,
            stNciChannel := stNciChannel
        );

        IF fbMoveLinear.Done THEN
            fbMoveLinear(Execute := FALSE);
            eState := E_DeltaRobotState.PLACE_PART;
        END_IF

    E_DeltaRobotState.PLACE_PART:
        fbMoveLinear(
            Execute := TRUE,
            PositionX := stPlacePos.X,
            PositionY := stPlacePos.Y,
            PositionZ := stPlacePos.Z, // Drop depth
            Velocity := 1000.0,
            stNciChannel := stNciChannel
        );

        IF fbMoveLinear.Done THEN
            fbMoveLinear(Execute := FALSE);
            bGripperActuate := FALSE; // Release
            fbTonGripper(IN:=FALSE);
            eState := E_DeltaRobotState.RELEASE_DELAY;
        END_IF

    E_DeltaRobotState.RELEASE_DELAY:
        fbTonGripper(IN := TRUE, PT := T#50MS);
        IF fbTonGripper.Q THEN
            eState := E_DeltaRobotState.RETRACT_PLACE;
        END_IF

    E_DeltaRobotState.RETRACT_PLACE:
        fbMoveLinear(
            Execute := TRUE,
            PositionX := stPlacePos.X,
            PositionY := stPlacePos.Y,
            PositionZ := stPlacePos.Z + fApproachHeight,
            Velocity := 2000.0,
            stNciChannel := stNciChannel
        );

        IF fbMoveLinear.Done THEN
            fbMoveLinear(Execute := FALSE);
            bDone := TRUE;
            eState := E_DeltaRobotState.IDLE; // Cycle complete
        END_IF

    E_DeltaRobotState.FAULTED:
        bReady := FALSE;
        bActive := FALSE;
        bError := TRUE;
        bGripperActuate := FALSE;

        // Disable movements and axes safely
        fbPower1(Axis:=stAxis1, Enable:=FALSE);
        fbPower2(Axis:=stAxis2, Enable:=FALSE);
        fbPower3(Axis:=stAxis3, Enable:=FALSE);
        fbPower4(Axis:=stAxis4, Enable:=FALSE);
        fbGroupEnable(bExecute:=FALSE, stNciChannel:=stNciChannel);
        fbTrackConveyor(Execute:=FALSE);

        IF bReset THEN
            bError := FALSE;
            nErrorID := 0;
            eState := E_DeltaRobotState.INIT;
            sStatusMsg := 'Faults reset. Reinitializing...';
        END_IF

END_CASE

(* --- 3D BOUNDING BOX COLLISION CHECK --- *)
// Get current TCP position (conceptual block)
fCurrentX := stNciChannel.fSetPosX;
fCurrentY := stNciChannel.fSetPosY;
fCurrentZ := stNciChannel.fSetPosZ;

IF (fCurrentX < stBoundingBoxMin.X OR fCurrentX > stBoundingBoxMax.X) OR
   (fCurrentY < stBoundingBoxMin.Y OR fCurrentY > stBoundingBoxMax.Y) OR
   (fCurrentZ < stBoundingBoxMin.Z OR fCurrentZ > stBoundingBoxMax.Z) THEN

    // TCP outside allowed volume! Immediate trip.
    IF eState <> E_DeltaRobotState.FAULTED THEN
        eState := E_DeltaRobotState.FAULTED;
        nErrorID := 16#C011; // Boundary violation error code
        sStatusMsg := 'CRITICAL: TCP Escaped 3D Bounding Box Limits!';
    END_IF
END_IF

END_FUNCTION_BLOCK

