(*
=========================================================================================================
  Module:      ISA-18.2 Advanced Alarm Management Framework (First-Out & Priority Handling)
  Version:     3.0.0 (Enterprise-Grade IEC 61131-3)
  Description: 
    This block implements a comprehensive ISA-18.2 compliant alarm management system. 
    It features rigorous state tracking for alarms (Normal, Unacknowledged, Acknowledged, 
    Return-to-Normal Unacknowledged), latching, safety interlock evaluation, 
    and first-out (FIFO) fault tracking across multiple priority classes.

    Priority Classes:
      - 1: CRITICAL (Safety/Equipment Damage Risk - Immediate Stop)
      - 2: HIGH (Process Deviation - Requires operator intervention)
      - 3: LOW (Warning - Minor deviation or maintenance required)

  Features:
    - ISA-18.2 State Machine (NORM, UNACK, ACK, RTNUN)
    - Hardware Abstractions (E-Stops, Thermal Overloads)
    - First-Out Annunciation (Captures the exact first alarm that triggered a trip)
    - Priority-based grouping and summary
    - Global Silence and Acknowledge mechanisms
=========================================================================================================
*)

TYPE E_AlarmState :
(
    ALM_NORM     := 0,  (* Normal - No Alarm *)
    ALM_UNACK    := 1,  (* Active & Unacknowledged *)
    ALM_ACK      := 2,  (* Active & Acknowledged *)
    ALM_RTNUN    := 3,  (* Return to Normal but Unacknowledged *)
    ALM_SHELVED  := 4   (* Shelved / Suppressed *)
);
END_TYPE

TYPE E_AlarmPriority :
(
    PRIO_LOW      := 3,
    PRIO_HIGH     := 2,
    PRIO_CRITICAL := 1
);
END_TYPE

TYPE ST_AlarmConfig :
STRUCT
    Priority     : E_AlarmPriority;
    DelayTime    : TIME;
    IsLatching   : BOOL;
    IsShelvable  : BOOL;
END_STRUCT
END_TYPE

TYPE ST_AlarmInstance :
STRUCT
    State        : E_AlarmState;
    Active       : BOOL;
    TriggerTime  : DATE_AND_TIME;
    Config       : ST_AlarmConfig;
END_STRUCT
END_TYPE

(*
---------------------------------------------------------------------------------------------------------
  FUNCTION BLOCK: FB_ISA18_2_AlarmManager
  Description: Centralized manager evaluating physical interlocks and logical alarms.
---------------------------------------------------------------------------------------------------------
*)
FUNCTION_BLOCK FB_ISA18_2_AlarmManager
VAR_INPUT
    (* Hardware Interlocks & Abstractions *)
    bEStop_OK          : BOOL;  (* TRUE = Healthy, FALSE = Tripped *)
    bThermalOvl_OK     : BOOL;  (* TRUE = Healthy, FALSE = Tripped *)
    bProcessLimit_HIHI : BOOL;  (* TRUE = Limit Exceeded *)
    bProcessLimit_LOLO : BOOL;  (* TRUE = Limit Exceeded *)

    (* Operator Actions *)
    bAcknowledgeAll    : BOOL;
    bResetAll          : BOOL;

    (* Raw Alarm Inputs (Indexed mapping for modular expansion) *)
    arRawConditions    : ARRAY[1..10] OF BOOL;
END_VAR

VAR_OUTPUT
    (* Aggregated Status *)
    bAnyCriticalUnack  : BOOL;
    bAnyHighUnack      : BOOL;
    bAnyLowUnack       : BOOL;

    bSystemTrip        : BOOL; (* Master trip signal for interlock logic *)

    (* First-Out (FIFO) Annunciation *)
    nFirstOutAlarmID   : INT;  (* 0 = No trip, 1-10 = Logical Alarms, 11-14 = Interlocks *)

    (* Output to HMI / Annunciator *)
    bHornOutput        : BOOL;
    bBeaconOutput      : BOOL;
END_VAR

VAR
    (* Internal Alarm Records *)
    arAlarms           : ARRAY[1..14] OF ST_AlarmInstance;

    (* Timers for debouncing/delays *)
    arTimers           : ARRAY[1..14] OF TON;

    (* Edge Detection *)
    rTrigAck           : R_TRIG;
    rTrigReset         : R_TRIG;

    (* Internal State *)
    i                  : INT;
    bInitDone          : BOOL;
    bTripLatched       : BOOL;
END_VAR

(* ------------------- INITIALIZATION ------------------- *)
IF NOT bInitDone THEN
    (* Configure Interlocks (Critical, Instantaneous, Latching) *)
    arAlarms[11].Config.Priority := E_AlarmPriority.PRIO_CRITICAL;
    arAlarms[11].Config.DelayTime := T#0ms;
    arAlarms[11].Config.IsLatching := TRUE;

    arAlarms[12].Config.Priority := E_AlarmPriority.PRIO_CRITICAL;
    arAlarms[12].Config.DelayTime := T#500ms;
    arAlarms[12].Config.IsLatching := TRUE;

    arAlarms[13].Config.Priority := E_AlarmPriority.PRIO_CRITICAL;
    arAlarms[13].Config.DelayTime := T#2s;
    arAlarms[13].Config.IsLatching := TRUE;

    arAlarms[14].Config.Priority := E_AlarmPriority.PRIO_CRITICAL;
    arAlarms[14].Config.DelayTime := T#2s;
    arAlarms[14].Config.IsLatching := TRUE;

    (* Configure Logical Alarms *)
    FOR i := 1 TO 10 DO
        arAlarms[i].Config.IsLatching := TRUE;
        IF i <= 3 THEN
            arAlarms[i].Config.Priority := E_AlarmPriority.PRIO_CRITICAL;
            arAlarms[i].Config.DelayTime := T#2s;
        ELSIF i <= 7 THEN
            arAlarms[i].Config.Priority := E_AlarmPriority.PRIO_HIGH;
            arAlarms[i].Config.DelayTime := T#5s;
        ELSE
            arAlarms[i].Config.Priority := E_AlarmPriority.PRIO_LOW;
            arAlarms[i].Config.DelayTime := T#10s;
        END_IF;
    END_FOR;

    nFirstOutAlarmID := 0;
    bInitDone := TRUE;
END_IF;

(* ------------------- EDGE DETECTORS ------------------- *)
rTrigAck(CLK := bAcknowledgeAll);
rTrigReset(CLK := bResetAll);

(* ------------------- CONDITION MAPPING ------------------- *)
(* Map Hardware Abstractions to Internal Conditions (Inverted for fail-safe) *)
arTimers[11](IN := NOT bEStop_OK, PT := arAlarms[11].Config.DelayTime);
arTimers[12](IN := NOT bThermalOvl_OK, PT := arAlarms[12].Config.DelayTime);
arTimers[13](IN := bProcessLimit_HIHI, PT := arAlarms[13].Config.DelayTime);
arTimers[14](IN := bProcessLimit_LOLO, PT := arAlarms[14].Config.DelayTime);

(* Map Logical Array *)
FOR i := 1 TO 10 DO
    arTimers[i](IN := arRawConditions[i], PT := arAlarms[i].Config.DelayTime);
END_FOR;

(* ------------------- ISA-18.2 STATE MACHINE ------------------- *)
bHornOutput := FALSE;
bBeaconOutput := FALSE;
bAnyCriticalUnack := FALSE;
bAnyHighUnack := FALSE;
bAnyLowUnack := FALSE;

FOR i := 1 TO 14 DO
    (* Evaluate Condition *)
    IF arTimers[i].Q THEN
        arAlarms[i].Active := TRUE;
    ELSIF NOT arAlarms[i].Config.IsLatching THEN
        arAlarms[i].Active := FALSE;
    ELSIF rTrigReset.Q AND arAlarms[i].State = E_AlarmState.ALM_ACK THEN
        arAlarms[i].Active := FALSE;
    END_IF;

    (* State Transitions *)
    CASE arAlarms[i].State OF
        E_AlarmState.ALM_NORM:
            IF arTimers[i].Q THEN
                arAlarms[i].State := E_AlarmState.ALM_UNACK;

                (* First-Out Logic: Capture the first critical alarm that caused a trip *)
                IF NOT bTripLatched AND arAlarms[i].Config.Priority = E_AlarmPriority.PRIO_CRITICAL THEN
                    nFirstOutAlarmID := i;
                    bTripLatched := TRUE;
                END_IF;
            END_IF;

        E_AlarmState.ALM_UNACK:
            IF rTrigAck.Q THEN
                IF arTimers[i].Q THEN
                    arAlarms[i].State := E_AlarmState.ALM_ACK;
                ELSE
                    IF arAlarms[i].Config.IsLatching THEN
                        arAlarms[i].State := E_AlarmState.ALM_ACK;
                    ELSE
                        arAlarms[i].State := E_AlarmState.ALM_NORM;
                    END_IF;
                END_IF;
            ELSIF NOT arTimers[i].Q THEN
                arAlarms[i].State := E_AlarmState.ALM_RTNUN;
            END_IF;

        E_AlarmState.ALM_ACK:
            IF NOT arTimers[i].Q THEN
                IF arAlarms[i].Config.IsLatching THEN
                    IF rTrigReset.Q THEN
                        arAlarms[i].State := E_AlarmState.ALM_NORM;
                    END_IF;
                ELSE
                    arAlarms[i].State := E_AlarmState.ALM_NORM;
                END_IF;
            END_IF;

        E_AlarmState.ALM_RTNUN:
            IF rTrigAck.Q THEN
                IF arAlarms[i].Config.IsLatching THEN
                    arAlarms[i].State := E_AlarmState.ALM_ACK; (* Awaiting Reset *)
                ELSE
                    arAlarms[i].State := E_AlarmState.ALM_NORM;
                END_IF;
            ELSIF arTimers[i].Q THEN
                arAlarms[i].State := E_AlarmState.ALM_UNACK;
            END_IF;
    END_CASE;

    (* Aggregation & Annunciation *)
    IF arAlarms[i].State = E_AlarmState.ALM_UNACK OR arAlarms[i].State = E_AlarmState.ALM_RTNUN THEN
        IF arAlarms[i].Config.Priority = E_AlarmPriority.PRIO_CRITICAL THEN
            bAnyCriticalUnack := TRUE;
            bHornOutput := TRUE; (* Horn always sounds for unacknowledged criticals *)
        ELSIF arAlarms[i].Config.Priority = E_AlarmPriority.PRIO_HIGH THEN
            bAnyHighUnack := TRUE;
            bHornOutput := TRUE;
        ELSIF arAlarms[i].Config.Priority = E_AlarmPriority.PRIO_LOW THEN
            bAnyLowUnack := TRUE;
        END_IF;
    END_IF;

    IF arAlarms[i].State <> E_AlarmState.ALM_NORM THEN
        IF arAlarms[i].Config.Priority = E_AlarmPriority.PRIO_CRITICAL THEN
            bBeaconOutput := TRUE;
        END_IF;
    END_IF;
END_FOR;

(* ------------------- FIRST-OUT & TRIP LOGIC ------------------- *)
(* If all Critical Alarms are NORM, we can reset the First-Out and Trip status *)
IF bTripLatched THEN
    bSystemTrip := TRUE;

    (* Check if any critical alarms are still active or unacknowledged *)
    bTripLatched := FALSE;
    FOR i := 1 TO 14 DO
        IF arAlarms[i].Config.Priority = E_AlarmPriority.PRIO_CRITICAL AND arAlarms[i].State <> E_AlarmState.ALM_NORM THEN
            bTripLatched := TRUE;
            EXIT;
        END_IF;
    END_FOR;

    IF NOT bTripLatched THEN
        bSystemTrip := FALSE;
        nFirstOutAlarmID := 0;
    END_IF;
ELSE
    bSystemTrip := FALSE;
END_IF;

END_FUNCTION_BLOCK

(*
================================================================================
Function Block: MULTI_PUMP_STATION
Description: Highly complex, production-ready multi-pump alternating lead-lag 
             system for municipal water treatment plants.
Features:
  - Runtime wear-leveling based on pump operating hours.
  - Cavitation detection via current spikes.
  - Dry-run protection via intake pressure switches.
  - Thermal overload interlocks and Emergency Stops (E-Stop).
  - State machine for pump sequence control (Lead, Lag, Standby).
================================================================================
*)

TYPE PumpState : (
    PUMP_OFF,
    PUMP_STARTING,
    PUMP_RUNNING,
    PUMP_STOPPING,
    PUMP_FAULTED
);
END_TYPE

TYPE PumpFaults : STRUCT
    ThermalOverload : BOOL;
    Cavitation      : BOOL;
    DryRun          : BOOL;
    FailedToStart   : BOOL;
END_STRUCT;
END_TYPE

TYPE PumpData : STRUCT
    State           : PumpState;
    RunHours        : REAL;
    CurrentDraw     : REAL;
    Faults          : PumpFaults;
END_STRUCT;
END_TYPE

FUNCTION_BLOCK MULTI_PUMP_STATION
VAR_INPUT
    EnableSystem    : BOOL;           (* Master enable for the pump station *)
    E_Stop          : BOOL;           (* Emergency stop, normally closed (NC) *)
    IntakePressure  : REAL;           (* Analog intake pressure in bar *)
    LevelSetPoint   : REAL;           (* Desired tank level *)
    LevelActual     : REAL;           (* Actual tank level *)

    Pump1_Current   : REAL;           (* Analog current feedback for Pump 1 *)
    Pump2_Current   : REAL;           (* Analog current feedback for Pump 2 *)

    Pump1_Thermal   : BOOL;           (* Thermal overload switch P1 (NC) *)
    Pump2_Thermal   : BOOL;           (* Thermal overload switch P2 (NC) *)

    ResetFaults     : BOOL;           (* Acknowledge and reset faults *)
END_VAR

VAR_OUTPUT
    Pump1_Cmd       : BOOL;           (* Command to run Pump 1 *)
    Pump2_Cmd       : BOOL;           (* Command to run Pump 2 *)
    SystemFault     : BOOL;           (* General fault indicator *)
    LeadPumpID      : INT;            (* Currently assigned lead pump (1 or 2) *)
END_VAR

VAR CONSTANT
    DRY_RUN_PRESSURE_MIN : REAL := 0.5;   (* Minimum bar before dry run fault *)
    CAVITATION_CURRENT   : REAL := 45.0;  (* Current limit indicating cavitation (Amps) *)
    START_DELAY          : TIME := T#5S;  (* Staggered start delay *)
    WEAR_LEVEL_DIFF      : REAL := 10.0;  (* Difference in hours to force switch *)
END_VAR

VAR
    Pumps                : ARRAY[1..2] OF PumpData;
    StartTimer           : TON;
    SysState             : INT := 0;      (* 0=Idle, 1=LeadReq, 2=LagReq *)
    CycleTimer           : TON;
    DryRunTimer          : TON;
    CavitationTimer1     : TON;
    CavitationTimer2     : TON;

    bDryRun              : BOOL;
    bEStopActive         : BOOL;
END_VAR

(* -----------------------------------------------------------------------------
   SAFETY INTERLOCKS
   ----------------------------------------------------------------------------- *)
bEStopActive := NOT E_Stop; (* E_Stop is NC *)

(* Dry run detection with 3-second debounce to avoid false trips *)
DryRunTimer(IN := (IntakePressure < DRY_RUN_PRESSURE_MIN), PT := T#3S);
bDryRun := DryRunTimer.Q;

(* -----------------------------------------------------------------------------
   FAULT MONITORING
   ----------------------------------------------------------------------------- *)
IF ResetFaults THEN
    Pumps[1].Faults.ThermalOverload := FALSE;
    Pumps[1].Faults.Cavitation := FALSE;
    Pumps[1].Faults.DryRun := FALSE;

    Pumps[2].Faults.ThermalOverload := FALSE;
    Pumps[2].Faults.Cavitation := FALSE;
    Pumps[2].Faults.DryRun := FALSE;
END_IF;

(* Hardware interlocks *)
IF NOT Pump1_Thermal THEN Pumps[1].Faults.ThermalOverload := TRUE; END_IF;
IF NOT Pump2_Thermal THEN Pumps[2].Faults.ThermalOverload := TRUE; END_IF;

IF bDryRun THEN
    Pumps[1].Faults.DryRun := TRUE;
    Pumps[2].Faults.DryRun := TRUE;
END_IF;

(* Cavitation detection via sustained current spikes (e.g., 2 seconds) *)
CavitationTimer1(IN := (Pump1_Current > CAVITATION_CURRENT) AND Pump1_Cmd, PT := T#2S);
IF CavitationTimer1.Q THEN Pumps[1].Faults.Cavitation := TRUE; END_IF;

CavitationTimer2(IN := (Pump2_Current > CAVITATION_CURRENT) AND Pump2_Cmd, PT := T#2S);
IF CavitationTimer2.Q THEN Pumps[2].Faults.Cavitation := TRUE; END_IF;

(* General system fault *)
SystemFault := bEStopActive OR 
               (Pumps[1].Faults.ThermalOverload OR Pumps[1].Faults.Cavitation OR Pumps[1].Faults.DryRun) OR 
               (Pumps[2].Faults.ThermalOverload OR Pumps[2].Faults.Cavitation OR Pumps[2].Faults.DryRun);

(* -----------------------------------------------------------------------------
   WEAR-LEVELING ALGORITHM
   ----------------------------------------------------------------------------- *)
(* Periodically evaluate which pump should be lead based on runtime hours.
   Only switch if difference exceeds the hysteresis value to prevent rapid toggling. *)
IF (Pumps[1].RunHours <= Pumps[2].RunHours) AND (Pumps[2].RunHours - Pumps[1].RunHours > WEAR_LEVEL_DIFF) THEN
    LeadPumpID := 1;
ELSIF (Pumps[2].RunHours < Pumps[1].RunHours) AND (Pumps[1].RunHours - Pumps[2].RunHours > WEAR_LEVEL_DIFF) THEN
    LeadPumpID := 2;
END_IF;

(* Fallback if Lead pump is faulted *)
IF LeadPumpID = 1 AND (Pumps[1].Faults.ThermalOverload OR Pumps[1].Faults.Cavitation OR Pumps[1].Faults.DryRun) THEN
    LeadPumpID := 2;
ELSIF LeadPumpID = 2 AND (Pumps[2].Faults.ThermalOverload OR Pumps[2].Faults.Cavitation OR Pumps[2].Faults.DryRun) THEN
    LeadPumpID := 1;
END_IF;

IF LeadPumpID = 0 THEN LeadPumpID := 1; END_IF; (* Initialization *)

(* -----------------------------------------------------------------------------
   PROCESS CONTROL & SEQUENCING (LEAD-LAG)
   ----------------------------------------------------------------------------- *)
IF NOT EnableSystem OR SystemFault THEN
    Pump1_Cmd := FALSE;
    Pump2_Cmd := FALSE;
    SysState := 0;
ELSE
    (* Control Logic based on Level Actual vs Setpoint.
       Assuming a drain sequence (pump out). *)

    (* Lead requirement: Level goes 10% above setpoint *)
    IF LevelActual > (LevelSetPoint * 1.1) THEN
        SysState := 1; 
    END_IF;

    (* Lag requirement: Level goes 20% above setpoint (high demand) *)
    IF LevelActual > (LevelSetPoint * 1.2) THEN
        SysState := 2;
    END_IF;

    (* Stop condition: Level drops below setpoint *)
    IF LevelActual <= LevelSetPoint THEN
        SysState := 0;
    END_IF;

    (* Execute commands based on state *)
    CASE SysState OF
        0: (* Idle *)
            Pump1_Cmd := FALSE;
            Pump2_Cmd := FALSE;

        1: (* Lead Only *)
            IF LeadPumpID = 1 THEN
                Pump1_Cmd := TRUE;
                Pump2_Cmd := FALSE;
            ELSE
                Pump1_Cmd := FALSE;
                Pump2_Cmd := TRUE;
            END_IF;

        2: (* Lead + Lag *)
            Pump1_Cmd := TRUE;
            Pump2_Cmd := TRUE;

    END_CASE;
END_IF;

(* -----------------------------------------------------------------------------
   RUNTIME ACCUMULATION (Simulated integration per cycle)
   ----------------------------------------------------------------------------- *)
(* Assuming a 1s task cycle for simple addition. In reality, use system time. *)
CycleTimer(IN := NOT CycleTimer.Q, PT := T#1S);
IF CycleTimer.Q THEN
    IF Pump1_Cmd THEN
        Pumps[1].RunHours := Pumps[1].RunHours + (1.0 / 3600.0);
    END_IF;
    IF Pump2_Cmd THEN
        Pumps[2].RunHours := Pumps[2].RunHours + (1.0 / 3600.0);
    END_IF;
END_IF;

END_FUNCTION_BLOCK

(*
=============================================================================
BLOCK: SIS_2oo3_Pressure_Voter
VERSION: 2.4 (SIL-3 Compliant)
AUTHOR: Lumina Elite Synthetic Data Architect
DATE: 2026-08-21

DESCRIPTION:
This Function Block implements a Two-out-of-Three (2oo3) voting logic 
for analog pressure transmitters on a critical gas pipeline.
Designed in accordance with IEC 61508 / IEC 61131-3 for SIL-3 applications.

KEY FEATURES:
1. 2oo3 Voting on Analog Values (Median Selection or Average of healthy).
2. Deviation Detection: Flags if any transmitter deviates from the median 
   by more than a configured tolerance.
3. Hardware Abstraction & Diagnostics: Evaluates NAMUR NE43 status codes 
   (e.g., open circuit, short circuit).
4. Safety Interlocks: Integrates global Emergency Stop (E-Stop) and 
   Maintenance Override (Bypass).
5. State Machine: Manages Normal Operation, Degraded (1oo2), Fault (Shutdown),
   and Override modes.

NOTES ON FAIL-SAFE LOGIC:
If one transmitter fails, the system automatically degrades to 1oo2 voting.
If two transmitters fail, the system transitions to a SAFE STATE (Trip).
An active E-Stop forces an immediate Safe State regardless of transmitter health.
=============================================================================
*)

FUNCTION_BLOCK SIS_2oo3_Pressure_Voter

VAR_INPUT
    // Analog Input Values from Hardware (e.g., 4-20mA scaled to 0-100 Bar)
    PT_01_Value : REAL; 
    PT_02_Value : REAL;
    PT_03_Value : REAL;

    // Hardware Diagnostic Status (NAMUR NE43 or Fieldbus Status)
    // TRUE = Healthy, FALSE = Fault (Open wire, Short, Out of Range)
    PT_01_Healthy : BOOL;
    PT_02_Healthy : BOOL;
    PT_03_Healthy : BOOL;

    // Trip Setpoint (Bar)
    Trip_Setpoint : REAL := 85.0; 

    // Deviation Tolerance for Cross-Checking (Bar)
    Deviation_Tol : REAL := 5.0;

    // Safety Interlocks
    E_Stop_Active : BOOL;       // TRUE if E-Stop is pressed
    Reset_Faults  : BOOL;       // Rising edge to acknowledge and reset trips
    Bypass_Enable : BOOL;       // Maintenance Override (Key-Switch)
END_VAR

VAR_OUTPUT
    // Voted Pressure Result
    Voted_Pressure : REAL;

    // Safety Action
    Trip_Command : BOOL;        // TRUE = TRIGGER SHUTDOWN (SAFE STATE)

    // Diagnostic Alarms
    Deviation_Alarm : BOOL;     // TRUE = One transmitter is deviating
    System_Degraded : BOOL;     // TRUE = Operating in 1oo2 mode
    System_Fault    : BOOL;     // TRUE = Operating in Safe State (>= 2 faults)

    // Current System State
    State_Status : STRING[20];
END_VAR

VAR
    // Internal State Machine
    TYPE SIS_STATE : (
        INIT, 
        NORMAL_2OO3, 
        DEGRADED_1OO2, 
        TRIP_STATE, 
        BYPASS_MODE
    );
    END_TYPE
    Current_State : SIS_STATE := INIT;

    // Internal Calculations
    Healthy_Count : INT;
    Median_Value  : REAL;
    Diff_1, Diff_2, Diff_3 : REAL;

    // Fault Flags
    Dev_Flt_1, Dev_Flt_2, Dev_Flt_3 : BOOL;
    HW_Flt_1, HW_Flt_2, HW_Flt_3 : BOOL;

    // Edge Detection
    Reset_Edge : R_TRIG;
END_VAR

(* -------------------------------------------------------------------------
   1. PROCESS INPUTS & HARDWARE DIAGNOSTICS
   ------------------------------------------------------------------------- *)
Reset_Edge(CLK := Reset_Faults);

// Evaluate Hardware Faults (Inverted logic for internal processing)
HW_Flt_1 := NOT PT_01_Healthy;
HW_Flt_2 := NOT PT_02_Healthy;
HW_Flt_3 := NOT PT_03_Healthy;

// Count Healthy Transmitters
Healthy_Count := 0;
IF NOT HW_Flt_1 THEN Healthy_Count := Healthy_Count + 1; END_IF;
IF NOT HW_Flt_2 THEN Healthy_Count := Healthy_Count + 1; END_IF;
IF NOT HW_Flt_3 THEN Healthy_Count := Healthy_Count + 1; END_IF;

(* -------------------------------------------------------------------------
   2. SAFETY STATE MACHINE
   ------------------------------------------------------------------------- *)
// Highest Priority: E-STOP
IF E_Stop_Active THEN
    Current_State := TRIP_STATE;
    State_Status := 'E-STOP ACTIVE';

// Second Priority: Bypass (Maintenance Mode)
ELSIF Bypass_Enable THEN
    Current_State := BYPASS_MODE;
    State_Status := 'MAINTENANCE BYPASS';

// Third Priority: State Evaluation based on Transmitter Health
ELSE
    CASE Current_State OF
        INIT:
            IF Healthy_Count = 3 THEN
                Current_State := NORMAL_2OO3;
            ELSIF Healthy_Count = 2 THEN
                Current_State := DEGRADED_1OO2;
            ELSE
                Current_State := TRIP_STATE;
            END_IF;

        NORMAL_2OO3:
            State_Status := 'NORMAL (2oo3)';
            IF Healthy_Count = 2 THEN
                Current_State := DEGRADED_1OO2;
            ELSIF Healthy_Count < 2 THEN
                Current_State := TRIP_STATE;
            END_IF;

        DEGRADED_1OO2:
            State_Status := 'DEGRADED (1oo2)';
            IF Healthy_Count = 3 THEN
                Current_State := NORMAL_2OO3;
            ELSIF Healthy_Count < 2 THEN
                Current_State := TRIP_STATE;
            END_IF;

        TRIP_STATE:
            State_Status := 'SYSTEM FAULT / TRIP';
            // Latching mechanism: requires explicit Reset AND Healthy Hardware
            IF Reset_Edge.Q AND (Healthy_Count >= 2) AND NOT E_Stop_Active THEN
                Current_State := INIT; 
            END_IF;

        BYPASS_MODE:
            IF NOT Bypass_Enable THEN
                Current_State := INIT;
            END_IF;
    END_CASE;
END_IF;

(* -------------------------------------------------------------------------
   3. VOTING LOGIC & DEVIATION DETECTION
   ------------------------------------------------------------------------- *)
// Reset intermediate values
Dev_Flt_1 := FALSE;
Dev_Flt_2 := FALSE;
Dev_Flt_3 := FALSE;

IF Current_State = NORMAL_2OO3 THEN
    // 2oo3 Voting: Select Median Value
    // Logic: If A > B then swap A,B. Simple median finding.
    IF (PT_01_Value >= PT_02_Value AND PT_01_Value <= PT_03_Value) OR 
       (PT_01_Value <= PT_02_Value AND PT_01_Value >= PT_03_Value) THEN
        Median_Value := PT_01_Value;
    ELSIF (PT_02_Value >= PT_01_Value AND PT_02_Value <= PT_03_Value) OR 
          (PT_02_Value <= PT_01_Value AND PT_02_Value >= PT_03_Value) THEN
        Median_Value := PT_02_Value;
    ELSE
        Median_Value := PT_03_Value;
    END_IF;

    Voted_Pressure := Median_Value;

    // Deviation Cross-Check against Median
    Diff_1 := ABS(PT_01_Value - Median_Value);
    Diff_2 := ABS(PT_02_Value - Median_Value);
    Diff_3 := ABS(PT_03_Value - Median_Value);

    IF Diff_1 > Deviation_Tol THEN Dev_Flt_1 := TRUE; END_IF;
    IF Diff_2 > Deviation_Tol THEN Dev_Flt_2 := TRUE; END_IF;
    IF Diff_3 > Deviation_Tol THEN Dev_Flt_3 := TRUE; END_IF;

ELSIF Current_State = DEGRADED_1OO2 THEN
    // 1oo2 Voting: Use the Maximum (most conservative for high-pressure trip)
    IF HW_Flt_1 THEN
        Voted_Pressure := MAX(PT_02_Value, PT_03_Value);
        Diff_2 := ABS(PT_02_Value - Voted_Pressure);
        Diff_3 := ABS(PT_03_Value - Voted_Pressure);
        IF ABS(PT_02_Value - PT_03_Value) > Deviation_Tol THEN
            Dev_Flt_2 := TRUE; Dev_Flt_3 := TRUE;
        END_IF;
    ELSIF HW_Flt_2 THEN
        Voted_Pressure := MAX(PT_01_Value, PT_03_Value);
        IF ABS(PT_01_Value - PT_03_Value) > Deviation_Tol THEN
            Dev_Flt_1 := TRUE; Dev_Flt_3 := TRUE;
        END_IF;
    ELSIF HW_Flt_3 THEN
        Voted_Pressure := MAX(PT_01_Value, PT_02_Value);
        IF ABS(PT_01_Value - PT_02_Value) > Deviation_Tol THEN
            Dev_Flt_1 := TRUE; Dev_Flt_2 := TRUE;
        END_IF;
    END_IF;

ELSIF Current_State = TRIP_STATE THEN
    // In Trip State, Voted Pressure defaults to Maximum Range or Trip Setpoint
    Voted_Pressure := Trip_Setpoint;

ELSIF Current_State = BYPASS_MODE THEN
    // In Bypass, maintain last known good or force to safe operating value (0)
    Voted_Pressure := 0.0;
END_IF;

(* -------------------------------------------------------------------------
   4. OUTPUT ASSIGNMENTS & TRIPS
   ------------------------------------------------------------------------- *)
// System Status Outputs
System_Degraded := (Current_State = DEGRADED_1OO2);
System_Fault    := (Current_State = TRIP_STATE);
Deviation_Alarm := Dev_Flt_1 OR Dev_Flt_2 OR Dev_Flt_3;

// Critical Trip Logic (Fail-Safe)
// Trip if in TRIP_STATE, OR if voted pressure exceeds setpoint (unless bypassed)
IF Current_State = BYPASS_MODE THEN
    Trip_Command := FALSE;
ELSIF Current_State = TRIP_STATE THEN
    Trip_Command := TRUE;
ELSE
    IF Voted_Pressure >= Trip_Setpoint THEN
        Trip_Command := TRUE;
    ELSE
        Trip_Command := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK

```iec61131-3
(*
