    UFLS_Active_Stage : INT;        (* Current UFLS Stage triggered (0 = None) *)
    TCM_Alarm : BOOL;               (* Trip coil monitoring failure alarm *)
    System_Locked_Out : BOOL;       (* Safety lockout state requiring manual reset *)
    GOOSE_Link_Fail_Alarm : BOOL;   (* GOOSE communication timeout or invalid data *)
    State_Diagnostics : STRING(50); (* Textual representation of system state *)
END_VAR

VAR CONSTANT
    FREQ_NOMINAL : REAL := 50.0;    (* 50 Hz or 60 Hz based on region *)
    UFLS_STAGE1_THR : REAL := 49.2;
    UFLS_STAGE2_THR : REAL := 49.0;
    UFLS_STAGE3_THR : REAL := 48.8;
    UFLS_STAGE4_THR : REAL := 48.6;
    DFDT_STAGE_ACCEL : REAL := -0.5;(* High df/dt threshold to accelerate tripping *)
    GOOSE_TIMEOUT : TIME := T#50ms;
END_VAR

VAR
    State : INT;                    (* Internal State Machine: 0=Init, 1=Run, 2=Trip, 3=Lockout *)
    GOOSE_Watchdog : TON;
    UFLS_Delay_1 : TON;
    UFLS_Delay_2 : TON;
    UFLS_Delay_3 : TON;
    UFLS_Delay_4 : TON;
    Sys_Lockout_Latch : RS;         (* Latch for critical failures *)
    Trip_Latch : RS;                (* Latch for breaker tripping *)
END_VAR

(* --- 1. Communication & Hardware Health Monitoring --- *)

(* GOOSE Link Watchdog *)
GOOSE_Watchdog(IN := NOT GOOSE_Msg_Valid, PT := GOOSE_TIMEOUT);
IF GOOSE_Watchdog.Q THEN
    GOOSE_Link_Fail_Alarm := TRUE;
ELSE
    GOOSE_Link_Fail_Alarm := FALSE;
END_IF;

(* Trip Coil Monitoring (TCM) Evaluation *)
IF NOT TCM_Sense_Aux AND State > 0 THEN
    TCM_Alarm := TRUE;
ELSE
    TCM_Alarm := FALSE;
END_IF;

(* --- 2. Safety Interlocks & Lockout Handling --- *)
(* Lockout conditions: E-Stop pressed, Thermal Overload, or continuous TCM Failure *)
Sys_Lockout_Latch(
    SET := NOT E_Stop OR NOT Thermal_Overload OR TCM_Alarm,
    RESET1 := Ack_Reset AND E_Stop AND Thermal_Overload AND NOT TCM_Alarm
);
System_Locked_Out := Sys_Lockout_Latch.Q1;

(* --- 3. Under-Frequency Load Shedding (UFLS) Algorithm --- *)
(* Accelerate trip times if df/dt is highly negative *)
IF df_dt < DFDT_STAGE_ACCEL THEN
    UFLS_Delay_1.PT := T#100ms;
    UFLS_Delay_2.PT := T#150ms;
    UFLS_Delay_3.PT := T#200ms;
    UFLS_Delay_4.PT := T#250ms;
ELSE
    UFLS_Delay_1.PT := T#250ms;
    UFLS_Delay_2.PT := T#300ms;
    UFLS_Delay_3.PT := T#400ms;
    UFLS_Delay_4.PT := T#500ms;
END_IF;

(* Stage 1 *)
UFLS_Delay_1(IN := (Grid_Freq <= UFLS_STAGE1_THR) AND Enable);
(* Stage 2 *)
UFLS_Delay_2(IN := (Grid_Freq <= UFLS_STAGE2_THR) AND Enable);
(* Stage 3 *)
UFLS_Delay_3(IN := (Grid_Freq <= UFLS_STAGE3_THR) AND Enable);
(* Stage 4 *)
UFLS_Delay_4(IN := (Grid_Freq <= UFLS_STAGE4_THR) AND Enable);

IF UFLS_Delay_4.Q THEN
    UFLS_Active_Stage := 4;
ELSIF UFLS_Delay_3.Q THEN
    UFLS_Active_Stage := 3;
ELSIF UFLS_Delay_2.Q THEN
    UFLS_Active_Stage := 2;
ELSIF UFLS_Delay_1.Q THEN
    UFLS_Active_Stage := 1;
ELSE
    UFLS_Active_Stage := 0;
END_IF;

(* --- 4. Main State Machine --- *)
CASE State OF
    0: (* INIT *)
        CB_Trip_Cmd := FALSE;
        State_Diagnostics := 'INITIALIZATION';
        IF Enable AND NOT System_Locked_Out AND GOOSE_Msg_Valid THEN
            State := 1;
        END_IF;

    1: (* RUN / MONITOR *)
        State_Diagnostics := 'SYSTEM HEALTHY - MONITORING';
        IF System_Locked_Out THEN
            State := 3;
        ELSIF UFLS_Active_Stage > 0 THEN
            State := 2;
        END_IF;

        Trip_Latch(SET := FALSE, RESET1 := TRUE);
        CB_Trip_Cmd := FALSE;

    2: (* TRIP ACTIVE *)
        State_Diagnostics := 'UFLS TRIPPED';
        Trip_Latch(SET := TRUE, RESET1 := Ack_Reset);
        CB_Trip_Cmd := Trip_Latch.Q1;

        IF System_Locked_Out THEN
            State := 3;
        ELSIF NOT Trip_Latch.Q1 AND UFLS_Active_Stage = 0 THEN
            State := 1;
        END_IF;

    3: (* LOCKOUT *)
        State_Diagnostics := 'SAFETY LOCKOUT - TRIP FORCED';
        Trip_Latch(SET := TRUE, RESET1 := FALSE); (* Force Trip in Lockout *)
        CB_Trip_Cmd := Trip_Latch.Q1;

        IF NOT System_Locked_Out AND Ack_Reset THEN
            State := 0;
        END_IF;

    ELSE
        State := 0;
END_CASE;

(* Ensure hardware abstraction aligns the output trip command with auxiliary contacts *)
(* The trip command continues to assert until the CB actually opens *)
IF CB_Aux_52b AND NOT CB_Aux_52a THEN
    (* CB is physically open, trip command can be relieved if not in lockout *)
    IF State = 2 THEN
        CB_Trip_Cmd := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
