(*
================================================================================
FUNCTION_BLOCK FB_AHU_Controller
================================================================================
Description:
    Advanced Air Handling Unit (AHU) Controller for Enterprise BMS.
    Includes hardware abstractions, safety interlocks, freeze protection,
    economizer logic, and chilled water PID control.

Author: Lumina Synthetic Data Architect
Version: 2.0.0
================================================================================
*)
FUNCTION_BLOCK FB_AHU_Controller

VAR_INPUT
    // Hardware Abstractions (Physical Inputs)
    bHw_SupplyFanStatus     : BOOL;  // Supply Fan Proof of Airflow (Current Switch/DP)
    bHw_ReturnFanStatus     : BOOL;  // Return Fan Proof of Airflow
    bHw_FreezeStat          : BOOL;  // Hardwired low-limit freeze stat (NC, opens on freeze)
    bHw_FireAlarm           : BOOL;  // Fire Alarm Interlock (NC, opens on alarm)
    bHw_ThermalOverload     : BOOL;  // Supply Fan VFD/Motor Thermal Overload (NC)
    bHw_EStop               : BOOL;  // Emergency Stop Pushbutton (NC)

    // Analog Inputs
    rHw_SupplyAirTemp       : REAL;  // Supply Air Temperature (deg C)
    rHw_ReturnAirTemp       : REAL;  // Return Air Temperature (deg C)
    rHw_MixedAirTemp        : REAL;  // Mixed Air Temperature (deg C)
    rHw_OutsideAirTemp      : REAL;  // Outside Air Temperature (deg C)
    rHw_OutsideAirEnthalpy  : REAL;  // Outside Air Enthalpy (kJ/kg)
    rHw_ReturnAirEnthalpy   : REAL;  // Return Air Enthalpy (kJ/kg)

    // Setpoints & Configuration
    bEnable                 : BOOL;  // System Enable Command
    rSupplyAirTempSp        : REAL;  // Supply Air Temperature Setpoint (deg C)
    rMinDamperPos           : REAL;  // Minimum Outside Air Damper Position (%)
    rEconomizerEnthalpySp   : REAL;  // Enthalpy Setpoint for Economizer (kJ/kg)

    // PID Parameters (Chilled Water)
    rChwKp                  : REAL := 2.5;
    rChwKi                  : REAL := 0.1;
    rChwKd                  : REAL := 0.0;
END_VAR

VAR_OUTPUT
    // Hardware Abstractions (Physical Outputs)
    bHw_SupplyFanCmd        : BOOL;  // Supply Fan Start/Stop Command
    bHw_ReturnFanCmd        : BOOL;  // Return Fan Start/Stop Command
    rHw_OaDamperCmd         : REAL;  // Outside Air Damper Command (0-100%)
    rHw_EaDamperCmd         : REAL;  // Exhaust Air Damper Command (0-100%)
    rHw_MaDamperCmd         : REAL;  // Mixed/Return Air Damper Command (0-100%)
    rHw_ChwValveCmd         : REAL;  // Chilled Water Valve Command (0-100%)

    // Status & Alarms
    bSystemRunning          : BOOL;
    bAlarm_EStop            : BOOL;
    bAlarm_Fire             : BOOL;
    bAlarm_Freeze           : BOOL;
    bAlarm_ThermalOverload  : BOOL;
    bAlarm_FanFailure       : BOOL;
    bEconomizerActive       : BOOL;
END_VAR

VAR
    // Internal State Machine
    eState                  : (INIT, OFF, PRESTART, RUNNING, FAULT);

    // Timers
    tonFanProof             : TON;
    tonPrestartDelay        : TON;

    // PIDs
    fbChwPID                : FB_PID; // Assuming standard library PID implementation

    // Internal Variables
    bSafetyOk               : BOOL;
    rCoolingDemand          : REAL;
END_VAR

(*=============================================================================
   Safety & Interlock Processing
=============================================================================*)
// Fail-safe logic: Inputs are Normally Closed (NC), so TRUE means OK, FALSE means Alarm.
bAlarm_EStop           := NOT bHw_EStop;
bAlarm_Fire            := NOT bHw_FireAlarm;
bAlarm_Freeze          := NOT bHw_FreezeStat;
bAlarm_ThermalOverload := NOT bHw_ThermalOverload;

// Global Safety Interlock
bSafetyOk := NOT bAlarm_EStop AND 
             NOT bAlarm_Fire AND 
             NOT bAlarm_Freeze AND 
             NOT bAlarm_ThermalOverload;

(*=============================================================================
   State Machine for AHU Control
=============================================================================*)
CASE eState OF

    INIT:
        // Initialization state: force outputs safely off
        bHw_SupplyFanCmd := FALSE;
        bHw_ReturnFanCmd := FALSE;
        rHw_OaDamperCmd  := 0.0;
        rHw_EaDamperCmd  := 0.0;
        rHw_MaDamperCmd  := 100.0; // Recirculate fully on init
        rHw_ChwValveCmd  := 0.0;
        IF bSafetyOk THEN
            eState := OFF;
        END_IF;

    OFF:
        // System off state
        bHw_SupplyFanCmd := FALSE;
        bHw_ReturnFanCmd := FALSE;
        rHw_OaDamperCmd  := 0.0;
        rHw_EaDamperCmd  := 0.0;
        rHw_MaDamperCmd  := 100.0;
        rHw_ChwValveCmd  := 0.0;

        IF bEnable AND bSafetyOk THEN
            eState := PRESTART;
        ELSIF NOT bSafetyOk THEN
            eState := FAULT;
        END_IF;

    PRESTART:
        // Open dampers to minimum position before starting fans to prevent duct implosion
        rHw_OaDamperCmd := rMinDamperPos;
        rHw_MaDamperCmd := 100.0 - rMinDamperPos;
        rHw_EaDamperCmd := rMinDamperPos;

        tonPrestartDelay(IN := TRUE, PT := T#10S);

        IF tonPrestartDelay.Q AND bSafetyOk THEN
            eState := RUNNING;
            tonPrestartDelay(IN := FALSE);
        ELSIF NOT bSafetyOk OR NOT bEnable THEN
            eState := OFF;
            tonPrestartDelay(IN := FALSE);
        END_IF;

    RUNNING:
        bSystemRunning := TRUE;
        bHw_SupplyFanCmd := TRUE;
        bHw_ReturnFanCmd := TRUE;

        // Fan proof of airflow evaluation (allow 30s for fans to spool up)
        tonFanProof(IN := bHw_SupplyFanCmd, PT := T#30S);
        IF tonFanProof.Q AND (NOT bHw_SupplyFanStatus OR NOT bHw_ReturnFanStatus) THEN
            bAlarm_FanFailure := TRUE;
            eState := FAULT;
        END_IF;

        IF NOT bSafetyOk OR NOT bEnable THEN
            eState := OFF;
            bSystemRunning := FALSE;
        END_IF;

    FAULT:
        // Fault override state
        bHw_SupplyFanCmd := FALSE;
        bHw_ReturnFanCmd := FALSE;
        rHw_OaDamperCmd  := 0.0;
        rHw_EaDamperCmd  := 0.0;
        rHw_MaDamperCmd  := 100.0;

        // Freeze protection override: if freezing, open CHW valve to allow flow and prevent coil rupture
        IF bAlarm_Freeze THEN
            rHw_ChwValveCmd := 100.0;
        ELSE
            rHw_ChwValveCmd := 0.0;
        END_IF;

        IF bSafetyOk AND NOT bAlarm_FanFailure THEN
            eState := OFF;
        END_IF;

END_CASE;

(*=============================================================================
   Economizer & Temperature Control Logic (Only active in RUNNING state)
=============================================================================*)
IF eState = RUNNING THEN

    // 1. Economizer Suitability Check
    // Active if Outside Air Enthalpy is lower than Return Air Enthalpy AND lower than Setpoint
    bEconomizerActive := (rHw_OutsideAirEnthalpy < rHw_ReturnAirEnthalpy) AND 
                         (rHw_OutsideAirEnthalpy < rEconomizerEnthalpySp);

    // 2. Chilled Water PID Loop calculation
    fbChwPID(
        ENABLE := TRUE,
        SP := rSupplyAirTempSp,
        PV := rHw_SupplyAirTemp,
        KP := rChwKp,
        KI := rChwKi,
        KD := rChwKd
    );
    rCoolingDemand := fbChwPID.Y; // 0.0 to 100.0 assumed output range

    // 3. Control Sequencing (Economizer vs Mechanical Cooling)
    IF bEconomizerActive THEN
        // Use outside air for free cooling
        // Linearly scale cooling demand (0-100%) to damper positions (MinOa-100%)
        rHw_OaDamperCmd := rMinDamperPos + (rCoolingDemand * (100.0 - rMinDamperPos) / 100.0);
        rHw_EaDamperCmd := rHw_OaDamperCmd;
        rHw_MaDamperCmd := 100.0 - rHw_OaDamperCmd;

        // Split-range control for CHW Valve: activate if cooling demand > 50%
        IF rCoolingDemand > 50.0 THEN
            rHw_ChwValveCmd := (rCoolingDemand - 50.0) * 2.0; 
            IF rHw_ChwValveCmd < 0.0 THEN rHw_ChwValveCmd := 0.0; END_IF;
            IF rHw_ChwValveCmd > 100.0 THEN rHw_ChwValveCmd := 100.0; END_IF;
        ELSE
            rHw_ChwValveCmd := 0.0;
        END_IF;

    ELSE
        // Economizer inactive: Dampers at minimum position, use mechanical cooling exclusively
        rHw_OaDamperCmd := rMinDamperPos;
        rHw_EaDamperCmd := rMinDamperPos;
        rHw_MaDamperCmd := 100.0 - rMinDamperPos;

        rHw_ChwValveCmd := rCoolingDemand;
    END_IF;

ELSE
    // Reset PIDs and states when not running
    fbChwPID(ENABLE := FALSE);
    bEconomizerActive := FALSE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_AutoPaintShopControl
TITLE = 'Automotive Paint Shop Control Block'
AUTHOR : 'Lumina Elite Architect'
VERSION : '1.0'

(* 
   =============================================================================
   Block Name: FB_AutoPaintShopControl
   Description:
   Highly complex state machine for an automotive paint shop control system.
   Manages paint color changeover sequences, solvent flush timers, robotic 
   spray arm interlocking, and rigorous safety monitoring (E-Stops, thermal overloads).
   =============================================================================
*)

VAR_INPUT
    xEnable               : BOOL;   (* System Enable *)
    xAutoMode             : BOOL;   (* TRUE = Auto Mode, FALSE = Manual Mode *)
    xEStop_OK             : BOOL;   (* Emergency Stop (TRUE = OK, FALSE = Tripped) *)
    xThermalOverload_OK   : BOOL;   (* Thermal Overload for Pumps/Motors (TRUE = OK) *)
    xSafetyDoors_Closed   : BOOL;   (* Cell Safety Doors Closed *)

    iReqColorCode         : INT;    (* Requested Paint Color Code (1..10) *)
    xStartChangeover      : BOOL;   (* Trigger for Color Changeover *)

    xRobotHomePos         : BOOL;   (* Robot is in Home/Safe Position *)
    xRobotFault           : BOOL;   (* Robot Fault Status *)
    xAirPressure_OK       : BOOL;   (* Atomizing Air Pressure OK *)

    xAckFault             : BOOL;   (* Fault Acknowledge / Reset *)
END_VAR

VAR_OUTPUT
    xSystemReady          : BOOL;   (* System is Ready for Production *)
    xRobotInterlock       : BOOL;   (* Interlock release to Robot (TRUE = Allowed to Spray) *)

    xPumpPaintCmd         : BOOL;   (* Command to Run Paint Supply Pump *)
    xPumpSolventCmd       : BOOL;   (* Command to Run Solvent Flush Pump *)
    xValvePaintOpen       : BOOL;   (* Paint Supply Valve Open *)
    xValveSolventOpen     : BOOL;   (* Solvent Supply Valve Open *)
    xValveDumpOpen        : BOOL;   (* Waste/Dump Valve Open (for flushing) *)
    xValveAirPurge        : BOOL;   (* Air Purge Valve Open *)

    iCurrentColorCode     : INT;    (* Currently Loaded Paint Color Code *)
    eState                : INT;    (* Active State Machine Step *)

    xFaultActive          : BOOL;   (* Master Fault Active *)
    iFaultID              : INT;    (* Fault Code *)
END_VAR

VAR
    (* State Machine Constants *)
    STATE_INIT           : INT := 0;
    STATE_IDLE           : INT := 10;
    STATE_PAINTING       : INT := 20;
    STATE_FLUSH_START    : INT := 30;
    STATE_SOLVENT_WASH   : INT := 40;
    STATE_AIR_PURGE      : INT := 50;
    STATE_LINE_FILL      : INT := 60;
    STATE_FAULT          : INT := 99;

    (* Internal Variables *)
    iTargetColor         : INT;

    (* Timers *)
    fbSolventWashTimer   : TON;
    fbAirPurgeTimer      : TON;
    fbLineFillTimer      : TON;

    (* Safety & Hardware Abstraction *)
    xSafetyOK            : BOOL;

    (* Edge Detections *)
    rtStartChangeover    : R_TRIG;
END_VAR

BEGIN
    (* ========================================================================= *)
    (* 1. SAFETY & INTERLOCK MONITORING *)
    (* ========================================================================= *)
    xSafetyOK := xEStop_OK AND xThermalOverload_OK AND xSafetyDoors_Closed AND xAirPressure_OK;

    IF NOT xSafetyOK OR xRobotFault THEN
        eState := STATE_FAULT;
        IF NOT xEStop_OK THEN
            iFaultID := 101; (* E-Stop Tripped *)
        ELSIF NOT xThermalOverload_OK THEN
            iFaultID := 102; (* Thermal Overload *)
        ELSIF NOT xSafetyDoors_Closed THEN
            iFaultID := 103; (* Safety Door Opened *)
        ELSIF NOT xAirPressure_OK THEN
            iFaultID := 104; (* Loss of Air Pressure *)
        ELSIF xRobotFault THEN
            iFaultID := 105; (* Robot Fault *)
        END_IF;
    END_IF;

    (* Fault Reset Logic *)
    IF (eState = STATE_FAULT) AND xAckFault AND xSafetyOK AND NOT xRobotFault THEN
        eState := STATE_INIT;
        iFaultID := 0;
        xFaultActive := FALSE;
    END_IF;

    xFaultActive := (eState = STATE_FAULT);

    (* Trigger Processing *)
    rtStartChangeover(CLK := xStartChangeover);

    (* ========================================================================= *)
    (* 2. MAIN STATE MACHINE *)
    (* ========================================================================= *)
    CASE eState OF

        STATE_INIT:
            xSystemReady := FALSE;
            xRobotInterlock := FALSE;
            xPumpPaintCmd := FALSE;
            xPumpSolventCmd := FALSE;
            xValvePaintOpen := FALSE;
            xValveSolventOpen := FALSE;
            xValveDumpOpen := FALSE;
            xValveAirPurge := FALSE;

            IF xEnable AND xSafetyOK THEN
                eState := STATE_IDLE;
            END_IF;

        STATE_IDLE:
            xSystemReady := TRUE;
            xRobotInterlock := FALSE;
            xPumpPaintCmd := FALSE;
            xPumpSolventCmd := FALSE;
            xValvePaintOpen := FALSE;
            xValveSolventOpen := FALSE;
            xValveDumpOpen := FALSE;
            xValveAirPurge := FALSE;

            IF rtStartChangeover.Q AND xAutoMode AND xRobotHomePos THEN
                iTargetColor := iReqColorCode;
                eState := STATE_FLUSH_START;
                xSystemReady := FALSE;
            ELSIF xAutoMode AND (iCurrentColorCode > 0) AND NOT xRobotHomePos THEN
                (* Assuming robot left home to paint *)
                eState := STATE_PAINTING;
            END_IF;

        STATE_PAINTING:
            xRobotInterlock := TRUE; (* Allow robot to actuate trigger *)
            xPumpPaintCmd := TRUE;
            xValvePaintOpen := TRUE;

            IF xRobotHomePos OR NOT xAutoMode THEN
                eState := STATE_IDLE;
            END_IF;

        STATE_FLUSH_START:
            (* Prepare for solvent wash: Close paint, open dump *)
            xValvePaintOpen := FALSE;
            xPumpPaintCmd := FALSE;
            xValveDumpOpen := TRUE;
            eState := STATE_SOLVENT_WASH;

        STATE_SOLVENT_WASH:
            xValveSolventOpen := TRUE;
            xPumpSolventCmd := TRUE;

            IF fbSolventWashTimer.Q THEN
                xValveSolventOpen := FALSE;
                xPumpSolventCmd := FALSE;
                eState := STATE_AIR_PURGE;
            END_IF;

        STATE_AIR_PURGE:
            xValveAirPurge := TRUE;

            IF fbAirPurgeTimer.Q THEN
                xValveAirPurge := FALSE;
                xValveDumpOpen := FALSE;
                eState := STATE_LINE_FILL;
            END_IF;

        STATE_LINE_FILL:
            (* Open new color paint valve to push out air and fill line *)
            xValvePaintOpen := TRUE;
            xPumpPaintCmd := TRUE;
            xValveDumpOpen := TRUE; (* Dump initial mix of air/paint *)

            IF fbLineFillTimer.Q THEN
                xValveDumpOpen := FALSE;
                iCurrentColorCode := iTargetColor;
                eState := STATE_IDLE;
            END_IF;

        STATE_FAULT:
            (* Safe State Override *)
            xSystemReady := FALSE;
            xRobotInterlock := FALSE;
            xPumpPaintCmd := FALSE;
            xPumpSolventCmd := FALSE;
            xValvePaintOpen := FALSE;
            xValveSolventOpen := FALSE;
            xValveDumpOpen := FALSE;
            xValveAirPurge := FALSE;

    END_CASE;

    (* ========================================================================= *)
    (* 3. TIMER UPDATES *)
    (* ========================================================================= *)
    fbSolventWashTimer(IN := (eState = STATE_SOLVENT_WASH), PT := T#15S);
    fbAirPurgeTimer(IN := (eState = STATE_AIR_PURGE), PT := T#10S);
    fbLineFillTimer(IN := (eState = STATE_LINE_FILL), PT := T#5S);

END_FUNCTION_BLOCK

