    LTR : REAL; (* Lateral Top Right *)
END_STRUCT;
END_TYPE

FUNCTION_BLOCK FB_ThrusterVectoring
VAR_INPUT
    Cmd : THRUSTER_COMMANDS;
    MaxRPM : REAL := 3000.0;
END_VAR
VAR_OUTPUT
    Out : THRUSTER_OUTPUTS;
END_VAR
VAR
    (* Transformation Matrix Coefficients based on ROV Thruster Geometry *)
    Coef_Surge_HL : REAL := 1.0;
    Coef_Surge_HR : REAL := 1.0;
    Coef_Sway_LTL : REAL := 1.0;
    Coef_Sway_LTR : REAL := 1.0;
    Coef_Heave_VL : REAL := 1.0;
    Coef_Heave_VR : REAL := 1.0;
END_VAR
(* Calculate Matrix allocations for each thruster using linear superposition *)
Out.HL := (Cmd.Surge * Coef_Surge_HL) + (Cmd.Yaw * 0.5);
Out.HR := (Cmd.Surge * Coef_Surge_HR) - (Cmd.Yaw * 0.5);
Out.VL := (Cmd.Heave * Coef_Heave_VL) + (Cmd.Roll * 0.5) - (Cmd.Pitch * 0.5);
Out.VR := (Cmd.Heave * Coef_Heave_VR) - (Cmd.Roll * 0.5) - (Cmd.Pitch * 0.5);
Out.LTL := (Cmd.Sway * Coef_Sway_LTL) + (Cmd.Yaw * 0.25);
Out.LTR := (Cmd.Sway * Coef_Sway_LTR) - (Cmd.Yaw * 0.25);

(* Saturate outputs to MaxRPM *)
Out.HL := LIMIT(-MaxRPM, Out.HL, MaxRPM);
Out.HR := LIMIT(-MaxRPM, Out.HR, MaxRPM);
Out.VL := LIMIT(-MaxRPM, Out.VL, MaxRPM);
Out.VR := LIMIT(-MaxRPM, Out.VR, MaxRPM);
Out.LTL := LIMIT(-MaxRPM, Out.LTL, MaxRPM);
Out.LTR := LIMIT(-MaxRPM, Out.LTR, MaxRPM);
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_TelemetryHeartbeat
VAR_INPUT
    RxHeartbeat : BOOL;
    TimeoutMS : TIME := T#500ms;
END_VAR
VAR_OUTPUT
    LinkActive : BOOL;
    FaultComm : BOOL;
END_VAR
VAR
    Timer : TON;
    PrevHeartbeat : BOOL;
END_VAR
Timer(IN := (RxHeartbeat = PrevHeartbeat), PT := TimeoutMS);
PrevHeartbeat := RxHeartbeat;

IF Timer.Q THEN
    LinkActive := FALSE;
    FaultComm := TRUE;
ELSE
    LinkActive := TRUE;
    FaultComm := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Compensator
VAR_INPUT
    Depth_Meters : REAL;
    HydraulicSysPress_Bar : REAL;
END_VAR
VAR_OUTPUT
    TargetCompPress_Bar : REAL;
    CompensatorFault : BOOL;
    PumpDriveSignal : REAL;
END_VAR
VAR
    AmbientPress_Bar : REAL;
    Overhead_Bar : REAL := 1.0; (* 1 Bar overhead above ambient to prevent water ingress *)
    Error : REAL;
    Kp : REAL := 2.5;
END_VAR
(* 10 meters of seawater is approximately 1 Bar *)
AmbientPress_Bar := (Depth_Meters / 10.0) + 1.0; (* +1 for atmospheric at surface *)
TargetCompPress_Bar := AmbientPress_Bar + Overhead_Bar;

Error := TargetCompPress_Bar - HydraulicSysPress_Bar;
PumpDriveSignal := Error * Kp;
PumpDriveSignal := LIMIT(0.0, PumpDriveSignal, 100.0);

(* Fault detection if pressure drops below ambient - critical failure risk (water ingress) *)
IF HydraulicSysPress_Bar < AmbientPress_Bar THEN
    CompensatorFault := TRUE;
ELSE
    CompensatorFault := FALSE;
END_IF;
END_FUNCTION_BLOCK

PROGRAM MAIN_ROV_SCM
VAR
    (* State Machine *)
    CurrentState : ROV_STATE := ST_INIT;

    (* I/O and Hardware Abstraction *)
    DepthSensor_M : REAL; (* Mapped to Analog Input *)
    HydraulicPressure_Bar : REAL; (* Mapped to Analog Input *)
    FiberOpticHeartbeat_Rx : BOOL; (* Mapped to Digital Input *)
    E_Stop_Surface : BOOL;
    E_Stop_Subsea : BOOL;
    MotorTempHigh : BOOL;

    (* Control Instances *)
    ThrusterCtrl : FB_ThrusterVectoring;
    PilotCmd : THRUSTER_COMMANDS;
    ThrusterOut : THRUSTER_OUTPUTS;

    TelemetryCtrl : FB_TelemetryHeartbeat;
    LinkActive : BOOL;
    TelemetryFault : BOOL;

    CompensatorCtrl : FB_Compensator;
    CompensatorFault : BOOL;
    HydraulicPumpCmd : REAL;

    (* Safety Interlocks *)
    CriticalFault : BOOL;
    SystemSafe : BOOL;
END_VAR

(* 1. Hardware abstraction & Data Acquisition would occur here (scaling AI/DI to engineering units) *)

(* 2. Umbilical Fiber-Optic Telemetry Heartbeat *)
TelemetryCtrl(RxHeartbeat := FiberOpticHeartbeat_Rx, TimeoutMS := T#1000ms);
LinkActive := TelemetryCtrl.LinkActive;
TelemetryFault := TelemetryCtrl.FaultComm;

(* 3. Hydraulic Pressure Compensation (6000m rated) *)
CompensatorCtrl(
    Depth_Meters := DepthSensor_M, 
    HydraulicSysPress_Bar := HydraulicPressure_Bar
);
HydraulicPumpCmd := CompensatorCtrl.PumpDriveSignal;
CompensatorFault := CompensatorCtrl.CompensatorFault;

(* 4. Safety Interlocks Evaluation *)
CriticalFault := TelemetryFault OR CompensatorFault OR E_Stop_Surface OR E_Stop_Subsea OR MotorTempHigh;
SystemSafe := NOT CriticalFault;

(* 5. SCM State Machine *)
CASE CurrentState OF
    ST_INIT:
        (* Initialize variables, check sensor presence *)
        IF SystemSafe THEN
            CurrentState := ST_SYSTEM_CHECK;
        END_IF;

    ST_SYSTEM_CHECK:
        (* Perform self-test routines, verify actuator responses *)
        IF CriticalFault THEN
            CurrentState := ST_SAFE_STATE_FAULT;
        ELSIF SystemSafe AND LinkActive THEN
            CurrentState := ST_STANDBY;
        END_IF;

    ST_STANDBY:
        IF CriticalFault THEN
            CurrentState := ST_SAFE_STATE_FAULT;
        ELSIF DepthSensor_M > 10.0 THEN
            CurrentState := ST_DESCENT;
        END_IF;

    ST_DESCENT:
        IF CriticalFault THEN
            CurrentState := ST_EMERGENCY_RECOVERY;
        ELSIF DepthSensor_M > 5900.0 THEN
            CurrentState := ST_SUBSEA_OPS;
        END_IF;

    ST_SUBSEA_OPS:
        (* Main operating mode at 6000m *)
        IF CriticalFault THEN
            CurrentState := ST_EMERGENCY_RECOVERY;
        ELSIF DepthSensor_M < 100.0 THEN
            CurrentState := ST_ASCENT;
        END_IF;

    ST_ASCENT:
        IF SystemSafe AND DepthSensor_M <= 10.0 THEN
            CurrentState := ST_STANDBY;
        END_IF;

    ST_EMERGENCY_RECOVERY:
        (* Drop weights, surface immediately, override non-critical locks *)
        ThrusterOut.VL := 3000.0; (* Full heave up *)
        ThrusterOut.VR := 3000.0;
        IF DepthSensor_M <= 10.0 THEN
            CurrentState := ST_SAFE_STATE_FAULT;
        END_IF;

    ST_SAFE_STATE_FAULT:
        (* Secure all outputs, isolate hydraulics, wait for intervention *)
        ThrusterOut.HL := 0.0;
        ThrusterOut.HR := 0.0;
        ThrusterOut.VL := 0.0;
        ThrusterOut.VR := 0.0;
        ThrusterOut.LTL := 0.0;
        ThrusterOut.LTR := 0.0;
        HydraulicPumpCmd := 0.0;

        IF SystemSafe THEN (* Requires manual reset of faults *)
            CurrentState := ST_INIT;
        END_IF;
END_CASE;

(* 6. Thruster Vectoring Matrix (Only in active subsea modes) *)
IF CurrentState = ST_SUBSEA_OPS OR CurrentState = ST_DESCENT OR CurrentState = ST_STANDBY THEN
    ThrusterCtrl(Cmd := PilotCmd, MaxRPM := 3000.0);
    ThrusterOut := ThrusterCtrl.Out;
ELSIF CurrentState = ST_SAFE_STATE_FAULT THEN
    (* Handled in state machine *)
END_IF;

(* 7. Output mapping back to hardware occurs here *)
END_PROGRAM
`

Here is a production-ready IEC 61131-3 Structured Text implementation of a Geothermal Power Plant Steam Turbine Sequencer. 

This highly robust function block incorporates a complex state machine for the turbine lifecycle, safety interlocks including overspeed and thermal overload, H2S abatement scrubber control, and reinjection well pump synchronization.

```iecst
(* 
    =============================================================================
    FUNCTION BLOCK: FB_GeothermalTurbineSequencer
    DESCRIPTION:    Advanced Geothermal Power Plant Steam Turbine Sequencer.
                    Manages startup, H2S abatement, grid synchronization, 
                    reinjection pumping, and critical safety interlocks.
    AUTHOR:         Lumina Elite Systems
    VERSION:        2.0.1
    =============================================================================
*)
FUNCTION_BLOCK FB_GeothermalTurbineSequencer
VAR_INPUT
    // Operator Commands
    xCmdStart             : BOOL;   // Operator command to initiate startup sequence
    xCmdStop              : BOOL;   // Operator command to initiate normal shutdown
    xCmdEStop             : BOOL;   // Emergency Stop (TRUE = Active/Trip)
    xResetFaults          : BOOL;   // Reset latched faults

    // Hardware Feedback & Sensors
    rTurbineSpeedRPM      : REAL;   // Current turbine speed in RPM
    rTurbineVibration     : REAL;   // Turbine vibration in mm/s
    rBearingTemp          : REAL;   // Main bearing temperature in °C
    rH2S_Concentration    : REAL;   // H2S gas concentration in ppm

    // Subsystem Status
    xScrubberReady        : BOOL;   // H2S scrubber system healthy and ready
    xReinjectionPumpReady : BOOL;   // Reinjection pump VFD ready
    xGridSyncOK           : BOOL;   // Generator is synchronized to the grid
END_VAR

VAR_OUTPUT
    // Actuators & Commands
    xMainSteamValve       : BOOL;   // Open main steam inlet valve
    xH2S_ScrubberPump     : BOOL;   // Command to run H2S abatement pump
    xReinjectionPumpCmd   : BOOL;   // Command to start reinjection pump
    xTripBreaker          : BOOL;   // Command to trip generator breaker

    // Status & Diagnostics
    iCurrentState         : INT;    // Active sequence state
    xFaultActive          : BOOL;   // General fault indicator
    sStatusMessage        : STRING[80]; // Human-readable status message
END_VAR

VAR
    // Trip Thresholds (Configurable)
    c_OverspeedLimit      : REAL := 3960.0; // 10% overspeed on 3600 RPM base
    c_VibrationLimit      : REAL := 8.5;    // Max allowable vibration (mm/s)
    c_BearingTempLimit    : REAL := 95.0;   // Max bearing temperature (°C)
    c_H2S_WarningLimit    : REAL := 50.0;   // H2S limit requiring max scrubbing

    // Sequence States
    STATE_STANDBY         : INT := 0;
    STATE_PRE_START       : INT := 10;
    STATE_TURBINE_ROLL    : INT := 20;
    STATE_SYNC            : INT := 30;
    STATE_RUNNING         : INT := 40;
    STATE_NORMAL_STOP     : INT := 50;
    STATE_TRIP            : INT := 99;

    // Timers
    fbScrubberWarmupTimer : TON;
    fbValveRampTimer      : TON;
    fbPumpSyncTimer       : TON;

    // Internal Fault Latches
    xOverspeedTrip        : BOOL;
    xVibTrip              : BOOL;
    xTempTrip             : BOOL;
    xEStopTrip            : BOOL;
END_VAR

BEGIN
    // =========================================================================
    // 1. SAFETY & CRITICAL INTERLOCKS (EVALUATED FIRST)
    // =========================================================================

    // E-Stop Evaluation
    IF xCmdEStop THEN
        xEStopTrip := TRUE;
    END_IF;

    // Overspeed Trip Logic
    IF rTurbineSpeedRPM > c_OverspeedLimit THEN
        xOverspeedTrip := TRUE;
    END_IF;

    // Thermal Overload / Bearing Temp Trip
    IF rBearingTemp > c_BearingTempLimit THEN
        xTempTrip := TRUE;
    END_IF;

    // High Vibration Trip
    IF rTurbineVibration > c_VibrationLimit THEN
        xVibTrip := TRUE;
    END_IF;

    // Fault Aggregation
    xFaultActive := xEStopTrip OR xOverspeedTrip OR xTempTrip OR xVibTrip;

    // Fault Reset Logic (Only if conditions cleared)
    IF xResetFaults AND NOT xCmdEStop THEN
        IF rTurbineSpeedRPM < (c_OverspeedLimit * 0.9) THEN xOverspeedTrip := FALSE; END_IF;
        IF rBearingTemp < (c_BearingTempLimit - 5.0) THEN xTempTrip := FALSE; END_IF;
        IF rTurbineVibration < (c_VibrationLimit - 1.0) THEN xVibTrip := FALSE; END_IF;
        xEStopTrip := FALSE;
    END_IF;

    // Immediate Trip Execution
    IF xFaultActive THEN
        iCurrentState := STATE_TRIP;
    END_IF;


    // =========================================================================
    // 2. MAIN STATE MACHINE
    // =========================================================================
    CASE iCurrentState OF

        // ---------------------------------------------------------------------
        STATE_STANDBY: 
            sStatusMessage := 'Standby: Ready to Start';
            xMainSteamValve := FALSE;
            xH2S_ScrubberPump := FALSE;
            xReinjectionPumpCmd := FALSE;
            xTripBreaker := FALSE;

            // State Transition
            IF xCmdStart AND NOT xFaultActive THEN
                iCurrentState := STATE_PRE_START;
            END_IF;

        // ---------------------------------------------------------------------
        STATE_PRE_START:
            sStatusMessage := 'Pre-Start: Initiating H2S Scrubber';
            xH2S_ScrubberPump := TRUE; // Start abatement before turbine roll

            // Wait for scrubber to be ready (simulated warmup timer)
            fbScrubberWarmupTimer(IN := xScrubberReady, PT := T#5s);

            IF fbScrubberWarmupTimer.Q AND NOT xCmdStop THEN
                iCurrentState := STATE_TURBINE_ROLL;
            ELSIF xCmdStop THEN
                iCurrentState := STATE_NORMAL_STOP;
            END_IF;

        // ---------------------------------------------------------------------
        STATE_TURBINE_ROLL:
            sStatusMessage := 'Turbine Roll: Admitting Steam';
            xMainSteamValve := TRUE; // Open steam valve to accelerate

            // Transition when approaching synchronous speed
            IF rTurbineSpeedRPM >= 3550.0 THEN
                iCurrentState := STATE_SYNC;
            END_IF;

        // ---------------------------------------------------------------------
        STATE_SYNC:
            sStatusMessage := 'Syncing: Waiting for Grid Synchronization';

            // Wait for AVR and synchronizer to match phase and close breaker
            IF xGridSyncOK THEN
                iCurrentState := STATE_RUNNING;
            END_IF;

        // ---------------------------------------------------------------------
        STATE_RUNNING:
            sStatusMessage := 'Running: Starting Reinjection Pumps';

            // Once synchronized, start reinjection of geothermal fluid
            fbPumpSyncTimer(IN := xReinjectionPumpReady AND xGridSyncOK, PT := T#3s);
            IF fbPumpSyncTimer.Q THEN
                xReinjectionPumpCmd := TRUE;
            END_IF;

            // Dynamic H2S Scrubber Control during run
            // Continuous operation in geothermal plants, boost if concentration rises
            xH2S_ScrubberPump := TRUE; 

            // Normal Shutdown request
            IF xCmdStop THEN
                iCurrentState := STATE_NORMAL_STOP;
            END_IF;

        // ---------------------------------------------------------------------
        STATE_NORMAL_STOP:
            sStatusMessage := 'Normal Stop: Unloading and Coasting Down';
            xMainSteamValve := FALSE; // Cut steam
            xTripBreaker := TRUE;     // Disconnect from grid

            // Stop reinjection when turbine drops below threshold
            IF rTurbineSpeedRPM < 1000.0 THEN
                xReinjectionPumpCmd := FALSE;
            END_IF;

            // Keep scrubber running until speed is 0 to manage tail gas
            IF rTurbineSpeedRPM < 10.0 THEN
                xH2S_ScrubberPump := FALSE;
                xTripBreaker := FALSE; // Reset trip command for next start
                iCurrentState := STATE_STANDBY;
            END_IF;

        // ---------------------------------------------------------------------
        STATE_TRIP:
            sStatusMessage := 'TRIP: Critical Safety Shutdown';
            xMainSteamValve := FALSE;
            xTripBreaker := TRUE;
            xReinjectionPumpCmd := FALSE;
            // Note: Scrubber kept ON during trip to handle vented gas!
            xH2S_ScrubberPump := TRUE; 

            IF NOT xFaultActive THEN
                // Faults have been cleared by operator
                xTripBreaker := FALSE;
                iCurrentState := STATE_STANDBY;
            END_IF;

        // ---------------------------------------------------------------------
        ELSE
            // Fallback for undefined states
            iCurrentState := STATE_TRIP;

    END_CASE;

    // Reset Timers if not in their respective states
    IF iCurrentState <> STATE_PRE_START THEN
        fbScrubberWarmupTimer(IN := FALSE, PT := T#5s);
    END_IF;

    IF iCurrentState <> STATE_RUNNING THEN
        fbPumpSyncTimer(IN := FALSE, PT := T#3s);
    END_IF;

END_FUNCTION_BLOCK
